-- NOT behaviorally diff-verified (these write data; verify with curated inputs before trusting).
USE EXCHANGESYS2026;
SET NAMES utf8mb4;
SET collation_connection='utf8mb4_unicode_ci';
SET SESSION sql_mode='IGNORE_SPACE,NO_ENGINE_SUBSTITUTION';   -- allows 'func (x)' spacing in legacy T-SQL

DROP PROCEDURE IF EXISTS `Accounts_GetLimitationVal`;
DELIMITER //
CREATE PROCEDURE `Accounts_GetLimitationVal`(IN `p_AccountType` INT, IN `p_AccID` BIGINT)
BEGIN
DECLARE v_AccBalnce DECIMAL(18, 3);
DECLARE v_sumcredet DECIMAL(18, 3);
DECLARE v_BID INT;
DECLARE v_SafesBalnce DECIMAL(18, 3);
START TRANSACTION;


SELECT at.BranchID INTO v_BID FROM AccountsTb at WHERE at.AccID=p_AccID;

	SELECT IFNULL( SUM( A.Debit ), 0 )- IFNULL( SUM( A.Credit ), 0 ) INTO v_sumcredet FROM ExSyAccounts_AccSafeActivityTb AS A
join AccountsTb as b on a.AccIDFrom=b.AccID
WHERE A.IsActive=1
	  AND A.AccBranchID=v_BID
	  AND  b.AccParent = 1010101;


                  SELECT IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(A.Credit), 0) INTO v_SafesBalnce FROM
                          ExSyAccounts_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                  WHERE
                          A.IsActive = 1
                          AND A.AccBranchID = v_BID
                          AND LEFT(b.AccParent, 5) = 10104
                          AND a.DailyClosed = 0
                  GROUP BY
                          b.AccParent
 ORDER BY b.AccParent DESC LIMIT 1;

  SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0) INTO v_AccBalnce FROM
          ExSyAccounts_AccSafeActivityTb a
  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1;

  IF p_AccountType = 0
     THEN
      SELECT
              b.AccID,
              a.BName AS EMCUST,
              CASE                       WHEN a.IsLimited = 1                         THEN                         a.LimitedVal + v_AccBalnce                       ELSE                       0.000               END     AS LimitedVal,
              a.IsLimited
      FROM
              CoBranch AS a
          LEFT JOIN
            AccountsTb AS b
              ON a.CurrentAccID = b.AccID
      WHERE
              a.BranchType = 3
              AND a.CurrentAccID = p_AccID
      ORDER BY
              a.BName;
    END IF;

  IF p_AccountType = 1
     THEN
      SELECT
              b.AccID,
              a.CustName AS EMCUST,
              CASE                       WHEN a.IsLimited = 1                         THEN                         a.LimitedVal + v_AccBalnce                       ELSE                       0.000               END        AS LimitedVal,
              a.IsLimited
      FROM
              CustomersTb AS a
          LEFT JOIN
            AccountsTb AS b
              ON a.AccID = b.AccID
      WHERE
              a.CandDebit = 0
              AND a.AccID = p_AccID
      ORDER BY
              a.CustName;
    END IF;
  IF p_AccountType = 2
     THEN
      SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0) INTO v_AccBalnce FROM
              ExSyAccounts_AccSafeActivityTb a
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1;
      SELECT
              a.AccID,
              a.UName AS EMCUST,
            IFNULL( v_sumcredet+v_SafesBalnce,0) AS AccBalnce,
              CASE                       WHEN a.IsLimited = 1                         THEN                         a.LimitedVal                        ELSE                       0.000               END     AS LimitedVal,
              a.IsLimited
      FROM
              TB_Users AS a
      WHERE
              a.AccID = p_AccID
      ORDER BY
              a.UName;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_CloseingIncomeStatmentLoadDVG`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_CloseingIncomeStatmentLoadDVG`()
BEGIN
START TRANSACTION;
  SELECT
          a.ISID,
          a.ID,
          a.Credit,
          a.Debit,
          c.BName,
          a.MovementType
  FROM
          ExSyAccounts_AccSafeActivityTb a
      LEFT JOIN
        AccountsTb b
          ON a.AccIDFrom = b.AccID
      LEFT JOIN
        CoBranch c
          ON a.AccBranchID = c.ID
  WHERE
          b.AccParent = 2040102
          AND a.DailyClosed = 0
          AND a.IsActive=1;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_ClosingINCOMESTATMENT`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_ClosingINCOMESTATMENT`(IN `p_BranchID` INT, IN `p_SafeID` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, INOUT `p_MsgSatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_NetTotal DECIMAL(18, 3);
DECLARE v_SunDebit DECIMAL(18, 3);
DECLARE v_SumCredit DECIMAL(18, 3);
DECLARE v_AccProfORLoss BIGINT;
DECLARE v_ISID LONGTEXT;
DECLARE v_D1 date;
DECLARE v_D2 date;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_MsgSatues = 0; END;

      START TRANSACTION;



SELECT D1, d2 INTO v_D1, v_D2 FROM ClosingINCOMESTATMENT_TB
WHERE BranchID=p_BranchID

AND ((p_dt1 BETWEEN D1 AND D2 ) OR (p_dt2 BETWEEN D1 AND D2)  );
      IF v_D1 IS NOT NULL AND v_D2 IS NOT NULL
         THEN
          SET p_MsgSatues = 0;
          SET p_MsgBox = CONCAT('عذرا هناك إقفال سابق خلال الفترة من', CHAR(13), CAST(v_D1 AS CHAR), CHAR(13), 'إلى', CHAR(13), CAST(v_D2 AS CHAR), CHAR(13), 'الرجاء اختيار تاريخ خارج هذه الفترة');
          ROLLBACK;
          LEAVE proc;
        END IF;





      SELECT at.AccID INTO v_AccProfORLoss FROM
              AccountsTb at
      WHERE
              at.AccParent = 2040102
              AND at.BranchID = p_BranchID;




      SET v_ISID = CONCAT('38', '-', CAST(MONTH(p_dt1) AS CHAR), CAST(MONTH(p_dt2) AS CHAR), '-', CAST(p_BranchID AS CHAR));
      SELECT CASE                                   WHEN (SUM(a.Credit) - SUM(a.Debit)) > 0                                     THEN                                     (SUM(a.Credit) - SUM(a.Debit))                                   ELSE                                   0.000                           END, CASE                                   WHEN (SUM(a.Debit) - SUM(a.Credit)) > 0                                     THEN                                     (SUM(a.Debit) - SUM(a.Credit))                                   ELSE                                   0.000                           END INTO v_SumCredit, v_SunDebit FROM
              ExSyAccounts_AccSafeActivityTb AS a
          LEFT OUTER JOIN
            AccountsTb AS b
              ON a.AccIDFrom = b.AccID
      WHERE
              b.BranchID = p_BranchID
              AND a.InsertDate >= p_dt1
              AND a.InsertDate <= p_dt2
              AND (   a.CurrencyID = 1
                      OR a.CurrencyID = 13)
              AND a.IsActive = 1
              AND b.AccActive = 1
AND a.TypeID<>38
              AND (   ACCCODE LIKE '3%'
                      OR ACCCODE LIKE '4%')
      HAVING
              SUM(a.Credit) - SUM(a.Debit) <> 0;


      IF v_SumCredit > v_SunDebit
         THEN
          SET v_NetTotal = v_SumCredit - v_SunDebit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement
                )
          VALUES
                  (
                    p_SafeID, 0.000, v_NetTotal, NOW(), v_ISID, 1, 38, 68, p_BranchID, v_AccProfORLoss, 0, CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)), 1, CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)), CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR))
                  );
        END IF;


      IF v_SunDebit > v_SumCredit
         THEN
          SET v_NetTotal = v_SunDebit - v_SumCredit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement
                )
          VALUES
                  (
                    p_SafeID, v_NetTotal, 0.000, NOW(), v_ISID, 1, 38, 68, p_BranchID, v_AccProfORLoss, 0, CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)), 1, CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)), CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR))
                  );
        END IF;



      INSERT INTO ExSyAccounts_AccSafeActivityTb
            (
              SafeID,
              Debit,
              Credit,
              InsertDate,
              ISID,
              IsActive,
              TypeID,
              OperationTypeID,
              AccBranchID,
              AccIDFrom,
              AccIDTo,
              MovementType,
              CurrencyID,
              Note,
              SafeIDMovement
            )
          SELECT
                  p_SafeID,
                  CASE                           WHEN (SUM(a.Credit) - SUM(a.Debit)) > 0                             THEN                             (SUM(a.Credit) - SUM(a.Debit))                           ELSE                           0.000                   END,
                  CASE                           WHEN (SUM(a.Debit) - SUM(a.Credit)) > 0                             THEN                             (SUM(a.Debit) - SUM(a.Credit))                           ELSE                           0.000                   END,
                  NOW(),
                  v_ISID,
                  1,
                  38,
                  68,
                  p_BranchID,
                  a.AccIDFrom,
                  v_AccProfORLoss,
                  CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)),
                  1,
                  CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR)),
                  CONCAT('إقفال قائمة الدخل خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR))
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                AccountsTb AS b
                  ON a.AccIDFrom = b.AccID
          WHERE
                  b.BranchID = p_BranchID
                  AND a.InsertDate >= p_dt1
                  AND a.InsertDate <= p_dt2
                  AND (   a.CurrencyID = 1
                          OR a.CurrencyID = 13)
                  AND a.IsActive = 1
                  AND b.AccActive = 1
AND a.TypeID<>38
                  AND (   ACCCODE LIKE '3%'
                          OR ACCCODE LIKE '4%')
          GROUP BY
                  b.AccCode,
                  a.AccIDFrom
          HAVING
                  SUM(a.Credit) - SUM(a.Debit) <> 0;



      INSERT INTO ClosingINCOMESTATMENT_TB
            (
              Code,
              BranchID,
              SafeId,
              D1,
              D2,
              ClosingDate,
              IsActive
            )
      VALUES
              (
                v_ISID, p_BranchID, p_SafeID, p_dt1, p_dt2, NOW(), 1
              );

      COMMIT;
      SET p_MsgSatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_FRMINCOMESTATMENT`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_FRMINCOMESTATMENT`(IN `p_bracnID` INT, IN `p_accacount` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, INOUT `p_SUMcredet` DECIMAL(18,0), INOUT `p_SUMdebit` DECIMAL(18,0), INOUT `p_ToralPrase` DECIMAL(18,0))
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

START TRANSACTION;

IF p_bracnID<>0
 THEN
if p_accacount= 4
 THEN

SELECT
			b.AccCode							AS accode,
				b.AccName as accname,
			sum(a.Credit)-sum(a.Debit) AS tolal
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			b.BranchID = p_bracnID
			AND a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2
			and a.IsActive=1
      AND b.AccActive=1
			AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
          AND a.TypeID<>38
			and  ACCCODE like CONCAT(CAST(p_accacount AS CHAR), '%')
			group BY b.AccCode, b.AccName
			Having sum(a.Credit)-sum(a.Debit)<>0;
			END IF;


if p_accacount= 3
 THEN
SELECT
			b.AccCode							AS accode2,
				b.AccName as accname2,
			sum(a.Debit)-sum(a.Credit) AS tolal2
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID

	WHERE
			b.BranchID = p_bracnID
			AND a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2
			and a.IsActive=1
      AND b.AccActive=1
			AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
          AND a.TypeID<>38
			and  ACCCODE like CONCAT(CAST(p_accacount AS CHAR), '%')
			group BY b.AccCode, b.AccName,b.AccID
			Having sum(a.Debit)-sum(a.Credit)<>0;
			END IF;

END IF;

IF p_bracnID=0
 THEN
if p_accacount= 4
 THEN

SELECT
			b.AccCode							AS accode,
				b.AccName as accname,
			sum(a.Credit)-sum(a.Debit) AS tolal
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	WHERE

			 a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2
			and a.IsActive=1
      AND b.AccActive=1
			AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
          AND a.TypeID<>38
			and  ACCCODE like CONCAT(CAST(p_accacount AS CHAR), '%')
			group BY b.AccCode, b.AccName
			Having sum(a.Credit)-sum(a.Debit)<>0;
			END IF;


if p_accacount= 3
 THEN
SELECT
			b.AccCode							AS accode2,
				b.AccName as accname2,
			sum(a.Debit)-sum(a.Credit) AS tolal2
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID

	WHERE

			 a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2
			and a.IsActive=1
      AND b.AccActive=1
			AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
          AND a.TypeID<>38
			and  ACCCODE like CONCAT(CAST(p_accacount AS CHAR), '%')
			group BY b.AccCode, b.AccName,b.AccID
			Having sum(a.Debit)-sum(a.Credit)<>0;
			END IF;

END IF;
 SELECT IFNULL(sum(a.Credit),0 ) INTO p_SUMcredet FROM ExSyAccounts_AccSafeActivityTb as a inner join ACCOUNTSTB as b on a.AccIDFrom = B.ACCID WHERE b.AccActive  = 1 and a.IsActive=1 AND a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2  and B.Accline = 4 and b.BranchID = p_bracnID 	AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
			AND (   lefT( b.AccParent, 5) = 40101 or lefT( b.AccParent, 7) =4010201 or lefT( b.AccParent, 7) =4010201
			or lefT( b.AccParent, 7) =4010202) and  ACCCODE like '4%';
 SELECT IFNULL(sum(a.Debit),0 ) INTO p_SUMdebit FROM ExSyAccounts_AccSafeActivityTb as a inner join ACCOUNTSTB as b on a.AccIDFrom = B.ACCID WHERE b.AccActive  = 1 and a.IsActive=1 AND a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2 	AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13) and B.Accline = 4 and b.BranchID = p_bracnID 	AND (   lefT( b.AccParent, 5) = 30101 or lefT( b.AccParent, 5) =30102) and b.Accline=4 and  ACCCODE like '3%';
SET p_ToralPrase =  p_SUMcredet -  p_SUMdebit;
commit;



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_FRMINCOMESTATMENT1`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_FRMINCOMESTATMENT1`(IN `p_bracnID` INT, IN `p_accacount` INT, IN `p_accacount2` INT, IN `p_dt1` DATE, IN `p_dt2` DATE)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;
    START TRANSACTION;
    SELECT
            CASE                     WHEN p_accacount = 4                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 40101                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010202)                       AND AccCode LIKE CONCAT(CAST(p_accacount AS CHAR), '%')                       THEN                       b.AccCode             END AS accode,
            case                     WHEN p_accacount = 4                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 40101                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010202)                       AND AccCode LIKE CONCAT(CAST(p_accacount AS CHAR), '%')                       THEN                       b.AccName             END AS accname,
            CASE                     WHEN p_accacount = 4                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 40101                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010201                         OR LEFT(b.AccParent, 7) = 4010202)                       AND AccCode LIKE CONCAT(CAST(p_accacount AS CHAR), '%')                       THEN                       SUM(a.Credit)             END AS tolal,
            CASE                     WHEN p_accacount2 = 3                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 30101                         OR LEFT(b.AccParent, 5) = 30102)                       AND b.Accline = 4                       AND AccCode LIKE CONCAT(CAST(p_accacount2 AS CHAR), '%')                       THEN                       b.AccCode             END AS accode2,
            CASE                     WHEN p_accacount2 = 3                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 30101                         OR LEFT(b.AccParent, 5) = 30102)                       AND b.Accline = 4                       AND AccCode LIKE CONCAT(CAST(p_accacount2 AS CHAR), '%')                       THEN                       b.AccName             END AS accname2,
            CASE                     WHEN p_accacount2 = 3                       AND b.BranchID = p_bracnID                       AND a.InsertDate >= p_dt1                       AND a.InsertDate <= p_dt2                       AND (a.CurrencyID = 1                         OR a.CurrencyID = 13)                       AND (LEFT(b.AccParent, 5) = 30101                         OR LEFT(b.AccParent, 5) = 30102)                       AND b.Accline = 4                       AND AccCode LIKE CONCAT(CAST(p_accacount2 AS CHAR), '%')                       THEN                       SUM(a.Debit)             END AS tolal2

    FROM
            ExSyAccounts_AccSafeActivityTb AS a
        INNER JOIN
          AccountsTb AS b
            ON a.AccIDFrom = b.AccID
    WHERE
            b.BranchID = p_bracnID
            AND a.InsertDate >= p_dt1
            AND a.InsertDate <= p_dt2
            AND (   a.CurrencyID = 1
                    OR a.CurrencyID = 13)
            AND (   LEFT(b.AccParent, 5) = 40101
                    OR LEFT(b.AccParent, 7) = 4010201
                    OR LEFT(b.AccParent, 7) = 4010201
                    OR LEFT(b.AccParent, 7) = 4010202


                    OR LEFT(b.AccParent, 5) = 30101
                    OR LEFT(b.AccParent, 5) = 30102)
            AND (   AccCode LIKE CONCAT(CAST(p_accacount AS CHAR), '%')
                    OR AccCode LIKE CONCAT(CAST(p_accacount2 AS CHAR), '%'))

    GROUP BY
            b.AccCode,
            b.AccName,
            b.AccID,
            b.AccParent,
            a.CurrencyID,
            b.BranchID,
            a.InsertDate,
            b.Accline
             ORDER BY b.AccName;
    COMMIT;


END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_FRMINCOMESTATMENT2`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_FRMINCOMESTATMENT2`(IN `p_bracnID` INT, IN `p_accacount` INT, IN `p_dt1` DATE, IN `p_dt2` DATE)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;

      IF p_accacount = 3
         THEN
          SELECT
                  b.AccCode    AS accode,
                  b.AccName    AS accname,
                  SUM(a.Debit) AS tolal2
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                AccountsTb AS b
                  ON a.AccIDFrom = b.AccID

          WHERE
                  b.BranchID = p_bracnID
                  AND a.InsertDate >= p_dt1
                  AND a.InsertDate <= p_dt2
                  AND (   a.CurrencyID = 1
                          OR a.CurrencyID = 13)
                  AND (   LEFT(b.AccParent, 5) = 30101
                          OR LEFT(b.AccParent, 5) = 30102)
                  AND b.Accline = 4
                  AND AccCode LIKE CONCAT(CAST(p_accacount AS CHAR), '%')
          GROUP BY
                  b.AccCode,
                  b.AccName,
                  b.AccID;
        END IF;


      COMMIT;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_GetAccIDBaseOnBranchID`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_GetAccIDBaseOnBranchID`(IN `p_BranchID` INT, IN `p_AccParent` DECIMAL(18,0))
BEGIN
START TRANSACTION;

	SELECT AccID
	FROM AccountsTb WHERE AccParent=p_AccParent AND AccountsTb.BranchID	= p_BranchID
	ORDER BY AccountsTb.AccID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_GetParentAccCode`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_GetParentAccCode`(IN `p_BranchID` INT, IN `p_AccParent` BIGINT)
BEGIN
START TRANSACTION;

	select AccCode FROM AccountsTb  where AccParent  =p_AccParent and BranchID=p_BranchID;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_GetShepingAcc`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_GetShepingAcc`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	select AccID,AccName FROM AccountsTb  where (AccParent  =4010205 OR AccParent=4010206) and BranchID=p_BranchID;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadEMPSafeToLKP`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadEMPSafeToLKP`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
     SELECT a.AccID,
            UNAME
     FROM TB_Users as a LEFT OUTER JOIN AccountsTb as b on a.AccID=B.AccID
     WHERE a.BranchID = p_BranchID AND a.TypeID	=1 AND a.IsActive=1;
     COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadEMPSafeToLKPHasVal`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadEMPSafeToLKPHasVal`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
     SELECT a.AccID,
            UNAME
     FROM TB_Users as a LEFT OUTER JOIN AccountsTb as b on a.AccID=B.AccID
     WHERE a.BranchID = p_BranchID AND a.TypeID	=1
	 group by a.AccID,
            UNAME
	HAVING `SafeIDEMP_GetAccVal`(a.AccID,p_BranchID)	>0.000;
     COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadEMPSafeToLKPHasValORNOT`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadEMPSafeToLKPHasValORNOT`(IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_TYPEs` INT)
BEGIN
START TRANSACTION;




  IF p_TypeID = 5
     THEN

















      SELECT
              at.AccID,
              at.AccName                              AS UNAME,
              Account_GetAccVal(AccID, p_TYPEs, 0) AS GetAccVal
      FROM
              AccountsTb at
      WHERE
              at.AccParent = (SELECT
                          a.AccCode
                  FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = 10104
                          AND a.BranchID = p_BranchID)
              AND at.AccActive = 1

      GROUP BY
              accid,
              accname
      HAVING
              Account_GetAccVal(at.AccID, p_TYPEs, 2) > 0.000;
    END IF;

  IF p_TypeID = 7
     THEN












      SELECT
              at.AccID,
              at.AccName                              AS UNAME,
              Account_GetAccVal(AccID, p_TYPEs, 0) AS GetAccVal
      FROM
              AccountsTb at
      WHERE
              at.AccParent = (SELECT
                          a.AccCode
                  FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = 10104
                          AND a.BranchID = p_BranchID)
              AND at.AccActive = 1

      GROUP BY
              accid,
              accname;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LOADINTOLKPBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LOADINTOLKPBASEDONAccParent`(IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_AccParent` BIGINT, IN `p_CurrencyID` INT)
BEGIN
START TRANSACTION;


IF  p_AccParent<>30101
 THEN
  SELECT
          at.AccID,
          at.AccName,
          Account_GetAccVal(AccID,1,2) AS AccVal
  FROM
          AccountsTb at
  WHERE
          at.AccParent =  p_AccParent
          AND At.accActive = 1
          AND at.BranchID = p_BranchID;
END IF;

IF  p_AccParent=30101
 THEN
  SELECT
          at.AccID,
          at.AccName,
          Account_GetAccVal(AccID,1,2) AS AccVal
  FROM
          AccountsTb at
  WHERE
          at.AccParent LIKE  '30101%'
          AND At.accActive = 1
          AND at.BranchID = p_BranchID;
END IF;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LOADINTOLKPBASEDONAccParent_WithoutBranch`;
DELIMITER //
