DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadMainBranchSafes`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadMainBranchSafes`(IN `p_BranchID` INT, IN `p_SType` INT)
BEGIN
START TRANSACTION;


  IF p_SType = 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY x.AccID ASC) AS '#',
              x.AccID,
              x.AccName             AS 'الخزنة',
              x.Total               AS 'الرصيد'
      FROM
              (   SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Account_GetAccVal(a.AccID,b.CurrencyID,0) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccounts_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE
                          NOT EXISTS (SELECT
                                      b.AccID
                              FROM
                                      TB_Users AS b
                              WHERE
                                      a.AccID = b.AccID
                                      AND b.BranchID = p_BranchID)
                          AND a.BranchID = p_BranchID
                          AND a.AccParent = 1010101
                          AND Accline = 4
                          AND (   b.CurrencyID = 1)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID
UNION
                           SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Account_GetAccVal(a.AccID,b.CurrencyID,0) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccounts_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE

                           a.BranchID = p_BranchID
                          AND a.AccParent LIKE '101040%'
                          AND Accline = 4
                          AND (   b.CurrencyID = 1)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID

                  UNION

                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccID,
                          b.AccName,
                          Sum_MainSAfes(p_BranchID, A.CurrencyID, 1) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                  WHERE
                          A.IsActive = 1
                          AND LEFT(b.AccParent, 5) = 10102
                          AND A.AccBranchID = p_BranchID
                          AND (   A.CurrencyID <> 1)
                  GROUP BY
                          b.AccID,
                          b.AccName,
                          A.CurrencyID

                  UNION


                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Sum_MainSAfes(p_BranchID, b.CurrencyID, 2) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccountsCurrency_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE
                          NOT EXISTS (SELECT
                                      b.AccID
                              FROM
                                      TB_Users AS b
                              WHERE
                                      a.AccID = b.AccID
                                      AND b.BranchID = p_BranchID)
                          AND a.BranchID = p_BranchID
                          AND a.AccParent = 10104
                          AND Accline = 4
                          AND (   b.CurrencyID <> 1)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID

                  UNION
                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccParent AS AccID,
                          CONCAT('خزائن الموظفين', SPACE(1), c.CuName) AS AccName,
                          IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(A.Debit), 0) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      INNER JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                      INNER JOIN
                        CurrencyMainTb AS c
                            ON a.CurrencyID = c.ID
                  WHERE
                          A.IsActive = 1
                          AND A.AccBranchID = p_BranchID
                          AND LEFT(b.AccParent, 5) = 10104
                          AND a.DailyClosed = 0
                  GROUP BY
                          b.AccParent,
                          b.AccID,
                          A.CurrencyID,
                          c.CuName
                  UNION

                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccParent AS AccID,
                          CONCAT('حسابات المصارف لعملة', SPACE(1), c.CuName) AS AccName,
                          Sum_MainSAfes(p_BranchID, A.CurrencyID, 3) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                      INNER JOIN
                        CurrencyMainTb AS c
                            ON a.CurrencyID = c.ID
                  WHERE
                          A.IsActive = 1
                          AND LEFT(b.AccParent, 5) = 10105
                          AND A.AccBranchID = p_BranchID
                          AND (   A.CurrencyID <> 1)
                  GROUP BY
                          b.AccID,
                          A.CurrencyID,
                          c.CuName,
                          b.AccParent) x
                          GROUP BY x.AccID,
                          x.AccName,
                          x.Total
                          HAVING x.Total<>0;
    END IF;
  IF p_SType = 1
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.AccID ASC)                                          AS '#',
              a.AccID,
              a.AccName                                                      AS 'الخزنة',
              FORMAT(`EMPCUST_GetAccVal`(a.AccID) * -1, 3) AS 'الرصيد'
      FROM
              AccountsTb AS a
      WHERE
              a.CountryID = p_BranchID
              AND LEFT(a.AccParent, 6) = 101012
              AND Accline = 4
              AND `EMPCUST_GetAccVal`(a.AccID) * -1 > 0;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadMainBranchSafesDetails`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadMainBranchSafesDetails`(IN `p_BranchID` INT, IN `p_SafeID` BIGINT, IN `p_SType` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(15,3), INOUT `p_SumCreditFinal` DECIMAL(15,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(15,3), INOUT `p_OverAllPeroidTotal` DECIMAL(15,3), INOUT `p_PreviewBalanceTotal` DECIMAL(15,3), IN `p_LoadType` TINYINT UNSIGNED)
BEGIN
DECLARE v_MainBr                 INT;
DECLARE v_SumDebit DECIMAL(12, 3) DEFAULT 0.000;
DECLARE v_SumCredit DECIMAL(12, 3) DEFAULT 0.000;
DECLARE v_OverAllPeroid DECIMAL(15, 3) DEFAULT 0.000;
DECLARE v_PreviewBalance DECIMAL(15, 3) DEFAULT 0.000;
DECLARE v_OverAllNetTotal DECIMAL(12, 3) DEFAULT 0.000;
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3) DEFAULT 0.000;
DECLARE v_AccFrom                BIGINT;
DECLARE v_IsDefault              BIT;


  START TRANSACTION;




IF p_BranchID<>0
 THEN

  SELECT b.IsDefault INTO v_IsDefault FROM
          AccountsTb AS a
      JOIN
        CurrencyMainTb AS b
          ON a.AccParent = b.FatherPerintACC
  WHERE
          (       AccParent = 1010101
                  OR LEFT(AccParent, 5) = 10102)
          AND (BranchID = p_BranchID )
          AND a.AccID = p_SafeID;

  IF p_LoadType = 1
     THEN
      IF p_SType = 0
         THEN

          IF v_IsDefault = 1
             THEN
              SELECT
                      ROW_NUMBER() OVER (
                      ORDER BY a.AccID ASC)                                                                                    AS '#',
                      b.ISID                                                                                                   AS 'الرمز',
                      b.InsertDate                                                                                             AS 'التاريخ',
                      FORMAT(b.Debit, 2)                                                                            AS 'مدين',
                      FORMAT(b.Credit, 2)                                                                           AS 'دائن',
                      FORMAT(`MainBranchSafesDetails_GetNetTotal`(p_SafeID, p_BranchID, b.CurrencyID, b.ID), 2) AS 'الصافي',
                      b.MovementType                                                                                           AS 'طبيعة الحركة'
              FROM
                      AccountsTb AS a
                  LEFT JOIN
                    ExSyAccounts_AccSafeActivityTb AS b
                      ON a.AccID = b.AccIDFrom
                  LEFT JOIN
                    CurrencyTb AS c
                      ON b.CurrencyID = c.ID
              WHERE
                      b.AccBranchID = p_BranchID
                      AND b.AccIDFrom = p_SafeID
                      AND b.IsActive = 1
                      AND b.InsertDate >= p_D1
                      AND b.InsertDate <= p_D2;


              SELECT SUM(a.Debit) INTO v_SumDebit FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Credit) INTO v_SumCredit FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;
              SET p_SumDebitFinal = v_SumDebit;
              SET p_SumCreditFinal = v_SumCredit;

              SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllPeroidTotal FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;

              SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO p_PreviewBalanceTotal FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate < p_D1
                      AND a.AccBranchID = p_BranchID;


              SELECT
                      IFNULL(FORMAT(p_SumDebitFinal, 2), 0.000),
                      IFNULL(FORMAT(p_SumCreditFinal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllPeroidTotal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllNetTotalFinal, 2), 0.000),
                      IFNULL(FORMAT(p_PreviewBalanceTotal, 2), 0.000);
            END IF;

          IF v_IsDefault = 0
             THEN
              SELECT
                      ROW_NUMBER() OVER (
                      ORDER BY a.AccID ASC)                                                                                    AS '#',
                      b.ISID                                                                                                   AS 'الرمز',
                      b.InsertDate                                                                                             AS 'التاريخ',
                      FORMAT(b.Credit, 2)                                                                           AS 'مدين',
                      FORMAT(b.Debit, 2)                                                                            AS 'دائن',
                      FORMAT(`MainBranchSafesDetails_GetNetTotal`(p_SafeID, p_BranchID, b.CurrencyID, b.ID), 2) AS 'الصافي',
                      b.MovementType                                                                                           AS 'طبيعة الحركة'
              FROM
                      AccountsTb AS a
                  LEFT JOIN
                    ExSyAccountsCurrency_AccSafeActivityTb AS b
                      ON a.AccID = b.AccIDFrom
                  LEFT JOIN
                    CurrencyTb AS c
                      ON b.CurrencyID = c.ID
              WHERE
                      b.AccBranchID = p_BranchID
                      AND b.AccIDFrom = p_SafeID
                      AND b.IsActive = 1
                      AND b.InsertDate >= p_D1
                      AND b.InsertDate <= p_D2;


              SELECT SUM(a.Credit) INTO v_SumDebit FROM
                      ExSyAccountsCurrency_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Debit) INTO v_SumCredit FROM
                      ExSyAccountsCurrency_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;
              SET p_SumDebitFinal = v_SumDebit;
              SET p_SumCreditFinal = v_SumCredit;

              SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllNetTotalFinal FROM
                      ExSyAccountsCurrency_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllPeroidTotal FROM
                      ExSyAccountsCurrency_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate >= p_D1
                      AND a.InsertDate <= p_D2
                      AND a.AccBranchID = p_BranchID;

              SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO p_PreviewBalanceTotal FROM
                      ExSyAccountsCurrency_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.InsertDate < p_D1
                      AND a.AccBranchID = p_BranchID;


              SELECT
                      IFNULL(FORMAT(p_SumDebitFinal, 2), 0.000),
                      IFNULL(FORMAT(p_SumCreditFinal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllPeroidTotal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllNetTotalFinal, 2), 0.000),
                      IFNULL(FORMAT(p_PreviewBalanceTotal, 2), 0.000);
            END IF;

        END IF;
      IF p_SType = 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY b.InsertDate ASC)                                                                               AS '#',
                  b.ISID                                                                                                   AS 'الرمز',
                  b.InsertDate                                                                                             AS 'التاريخ',
                  FORMAT(b.Debit, 2)                                                                            AS 'مدين',
                  FORMAT(b.Credit, 2)                                                                           AS 'دائن',
                  FORMAT(`MainBranchSafesDetails_GetNetTotal`(p_SafeID, p_BranchID, b.CurrencyID, b.ID), 2) AS 'الصافي',
                  b.MovementType                                                                                           AS 'طبيعة الحركة'
          FROM
                  AccountsTb AS a
              LEFT JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
              LEFT JOIN
                CurrencyTb AS c
                  ON b.CurrencyID = c.ID
          WHERE
                  b.AccBranchID = p_BranchID
                  AND b.AccIDFrom = p_SafeID
                  AND b.IsActive = 1
                  AND b.InsertDate >= p_D1
                  AND b.InsertDate <= p_D2
          ORDER BY
                  b.InsertDate;


          SELECT SUM(a.Debit) INTO v_SumDebit FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.IsActive = 1
                  AND a.AccIDFrom = p_SafeID
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.AccBranchID = p_BranchID;

          SELECT SUM(a.Credit) INTO v_SumCredit FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.IsActive = 1
                  AND a.AccIDFrom = p_SafeID
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.AccBranchID = p_BranchID;
          SET p_SumDebitFinal = v_SumDebit;
          SET p_SumCreditFinal = v_SumCredit;

          SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.IsActive = 1
                  AND a.AccIDFrom = p_SafeID
                  AND a.AccBranchID = p_BranchID;

          SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllPeroidTotal FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.IsActive = 1
                  AND a.AccIDFrom = p_SafeID
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.AccBranchID = p_BranchID;

          SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO p_PreviewBalanceTotal FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.IsActive = 1
                  AND a.AccIDFrom = p_SafeID
                  AND a.InsertDate < p_D1
                  AND a.AccBranchID = p_BranchID;


          SELECT
                  IFNULL(FORMAT(p_SumDebitFinal, 2), 0.000),
                  IFNULL(FORMAT(p_SumCreditFinal, 2), 0.000),
                  IFNULL(FORMAT(p_OverAllPeroidTotal, 2), 0.000),
                  IFNULL(FORMAT(p_OverAllNetTotalFinal, 2), 0.000),
                  IFNULL(FORMAT(p_PreviewBalanceTotal, 2), 0.000);
        END IF;
    END IF;
  IF p_LoadType = 0
     THEN
      IF p_SType = 0
         THEN
          IF v_IsDefault = 1
             THEN
              SELECT
                      ROW_NUMBER() OVER (
                      ORDER BY a.AccID ASC)                                                                                    AS '#',
                      b.ISID                                                                                                   AS 'الرمز',
                      b.InsertDate                                                                                             AS 'التاريخ',
                      FORMAT(b.Debit, 2)                                                                            AS 'مدين',
                      FORMAT(b.Credit, 2)                                                                           AS 'دائن',
                      FORMAT(`MainBranchSafesDetails_GetNetTotal`(p_SafeID, p_BranchID, b.CurrencyID, b.ID), 2) AS 'الصافي',
                      b.MovementType                                                                                           AS 'طبيعة الحركة'
              FROM
                      AccountsTb AS a
                  LEFT JOIN
                    ExSyAccounts_AccSafeActivityTb AS b
                      ON a.AccID = b.AccIDFrom
                  LEFT JOIN
                    CurrencyTb AS c
                      ON b.CurrencyID = c.ID
              WHERE
                      b.AccBranchID = p_BranchID
                      AND b.AccIDFrom = p_SafeID
                      AND b.IsActive = 1;


              SELECT SUM(a.Debit) INTO v_SumDebit FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Credit) INTO v_SumCredit FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;
              SET p_SumDebitFinal = v_SumDebit;
              SET p_SumCreditFinal = v_SumCredit;

              SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;

              SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllPeroidTotal FROM
                      ExSyAccounts_AccSafeActivityTb AS a
              WHERE
                      a.IsActive = 1
                      AND a.AccIDFrom = p_SafeID
                      AND a.AccBranchID = p_BranchID;
SET p_PreviewBalanceTotal = 0.000;
              SELECT
                      IFNULL(FORMAT(p_SumDebitFinal, 2), 0.000),
                      IFNULL(FORMAT(p_SumCreditFinal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllPeroidTotal, 2), 0.000),
                      IFNULL(FORMAT(p_OverAllNetTotalFinal, 2), 0.000),
                      IFNULL(FORMAT(p_PreviewBalanceTotal, 2), 0.000);
            END IF;

          IF v_IsDefault = 0
             THEN
              SELECT
                      ROW_NUMBER() OVER (
                      ORDER BY a.AccID ASC)                                                                                    AS '#',
                      b.ISID                                                                                                   AS 'الرمز',
                      b.InsertDate                                                                                             AS 'التاريخ',
                      FORMAT(b.Credit, 2)                                                                           AS 'مدين',
                      FORMAT(b.Debit, 2)                                                                            AS 'دائن',
                      FORMAT(`MainBranchSafesDetails_GetNetTotal`(p_SafeID, p_BranchID, b.CurrencyID, b.ID), 2) AS 'الصافي',
                      b.MovementType                                                                                           AS 'طبيعة الحركة'
              FROM
                      AccountsTb AS a
                  LEFT JOIN
                    ExSyAccountsCurrency_AccSafeActivityTb AS b
