DROP PROCEDURE IF EXISTS `AccountsTb_LoadSafeToTransferHaveVal`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadSafeToTransferHaveVal`(IN `p_BranchID` INT, IN `p_CurrencyId` INT)
BEGIN
START TRANSACTION;



















   SELECT
			at.AccID  ,
			at.AccName
	FROM
			AccountsTb at
			where at.AccParent= (select a.AccCode from AccountsTb as a where a.AccParent= 10104 and a.BranchID=  p_BranchID) and at.AccActive=1

GROUP BY
        accid,
         accname
  HAVING
         `SafeAcc_GetAccVal`(at.AccID, p_BranchID, p_CurrencyId) > 0.000;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_LoadSafeToTransferNotExist`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_LoadSafeToTransferNotExist`(IN `p_BranchID` INT, IN `p_AccID` INT)
BEGIN
START TRANSACTION;

















   SELECT
			at.AccID  ,
			at.AccName
	FROM
			AccountsTb at
			where at.AccParent= (select a.AccCode from AccountsTb as a where a.AccParent= 10104 and a.BranchID=  p_BranchID) and at.AccActive=1 and at.AccID<>p_AccID;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_MainBranchSafesDetailsNetTotal`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_MainBranchSafesDetailsNetTotal`(IN `p_BranchID` INT, IN `p_SafeID` BIGINT)
BEGIN
DECLARE v_IsDefault bit;


     START TRANSACTION;


	 If p_BranchID<>0
	  THEN
	 SELECT b.IsDefault INTO v_IsDefault FROM AccountsTb as a join CurrencyMainTb as b on a.accparent=b.FatherPerintACC where (AccParent=1010101 or left(AccParent,5)=10102) and (BranchID=p_BranchID or p_BranchID=0) and a.AccID=p_SafeID;
	 END IF;

	 If p_BranchID=0
	  THEN
SET v_IsDefault=1;
	 END IF;

	 if v_IsDefault=1
	  THEN
     SELECT CASE                 WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit)                 THEN SUM(a.Debit) - SUM(a.Credit)                 ELSE 0.000             END AS 'أول',
            CASE                 WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit)                 THEN SUM(a.Credit) - SUM(a.Debit)                 ELSE 0.000             END AS 'ثاني'
     FROM ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
     WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND a.AccIDFrom = p_SafeID
           AND (a.AccBranchID = p_BranchID Or p_BranchID=0);
		   END IF;

		   if v_IsDefault=0
	  THEN
     SELECT CASE                 WHEN SUM(a.Debit) - SUM(a.Credit) < SUM(a.Credit) - SUM(a.Debit)                 THEN  SUM(a.Credit)-SUM(a.Debit)                  ELSE 0.000             END AS 'أول',
            CASE                 WHEN SUM(a.Credit) - SUM(a.Debit) < SUM(a.Debit) - SUM(a.Credit)                 THEN  SUM(a.Debit)-SUM(a.Credit)                  ELSE 0.000             END AS 'ثاني'
     FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          INNER JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
     WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND a.AccIDFrom = p_SafeID
           AND (a.AccBranchID = p_BranchID Or p_BranchID=0);
		   END IF;
     COMMIT;
END //
DELIMITER ;

