DECLARE v_MainCurrentAcc BIGINT;
DECLARE v_MainShareAcc BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_MsgSatues = 0; END;

      START TRANSACTION;




      SELECT a.ID, a.CurrentAccID INTO v_MainBr, v_MainCurrentAcc FROM
              CoBranch a
      WHERE
              a.IsMain = 1;



      SELECT at.AccID INTO v_MainShareAcc FROM
              AccountsTb at
      WHERE
              at.AccCode = 2040101601;


      SELECT cit.D1, cit.D2, cit.BranchID INTO v_D1, v_D2, v_BranchID FROM
              ClosingINCOMESTATMENT_TB cit
      WHERE
              cit.Code = p_ISID;

      SELECT a.CurrentAccID INTO v_CurrentAcc FROM
              CoBranch a
      WHERE
              a.ID = v_BranchID;


      SELECT IFNULL(SUM(apt.PTRATE), 0) INTO v_SumPartnerRate FROM
              AddPartnerTb apt
      WHERE
              BranchID = v_BranchID
              AND apt.IsActive = 1;

      IF v_SumPartnerRate > 100
         THEN
          SET p_MsgSatues = 0;
          SET p_MsgBox = 'عذرا لايمكن أن يكون مجموع نسبة الشركاء أكثر من 100% الرجاء التأكد من تقسيم النسب بشكل صحيح ثم أعد المحاولة';
          ROLLBACK;
          LEAVE proc;
        END IF;
















      SELECT a.AccIDFrom, a.Credit, a.Debit INTO v_AccProfORLoss, v_Credit, v_Debit FROM
              ExSyAccounts_AccSafeActivityTb a
      WHERE
              a.ID = p_ID;


      SELECT IFNULL(COUNT(a.AccIDFrom), 0) INTO v_CodeID FROM
              ExSyAccounts_AccSafeActivityTb a
      WHERE
              a.TypeID = 42;



      SET v_Code = CONCAT('42', '-', CAST(v_BranchID AS CHAR), '-', CAST(v_CodeID AS CHAR));
      SELECT cb.BName INTO v_BName FROM
              CoBranch cb
      WHERE
              cb.ID = v_BranchID;





      IF v_Credit > v_Debit
         THEN
          SET v_MovmentType = CONCAT('تقسيم أرباح', ' ', v_BName, ' ', 'عن الفترة من', ' ', CAST(v_D1 AS CHAR), ' ', 'إلى', ' ', CAST(v_D2 AS CHAR));
        END IF;
      IF v_Credit < v_Debit
         THEN
          SET v_MovmentType = CONCAT('تقسيم خسائر', ' ', v_BName, ' ', 'عن الفترة من', ' ', CAST(v_D1 AS CHAR), ' ', 'إلى', ' ', CAST(v_D2 AS CHAR));
        END IF;




      IF v_Credit > v_Debit
         THEN
          SET v_NetTotal = v_Credit - v_Debit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement,
                  DailyClosed,
                  SafeIDDailyClose,
                  Description
                )
          VALUES
                  (
                    p_SafeID, v_NetTotal, 0.000, NOW(), v_Code, 1, 42, 71, v_BranchID, v_AccProfORLoss, 0, v_MovmentType, 1, v_MovmentType, v_MovmentType, 1, p_SafeID, v_MovmentType
                  );



          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement,
                  DailyClosed,
                  SafeIDDailyClose,
                  Description
                )
              SELECT
                      p_SafeID,
                      0.000,
                      v_NetTotal * (a.PTRATE / 100),
                      NOW(),
                      v_Code,
                      1,
                      42,
                      71,
                      v_BranchID,
                      a.CurrentAcc,
                      v_AccProfORLoss,
                      v_MovmentType,
                      1,
                      v_MovmentType,
                      v_MovmentType,
                      1,
                      p_SafeID,
                      v_MovmentType
              FROM
                      AddPartnerTb AS a
              WHERE
                      a.BranchID = v_BranchID
                      AND a.IsActive = 1
                      AND a.PTRATE > 0;

          IF v_SumPartnerRate < 100
             THEN

              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          0.000,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_BranchID,
                          v_MainCurrentAcc,
                          v_MainShareAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;


              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          0.000,
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_MainBr,
                          v_CurrentAcc,
                          v_MainShareAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;


              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          0.000,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_MainBr,
                          v_MainShareAcc,
                          v_CurrentAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;
            END IF;
        END IF;



      IF v_Credit < v_Debit
         THEN
          SET v_NetTotal = v_Debit - v_Credit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement,
                  DailyClosed,
                  SafeIDDailyClose,
                  Description
                )
          VALUES
                  (
                    p_SafeID, 0.000, v_NetTotal, NOW(), v_Code, 1, 42, 71, v_BranchID, v_AccProfORLoss, 0, v_MovmentType, 1, v_MovmentType, v_MovmentType, 1, p_SafeID, v_MovmentType
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement,
                  DailyClosed,
                  SafeIDDailyClose,
                  Description
                )
              SELECT
                      p_SafeID,
                      v_NetTotal * (a.PTRATE / 100),
                      0.000,
                      NOW(),
                      v_Code,
                      1,
                      42,
                      72,
                      v_BranchID,
                      a.CurrentAcc,
                      v_AccProfORLoss,
                      v_MovmentType,
                      1,
                      v_MovmentType,
                      v_MovmentType,
                      1,
                      p_SafeID,
                      v_MovmentType
              FROM
                      AddPartnerTb AS a
              WHERE
                      a.BranchID = v_BranchID
                      AND a.IsActive = 1
                      AND a.PTRATE > 0;

          IF v_SumPartnerRate < 100
             THEN

              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          0.000,
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_BranchID,
                          v_MainCurrentAcc,
                          v_MainShareAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;


              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          0.000,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_MainBr,
                          v_CurrentAcc,
                          v_MainShareAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;


              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      InsertDate,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      MovementType,
                      CurrencyID,
                      Note,
                      SafeIDMovement,
                      DailyClosed,
                      SafeIDDailyClose,
                      Description
                    )
                  SELECT
                          p_SafeID,
                          v_NetTotal * ((100 - IFNULL(SUM(a.PTRATE), 0)) / 100),
                          0.000,
                          NOW(),
                          v_Code,
                          1,
                          42,
                          71,
                          v_MainBr,
                          v_MainShareAcc,
                          v_CurrentAcc,
                          v_MovmentType,
                          1,
                          v_MovmentType,
                          v_MovmentType,
                          1,
                          p_SafeID,
                          v_MovmentType
                  FROM
                          AddPartnerTb AS a
                  WHERE
                          a.BranchID = v_BranchID
                          AND a.IsActive = 1
                          AND a.PTRATE > 0;
            END IF;
        END IF;



      UPDATE
              ExSyAccounts_AccSafeActivityTb
      SET
              DailyClosed = 1
      WHERE
        ID = p_ID;

      COMMIT;
      SET p_MsgSatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_ProfitaAndLossSharingLoadDVG`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_ProfitaAndLossSharingLoadDVG`()
BEGIN
START TRANSACTION;
  SELECT
          a.ISID,
          b.AccName,
          a.Credit,
          a.Debit,
          c.BName,
          a.MovementType
  FROM
          ExSyAccounts_AccSafeActivityTb a
      LEFT JOIN
        AccountsTb b
          ON a.AccIDFrom = b.AccID
      LEFT JOIN
        CoBranch c
          ON a.AccBranchID = c.ID
  WHERE

           a.DailyClosed = 1
          AND a.IsActive=1
          AND a.TypeID=42;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_SafeMobile`;
DELIMITER //
CREATE PROCEDURE `AccountsTb_SafeMobile`(IN `p_AccCode` BIGINT, IN `p_AccName` LONGTEXT, IN `p_AccPhone` LONGTEXT, IN `p_AccMobile` LONGTEXT, IN `p_BranchID` INT, IN `p_AddUser` INT, IN `p_LimitedVal` DOUBLE, INOUT `p_Imsg` INT, INOUT `p_MSg` LONGTEXT)
proc: BEGIN
DECLARE v_IDcode int;
DECLARE v_IDoce_set int;
DECLARE v_AccParent bigint;
DECLARE v_SET_pohone LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set p_Imsg = 0; CALL ERROR_PROC(); END;
START TRANSACTION;


SELECT AccCode INTO v_AccParent FROM AccountsTb AS A WHERE A.AccParent = 10104 AND A.BranchID= p_BranchID;

IF v_AccParent IS NULL
 THEN
set p_Imsg = 0;
set p_MSg= 'الرجاء التحققمن الحساب الاب موجود او لا';
rollback;
LEAVE proc;

END IF;


SELECT IFNULL(max (IDcode),0) + 1 INTO v_IDcode FROM AccountsTb as a where a.AccParent= v_AccParent;

SELECT IDcode INTO v_IDoce_set FROM AccountsTb as a where a.AccParent= v_AccParent and  IDcode= v_IDcode;

SELECT AccPhone INTO v_SET_pohone FROM AccountsTb as a where a.AccPhone= p_AccPhone;

if v_SET_pohone = p_AccPhone
 THEN

set p_Imsg = 0;
set p_MSg= CONCAT('عذرا رقم الهاتف هذه موجود مسبقا باسم حساب اخر', SPACE(1), p_AccPhone);
rollback;
LEAVE proc;

END IF;


if v_IDoce_set = v_IDcode
 THEN

set p_Imsg = 0;
set p_MSg= 'عذرا هذه الرقم موجود مسبقا';
rollback;
LEAVE proc;
END IF;

INSERT INTO `AccountsTb`
           (`AccCode`,`AccName`,
		   `AccType`,
		   `Accline`,
		   `AccParent`,
		   `AccDmType`,
		   `AccFinal`
           ,`AccPhone`
           ,`AccMobile`
           ,`BranchID`
           ,`AddUser`
           ,`AddDate`
           ,`AccActive`
           ,`AccCurID`
           ,`CountryID`
           ,`IDcode`
           ,`LimitedVal`
          )
    values(p_AccCode , p_AccName , 1 ,5 ,v_AccParent  , 0 ,1 , p_AccPhone ,p_AccMobile
	 , p_BranchID ,p_AddUser , NOW(), 1 ,0,1 ,v_IDcode , p_LimitedVal  );


INSERT INTO `users`
           (
           `phone`
           ,`UeserType`
           ,`AccID`
           ,`Reg`
           ,`Countries`
           ,`BrancchID`
          )
		  select a.AccPhone,  5 , a.AccID , 'NO' ,a.IDcode , a.BranchID
		  from AccountsTb as a
		  where a.AccCode=p_AccCode and a.AccParent= v_AccParent  and a.IDcode= v_IDcode;



		  INSERT INTO `wallet`
           (`UeserID`
           ,`Walet`
           ,`Currency_ID`)


		  select a.id ,  0 , c.ID from users as a inner join AccountsTb as b on a.AccID= b.AccID
		  cross join CurrencyMainTb as c
		   where b.AccCode=p_AccCode and b.AccParent= v_AccParent  and b.IDcode= v_IDcode;


	 commit;
	 set p_Imsg= 1;
	 END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_select_for`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_select_for`(IN `p_tybid` INT, IN `p_dat1` DATE, IN `p_date2` DATE, IN `p_accline` TINYINT UNSIGNED, IN `p_BrnchID` INT)
BEGIN
DECLARE v_SELECTASS INT DEFAULT 0;
DECLARE v_SELECTDASS INT DEFAULT 0;
DECLARE v_MainBranch INT;
DECLARE v_Ismain BIT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;

    START TRANSACTION;


    SELECT co.IsMain INTO v_Ismain FROM
            CoBranch AS co
    WHERE
            co.ID = p_BrnchID;
    SELECT co.ID INTO v_MainBranch FROM
            CoBranch AS co
    WHERE
            co.IsMain = 1;
    IF p_tybid = 0
       THEN
        SELECT
                AccCode,
                AccName,
                LEFT(CAST(CAST(AccCode AS SIGNED) AS CHAR),1) AS ID,
                AccID,
                FORMAT(sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1), 2)               AS debet,
                FORMAT(sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1), 2)                   AS credet,
                v_SELECTASS                                                                               AS INSERTDEBIT,
                v_SELECTDASS                                                                              AS INSERCREDET,
                FORMAT(sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1) + v_SELECTDASS, 2) AS Noetes,
                FORMAT(sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1) + v_SELECTASS, 2)      AS total
        FROM
                AccountsTb
        WHERE


                BranchID = p_BrnchID

                AND (   Accline = p_accline
                        OR p_accline = 0)
        GROUP BY
                AccCode,
                AccName,
                AccID
        HAVING
                sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1) > 0
                OR sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1) > 0
        ORDER BY

                AccCode,
                AccName,
                AccID;
      END IF;


    IF p_tybid = 1
       THEN
        IF v_Ismain = 1

           THEN
            SELECT



                    AccCode,
                    AccName,
                    CASE                             WHEN AccParent LIKE N'10109%'                               THEN                               'مشترك جمعية'                             WHEN AccParent LIKE N'1010100%'                               THEN                               'حساب مدين'                             WHEN AccParent LIKE N'20103%'                               THEN                               'عميل'                             WHEN AccParent LIKE N'20105%'                               THEN                               'موظف'                             WHEN AccParent LIKE N'10104%'                               THEN                               'خزنة موظف'                             WHEN AccParent LIKE N'201010%'                               THEN                               'شريك'                             ELSE                             '-'                     END                                                                                                                                                         AS accparent,

                    AccID,
                    FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2) AS debet,
                    FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)         AS credet,
                    v_SELECTASS                                                                                                                                                  AS INSERTDEBIT,
                    v_SELECTDASS                                                                                                                                                 AS INSERCREDET,
                    CASE                             WHEN (sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0                               THEN                               FORMAT((sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)), 2)                             ELSE                             '0.00'                     END                                                                                                                                                         AS Noetes,
                    CASE                             WHEN (sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0                               THEN                               FORMAT((sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)), 2)                             ELSE                             '0.00'                     END                                                                                                                                                         AS total
            FROM
                    AccountsTb AS a
            WHERE


                    AccType = p_tybid

                    AND (   (       a.BranchID = p_BrnchID
                                    AND (   AccParent <> 2010201
                                            OR AccParent <> 2010701))
                            OR (    a.BranchID <> p_BrnchID
                                    AND (   AccParent = 2010201
                                            OR AccParent = 2010701)))

            GROUP BY
                    AccCode,
                    AccName,
                    AccID,
                    AccParent
            HAVING
                    (sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)  > 0)
                    OR( sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) ) > 0
            ORDER BY
                    AccCode,
                    AccName,
                    AccID,
                    AccParent;












































          END IF;

        IF v_Ismain <> 1
           THEN
            BEGIN
              SELECT
                      AccCode,
                      AccName,
                      AccID,
                      CASE                               WHEN AccParent LIKE '10109%'                                 THEN                                 'مشترك جمعية'                               WHEN AccParent LIKE '1010100%'                                 THEN                                 'حساب مدين'                               WHEN AccParent LIKE '20103%'                                 THEN                                 'عميل'                               WHEN AccParent LIKE '20105%'                                 THEN                                 'موظف'                               WHEN AccParent LIKE '10104%'                                 THEN                                 'خزنة موظف'                               WHEN AccParent LIKE '201010%'                                 THEN                                 'شريك'                               ELSE                               '-'                       END                                                                                   AS accparent,
                      FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2) AS debet,
                      FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)     AS credet,
                      v_SELECTASS                                                                            AS INSERTDEBIT,
                      v_SELECTDASS                                                                           AS INSERCREDET,
                      CASE                               WHEN sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0                                 THEN                                 FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)                               ELSE                               '0'                       END                                                                                   AS Noetes,
                      CASE                               WHEN sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0                                 THEN                                 FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)                               ELSE                               '0'                       END                                                                                   AS total
              FROM
                      AccountsTb AS a
              WHERE



                      AccType = p_tybid
                      AND (   (       a.BranchID = v_MainBranch
                                      AND (   AccParent = 2010201
                                              OR AccParent = 2010701))
                              OR (    a.BranchID = p_BrnchID
                                      AND (   AccParent <> 2010201
                                              OR AccParent <> 2010701)))
              GROUP BY
                      AccCode,
                      AccName,
                      AccID,
                      AccParent
              HAVING
                      sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0
                      OR sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0
              ORDER BY
                      AccCode,
                      AccName,
                      AccID,
                      AccParent;
            END;
          END IF;

      END IF;
    COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_select_forDepositSafe`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_select_forDepositSafe`(IN `p_dat1` DATE, IN `p_date2` DATE, IN `p_BrnchID` INT, IN `p_CurrencyFrom` INT)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;
		START TRANSACTION;
		SELECT
				AccCode,
				AccName,
				AccID,
				sumDEBETalter(1, AccCode, p_dat1, p_date2,p_CurrencyFrom) AS debet,
				sumcredet(1, AccCode, p_dat1, p_date2,p_CurrencyFrom)	 AS credet
		FROM
				ACCOUNTSTB AS a
		WHERE
				AccActive = 1
				AND AccType = 1
				AND AccCode LIKE '113%'
				AND BranchID = p_BrnchID
		GROUP BY
				AccCode,
				AccName,
				AccID
		HAVING
				sumDEBETalter(1, AccCode, p_dat1, p_date2,p_CurrencyFrom) > 0
				OR sumcredet(1, AccCode, p_dat1, p_date2,p_CurrencyFrom) > 0
		ORDER BY
				AccCode;
		COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccountsTb_SelectByCode`;
DELIMITER //
