DROP PROCEDURE IF EXISTS `ACCOUNTSTB_update`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_update`(IN `p_AccCode` BIGINT, IN `p_AccName` VARCHAR(80), IN `p_AccType` TINYINT UNSIGNED, IN `p_AccParent` DECIMAL(18,0), IN `p_AccDmType` TINYINT UNSIGNED, IN `p_AccFinal` TINYINT UNSIGNED, IN `p_AccPhone` VARCHAR(15), IN `p_AccMobile` VARCHAR(15), IN `p_AccEmail` VARCHAR(80), IN `p_AccAddress` LONGTEXT, IN `p_AccNotes` LONGTEXT, IN `p_AccMaxLimit` INT, IN `p_AccMaxDuration` SMALLINT, IN `p_BranchID` INT, IN `p_ID` INT, IN `p_Accline` TINYINT UNSIGNED, IN `p_AccActive` TINYINT(1), IN `p_IDcode` BIGINT)
BEGIN
DECLARE v_IDcodse INT;
DECLARE v_perent DECIMAL(18, 0);
DECLARE v_EmpAccID bigint;
START TRANSACTION;
SET p_Accline=GetAccline( p_AccParent );


SELECT AccountsTb.AccParent INTO v_perent FROM AccountsTb
WHERE AccountsTb.AccID=p_ID;

SELECT AccID INTO v_EmpAccID FROM EmployeeTb where AccID=p_ID;

IF v_perent=p_AccParent
 THEN
	SELECT IDcode INTO v_IDcodse FROM AccountsTb
	WHERE AccountsTb.AccID=p_ID;

	IF v_IDcodse=NULL
	 THEN
SET p_IDcode=`AccountTb_GetIDCode`( p_AccParent, p_AccType );
	END IF;

	IF v_IDcodse IS NOT NULL
	 THEN
SET p_IDcode=v_IDcodse;
	END IF;

END IF;

IF v_perent<>p_AccParent
 THEN
SET p_IDcode=`AccountTb_GetIDCode`( p_AccParent, p_AccType );
END IF;

UPDATE AccountsTb
SET
	AccCode=p_AccCode, AccName=p_AccName, AccType=p_AccType, AccParent=p_AccParent, AccDmType=p_AccDmType, AccFinal=p_AccFinal, AccPhone=p_AccPhone, AccMobile=p_AccMobile, AccEmail=p_AccEmail, AccAddress=p_AccAddress, AccNotes=p_AccNotes, AccMaxLimit=p_AccMaxLimit, AccMaxDuration=p_AccMaxDuration, BranchID=p_BranchID, Accline=p_Accline, AccActive=p_AccActive, IDcode=p_IDcode
WHERE (AccID=p_ID
	  OR p_ID IS NULL);


	  Update EmployeeTb set BranchID=p_BranchID Where AccID=p_ID;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ACCOUNTSTB_UPDATECHANGEDBRANCH`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_UPDATECHANGEDBRANCH`(IN `p_ID` BIGINT, IN `p_AccCode` BIGINT, IN `p_AccName` VARCHAR(80), IN `p_AccParent` DECIMAL(18,0), IN `p_BranchID` INT, IN `p_IDcode` BIGINT)
BEGIN
START TRANSACTION;
UPDATE AccountsTb
SET
	AccCode=p_AccCode, AccName=p_AccName, AccParent=p_AccParent, BranchID=p_BranchID, IDcode=p_IDcode
WHERE (AccID=p_ID
	  OR p_ID IS NULL);
COMMIT;
