DROP PROCEDURE IF EXISTS `AccSafeActivityTb_DeleteRecord`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_DeleteRecord`(IN `p_Code` LONGTEXT, IN `p_TypeID` INT)
proc: BEGIN



    START TRANSACTION;

    IF NOT EXISTS (
        SELECT 1
        FROM `ExSyAccounts`.`AccSafeActivityTb`
        WHERE ISID = p_Code
          AND IsActive = 1
    )
     THEN
        ROLLBACK;
        SELECT N'❌ يوجد خطأ في رمز المعاملة، يرجى التحقق من الكود أولاً' AS Message;
        LEAVE proc;
    END IF;


    IF p_TypeID = 0
     THEN
        DELETE FROM `ExSyAccounts`.`AccSafeActivityTb`
        WHERE ISID = p_Code
          AND IsActive = 1;

        UPDATE InternalEx
        SET IsActive = 0
        WHERE Code = p_Code;

        SELECT N'✅ تم حذف السجل بنجاح' AS Message;
    END IF;


    IF p_TypeID = 1
     THEN
        DELETE FROM `ExSyAccounts`.`AccSafeActivityTb`
        WHERE ISID = p_Code
          AND IsActive = 1;

        UPDATE ExternalEx
        SET IsActive = 0
        WHERE Code = p_Code;

        SELECT N'✅ تم حذف السجل بنجاح' AS Message;
    END IF;

    COMMIT;
END //
DELIMITER ;

