DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GetAccountsDetails`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GetAccountsDetails`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebit` DECIMAL(15,3), INOUT `p_SumCredit` DECIMAL(15,3), INOUT `p_OverallTotal` DECIMAL(15,3))
BEGIN
DECLARE v_MainBranch INT;
DECLARE v_Ismain BIT;


  START TRANSACTION;

    SELECT co.IsMain INTO v_Ismain FROM
            CoBranch AS co
    WHERE
            co.ID = p_BranchID;
    SELECT co.ID INTO v_MainBranch FROM
            CoBranch AS co
    WHERE
            co.IsMain = 1;


IF v_Ismain = 1

           THEN
  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ISID ASC) AS '#',
          a.ISID                                  AS 'الرمز',
          b.AccName                               AS 'الجاري',
          a.InsertDate                            AS 'التاريخ',
          FORMAT(a.Debit, 2)           AS 'مدين',
          FORMAT(a.Credit, 2)          AS 'دائن',
		    a.MovementType                          AS 'طبيعة الحركة'


   FROM
          ExSyAccounts_AccSafeActivityTb AS a
      INNER JOIN
        AccountsTb AS b
          ON a.AccIDFrom = b.AccID












  WHERE
          a.IsActive = 1
          AND a.InsertDate >= p_D1
          AND a.InsertDate <= p_D2


		     AND ( a.AccBranchID = p_BranchID AND AccParent = 2010201 )

  ORDER BY
          a.ISID,
          a.ID ASC;

		  END IF;

IF v_Ismain <> 1

           THEN
  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ISID ASC) AS '#',
          a.ISID                                  AS 'الرمز',
          b.AccName                               AS 'الجاري',
          a.InsertDate                            AS 'التاريخ',
          FORMAT(a.Debit, 2)           AS 'مدين',
          FORMAT(a.Credit, 2)          AS 'دائن',
		  a.MovementType                          AS 'طبيعة الحركة'


   FROM
          ExSyAccounts_AccSafeActivityTb AS a
      INNER JOIN
        AccountsTb AS b
          ON a.AccIDFrom = b.AccID












  WHERE
          a.IsActive = 1
          AND a.InsertDate >= p_D1
          AND a.InsertDate <= p_D2


		    AND ( a.AccBranchID = p_BranchID AND AccParent = 2010201 )

  ORDER BY
          a.ISID,
          a.ID ASC;

		  END IF;


















  SELECT SUM(a.Debit) INTO p_SumDebit FROM
          ExSyAccounts_AccSafeActivityTb AS a
      INNER JOIN
        AccountsTb AS b
          ON a.AccIDFrom = b.AccID
      INNER JOIN
        InternalEx AS c
          ON a.ISID = c.Code
      INNER JOIN
        CoBranch AS d
          ON c.BranchRecievedID = d.ID
      INNER JOIN
        CoBranch AS e
          ON c.BranchDeliveredID = e.ID
  WHERE
          a.IsActive = 1
          AND a.InsertDate >= p_D1
          AND a.InsertDate <= p_D2
          AND b.BranchID = p_BranchID
          AND b.AccParent = 2010201;
  SELECT SUM(a.Credit) INTO p_SumCredit FROM
          ExSyAccounts_AccSafeActivityTb AS a
      INNER JOIN
        AccountsTb AS b
          ON a.AccIDFrom = b.AccID
      INNER JOIN
        InternalEx AS c
          ON a.ISID = c.Code
      INNER JOIN
        CoBranch AS d
          ON c.BranchRecievedID = d.ID
      INNER JOIN
        CoBranch AS e
          ON c.BranchDeliveredID = e.ID
  WHERE
          a.IsActive = 1
          AND a.InsertDate >= p_D1
          AND a.InsertDate <= p_D2
          AND b.BranchID = p_BranchID
          AND b.AccParent = 2010201;
SET p_OverallTotal = p_SumDebit - p_SumCredit;
  SELECT
          p_SumDebit,
          p_SumCredit,
          p_OverallTotal;




























































































  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETAGENTTOTAL`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETAGENTTOTAL`(IN `p_BranchID` INT, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_AccID BIGINT;
DECLARE v_ISDeffult bit;


	START TRANSACTION;

SELECT cmt.IsDefault INTO v_ISDeffult FROM CurrencyMainTb cmt WHERE cmt.ID=p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;

	SELECT a.AccID INTO v_AccID FROM
			AccountsTb AS a
	WHERE
			a.AccParent = 2010201
			AND a.BranchID = p_BranchID;
IF v_ISDeffult=1
 THEN
	SELECT
			CASE 					WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 						THEN 						SUM(a.Debit) - SUM(a.Credit) 					ELSE 					0.000 			END AS 'أول',
			CASE 					WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 						THEN 						SUM(a.Credit) - SUM(a.Debit) 					ELSE 					0.000 			END AS 'ثاني'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
	WHERE
			a.AccIDFrom = v_AccID
			AND a.IsActive = 1;
      END IF;

IF v_ISDeffult<>1
 THEN
	SELECT
			CASE 					WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 						THEN 						SUM(a.Credit) - SUM(a.Debit) 					ELSE 					0.000 			END AS 'أول',
			CASE 					WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 						THEN 						SUM(a.Debit) - SUM(a.Credit) 					ELSE 					0.000 			END AS 'ثاني'
	FROM
			ExSyAccountsCurrency_AccSafeActivityTb  AS a
	WHERE
			a.AccIDFrom = v_AccID
			AND a.IsActive = 1
      AND A.CurrencyID=p_CurrencyID;
      END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETBBranchMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETBBranchMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT)
BEGIN
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_IsDefault INT;


	START TRANSACTION;
	SELECT IsDefault INTO v_IsDefault FROM
			CurrencyMainTb AS CMT
			where cmt.ID= p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

	IF v_IsDefault = 1
		 THEN
			SELECT
					ROW_NUMBER() OVER (
					ORDER BY a.ID ASC)																					   AS '#',
					a.ISID																								   AS 'الرمز',
					a.InsertDate																						   'التاريخ',
					b.CurrencyName																						   'العملة',
					FORMAT(a.Debit, 3)																		   'مدين',
					FORMAT(a.Credit, 3)																		   'دائن',
					FORMAT(`CUSTMOVEMENT_GetNetTotal`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo)*-1, 3) AS 'الرصيد',
					a.MovementType																						   'طبيعة الحركة',
					a.Description																						   AS 'ملاحظات'
			FROM
					ExSyAccounts_AccSafeActivityTb AS a
				LEFT JOIN
					CurrencyTb AS b
						ON a.CurrencyID = b.ID
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate >= p_D1
					AND a.InsertDate <= p_D2

			ORDER BY
					a.ID ASC;

			SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO v_PrievewBalance FROM
					ExSyAccounts_AccSafeActivityTb AS a
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate < p_D1;
			SELECT
					v_PrievewBalance AS PrievewBalance;
		END IF;


	IF v_IsDefault <> 1
		 THEN
			SELECT
					ROW_NUMBER() OVER (
					ORDER BY a.ID ASC)																					   AS '#',
					a.ISID																								   AS 'الرمز',
					a.InsertDate																						   'التاريخ',
					b.CuName																							   'العملة',
					FORMAT(a.Credit, 3)																		   'مدين',
					FORMAT(a.Debit, 3) 																		   'دائن',
					FORMAT(`CUSTMOVEMENT_GetNetTotal`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo)*-1, 3) AS 'الرصيد',
					a.MovementType																						   'طبيعة الحركة',
					a.Description																						   AS 'ملاحظات'
			FROM
					ExSyAccountsCurrency_AccSafeActivityTb AS a
				LEFT JOIN
					CurrencyMainTb AS b
						ON a.CurrencyID = b.ID
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate >= p_D1
					AND a.InsertDate <= p_D2
					AND a.CurrencyID = p_CurrencyTo
			ORDER BY
					a.ID ASC;

			SELECT IFNULL(SUM(a.Debit)-SUM(a.Credit)  , 0.000) INTO v_PrievewBalance FROM
					ExSyAccountsCurrency_AccSafeActivityTb AS a
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate < p_D1
					AND a.CurrencyID = p_CurrencyTo;
			SELECT
					v_PrievewBalance AS PrievewBalance;


		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GetBenefits`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GetBenefits`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_OverAllNetTotalFinal` DECIMAL(15,3))
BEGIN
DECLARE v_MainBr INT;
DECLARE v_OutcomeProfit DECIMAL(15, 3);
DECLARE v_IncomeProfit DECIMAL(15, 3);
DECLARE v_SumCredit				DECIMAL(12, 3);
DECLARE v_OverAllNetTotal		DECIMAL(12, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3);
START TRANSACTION;


	SELECT a.ID INTO v_MainBr FROM
			CoBranch AS a
	WHERE
			a.IsMain = 1;
	SELECT
			a.ID,
			a.ISID		 AS 'الرمز',
			a.InsertDate AS 'التاريخ',
			b.AccName	 AS 'اسم الحساب',
			a.Credit	 AS 'القيمة'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND a.AccBranchID = p_BranchID
			AND (   a.CurrencyID = p_CurrencyID
					OR a.CurrencyID = 13)
			AND (   a.OperationTypeID = 22
					OR a.OperationTypeID = 21
					OR a.OperationTypeID = 29
					OR a.OperationTypeID = 31
					OR a.OperationTypeID = 30
					OR a.OperationTypeID = 13)
	ORDER BY
			a.InsertDate asc;
	SELECT SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
			ExSyAccounts_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND a.AccBranchID = p_BranchID
			AND (   a.CurrencyID = p_CurrencyID
					OR a.CurrencyID = 13)
		AND (   a.OperationTypeID = 22
					OR a.OperationTypeID = 21
					OR a.OperationTypeID = 29
					OR a.OperationTypeID = 31
					OR a.OperationTypeID = 30
					OR a.OperationTypeID = 13);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETByEXPENSE`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETByEXPENSE`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

SELECT

                    A.ISID    AS                      'الرمز',
					A.Debit as 'مدين',
                    A.Credit as 'دائن',

                    A.InsertDate as 'التاريخ',
					A.MovementType as 'طبيعة الحركة',
                    A.Note as 'ملاحظات'
            FROM
                    ExSyAccounts_AccSafeActivityTb AS A
                INNER JOIN
                  PCSettlementDetailsTB AS e
                    ON A.AccIDFrom = e.AccIDEX
                INNER JOIN
                  AccountsTb AS B
                    ON A.AccIDFrom = B.AccID



            WHERE
                    A.AccBranchID = p_BranchID
                    AND A.InsertDate BETWEEN p_D1 AND p_D2
                    AND A.IsActive = 1
                    AND e.IsActive = 1
                    AND A.CurrencyID = 1
					AND a.AccIDFrom=p_AccID
                    UNION
                      SELECT
                      A.ISID    AS                      'الرمز',
					  A.Debit as 'مدين',
                    A.Credit as 'دائن',

                    A.InsertDate as 'التاريخ',
					A.MovementType as 'طبيعة الحركة',
                    A.Note as 'ملاحظات'

            FROM
                    ExSyAccounts_AccSafeActivityTb AS A



                INNER JOIN
                  .AccountsTb AS B
                    ON A.AccIDFrom = B.AccID
            WHERE
                    A.AccBranchID = p_BranchID
                    AND A.InsertDate BETWEEN p_D1 AND p_D2
                    AND A.IsActive = 1
                    AND A.CurrencyID = 1
					AND a.AccIDFrom=p_AccID;
































COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETCUSTMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETCUSTMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT, IN `p_Type` TINYINT UNSIGNED)
BEGIN
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_IsDefault INT;


  START TRANSACTION;
  SELECT IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

  IF p_Type = 0
     THEN
      IF v_IsDefault = 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                                            AS '#',
                  a.ISID                                                                                                                        AS 'الرمز',
                  a.InsertDate                                                                                                                  'التاريخ',
                  b.CurrencyName                                                                                                                'العملة',
                  FORMAT(a.Debit, 3)                                                                                                'مدين',
                  FORMAT(a.Credit, 3)                                                                                               'دائن',
                  FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                                                'طبيعة الحركة',
                  a.Note                                                                                                                 AS 'ملاحظات'
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2

          ORDER BY
                  a.ID ASC;

          SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccounts_AccSafeActivityTb AS a
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate < p_D1;
          SELECT
                  v_PrievewBalance AS PrievewBalance;
        END IF;


      IF v_IsDefault <> 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                                            AS '#',
                  a.ISID                                                                                                                        AS 'الرمز',
                  a.InsertDate                                                                                                                  'التاريخ',
                  b.CuName                                                                                                                      'العملة',
                  FORMAT(a.Credit, 3)                                                                                               'مدين',
                  FORMAT(a.Debit, 3)                                                                                                'دائن',
