DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETEMPMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETEMPMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT, IN `p_Type` TINYINT UNSIGNED)
BEGIN
DECLARE v_IsDefault BIT;


  START TRANSACTION;
  SELECT CMT.IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          CMT.ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;


if p_Type=0
 THEN
  IF v_IsDefault = 1
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.ID ASC)                                                                               AS '#',
              a.ISID                                                                                           AS 'الرمز',
              a.INSERTDATE                                                                                     AS 'التاريخ',
              CASE                       WHEN a.CurrencyID = 13                         THEN                         'الدينار الليبي'                       ELSE                       b.CuName               END                                                                                              AS 'العملة',
              FORMAT(a.Debit, 3)                                                                   AS 'مدين',
              FORMAT(a.Credit, 3)                                                                  AS 'دائن',
              FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo,p_Type), 3) AS 'الرصيد',
              a.MovementType                                                                                   AS 'طبيعة الحركة',
              a.Note                                                                                           AS 'ملاحظات'
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          LEFT OUTER JOIN
            CurrencyMainTb AS b
              ON a.CurrencyID = b.ID

      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.INSERTDATE >= p_D1
              AND a.INSERTDATE <= p_D2
              AND   a.CurrencyID = p_CurrencyTo
