DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETEMPMOVEMENTNETTOTAL`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETEMPMOVEMENTNETTOTAL`(IN `p_AccID` BIGINT, IN `p_CurrencyTo` INT, IN `p_Type` TINYINT UNSIGNED)
BEGIN
DECLARE v_IsDefault INT;


START TRANSACTION;
SELECT IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
where cmt.ID=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;


if p_Type=0
 THEN
IF v_IsDefault=1
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'أول',
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN FORMAT(SUM( a.Credit )-SUM( a.Debit ), 3)                 ELSE '0.000'        END AS 'ثاني'
FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
	   AND( a.CurrencyID=p_CurrencyTo or a.CurrencyID=13 );
END IF;

IF v_IsDefault=0
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'ثاني' ,
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN SUM( a.Credit )-SUM( a.Debit )                 ELSE '0.000'        END AS  'أول'
FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
      AND a.CurrencyID=p_CurrencyTo;
END IF;
END IF;


if p_Type=1
 THEN
IF v_IsDefault=1
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'أول',
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN FORMAT(SUM( a.Credit )-SUM( a.Debit ), 3)                 ELSE '0.000'        END AS 'ثاني'
FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
	   AND( a.CurrencyID=p_CurrencyTo or a.CurrencyID=13 )
	   AND a.IsBank=0;
END IF;

IF v_IsDefault=0
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'ثاني' ,
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN SUM( a.Credit )-SUM( a.Debit )                 ELSE '0.000'        END AS  'أول'
FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
      AND a.CurrencyID=p_CurrencyTo;
END IF;
END IF;


if p_Type=2
 THEN
IF v_IsDefault=1
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'أول',
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN FORMAT(SUM( a.Credit )-SUM( a.Debit ), 3)                 ELSE '0.000'        END AS 'ثاني'
FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
	   AND( a.CurrencyID=p_CurrencyTo or a.CurrencyID=13 )
	   AND a.IsBank=1;
END IF;

IF v_IsDefault=0
 THEN
SELECT CASE                 WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit )                 THEN FORMAT(SUM( a.Debit )-SUM( a.Credit ), 3)                 ELSE '0.000'        END AS 'ثاني' ,
       CASE                 WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit )                 THEN SUM( a.Credit )-SUM( a.Debit )                 ELSE '0.000'        END AS  'أول'
FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
WHERE a.AccIDFrom=p_AccID
      AND a.IsActive=1
      AND a.CurrencyID=p_CurrencyTo;
END IF;
END IF;
COMMIT;
END //
DELIMITER ;

