							'رصيد سابق' AS 'الرمز',
							''			AS 'التاريخ',
							CASE 									WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 										THEN 										FORMAT(SUM(a.Debit) - SUM(a.Credit), 3) 									ELSE 									'0.000' 							END			AS 'مدين',
							CASE 									WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 										THEN 										FORMAT(SUM(a.Credit) - SUM(a.Debit), 3) 									ELSE 									'0.000' 							END			AS 'دائن',
							''			AS 'الرصيد',
							''			AS 'طبيعة الحركة',
							''			AS 'ملاحظات'
					FROM
							ExSyAccounts_AccSafeActivityTb AS a
					WHERE
							a.AccIDFrom = p_AccID
							AND a.InsertDate < p_D1
							AND a.IsActive = 1
							AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
							AND a.IsBank=1;
				END IF;

		END IF;


	IF v_IsDefault = 0
		 THEN

			IF p_IsValIn = 0
				 THEN
					SELECT
							''  AS '#',
							''  AS 'الرمز',
							''  AS 'التاريخ',
							CASE 									WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 										THEN 										FORMAT(SUM(a.Debit) - SUM(a.Credit), 3) 									ELSE 									'0.000' 							END AS 'دائن',
							CASE 									WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 										THEN 										FORMAT(SUM(a.Credit) - SUM(a.Debit), 3) 									ELSE 									'0.000' 							END AS 'مدين',
							''  AS 'الرصيد',
							''  AS 'طبيعة الحركة',
							''  AS 'ملاحظات'
					FROM
							ExSyAccountsCurrency_AccSafeActivityTb AS a
					WHERE
							a.AccIDFrom = p_AccID
							AND a.InsertDate < p_D1
							AND a.IsActive = 1
							AND a.CurrencyID = p_CurrencyTo;
				END IF;

			IF p_IsValIn = 1
				 THEN
					SELECT
							''			AS '#',
							'رصيد سابق' AS 'الرمز',
							''			AS 'التاريخ',
							CASE 									WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 										THEN 										FORMAT(SUM(a.Debit) - SUM(a.Credit), 3) 									ELSE 									'0.000' 							END			AS 'دائن',
							CASE 									WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 										THEN 										FORMAT(SUM(a.Credit) - SUM(a.Debit), 3) 									ELSE 									'0.000' 							END			AS 'مدين',
							''			AS 'الرصيد',
							''			AS 'طبيعة الحركة',
							''			AS 'ملاحظات'
					FROM
							ExSyAccountsCurrency_AccSafeActivityTb AS a
					WHERE
							a.AccIDFrom = p_AccID
							AND a.InsertDate < p_D1
							AND a.IsActive = 1
							AND a.CurrencyID = p_CurrencyTo;
				END IF;

		END IF;

END IF;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GetEmpSalary`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GetEmpSalary`(IN `p_DateFrom` DATE, IN `p_DateTo` DATE)
BEGIN
DECLARE v_OverAllTotal decimal(15,3);


     START TRANSACTION;
     SELECT row_number() over(ORDER BY	b.AccName) AS '#',
		  a.ISID AS 'الرمز',
            a.InsertDate AS 'التاريخ',
            b.AccName AS 'اسم الموظف',
            d.BName AS 'الفرع',
            a.Credit AS 'القيمة',
            a.MovementType AS 'ملاحظات'

     FROM `ExSyAccounts`.AccSafeActivityTb AS a
          RIGHT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          RIGHT JOIN EmployeeTb AS c ON b.AccName = c.EMPNAME
          RIGHT JOIN CoBranch AS d ON b.BranchID = d.ID
     WHERE a.InsertDate between CAST(p_DateFrom AS DATE) AND CAST(p_DateTo AS DATE)
	order by c.EMPNAME;
     COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETEXPENSE`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETEXPENSE`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
SELECT
 x.ACCCODE      AS 'الرمز',
          x.InsertDate   'التاريخ',
          x.AccName      AS 'اسم الحساب',
          x.Debit        AS 'مدين',
          x.Credit       AS 'دائن',
          x.MovementType AS 'طبيعة الحركة',
          x.Note         AS 'ملاحظات'
          From(
                      SELECT
                    B.AccName,
                    A.ISID                                                                                         AS ACCCODE,
                    A.Credit,
                    A.Debit,
                    A.InsertDate,
                    A.Note,
                    A.MovementType
            FROM
                    ExSyAccounts_AccSafeActivityTb AS A
                INNER JOIN
                  AccountsTb AS B
                    ON A.AccIDFrom = B.AccID
            WHERE
                    A.AccBranchID = p_BranchID
                    AND A.InsertDate BETWEEN p_D1 AND p_D2
                    AND A.IsActive = 1
                    AND A.CurrencyID = 1
                    AND B.AccParent LIKE '301010%') AS x
ORDER BY x.InsertDate;












  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETPartnerMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETPartnerMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT)
BEGIN
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_IsDefault INT;


	START TRANSACTION;
	SELECT IsDefault INTO v_IsDefault FROM
			CurrencyMainTb AS CMT
			where cmt.ID= p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;


	IF v_IsDefault = 1
		 THEN
			SELECT
					ROW_NUMBER() OVER (
					ORDER BY a.ID ASC)																					   AS '#',
					a.ISID																								   AS 'الرمز',
					DATE_FORMAT(a.InsertDate, '%d/%m/%Y')																						   'التاريخ',
					b.CurrencyName																						   'العملة',
					FORMAT(a.Debit, 3)																		   'مدين',
					FORMAT(a.Credit, 3)																		   'دائن',
					FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo,0), 3) AS 'الرصيد',
					a.MovementType																						   'طبيعة الحركة',
					a.Description																						   AS 'ملاحظات'
			FROM
					ExSyAccounts_AccSafeActivityTb AS a
				LEFT JOIN
					CurrencyTb AS b
						ON a.CurrencyID = b.ID
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate >= p_D1
					AND a.InsertDate <= p_D2

			ORDER BY
					a.ID ASC;

			SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO v_PrievewBalance FROM
					ExSyAccounts_AccSafeActivityTb AS a
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate < p_D1;
			SELECT
					v_PrievewBalance AS PrievewBalance;
		END IF;

	IF v_IsDefault <> 1
		 THEN
			SELECT
					ROW_NUMBER() OVER (
					ORDER BY a.ID ASC)																					   AS '#',
					a.ISID																								   AS 'الرمز',
					DATE_FORMAT(a.InsertDate, '%d/%m/%Y')																						   'التاريخ',
					b.CuName																							   'العملة',
					FORMAT(a.Credit, 3)																		   'مدين',
					FORMAT(a.Debit, 3) 																		   'دائن',
					FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo,0), 3) AS 'الرصيد',
					a.MovementType																						   'طبيعة الحركة',
					a.Description																						   AS 'ملاحظات'
			FROM
					ExSyAccountsCurrency_AccSafeActivityTb_Inert AS a
				LEFT JOIN
					CurrencyMainTb AS b
						ON a.CurrencyID = b.ID
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate >= p_D1
					AND a.InsertDate <= p_D2
					AND a.CurrencyID = p_CurrencyTo
			ORDER BY
					a.ID ASC;

			SELECT IFNULL(SUM(a.Debit)-SUM(a.Credit)  , 0.000) INTO v_PrievewBalance FROM
					ExSyAccountsCurrency_AccSafeActivityTb_Inert AS a
			WHERE
					a.AccIDFrom = p_AccID
					AND a.IsActive = 1
					AND a.InsertDate < p_D1
					AND a.CurrencyID = p_CurrencyTo;
			SELECT
					v_PrievewBalance AS PrievewBalance;


		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETPartnerMOVEMENTNETTOTAL`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETPartnerMOVEMENTNETTOTAL`(IN `p_AccID` BIGINT, IN `p_CurrencyTo` INT)
BEGIN
DECLARE v_IsDefault INT;


START TRANSACTION;
SELECT IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
where cmt.ID=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;



IF v_IsDefault=1
 THEN

	SELECT CASE 					WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 					THEN SUM( a.Debit )-SUM( a.Credit ) 					ELSE '0.000' 		   END AS 'أول',
		   CASE 					WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 					THEN SUM( a.Credit )-SUM( a.Debit ) 					ELSE '0.000' 		   END AS 'ثاني'
	FROM ExSyAccounts_AccSafeActivityTb AS a
	WHERE a.AccIDFrom=p_AccID
		  AND a.IsActive=1;
END IF;

IF v_IsDefault=0
 THEN

	SELECT CASE 					WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 					THEN SUM( a.Debit )-SUM( a.Credit ) 					ELSE '0.000' 		   END AS 'ثاني' ,
		   CASE 					WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 					THEN SUM( a.Credit )-SUM( a.Debit ) 					ELSE '0.000' 		   END AS 'أول'
	FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
	WHERE a.AccIDFrom=p_AccID
		  AND a.IsActive=1
		  AND a.CurrencyID=p_CurrencyTo;
END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETPCEMPID`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETPCEMPID`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_IsSettlement` INT)
BEGIN
START TRANSACTION;
IF p_IsSettlement=1
 THEN
	SELECT a.ISID AS 'الرمز',
		   a.InsertDate 'التاريخ',
		   D.AccName 'العهدة',
		   a.Debit 'مدين',
		   a.Credit 'دائن',
		   a.MovementType 'طبيعة الحركة',
		    Case When A.Note =''  Then 'لا يوجد' else A.Note END  AS 'ملاحظات'
	FROM ExSyAccounts_AccSafeActivityTb AS a



INNER JOIN
PCSettlementTB AS C
ON a.AccIDFrom=C.AccIDPC
INNER JOIN
AccountsTb AS D
ON C.AccIDPC=D.AccID
INNER JOIN
PettyCashTb AS E
ON c.ISID=E.Code
	WHERE c.BranchID=p_BranchID
		  AND a.IsActive=1
		  AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
		  AND a.TypeID=14
		  AND E.IsSettlement=1
	GROUP BY a.ISID,
			 a.InsertDate,
			 D.AccName,
			 a.Debit,
			 a.Credit,
			 a.Note,
			 a.MovementType;
END IF;

IF p_IsSettlement=0
 THEN
	 SELECT  a.Code AS 'الرمز',
		   a.InsertDate 'التاريخ',
		   f.EMPNAME as 'الموظف',
		   a.PettyCashVal 'مدين',
		   0.000 AS 'دائن',
		   B.MovementType 'طبيعة الحركة',
		    Case When A.Notes =''  Then 'لا يوجد' else A.Notes END  AS 'ملاحظات'
	 FROM PettyCashTb AS a
	inner join ExSyAccounts_AccSafeActivityTb as b
	on a.Code=B.ISID
INNER JOIN `EmployeeTb` as f
on A.EMPID=f.ID
	WHERE A.BranchID=p_BranchID
		  AND a.IsActive=1
		  AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
		  AND A.IsSettlement=0
	GROUP BY a.Code,
			 a.InsertDate,
			 f.EMPNAME,
			 a.PettyCashVal,
			 a.NoteS,
			 B.MovementType
	ORDER BY a.InsertDate ASC;
END IF;








































































COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETPCEMPIDDETAILS`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETPCEMPIDDETAILS`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_ISID` LONGTEXT)
BEGIN
START TRANSACTION;
SELECT a.ISID AS 'الرمز',
	   a.InsertDate 'التاريخ',
	   D.AccName 'اسم المصروف',
	   a.Debit 'مدين',
	   a.Credit 'دائن',
	   a.Note AS 'ملاحظات',
	   a.MovementType 'طبيعة الحركة'

FROM ExSyAccounts_AccSafeActivityTb AS a
	LEFT JOIN
	CurrencyTb AS b
	ON a.CurrencyID=b.ID
	INNER JOIN
	PCSettlementDetailsTB AS C
	ON a.AccIDFrom=C.AccIDEX
	INNER JOIN
	AccountsTb AS D
	ON c.AccIDEX=d.accid

WHERE a.AccBranchID=1
	  AND a.IsActive=1
	  AND C.IsActive=1
	  AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
	  AND a.ISID=p_ISID
GROUP BY a.ISID,
		 a.InsertDate,
		 D.AccName,
		 a.Debit,
		 a.Credit,
		 a.Note,
		 a.MovementType;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GETPCEMPIDRPT`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GETPCEMPIDRPT`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_IsSettlement` INT)
BEGIN
START TRANSACTION;

IF p_IsSettlement=1
 THEN
	SELECT a.ISID AS 'الرمز',
		   a.InsertDate 'التاريخ',
		   D.AccName,
		   a.Debit 'مدين',
		   a.Credit 'دائن',
		   a.Note AS 'ملاحظات',
		   a.MovementType 'طبيعة الحركة'
	FROM ExSyAccounts_AccSafeActivityTb AS a
LEFT JOIN
CurrencyTb AS b
ON a.CurrencyID=b.ID
LEFT JOIN
PCSettlementTB AS C
ON a.AccIDFrom=C.AccIDPC
LEFT JOIN
AccountsTb AS D
ON C.AccIDPC=D.AccID
LEFT JOIN
PettyCashTb AS E
ON a.AccIDFrom=E.AccIDPetty
	WHERE C.BranchID=p_BranchID
		  AND a.IsActive=1
		  AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
		  AND a.TypeID=14
		  AND E.IsSettlement=1
	GROUP BY a.ISID,
			 a.InsertDate,
			 D.AccName,
			 a.Debit,
			 a.Credit,
			 a.Note,
			 a.MovementType;
END IF;

IF p_IsSettlement=0
 THEN
	SELECT a.ISID AS 'الرمز',
		   a.InsertDate 'التاريخ',
		   D.AccName,
		   a.Debit 'مدين',
		   a.Credit 'دائن',
		   a.Note AS 'ملاحظات',
		   a.MovementType AS 'طبيعة الحركة'
	FROM ExSyAccounts_AccSafeActivityTb AS a
LEFT JOIN
CurrencyTb AS b
ON a.CurrencyID=b.ID
LEFT JOIN
PettyCashTb AS e
ON a.AccIDFrom=e.AccIDPetty
LEFT JOIN
AccountsTb AS D
ON e.AccIDPetty=D.AccID
	WHERE e.BranchID=p_BranchID
		  AND a.IsActive=1
		  AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
		  AND e.IsSettlement=0;
END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_GetSafeVal`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_GetSafeVal`(IN `p_AccIDFrom` INT, IN `p_AccBranchID` INT, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_sumDebit DECIMAL(15, 3);
DECLARE v_sumCredit DECIMAL(15, 3);
DECLARE v_sumWDVal DECIMAL(15, 3);
DECLARE v_NetTotal DECIMAL(30, 3);
DECLARE v_IsDefault bit;
START TRANSACTION;

	SELECT aa.IsDefault INTO v_IsDefault FROM
	CurrencyMainTb as aa
	where aa.ID= p_CurrencyID
 ORDER BY aa.ID DESC LIMIT 1;


	if p_AccIDFrom=0
	 THEN
	if v_IsDefault=1
	 THEN
SELECT IFNULL( SUM( A.Debit ), 0 )-IFNULL( SUM( A.Credit ), 0 ) INTO v_NetTotal FROM ExSyAccounts_AccSafeActivityTb AS A
join AccountsTb as b on a.AccIDFrom=b.AccID
WHERE A.IsActive=1
	  AND b.AccParent=1010101
	  AND A.AccBranchID=p_AccBranchID
	  AND (A.CurrencyID=p_CurrencyID
		   OR A.CurrencyID=13);
SELECT v_NetTotal AS NetTotal;
END IF;





if v_IsDefault=0
 THEN
SELECT IFNULL( SUM( A.Credit ), 0 )-IFNULL( SUM( A.Debit ), 0 ) INTO v_NetTotal FROM ExSyAccountsCurrency_AccSafeActivityTb AS A
join AccountsTb as b on a.AccIDFrom=b.AccID
WHERE A.IsActive=1
	  AND LEFT( b.AccParent, 5 ) = 10102
	  AND A.AccBranchID=p_AccBranchID
	  AND (A.CurrencyID=p_CurrencyID);
	  SELECT v_NetTotal AS NetTotal;
END IF;
END IF;


	if p_AccIDFrom<>0
	 THEN
	if v_IsDefault=1
	 THEN
SELECT IFNULL( SUM( A.Debit ), 0 )-IFNULL( SUM( A.Credit ), 0 ) INTO v_NetTotal FROM ExSyAccounts_AccSafeActivityTb AS A
WHERE A.IsActive=1
	  AND A.AccIDFrom=p_AccIDFrom
	  AND A.AccBranchID=p_AccBranchID
	  AND (A.CurrencyID=p_CurrencyID
		   OR A.CurrencyID=13);
SELECT v_NetTotal AS NetTotal;
END IF;





if v_IsDefault=0
 THEN
SELECT IFNULL( SUM( A.Credit ), 0 )-IFNULL( SUM( A.Debit ), 0 ) INTO v_NetTotal FROM ExSyAccountsCurrency_AccSafeActivityTb AS A
WHERE A.IsActive=1
	  AND A.AccIDFrom=p_AccIDFrom
	  AND A.AccBranchID=p_AccBranchID
	  AND (A.CurrencyID=p_CurrencyID);
	  SELECT v_NetTotal AS NetTotal;
END IF;
END IF;
COMMIT;
END //
DELIMITER ;

