DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_IncreaseValTbInsert`(IN `p_SafeID` INT, IN `p_Debit` DECIMAL(12,3), IN `p_Credit` DECIMAL(12,3), IN `p_InsertDate` DATE, IN `p_Code` TEXT, IN `p_TypeID` TINYINT UNSIGNED, IN `p_OperationTypeID` INT, IN `p_AccBranchID` INT, IN `p_AccIDFrom` INT, IN `p_AccIDTo` INT, IN `p_MovementType` LONGTEXT)
