WHERE ISID=p_Code;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_InsertSalaryCalc`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_InsertSalaryCalc`(IN `p_BranchID` INT, IN `p_SafeID` INT, IN `p_Debit` DECIMAL(12,3), IN `p_InsertDate` DATE, IN `p_CurrencyID` INT, IN `p_EmpID` INT, IN `p_MonthVal` VARCHAR(10), IN `p_YearVal` VARCHAR(20), IN `p_ISID` LONGTEXT)
BEGIN
DECLARE v_AccSalaryID BIGINT;
DECLARE v_AccEmpID INT;
DECLARE v_EmName VARCHAR(50);
DECLARE v_MovementType LONGTEXT;
DECLARE v_OpType INT;


START TRANSACTION;

SELECT a.AccID INTO v_AccSalaryID FROM AccountsTb AS a
WHERE a.AccParent=30101010
	  AND a.BranchID=p_BranchID;

SELECT a.AccID INTO v_AccEmpID FROM AccountsTb AS a
	INNER JOIN
	EmployeeTb AS b
	ON a.AccName=b.EMPNAME
WHERE a.BranchID=p_BranchID
	  AND b.ID=p_EmpID;

SELECT a.EMPNAME INTO v_EmName FROM EmployeeTb AS a
WHERE a.ID=p_EmpID;

SELECT a.OpNum INTO v_OpType FROM OperationTypeTb AS a
WHERE a.OperationType='احتساب مرتب';
SET v_MovementType=CONCAT('مرتب', ' ', 'عن ش', ' ', p_MonthVal, ' ', 'س', ' ', p_YearVal);
INSERT INTO `ExSyAccounts`.AccSafeActivityTb
(

 SafeID,
 Debit,
 Credit,
 InsertDate,
 ISID,
 ISACTIVE,
 TypeID,
 OperationTypeID,
 AccBranchID,
 AccIDFrom,
 AccIDTo,
 IsConfirmed,
 IsCanceled,
 MovementType,
 CurrencyID,
 DailyClosed,
 SafeIDDailyClose)
VALUES
(

  p_SafeID,
  p_Debit,
  0.000,
  p_InsertDate,
  p_ISID,
  1,
  36,
  36,
  p_BranchID,
  v_AccSalaryID,
  v_AccEmpID,
  1,
  0,
