DROP PROCEDURE IF EXISTS `AccSafeActivityTb_Select`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_Select`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
        SELECT
            ROW_NUMBER () OVER (ORDER BY a.ISID ASC) AS '#',
			a.ISID AS 'رمز الحوالة',
            b.AccName AS 'اسم الحساب',
            a.InsertDate AS 'التاريخ',
            a.Debit AS 'مدين',
            a.Credit AS 'دائن',
            a.MovementType AS 'طبيعة الحركة',
            c.UName AS 'اسم الموظف'
        FROM
            ExSyAccounts_AccSafeActivityTb AS a
            INNER JOIN
            AccountsTb AS b
            ON a.AccIDFrom = b.AccID
            INNER JOIN
            TB_Users AS c
            ON a.SafeID = c.USID
        WHERE
            a.IsActive = 1 AND
            b.AccActive = 1 AND
            a.AccBranchID = p_BranchID AND
            a.InsertDate >= p_D1 AND
            a.insertdate <= p_D2;
        COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectAccountsBetweenBranches`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectAccountsBetweenBranches`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_CurrentAccID BIGINT;


START TRANSACTION;
SELECT at.AccID INTO v_CurrentAccID FROM AccountsTb at
WHERE at.BranchID=p_BranchID
	  AND at.AccParent=2010201;

SELECT d.ID,
	   ROW_NUMBER( ) OVER (ORDER BY b.AccName ASC) AS '#',
	   b.AccName AS 'اسم الحساب',
	   CASE 				WHEN SUM( a.Debit )>SUM( a.Credit ) 				THEN FORMAT(SUM( a.Credit )-SUM( a.Debit ), 3) 				ELSE FORMAT((0.000), 3) 	   END AS 'مدين (له)',
	   CASE 				WHEN SUM( a.Credit )>SUM( a.Debit ) 				THEN FORMAT(SUM( a.Credit )-SUM( a.Debit ), 3) 				ELSE FORMAT((0.000), 3) 	   END AS 'دائن (عليه)'
FROM ExSyAccounts_AccSafeActivityTb AS a
	INNER JOIN
AccountsTb AS b
	ON a.AccIDFrom=b.AccID
	INNER JOIN
	CoBranch AS d
	ON b.BranchID=d.ID
WHERE a.ISACTIVE=1
	  AND b.AccActive=1
	  AND a.InsertDate>=p_D1
	  AND a.InsertDate<=p_D2
	  AND a.AccBranchID=p_BranchID
	  AND b.AccParent=2010201
GROUP BY b.AccName,
		 d.ID
ORDER BY b.AccName ASC;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectBankServices`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectBankServices`(IN `p_BranchID` INT, IN `p_BBranchID` INT, IN `p_ServiceID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY c.ID ASC)     AS '#',
          c.ISID                                    AS 'الرمز',
          c.InsertDate                              AS 'التاريخ',
          FORMAT(c.Debit, 4)            AS 'مدين',
          FORMAT(d.Credit, 4)           AS 'دائن',
          FORMAT(c.Debit - d.Credit, 3) AS 'الإجمالي'
  FROM
          BBranchTb AS a
      INNER JOIN
        BankServicesTb AS b
          ON a.ID = b.BBranchID
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb AS c
          ON a.AccID = c.AccIDFrom
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb AS d
          ON a.AccIDBBranchAllowance = d.AccIDFrom
  WHERE
          a.AccountType = 1
          AND c.AccBranchID = p_BranchID
          AND a.ID = p_BBranchID
          AND b.ID = p_ServiceID
          AND c.InsertDate >= p_D1
          AND c.InsertDate <= p_D2
		  AND c.ISID=d.ISID
  GROUP BY
          a.BranchName,
          c.ISID,
          c.InsertDate,
          c.Debit,
          d.Credit,
          c.ID
  ORDER BY
          c.ID;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByAgent`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByAgent`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(18,3), INOUT `p_SumCreditFinal` DECIMAL(18,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(18,3), IN `p_CurrencyID` INT)
BEGIN
DECLARE v_BranchType INT;
DECLARE v_SumDebit				DECIMAL(18, 3);
DECLARE v_SumCredit				DECIMAL(18, 3);
DECLARE v_OverAllNetTotal		DECIMAL(18, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(18, 3);
DECLARE v_AccID BIGINT;
DECLARE v_isDeffCurr BIT;


	START TRANSACTION;
	SELECT a.AccID INTO v_AccID FROM
			AccountsTb AS a
	WHERE
			a.AccParent = 2010201
			AND a.BranchID = p_BranchID;
SELECT cmt.IsDefault INTO v_isDeffCurr FROM CurrencyMainTb cmt WHERE cmt.id=p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;
IF v_isDeffCurr=1
 THEN
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ASC)												 AS '#',
			a.ISID																				 AS 'رمز الحوالة',
			a.InsertDate																		 AS 'التاريخ',
			FORMAT(a.Debit, 3)														 AS 'مدين',
			FORMAT(a.Credit, 3)														 AS 'دائن',
			FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyID,0), 3) AS 'الصافي',
			case when a.MovementType='' then a.SafeIDMovement else a.MovementType END 																	 AS 'طبيعة الحركة',
			case when a.Description<>'' Then a.Description When a.Description='' AND a.Note<>'' Then a.Note Else 'لايوجد' END							 AS 'ملاحظات'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND a.AccIDFrom = v_AccID
	ORDER BY
			a.ID ASC;
	SELECT SUM(a.Debit) INTO v_SumDebit FROM
			ExSyAccounts_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS c
				ON a.AccIDFrom = c.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND c.BranchID = p_BranchID;

	SELECT SUM(a.Credit) INTO v_SumCredit FROM
			ExSyAccounts_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS c
				ON a.AccIDFrom = c.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND c.BranchID = p_BranchID;
END IF;

IF v_isDeffCurr<>1
 THEN
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ASC)												 AS '#',
			a.ISID																				 AS 'رمز الحوالة',
			a.InsertDate																		 AS 'التاريخ',
				FORMAT(a.Credit, 3)														 AS 'مدين',
			FORMAT(a.Debit, 3)													 AS 'دائن',
			FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyID,0), 3) AS 'الصافي',
			case when a.MovementType='' then a.SafeIDMovement else a.MovementType END 																	 AS 'طبيعة الحركة',
			case when a.Description<>'' Then a.Description When a.Description='' AND a.Note<>'' Then a.Note Else 'لايوجد' END							 AS 'ملاحظات'
	FROM
			ExSyAccountsCurrency_AccSafeActivityTb  AS a
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND a.AccIDFrom = v_AccID
      AND a.CurrencyID=p_CurrencyID
	ORDER BY
			a.ID ASC;
	SELECT SUM(a.Debit) INTO v_SumDebit FROM
			ExSyAccountsCurrency_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS c
				ON a.AccIDFrom = c.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND c.BranchID = p_BranchID;

	SELECT SUM(a.Credit) INTO v_SumCredit FROM
			ExSyAccountsCurrency_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS c
				ON a.AccIDFrom = c.AccID
	WHERE
			a.IsActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND c.BranchID = p_BranchID;
END IF;

	SET p_SumDebitFinal = v_SumDebit;


	SET p_SumCreditFinal = v_SumCredit;
	IF p_SumDebitFinal > p_SumCreditFinal
		 THEN
			SET p_OverAllNetTotalFinal = p_SumDebitFinal - p_SumCreditFinal;
		END IF;
	IF p_SumCreditFinal > p_SumDebitFinal
		 THEN
			SET p_OverAllNetTotalFinal = p_SumCreditFinal - p_SumDebitFinal;
		END IF;
	SELECT
			p_SumDebitFinal,
			p_SumCreditFinal,
			p_OverAllNetTotalFinal;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByBankEmSafe`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByBankEmSafe`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault              BIT;


    START TRANSACTION;
    SELECT CMT.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS CMT
    WHERE
            CMT.ID = p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;

			SELECT USID INTO v_AccFrom FROM TB_Users Where accid=p_SafeID
 ORDER BY TB_Users.USID DESC LIMIT 1;

    IF v_IsDefault = 1
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.id ASC)                                                                          AS '#',
                a.ISID                                                                                              AS 'الكود',
                a.InsertDate                                                                                        AS 'التاريخ',
                FORMAT(a.Debit, 3)                                                                      AS 'مدين',
                FORMAT(a.Credit, 3)                                                                     AS 'دائن',

                a.MovementType                                                                                    AS 'طبيعة الحركة'
        FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE

                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND a.IsBank=1
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID
        ORDER BY
                a.ID ASC;



      END IF;



    IF v_IsDefault = 0
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.InsertDate ASC)                                                                          AS '#',
                a.ISID                                                                                              AS 'الكود',
                a.InsertDate                                                                                        AS 'التاريخ',
                FORMAT(a.Debit, 3)                                                                      AS 'دائن',
                FORMAT(a.Credit, 3)                                                                     AS 'مدين',

                a.SafeIDMovement                                                                                    AS 'طبيعة الحركة'
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND (a.TypeID between 15 and 18)
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID
        ORDER BY
                a.InsertDate ASC;
        END IF;
		END;

	COMMIT //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByBankSerivecsEmSafe`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByBankSerivecsEmSafe`(IN `p_BankService` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault BIT;
DECLARE v_PreviousBalance DECIMAL(18, 3) DEFAULT 0;


    START TRANSACTION;


    SELECT CMT.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS CMT
    WHERE
            CMT.ID = p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;

    SELECT USID INTO v_AccFrom FROM
            TB_Users
    WHERE
            accid = p_SafeID
 ORDER BY TB_Users.USID DESC LIMIT 1;

    IF v_IsDefault = 1
       THEN


        SELECT SUM(IFNULL(a.Debit, 0)) - SUM(IFNULL(a.Credit, 0)) INTO v_PreviousBalance FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.ID
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND c.ID = p_BankService
                AND a.SafeID <> v_AccFrom
                AND a.InsertDate BETWEEN p_D1 AND p_D2;


        SELECT
                *
        FROM
                (   SELECT
                            0 AS `#`,
                            NULL AS `الكود`,
                            p_D1 AS `التاريخ`,
                            N'رصيد سابق' AS `اسم الحساب`,
                            CASE                                     WHEN v_PreviousBalance > 0                                       THEN                                       FORMAT(v_PreviousBalance, 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `مدين`,
                            CASE                                     WHEN v_PreviousBalance < 0                                       THEN                                       FORMAT(ABS(v_PreviousBalance ) * -1, 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `دائن`,
                            FORMAT(v_PreviousBalance, 3) AS `الصافي`,
                            N'رصيد سابق' AS `طبيعة الحركة`) AS OpeningRow


        UNION ALL

        SELECT
                ROW_NUMBER() OVER (ORDER BY a.ID ASC) + 1                                                                     AS `#`,
                a.ISID                                                                                                        AS `الكود`,
                a.InsertDate                                                                                                  AS `التاريخ`,
                b.BranchName                                                                                                  AS `اسم الحساب`,
                FORMAT(a.Debit, 3)                                                                                AS `مدين`,
                FORMAT(a.Credit, 3)                                                                               AS `دائن`,
                FORMAT(`SafeIDBankServices_GetNetTotal`(v_AccFrom, p_BankService, p_CurrencyID, a.ID) * -1, 3) AS `الصافي`,
                a.SafeIDMovement                                                                                              AS `طبيعة الحركة`
        FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.ID
                LEFT JOIN
                InternalEx ie
                ON a.ISID=ie.Code AND c.ID=ie.ServiceType
                LEFT JOIN
                ExternalEx ee
                ON a.ISID=ee.Code AND c.ID=ee.BankServiceType
        WHERE

                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND c.ID = p_BankService
                AND a.InsertDate BETWEEN p_D1 AND p_D2
                AND (ie.ServiceType=p_BankService OR ee.BankServiceType=p_BankService);





       ELSEIF  v_IsDefault = 0
       THEN



        SELECT SUM(IFNULL(a.Debit, 0)) - SUM(IFNULL(a.Credit, 0)) INTO v_PreviousBalance FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.ID
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND c.ID = p_BankService
                AND a.SafeID <> v_AccFrom
                AND a.InsertDate BETWEEN p_D1 AND p_D2;

        SELECT
                *
        FROM
                (   SELECT
                            0 AS `#`,
                            NULL AS `الكود`,
                            p_D1 AS `التاريخ`,
                            CASE                                     WHEN v_PreviousBalance > 0                                       THEN                                       FORMAT(v_PreviousBalance, 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `مدين`,
                            CASE                                     WHEN v_PreviousBalance < 0                                       THEN                                       FORMAT(ABS(v_PreviousBalance), 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `دائن`,
                            FORMAT(v_PreviousBalance * -1, 3) AS `الصافي`,
                            N'رصيد سابق' AS `طبيعة الحركة`,
                            N'رصيد سابق' AS `اسم الحساب`) AS OpeningRow

        UNION ALL

        SELECT
                ROW_NUMBER() OVER (ORDER BY a.ID ASC) + 1                                                                     AS `#`,
                a.ISID                                                                                                        AS `الكود`,
                a.InsertDate                                                                                                  AS `التاريخ`,
                b.BranchName                                                                                                  AS `اسم الحساب`,
                FORMAT(a.Debit, 3)                                                                                AS `مدين`,
                FORMAT(a.Credit, 3)                                                                               AS `دائن`,
                FORMAT(`SafeIDBankServices_GetNetTotal`(v_AccFrom, p_BankService, p_CurrencyID, a.ID) * -1, 3) AS `الصافي`,
                a.SafeIDMovement                                                                                              AS `طبيعة الحركة`
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.ID
        WHERE

                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND c.ID = p_BankService
                AND a.InsertDate BETWEEN p_D1 AND p_D2
        ORDER BY
                `#`;
      END IF;


    COMMIT;

  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByBankSerivecsEmSafe2`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByBankSerivecsEmSafe2`(IN `p_BankService` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
