        ORDER BY
                `#`;
       ELSEIF  v_IsDefault = 0
       THEN



        SELECT SUM(IFNULL(a.Debit, 0)) - SUM(IFNULL(a.Credit, 0)) INTO v_PreviousBalance FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
