                        OR a.CurrencyID = 13)
                AND c.ID = p_BankService
                AND a.SafeID <> v_AccFrom
                AND a.InsertDate BETWEEN p_D1 AND p_D2;

        SELECT
                *
        FROM
                (   SELECT
                            0 AS `#`,
                            NULL AS `الكود`,
                            p_D1 AS `التاريخ`,
                            CASE                                     WHEN v_PreviousBalance > 0                                       THEN                                       FORMAT(v_PreviousBalance, 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `مدين`,
                            CASE                                     WHEN v_PreviousBalance < 0                                       THEN                                       FORMAT(ABS(v_PreviousBalance), 3)                                     ELSE                                     FORMAT(0, 3)                             END AS `دائن`,
                            FORMAT(v_PreviousBalance * -1, 3) AS `الصافي`,
                            N'رصيد سابق' AS `طبيعة الحركة`,
                            N'رصيد سابق' AS `اسم الحساب`) AS OpeningRow

        UNION ALL

        SELECT
                ROW_NUMBER() OVER (ORDER BY a.ID ASC) + 1                                                                     AS `#`,
                a.ISID                                                                                                        AS `الكود`,
                a.InsertDate                                                                                                  AS `التاريخ`,
                b.BranchName                                                                                                  AS `اسم الحساب`,
                FORMAT(a.Debit, 3)                                                                                AS `مدين`,
                FORMAT(a.Credit, 3)                                                                               AS `دائن`,
                FORMAT(`SafeIDBankServices_GetNetTotal`(v_AccFrom, p_BankService, p_CurrencyID, a.ID) * -1, 3) AS `الصافي`,
                a.SafeIDMovement                                                                                              AS `طبيعة الحركة`
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.ID
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND c.ID = p_BankService
                AND a.InsertDate BETWEEN p_D1 AND p_D2
        ORDER BY
                `#`;
      END IF;

    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByCurEmSafePreviews`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByCurEmSafePreviews`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_D1` DATE, IN `p_ExistVal` TINYINT(1))
BEGIN
DECLARE v_MainBr INT;
DECLARE v_SumDebit				DECIMAL(12, 3);
DECLARE v_SumCredit				DECIMAL(12, 3);
DECLARE v_OverAllNetTotal		DECIMAL(12, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3);
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault				BIT;


		START TRANSACTION;
		SELECT CMT.IsDefault INTO v_IsDefault FROM
				CurrencyMainTb AS CMT
		WHERE
				CMT.id = p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;
		SELECT a.ID INTO v_MainBr FROM
				CoBranch AS a
		WHERE
				a.IsMain = 1;

		IF v_IsDefault = 1
			 THEN

				IF p_ExistVal = 1
					 THEN
						SELECT
								''			AS '#',
								'رصيد سابق' AS 'الكود',
								''			AS 'التاريخ',
								CASE 										WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 											THEN 											SUM(a.Debit) - SUM(a.Credit) 										ELSE 										0.000 								END			AS 'مدين',
								CASE 										WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 											THEN 											SUM(a.Credit) - SUM(a.Debit) 										ELSE 										0.000 								END			AS 'دائن',
								''			AS 'الصافي',
								''			AS 'طبيعة الحركة'
						FROM
								ExSyAccounts_AccSafeActivityTb AS a
						WHERE
								a.IsActive = 1

								AND (   a.CurrencyID = p_CurrencyID
										OR a.CurrencyID = 13)

								AND a.InsertDate < p_D1
								AND a.AccBranchID = p_BranchID;
					END IF;

				IF p_ExistVal = 0
					 THEN
						SELECT
								''			AS '#',
								'رصيد سابق' AS 'الكود',
								''			AS 'التاريخ',
								CASE 										WHEN SUM(a.Debit) - SUM(a.Credit) > SUM(a.Credit) - SUM(a.Debit) 											THEN 											SUM(a.Debit) - SUM(a.Credit) 										ELSE 										0.000 								END			AS 'مدين',
								CASE 										WHEN SUM(a.Credit) - SUM(a.Debit) > SUM(a.Debit) - SUM(a.Credit) 											THEN 											SUM(a.Credit) - SUM(a.Debit) 										ELSE 										0.000 								END			AS 'دائن',
								''			AS 'الصافي',
								''			AS 'طبيعة الحركة'
						FROM
								ExSyAccounts_AccSafeActivityTb AS a
						WHERE
								a.IsActive = 1

								AND (   a.CurrencyID = p_CurrencyID
										OR a.CurrencyID = 13)

								AND a.InsertDate < p_D1
								AND a.AccBranchID = p_BranchID;
					END IF;

			END IF;


		IF v_IsDefault = 0
			 THEN

				IF p_ExistVal = 1
					 THEN
						SELECT
								''			AS '#',
								'رصيد سابق' AS 'الكود',
								''			AS 'التاريخ',
								CASE 										WHEN SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) > SUM(a.ACC_DEPET_TO) - SUM(a.CRedetTO) 											THEN 											SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 										ELSE 										0.000 								END			AS 'مدين',
								CASE 										WHEN SUM(a.ACC_DEPET_TO) - SUM(a.CRedetTO) > SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 											THEN 											SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 										ELSE 										0.000 								END			AS 'دائن',
								''			AS 'الصافي',
								''			AS 'طبيعة الحركة'
						FROM
								ExSyAccountsCurrency_CurrencymovementPruse AS a
						WHERE
								a.IsActive = 1
								AND (a.AccFrom = p_CurrencyID)

								AND a.Inseart_Date < p_D1
								AND a.BID = p_BranchID;
					END IF;

				IF p_ExistVal = 0
					 THEN
						SELECT
								''			AS '#',
								'رصيد سابق' AS 'الكود',
								''			AS 'التاريخ',
								CASE 										WHEN SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) > SUM(a.ACC_DEPET_TO) - SUM(a.CRedetTO) 											THEN 											SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 										ELSE 										0.000 								END			AS 'مدين',
								CASE 										WHEN SUM(a.ACC_DEPET_TO) - SUM(a.CRedetTO) > SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 											THEN 											SUM(a.CRedetTO) - SUM(a.ACC_DEPET_TO) 										ELSE 										0.000 								END			AS 'دائن',
								''			AS 'الصافي',
								''			AS 'طبيعة الحركة'
						FROM
								ExSyAccountsCurrency_CurrencymovementPruse AS a
						WHERE
								a.IsActive = 1
								AND (a.AccFrom = p_CurrencyID)

								AND a.Inseart_Date < p_D1
								AND a.BID = p_BranchID;
					END IF;

			END IF;

		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByEmSafe`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByEmSafe`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(15,3), INOUT `p_SumCreditFinal` DECIMAL(15,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(15,3), INOUT `p_OverAllPeroidTotal` DECIMAL(15,3), INOUT `p_PreviewBalanceTotal` DECIMAL(15,3))
BEGIN
DECLARE v_ABranchID INT;
DECLARE v_ACurrencyID INT;
DECLARE v_ASafeID BIGINT;
DECLARE v_AD1 DATE;
DECLARE v_AD2 DATE;
DECLARE v_OldPreviwovs DECIMAL(18, 3);
DECLARE v_OverAllNetTotal DECIMAL(12, 3);
DECLARE v_SumDebit  DECIMAL(12, 3);
DECLARE v_SumCredit DECIMAL(12, 3);
DECLARE v_IsDefault BIT;


    START TRANSACTION;
    SET v_ABranchID = p_BranchID;
    SET v_ACurrencyID = p_CurrencyID;
    SET v_ASafeID = p_SafeID;
    SET v_AD1 = p_D1;
    SET v_AD2 = p_D2;
    SELECT CMT.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS CMT
    WHERE
            CMT.ID = v_ACurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;


    IF v_IsDefault = 1
       THEN
        SELECT SUM(a.Debit) - SUM(a.Credit) INTO v_OverAllNetTotal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.AccBranchID = v_ABranchID;

        SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0) INTO v_OldPreviwovs FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate < p_D1
                AND a.AccBranchID = p_BranchID;

        SELECT
                ''                                         AS 'SN',
                'الــــرصــــيـــــد الـــــســـــابــــق' AS 'الكود',
                'الــــرصــــيـــــد' AS 'RPTCode',
               'الـــــســـــابــــق' AS 'RPTDate',
                ''                                         AS 'التاريخ',
                ''                                         AS 'مدين',
                ''                                         AS 'دائن',
                v_OldPreviwovs                              AS 'الصافي',
                ''                                         AS 'طبيعة الحركة',
                v_OldPreviwovs                              AS OldPreviwovs,
                v_OverAllNetTotal                           AS OverAllNetTotal
        UNION ALL
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.ID ASC) AS 'SN',

                `الكود`,
                a.الكود AS 'RPTCode',
CAST(`التاريخ` AS CHAR) AS 'RPTDate',
                CAST(`التاريخ` AS CHAR),
                CAST(`مدين` AS CHAR),
                CAST(`دائن` AS CHAR),
                CAST((SUM(`مدين`) OVER (PARTITION BY a.AccIDFrom ORDER BY a.id)
                - SUM(`دائن`) OVER (PARTITION BY a.AccIDFrom ORDER BY a.id)) + v_OldPreviwovs AS CHAR)
                AS 'الصافي',

                a.`طبيعة الحركة`,

                v_OldPreviwovs              AS OldPreviwovs,
                v_OverAllNetTotal           AS OverAllNetTotal
        FROM
                View_AccSafeActiv_SafeLoad AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;




        SELECT SUM(a.Debit) INTO v_SumDebit FROM
                View_AccSafeActiv_SafeLoad AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SELECT SUM(a.Credit) INTO v_SumCredit FROM
                View_AccSafeActiv_SafeLoad AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SET p_SumDebitFinal = v_SumDebit;
        SET p_SumCreditFinal = v_SumCredit;
        SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.AccBranchID = v_ABranchID;
        SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllPeroidTotal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO p_PreviewBalanceTotal FROM
                View_AccSafeActiv_SafeLoad AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = v_ACurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
      END IF;
    IF v_IsDefault = 0
       THEN
        SELECT SUM(a.Credit) - SUM(a.Debit) INTO v_OverAllNetTotal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.AccBranchID = v_ABranchID;
        SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0) INTO v_OldPreviwovs FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate < p_D1
                AND a.AccBranchID = p_BranchID;

        SELECT
                ''                                         AS 'SN',
                'الــــرصــــيـــــد الـــــســـــابــــق' AS 'الكود',
                ''                                         AS 'التاريخ',
                ''                                         AS 'مدين',
                ''                                         AS 'دائن',
                v_OldPreviwovs                              AS 'الصافي',
                ''                                         AS 'طبيعة الحركة',
                v_OldPreviwovs                              AS OldPreviwovs,
                v_OverAllNetTotal                           AS OverAllNetTotal
        UNION ALL

        SELECT
                CAST(ROW_NUMBER() OVER (ORDER BY a.InsertDate ASC) AS CHAR) AS `SN`,
                a.ISID                                                           AS `الكود`,
                CAST(a.InsertDate AS CHAR)                                  AS `التاريخ`,
                CAST(a.Credit AS CHAR)                                      AS `مدين`,
                CAST(a.Debit AS CHAR)                                       AS `دائن`,
                CAST((SUM(a.Credit) OVER (PARTITION BY a.AccIDFrom ORDER BY a.id)
                - SUM(a.Debit) OVER (PARTITION BY a.AccIDFrom ORDER BY a.id)) + v_OldPreviwovs AS CHAR)
                AS 'الصافي',
                a.SafeIDMovement                                                 AS `طبيعة الحركة`,
                v_OldPreviwovs                                                    AS OldPreviwovs,
                v_OverAllNetTotal                                                 AS OverAllNetTotal
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SELECT SUM(a.Credit) INTO v_SumDebit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SELECT SUM(a.Debit) INTO v_SumCredit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SET p_SumDebitFinal = v_SumDebit;
        SET p_SumCreditFinal = v_SumCredit;
        SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllNetTotalFinal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.AccBranchID = v_ABranchID;
        SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllPeroidTotal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate >= v_AD1
                AND a.InsertDate <= v_AD2
                AND a.AccBranchID = v_ABranchID;
        SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO p_PreviewBalanceTotal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = v_ACurrencyID)
                AND a.AccIDFrom = v_ASafeID
                AND a.InsertDate < v_AD1
                AND a.AccBranchID = v_ABranchID;
      END IF;
    SELECT
            p_SumDebitFinal,
            p_SumCreditFinal,
            p_OverAllPeroidTotal,
            p_OverAllNetTotalFinal AS OverAllNetTotalFinal,
            p_PreviewBalanceTotal,
            v_OldPreviwovs         AS OldPreviwovs;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByEmSafeNetTotal`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByEmSafeNetTotal`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT)
BEGIN
DECLARE v_MainBr INT;
DECLARE v_SumDebit				  DECIMAL(12, 3);
DECLARE v_SumCredit			  DECIMAL(12, 3);
DECLARE v_OverAllNetTotal		  DECIMAL(12, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3);
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault			  BIT;


START TRANSACTION;
SELECT CMT.IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
WHERE CMT.id=p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;
SELECT a.AccID INTO v_AccFrom FROM TB_Users AS a
WHERE USID=p_SafeID
 ORDER BY a.USID DESC LIMIT 1;
SELECT a.ID INTO v_MainBr FROM CoBranch AS a
WHERE a.IsMain=1;

IF v_IsDefault=1
 THEN

	SELECT CASE 					WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 					THEN SUM( a.Debit )-SUM( a.Credit ) 					ELSE 0.000 		   END AS 'أول',
		   CASE 					WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 					THEN SUM( a.Credit )-SUM( a.Debit ) 					ELSE 0.000 		   END AS 'ثاني'
	FROM ExSyAccounts_AccSafeActivityTb AS a
INNER JOIN
AccountsTb AS b
ON a.AccIDFrom=b.AccID
	WHERE a.IsActive=1
		  AND b.AccActive=1
		  AND (a.CurrencyID=p_CurrencyID
			   OR a.CurrencyID=13)
		  AND a.AccIDFrom=p_SafeID
		  AND a.AccBranchID=p_BranchID;
END IF;

IF v_IsDefault=0
 THEN

	SELECT CASE 					WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 					THEN SUM( a.Credit )-SUM( a.Debit ) 					ELSE 0.000 		   END AS 'أول',
		   CASE 					WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 					THEN SUM( a.Debit )-SUM( a.Credit ) 					ELSE 0.000 		   END AS 'ثاني'
	FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
INNER JOIN
AccountsTb AS b
ON a.AccIDFrom=b.AccID
	WHERE a.IsActive=1
		  AND b.AccActive=1
		  AND (a.CurrencyID=p_CurrencyID)
		  AND a.AccIDFrom=p_SafeID
		  AND a.AccBranchID=p_BranchID;
END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByEmSafePreviews`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByEmSafePreviews`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_ExistVal` TINYINT(1))
BEGIN
DECLARE v_MainBr INT;
DECLARE v_SumDebit				  DECIMAL(12, 3);
DECLARE v_SumCredit			  DECIMAL(12, 3);
DECLARE v_OverAllNetTotal		  DECIMAL(12, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3);
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault			  BIT;


START TRANSACTION;
SELECT CMT.IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
WHERE CMT.id=p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;
SELECT a.AccID INTO v_AccFrom FROM TB_Users AS a
WHERE USID=p_SafeID
 ORDER BY a.USID DESC LIMIT 1;
SELECT a.ID INTO v_MainBr FROM CoBranch AS a
WHERE a.IsMain=1;

IF v_IsDefault=1
 THEN

	IF p_ExistVal=1
	 THEN
		SELECT '' AS '#',
			   'رصيد سابق' AS 'الكود',
			   '' AS 'التاريخ',
			   CASE 						WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 						THEN SUM( a.Debit )-SUM( a.Credit ) 						ELSE 0.000 			   END AS 'مدين',
			   CASE 						WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'دائن',
			   '' AS 'الصافي',
			   '' AS 'طبيعة الحركة'
		FROM ExSyAccounts_AccSafeActivityTb AS a
	LEFT OUTER JOIN
	AccountsTb AS b
	ON a.AccIDFrom=b.AccID
		WHERE a.IsActive=1
			  AND b.AccActive=1
			  AND (a.CurrencyID=p_CurrencyID
				   OR a.CurrencyID=13)
			  AND a.AccIDFrom=p_SafeID
			  AND a.InsertDate<p_D1
			  AND a.AccBranchID=p_BranchID;
	END IF;

	IF p_ExistVal=0
	 THEN
		SELECT '' AS '#',
			   'رصيد سابق' AS 'الكود',
			   '' AS 'التاريخ',
			   CASE 						WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 						THEN SUM( a.Debit )-SUM( a.Credit ) 						ELSE 0.000 			   END AS 'مدين',
			   CASE 						WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'دائن',
			   '' AS 'الصافي',
			   '' AS 'طبيعة الحركة'
		FROM ExSyAccounts_AccSafeActivityTb AS a
	LEFT OUTER JOIN
	AccountsTb AS b
	ON a.AccIDFrom=b.AccID
		WHERE a.IsActive=1
			  AND b.AccActive=1
			  AND (a.CurrencyID=p_CurrencyID
				   OR a.CurrencyID=13)
			  AND a.AccIDFrom=p_SafeID
			  AND a.InsertDate<p_D1
			  AND a.AccBranchID=p_BranchID;
	END IF;

END IF;


IF v_IsDefault=0
 THEN

	IF p_ExistVal=1
	 THEN
		SELECT '' AS '#',
			   'رصيد سابق' AS 'الكود',
			   '' AS 'التاريخ',
			   CASE 						WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'مدين',
			   CASE 						WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'دائن',
			   '' AS 'الصافي',
			   '' AS 'طبيعة الحركة'
		FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
	LEFT OUTER JOIN
	AccountsTb AS b
	ON a.AccIDFrom=b.AccID
		WHERE a.IsActive=1
			  AND b.AccActive=1
			  AND (a.CurrencyID=p_CurrencyID)
			  AND a.AccIDFrom=p_SafeID
			  AND a.InsertDate<p_D1
			  AND a.AccBranchID=p_BranchID;
	END IF;

	IF p_ExistVal=0
	 THEN
		SELECT '' AS '#',
			   'رصيد سابق' AS 'الكود',
			   '' AS 'التاريخ',
			   CASE 						WHEN SUM( a.Credit )-SUM( a.Debit )>SUM( a.Debit )-SUM( a.Credit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'مدين',
			   CASE 						WHEN SUM( a.Debit )-SUM( a.Credit )>SUM( a.Credit )-SUM( a.Debit ) 						THEN SUM( a.Credit )-SUM( a.Debit ) 						ELSE 0.000 			   END AS 'دائن',
			   '' AS 'الصافي',
			   '' AS 'طبيعة الحركة'
		FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
	LEFT OUTER JOIN
	AccountsTb AS b
	ON a.AccIDFrom=b.AccID
		WHERE a.IsActive=1
			  AND b.AccActive=1
			  AND (a.CurrencyID=p_CurrencyID)
			  AND a.AccIDFrom=p_SafeID
			  AND a.InsertDate<p_D1
			  AND a.AccBranchID=p_BranchID;
	END IF;

END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectByEmSafePrintReport`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectByEmSafePrintReport`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN


START TRANSACTION;

SELECT ROW_NUMBER( ) OVER (
	   ORDER BY a.InsertDate ASC) AS '#',
	   a.ISID,
	   a.InsertDate,
	   FORMAT(a.Debit, 2) AS Debit,
	   FORMAT(a.Credit, 2) AS Credit,
	   a.SafeIDMovement
FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE a.IsActive=1
	  AND (a.CurrencyID=p_CurrencyID
		   OR a.CurrencyID=13)
	  AND a.AccIDFrom=p_SafeID
	  AND a.InsertDate>=p_D1
	  AND a.InsertDate<=p_D2
	  AND a.AccBranchID=p_BranchID
ORDER BY a.InsertDate ASC;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTb_SelectPreviewByAgent`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_SelectPreviewByAgent`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_IsValIn` TINYINT(1), INOUT `p_PeroidValue` DECIMAL(18,3), IN `p_CurrencyID` INT)
BEGIN
DECLARE v_BranchType INT;
DECLARE v_SumDebit				  DECIMAL(18, 3);
DECLARE v_SumCredit			  DECIMAL(18, 3);
DECLARE v_OverAllNetTotal		  DECIMAL(18, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(18, 3);
DECLARE v_AccID BIGINT;
DECLARE v_ISDeffult bit;


START TRANSACTION;

SELECT cmt.IsDefault INTO v_ISDeffult FROM CurrencyMainTb cmt WHERE cmt.ID=p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;

SELECT a.AccID INTO v_AccID FROM AccountsTb AS a
WHERE a.AccParent=2010201
	  AND a.BranchID=p_BranchID;
IF v_ISDeffult=1
 THEN
IF p_IsValIn=1
 THEN
	SELECT '' AS '#',
		   'رصيد سابق' AS 'رمز الحوالة',
		   '' AS 'التاريخ',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )<IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'مدين',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )>IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'دائن',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )<IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					WHEN IFNULL( SUM( a.Credit ), 0.000 )>IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'الصافي',
		   '' AS 'طبيعة الحركة',
		   '' AS 'ملاحظات'
	FROM ExSyAccounts_AccSafeActivityTb AS a
	WHERE a.IsActive=1
		  AND a.InsertDate<p_D1
		  AND a.AccIDFrom=v_AccID;
END IF;

IF p_IsValIn=0
 THEN
	SELECT '' AS '#',
		   '' AS 'رمز الحوالة',
		   '' AS 'التاريخ',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )<IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'مدين',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )>IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'دائن',
		   CASE 					WHEN IFNULL( SUM( a.Credit ), 0.000 )<IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					WHEN IFNULL( SUM( a.Credit ), 0.000 )>IFNULL( SUM( a.Debit ), 0.000 ) 					THEN IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) 					ELSE 0.000 		   END AS 'الصافي',

		   '' AS 'طبيعة الحركة',
		   '' AS 'ملاحظات'
	FROM ExSyAccounts_AccSafeActivityTb AS a
	WHERE a.IsActive=1
		  AND a.InsertDate<p_D1
		  AND a.AccIDFrom=v_AccID;
END IF;

SELECT IFNULL( SUM( a.Credit ), 0.000 )-IFNULL( SUM( a.Debit ), 0.000 ) INTO p_PeroidValue FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE a.IsActive=1
	  AND a.InsertDate<p_D1
	  AND a.AccIDFrom=v_AccID;

END IF;

IF v_ISDeffult<>1
 THEN
IF p_IsValIn=1
 THEN
	SELECT '' AS '#',
		   'رصيد سابق' AS 'رمز الحوالة',
		   '' AS 'التاريخ',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )<IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'مدين',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )>IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'دائن',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )<IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					WHEN IFNULL( SUM( a.Debit ), 0.000 )>IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'الصافي',
		   '' AS 'طبيعة الحركة',
		   '' AS 'ملاحظات'
	FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
	WHERE a.IsActive=1
		  AND a.InsertDate<p_D1
		  AND a.AccIDFrom=v_AccID
      AND a.CurrencyID=p_CurrencyID;
END IF;

IF p_IsValIn=0
 THEN
	SELECT '' AS '#',
		   '' AS 'رمز الحوالة',
		   '' AS 'التاريخ',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )<IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'مدين',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )>IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'دائن',
		   CASE 					WHEN IFNULL( SUM( a.Debit ), 0.000 )<IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					WHEN IFNULL( SUM( a.Debit ), 0.000 )>IFNULL( SUM( a.Credit ), 0.000 ) 					THEN IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) 					ELSE 0.000 		   END AS 'الصافي',

		   '' AS 'طبيعة الحركة',
		   '' AS 'ملاحظات'
	FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
	WHERE a.IsActive=1
		  AND a.InsertDate<p_D1
		  AND a.AccIDFrom=v_AccID
      AND a.CurrencyID=p_CurrencyID;
END IF;

SELECT IFNULL( SUM( a.Debit ), 0.000 )-IFNULL( SUM( a.Credit ), 0.000 ) INTO p_PeroidValue FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
WHERE a.IsActive=1
	  AND a.InsertDate<p_D1
	  AND a.AccIDFrom=v_AccID
AND a.CurrencyID=p_CurrencyID;
END IF;

SELECT p_PeroidValue;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ActivivationTb_selectBranchID`;
DELIMITER //
