DROP PROCEDURE IF EXISTS `ADDFORIGNACCOUNTTB_Insert`;
DELIMITER //
CREATE PROCEDURE `ADDFORIGNACCOUNTTB_Insert`(IN `p_ID` INT, IN `p_CountryID` INT, IN `p_CityID` INT, IN `p_CurrencyID` INT, IN `p_IsActive` TINYINT(1), IN `p_InsertDate` DATE, IN `p_IsUpdate` TINYINT(1), IN `p_UserID` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
BEGIN
DECLARE v_CurrentAccParent BIGINT;
DECLARE v_CurrentAcc       BIGINT;
DECLARE v_CapitalAccParent BIGINT;
DECLARE v_CapitalAcc       BIGINT;
DECLARE v_AccParent BIGINT;
DECLARE v_IsExist INT;
DECLARE v_IDcode BIGINT;
DECLARE v_AccCode BIGINT;
DECLARE v_CityName LONGTEXT;
DECLARE v_CountryName LONGTEXT;
DECLARE v_CurrencyName LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
    START TRANSACTION;
    SELECT a.CName INTO v_CountryName FROM
            CountiresTb AS a
    WHERE
            a.ID = p_CountryID;
    SELECT a.CityName INTO v_CityName FROM
            CitiesTb AS a
    WHERE
            a.ID = p_CityID;
    SELECT a.CuName INTO v_CurrencyName FROM
            CurrencyMainTb AS a
    WHERE
            a.ID = p_CurrencyID
 ORDER BY a.ID DESC LIMIT 1;

    IF p_IsUpdate = 0
       THEN

        INSERT INTO ADDFORIGNACCOUNTTB
              (
                AccName,
                CountryID,
                CityID,
                CurrencyID,
                IsActive,
                InsertDate
              )
            SELECT
                    CONCAT('خزينة', SPACE(1), v_CurrencyName, SPACE(1), v_CityName),
                    p_CountryID,
                    p_CityID,
                    p_CurrencyID,
                    p_IsActive,
                    p_InsertDate;


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = 'خزائن خارجية';

        IF v_IsExist = 0
           THEN
SET v_AccParent = 101;
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        'خزائن خارجية',
                        0,
                        2,
                        v_AccParent,
                        0,
                        1,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
          END IF;


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('خزائن خارجية', SPACE(1), v_CountryName);
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'خزائن خارجية';
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        CONCAT('خزائن خارجية', SPACE(1), v_CountryName),
                        0,
                        3,
                        v_AccParent,
                        0,
                        1,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        p_CurrencyID,
                        p_CountryID,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;


          END IF;
        UPDATE ADDFORIGNACCOUNTTB, AccountsTb AS a SET AccParent = a.AccID WHERE
          ID = p_ID
          AND a.AccName = CONCAT('خزائن خارجية', SPACE(1), v_CountryName);


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('خزينة', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = CONCAT('خزائن خارجية', SPACE(1), v_CountryName);
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        CONCAT('خزينة', SPACE(1), v_CurrencyName, SPACE(1), v_CityName),
                        1,
                        4,
                        v_AccParent,
                        0,
                        1,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        p_CurrencyID,
                        p_CountryID,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
            UPDATE ADDFORIGNACCOUNTTB, AccountsTb AS a SET AccID = a.AccID WHERE
              ID = p_ID
              AND a.AccName = CONCAT('خزينة', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);
          END IF;



        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = 'خسائر خزائن خارجية';

        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'مصروفات النشاط';

            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        'خسائر خزائن خارجية',
                        0,
                        3,
                        v_AccParent,
                        0,
                        0,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
            UPDATE
                    ADDFORIGNACCOUNTTB
            SET
                    LossesParentAccID = v_AccParent
            WHERE
              ID = p_ID;
          END IF;


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('خسائر', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'خسائر خزائن خارجية';
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        CONCAT('خسائر', SPACE(1), v_CurrencyName, SPACE(1), v_CityName),
                        0,
                        4,
                        v_AccParent,
                        0,
                        0,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        p_CurrencyID,
                        p_CountryID,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
            UPDATE ADDFORIGNACCOUNTTB, AccountsTb AS a SET LossesAccID = a.AccID WHERE
              ID = p_ID
              AND a.AccName = CONCAT('خسائر', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);

          END IF;





        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = 'أرباح خزائن خارجية';

        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'إيرادات النشاط';

            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        'أرباح خزائن خارجية',
                        0,
                        3,
                        v_AccParent,
                        1,
                        0,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
            UPDATE
                    ADDFORIGNACCOUNTTB
            SET
                    BounsParentAccID = v_AccParent
            WHERE
              ID = p_ID;
          END IF;


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('خسائر', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'أرباح خزائن خارجية';
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDcode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        CONCAT('أرباح', SPACE(1), v_CurrencyName, SPACE(1), v_CityName),
                        0,
                        4,
                        v_AccParent,
                        0,
                        0,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        p_CurrencyID,
                        p_CountryID,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
            UPDATE ADDFORIGNACCOUNTTB, AccountsTb AS a SET BounsAccID = a.AccID WHERE
              ID = p_ID
              AND a.AccName = CONCAT('أرباح', SPACE(1), v_CurrencyName, SPACE(1), v_CityName);
          END IF;


      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ADDINCOMETB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `ADDINCOMETB_LOADTODVG`(IN `p_TypeID` TINYINT UNSIGNED, IN `p_BranchID` INT, IN `p_accTIPE` INT)
BEGIN
START TRANSACTION;
  IF p_accTIPE = 1
     THEN
      IF p_TypeID = 36
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  IncomeTb AS A
              INNER JOIN
                AccountsTb AS B
                  ON A.EMPID = B.AccCode
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
      IF p_TypeID = 37
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  IncomeTb AS A
              INNER JOIN
                AccountsTb AS B
                  ON A.EMPID = B.AccCode
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
      IF p_TypeID = 34
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  IncomeTb AS A
              INNER JOIN
                AccountsTb AS B
                  ON A.EMPID = B.AccCode
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
      IF p_TypeID = 35
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  IncomeTb AS A
              INNER JOIN
                AccountsTb AS B
                  ON A.EMPID = B.AccCode
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
    END IF;

  IF p_accTIPE <> 1
     THEN
      IF p_TypeID = 5

         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.EMPNAME    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                EmployeeTb AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;
      IF p_TypeID = 8
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.CustName   'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                CustomersTb AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;
      IF p_TypeID = 7
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.EMPNAME    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                EmployeeTb AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;
      IF p_TypeID = 6
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.CustName   'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                CustomersTb AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AddLeaveTypeTb_Insert`;
DELIMITER //
CREATE PROCEDURE `AddLeaveTypeTb_Insert`(IN `p_ID` INT, IN `p_LeaveName` VARCHAR(50), IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_ISExist INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
    START TRANSACTION;
    IF p_IsUpdate = 0
       THEN
        SELECT COUNT(LeaveName) INTO v_ISExist FROM
                AddLeaveTypeTb
                WHERE
                LeaveName=p_LeaveName;
        IF v_ISExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا هذا الاسم موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;
        INSERT INTO AddLeaveTypeTb
              (
                LeaveName,
                IsActive
              )
            SELECT
                    p_LeaveName,
                    1;
      END IF;
    IF p_IsUpdate = 1
       THEN
        UPDATE
                AddLeaveTypeTb
        SET
                LeaveName = p_LeaveName, IsActive = p_IsActive
        WHERE
          ID = p_ID;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AddLeaveTypeTb_LOADTOLSBOX`;
