DROP PROCEDURE IF EXISTS `AddNotification`;
DELIMITER //
CREATE PROCEDURE `AddNotification`(IN `p_NotificationID` INT, IN `p_NotificationNAME` LONGTEXT, IN `p_ButtonName` VARCHAR(50), IN `p_BUTTONNAME2` VARCHAR(50), INOUT `p_msg` INT, INOUT `p_msages` LONGTEXT)
proc: BEGIN
DECLARE v_Table_NotificationNAME LONGTEXT;
DECLARE v_Table_p_ButtonName LONGTEXT;
DECLARE v_Table_p_BUTTONNAME2 LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_msg = 2; END;

      START TRANSACTION;




      SELECT a.NotificationNAME INTO v_Table_NotificationNAME FROM
              `frmNotifications` AS a
      WHERE
              a.NotificationNAME = p_NotificationNAME;


      IF v_Table_NotificationNAME = p_NotificationNAME
         THEN

          SET p_msg = 0;
          SET p_msages = v_Table_NotificationNAME;
          ROLLBACK;
          LEAVE proc;
        END IF;

      SELECT a.`Button name` INTO v_Table_p_ButtonName FROM
              `frmNotifications` AS a
      WHERE
              a.`Button name` = p_ButtonName;


      IF v_Table_p_ButtonName = p_ButtonName
         THEN

          SET p_msg = 0;
          SET p_msages = 'عذر اسم هذه الزر  موجود مسبقاً';
          ROLLBACK;
          LEAVE proc;
        END IF;




      SELECT a.BUTTONNAME2 INTO v_Table_p_BUTTONNAME2 FROM
              `frmNotifications` AS a
      WHERE
              a.BUTTONNAME2 = p_BUTTONNAME2;


      IF v_Table_p_BUTTONNAME2 = p_BUTTONNAME2
         THEN

          SET p_msg = 0;
          SET p_msages = 'عذر اسم هذه الزر 2 موجود مسبقاً';
          ROLLBACK;
          LEAVE proc;
        END IF;




      INSERT INTO `frmNotifications`
            (
              NotificationID,
              NotificationNAME,
              `Button name`,
              BUTTONNAME2
            )
      VALUES
              (
                p_NotificationID, p_NotificationNAME, p_ButtonName, p_BUTTONNAME2
              );



      INSERT INTO `NotificationPROFILE`
            (
              `profileID`,
              `NotificationID`,
              `canshow`
            )
          SELECT
                  a.ProfID,
                  p_NotificationID,
                  1
          FROM
                  ProfileName AS a
          GROUP BY
                  a.ProfID;


      INSERT INTO `NotificationUSERID`
            (
              `profileID`,
              `NotificationID`,
              `canshow`,
              `userID`
            )
          SELECT
                  a.ProfID,
                  p_NotificationID,
                  1,
                  b.USID
          FROM
                  ProfileName AS a
              JOIN
                TB_Users AS b
                  ON a.ProfID = b.UserType
          GROUP BY
                  a.ProfID,
                  b.USID;


      COMMIT;
      SET p_msg = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AddPartnerTb_Insert`;
DELIMITER //
CREATE PROCEDURE `AddPartnerTb_Insert`(IN `p_ID` INT, IN `p_Code` VARCHAR(50), IN `p_InsertDate` DATE, IN `p_AccName` VARCHAR(50), IN `p_Phone1` VARCHAR(50), IN `p_Phone2` VARCHAR(50), IN `p_IDNoe` VARCHAR(50), IN `p_PTRATE` DECIMAL(12,3), IN `p_IsActive` TINYINT(1), IN `p_UserID` INT, IN `p_BranchID` INT, IN `p_IsUpdate` TINYINT(1), IN `p_TypeID` INT, IN `p_Phone3` VARCHAR(250), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_CurrentAccParent BIGINT;
DECLARE v_CurrentAcc       BIGINT;
DECLARE v_CapitalAccParent BIGINT;
DECLARE v_CapitalAcc       BIGINT;
DECLARE v_AccParent BIGINT;
DECLARE v_IsExist INT;
DECLARE v_IDcode BIGINT;
DECLARE v_AccCode BIGINT;
DECLARE v_BranchName LONGTEXT;
DECLARE v_NewIDCode INT;
DECLARE v_NewAccCode VARCHAR(50);
DECLARE v_NewAccID INT;
DECLARE v_MaxCodeID     INT;
DECLARE v_Name      VARCHAR(250);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
    START TRANSACTION;
    SELECT a.BName INTO v_BranchName FROM
            CoBranch AS a
    WHERE
            a.ID = p_BranchID;
    IF p_IsUpdate = 0
       THEN
        SELECT COUNT(CT.AccName) INTO v_IsExist FROM
                AddPartnerTb AS CT
        WHERE
                CT.AccName = p_AccName AND CT.BranchID=p_BranchID;

        IF v_IsExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا هذا الاسم موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;

        INSERT INTO AddPartnerTb
              (
                Code,
                InsertDate,
                AccName,
                Phone1,
                Phone2,
                Phone3,
                IDNoe,
                PTRATE,
                IsActive,
                BranchID,
                TypeID
              )
            SELECT
                    p_Code,
                    p_InsertDate,
                    p_AccName,
                    p_Phone1,
                    p_Phone2,
                    p_Phone3,
                    p_IDNoe,
                    p_PTRATE,
                    1,
                    p_BranchID,
                    p_TypeID;

IF p_TypeID=0
 THEN

        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = 'حسابات جارية الشركاء';

        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccParent = 201;

            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDCode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        'حسابات جارية الشركاء',
                        0,
                        2,
                        v_AccParent,
                        1,
                        1,
                        0,
                        0,
                        0,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;
          END IF;


        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('حسابات جارية الشركاء', SPACE(1), v_BranchName);
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE
                    a.AccName = 'حسابات جارية الشركاء';
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDCode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                        CONCAT('حسابات جارية الشركاء', SPACE(1), v_BranchName),
                        0,
                        3,
                        v_AccParent,
                        1,
                        1,
                        0,
                        0,
                        p_BranchID,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent), 0) + 1  AS IDcode;


          END IF;
                   UPDATE AddPartnerTb, AccountsTb AS a SET CurrentAccParent = AccID WHERE
             a.AccName = CONCAT('حسابات جارية الشركاء', SPACE(1), v_BranchName) AND a.BranchID=p_BranchID;
        SELECT COUNT(a.AccName) INTO v_IsExist FROM
                AccountsTb AS a
        WHERE
                a.AccName = CONCAT('حساب', SPACE(1), p_AccName) AND a.BranchID=p_BranchID;
        IF v_IsExist = 0
           THEN
            SELECT a.AccCode INTO v_AccParent FROM
                    AccountsTb AS a
            WHERE

                     a.AccParent=201010
                    AND a.BranchID = p_BranchID;
            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccPhone,
                    AccMobile,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    CanDebit,
                    IDCode
                  )
                SELECT
                        CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent
                                    AND xx.BranchID = p_BranchID), 0) + 1 AS CHAR))                           AS AccCode,
                          CONCAT('حساب الشريك', SPACE(1), p_AccName),
                        1,
                        4,
                        v_AccParent,
                        1,
                        1,
                        p_Phone1,
                        p_Phone2,
                        0,
                        0,
                        p_BranchID,
                        p_UserID,
                        NOW(),
                        0,
                        NOW(),
                        0,
                        1,
                        0,
                        0,
                        1,
                        IFNULL((SELECT
                                    MAX(xx.IDcode)
                            FROM
                                    AccountsTb AS xx
                            WHERE
                                    xx.AccParent = v_AccParent
                                    AND xx.BranchID = p_BranchID), 0) + 1                            AS IDcode;
            UPDATE AddPartnerTb, AccountsTb AS a SET CurrentAcc = a.AccID WHERE
             a.AccName = CONCAT('حساب الشريك', SPACE(1), p_AccName)
             AND a.BranchID=p_BranchID
             AND AddPartnerTb.AccName=p_AccName;
          END IF;

END IF;

IF p_TypeID=1
 THEN





SELECT COUNT(1) INTO v_IsExist FROM AccountsTb a
WHERE a.AccName = CONCAT(N'حساب المستثمر ', p_AccName)
  AND a.BranchID = p_BranchID;




IF v_IsExist = 0
 THEN





        SELECT a.AccCode INTO v_AccParent FROM AccountsTb a
        WHERE a.AccParent = 201018
          AND a.BranchID = p_BranchID LIMIT 1 ;




        SELECT IFNULL(MAX(xx.IDcode), 0) + 1 INTO v_NewIDCode FROM AccountsTb xx
        WHERE xx.AccParent = v_AccParent
          AND xx.BranchID = p_BranchID;




        SET v_NewAccCode = CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(v_NewIDCode AS CHAR));




        INSERT INTO AccountsTb
        (
            AccCode, AccName, AccType, Accline, AccParent,
            AccDmType, AccFinal, AccPhone, AccMobile,
            AccMaxLimit, AccMaxDuration, BranchID,
            AddUser, AddDate, EditUser, EditDate,
            NumofEdit, AccActive, AccCurID, CountryID,
            CanDebit, IDCode
        )
        VALUES
        (
            v_NewAccCode,
            CONCAT(N'حساب المستثمر ', p_AccName),
            1, 4, v_AccParent,
            1, 1, p_Phone1, p_Phone2,
            0, 0, p_BranchID,
            p_UserID, NOW(), 0, NOW(),
            0, 1, 0, 0,
            1, v_NewIDCode
        );




        SET v_NewAccID = LAST_INSERT_ID();




        UPDATE AddPartnerTb
        SET CurrentAcc = v_NewAccID
        WHERE AccName = p_AccName;

END IF;

      END IF;







          SELECT at.AccCode INTO v_AccParent FROM
                  AccountsTb at
          WHERE
                  at.AccParent = 20401
                  AND at.BranchID = p_BranchID;

          IF v_AccParent IS NULL
             THEN
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='الرجاء التأكد من وجود حساب أب (رأس المال المدفوع) لهذا الفرع';
              LEAVE proc;
            END IF;

          SELECT IFNULL(MAX(IDcode), 0) + 1 INTO v_MaxCodeID FROM
                  AccountsTb
          WHERE
                  AccParent = v_AccParent;

          SET v_AccCode = CONCAT(v_AccParent, '0', v_MaxCodeID);
          SET v_Name = CONCAT(N'رأس مال ', CASE WHEN p_TypeID=0 THEN  N'الشريك ' ELSE N'المستثمر ' END, p_AccName);


            INSERT INTO AccountsTb
                  (
                    AccCode,
                    AccName,
                    AccType,
                    Accline,
                    AccParent,
                    AccDmType,
                    AccFinal,
                    AccMaxLimit,
                    AccMaxDuration,
                    BranchID,
                    AddUser,
                    AddDate,
                    EditUser,
                    EditDate,
                    NumofEdit,
                    AccActive,
                    AccCurID,
                    CountryID,
                    IDCode,
                    AccPhone
                  )
              VALUES
              (

            v_AccCode,
            v_Name,
            1,
            4,
            v_AccParent,
            1,
            1,
            0,
            0,
            p_BranchID,
            p_UserID,
            NOW(),
            0,
            NOW(),
            0,
            1,
            0,
            0,
            v_MaxCodeID,
            p_Phone3);

SET v_CapitalAcc=LAST_INSERT_ID();
UPDATE AddPartnerTb SET CapitalAcc=v_CapitalAcc WHERE Code=p_Code;

      END IF;

 IF p_IsUpdate = 1
       THEN
      UPDATE AddPartnerTb
SET
 Code = p_Code
 ,AccName = p_AccName
 ,Phone1 = p_Phone1
 ,Phone2 = p_Phone2
 ,Phone3 = p_Phone3
 ,IDNoe = p_IDNoe
 ,PTRATE = p_PTRATE
 ,IsActive = p_IsActive
 ,TypeID=p_TypeID

WHERE
  ID = p_ID;

SELECT apt.CurrentAcc, apt.CapitalAcc INTO v_CurrentAcc, v_CapitalAcc FROM AddPartnerTb apt WHERE apt.ID =p_ID;

UPDATE AccountsTb
SET
        AccPhone = p_Phone1, AccMobile = p_Phone2, AccIDNo = p_IDNoe, AccActive = p_IsActive, AccName=CONCAT(CASE WHEN p_TypeID=0 THEN  'الشريك'ELSE N'المستثمر' END, SPACE(1), p_AccName)
WHERE
  AccID = v_CurrentAcc;

UPDATE AccountsTb
SET
AccName= CONCAT(N'رأس مال ', CASE WHEN p_TypeID=0 THEN  N'الشريك ' ELSE N'المستثمر ' END, p_AccName), AccPhone=p_Phone3
WHERE
  AccID = v_CapitalAcc;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

