DROP PROCEDURE IF EXISTS `AdvancePaymentTb_ADPMNTTOUPDATE`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_ADPMNTTOUPDATE`(IN `p_EMPID` INT, IN `p_PaidVal` DECIMAL(12,3), IN `p_PaymentTimes` INT)
BEGIN
DECLARE v_PMTIMES INT;
DECLARE v_RePMNTBYMTH INT;
START TRANSACTION;
UPDATE AdvancePaymentTb
SET
	PaidVal=p_PaidVal, PaymentTimes=p_PaymentTimes
WHERE AdvancePaymentTb.EMPID=p_EMPID;
SELECT PaymentTimes INTO v_PMTIMES FROM AdvancePaymentTb
WHERE EMPID=p_EMPID
 ORDER BY AdvancePaymentTb.ID DESC LIMIT 1;
SELECT AdvancePaymentTb.RepaymentPeroid INTO v_RePMNTBYMTH FROM AdvancePaymentTb
WHERE EMPID=p_EMPID
 ORDER BY AdvancePaymentTb.ID DESC LIMIT 1;

IF v_PMTIMES=v_RePMNTBYMTH
 THEN
	UPDATE AdvancePaymentTb
	SET
		IsOpened=0
	WHERE AdvancePaymentTb.EMPID=p_EMPID;
END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_Delete`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_Delete`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;
UPDATE AdvancePaymentTb
SET
	AdvancePaymentTb.IsActive=0,
	AdvancePaymentTb.IsOpened=0
WHERE Code=p_Code;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_GetADPMNTTOUPDATE`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_GetADPMNTTOUPDATE`(IN `p_EMPID` INT)
BEGIN
START TRANSACTION;

SELECT RepaymentPeroid,
	   ValPerMonth,
	   PaymentTimes,
	   PaidVal
FROM AdvancePaymentTb
WHERE EMPID=p_EMPID
	  AND AdvancePaymentTb.IsOpened=1
	  AND AdvancePaymentTb.IsActive=1;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_Insert`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_Insert`(IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_EMPID` INT, IN `p_BranchID` INT, IN `p_OverAllVal` DECIMAL(12,3), IN `p_RepaymentPeroid` TINYINT UNSIGNED, IN `p_ValPerMonth` DECIMAL(12,3), IN `p_SafeID` INT, IN `p_CurrencyID` INT, IN `p_Notes` LONGTEXT, IN `p_AccIDFrom` INT, IN `p_AccIDTo` INT, IN `p_MovementType` LONGTEXT, IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MSGBOX` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_PaidVal DECIMAL(12,3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


			START TRANSACTION;



	IF p_IsUpdate = 0
		 THEN
		SELECT Code INTO v_GETID FROM
					AdvancePaymentTb AS a
			WHERE
					a.Code = p_Code
 ORDER BY a.ID DESC LIMIT 1;
		IF p_Code = v_GETID
								 THEN
									SET p_MSGSTatues = 0;
									SET p_MSGBOX = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
									ROLLBACK;
									LEAVE proc;
		END IF;
			INSERT INTO AdvancePaymentTb
					(
						Code,
						InsertDate,
						EMPID,
						BranchID,
						OverAllVal,
						RepaymentPeroid,
						ValPerMonth,
						IsOpened,
						PaymentTimes,
						PaidVal,
						IsActive,
						SafeID,
						CurrencyID,
						Notes
					)
			VALUES
					(
						p_Code, p_InsertDate, p_EMPID, p_BranchID, p_OverAllVal, p_RepaymentPeroid, p_ValPerMonth, 1, 0, 0.000, 1, p_SafeID, p_CurrencyID, p_Notes
					);



			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						AccSafeActivityTb.Note
					)
			VALUES
					(

						p_SafeID,
						p_OverAllVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						10,
						42,
						p_BranchID,
						p_AccIDFrom,
						p_AccIDTo,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes
					);

			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_OverAllVal,
						p_InsertDate,
						p_Code,
						1,
						10,
						42,
						p_BranchID,
						p_AccIDTo,
						p_AccIDFrom,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes
					);
			SELECT
					ID,
					Code,
					InsertDate,
					EMPID,
					BranchID,
					OverAllVal,
					RepaymentPeroid,
					ValPerMonth,
					IsOpened,
					PaymentTimes,
					PaidVal,
					IsActive,
					SafeID,
					CurrencyID
			FROM
					AdvancePaymentTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;

	IF p_IsUpdate = 1
		 THEN
			UPDATE
					AdvancePaymentTb
			SET
					AdvancePaymentTb.IsActive = 0,
          IsOpened=0
			WHERE
				AdvancePaymentTb.Code = p_Code;

SELECT PaidVal INTO v_PaidVal FROM AdvancePaymentTb  WHERE Code= p_Code
 ORDER BY AdvancePaymentTb.ID DESC LIMIT 1;



			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_OverAllVal-v_PaidVal,
						NOW(),
						p_Code,
						1,
						10,
						42,
						p_BranchID,
						p_AccIDFrom,
						p_AccIDTo,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes
					);

			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note
					)
			VALUES
					(

						p_SafeID,
						p_OverAllVal-v_PaidVal,
						0.000,
						NOW(),
						p_Code,
						1,
						10,
						42,
						p_BranchID,
						p_AccIDTo,
						p_AccIDFrom,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes
					);
			SELECT
					ID,
					Code,
					InsertDate,
					EMPID,
					BranchID,
					OverAllVal,
					RepaymentPeroid,
					ValPerMonth,
					IsOpened,
					PaymentTimes,
					PaidVal,
					IsActive,
					SafeID,
					CurrencyID
			FROM
					AdvancePaymentTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;

				COMMIT;
			SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_LoadAllData`(IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (
			ORDER BY a.Code ASC)		   AS '#',
			a.Code						   AS 'الرمز',
			a.InsertDate				   AS 'التاريخ',
			c.EMPNAME					   AS 'اسم الموظف',
			d.BName						   AS 'الفرع',
			b.CurrencyName				   AS 'نوع العملة',
			a.OverAllVal				   AS 'إجمالي السلفة',
			a.RepaymentPeroid			   AS 'عدد الدفعات',
			a.ValPerMonth				   AS 'قيمة الدفع الشهري',
			a.ValPerMonth * a.PaymentTimes AS 'المدفوع منها',
			CASE 					WHEN a.IsOpened = 1 						THEN 						'مستمرة' 					ELSE 					'منتهية' 			END							   AS 'الحالة'
	FROM
			AdvancePaymentTb AS a
		LEFT JOIN
			CurrencyTb AS b
				ON a.CurrencyID = b.ID
		LEFT JOIN
			EmployeeTb AS c
				ON a.EMPID = c.ID
		LEFT JOIN
			CoBranch AS d
				ON a.BranchID = d.ID
	WHERE
			a.IsActive = 1
			AND b.IsActive = 1
			AND
			a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			a.Code		 'الرمز',
			a.InsertDate 'التاريخ',
			b.EMPNAME	 'الموظف',
			a.OverAllVal 'قيمة السلفة'
	FROM
			AdvancePaymentTb AS a
		LEFT JOIN
			EmployeeTb AS b
				ON a.EMPID = b.ID
	WHERE
	a.BranchID=p_BranchID
	AND
			a.IsActive = 1;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_SelectByCode`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.ID,
			A.Code,
			A.InsertDate,
			A.EMPID,
			A.BranchID,
			B.CurrencyName,
			C.BName,
			D.EMPNAME,
			E.AccName,
			A.OverAllVal,
			A.RepaymentPeroid,
			A.ValPerMonth,
			A.IsOpened,
			A.PaymentTimes,
			A.PaidVal,
			A.IsActive,
			A.SafeID,
			A.CurrencyID,
			 Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes
	FROM
			AdvancePaymentTb AS A
		LEFT JOIN
			CurrencyTb AS B
				ON A.CurrencyID = B.ID
		LEFT JOIN
			CoBranch AS C
				ON A.BranchID = C.ID
		LEFT JOIN
			EmployeeTb AS D
				ON A.EMPID = D.ID
		LEFT JOIN
			AccountsTb AS E
				ON A.SafeID = E.AccID
	WHERE
			A.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AdvancePaymentTb_Update`;
DELIMITER //
CREATE PROCEDURE `AdvancePaymentTb_Update`(IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_EMPID` INT, IN `p_BranchID` INT, IN `p_OverAllVal` DECIMAL(12,3), IN `p_RepaymentPeroid` TINYINT UNSIGNED, IN `p_ValPerMonth` DECIMAL(12,3), IN `p_SafeID` INT, IN `p_CurrencyID` INT, IN `p_Notes` LONGTEXT)
BEGIN
START TRANSACTION;
	UPDATE
			AdvancePaymentTb
	SET
			InsertDate = p_InsertDate, EMPID = p_EMPID, BranchID = p_BranchID, OverAllVal = p_OverAllVal, RepaymentPeroid = p_RepaymentPeroid, ValPerMonth = p_ValPerMonth, IsOpened = 1, IsActive = 1, SafeID = p_SafeID, CurrencyID = p_CurrencyID, Notes = p_Notes
	WHERE
		Code = p_Code;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AgentActivityTb_Insert`;
DELIMITER //
CREATE PROCEDURE `AgentActivityTb_Insert`(IN `p_InsertDate` DATE, IN `p_ISID` LONGTEXT, IN `p_OvearAll` DECIMAL(12,3), IN `p_ExVall` DECIMAL(12,3), IN `p_ISHandallEX` TINYINT(1), IN `p_HandallExVal` DECIMAL(12,3), IN `p_BranchIDFrom` INT, IN `p_BranchIDTo` INT, IN `p_SafeID` INT, IN `p_CurrencyID` INT, IN `p_Notes` LONGTEXT)
BEGIN
START TRANSACTION;

	INSERT INTO AgentActivityTb
			(
				InsertDate,
				ISID,
				OvearAll,
				ExVall,
				ISHandallEX,
				HandallExVal,
				BranchID,
				BranchIDTo,
				SafeID,
				CurrencyID,
				Notes
			)
	VALUES
			(
				p_InsertDate, p_ISID, p_OvearAll, p_ExVall, p_ISHandallEX, p_HandallExVal, p_BranchIDFrom, p_BranchIDTo,p_SafeID, p_CurrencyID, p_Notes

			);
	SELECT
			InsertDate,
				ISID,
				OvearAll,
				ExVall,
				ISHandallEX,
				HandallExVal,
				BranchID,
				BranchIDTo,
				SafeID,
				CurrencyID,
				Notes
	FROM
			AgentActivityTb
	WHERE
			(ID = LAST_INSERT_ID());

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AhmedAshraf`;
DELIMITER //
CREATE PROCEDURE `AhmedAshraf`(IN `p_bracnID` INT, IN `p_dt1` DATE, IN `p_dt2` DATE)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

START TRANSACTION;



SELECT
			b.AccCode							AS accode,
				b.AccName as accname,
			Account_GetAccVal(b.AccID,1,2) AS tolal
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			b.BranchID = p_bracnID
			AND a.InsertDate >= p_dt1
			AND a.InsertDate <= p_dt2
			and a.IsActive=1
      AND b.AccActive=1
			AND (   a.CurrencyID = 1
					OR a.CurrencyID = 13)
          AND a.TypeID<>38
			and (( ACCCODE like CONCAT(CAST(3 AS CHAR), '%')) OR ( ACCCODE like CONCAT(CAST(4 AS CHAR), '%')))
			group BY b.AccCode, b.AccName,b.AccID
			Having Account_GetAccVal(b.AccID,1,2)<>0;



commit;



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ALLAccountStatement`;
DELIMITER //
CREATE PROCEDURE `ALLAccountStatement`(IN `p_BranchID` INT, IN `p_CurrencyTo` INT, IN `p_AccountType` INT)
BEGIN
DECLARE v_IsDefault INT;


  SELECT IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
	where cmt.id=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
  IF v_IsDefault = 1
   THEN

    IF p_AccountType = 0
     THEN

      SELECT a.AccID,
             FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel
        FROM `CustomersTb` AS a
        INNER JOIN ExSyAccounts_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND b.IsActive = 1
      GROUP BY   a.AccID
               HAVING IFNULL(SUM(b.Credit), 0.00) >0 Or IFNULL(SUM(b.Debit), 0.000)>0;
    END IF;


    IF p_AccountType = 1
     THEN

      SELECT a.AccID,
             FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel
        FROM EmployeeTb AS a
        INNER JOIN ExSyAccounts_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND b.IsActive = 1
      GROUP BY a.AccID
                HAVING IFNULL(SUM(b.Credit), 0.00) >0 Or IFNULL(SUM(b.Debit), 0.000)>0;

    END IF;



    IF p_AccountType = 2
     THEN
      SELECT a.AccID,
             FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel
        FROM CreditAccountsTb AS a
        INNER JOIN ExSyAccounts_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND b.IsActive = 1
      GROUP BY   a.AccID
               HAVING IFNULL(SUM(b.Credit), 0.00) >0 Or IFNULL(SUM(b.Debit), 0.000)>0;

  END IF;
END IF;
  IF v_IsDefault =0
   THEN
    IF p_AccountType = 0
     THEN

      SELECT a.AccID,
             a.CustName,
             FORMAT(IFNULL(SUM(b.Credit), 0.00), 3) AS Debit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000), 3) AS Credit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000)-IFNULL(SUM(b.Credit), 0.00), 3)   AS ACCNETtotel,
             a.ID,
             0 AS TypeMov
        FROM `CustomersTb` AS a
        INNER JOIN ExSyAccountsCurrency_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND b.IsActive = 1
         AND b.CurrencyID = p_CurrencyTo
      GROUP BY a.ID,
               a.CustName,
               AccID;


    END IF;
    IF p_AccountType = 1
     THEN

      SELECT a.AccID,
             a.AccName AS CustName,
             FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)AS Debit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)  AS Credit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000)-IFNULL(SUM(b.Credit), 0.00), 3)  AS ACCNETtotel,
             a.AccID AS ID,
             1 AS TypeMov
        FROM AccountsTb AS a
        INNER JOIN EmployeeTb AS c
          ON a.AccID = c.AccID
        INNER JOIN ExSyAccountsCurrency_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (c.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.AccActive = 1
         AND b.IsActive = 1
         AND b.CurrencyID = p_CurrencyTo
      GROUP BY a.AccID,
               a.AccName;
    END IF;




    IF p_AccountType = 2
     THEN
      SELECT a.AccID,
             a.CustName,
             FORMAT(IFNULL(SUM(b.Credit), 0.00), 3) AS Debit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000), 3) AS Credit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000)-IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
             a.ID,
             0 AS TypeMov
        FROM `CustomersTb` AS a
        INNER JOIN ExSyAccountsCurrency_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND b.IsActive = 1
         AND b.CurrencyID = p_CurrencyTo
      GROUP BY a.ID,
               a.CustName,
               AccID


      UNION


      SELECT a.AccID,
             a.AccName AS CustName,
             FORMAT(IFNULL(SUM(b.Credit), 0.00), 3) AS Debit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000), 3) AS Credit,
             FORMAT(IFNULL(SUM(b.Debit), 0.000)-IFNULL(SUM(b.Credit), 0.00), 3)  AS ACCNETtotel,
             a.AccID AS ID,
             1 AS TypeMov
        FROM AccountsTb AS a
        INNER JOIN EmployeeTb AS c
          ON a.AccID = c.AccID
        INNER JOIN ExSyAccountsCurrency_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (c.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.AccActive = 1
         AND b.IsActive = 1
         AND b.CurrencyID = p_CurrencyTo
      GROUP BY a.AccID,
               a.AccName;

    END IF;


  END IF;
END //
DELIMITER ;

