DROP PROCEDURE IF EXISTS `ANOTHEREXPENSTB_Insert`;
DELIMITER //
CREATE PROCEDURE `ANOTHEREXPENSTB_Insert`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_SafeID` BIGINT, IN `p_CurrencyID` INT, IN `p_ExpensVal` DECIMAL(12,3), IN `p_AccIDEX` BIGINT, IN `p_Notes` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_IDCode` BIGINT, IN `p_AccIDSafeID` BIGINT, IN `p_Movement` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_UserInsert` BIGINT)
BEGIN
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_MovementType VARCHAR(100);


	START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO ANOTHEREXPENSTB
					(
						Code,
						InsertDate,
						BranchID,
						SafeID,
						CurrencyID,
						ExpensVal,
						Notes,
						IsActive,
						IDCode,
						AccSafeID,
						AccIDPC,
						UserInsert
					)
			VALUES
