						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						p_ExpensVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						15,
						45,
						p_BranchID,
						p_AccIDEX,
						p_AccIDSafeID,
						1,
						0,
						v_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_Movement
					);


			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_ExpensVal,
						p_InsertDate,
						p_Code,
						1,
						15,
						45,
						p_BranchID,
						p_AccIDSafeID,
						p_AccIDEX,
						1,
						0,
						v_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_Movement
					);
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					ANOTHEREXPENSTB
			SET
					IsActive = 0,UserInsert=p_UserInsert
			WHERE
				code = p_Code;
SET v_MovementType = ' معالجة خطأ مصروفات بدون عهدة ';
			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_ExpensVal,
						p_InsertDate,
						p_Code,
						1,
						15,
						45,
						p_BranchID,
						p_AccIDEX,
						p_AccIDSafeID,
						1,
						0,
						v_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_Movement
					);


			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						p_ExpensVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						15,
						45,
						p_BranchID,
						p_AccIDSafeID,
						p_AccIDEX,
						1,
						0,
						v_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_Movement
					);
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ANOTHEREXPENSTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `ANOTHEREXPENSTB_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code		 AS 'الرمز',
			A.InsertDate AS 'التاريخ',
			B.AccName	 AS 'المصروف',
			A.ExpensVal	 AS 'القيمة'
	FROM
			ANOTHEREXPENSTB AS A
		LEFT JOIN
			AccountsTb AS B
				ON A.AccIDPC = B.AccID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ANOTHEREXPENSTB_SELECTByCODE`;
DELIMITER //
CREATE PROCEDURE `ANOTHEREXPENSTB_SELECTByCODE`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code,
			A.InsertDate,
			A.AccIDPC,
			A.AccSafeID,
			A.BranchID,
			A.CurrencyID,
			A.ExpensVal,
			A.Notes,
			A.IDCode
	FROM
			ANOTHEREXPENSTB AS A
	WHERE
			A.Code = p_Code
			AND A.IsActive = 1;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AseetT_typeinsertTP`;
DELIMITER //
CREATE PROCEDURE `AseetT_typeinsertTP`(IN `p_code` LONGTEXT, IN `p_branchID` BIGINT, IN `p_parent` INT, IN `p_clsf` INT, IN `p_clsname` LONGTEXT)
proc: BEGIN
DECLARE v_idcode int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;



        IF EXISTS (SELECT
                        1
                FROM
                      AseetT_type
                WHERE
                        code = p_code)
             THEN
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='كود التصنيف موجود مسبقا';
              LEAVE proc;
            END IF;
            SELECT IFNULL(max(IDcode),0)+1 INTO v_idcode FROM AseetT_type where parent=p_parent;
    INSERT INTO AseetT_type
        (  code, parent, branchID,clsf,clsname,IDcode)
    VALUES
        ( p_code, p_parent, p_branchID,p_clsf,p_clsname,v_idcode);



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AssActivityTb_GETASSO`;
DELIMITER //
CREATE PROCEDURE `AssActivityTb_GETASSO`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          a.InsertDate                          AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',

          CASE                   WHEN a.Note = ''                     OR a.Note IS NULL                     THEN                     a.MovementType                   ELSE                   a.Note           END                                   AS 'ملاحظات'

  FROM
          ExSyAccounts_AccSafeActivityTb AS a
  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE);
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AssActivityTb_GETEMPMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `AssActivityTb_GETEMPMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
     SELECT a.ISID AS 'الرمز',
            a.InsertDate 'التاريخ',
            b.CurrencyName 'العملة',
            a.Debit 'مدين',
            a.Credit 'دائن',
            a.MovementType 'طبيعة الحركة'
     FROM AssActivityTb AS a
          LEFT JOIN CurrencyTb AS b ON a.CurrencyID = b.ID
     WHERE a.AccIDFrom = p_AccID
           AND a.IsActive = 1
           AND A.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE);
     COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AssActivityTb_GETMEMBER`;
DELIMITER //
CREATE PROCEDURE `AssActivityTb_GETMEMBER`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT, IN `p_AssID` INT, IN `p_LOADTYPE` INT)
BEGIN
START TRANSACTION;
  IF p_LOADTYPE = 2
     THEN

      SELECT
              ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
              a.ISID                                AS 'الرمز',
              a.InsertDate                          AS 'التاريخ',
              a.Debit                               AS 'مدين',
              a.Credit                              AS 'دائن',
              a.SafeIDMovement                      AS 'طبيعة الحركة',
              CASE                       WHEN a.Note = ''                         THEN                         a.MovementType                       ELSE                       a.Note               END                                   AS 'ملاحظات'

      FROM
              ExSyAccounts_AccSafeActivityTb AS a
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE);
    END IF;
  IF p_LOADTYPE = 1
     THEN

      SELECT
              ROW_NUMBER() OVER (ORDER BY b.ID ASC) AS '#',
              b.MEMBERNAME                          AS 'الاسم',
              FORMAT(SUM(a.Debit), 3)   AS 'مدين',
              FORMAT(SUM(a.Credit), 3)  AS 'دائن',
              b.AccID,
              a.MovementType                        AS 'ملاحظات'
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            ASSOCIATIONTB AS b
              ON a.AccIDFrom = b.AccID
      WHERE
              b.ASSOCIATIONID = p_AssID
              AND a.IsActive = 1
              AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
      GROUP BY
              b.MEMBERNAME,
              b.ID,
              b.AccID,
              a.MovementType;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS ``;
DELIMITER //
CREATE PROCEDURE `Association expenses`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          a.InsertDate                          AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',
          CASE                   WHEN a.Note = '' OR a.Note IS NULL                   THEN a.MovementType                   ELSE a.Note           END AS 'ملاحظات'
  FROM ExSyAccounts_AccSafeActivityTb AS a
  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
          AND a.Debit > 0;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Association_revenues`;
DELIMITER //
CREATE PROCEDURE `Association_revenues`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          a.InsertDate                          AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',
          CASE                   WHEN a.Note = '' OR a.Note IS NULL                   THEN a.MovementType                   ELSE a.Note           END AS 'ملاحظات'
  FROM ExSyAccounts_AccSafeActivityTb AS a
  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
          AND a.Credit  > 0;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ASSOCIATIONNAMETB_Insert`;
DELIMITER //
CREATE PROCEDURE `ASSOCIATIONNAMETB_Insert`(IN `p_ID` INT, IN `p_ASSNAME` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_IsActive` TINYINT(1), IN `p_BranchID` INT, IN `p_AssValue` DECIMAL(12,3), IN `p_INSERTTYPE` INT)
BEGIN
DECLARE v_acccode			  BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_AccNameMain INT;
DECLARE v_AccNameMainTow INT;
DECLARE v_AccNameMainTowBranch INT;
DECLARE v_AccNameMainThree INT;
DECLARE v_AccNameMainFour INT;
DECLARE v_AccID				  BIGINT;
DECLARE v_ASSOACCID			  BIGINT;
START TRANSACTION;

	IF p_INSERTTYPE = 1
		 THEN
			IF p_IsUpdate = 0
				 THEN
					INSERT INTO ASSOCIATIONNAMETB
							(
								ASSNAME,
								IsActive,
								AssValue
							)
						SELECT
								p_ASSNAME,
								1,
								p_AssValue;

					SELECT COUNT(AccID) INTO v_AccNameMain FROM
							AccountsTb at
					WHERE
							at.AccName = 'مشتركو الجمعية';
					IF v_AccNameMain = 0
						 THEN
SET v_IDParent = 11;
							SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
									AccountsTb AS a
							WHERE
									AccParent = v_IDParent;
							IF v_IDcode IS NULL
								 THEN
SET v_IDcode = 1;
								END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = 'مشتركو الجمعية';
							INSERT INTO AccountsTb
									(

										AccCode,
										AccName,
										AccType,
										Accline,
										AccParent,
										AccDmType,
										AccFinal,
										AccMaxLimit,
										AccMaxDuration,
										BranchID,
										AccActive,
										IDcode
									)
							VALUES
									(
										v_acccode, v_AccName, 0, 2, v_IDParent, 0, 1, 0, 0, p_BranchID, 1, v_IDcode
									);
						END IF;

					SELECT COUNT(AccID) INTO v_AccNameMainTow FROM
							AccountsTb at
					WHERE
							at.AccName = 'الجمعيات الدائنة';
					IF v_AccNameMainTow = 0
						 THEN
SET v_IDParent = 21;
							SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
									AccountsTb AS a
							WHERE
									AccParent = v_IDParent;
							IF v_IDcode IS NULL
								 THEN
SET v_IDcode = 1;
								END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = 'الجمعيات الدائنة';
							INSERT INTO AccountsTb
									(
										AccCode,
										AccName,
										AccType,
										Accline,
										AccParent,
										AccDmType,
										AccFinal,
										BranchID,
										AccActive,
										IDcode
									)
							VALUES
									(
										v_acccode, v_AccName, 0, 2, v_IDParent, 1, 1, p_BranchID, 1, v_IDcode
									);
						END IF;

					SELECT COUNT(AccID) INTO v_AccNameMainTow FROM
							AccountsTb at
					WHERE
							at.AccName = 'الجمعيات';
					IF v_AccNameMainTow = 0
						 THEN
							SELECT at.AccCode INTO v_IDParent FROM
							AccountsTb at
					WHERE
							at.AccName = 'الجمعيات الدائنة';
							SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
									AccountsTb AS a
							WHERE
									AccParent = v_IDParent;
							IF v_IDcode IS NULL
								 THEN
SET v_IDcode = 1;
								END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = 'الجمعيات';
							INSERT INTO AccountsTb
									(
										AccCode,
										AccName,
										AccType,
										Accline,
										AccParent,
										AccDmType,
										AccFinal,
										BranchID,
										AccActive,
										IDcode
									)
							VALUES
									(
										v_acccode, v_AccName, 0, 3, v_IDParent, 1, 1, p_BranchID, 1, v_IDcode
									);
						END IF;

					SELECT AccCode INTO v_IDParent FROM
							AccountsTb AS a
					WHERE
							AccName = 'الجمعيات';
					SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
							AccountsTb AS a
					WHERE
							AccParent = v_IDParent;
					IF v_IDcode IS NULL
						 THEN
SET v_IDcode = 1;
						END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('جمعية', ' ', p_ASSNAME);
					INSERT INTO AccountsTb
							(
								AccCode,
								AccName,
								AccType,
								Accline,
								AccParent,
								AccDmType,
								AccFinal,
								BranchID,
								AccActive,
								IDcode
							)
					VALUES
							(
								v_acccode, v_AccName, 1, 4, v_IDParent, 1, 1, p_BranchID, 1, v_IDcode
							);
					SELECT AccID INTO v_ASSOACCID FROM
							AccountsTb
					WHERE
							AccCode = v_acccode;
					UPDATE
							ASSOCIATIONNAMETB
					SET
							ASSOACCID = v_ASSOACCID
					WHERE
						ID = p_ID;

					SELECT COUNT(AccID) INTO v_AccNameMainThree FROM
							AccountsTb at
					WHERE
							at.AccName = 'مستحقات اشتراكات جمعيات';
					IF v_AccNameMainThree = 0
						 THEN
SET v_IDParent = 217;
							SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
									AccountsTb AS a
							WHERE
									AccParent = v_IDParent;
							IF v_IDcode IS NULL
								 THEN
SET v_IDcode = 1;
								END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = 'مستحقات اشتراكات جمعيات';
							INSERT INTO AccountsTb
									(
										AccCode,
										AccName,
										AccType,
										Accline,
										AccParent,
										AccDmType,
										AccFinal,
										BranchID,
										AccActive,
										IDcode
									)
							VALUES
									(
										v_acccode, v_AccName, 0, 3, v_IDParent, 1, 1, p_BranchID, 1, v_IDcode
									);
						END IF;

					SELECT COUNT(AccID) INTO v_AccNameMainThree FROM
							AccountsTb at
					WHERE
							at.AccName = 'اشتراكات مستحقة جمعيات';
					IF v_AccNameMainThree = 0
						 THEN
							SELECT AccCode INTO v_IDParent FROM
									AccountsTb AS a
							WHERE
									AccName = 'مستحقات اشتراكات جمعيات';
							SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
									AccountsTb AS a
							WHERE
									AccParent = v_IDParent;
							IF v_IDcode IS NULL
								 THEN
SET v_IDcode = 1;
								END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('اشتراكات مستحقة جمعية', ' ', p_ASSNAME);
							INSERT INTO AccountsTb
									(
										AccCode,
										AccName,
										AccType,
										Accline,
										AccParent,
										AccDmType,
										AccFinal,
										BranchID,
										AccActive,
										IDcode
									)
							VALUES
									(
										v_acccode, v_AccName, 1, 4, v_IDParent, 1, 1, p_BranchID, 1, v_IDcode
									);
						END IF;

					SELECT A.AccCode INTO v_IDParent FROM
							AccountsTb AS A
					WHERE
							A.AccName = 'مشتركو الجمعية';
					SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
							AccountsTb AS a
					WHERE
							AccParent = v_IDParent;
					IF v_IDcode IS NULL
						 THEN
SET v_IDcode = 1;
						END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('مشتركو جمعية', ' ', p_ASSNAME);
					INSERT INTO AccountsTb
							(
								AccCode,
								AccName,
								AccType,
								Accline,
								AccParent,
								AccDmType,
								AccFinal,
								AccMaxLimit,
								AccMaxDuration,
								AccActive,
								IDcode,
								BranchID
							)
