							AccountsTb at
					WHERE
							at.AccName = CONCAT('مشتركو جمعية', ' ', p_ASSNAME);
					UPDATE
							ASSOCIATIONNAMETB
					SET
							AccID = v_AccID
					WHERE
						ID = p_ID;


				END IF;
			IF p_IsUpdate = 1
				 THEN
					UPDATE
							ASSOCIATIONNAMETB
					SET
							ASSNAME = p_ASSNAME, AssValue = p_AssValue, IsActive = p_IsActive
					WHERE
						ID = p_ID;
					SELECT AccID INTO v_AccID FROM
							ASSOCIATIONNAMETB at
					WHERE
							at.ID = p_ID;

					UPDATE
							AccountsTb
					SET
							AccName = CONCAT('مشتركو جمعية', ' ', p_ASSNAME)
					WHERE
						AccID = v_AccID;
					SELECT ASSOACCID INTO v_ASSOACCID FROM
							ASSOCIATIONNAMETB
					WHERE
							ID = p_ID;
					UPDATE
							AccountsTb
					SET
							AccName = CONCAT('جمعية', ' ', p_ASSNAME)
					WHERE
						AccID = v_ASSOACCID;
				END IF;
		END IF;
	IF p_INSERTTYPE = 2
		 THEN
			UPDATE
					ASSOCIATIONNAMETB
			SET
					AssValue = p_AssValue
			WHERE
				ID = p_ID;
		END IF;
	COMMIT;
END //
DELIMITER ;

