DROP PROCEDURE IF EXISTS `ASSOCIATIONTB_Insert`;
DELIMITER //
CREATE PROCEDURE `ASSOCIATIONTB_Insert`(IN `p_ID` BIGINT, IN `p_MEMBERNAME` LONGTEXT, IN `p_PHONE` VARCHAR(50), IN `p_IDNO` VARCHAR(50), IN `p_ASSOCIATIONID` INT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_BranchID` INT)
BEGIN
DECLARE v_acccode		  BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_AccNameMain INT;
DECLARE v_AccID			  BIGINT;
DECLARE v_ASSOCIATIONACCID BIGINT;
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO ASSOCIATIONTB
					(
						MEMBERNAME,
						PHONE,
						IDNO,
						ASSOCIATIONID,
						IsActive
					)
				SELECT
						p_MEMBERNAME,
						p_PHONE,
						p_IDNO,
						p_ASSOCIATIONID,
						1;

			SELECT at.AccCode INTO v_IDParent FROM
					ASSOCIATIONNAMETB a
				LEFT OUTER JOIN
					AccountsTb at
						ON a.AccID = at.AccID
			WHERE
					ID = p_ASSOCIATIONID;
			SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
					AccountsTb AS a
			WHERE
					AccParent = v_IDParent;
			IF v_IDcode IS NULL
				 THEN
SET v_IDcode = 1;
				END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
			INSERT INTO AccountsTb
					(
						AccCode,
						AccName,
						AccType,
						Accline,
						AccParent,
						AccDmType,
						AccFinal,
						AccActive,
						BranchID,
						IDcode
					)
			VALUES
					(
						v_acccode, p_MEMBERNAME, 1, 4, v_IDParent, 0, 1, 1, p_BranchID, v_IDcode
					);
SET v_AccID = LAST_INSERT_ID();
			UPDATE
					ASSOCIATIONTB
			SET
					AccID = v_AccID
			WHERE
				ID = p_ID;
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					ASSOCIATIONTB
			SET
					MEMBERNAME = p_MEMBERNAME, PHONE = p_PHONE, IDNO = p_IDNO, ASSOCIATIONID = p_ASSOCIATIONID, IsActive = p_IsActive
			WHERE
				ID = p_ID;

			SELECT AccID INTO v_AccID FROM
					ASSOCIATIONTB at
			WHERE
					at.ID = p_ID;
			UPDATE
					AccountsTb
			SET
					AccName = p_MEMBERNAME
			WHERE
				AccID = v_AccID;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ASSOCIATIONTB_LOADBASEDONASSID`;
DELIMITER //
CREATE PROCEDURE `ASSOCIATIONTB_LOADBASEDONASSID`(IN `p_ASSID` INT)
BEGIN
START TRANSACTION;

	SELECT
			a.ID,
			a.MEMBERNAME,
			a.AccID
	FROM
			ASSOCIATIONTB AS a
		LEFT OUTER JOIN
			ASSOCIATIONNAMETB AS b
				ON a.ASSOCIATIONID = b.ID
	WHERE
			a.ASSOCIATIONID = p_ASSID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ASSOCIATIONTB_LOADMEMBERS`;
