BEGIN
START TRANSACTION;

	SELECT
			MEMBERNAME,
			ID
	FROM
			ASSOCIATIONTB
	GROUP BY
			MEMBERNAME,
			ID
	ORDER BY
			MEMBERNAME ASC;
	COMMIT;
END //
DELIMITER ;

