			PHONE,
			IDNO,
			ASSOCIATIONID,
			IsActive,
			AccID
	FROM
			ASSOCIATIONTB
	WHERE
			ID = p_ID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BalanceSheet_Statment`;
DELIMITER //
CREATE PROCEDURE `BalanceSheet_Statment`(IN `p_BranchID` INT, IN `p_Type` INT)
BEGIN
DECLARE v_MainBr INT;



  SELECT cb.ID INTO v_MainBr FROM
          CoBranch cb
  WHERE
          cb.IsMain = 1;

IF p_Type=1
 THEN
  SELECT
          1                       AS TypeID,
          'النقدية والمصارف'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
          SUM(b.Debit) - SUM(b.Credit) AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.AccBranchID = p_BranchID
          AND at.AccParent LIKE '1010%'
          AND at.AccParent NOT LIKE '101030%'
          AND at.AccParent NOT LIKE '101060%'
          AND at.AccParent NOT LIKE '101070%'
          AND at.AccParent NOT LIKE '101080%'
          AND at.AccParent NOT LIKE '101090%'
          AND at.AccParent NOT LIKE '1010100%'
          AND at.AccParent NOT LIKE '1010110%'
          AND b.IsActive=1
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0


  UNION ALL

  SELECT
          2                            AS TypeID,
          'مستحقات من الغير'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
          SUM(b.Debit) - SUM(b.Credit) AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND   ( b.AccBranchID = p_BranchID
                  AND (   (       at.AccParent LIKE '2010%'
                                  AND at.AccParent NOT LIKE '201060%'
                                  AND at.AccParent <>2010701
                                  AND at.AccParent <>2010702
                                  AND at.AccParent <>2010703
                                  AND at.AccParent NOT LIKE '201090%'
                                  AND at.AccParent NOT LIKE '201080%'
                                  AND at.AccParent NOT LIKE '2010201%'
                          )
                          OR (at.AccParent LIKE '101070%')
                          OR (at.AccParent LIKE '101080%')))
                  OR
                     (p_BranchID=v_MainBr AND  b.IsActive=1 AND  (     at.BranchID <> p_BranchID
                                    AND (    at.AccParent = 2010201
                                            )))
 OR
                     (p_BranchID<>v_MainBr          AND  b.IsActive=1 AND  (   (       at.BranchID = v_MainBr
                                      AND (   at.AccParent = 2010201
                                              ))) AND b.AccBranchID=p_BranchID)


  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          (SUM(b.Debit) - SUM(b.Credit) > 0)
          OR (SUM(b.Debit) - SUM(b.Credit) <> 0 AND  ((at.AccParent LIKE '101070%')
                          OR (at.AccParent LIKE '101080%')))



  UNION ALL

  SELECT
          3                       AS TypeID,
          'مستحقات محتملة من الفروع'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
          SUM(b.Debit) - SUM(b.Credit) AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND at.AccParent  LIKE '101060%'

  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0

UNION ALL

  SELECT
          4                       AS TypeID,
          'الأصول الثابتة والمواد'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
          SUM(b.Debit) - SUM(b.Credit) AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND (at.AccParent LIKE '1020%'
          OR at.AccParent LIKE '1010110%')
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0


UNION ALL

  SELECT
          5                       AS TypeID,
          'الأصول الأخرى'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
         (SUM(b.Debit)-SUM(b.Credit))   AS Accval



  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND (at.AccParent LIKE '1030%'
          OR at.AccParent LIKE '101090%'
          OR at.AccParent LIKE '101030%')
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0;


END IF;


IF p_Type=2
 THEN
  SELECT
          1                       AS TypeID,
          'حقوق الملكية'           AS TypeName,
          x.AccParent,
          x.AccID,
          x.AccName,
          x.ParentName                    AS ParentName,
            x.Accval
  FROM

(SELECT
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
          SUM(b.Credit)-SUM(b.Debit)  AS Accval
          FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND at.AccParent LIKE '2040%'

  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0

UNION ALL

SELECT
          0 AS  AccParent,
          0 AS AccID,
          CASE WHEN SUM(b.Credit)-SUM(b.Debit)>0 THEN 'أرباح الفترة'ELSE 'خسائر الفترة' END  AccName,
          'صافي قائمة الدخل'                    AS ParentName,
          SUM(b.Credit)-SUM(b.Debit)  AS Accval
          FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND (at.AccParent LIKE '3%' OR at.AccParent LIKE '4%')
          AND at.AccActive=1


          ) AS x


  UNION ALL

  SELECT
          2                            AS TypeID,
          'مستحقات للغير'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
         SUM(b.Credit)- SUM(b.Debit)   AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND(    b.AccBranchID = p_BranchID
                  AND (  (       at.AccParent LIKE '2010%'
                                  AND at.AccParent NOT LIKE '201060%'
                                  AND at.AccParent <>2010701
                                  AND at.AccParent <>2010702
                                  AND at.AccParent <>2010703
                                  AND at.AccParent NOT LIKE '201090%'
                                  AND at.AccParent NOT LIKE '201080%'
                                   AND at.AccParent NOT LIKE '2010201%'
                          )) )
                  OR
                     (p_BranchID=v_MainBr AND  b.IsActive=1 AND  (     at.BranchID <> p_BranchID
                                    AND (    at.AccParent = 2010201
                                            )))
 OR
                     (p_BranchID<>v_MainBr          AND  b.IsActive=1 AND  (   (       at.BranchID = v_MainBr
                                      AND (   at.AccParent = 2010201
                                              ))) AND b.AccBranchID=p_BranchID)
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Debit) - SUM(b.Credit) < 0



  UNION ALL

  SELECT
          3                       AS TypeID,
          'التزامات محتملة للفروع والزبائن'           AS TypeName,
          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
         SUM(b.Credit)- SUM(b.Debit)   AS Accval
  FROM
          AccountsTb at
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4
          AND b.IsActive=1
          AND b.AccBranchID = p_BranchID
          AND (at.AccParent  LIKE '201060%'
          OR at.AccParent  =2010701
          OR at.AccParent  =2010703
 )
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent
  HAVING
          SUM(b.Credit) - SUM(b.Debit) <> 0

UNION ALL


  SELECT
              4                     AS TypeID,
          'التزامات أخرى'           AS TypeName,
          x.AccParent,
          x.AccID,
          x.AccName,
          x.AccName                    AS ParentName,
         (SUM(x.Credit)-SUM(x.Debit))   AS Accval

  from
 ( SELECT

          at.AccParent,
          at.AccID,
          at.AccName,
          d.AccName                    AS ParentName,
         SUM(b.Credit) AS Credit,
         SUM(b.Debit)   AS Debit
  FROM
          AccountsTb at
      LEFT JOIN
        ExSyAccounts_AccSafeActivityTb b
          ON at.AccID = b.AccIDFrom
      INNER JOIN
        AccountsTb c
          ON at.AccParent = c.AccCode
      INNER JOIN
        AccountsTb d
          ON c.AccParent = d.AccCode
  WHERE
          at.Accline = 4

          AND b.AccBranchID = p_BranchID
          AND (at.AccParent LIKE '2030%'
          OR at.AccParent = 2010702
          OR at.AccParent = 2010801
          OR at.AccParent LIKE '201090%')
  GROUP BY
          at.AccID,
          at.AccName,
          d.AccName,
          at.AccParent


          ) as x

  GROUP BY
          x.AccID,
          x.AccName,
          x.AccName,
          x.AccParent
  HAVING
          SUM(x.Credit) - SUM(x.Debit) <> 0;
END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankDipWdTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BankDipWdTb_Insert`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_SafeAccID` BIGINT, IN `p_AccFrom` BIGINT, IN `p_AccTo` BIGINT, IN `p_CODEID` BIGINT, IN `p_BillVal` DECIMAL(18,3), IN `p_IsDiscount` TINYINT(1), IN `p_DiscountFrom` TINYINT UNSIGNED, IN `p_DiscountType` TINYINT UNSIGNED, IN `p_OverAllTotal` DECIMAL(18,3), IN `p_DiscountVal` DECIMAL(12,3), IN `p_BillNo` VARCHAR(50), IN `p_Notes` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_TypeID` INT, IN `p_OperationTypeID` INT, IN `p_CurrencyID` INT, IN `p_MovementType2` LONGTEXT, IN `p_UserID` INT, IN `p_GetAccountName` LONGTEXT, IN `p_DiscountAccID` BIGINT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_OwnAccountName` VARCHAR(50), IN `p_OwnAccountPhone` VARCHAR(50), IN `p_EXID` INT, IN `p_AccParent` BIGINT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_RestVal DECIMAL(12, 3);
DECLARE v_MovementType   LONGTEXT;
DECLARE v_ExValAccID BIGINT;
DECLARE v_BankBounsAccID BIGINT;
DECLARE v_BRANCHNAME LONGTEXT;
DECLARE v_IsDis          BIT;
DECLARE v_DiscountTp     TINYINT;
DECLARE v_DiscountF      TINYINT;
DECLARE v_ExName LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


    START TRANSACTION;
    SELECT cb.BName INTO v_BRANCHNAME FROM
            CoBranch cb
    WHERE
            ID = p_BranchID;
    SELECT at.AccID INTO v_BankBounsAccID FROM
            AccountsTb at
    WHERE
            at.AccName = CONCAT('عمولات تحويلات مصرفية', ' ', v_BRANCHNAME);
    SELECT at.AccID INTO v_BankBounsAccID FROM
            AccountsTb at
    WHERE
            at.AccParent = 4010107
            AND at.BranchID = p_BranchID;
    IF p_IsUpdate = 0
       THEN
        SELECT Code INTO v_GETID FROM
                BankDipWdTb AS a
        WHERE
                a.Code = p_Code;
        IF p_Code = v_GETID
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
            ROLLBACK;
            LEAVE proc;
          END IF;
        INSERT INTO BankDipWdTb
              (
                Code,
                InsertDate,
                BranchID,
                SafeAccID,
                AccFrom,
                AccTo,
                CODEID,
                CurrencyID,
                BillVal,
                IsDiscount,
                DiscountFrom,
                DiscountType,
                OverAllTotal,
                DiscountVal,
                BillNo,
                TypeID,
                Notes,
                IsActive,
                OwnAccountName,
                OwnAccountPhone,
                EXID,
                AccParent
              )
        VALUES
                (
                  p_Code, p_InsertDate, p_BranchID, p_SafeAccID, p_AccFrom, p_AccTo, p_CODEID, p_CurrencyID, p_BillVal, p_IsDiscount, p_DiscountFrom, p_DiscountType, p_OverAllTotal, p_DiscountVal, p_BillNo, p_TypeID, p_Notes, p_IsActive, p_OwnAccountName, p_OwnAccountPhone, p_EXID,p_AccParent
                );
        SELECT A.IsDiscount, A.DiscountType, A.DiscountFrom INTO v_IsDis, v_DiscountTp, v_DiscountF FROM
                BankDipWdTb AS A
        WHERE
                A.Code = p_Code;
        IF (p_TypeID = 16
          OR
          p_TypeID = 18)
           THEN
            IF p_EXID <> 0
               THEN
                SELECT a.ExName INTO v_MovementType FROM
                        ContractDB.ExpensesTb AS a
                WHERE
                        a.ID = p_EXID;
              END IF;
