                BankDipWdTb.IsActive = 0
        WHERE
          BankDipWdTb.Code = p_Code;

        IF (p_TypeID = 16
          OR
          p_TypeID = 18)
           THEN
SET v_MovementType = 'معالجة خطأ في إيداع بتحويل مصرفي';
          END IF;
        IF (p_TypeID = 17
          OR
          p_TypeID = 19)
           THEN
SET v_MovementType = 'معالجة خطأ في سحب بتحويل مصرفي';
          END IF;
        IF (p_TypeID = 47)
           THEN
SET v_MovementType = 'معالجة خطأ في تحويل مصرفي بين الحسابات';
          END IF;
        IF (p_TypeID = 16
          OR
          p_TypeID = 18)
           THEN

            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (

                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                  )
                  SELECT
                    p_UserID,
                    Credit,
                    Debit,
                    NOW(),
                    ISID,
                    p_TypeID,
                    p_OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    v_MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                    FROM ExSyAccounts_AccSafeActivityTb a WHERE a.ISID=p_Code
                    ORDER BY a.ID;
































































































































































































































































          END IF;
        IF (p_TypeID = 17
          OR
          p_TypeID = 19)
           THEN
            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (

                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                  )
                  SELECT
                    p_UserID,
                    Credit,
                    Debit,
                    NOW(),
                    ISID,
                    p_TypeID,
                    p_OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    v_MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                    FROM ExSyAccounts_AccSafeActivityTb a WHERE a.ISID=p_Code
                    ORDER BY a.ID;































































































































































































































































          END IF;
        IF (p_TypeID = 47)
           THEN
            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (

                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                  )
                  SELECT
                    p_UserID,
                    Credit,
                    Debit,
                    NOW(),
                    ISID,
                    p_TypeID,
                    p_OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    v_MovementType,
                    CurrencyID,
                    Note,
                    IsBank
                    FROM ExSyAccounts_AccSafeActivityTb a WHERE a.ISID=p_Code
                    ORDER BY a.ID;




















































          END IF;
        SELECT
                ID,
                Code,
                InsertDate,
                BranchID,
                SafeAccID,
                AccFrom,
                AccTo,
                BillVal,
                IsDiscount,
                DiscountFrom,
                DiscountType,
                OverAllTotal,
                DiscountVal,
                Notes,
                IsActive
        FROM
                BankDipWdTb
        WHERE
                (ID = LAST_INSERT_ID());
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankDipWdTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `BankDipWdTb_LOADTODVG`(IN `p_TypeID` INT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code        'الرمز',
          A.InsertDate  'التاريخ',
          B.AccName     'من حساب',
          C.AccName     'إلى حساب',
          A.BillVal     'القيمة',
          A.DiscountVal 'العمولة',
          A.TypeID
  FROM
          BankDipWdTb AS A
      LEFT OUTER JOIN
        AccountsTb AS B
          ON A.AccFrom = B.AccID
      LEFT OUTER JOIN
        AccountsTb AS C
          ON A.AccTo = C.AccID
  WHERE
          A.TypeID = p_TypeID
          AND A.BranchID = p_BranchID
          AND A.IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankDipWdTb_MaxID`;
DELIMITER //
CREATE PROCEDURE `BankDipWdTb_MaxID`(IN `p_TypeID` TINYINT UNSIGNED, IN `p_BranchID` INT)
BEGIN
DECLARE v_Code LONGTEXT;


	START TRANSACTION;
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '0', CAST(p_TypeID AS CHAR), '-', CAST(BankDipWdTb_GetMaxCODEID(p_TypeID) AS CHAR));
	SELECT
			v_Code								  AS Code,
			BankDipWdTb_GetMaxCODEID(p_TypeID) AS ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankDipWdTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `BankDipWdTb_SelectByCode`(IN `p_Code` LONGTEXT, IN `p_TypeID` INT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code,
			A.InsertDate,
			A.BranchID,
			B.BName,
			A.SafeAccID,
			C.AccName				   AS SafeName,
			A.AccFrom,
			D.AccName				   AS FromName,
			A.AccTo,
			E.AccName				   AS ToName,
      e.AccParent,
			A.CurrencyID,
			F.CurrencyName,
			A.BillVal,
			A.IsDiscount,
			A.DiscountFrom,
			A.DiscountType,
			A.OverAllTotal,
			A.DiscountVal,
			A.BillNo,
			Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
			A.IsActive,
			CASE 					WHEN A.IsDiscount = 0 						THEN 						'نعم' 					ELSE 					'لا' 			END						   AS IsDiscount1,
			CASE 					WHEN A.DiscountFrom = 0 						THEN 						'العميل' 					WHEN A.DiscountFrom = 1 						THEN 						'الشركة' 					ELSE 					'لا يوجد' 			END						   AS DiscountFrom1,
			CASE 					WHEN A.DiscountType = 0 						THEN 						'نقدي' 					WHEN A.DiscountType = 1 						THEN 						'من الحساب' 					ELSE 					'لا يوجد' 			END						   AS DiscountType1,
      A.OwnAccountName,
      A.OwnAccountPhone,
      A.AccParent AS AccParCode
	FROM
			BankDipWdTb AS A
		LEFT JOIN
			CoBranch AS B
				ON A.BranchID = B.ID
		LEFT JOIN
			AccountsTb AS C
				ON A.SafeAccID = C.AccID
		LEFT JOIN
			AccountsTb AS D
				ON A.AccFrom = D.AccID
		LEFT JOIN
			AccountsTb AS E
				ON A.AccTo = E.AccID
		LEFT JOIN
			CurrencyTb AS F
				ON A.CurrencyID = F.ID
	WHERE
			A.Code = p_Code
			AND A.TypeID = p_TypeID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankService_LoadALLToLKP`;
