DROP PROCEDURE IF EXISTS `BankServicesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BankServicesTb_Insert`(IN `p_ID` INT, IN `p_ServiceName` LONGTEXT, IN `p_BBranchID` INT, IN `p_InsertUser` INT, IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_ValRate` DECIMAL(12,3), IN `p_DifferentialVal` DECIMAL(12,3), IN `p_TransVal` DECIMAL(12,3))
proc: BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;

      START TRANSACTION;





        IF p_IsUpdate = 0 AND EXISTS (
            SELECT 1
            FROM BankServicesTb
            WHERE BBranchID = p_BBranchID AND ServiceName = p_ServiceName
        )
         THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = N'عذرا اسم الخدمة موجود مسبقا لنفس الفرع.';
          ROLLBACK;
          LEAVE proc;
        END IF;


        IF EXISTS (
            SELECT 1


            FROM BankServicesTb

            WHERE BBranchID = p_BBranchID
              AND (p_IsUpdate = 0 OR ID <> p_ID)
        )
         THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = N'عذرا يوجد خدمة مربوطة بهذا المصرف مسبقا';
          ROLLBACK;
          LEAVE proc;
        END IF;


        IF p_IsUpdate = 0
         THEN
            INSERT INTO BankServicesTb
            (
                ServiceName,
                BBranchID,
                InsertDate,
                InsertUser,
                IsActive,
                ValRate,
                DifferentialVal,
                TransVal
            )
            VALUES
            (
                p_ServiceName,
                p_BBranchID,
                NOW(),
                p_InsertUser,
                1,
                p_ValRate,
                p_DifferentialVal,
                p_TransVal
            );
         ELSE






            UPDATE BankServicesTb
            SET
                ServiceName     = p_ServiceName, BBranchID       = p_BBranchID, InsertDate      = NOW(), IsActive        = p_IsActive, ValRate         = p_ValRate, DifferentialVal = p_DifferentialVal, TransVal        = p_TransVal
            WHERE ID = p_ID;
        END IF;

        COMMIT;
        SET p_MSGSTatues = 1;


END //
DELIMITER ;

