DROP PROCEDURE IF EXISTS `BanksTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BanksTb_Insert`(IN `p_ID` INT, IN `p_BankName` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_CountryID` INT)
BEGIN
DECLARE v_IDcode BIGINT;
DECLARE v_AccID BIGINT;
DECLARE v_AccCustom BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_code BIGINT;
DECLARE v_BN BIGINT;
DECLARE v_AccParent BIGINT;


  START TRANSACTION;
  IF p_IsUpdate = 0
     THEN
      INSERT INTO BanksTb
            (
              BankName,
              IsActive,
              CountryID
            )
      VALUES
              (
                p_BankName, 1, p_CountryID
              );
      SELECT MAX(IFNULL(IDcode, 1)) + 1 INTO v_IDcode FROM
              AccountsTb at
      WHERE
              at.AccParent = 10105;
SET v_code = CONCAT(CAST(10105 AS CHAR), '0', CAST(v_IDcode AS CHAR));
      INSERT INTO AccountsTb
            (
              AccCode,
              AccName,
              AccType,
              Accline,
              AccParent,
              AccDmType,
              AccFinal,
              AccActive,
              BranchID,
              AccMaxLimit,
              AccMaxDuration,
              IDcode
            )
      VALUES
              (
                v_code, p_BankName, 0, 3, 10105, 0, 1, 1,0,0,0, v_IDcode
              );

      SELECT at.AccID INTO v_BN FROM
              AccountsTb at
      WHERE
              at.AccParent = 10105
              AND at.AccName = p_BankName;
      UPDATE
              BanksTb
      SET
              AccID = v_BN
      WHERE
        BanksTb.BankName = p_BankName;

      SELECT AT.AccCode INTO v_AccParent FROM
              AccountsTb AS AT
      WHERE
              AT.AccName = 'مخصصات المصارف';
      SELECT MAX(IFNULL(IDcode, 1)) + 1 INTO v_IDcode FROM
              AccountsTb at
      WHERE
              at.AccParent = v_AccParent;
SET v_code = CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('مخصص', SPACE(1), p_BankName);
      INSERT INTO AccountsTb
            (
              AccCode,
              AccName,
              AccType,
              Accline,
              AccParent,
              AccDmType,
              AccFinal,
              AccActive,
              BranchID,
                 AccMaxLimit,
              AccMaxDuration,
              IDcode
            )
      VALUES
              (

                v_code, v_AccName, 0, 3, v_AccParent, 1, 1, 1,0,0,0, v_IDcode
              );
              SELECT at.AccID INTO v_AccCustom FROM
              AccountsTb at
      WHERE
              at.AccName = CONCAT('مخصص', SPACE(1), p_BankName);
              UPDATE BanksTb SET AccCustom= v_AccCustom WHERE ID=p_ID;

      SELECT
              ID,
              BankName,
              AccID,
              IsActive
      FROM
              BanksTb
      WHERE
              (ID = LAST_INSERT_ID());
    END IF;
  IF p_IsUpdate = 1
     THEN
      SELECT at.AccID INTO v_AccID FROM
              BanksTb at
      WHERE
              ID = p_ID;

      SELECT at.AccCustom INTO v_AccCustom FROM
              BanksTb at
      WHERE
              ID = p_ID;

    END IF;
  UPDATE
          AccountsTb
  SET
          AccountsTb.AccName = p_BankName
  WHERE
    AccountsTb.AccID = v_AccID;


  UPDATE
          AccountsTb
  SET
          AccountsTb.AccName = CONCAT('مخصص', SPACE(1), p_BankName)
  WHERE
    AccountsTb.AccID = v_AccCustom;

   UPDATE
              BanksTb
      SET
              BankName = p_BankName, CountryID = p_CountryID, IsActive = 1
      WHERE
        ( ID = p_ID
          OR p_ID IS NULL);
  COMMIT;
END //
DELIMITER ;

