DROP PROCEDURE IF EXISTS `BankTransaction_Stetment`;
DELIMITER //
CREATE PROCEDURE `BankTransaction_Stetment`(IN `p_TypeID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
IF p_TypeID=0
 THEN
  SELECT
          A.Code        'الرمز',
          A.InsertDate  'التاريخ',
          B.AccName     'إيداع في حساب',
          C.AccName     'إيداع مصرفي لحساب',
          A.BillVal     'القيمة',
          A.DiscountVal 'العمولة',
          a.OwnAccountName 'مودعه من حساب',
          a.OwnAccountPhone 'رقم صاحب الحساب',
          a.BillNo 'رقم القسيمة أو الصك'


  FROM
          BankDipWdTb AS A
      LEFT OUTER JOIN
        AccountsTb AS B
          ON A.AccFrom = B.AccID
      LEFT OUTER JOIN
        AccountsTb AS C
          ON A.AccTo = C.AccID
  WHERE
          A.TypeID = 16
          AND A.InsertDate BETWEEN p_D1 AND p_D2;
          END IF;

IF p_TypeID=1
 THEN
  SELECT
          A.Code        'الرمز',
          A.InsertDate  'التاريخ',
          c.AccName     'من حساب العميل',
          b.AccName     'سحب من حساب مصرف',
          A.BillVal     'القيمة',
          A.DiscountVal 'العمولة',
          a.OwnAccountName 'صاحب الحساب المصرفي',
          a.OwnAccountPhone 'رقم صاحب الحساب',
          a.BillNo 'رقم القسيمة أو الصك'
  FROM
          BankDipWdTb AS A
      LEFT OUTER JOIN
        AccountsTb AS B
          ON A.AccFrom = B.AccID
      LEFT OUTER JOIN
        AccountsTb AS C
          ON A.AccTo = C.AccID
  WHERE
          A.TypeID = 17
                    AND A.InsertDate BETWEEN p_D1 AND p_D2;
          END IF;

IF p_TypeID=2
 THEN
  SELECT
          A.Code        'الرمز',
          A.InsertDate  'التاريخ',
          B.AccName     'من حساب مصرف',
          A.BillVal     'القيمة',
          A.DiscountVal 'العمولة',
          a.BillNo 'رقم الاشعار',
          C.AccName     'إلى حساب مصرف',
          a.Notes     'البيان'

  FROM
          BankDipWdTb AS A
      LEFT OUTER JOIN
        AccountsTb AS B
          ON A.AccFrom = B.AccID
      LEFT OUTER JOIN
        AccountsTb AS C
          ON A.AccTo = C.AccID
  WHERE
          A.TypeID = 47
                    AND A.InsertDate BETWEEN p_D1 AND p_D2;
          END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BankWithdrawal_LOADINTOLKPBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `BankWithdrawal_LOADINTOLKPBASEDONAccParent`(IN `p_BranchID` INT, IN `p_AccParent` BIGINT, IN `p_SendOrRec` TINYINT UNSIGNED, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_IsMain INT;
START TRANSACTION;


SELECT cb.IsMain INTO v_IsMain FROM  CoBranch cb WHERE cb.ID=p_BranchID;
  SELECT
          at.AccID,
          at.AccName,




Account_GetAccVal(at.AccID,p_CurrencyID,2) AS AccVal
  FROM
          AccountsTb at
          LEFT JOIN
          CoBranch cb
          ON at.AccID=cb.CurrentAccID
  WHERE
          (at.AccParent =  p_AccParent
          AND At.accActive = 1
          AND at.BranchID = p_BranchID
          AND at.AccParent <>  2010201
          AND (Account_GetAccVal(at.AccID,p_CurrencyID,2)>0 OR at.CanDebit=1 OR at.AccDmType=0 OR p_SendOrRec=1))
          OR
          (
          at.AccParent =  2010201
          AND p_AccParent= 2010201
          AND v_IsMain=1
          AND cb.BranchType=3
          AND (Account_GetAccVal(at.AccID,p_CurrencyID,2)>0 OR at.CanDebit=1 OR at.AccDmType=0 OR p_SendOrRec=1)
          )
                    OR
          (
 p_AccParent LIKE '3010%'
 AND at.AccParent LIKE '3010%'
AND at.Accline=4
AND at.BranchID=p_BranchID
          );




  COMMIT;
END //
DELIMITER ;

