DROP PROCEDURE IF EXISTS `BBranchTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BBranchTb_Insert`(IN `p_ID` INT, IN `p_BankID` INT, IN `p_BranchName` LONGTEXT, IN `p_AccountNo` VARCHAR(200), IN `p_IBAN` VARCHAR(200), IN `p_BranchID` INT, IN `p_MobileNo` LONGTEXT, IN `p_AuthorizedToSign` LONGTEXT, IN `p_DelegateID` INT, IN `p_AccID` BIGINT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_AccountType` TINYINT UNSIGNED, INOUT `p_msgIN` INT, INOUT `p_MSG` LONGTEXT, IN `p_CurrencyID` INT)
proc: BEGIN
DECLARE v_code           BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_AccParent1 LONGTEXT;
DECLARE v_Accparent2 LONGTEXT;
DECLARE v_AccName        LONGTEXT;
DECLARE v_CheckName      INT;
DECLARE v_OldeBranchName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_acccode DECIMAL(18, 0);
DECLARE v_BName LONGTEXT;
DECLARE v_AccIDAllowance BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_msgIN = 0; END;


      START TRANSACTION;




      SELECT COUNT(*) INTO v_AccParent1 FROM
              AccountsTb at
          INNER JOIN
            BanksTb bt
              ON at.AccName = bt.BankName
      WHERE
              at.AccParent = 10105
              AND at.AccName = bt.BankName;
      SELECT COUNT(*) INTO v_Accparent2 FROM
              AccountsTb at
          INNER JOIN
            BanksTb bt
              ON RIGHT(at.AccName, 4) = RIGHT(bt.BankName, 4)
      WHERE
              at.AccParent = 20104
              AND at.AccName = CONCAT('مخصص', SPACE(1), bt.BankName);
      IF p_IsUpdate = 0
         THEN
          IF p_AccountType = 0
             THEN
              SELECT COUNT(bt.BranchName) INTO v_CheckName FROM
                      BBranchTb bt
              WHERE
                      ID = p_ID
                      AND bt.BankID = p_BankID;
              IF v_CheckName > 0
                 THEN
                  SET p_msgIN = 0;
                  SET p_MSG = 'عذراً هذا الاسم موجود مسبقاً';
                  ROLLBACK;
                  LEAVE proc;
                END IF;
            END IF;
          IF p_AccountType = 1
             THEN
              SELECT COUNT(bt.BranchName) INTO v_CheckName FROM
                      BBranchTb bt
              WHERE
                      ID = p_ID
                      AND bt.BankID = p_BankID
                      AND bt.AccountNo = p_AccountNo;
              IF v_CheckName > 0
                 THEN
                  SET p_msgIN = 0;
                  SET p_MSG = 'عذراً هذا الاسم موجود مسبقاً';
                  ROLLBACK;
                  LEAVE proc;
                END IF;
            END IF;
          INSERT INTO BBranchTb
                (
                  BankID,
                  BranchName,
                  AccountNo,
				  IBAN,
                  BranchID,
                  MobileNo,
                  AuthorizedToSign,
                  DelegateID,
                  AccID,
                  IsActive,
                  AccountType,
                  CurrencyID
                )
          VALUES
                  (
                    p_BankID, p_BranchName, p_AccountNo,p_IBAN, p_BranchID, p_MobileNo, p_AuthorizedToSign, p_DelegateID, p_AccID, 1, p_AccountType,p_CurrencyID
                  );
          IF v_AccParent1 > 0
             THEN
              SELECT at.AccCode INTO v_IDParent FROM
                      AccountsTb at
                  INNER JOIN
                    BanksTb bt
                      ON at.AccName = bt.BankName
              WHERE
                      at.AccParent = 10105
                      AND bt.ID = p_BankID;
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_code = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode,
                      AccountsTb.AccPhone,
                      AccountsTb.AccMobile,
                      AccCurID
                    )
              VALUES
                      (
                        v_code, CASE WHEN  p_AccountType = 1 THEN CONCAT(p_BranchName, SPACE(1), '-', SPACE(1), p_AccountNo) ELSE p_BranchName END, 1, 4, v_IDParent, 0, 1, 0, 0, p_BranchID, 1, v_IDcode, p_MobileNo, p_MobileNo,p_CurrencyID
                      );
              SELECT at.AccID INTO p_AccID FROM
                      AccountsTb at

              WHERE
                      at.AccName = CASE                               WHEN (p_AccountType = 0 OR p_AccountType=2)                                 THEN                                 p_BranchName                               WHEN p_AccountType = 1                                 THEN                                 CONCAT(p_BranchName, SPACE(1), '-', SPACE(1), p_AccountNo)                       END;
              UPDATE
                      BBranchTb
              SET
                      AccID = p_AccID
              WHERE
                BBranchTb.ID = p_ID;
            END IF;


          IF v_Accparent2 > 0
             THEN
              SELECT at.AccCode INTO v_IDParent FROM
                      AccountsTb at
                  INNER JOIN
                    BanksTb bt
                      ON RIGHT(at.AccName, 4) = RIGHT(bt.BankName, 4)
              WHERE
                      at.AccParent = 20104
                      AND bt.ID = p_BankID;
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_code = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode,
                      AccountsTb.AccPhone,
                      AccountsTb.AccMobile,
                      AccCurID
                    )
              VALUES
                      (
                        v_code, CASE   WHEN p_AccountType = 1 THEN CONCAT('مخصص', SPACE(1), p_BranchName, '-', SPACE(1), p_AccountNo) ELSE CONCAT('مخصص', SPACE(1), p_BranchName) END, 1, 4, v_IDParent, 1, 1, 0, 0, p_BranchID, 1, v_IDcode, p_MobileNo, p_MobileNo,p_CurrencyID
                      );
              SELECT at.AccID INTO v_AccIDAllowance FROM
                      AccountsTb at
              WHERE
                      at.AccName = CASE                               WHEN (p_AccountType = 0 OR p_AccountType=2)                                 THEN                                 CONCAT('مخصص', SPACE(1), p_BranchName)                               WHEN p_AccountType = 1                                 THEN                                 CONCAT('مخصص', SPACE(1), p_BranchName, '-', SPACE(1), p_AccountNo)                       END;
              UPDATE
                      BBranchTb
              SET
                      AccIDBBranchAllowance = v_AccIDAllowance
              WHERE
                ID = p_ID;
            END IF;
        END IF;
      IF p_IsUpdate = 1
         THEN

          SELECT bt.BranchName INTO v_OldeBranchName FROM
                  BBranchTb bt
          WHERE
                  bt.ID = p_ID;





          SELECT at.AccID INTO p_AccID FROM
                  BBranchTb at
          WHERE
                  ID = p_ID;

          SELECT a.AccCode INTO v_IDParent FROM
                  AccountsTb AS a
              LEFT JOIN
                BanksTb AS b
                  ON a.AccName = b.BankName
          WHERE
                  b.ID = p_BankID;

          SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                  AccountsTb AS a
              LEFT JOIN
                BanksTb AS b
                  ON a.AccName = b.BankName
          WHERE
                  AccParent = v_IDParent;



          SELECT at.AccIDBBranchAllowance INTO v_AccIDAllowance FROM
                  BBranchTb at
          WHERE
                  ID = p_ID;
          SELECT a.AccCode INTO v_IDParent FROM
                  AccountsTb AS a
              INNER JOIN
                BanksTb AS b
                  ON a.AccName = CONCAT('مخصص', SPACE(1), b.BankName)
          WHERE
                  b.ID = p_BankID;


          IF v_OldeBranchName <> p_BranchName
             THEN
              UPDATE
                      AccountsTb
              SET
                      AccountsTb.AccName = p_BranchName,
                      AccountsTb.BranchID = p_BranchID
              WHERE
                AccountsTb.AccID = p_AccID;




              UPDATE
                      AccountsTb
              SET
                      AccountsTb.AccName = CONCAT('مخصص', SPACE(1), p_BranchName),
                      AccountsTb.BranchID = p_BranchID
              WHERE
                AccountsTb.AccID = v_AccIDAllowance;
            END IF;








































          UPDATE
                  BBranchTb
          SET
                  BankID = p_BankID, BranchName = p_BranchName, AccountNo = p_AccountNo, IBAN=p_IBAN, BranchID = p_BranchID, MobileNo = p_MobileNo, AuthorizedToSign = p_AuthorizedToSign, DelegateID = p_DelegateID, AccID = p_AccID, IsActive = p_IsActive, AccountType = p_AccountType
          WHERE
            ( ID = p_ID
              OR p_ID IS NULL);
        END IF;
      COMMIT;
      SET p_msgIN = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BBranchTb_LOADBASEDCURRENCY`;
DELIMITER //
CREATE PROCEDURE `BBranchTb_LOADBASEDCURRENCY`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_Action` INT)
BEGIN
START TRANSACTION;
  IF p_Action = 0
     THEN
      SELECT
              a.AccID,
              a.BranchName AS AccName

      FROM
              BBranchTb AS a


      WHERE
              a.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID
              AND a.IsActive = 1;
    END IF;
  IF p_Action = 1
     THEN
      SELECT
              a.AccID,
              a.BranchName AS AccName

      FROM
              BBranchTb AS a
          INNER JOIN
            NewCurrencyPricesOwnTb AS b
              ON a.ID = b.BankID

      WHERE
              a.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID
              AND a.IsActive = 1;
    END IF;
  IF p_Action = 2
     THEN
      SELECT
              a.CUID                                 AS AccID,
              CONCAT(b.cuBankName, SPACE(1), a.CUBranchName) AS AccName
      FROM
              BBranchCurrencyBuyAndSaleTb AS a
          INNER JOIN
            CURRENCYBYANDSALEBanksTb AS b
              ON a.cuBankID = b.cuID
      WHERE

              a.cuIsActive = 1;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BBranchTb_LoadBasedOnServices`;
DELIMITER //
CREATE PROCEDURE `BBranchTb_LoadBasedOnServices`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
  SELECT
          a.ID,
          a.BranchName,
          a.AccID,
          IFNULL(b.ValRate,0) AS ValRate,
          IFNULL(b.DifferentialVal,0) AS DifferentialVal ,
          IFNULL(b.TransVal,0) AS TransVal,
          a.BankID,
          b.ID AS SID
  FROM
          BBranchTb AS a
          INNER JOIN
          BankServicesTb b
          ON a.ID=b.BBranchID
  WHERE
          a.IsActive = 1
          AND a.AccountType = 1
          AND BranchID = p_BranchID;

  COMMIT;
END //
DELIMITER ;

