DROP PROCEDURE IF EXISTS `BBranchTb_LOADTOGITHER`;
DELIMITER //
CREATE PROCEDURE `BBranchTb_LOADTOGITHER`()
BEGIN
START TRANSACTION;

  SELECT
          B.AccID,
          CONCAT(B.BankName, SPACE(1), A.BranchName) AS BranchName
  FROM
          BBranchTb AS A
      LEFT JOIN
        BanksTb AS B
          ON A.BankID = B.ID

  ORDER BY
          BranchName;

  COMMIT;
END //
