DROP PROCEDURE IF EXISTS `Branch_GetCurrBenefits`;
DELIMITER //
CREATE PROCEDURE `Branch_GetCurrBenefits`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_MainCountry INT;


	START TRANSACTION;

SELECT ct.ID INTO v_MainCountry FROM CountiresTb ct WHERE ct.IsMain=1;

SELECT
			a.ISID							AS 'الرمز',
      a.SafeIDMovement  AS 'طبيعة الحركة',
      c.salesPurchaseprice AS 'سعر البيع',
			FORMAT(a.Credit, 3) AS 'الإيراد',
			FORMAT(a.Debit, 3)  AS 'الخسارة'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
	INNER JOIN
			ExSyAccountsCurrency_CurrencymovementPruse AS c
				ON a.ISID  = c.ISID
WHERE
			b.BranchID = p_BranchID
      AND a.IsActive=1
      AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
      AND a.TypeID<>38
			AND (   b.AccCode LIKE '3%' OR  b.AccCode LIKE '4%')
AND c.CountryID=v_MainCountry
AND (c.ACCFRom=p_CurrencyID OR p_CurrencyID=0);

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Branch_GetInteralBenefits`;
DELIMITER //
CREATE PROCEDURE `Branch_GetInteralBenefits`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;























































































































SELECT

			a.ISID							AS 'الرمز',
      b.AccName AS 'اسم الحساب',










			FORMAT(a.Credit, 3) AS 'الإيراد',
			FORMAT(a.Debit, 3)  AS 'الخسارة'

	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID






WHERE
			b.BranchID = p_BranchID
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
      AND a.IsActive=1
      AND a.TypeID<>38
			AND (   b.AccCode LIKE '3%' OR  b.AccCode LIKE '4%');

















	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Branch_GetInteralExBenefits`;
DELIMITER //
CREATE PROCEDURE `Branch_GetInteralExBenefits`()
BEGIN
START TRANSACTION;
	SELECT
			a.Code,
			a.BranchRecievedID,
			a.BranchDeliveredID,
			a.ExVal
	FROM
			InternalEx AS a
	WHERE
			NOT EXISTS (SELECT
						b.Code
				FROM
						CanceledInternalExTb AS b
				WHERE
						a.Code = b.Code);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTb_Insert`(IN `p_ID` BIGINT, IN `p_FBranchID` INT, IN `p_FBRate` DECIMAL(12,3), IN `p_SBranchID` INT, IN `p_SBRate` DECIMAL(12,3), IN `p_IsUpdate` TINYINT(1))
BEGIN
DECLARE v_MAXBID INT;
DECLARE v_PREMAXBID INT;
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO BranchRatesTb
					(
						FBranchID,
						FBRate,
						SBranchID,
						SBRate
					)
				SELECT
						p_FBranchID,
						p_FBRate,
						p_SBranchID,
						p_SBRate;
			INSERT INTO BranchRatesTb
					(
						FBranchID,
						FBRate,
						SBranchID,
						SBRate
					)
				SELECT
						p_SBranchID,
						p_SBRate,
						p_FBranchID,
						p_FBRate;

			TRUNCATE TABLE BranchRatesTempTb;
			UPDATE
					CoBranch
			SET
					IsRated = 1
			WHERE
				ID = p_FBranchID;
			SELECT MAX(ID) - 1 INTO v_PREMAXBID FROM
					CoBranch cb;
			IF p_FBranchID = v_PREMAXBID
				 THEN
					SELECT MAX(ID) INTO v_MAXBID FROM
							CoBranch cb;
					UPDATE
							CoBranch
					SET
							IsRated = 1
					WHERE
						ID = v_MAXBID;
				END IF;
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					BranchRatesTb
			SET
					FBRate = p_FBRate, SBRate = p_SBRate
			WHERE
				ID = p_ID;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTb_LoadFBranchToLKP`;
