DROP PROCEDURE IF EXISTS `BranchRatesTb_LoadSBranchToLKP`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTb_LoadSBranchToLKP`(IN `p_ID` INT, IN `p_IsExist` TINYINT(1))
BEGIN
DECLARE v_otherID INT;
START TRANSACTION;
	IF p_IsExist = 0
		 THEN
			SELECT
					ID,
					a.BName
			FROM
					CoBranch AS a
			WHERE
					ID <> p_ID
					AND (   NOT EXISTS (SELECT
										*
								FROM
										BranchRatesTb
								WHERE
										(		SBranchID = a.ID
												AND FBranchID = p_ID))
							OR NOT EXISTS (SELECT
										*
								FROM
										BranchRatesTb
								WHERE
										(		FBranchID = a.ID
												AND SBranchID = p_ID))
					);
		END IF;
	IF p_IsExist = 1
		 THEN
			SELECT
					a.ID,
					a.BName
			FROM
					CoBranch AS a
			WHERE
					a.ID <> p_ID
					AND a.ID NOT IN (SELECT
								BrID
						FROM
								BranchRatesTempTb)
					AND a.ID NOT IN (SELECT
								FBranchID
						FROM
								BranchRatesTb
						WHERE
								SBranchID = p_ID);
		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTb_LoadToUpdate`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTb_LoadToUpdate`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS RowHandle,
			b.BName								  AS FBranchName,
			a.FBranchID                           AS FBranchID,
			a.FBRate,
			c.BName								  AS SBranchName,
			a.SBranchID                           AS SBranchID,
			a.SBRate,
			a.ID								  AS TBID
	FROM
			BranchRatesTb AS a
		LEFT OUTER JOIN
			CoBranch AS b
				ON a.FBranchID = b.ID
		LEFT OUTER JOIN
			CoBranch AS c
				ON a.SBranchID = c.ID
	WHERE
			(		a.FBranchID = p_BranchID
					OR a.SBranchID = p_BranchID);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTempTb_Delete`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTempTb_Delete`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	DELETE FROM
	BranchRatesTempTb
	WHERE
			BrID = p_BranchID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTempTb_Insert`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTempTb_Insert`(IN `p_BrID` INT)
BEGIN
START TRANSACTION;

	INSERT INTO BranchRatesTempTb
			(
				BrID
			)
		SELECT
				p_BrID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BranchRatesTempTb_Truncate`;
DELIMITER //
CREATE PROCEDURE `BranchRatesTempTb_Truncate`(IN `p_BranchID` INT)
BEGIN
DECLARE v_FBID INT;
DECLARE v_SBID INT;
START TRANSACTION;
  TRUNCATE TABLE BranchRatesTempTb;
  UPDATE
          CoBranch
  SET
          IsRated = 0
  WHERE
    ID = p_BranchID;
  SELECT brt.FBranchID INTO v_FBID FROM
          BranchRatesTb brt
  WHERE
          brt.FBranchID = p_BranchID
 ORDER BY brt.ID DESC LIMIT 1;
  SELECT brt.SBranchID INTO v_SBID FROM
          BranchRatesTb brt
  WHERE
          brt.SBranchID = p_BranchID
 ORDER BY brt.ID DESC LIMIT 1;
  IF (p_BranchID = v_FBID
    OR
    p_BranchID = v_SBID)
     THEN
      DELETE FROM
      BranchRatesTb
      WHERE
              ( FBranchID = p_BranchID
                OR SBranchID = p_BranchID);
    END IF;
  COMMIT;
END //
DELIMITER ;

