= AccID WHERE  AccCode = '20105' group by  AccName  , AccID ,BranchID ,AccDmType UNION SELECT AccName ,  SUM(Credit ) - SUM(Debit)  , AccID ,BranchID ,AccDmType   from   `AccountsTb` as  A INNER JOIN `AccountsTb` AS B ON AccCode = AccParent INNER JOIN `AccountsTb` AS C ON AccCode = AccParent inner join  ExSyAccounts_AccSafeActivityTb as d on AccIDFrom = AccID WHERE  AccCode = '201010' group by  AccName  , AccID ,BranchID ,AccDmType union SELECT AccName ,  SUM(Credit ) - SUM(Debit)  , AccID ,BranchID ,AccDmType   from   `AccountsTb` as  A INNER JOIN `AccountsTb` AS B ON AccCode = AccParent INNER JOIN `AccountsTb` AS C ON AccCode = AccParent inner join  ExSyAccounts_AccSafeActivityTb as d on AccIDFrom = AccID WHERE  AccCode = '20401' AND AccCode <> '2040102' and AccCode <> '204010302' group by  AccName  , AccID ,BranchID ,AccDmType union select  CONCAT('صافي قائمة الدخل', SPACE(1), BName) as BName  ,  sum(Credit )  - SUM(Debit)   as TenTotel , 4 , ID , 1   from AccountsTb as a inner join  ExSyAccounts_AccSafeActivityTb as b on AccID = AccIDFrom inner join CoBranch as c on BranchID = ID where AccFinal	 = 0 group by  BName ,ID ) AS Z WHERE  ( BranchID = p_BranchID  OR p_BranchID = 0   )  and AccDmType = 1 union SELECT   SUM(Credit ) - SUM(Debit)    from   `AccountsTb` as  A inner join  ExSyAccounts_AccSafeActivityTb as d on AccIDFrom = AccID WHERE  AccParent = '2010201'  and AccBranchID =  p_BranchID group by  AccName  , AccID ,BranchID ,AccDmType ) as xx;


 SELECT IFNULL(  sum (TenTotel) , 0.0) INTO p_sumorDebit FROM (

