DROP PROCEDURE IF EXISTS `BuyCurrency2026_LOADINTOLKPBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `BuyCurrency2026_LOADINTOLKPBASEDONAccParent`(IN `p_Action` INT, IN `p_BranchID` INT, IN `p_AccParent` BIGINT, IN `p_SendOrRec` TINYINT UNSIGNED, IN `p_CurrencyID` INT, IN `p_CountryID` INT, IN `p_PriceType` INT)
BEGIN
DECLARE v_BrMain INT;
SELECT cb.ID INTO v_BrMain FROM CoBranch cb WHERE cb.IsMain=1;

IF p_Action=0
 THEN
IF p_AccParent=2010201
 THEN
SELECT
          at.AccID,
          at.AccName,
          IFNULL(at.AccPhone,'0') AS AccPhone,
          IFNULL(at.AccMobile,'0') AS AccMobile,
          IFNULL(at.AccIDNo,'') AS AccIDNo,
          IFNULL(at.AccNatNumber,'') AS AccNatNumber ,
          Account_GetAccVal(at.AccID,p_CurrencyID,0) AS GetAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,1) AS GetBankAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,2) AS AccVal,
Account_GetAccVal_BuyCurrncey2026(at.AccID,p_CurrencyID,p_PriceType,p_CountryID,p_BranchID,p_AccParent) AS CurrAccVal
        FROM
        AccountsTb at
        INNER JOIN
        CoBranch  b ON at.AccID = b.CurrentAccID
        WHERE b.BranchType=3
        AND v_BrMain=p_BranchID
        AND (((Account_GetAccVal(at.AccID,p_CurrencyID,2)>0 AND p_CurrencyID=1 ) OR (Account_GetAccVal_BuyCurrncey2026(at.AccID,p_CurrencyID,p_PriceType,p_CountryID,p_BranchID,p_AccParent)>0 AND p_CurrencyID<>1) )  OR ( at.CanDebit=1 AND p_CurrencyID=1) OR at.AccDmType=0 OR p_SendOrRec=1);
        END IF;
IF p_AccParent<>2010201
 THEN
  SELECT
          at.AccID,
          at.AccName,
          IFNULL(at.AccPhone,'0') AS AccPhone,
          IFNULL(at.AccMobile,'0') AS AccMobile,
          IFNULL(at.AccIDNo,'') AS AccIDNo,
          IFNULL(at.AccNatNumber,'') AS AccNatNumber ,
          Account_GetAccVal(at.AccID,p_CurrencyID,0) AS GetAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,1) AS GetBankAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,2) AS AccVal,
Account_GetAccVal_BuyCurrncey2026(at.AccID,p_CurrencyID,p_PriceType,p_CountryID,p_BranchID,p_AccParent) AS CurrAccVal
  FROM
          AccountsTb at
          LEFT JOIN
          BBranchTb b
          ON at.AccID = b.AccID
  WHERE
          ((at.AccParent =  p_AccParent AND (Account_GetAccVal(at.AccID,p_CurrencyID,2)>0 OR ( at.CanDebit=1 AND p_CurrencyID=1) OR at.AccDmType=0 OR p_SendOrRec=1) )
          OR (p_AccParent=0 AND (p_PriceType<>1 OR p_SendOrRec=1) AND at.AccParent LIKE '10104%') OR (p_AccParent=0 AND  p_PriceType=1 AND p_SendOrRec=0 AND at.AccParent LIKE '101012%' AND at.AccCurID =p_CurrencyID AND at.CountryID=p_CountryID))
          AND At.accActive = 1
          AND at.BranchID = p_BranchID
          AND (IFNULL(b.AccountType,0)=0 OR b.AccountType=2)
          AND (b.CurrencyID=p_CurrencyID OR b.ID IS NULL);

END IF;
END IF;

IF p_Action=1
 THEN


SELECT cb.CountryID INTO p_CountryID FROM CoBranch cb WHERE cb.ID=p_BranchID;
SELECT
        a.AccCode,
        a.AccName,
        0 IsBank
FROM
        AccountsTb AS a
WHERE
        a.AccDmType = 1
        AND a.AccFinal = 1
        AND a.Accline = 3
        AND a.BranchID = p_BranchID
        AND a.AccParent<>20401
        AND a.AccActive = 1
        AND ((p_PriceType=1 AND a.CountryID=p_CountryID) OR (p_PriceType<>1 ))

UNION

SELECT
        a.AccCode,
        a.AccName,
        1 IsBank
        FROM
        AccountsTb a
        INNER JOIN
        BanksTb  b ON a.AccID = b.AccID
        WHERE b.CountryID=p_CountryID

UNION

SELECT
        a.AccCode,
        a.AccName,
        0 IsBank
        FROM
        AccountsTb a
        WHERE a.AccCode=2010201
        AND v_BrMain=p_BranchID;















END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `card_bookings_UPDATE_CANCEL`;
DELIMITER //
CREATE PROCEDURE `card_bookings_UPDATE_CANCEL`(IN `p_ID` INT, INOUT `p_MSGSTUTE` INT, INOUT `p_MASGEBOX` LONGTEXT, IN `p_stutes` INT, IN `p_ueserID` INT)
proc: BEGIN
DECLARE v_PEMEINT INT;
DECLARE v_GETsTAUES INT;
DECLARE v_booking_amount decimal(10, 2);
DECLARE v_bYPRASE decimal(18, 3);
DECLARE v_tOTALpRASE decimal(18, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_MSGSTUTE = 2; END;
START TRANSACTION;


SELECT payment_type, A.`status`, A.booking_amount INTO v_PEMEINT, v_GETsTAUES, v_booking_amount FROM rhalla2024Teset.`card_bookings` AS A WHERE A.ID =p_ID;


SELECT A.SalePrice INTO v_bYPRASE FROM NewCurrencyPriceOwnDetailsTb AS A  WHERE A.CurrencyIDFrom = 1 AND CurrencyIDTo = 9;
SET v_tOTALpRASE= v_booking_amount * v_bYPRASE;
IF v_GETsTAUES <> 0
 THEN
SET p_MSGSTUTE = 0;
SET p_MASGEBOX = 'عذرا تم لايمكن قبول هذه الحوالة الان تمت الموافقة عليها مسبقا او الغاءها';
ROLLBACK;
LEAVE proc;
END IF;
UPDATE rhalla2024Teset.`card_bookings`
   SET
