 WHERE id = p_ID;






































































commit;
SET p_MSGSTUTE = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Cash_BankTransfersTB_CRUD`;
DELIMITER //
CREATE PROCEDURE `Cash_BankTransfersTB_CRUD`(IN `p_Action` INT, IN `p_Code` VARCHAR(250), IN `p_ID` INT, IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_TransType` INT, IN `p_ParentID` BIGINT, IN `p_AccID` BIGINT, IN `p_TransVal` DECIMAL(18,3), IN `p_Notes` LONGTEXT, IN `p_UserID` INT, IN `p_IsActive` TINYINT(1))
proc: BEGIN
DECLARE v_IsBank INT;
DECLARE v_OPType INT;
DECLARE v_movType LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;







        IF p_Action = 0
         THEN
            SELECT
                ID,
                Code,
                InseretDate,
                BranchID,
                CurrencyID,
                TransType,
                ParentID,
                AccID,
                TransVal,
                Notes,
                IsActive
            FROM Cash_BankTransfersTB
            WHERE
                  (BranchID  = p_BranchID  OR p_BranchID  IS NULL)
              AND (CurrencyID = p_CurrencyID OR p_CurrencyID IS NULL)
              AND (TransType = p_TransType OR p_TransType IS NULL)
              AND (Code = p_Code OR p_Code IS NULL)
              AND (IsActive = p_IsActive OR p_IsActive IS NULL);
         ELSEIF  p_Action = 1
         THEN


            IF EXISTS(SELECT 1 FROM Cash_BankTransfersTB WHERE Code = p_Code)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='الكود موجود مسبقاً، الرجاء إعادة الحفظ';
                LEAVE proc;
            END IF;


            IF p_TransType = 1
             THEN
                IF TestAccount_CanUseVal(p_AccID, p_CurrencyID, 1, p_TransVal) = 0
                 THEN
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='عذراً، الرصيد المصرفي للحساب غير كافٍ لإجراء العملية';
                    LEAVE proc;
                END IF;
            END IF;

SET v_IsBank=Case WHEN p_TransType=0 THEN  1 ELSE 0  END;
SET v_OPType=Case WHEN p_TransType=0 THEN  96 ELSE 97  END;
SELECT ott.OperationType INTO v_movType FROM OperationTypeTb ott WHERE ott.ID=v_OPType;

            INSERT INTO Cash_BankTransfersTB
            (
                Code, BranchID, CurrencyID, TransType, ParentID, AccID,
                TransVal, Notes, IsActive
            )
            VALUES
            (
                p_Code, p_BranchID, p_CurrencyID, p_TransType, p_ParentID, p_AccID,
                p_TransVal, p_Notes, 1
            );





INSERT INTO ExSyAccounts_AccSafeActivityTb
  (
    SafeID,
    Debit,
    Credit,
    InsertDate,
    DESCRIPTION,
    ISID,
    TypeID,
    OperationTypeID,
    AccBranchID,
    AccIDFrom,
    AccIDTo,
    MovementType,
    CurrencyID,
    Note,
    SafeIDMovement,
    IsBank
  )
VALUES
        (
          p_UserID, p_TransVal, 0,  NOW(), p_Notes, p_Code,  58, v_OPType, p_BranchID, p_AccID, p_AccID, v_movType,p_CurrencyID, p_Notes, v_movType,p_TransType
        );




INSERT INTO ExSyAccounts_AccSafeActivityTb
  (
    SafeID,
    Debit,
    Credit,
    InsertDate,
    DESCRIPTION,
    ISID,
    TypeID,
    OperationTypeID,
    AccBranchID,
    AccIDFrom,
    AccIDTo,
    MovementType,
    CurrencyID,
    Note,
    SafeIDMovement,
    IsBank
  )
VALUES
        (
          p_UserID,0, p_TransVal,   NOW(), p_Notes, p_Code,  58, v_OPType, p_BranchID, p_AccID, p_AccID, v_movType,p_CurrencyID, p_Notes, v_movType,v_IsBank
        );

         ELSEIF  p_Action = 2
         THEN
            UPDATE Cash_BankTransfersTB
            SET IsActive = 0
            WHERE Code = p_Code;


            INSERT INTO AccSafeActivityTb
            (
                SafeID, Debit, Credit, ISID, TypeID, OperationTypeID,
                AccBranchID, AccIDFrom, AccIDTo, MovementType,
                CurrencyID, Note, EXID, IsBank
            )
            SELECT
                p_UserID,
                a.Credit,
                a.Debit,
                a.ISID,
                59,
                98,
                a.AccBranchID,
                a.AccIDTo,
                a.AccIDFrom,
                N'عكس عملية تحويل نقد/مصرف',
                a.CurrencyID,
                a.Note,
                0,
                a.IsBank
            FROM AccSafeActivityTb a
            WHERE a.ISID = p_Code;
         ELSEIF  p_Action = 3
         THEN
            SELECT
                t.Code 'الرمز',
                t.InseretDate 'التاريخ',
                b.BName 'الفرع',
                c.CuName 'العملة',
                CASE t.TransType WHEN 1 THEN N'مصرف ← نقد' ELSE N'نقد ← مصرف' END 'نوع التحويل',
                a.AccName 'الحساب',
                t.TransVal 'القيمة',
                t.Notes 'ملاحظات'
            FROM Cash_BankTransfersTB t
            LEFT JOIN CoBranch b ON t.BranchID = b.ID
            LEFT JOIN CurrencyMainTb  c ON t.CurrencyID = c.ID
            LEFT JOIN AccountsTb a ON t.AccID = a.AccID
            WHERE
                  (t.BranchID = p_BranchID OR p_BranchID IS NULL)
              AND (t.CurrencyID = p_CurrencyID OR p_CurrencyID IS NULL)
              AND (t.Code = p_Code OR p_Code IS NULL)
              AND (t.IsActive = p_IsActive OR p_IsActive IS NULL);
        END IF;






END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CashMonment_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `CashMonment_LOADTODVG`(IN `p_BranchID` INT, IN `p_accTIPE` INT, IN `p_CurrencyID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;

  IF p_accTIPE = 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY A.Code ASC)       AS '#',
              A.Code                     AS 'الرمز',
              A.InsertDate               'التاريخ',
              A.WDVAL                    'القيمة',
              CONCAT('لحساب/', ' ', c.AccName) AS 'لحساب',
              B.UName                    'المستخدم',
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END                        AS 'الملاحظات'
      FROM
              EMPORCUSTWITHDRAWALTB AS A
          INNER JOIN
            TB_Users AS B
              ON A.SafeID = B.AccID
          INNER JOIN
            AccountsTb AS c
              ON A.EMPID = c.AccID
      WHERE
              A.BranchID = p_BranchID
              AND A.CurrencyFrom = p_CurrencyID
              AND (A.TypeID = 5)
              AND A.IsActive = 1
              AND (A.InsertDate BETWEEN p_D1 AND p_D2)

      ORDER BY
              'التاريخ';
    END IF;
  IF p_accTIPE = 1
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY A.Code ASC)       AS '#',
              A.Code                     AS 'الرمز',
              A.InsertDate               'التاريخ',
              A.WDVAL                    'القيمة',
              CONCAT('لحساب/', ' ', c.AccName) AS 'لحساب',
              B.UName                    'المستخدم',
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END                        AS 'الملاحظات'
      FROM
              EMPORCUSTWITHDRAWALTB AS A
          INNER JOIN
            TB_Users AS B
              ON A.SafeID = B.AccID
          INNER JOIN
            AccountsTb AS c
              ON A.EMPID = c.AccID
      WHERE
              A.BranchID = p_BranchID
              AND A.CurrencyFrom = p_CurrencyID
              AND (A.TypeID = 7)
              AND A.IsActive = 1
              AND (A.InsertDate BETWEEN p_D1 AND p_D2)

      ORDER BY
              'التاريخ';
    END IF;



  IF p_accTIPE = 2
     THEN
      SELECT

      DISTINCT
              a.Code               AS 'الرمز',
              ROW_NUMBER() OVER (
              ORDER BY a.Code ASC) AS '#',
              a.InsertDate         'التاريخ',
              a.ExpensVal          'القيمة',
              B.UName              'المستخدم',

              CASE                       WHEN c.SafeIDMovement = ''                         THEN                         'لا يوجد'                       ELSE                       c.SafeIDMovement               END                  AS 'طبيعة الحركة',
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END                  AS 'الملاحظات'


      FROM
              ANOTHEREXPENSTB AS a
          INNER JOIN
            TB_Users AS B
              ON a.AccSafeID = B.AccID
          inner JOIN
            ExSyAccounts2026.`AccSafeActivityTb` AS c
              ON a.Code = c.isid
          LEFT JOIN
            ExpensesTb AS d
              ON a.AccIDPC = d.AccID
      WHERE
              a.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID
              AND (a.InsertDate BETWEEN p_D1 AND p_D2)
              AND a.IsActive = 1
      ORDER BY
              a.InsertDate;
    END IF;

  IF p_accTIPE = 3
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.Code ASC) AS '#',
              a.Code               AS 'الرمز',
              a.TransDate          'التاريخ',
              c.AccName            AS 'من حساب',
              d.AccName            AS 'إلى حساب',
              a.TransValue         'القيمة',
              0.000                AS 'العمولة',
              B.UName              'المستخدم'









      FROM
              TransBetweenAccountsTB AS a
          INNER JOIN
            TB_Users AS B
              ON a.SAFEID = B.USID
          INNER JOIN
            AccountsTb AS c
              ON a.TransFrom = c.AccID
          INNER JOIN
            AccountsTb AS d
              ON a.TransTo = d.AccID
      WHERE
              a.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID
              AND (a.TransDate BETWEEN p_D1 AND p_D2)
              AND a.IsActive = 1
      ORDER BY
              a.TransDate;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Cashstatement`;
DELIMITER //
CREATE PROCEDURE `Cashstatement`()
BEGIN
START TRANSACTION;


      SELECT
                    x.BName AS Bname              ,
      IFNULL(Sum(x.Incomming),0.000)  AS Incomming,
              IFNULL(Sum(x.Total),0)             AS Total,

              IFNULL(Sum(x.Total),0)-IFNULL(Sum(x.Incomming),0.000) AS NetTotal,
              AccBranchID,
              0 AS Typeid
      FROM
              (   SELECT
                                                    b.AccBranchID AS AccBranchID,
                          IFNULL(SUM(b.Debit), 0) - IFNULL(SUM(b.Credit), 0) AS Total,
                          0.000 AS Incomming,
                          '' AS Code,
                           c.BName
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccounts_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                                                                              LEFT JOIN
                        CoBranch AS c
                            ON b.AccBranchID = c.ID
                  WHERE
                          NOT EXISTS (SELECT
                                      b.AccID
                              FROM
                                      TB_Users AS b
                              WHERE
                                      a.AccID = b.AccID)
AND b.IsActive=1
                          AND a.AccParent = 1010101
                          AND Accline = 4
                          AND (   b.CurrencyID = 1
                                  OR b.CurrencyID = 13)
                  GROUP BY
b.AccBranchID,
                          c.BName,
                          b.CurrencyID

                  UNION

                  SELECT

                           a.AccBranchID AS AccBranchID,
                          IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(A.Credit), 0) AS Total,
                          0.000 AS Incomming,
                           '' AS Code,
                           c.BName

                  FROM
                          ExSyAccounts_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                                                  LEFT JOIN
                        CoBranch AS c
                            ON a.AccBranchID = c.ID
                  WHERE
                          A.IsActive = 1
                          AND LEFT(b.AccParent, 5) = 10104
                          AND a.DailyClosed = 0
                  GROUP BY
a.AccBranchID,
                         c.BName


                          UNION

                  SELECT

                          a.BranchDeliveredID AS AccBranchID,
                          0 AS Total,
a.OverallVal AS Incomming,
a.Code,
c.BName


                  FROM
                          InternalEx AS a
                      LEFT JOIN
                        CoBranch AS c
                            ON a.BranchDeliveredID = c.ID
                  WHERE
                          a.IsCanceled = 0
                          AND a.ConfirmType = 1
                          AND c.BranchType<>3
                          AND a.IsActive=1


                  GROUP BY
a.BranchDeliveredID,
                         c.BName,
                         a.Code,
                         a.OverallVal


                         ) x
                         GROUP BY
                         x.AccBranchID,
                         x.BName
UNION

SELECT
             a.Bname ,
                  0.000  AS Incomming,
              0.000            AS Total,
             IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000) AS NetTotal,
             a.ID AS AccBranchID,
             1 AS Typeid
        FROM `CoBRAnch` AS a
        INNER JOIN ExSyAccounts_AccSafeActivityTb AS b
          ON a.CurrentAccID = b.AccIDFrom
       WHERE
          a.IsActive = 1
         AND b.IsActive = 1
         AND a.BranchType=3
      GROUP BY a.CurrentAccID,
               a.Bname,
			    a.ID


ORDER BY Typeid, AccBranchID;
  COMMIT;
END //
DELIMITER ;

