DROP PROCEDURE IF EXISTS `CATEGORYTYPESDETAILSTB_GET_ServiceExVal`;
DELIMITER //
CREATE PROCEDURE `CATEGORYTYPESDETAILSTB_GET_ServiceExVal`(IN `p_ServiceID` INT, IN `p_BetweenVal` DECIMAL(18,3), INOUT `p_IsHasEXVal` INT, INOUT `p_SerExVal` LONGTEXT)
proc: BEGIN
DECLARE v_DisConstant DECIMAL(12, 3);
DECLARE v_RateType INT;
DECLARE v_MaxSerVal DECIMAL(12, 3);
DECLARE v_MaxVal DECIMAL(24, 3);
DECLARE v_SubVal DECIMAL(12, 3);
DECLARE v_OrgenalSub DECIMAL(12, 3);
DECLARE v_FinalSub DECIMAL(12, 3);
DECLARE v_FirstSerExVal DECIMAL(12, 3);
DECLARE v_SecoundSerExVal DECIMAL(12, 3);
DECLARE v_FinalVal DECIMAL(12, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;
      SELECT a.RateType INTO v_RateType FROM
              CATEGORYTYPESTB AS a
      WHERE
              ID = p_ServiceID;
      SELECT IFNULL(DisConstant, 0.000) INTO v_DisConstant FROM
              `ExtTraServiceTypeTb`
      WHERE
              ID = p_ServiceID;

      SELECT IFNULL(`MaxValue`, 1), IFNULL(MaxSerVal, 1) INTO v_MaxVal, v_MaxSerVal FROM
              `ExtTraServiceTypeTb`
      WHERE
              ID = p_ServiceID;


			  IF p_BetweenVal>(v_MaxVal+v_MaxSerVal)
			   THEN
			  Set v_OrgenalSub=p_BetweenVal/v_MaxVal;
			  Set v_FinalSub=Floor(v_OrgenalSub);
Set v_FirstSerExVal = v_MaxSerVal*v_FinalSub;
Set v_SubVal=p_BetweenVal-((v_MaxVal*v_FinalSub)+v_FirstSerExVal);
			SELECT CASE                                  WHEN a.RateType = 0                                    THEN                                    CAST((DisVal + v_DisConstant) AS CHAR)                                  WHEN a.RateType = 1                                    THEN                                     CAST(((v_SubVal * DisVal) + v_DisConstant) AS CHAR)                           END INTO v_SecoundSerExVal FROM
              `CATEGORYTYPESDETAILSTB` AS a
      WHERE
              a.CATID = p_ServiceID
              AND v_SubVal >= ValFrom
              AND v_SubVal <= ValTo;

			 Set p_SerExVal=CAST(v_FirstSerExVal+v_SecoundSerExVal AS CHAR);
			   END IF;




			  IF p_BetweenVal<=(v_MaxVal+v_MaxSerVal)
			   THEN
      SELECT CASE                                  WHEN a.RateType = 0                                    THEN                                    CAST((DisVal + v_DisConstant) AS CHAR)                                  WHEN a.RateType = 1                                    THEN                                     CAST(((p_BetweenVal * DisVal) + v_DisConstant) AS CHAR)                           END INTO p_SerExVal FROM
              `CATEGORYTYPESDETAILSTB` AS a
      WHERE
              a.CATID = p_ServiceID
              AND p_BetweenVal >= ValFrom
              AND p_BetweenVal <= ValTo;
			   END IF;


      IF p_SerExVal = ''
         THEN
          SET p_IsHasEXVal = 0;
          SET p_SerExVal = 'عذرا هذه القيمة لايمكن تحويلها عن طريق هذه الخدمة ';
          ROLLBACK;
          LEAVE proc;
        END IF;

      IF p_SerExVal <> ''
         THEN
          SET p_IsHasEXVal = 1;
          SELECT
                  p_IsHasEXVal,
                  p_SerExVal;
        END IF;
      COMMIT;



  END //
DELIMITER ;

