DROP PROCEDURE IF EXISTS `CentralBankStatement`;
DELIMITER //
CREATE PROCEDURE `CentralBankStatement`(IN `p_Action` INT)
BEGIN
IF p_Action = 0
     THEN
      WITH RankedResults
      AS (   SELECT
                     ROW_NUMBER() OVER (PARTITION BY bst.ID ORDER BY bcs.ID) AS rn,
                     ROW_NUMBER() OVER (ORDER BY bst.ID) AS RowNum,
                     bst.ID AS 'معرف المصرف التجاري',
                     bst.ACCAcount AS 'النص الأصلي',
                     ExtractAccountNumberFromText(bst.ACCAcount) AS 'رقم الحساب',
                     bst.Exret AS 'القيمة',
                     ExtractNumbers(bcs.IBAN) AS 'رقم حساب المركزي',
                     bcs.BANK_NAME AS 'اسم المصرف'
             FROM
                     Banck_Sheet_Tigare bst
                 INNER JOIN
                   Banck_central_shee bcs
                       ON ExtractLastNumbers(ExtractAccountNumberFromText(bst.ACCAcount), 15) = ExtractLastNumbers(bcs.IBAN, 15)
                       AND ExtractLastNumbers(bcs.IBAN, 15) IS NOT NULL
                       AND ExtractLastNumbers(bcs.IBAN, 15) <> ''
             WHERE
                     CHAR_LENGTH(ExtractLastNumbers(bcs.IBAN, 15)) >= 10)
      SELECT
              RowNum AS '#',
              `النص الأصلي`,
              `رقم الحساب`,
              `القيمة`,
              `رقم حساب المركزي`,
              `اسم المصرف`
      FROM
              RankedResults
      WHERE
              rn = 1
      ORDER BY
              `معرف المصرف التجاري`;
    END IF;
  IF p_Action = 1
     THEN

      SELECT
              ROW_NUMBER() OVER (ORDER BY bst.ID)             AS '#',
              'موجود في التجاري فقط'                          AS 'الحالة',
              bst.ID                                          AS 'معرف المصرف التجاري',
              bst.ACCAcount                                   AS 'النص الأصلي',
              ExtractAccountNumberFromText(bst.ACCAcount) AS 'رقم الحساب المستخرج',
              bst.Exret AS 'القيمة'
      FROM
              Banck_Sheet_Tigare bst
      WHERE
              ExtractAccountNumberFromText(bst.ACCAcount) IS NOT NULL
              AND NOT EXISTS (SELECT
                          1
                  FROM
                          Banck_central_shee bcs
                  WHERE
                          ExtractLastNumbers(ExtractAccountNumberFromText(bst.ACCAcount), 15) = ExtractLastNumbers(bcs.IBAN, 15)
                          AND ExtractLastNumbers(bcs.IBAN, 15) IS NOT NULL
                          AND ExtractLastNumbers(bcs.IBAN, 15) <> ''
                          AND CHAR_LENGTH(ExtractLastNumbers(bcs.IBAN, 15)) >= 10);
    END IF;
  IF p_Action = 2
     THEN
      SELECT
              ROW_NUMBER() OVER (ORDER BY bcs.ID)  AS '#',
              'موجود في المركزي فقط'               AS 'الحالة',
              bcs.ID                               AS 'معرف المركزي',
              bcs.IBAN                             AS 'آي بان المركزي',
              ExtractNumbers(bcs.IBAN)         AS 'رقم حساب المركزي',
              ExtractLastNumbers(bcs.IBAN, 15) AS 'رقم المركزي',
              bcs.CASH_PRICE                       AS 'سعر النقدي',
              bcs.BANK_TRANSFER_PRICE              AS 'سعر التحويل',
              bcs.AMOUNT_REQUESTED                 AS 'الكمية',
              bcs.COST                             AS 'التكلفة',
              bcs.BANK_NAME                        AS 'اسم المصرف'
      FROM
              Banck_central_shee bcs
      WHERE
              ExtractLastNumbers(bcs.IBAN, 15) IS NOT NULL
              AND ExtractLastNumbers(bcs.IBAN, 15) <> ''
              AND CHAR_LENGTH(ExtractLastNumbers(bcs.IBAN, 15)) >= 10
              AND NOT EXISTS (SELECT
                          1
                  FROM
                          Banck_Sheet_Tigare bst
                  WHERE
                          ExtractLastNumbers(ExtractAccountNumberFromText(bst.ACCAcount), 15) = ExtractLastNumbers(bcs.IBAN, 15)
                          AND ExtractAccountNumberFromText(bst.ACCAcount) IS NOT NULL);
    END IF;
END //
DELIMITER ;

