DROP PROCEDURE IF EXISTS `CitiesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_Insert`(IN `p_CCode` VARCHAR(50), IN `p_CName` VARCHAR(150), IN `p_CountryID` INT)
BEGIN
INSERT INTO CitiesTb
			(
				Code,
				CityName,
				CountryID
			)
	VALUES
			(
				p_CCode, p_CName, p_CountryID
			);
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LOADFORAGENTTRANS`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LOADFORAGENTTRANS`()
BEGIN
START TRANSACTION;
	SELECT
			a.CityName,
			a.ID
	FROM
			CitiesTb AS a
		INNER JOIN
			CountiresTb AS b
				ON a.CountryID = b.ID
	WHERE
			b.ID=1
	GROUP BY
			a.ID,
			a.CityName;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LOADFORAGENTTRANSNOTEXIST`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LOADFORAGENTTRANSNOTEXIST`(IN `p_CityID` INT)
BEGIN
START TRANSACTION;
	SELECT
			a.CityName,
			a.ID
	FROM
			CitiesTb AS a
		INNER JOIN
			CoBranch AS b
				ON a.id = b.CityID
	WHERE
			b.ID <> p_CityID AND b.BranchType <> 4 AND A.CountryID=1
	GROUP BY
			a.ID,
			a.CityName

      UNION
	SELECT
			a.CityName,
			a.ID
	FROM
			CitiesTb AS a
	WHERE
			 A.CountryID=1
	GROUP BY
			a.ID,
			a.CityName;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LOADFORCONFIRM`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LOADFORCONFIRM`()
BEGIN
START TRANSACTION;
	SELECT
			a.CityName,
			a.ID
	FROM
			CitiesTb AS a
	ORDER BY
			a.CityName;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LoadToListBox`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LoadToListBox`(IN `p_CountryID` INT)
BEGIN
SELECT
			ID,
			Code,
			CityName,
			CountryID
	FROM
			CitiesTb
	WHERE
			CountryID = p_CountryID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LoadToLKP`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LoadToLKP`(IN `p_CountryID` INT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			b.ID AS DBRID,
			CityName,
			a.ID AS CTID,
			b.BranchType
	FROM
			CitiesTb AS a
		INNER JOIN
			CoBranch AS b
				ON a.ID = b.CityID
	WHERE
			a.CountryID = p_CountryID
			AND b.ID <> p_BranchID
	GROUP BY
			a.ID,
			CityName,
			b.ID,
			b.BranchType;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CitiesTb_LoadToLKPBasedOnBranch`;
DELIMITER //
CREATE PROCEDURE `CitiesTb_LoadToLKPBasedOnBranch`()
BEGIN
START TRANSACTION;
	SELECT
			CityName,
			a.ID AS CTID
	FROM
			CitiesTb AS a
		INNER JOIN
			CoBranch  AS b
				ON a.id = b.CityID
        WHERE (b.BranchType=1 OR b.BranchType=2 OR b.BranchType=3)
	GROUP BY
			a.ID,
			CityName;
	COMMIT;
END //
DELIMITER ;

