START TRANSACTION;
	SELECT
			CityName,
			a.ID AS CTID
	FROM
			CitiesTb AS a
		INNER JOIN
			CountiresTb AS b
				ON a.CountryID = b.ID
	WHERE
			a.CountryID = p_CountryID
	GROUP BY
			a.ID,
			CityName;
	COMMIT;
END //
DELIMITER ;

