DROP PROCEDURE IF EXISTS `CoBranch_GetBenefitRates`;
DELIMITER //
CREATE PROCEDURE `CoBranch_GetBenefitRates`(IN `p_RBranchID` INT, IN `p_DBranchID` INT, IN `p_InputVal` DECIMAL(12,3))
BEGIN
DECLARE v_RBrType INT;
DECLARE v_DBrType INT;
DECLARE v_CulRes DECIMAL(12, 3);
DECLARE v_RestShare DECIMAL(12, 3);
DECLARE v_BrRt DECIMAL(12, 3);
DECLARE v_RBShare DECIMAL(12, 3);
DECLARE v_DBShare DECIMAL(12, 3);
DECLARE v_DbrRt DECIMAL(12, 3);
DECLARE v_AgentRestVal DECIMAL(12, 3);
DECLARE v_MainBr INT;
START TRANSACTION;
	SELECT ID INTO v_MainBr FROM
			CoBranch
	WHERE
			IsMain = 1;

	SET v_RBrType = (SELECT BranchType FROM CoBranch WHERE ID = p_RBranchID);
	SET v_DBrType = (SELECT BranchType FROM CoBranch WHERE ID = p_DBranchID);
	IF p_RBranchID = v_MainBr
		 THEN
			SELECT MainBranchBenefit INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_RBShare = p_InputVal - v_DBShare;
SET v_RestShare = 0.000;
		END IF;



	IF p_DBranchID = v_MainBr
		 THEN
			SELECT MainBranchBenefit INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_DBShare = p_InputVal - v_RBShare;
SET v_RestShare = 0.000;
		END IF;


	IF p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		AND
		v_DBrType = 1
		AND
		v_RBrType = 1
		 THEN


			SELECT CoBranch.WithBranchRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT CoBranch.WithBranchRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;






		END IF;






































	IF v_RBrType = 2
		AND
		v_DBrType = 1
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT BranchRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT WithMediumRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;




		END IF;


	IF v_RBrType = 1
		AND
		v_DBrType = 2
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT WithMediumRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT BranchRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;




		END IF;


	IF v_RBrType = 2
		AND
		v_DBrType = 2
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT cb.WithMediumRate INTO v_BrRt FROM
					CoBranch cb
			WHERE
					ID = p_RBranchID;

			SELECT cb.WithMediumRate INTO v_DbrRt FROM
					CoBranch cb
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;




		END IF;



































	IF v_RBrType = 3
		AND
		v_DBrType = 1
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT BranchRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT WithAgentRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_AgentRestVal = p_InputVal - v_RBShare;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;
		END IF;


	IF v_RBrType = 1
		AND
		v_DBrType = 3
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT WithAgentRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT BranchRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_AgentRestVal = p_InputVal - v_DBShare;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;
		END IF;



	IF v_RBrType = 3
		AND
		v_DBrType = 2
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT BranchRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT WithAgentRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_AgentRestVal = p_InputVal - v_RBShare;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;
		END IF;


	IF v_RBrType = 2
		AND
		v_DBrType = 3
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN

			SELECT WithAgentRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT BranchRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_AgentRestVal = p_InputVal - v_DBShare;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;
		END IF;


	IF v_RBrType = 3
		AND
		v_DBrType = 3
		AND
		p_DBranchID <> v_MainBr
		AND
		p_RBranchID <> v_MainBr
		 THEN
			SELECT WithAgentRate INTO v_BrRt FROM
					CoBranch
			WHERE
					ID = p_RBranchID;

			SELECT WithAgentRate INTO v_DbrRt FROM
					CoBranch
			WHERE
					ID = p_DBranchID;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_RBShare = p_InputVal * v_BrRt / 100;
SET v_CulRes = v_RBShare + v_DBShare;
			IF v_CulRes <> 0
				 THEN
SET v_RestShare = p_InputVal - v_CulRes;
				END IF;
		END IF;
	IF v_RestShare = 0
		 THEN
SET v_RestShare = 0.000;
		END IF;
	IF v_DBShare = 0
		 THEN
SET v_DBShare = 0.000;
		END IF;
	IF v_RBShare = 0
		 THEN
SET v_RBShare = 0.000;
		END IF;
	SELECT
			v_RestShare AS RestShare,
			v_DBShare   AS DBShare,
			v_RBShare   AS RBShare;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranch_GetMainBranch`;
DELIMITER //
