DROP PROCEDURE IF EXISTS `CoBranch_Insert`;
DELIMITER //
CREATE PROCEDURE `CoBranch_Insert`(IN `p_Code` LONGTEXT, IN `p_BName` LONGTEXT, IN `p_CountryID` INT, IN `p_CityID` INT, IN `p_BAddress` LONGTEXT, IN `p_Mobile1` LONGTEXT, IN `p_Mobile2` LONGTEXT, IN `p_Notes` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_IsMain` TINYINT(1), IN `p_BranchType` TINYINT UNSIGNED, IN `p_IsPartner` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_BID` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_OwnerName` LONGTEXT, IN `p_GroupName` LONGTEXT, IN `p_IDGroup` LONGTEXT)
BEGIN
DECLARE v_acccode        BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_BranchID INT;
DECLARE v_CurrentAccID   BIGINT;
DECLARE v_CheckAccExist INT;
DECLARE v_CurrencyName LONGTEXT;
DECLARE v_IsDefault BIT;
DECLARE v_MainBranchName LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


      START TRANSACTION;
      IF p_IsUpdate = 0
         THEN
          SELECT cb.BName INTO v_MainBranchName FROM
                  CoBranch cb
          WHERE
                  cb.IsMain = 1;
          INSERT INTO CoBranch
                (
                  Code,
                  BName,
                  CountryID,
                  CityID,
                  BAddress,
                  Mobile1,
                  Mobile2,
                  Notes,
                  IsActive,
                  IsMain,
                  BranchType,
                  IsPartner,
                  OwnerName,
                  IsAttached
                )
          VALUES
                  (
                    p_Code, p_BName, p_CountryID, p_CityID, p_BAddress, p_Mobile1,
                    p_Mobile2, p_Notes, p_IsActive, p_IsMain, p_BranchType, p_IsPartner, p_OwnerName,p_IsPartner
                  );
          SELECT ID INTO v_BranchID FROM
                  CoBranch AS a
          WHERE
                  a.BName = p_BName;
          INSERT INTO BranchRatesTb
                (
                  FBranchID,
                  FBRate,
                  SBranchID,
                  SBRate
                )
              SELECT
                      v_BranchID,
                      a.FBRate,
                      a.SBranchID,
                      a.SBRate
              FROM
                      View_CBranch AS a
              WHERE
                      a.SBranchID <> v_BranchID;
          INSERT INTO BranchRatesTb
                (
                  FBranchID,
                  FBRate,
                  SBranchID,
                  SBRate
                )
              SELECT
                      a.FBranchID,
                      a.FBRate,
                      v_BranchID,
                      a.SBRate
              FROM
                      View_CBranch AS a
              WHERE
                      a.FBranchID <> v_BranchID;

          UPDATE
                  CoBranch
          SET
                  IsRated = 1
          WHERE
            id = v_BranchID;


            INSERT INTO `whtsappGRoup`
           (`IDGroup`
           ,`GroupName`
           ,`Branchid`
           ,`IsActive`
           ,`InsertDate`
           ,`IDGroup2`)
     VALUEs (p_IDGroup , p_GroupName , v_BranchID ,1  , NOW() , '');
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
          SELECT COUNT(*) INTO v_CheckAccExist FROM
                  AccountsTb AS AT
          WHERE
                  AT.AccName = 'الحسابات الجارية';

          IF v_CheckAccExist = 0
             THEN
              SELECT AccCode INTO v_IDParent FROM
                      AccountsTb AS AT
              WHERE
                      AT.AccName = 'الخصوم المتداولة';
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;

              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_AccName = 'الحسابات الجارية';
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode
                    )
              VALUES
                      (
                        v_acccode, v_AccName, 0, 2, v_IDParent, 1, 1, 0, 0, 0, 1, v_IDcode
                      );
            END IF;


          SELECT COUNT(*) INTO v_CheckAccExist FROM
                  AccountsTb AS AT
          WHERE
                  AT.AccName = 'حسابات جارية الفروع والوكلاء';

          IF v_CheckAccExist = 0
             THEN
              SELECT AccCode INTO v_IDParent FROM
                      AccountsTb
              WHERE
                      AccName = 'الحسابات الجارية';
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;

              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_AccName = 'حسابات جارية الفروع والوكلاء';
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode
                    )
              VALUES
                      (
                        v_acccode, v_AccName, 0, 3, v_IDParent, 1, 1, 0, 0, 0, 1, v_IDcode
                      );

            END IF;


          SELECT COUNT(*) INTO v_CheckAccExist FROM
                  AccountsTb AS AT
          WHERE
                  AT.AccName = CONCAT('جاري', SPACE(1), p_BName);

          IF v_CheckAccExist = 0
             THEN
              SELECT AccCode INTO v_IDParent FROM
                      AccountsTb
              WHERE
                      AccName = 'حسابات جارية الفروع والوكلاء';
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;

              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_AccName = CONCAT('جاري', SPACE(1), p_BName);
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode,
                      CanDebit
                    )
              VALUES
                      (
                        v_acccode, v_AccName, 1, 4, v_IDParent, 1, 1, 0, 0, v_BranchID, 1, v_IDcode,1
                      );
              SELECT at.AccID INTO v_CurrentAccID FROM
                      AccountsTb at
              WHERE
                      at.AccName = CONCAT('جاري', SPACE(1), p_BName);
              UPDATE
                      CoBranch
              SET
                      CurrentAccID = v_CurrentAccID
              WHERE
                ID = p_Code;
            END IF;




          SELECT COUNT(*) INTO v_CheckAccExist FROM
                  AccountsTb AS AT
          WHERE
                  AT.AccName = 'حسابات جارية الشركاء';
          IF v_CheckAccExist = 0
             THEN
              SELECT AccCode INTO v_IDParent FROM
                      AccountsTb AS AT
              WHERE
                      AT.AccName = 'الخصوم المتداولة';
              SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                      AccountsTb AS a
              WHERE
                      AccParent = v_IDParent;
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_AccName = 'حسابات جارية الشركاء';
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
              INSERT INTO AccountsTb
                    (
                      AccCode,
                      AccName,
                      AccType,
                      Accline,
                      AccParent,
                      AccDmType,
                      AccFinal,
                      AccMaxLimit,
                      AccMaxDuration,
                      BranchID,
                      AccActive,
                      IDcode
                    )
              VALUES
                      (
                        v_acccode, v_AccName, 0, 2, v_IDParent, 1, 1, 0, 0, 0, 1, v_IDcode
