DROP PROCEDURE IF EXISTS `CoBranch_ReloadDataForUpdate`;
DELIMITER //
CREATE PROCEDURE `CoBranch_ReloadDataForUpdate`(IN `p_Code` LONGTEXT, IN `p_ID` INT)
BEGIN


		SELECT
				a.`ID`,
				`Code`,
				`BName`,
				CountryID,
				CityID,
				`BAddress`,
				`Mobile1`,
				`Mobile2`,
				`Notes`,
			a.	`IsActive`,
				`IsMain`,
				`BranchType`,
				BranchRate,
				WithAgentRate,
				WithMediumRate,
				WithBranchRate,
				MainBranchBenefit,
				b.IDGroup ,
				b.GroupName ,
        OwnerName
		FROM
				`CoBranch` as a
				inner join whtsappGRoup as b on a.ID = b.Branchid
		WHERE
				a.`ID` = p_ID
				AND `Code` = p_Code;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LoadAgentHasCurrencyPrice`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LoadAgentHasCurrencyPrice`(IN `p_CountryID` INT)
BEGIN


		START TRANSACTION;

		SELECT
				a.ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch as a
        INNER JOIN
       NewCurrencyPricesOwnTb AS b
        ON a.ID=b.BranchID
		WHERE
				a.IsActive = 1
				and ((a.CountryID=p_CountryID AND a.BranchType=4)OR a.BranchType=3);


		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LoadAgentHasCurrencyPrices`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LoadAgentHasCurrencyPrices`(IN `p_CountryID` INT)
BEGIN


		START TRANSACTION;

		SELECT
				a.ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch as a
        INNER JOIN
       NewCurrencyPricesOwnTb AS b
        ON a.ID=b.BranchID
		WHERE
				a.IsActive = 1
				and (b.CountryID=p_CountryID AND (a.BranchType=4 OR a.BranchType=3));


		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LoadconnectedBranch`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LoadconnectedBranch`()
BEGIN


    START TRANSACTION;
    SELECT
            a.ID AS DBRID,
            BName
    FROM
            CoBranch a
    WHERE
            a.IsActive = 1
            AND a.israted = 1
            AND (   EXISTS (SELECT
                                1
                        FROM
                                EmployeeTb b
                        WHERE
                                a.ID = b.BranchID)
                    OR a.ID = 43);
    COMMIT;
  END //
DELIMITER ;

