DROP PROCEDURE IF EXISTS `CoBranches_LoadForBranchNotMain`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LoadForBranchNotMain`(IN `p_BranchId` INT)
BEGIN
DECLARE v_IsMain INT;


    START TRANSACTION;
    SELECT
            ID AS DBRID,
            BName,
            BranchType,
            CityID
    FROM
            CoBranch
    WHERE
            IsActive = 1
            AND ID <> p_BranchId;

    COMMIT;
  END //
