DROP PROCEDURE IF EXISTS `CoBranches_LOADTOGLKPNotSelectCOUNTRY`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LOADTOGLKPNotSelectCOUNTRY`(IN `p_CountryID` INT)
BEGIN
DECLARE v_MainCountry INT;


		START TRANSACTION;

SELECT ID INTO v_MainCountry FROM CountiresTb AS ct WHERE ct.IsMain=1;
		SELECT
				ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch as a
		WHERE
				IsActive = 1
				and a.CountryID<>p_CountryID
        AND a.CountryID<>v_MainCountry
				and a.branchType=1
			  AND a.IsMain<>1;

		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LOADTOGLKPWITHCOUNTRY`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LOADTOGLKPWITHCOUNTRY`(IN `p_CountryID` INT)
BEGIN
DECLARE v_IsMain Bit;


		START TRANSACTION;
		SELECT ISMain INTO v_IsMain FROM
				CountiresTb as a
				 Where  a.ID=p_CountryID;

If v_IsMain=1
 THEN
		SELECT
				ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch as a
		WHERE
				IsActive = 1
				and a.CountryID=p_CountryID
				and
				 (a.BranchType=1 OR a.BranchType=3);
				END IF;

If v_IsMain=0
 THEN
SELECT
				a.ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch as a
        INNER JOIN
       NewCurrencyPricesOwnTb AS b
        ON a.ID=b.BranchID
		WHERE
				a.IsActive = 1
				and (b.CountryID=p_CountryID AND (a.BranchType<>4 OR a.BranchType<>3))

Union
		Select AccID AS DBRID,AccName as BName,0 as BranchType from `AccountsTb` As ac Where  AccParent=10101201  And CountryID=p_CountryID;
				END IF;

		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LOADTOGLKPWITHCOUNTRYAndBID`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LOADTOGLKPWITHCOUNTRYAndBID`(IN `p_CountryID` INT, IN `p_BID` INT)
BEGIN
DECLARE v_IsMain BIT;
DECLARE v_IsMainBID BIT;


    START TRANSACTION;
    SELECT ISMain INTO v_IsMain FROM
            CountiresTb AS a
    WHERE
            a.ID = p_CountryID;
    SELECT Co.IsMain INTO v_IsMainBID FROM
            CoBranch AS Co
    WHERE
            Co.ID = p_BID;

    IF v_IsMain = 1
       THEN
        IF v_IsMainBID = 1
           THEN
            SELECT
                    ID AS DBRID,
                    BName,
                    BranchType,
                    a.CityID
            FROM
                    CoBranch AS a
            WHERE
                    IsActive = 1
                    AND a.CountryID = p_CountryID
                    AND (   (a.BranchType = 3)
                            OR a.ID = p_BID);
          END IF;

        IF v_IsMainBID = 0
           THEN
            SELECT
                    ID AS DBRID,
                    BName,
                    BranchType,
                    a.CityID
            FROM
                    CoBranch AS a
            WHERE
                    IsActive = 1
                    AND a.CountryID = p_CountryID
                    AND a.ID = p_BID;
          END IF;
      END IF;
    IF v_IsMain = 0
       THEN
        SELECT
                a.ID AS DBRID,
                BName,
                BranchType,
                a.CityID
        FROM
                CoBranch AS a
            INNER JOIN
              NewCurrencyPricesOwnTb AS b
                ON a.ID = b.BranchID
        WHERE
                a.IsActive = 1
                AND (   b.CountryID = p_CountryID
                        AND (   a.BranchType = 4
                                OR a.BranchType = 3))

        UNION
        SELECT
                AccID        AS DBRID,
                AccName      AS BName,
                0            AS BranchType,
                ac.CountryID AS CityID
        FROM
                `AccountsTb` AS ac
        WHERE
                AccParent = 10101201
                AND CountryID = p_CountryID;
      END IF;

    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranches_LOADTOGLKPWITHTransType`;
DELIMITER //
CREATE PROCEDURE `CoBranches_LOADTOGLKPWITHTransType`(IN `p_CountryID` INT, IN `p_TransType` INT)
BEGIN
DECLARE v_IsMain BIT;
DECLARE v_CurrID INT;


    START TRANSACTION;

    SELECT c.DefualtCurrency INTO v_CurrID FROM
            `CountiresTb` AS c
    WHERE
            c.ID = p_CountryID;



    SELECT IsMain INTO v_IsMain FROM
            CountiresTb AS a
    WHERE
            a.ID = p_CountryID;

    IF v_IsMain = 1
       THEN
        SELECT
                ID AS DBRID,
                BName,
                BranchType
        FROM
                CoBranch AS a
        WHERE
                IsActive = 1
                AND a.CountryID = p_CountryID
                AND (   a.BranchType = 1
                        OR a.BranchType = 3);
      END IF;

    IF v_IsMain = 0
       THEN
        IF p_TransType = 0
           THEN
            SELECT
                    AccID   AS DBRID,
                    AccName AS BName,
                    ''      AS BranchType
            FROM
                    `AccountsTb` AS ac
            WHERE
                    AccParent LIKE '1010120%'
                    AND AccCurID = v_CurrID
                    AND ac.CountryID = p_CountryID;
          END IF;
        IF p_TransType = 2
           THEN
            SELECT
                    a.ID AS DBRID,
                    BName,
                    BranchType
            FROM
                    CoBranch AS a
                INNER JOIN
                  NewCurrencyPricesOwnTb AS b
                    ON a.ID = b.BranchID
            WHERE
                    a.IsActive = 1
                    AND (   b.CountryID = p_CountryID
                            AND (   a.BranchType = 4
                                    OR a.BranchType = 3));
          END IF;

        IF p_TransType = 3
           THEN
            SELECT
                    a.ID AS DBRID,
                    BName,
                    BranchType
            FROM
                    CoBranch AS a
                INNER JOIN
                  NewCurrencyPricesOwnTb AS b
                    ON a.ID = b.BranchID
            WHERE
                    a.IsActive = 1
                    AND (   b.CountryID = p_CountryID
                            AND (   a.BranchType <> 4
                                    OR a.BranchType <> 3));
          END IF;
      END IF;
    COMMIT;
  END //
DELIMITER ;

