DROP PROCEDURE IF EXISTS `Companies_Crud`;
DELIMITER //
CREATE PROCEDURE `Companies_Crud`(IN `p_Action` INT, IN `p_ID` INT, IN `p_CompanyName` TEXT, IN `p_TypeID` INT, IN `p_ParentID` INT, IN `p_EmpID` INT, IN `p_ManagerName` VARCHAR(250), IN `p_LicenseNumber` VARCHAR(150), IN `p_TaxNumber` VARCHAR(50), IN `p_IsActive` TINYINT(1))
proc: BEGIN
DECLARE v_NewID INT DEFAULT LAST_INSERT_ID();
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;







        IF p_Action = 0
         THEN
            SELECT
                  C.ID
                  ,c.CompanyName
                , CONCAT(CASE WHEN C.TypeID=0 THEN 'شركة ' ELSE 'قسم ' END, C.CompanyName) AS CompanyName1
                , C.TypeID
                , C.ParentID
                , P.CompanyName AS ParentCompany
                , C.EmpID
                , C.ManagerName
                , C.LicenseNumber
                , C.TaxNumber
                , C.IsActive
            FROM Companies C
            LEFT JOIN Companies P ON P.ID = C.ParentID
            WHERE C.IsActive = 1
              AND (C.TypeID = p_TypeID OR p_TypeID IS NULL)
              AND (C.ParentID = p_ParentID OR p_ParentID IS NULL)
            ORDER BY C.CompanyName
            ;
            LEAVE proc;
        END IF;




        IF p_Action = 1
         THEN
            START TRANSACTION;

            IF EXISTS (SELECT 1 FROM Companies WHERE CompanyName = p_CompanyName AND IsActive = 1)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='اسم الشركة موجود مسبقاً';
                ROLLBACK;
                LEAVE proc;
            END IF;

            IF EXISTS (SELECT 1 FROM Companies ) AND p_ParentID IS NULL
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='عذرا حقل الشركة الأم لا يمكن أن يكون فارغا';
                ROLLBACK;
                LEAVE proc;
            END IF;

            IF NOT EXISTS (SELECT 1 FROM Companies ) AND p_ParentID IS NULL
             THEN
 SET p_ParentID=0;
            END IF;

            INSERT INTO Companies
            (
                  CompanyName, TypeID, ParentID, EmpID, ManagerName, LicenseNumber, TaxNumber, IsActive
            )
            VALUES
            (
                  p_CompanyName, p_TypeID, p_ParentID, p_EmpID, p_ManagerName, p_LicenseNumber, p_TaxNumber, p_IsActive
            );



            IF p_EmpID IS NOT NULL AND EXISTS (SELECT 1 FROM EmployeeTb WHERE ID = p_EmpID)
             THEN
                UPDATE EmployeeTb SET Jobgrade = v_NewID WHERE ID = p_EmpID;
            END IF;

            COMMIT;
            SELECT v_NewID AS NewID;
            LEAVE proc;
        END IF;




        IF p_Action = 2
         THEN
            START TRANSACTION;


            IF p_ParentID IS NOT NULL AND p_ParentID = p_ID
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='لا يمكن أن تكون الشركة تابعة لنفسها!';
                ROLLBACK;
                LEAVE proc;
            END IF;

            IF EXISTS (SELECT 1 FROM Companies WHERE CompanyName = p_CompanyName AND ID <> p_ID AND IsActive = 1)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='اسم الشركة موجود مسبقاً';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE Companies
               SET CompanyName   = p_CompanyName, TypeID        = p_TypeID, ParentID      = p_ParentID, EmpID         = p_EmpID, ManagerName   = p_ManagerName, LicenseNumber = p_LicenseNumber, TaxNumber     = p_TaxNumber, IsActive      = p_IsActive
             WHERE ID = p_ID;

 UPDATE EmployeeTb SET Jobgrade = p_ID WHERE ID = p_EmpID;

            COMMIT;
            SELECT p_ID AS UpdatedID;
            LEAVE proc;
        END IF;




        IF p_Action = 3
         THEN
            START TRANSACTION;


            IF EXISTS (SELECT 1 FROM Companies WHERE ParentID = p_ID AND IsActive = 1)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='لا يمكن حذف هذه الشركة لوجود شركات تابعة لها. الرجاء نقل أو حذف الشركات التابعة أولاً.';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE Companies SET IsActive = 0 WHERE ID = p_ID;

            COMMIT;
            SELECT p_ID AS DeletedID;
            LEAVE proc;
        END IF;




        IF p_Action = 4
         THEN
            SELECT
                  C.ID, C.CompanyName, C.TypeID, C.ParentID, P.CompanyName AS ParentCompany,
                  C.EmpID, C.ManagerName, C.LicenseNumber, C.TaxNumber, C.IsActive
            FROM Companies C
            LEFT JOIN Companies P ON P.ID = C.ParentID
            WHERE C.ID = p_ID;
            LEAVE proc;
        END IF;



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CompanyInfo_CRUD`;
DELIMITER //
CREATE PROCEDURE `CompanyInfo_CRUD`(IN `p_Action` INT, IN `p_ARName` TEXT, IN `p_Mobile1` VARCHAR(50), IN `p_IMG` LONGBLOB, IN `p_CityName` VARCHAR(100), IN `p_CoAddress` VARCHAR(250), IN `p_WebSite` VARCHAR(50), IN `p_EMail` VARCHAR(50), IN `p_FaceBook` TEXT)
BEGIN
DECLARE v_Oount int;

IF p_Action=0
 THEN
	SELECT
  ci.ID,
  ci.ARName,
  ci.FaceBook,
  ci.Country,
  ci.CityName,
  ci.CoAddress,
  ci.LandLine1,
  ci.LandLine2,
  ci.Mobile1,
  ci.Mobile2,
  ci.WebSite,
  ci.EMail,
  ci.IMG,
  ci.Notes
  FROM CompanyInfo ci;
END IF;

    SELECT COUNT(ARName) INTO v_Oount FROM CompanyInfo;


    IF v_Oount = 0
     THEN
        INSERT INTO CompanyInfo
        (
            ARName,
            CityName,
            CoAddress,
            Mobile1,
            EMail,
            WebSite,
            IMG,
            FaceBook
        )
        VALUES
            (
             p_ARName, p_CityName, p_CoAddress, p_Mobile1, p_EMail, p_WebSite, p_IMG,p_FaceBook
            );
    END IF;


    IF v_Oount > 0
     THEN
        UPDATE CompanyInfo
        SET
            ARName = p_ARName, CityName = p_CityName, CoAddress = p_CoAddress, Mobile1 = p_Mobile1, EMail = p_EMail, WebSite = p_WebSite, IMG = p_IMG, FaceBook=    p_FaceBook
        WHERE
            ID = 1;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_Activity_LoadToDVGBasedOnActivityType`;
DELIMITER //
CREATE PROCEDURE `CONDB_Activity_LoadToDVGBasedOnActivityType`(IN `p_ActivityType` BIGINT, IN `p_dt1` DATE, IN `p_dt2` DATE)
BEGIN


    START TRANSACTION;
    SELECT
            a.AccCode,
            a.AccName,
           CASE WHEN sum(b.Credit)>  sum(b.Debit) THEN sum(b.Credit)-  sum(b.Debit) ELSE 0.000 END AS Credit,
            CASE WHEN sum(b.Credit)<  sum(b.Debit) THEN sum(b.Debit)-sum(b.Credit) ELSE 0.000 END AS Debit
    FROM
            AccountsTb a
            INNER JOIN
            ExSyAccounts_AccSafeActivityTb  b
            ON a.AccID=b.AccIDFrom
    WHERE
            a.AccParent =p_ActivityType
            AND a.AccActive=1
            AND b.IsActive=1
            AND b.InsertDate BETWEEN p_dt1 AND p_dt2
            AND b.TypeID<>53
AND a.AccName NOT LIKE '%أصول%'
            GROUP BY
            a.AccCode,
            a.AccName
                      HAVING
                  SUM(b.Credit) - SUM(b.Debit) <> 0;
    COMMIT;
  END //
DELIMITER ;

