            a.AccCode,
            a.AccName
    FROM
            AccountsTb a
    WHERE
            a.AccCode=1030201
            AND a.AccActive=1;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_ClosingBusinessActivity_TB`;
DELIMITER //
CREATE PROCEDURE `CONDB_ClosingBusinessActivity_TB`(IN `p_ActivityCode` BIGINT, IN `p_SafeID` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, INOUT `p_MsgSatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_NetTotal DECIMAL(18, 3);
DECLARE v_SunDebit DECIMAL(18, 3);
DECLARE v_SumCredit DECIMAL(18, 3);
DECLARE v_AccProfORLoss BIGINT;
DECLARE v_ISID LONGTEXT;
DECLARE v_D1 DATE;
DECLARE v_D2 DATE;
DECLARE v_ActivityName VARCHAR(80);
DECLARE v_MaxID INT;
DECLARE v_MovmentType LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_MsgSatues = 0; END;

      START TRANSACTION;



      SELECT D1, d2 INTO v_D1, v_D2 FROM
              ClosingBusinessActivity_TB
      WHERE
              ActivityCode = p_ActivityCode
              AND (   (       D1 >= p_dt1
                              AND D1 <= p_dt2)
                      OR (    D2 >= p_dt1
                              AND D2 <= p_dt2));

      IF v_D1 IS NOT NULL
        AND
        v_D2 IS NOT NULL
         THEN
          SET p_MsgSatues = 0;
          SET p_MsgBox = CONCAT('عذرا هناك إقفال سابق خلال الفترة من', CHAR(13), CAST(v_D1 AS CHAR), CHAR(13), 'إلى', CHAR(13), CAST(v_D2 AS CHAR), CHAR(13), 'الرجاء اختيار تاريخ خارج هذه الفترة');
          ROLLBACK;
          LEAVE proc;
        END IF;





      SELECT a.AccName INTO v_ActivityName FROM
              AccountsTb a
      WHERE
              a.AccCode = p_ActivityCode;









      SELECT at.AccID INTO v_AccProfORLoss FROM
              AccountsTb at
      WHERE
              at.AccParent = 20401017
              AND at.AccName LIKE '%العملات%';

      IF v_AccProfORLoss IS NULL
         THEN
          SET p_MsgSatues = 0;
          SET p_MsgBox = 'لم يتم العثور على حساب صافي الدخل لهذا النشاط الرجاء التأكد من زرع الحساب ثم أعد المحاولة';
          ROLLBACK;
          LEAVE proc;
        END IF;







      SELECT IFNULL(MAX(ID), 0) + 1 INTO v_MaxID FROM
              ClosingBusinessActivity_TB;
SET v_ISID = CONCAT('53', '-', CAST(MONTH(p_dt1) AS CHAR), CAST(MONTH(p_dt2) AS CHAR), '-', CAST(v_MaxID AS CHAR));
      SET v_MovmentType = CONCAT('إقفال نشاط', ' ', v_ActivityName, ' ', 'خلال الفترة من', ' ', CAST(p_dt1 AS CHAR), ' ', 'إلى', ' ', CAST(p_dt2 AS CHAR));
      SELECT CASE                                   WHEN (SUM(b.Credit) - SUM(b.Debit)) > 0                                     THEN                                     (SUM(b.Credit) - SUM(b.Debit))                                   ELSE                                   0.000                           END, CASE                                   WHEN (SUM(b.Debit) - SUM(b.Credit)) > 0                                     THEN                                     (SUM(b.Debit) - SUM(b.Credit))                                   ELSE                                   0.000                           END INTO v_SumCredit, v_SunDebit FROM
              AccountsTb a
          INNER JOIN
            ExSyAccounts_AccSafeActivityTb b
              ON a.AccID = b.AccIDFrom
      WHERE
              a.AccParent = p_ActivityCode
              AND a.AccActive = 1
              AND b.IsActive = 1
              AND b.InsertDate BETWEEN p_dt1 AND p_dt2
              AND b.TypeID <> 53
              AND a.AccName NOT LIKE '%أصول%'



      HAVING
              SUM(b.Credit) - SUM(b.Debit) <> 0;

      IF v_SumCredit > v_SunDebit
         THEN
          SET v_NetTotal = v_SumCredit - v_SunDebit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement
                )
          VALUES
                  (
                    p_SafeID, 0.000, v_NetTotal, NOW(), v_ISID, 1, 53, 88, 1, v_AccProfORLoss, 0, v_MovmentType, 1, v_MovmentType, v_MovmentType
                  );
        END IF;


      IF v_SunDebit > v_SumCredit
         THEN
          SET v_NetTotal = v_SunDebit - v_SumCredit;
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  MovementType,
                  CurrencyID,
                  Note,
                  SafeIDMovement
                )
          VALUES
                  (
                    p_SafeID, v_NetTotal, 0.000, NOW(), v_ISID, 1, 53, 88, 1, v_AccProfORLoss, 0, v_MovmentType, 1, v_MovmentType, v_MovmentType
                  );
        END IF;



      INSERT INTO ExSyAccounts_AccSafeActivityTb
            (
              SafeID,
              Debit,
              Credit,
              InsertDate,
              ISID,
              IsActive,
              TypeID,
              OperationTypeID,
              AccBranchID,
              AccIDFrom,
              AccIDTo,
              MovementType,
              CurrencyID,
              Note,
              SafeIDMovement
            )
          SELECT
                  p_SafeID,
                  CASE                           WHEN (SUM(b.Credit) - SUM(b.Debit)) > 0                             THEN                             (SUM(b.Credit) - SUM(b.Debit))                           ELSE                           0.000                   END,
                  CASE                           WHEN (SUM(b.Debit) - SUM(b.Credit)) > 0                             THEN                             (SUM(b.Debit) - SUM(b.Credit))                           ELSE                           0.000                   END,
                  NOW(),
                  v_ISID,
                  1,
                  53,
                  88,
                  1,
                  a.AccID,
                  v_AccProfORLoss,
                  v_MovmentType,
                  1,
                  v_MovmentType,
                  v_MovmentType
          FROM
                  AccountsTb a
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  a.AccParent = p_ActivityCode
                  AND a.AccActive = 1
                  AND b.IsActive = 1
                  AND b.InsertDate BETWEEN p_dt1 AND p_dt2
                  AND b.TypeID <> 53
                  AND a.AccName NOT LIKE '%أصول%'
          GROUP BY
                  a.AccID,
                  a.AccName

          HAVING
                  SUM(b.Credit) - SUM(b.Debit) <> 0;



      INSERT INTO ClosingBusinessActivity_TB
            (
              Code,
              ActivityCode,
              SafeId,
              D1,
              D2,
              ClosingDate,
              IsActive
            )
      VALUES
              (
                v_ISID, p_ActivityCode, p_SafeID, p_dt1, p_dt2, NOW(), 1
              );

      COMMIT;
      SET p_MsgSatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_GetActivityBenefits`;
DELIMITER //
CREATE PROCEDURE `CONDB_GetActivityBenefits`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;



SELECT

			a.ISID							AS 'الرمز',
      DATE_FORMAT(a.InsertDate, '%d/%m/%Y') AS 'التاريخ',
      b.AccName AS 'اسم الحساب',
			FORMAT(a.Credit, 3) AS 'الإيراد',
			FORMAT(a.Debit, 3)  AS 'الخسارة',
      a.Note AS 'الملاحظات'

	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID

WHERE
            b.AccParent =p_BranchID
            AND b.AccActive=1
            AND a.IsActive=1
            AND a.InsertDate BETWEEN p_D1 AND p_D2
            AND a.TypeID<>53
AND b.AccName NOT LIKE '%أصول%';

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_WorkshopOperations_Select`;
DELIMITER //
CREATE PROCEDURE `CONDB_WorkshopOperations_Select`(IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_ActivityType` INT)
BEGIN
START TRANSACTION;









  IF p_TypeID = 3
     THEN
      SELECT
              a.AccID,
              a.AccName
      FROM
              AccountsTb a
      WHERE
              a.AccParent = p_ActivityType
              AND a.BranchID = p_BranchID
              AND a.AccName LIKE '%مصروف%';
    END IF;


  IF p_TypeID = 5
     THEN
      SELECT
              a.AccID,
              a.AccName
      FROM
              AccountsTb a
      WHERE
              a.AccParent LIKE '201010%'
              AND a.acccode NOT LIKE '2010100%'
              AND a.BranchID = p_BranchID;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_WorkshopOperationsTB_Insert`;
DELIMITER //
CREATE PROCEDURE `CONDB_WorkshopOperationsTB_Insert`(IN `p_CodeID` BIGINT, IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_SafeID` INT, IN `p_AccIDFrom` BIGINT, IN `p_AccIDTO` BIGINT, IN `p_NetVal` DECIMAL(18,3), IN `p_Note` LONGTEXT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_ActivityType` BIGINT, IN `p_CountOfOperation` INT, IN `p_BankNo` VARCHAR(250), IN `p_CustName` VARCHAR(250), IN `p_CustBankNo` VARCHAR(250), IN `p_CustPhone` VARCHAR(250))
proc: BEGIN
DECLARE v_MovementType VARCHAR(100);
DECLARE v_GETID VARCHAR(300);
DECLARE v_OPTYPE INT;
DECLARE v_UserMovement LONGTEXT;
DECLARE v_AccFrom BIGINT;
DECLARE v_AccTo BIGINT;
DECLARE v_OriginsAcc BIGINT;
DECLARE v_MaterialsAcc BIGINT;
DECLARE v_ExpenseAcc BIGINT;
DECLARE v_RevenueAcc BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


    START TRANSACTION;


    SELECT a.AccID INTO v_OriginsAcc FROM
            AccountsTb a
    WHERE
            a.AccParent = p_ActivityType
            AND a.AccName LIKE '%أصول%';



    SELECT a.AccID INTO v_MaterialsAcc FROM
            AccountsTb a
    WHERE
            a.AccCode = 103020102;



    SELECT a.AccID INTO v_ExpenseAcc FROM
            AccountsTb a
    WHERE
            a.AccCode = 103020103;



    SELECT a.AccID INTO v_RevenueAcc FROM
            AccountsTb a
    WHERE
            a.AccCode = 103020104;


    IF p_TypeID = 0
       THEN
SET v_OPTYPE       = 81;
SET v_UserMovement = 'سداد مصروف';
SET v_AccFrom      = p_AccIDFrom;
SET v_AccTo        = v_ExpenseAcc;
      END IF;
    IF p_TypeID = 1
       THEN
SET v_OPTYPE       = 83;
SET v_UserMovement = 'تكلفة العملة';
SET v_AccFrom      = p_AccIDFrom;
SET v_AccTo        = v_MaterialsAcc;
      END IF;

    IF p_TypeID = 2
       THEN
SET v_OPTYPE       = 85;
SET v_UserMovement = 'مبيعات عملة';
SET v_AccFrom      = p_AccIDFrom;
SET v_AccTo        = v_RevenueAcc;
      END IF;
    IF p_IsUpdate = 0
       THEN
        SELECT a.Code INTO v_GETID FROM
                WorkshopOperationsTB AS a
        WHERE
                a.Code = p_Code;
        IF p_Code = v_GETID
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
            ROLLBACK;
            LEAVE proc;
          END IF;
        INSERT INTO WorkshopOperationsTB
              (
                CodeID,
                Code,
                InsertDate,
                BranchID,
                TypeID,
                SafeID,
                AccIDFrom,
                AccIDTO,
                NetVal,
                Note,
                ActivityAccCode,
                CountOfOperation,
                BankNo,
                CustName,
                CustBankNo,
                CustPhone
              )
            SELECT
                    p_CodeID,
                    p_Code,
                    p_InsertDate,
                    p_BranchID,
                    p_TypeID,
                    p_SafeID,
                    v_AccFrom,
                    v_AccTo,
                    p_NetVal,
                    p_Note,
                    p_ActivityType,
                    p_CountOfOperation,
                    p_BankNo,
                    p_CustName,
                    p_CustBankNo,
                    p_CustPhone;
SET v_MovementType = 'مصروفات نشاط';
        IF p_TypeID <> 2
           THEN

            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (
                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    IsActive,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    IsConfirmed,
                    IsCanceled,
                    MovementType,
                    CurrencyID,
                    DailyClosed,
                    SafeIDDailyClose,
                    Note,
                    AccSafeActivityTb.SafeIDMovement
                  )
            VALUES
                    (

                      p_SafeID,
                      0.000,
                      p_NetVal,
                      p_InsertDate,
                      p_Code,
                      1,
                      51,
                      v_OPTYPE,
                      p_BranchID,
                      v_AccFrom,
                      v_AccTo,
                      1,
                      0,
                      v_MovementType,
                      1,
                      0,
                      0,
                      p_Note, v_UserMovement
                    );


            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (

                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    IsActive,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    IsConfirmed,
                    IsCanceled,
                    MovementType,
                    CurrencyID,
                    DailyClosed,
                    SafeIDDailyClose,
                    Note,
                    AccSafeActivityTb.SafeIDMovement
                  )
            VALUES
                    (

                      p_SafeID,
                      p_NetVal,
                      0.000,
                      p_InsertDate,
                      p_Code,
                      1,
                      51,
                      v_OPTYPE,
                      p_BranchID,
                      v_AccTo,
                      v_AccFrom,
                      1,
                      0,
                      v_MovementType,
                      1,
                      0,
                      0,
                      p_Note, v_UserMovement
                    );
          END IF;
        IF p_TypeID = 2
           THEN

            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (
                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    IsActive,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    IsConfirmed,
                    IsCanceled,
                    MovementType,
                    CurrencyID,
                    DailyClosed,
                    SafeIDDailyClose,
                    Note,
                    AccSafeActivityTb.SafeIDMovement
                  )
            VALUES
                    (

                      p_SafeID,
                      p_NetVal, 0.000, p_InsertDate,
                      p_Code,
                      1,
                      51,
                      v_OPTYPE,
                      p_BranchID,
                      v_AccFrom,
                      v_AccTo,
                      1,
                      0,
                      v_MovementType,
                      1,
                      0,
                      0,
                      p_Note, v_UserMovement
                    );


            INSERT INTO ExSyAccounts_AccSafeActivityTb
                  (

                    SafeID,
                    Debit,
                    Credit,
                    InsertDate,
                    ISID,
                    IsActive,
                    TypeID,
                    OperationTypeID,
                    AccBranchID,
                    AccIDFrom,
                    AccIDTo,
                    IsConfirmed,
                    IsCanceled,
                    MovementType,
                    CurrencyID,
                    DailyClosed,
                    SafeIDDailyClose,
                    Note,
                    AccSafeActivityTb.SafeIDMovement
                  )
            VALUES
                    (

                      p_SafeID,
                      0.000, p_NetVal, p_InsertDate,
                      p_Code,
                      1,
                      51,
                      v_OPTYPE,
                      p_BranchID,
                      v_AccTo,
                      v_AccFrom,
                      1,
                      0,
                      v_MovementType,
                      1,
                      0,
                      0,
                      p_Note, v_UserMovement
                    );
          END IF;
      END IF;
    IF p_IsUpdate = 1
       THEN

        UPDATE
                WorkshopOperationsTB
        SET
                IsActive = 0
        WHERE
          Code = p_Code;
SET v_MovementType = 'تعديل قيد مصروفات';
        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (
                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                Note,
                AccSafeActivityTb.SafeIDMovement
              )
        VALUES
                (

                  p_SafeID,
                  p_NetVal,
                  0.000,
                  p_InsertDate,
                  p_Code,
                  1,
                  51,
                  v_OPTYPE,
                  p_BranchID,
                  v_AccFrom,
                  v_AccTo,
                  1,
                  0,
                  v_MovementType,
                  1,
                  0,
                  0,
                  p_Note, v_UserMovement
                );


        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (

                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                Note,
                AccSafeActivityTb.SafeIDMovement
              )
        VALUES
                (

                  p_SafeID,
                  0.000,
                  p_NetVal,
                  p_InsertDate,
                  p_Code,
                  1,
                  51,
                  v_OPTYPE,
                  p_BranchID,
                  v_AccTo,
                  v_AccFrom,
                  1,
                  0,
                  v_MovementType,
                  1,
                  0,
                  0,
                  p_Note, v_UserMovement
                );
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
    SET p_MsgBox = '';
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CONDB_ZRPT_WorkshopOperationsTB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `CONDB_ZRPT_WorkshopOperationsTB_SelectByCode`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code,
          A.InsertDate,
          B.BName,
          CASE            	WHEN a.TypeID=0 THEN 'سداد مصروف'           	WHEN a.TypeID=1 THEN 'تكلفة عملة'             WHEN a.TypeID=2 THEN 'مبيعات عملة'           END AS TypeID,
CONCAT(d.AccName, '   ', IFNULL(a.BankNo,' ')) AS AccNameTo,
a.NetVal,
c.UName,
e.AccName as ActivityName,
          CustName,
          CustBankNo,
          CustPhone,
          CASE                   WHEN A.Note = ''                     THEN                     'لا يوجد'                   ELSE                   A.Note           END       AS Notes,
          CASE                   WHEN B.Mobile1 = ''                     AND B.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN B.Mobile1 = ''                     THEN                     B.Mobile2                   WHEN B.Mobile2 = ''                     THEN                     B.Mobile1                   ELSE                   CONCAT(B.Mobile1, '-', B.Mobile2)           END       AS Phone

  FROM
          WorkshopOperationsTB  AS A
      LEFT JOIN
        CoBranch AS B
          ON A.BranchID = B.ID
      LEFT JOIN
        TB_Users AS C
          ON A.SafeID = C.USID
      LEFT JOIN
        AccountsTb AS D
          ON A.AccIDFrom = D.AccID
      LEFT JOIN
        AccountsTb AS E
          ON A.ActivityAccCode = e.AccCode

  WHERE
          A.Code = p_Code;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Countries_LoadBasedOnBranchID`;
DELIMITER //
CREATE PROCEDURE `Countries_LoadBasedOnBranchID`(IN `p_BranchID` INT)
BEGIN


    START TRANSACTION;
    SELECT
            a.ID    AS CouID,
            a.CName AS CountryName
    FROM
            CountiresTb AS a
        INNER JOIN
          CoBranch AS b
            ON a.ID = b.CountryID
    WHERE
            b.IsActive = 1
            GROUP BY a.ID,a.CName;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Countries_LoadCountryCityBasedOnBranchID`;
DELIMITER //
CREATE PROCEDURE `Countries_LoadCountryCityBasedOnBranchID`(IN `p_BranchID` INT)
BEGIN


    START TRANSACTION;
    SELECT
            b.CountryID   AS CouID,
           b.CityID        AS CTID
    FROM

          CoBranch AS b

    WHERE
            b.IsActive = 1
            AND id=p_BranchID
            GROUP BY  b.CountryID,  b.CityID;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CountriesTb_BindLKPForCities`;
DELIMITER //
CREATE PROCEDURE `CountriesTb_BindLKPForCities`(IN `p_CountryID` INT)
BEGIN
SELECT
			a.ID,
			a.CountryID
	FROM
			CitiesTb AS a
		INNER JOIN
			CountiresTb AS b
				ON a.CountryID = b.ID
	WHERE
			a.ID = p_CountryID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CountriesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CountriesTb_Insert`(IN `p_ID` INT, IN `p_CCode` VARCHAR(50), IN `p_CName` VARCHAR(150), IN `p_IsMain` TINYINT(1), IN `p_DefualtCurrency` INT)
BEGIN
DECLARE v_CheckAccExist INT;
DECLARE v_IDParent BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_acccode BIGINT;
DECLARE v_BranchID INT;
DECLARE v_DefCurr BIT;



  SELECT cmt.IsDefault INTO v_DefCurr FROM
          CurrencyMainTb cmt
  WHERE
          cmt.IsDefault = 0
 ORDER BY cmt.ID DESC LIMIT 1;
  SELECT cb.ID INTO v_BranchID FROM
          CoBranch cb

  WHERE
          cb.IsMain = 1;

  INSERT INTO CountiresTb
        (
          CCode,
          CName,
          DefualtCurrency,
          IsMain
        )
  VALUES
          (
            p_CCode, p_CName, p_DefualtCurrency, p_IsMain
          );


  IF p_IsMain = 0
    AND
    v_DefCurr = 0
     THEN

      SELECT COUNT(*) INTO v_CheckAccExist FROM
              AccountsTb AS AT
      WHERE
              AT.AccName = 'خزائن خارجية';
      IF v_CheckAccExist = 0
         THEN
          SELECT a.AccCode INTO v_IDParent FROM
                  AccountsTb AS a
          WHERE
                  a.AccName = 'الأصول المتداولة';
          SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                  AccountsTb AS a
          WHERE
                  AccParent = v_IDParent;
          IF v_IDcode IS NULL
             THEN
SET v_IDcode = 1;
            END IF;
SET v_AccName = 'خزائن خارجية';
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
          INSERT INTO AccountsTb
                (
                  AccCode,
                  AccName,
                  AccType,
                  Accline,
                  AccParent,
                  AccDmType,
                  AccFinal,
                  AccMaxLimit,
                  AccMaxDuration,
                  BranchID,
                  AccActive,
                  IDcode
                )
          VALUES
                  (
                    v_acccode, v_AccName, 0, 2, v_IDParent, 0, 1, 0, 0, 0, 1, v_IDcode
                  );
        END IF;


      SELECT COUNT(*) INTO v_CheckAccExist FROM
              AccountsTb AS AT
      WHERE
              AT.AccName = CONCAT('خزائن خارجية', SPACE(1), p_CName);
      IF v_CheckAccExist = 0
         THEN
          SELECT AccCode INTO v_IDParent FROM
                  AccountsTb AS AT
          WHERE
                  AT.AccName = 'خزائن خارجية';
          SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                  AccountsTb AS a
          WHERE
                  AccParent = v_IDParent;

          IF v_IDcode IS NULL
             THEN
SET v_IDcode = 1;
            END IF;
SET v_AccName = CONCAT('خزائن خارجية', SPACE(1), p_CName);
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
          INSERT INTO AccountsTb
                (
                  AccCode,
                  AccName,
                  AccType,
                  Accline,
                  AccParent,
                  AccDmType,
                  AccFinal,
                  AccMaxLimit,
                  AccMaxDuration,
                  BranchID,
                  AccActive,
                  IDcode,
                  CountryID
                )
          VALUES
                  (
                    v_acccode, v_AccName, 0, 3, v_IDParent, 0, 1, 0, 0, 0, 1, v_IDcode, p_ID
                  );
        END IF;


      SELECT AccCode INTO v_IDParent FROM
              AccountsTb AS AT
      WHERE
              AT.AccName = CONCAT('خزائن خارجية', SPACE(1), p_CName);
      INSERT INTO AccountsTb
            (
              AccCode,
              AccName,
              AccType,
              Accline,
              AccParent,
              AccDmType,
              AccFinal,
              AccMaxLimit,
              AccMaxDuration,
              BranchID,
              AccActive,
              IDcode,
              CountryID,
              AccCurID
            )
          SELECT
                  CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(IFNULL((SELECT
                              MAX(xx.IDcode)
                      FROM
                              AccountsTb AS xx
                      WHERE
                              xx.AccParent = v_IDParent), 0) + 1 AS CHAR))    AS AccCode,
                  CONCAT('خزينة', SPACE(1), a.CuName, SPACE(1), p_CName) AS AccName,
                  1,
                  4,
                  v_IDParent,
                  0,
                  1,
                  0,
                  0,
                  v_BranchID,
                  1,
                  IFNULL((SELECT
                              MAX(xx.IDcode)
                      FROM
                              AccountsTb AS xx
                      WHERE
                              xx.AccParent = v_IDParent), 0) + 1     AS IDcode,
                  p_ID,
                  a.ID

          FROM
                  CurrencyMainTb AS a
              INNER JOIN
                AccountsTb AS b
                  ON b.AccCode = v_IDParent
          WHERE
                  a.IsDefault <> 1
                  AND a.IsActive = 1 AND a.ID=p_DefualtCurrency;

    END IF;
END //
DELIMITER ;

