DROP PROCEDURE IF EXISTS `CreditAccounts_LOADTOLKP`;
DELIMITER //
CREATE PROCEDURE `CreditAccounts_LOADTOLKP`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
							a.AccID,
							apt.AccName ,
              a.AccPhone
					FROM
							AccountsTb  AS a
              INNER JOIN
              AddPartnerTb apt
              ON a.AccID=apt.CurrentAcc
					WHERE
							a.BranchID = p_BranchID
							AND a.AccActive=1
              AND a.AccParent LIKE '2010180%'
					ORDER BY
							a.AccName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CreditAccountsTb_CHECKNAME`;
