CREATE PROCEDURE `CreditAccountsTb_CHECKNAME`(IN `p_AccName` LONGTEXT)
BEGIN
START TRANSACTION;
	SELECT
			AccName
	FROM
			CreditAccountsTb cat
	WHERE
			cat.AccName = p_AccName;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CreditAccountsTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CreditAccountsTb_Insert`(IN `p_ID` INT, IN `p_Code` LONGTEXT, IN `p_AccName` LONGTEXT, IN `p_Phone1` VARCHAR(50), IN `p_Phone2` VARCHAR(50), IN `p_BranchID` INT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1))
BEGIN
DECLARE v_OldAccName LONGTEXT;
DECLARE v_fatherparent DECIMAL(18, 0);
DECLARE v_acccode DECIMAL(18, 0);
DECLARE v_IDcodeAcc BIGINT;
DECLARE v_AccIDIsCash BIGINT;
DECLARE v_BNAME        LONGTEXT;
DECLARE v_AccID BIGINT;
START TRANSACTION;
  IF p_IsUpdate = 0
     THEN
      INSERT INTO CreditAccountsTb
            (
              Code,
              AccName,
              Phone1,
              Phone2,
              BranchID,
              IsActive
            )
          SELECT
                  p_Code,
                  p_AccName,
                  p_Phone1,
                  p_Phone2,
                  p_BranchID,
                  p_IsActive;


      SELECT cb.BName INTO v_BNAME FROM
              CoBranch cb
      WHERE
              ID = p_BranchID;
      SELECT at.AccCode INTO v_fatherparent FROM
              AccountsTb at
      WHERE
              at.AccName = CONCAT('المدينون', ' ', v_BNAME)
              AND at.BranchID = p_BranchID;
SET v_IDcodeAcc = CAST(`AccountTb_GetIDCode`(v_fatherparent, 1) AS CHAR);
      IF v_IDcodeAcc IS NULL
         THEN
SET v_IDcodeAcc = 1;
        END IF;
SET v_acccode = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(v_IDcodeAcc AS CHAR));
      CALL ACCOUNTSTB_insert(v_acccode, p_AccName, 1, v_fatherparent, 0, 1, p_Phone1, p_Phone2, '', '', '', 0, 0, p_BranchID, 4, v_IDcodeAcc);
      SELECT at.AccID INTO v_AccID FROM
              AccountsTb at
      WHERE
              at.AccCode = v_acccode;
      UPDATE
              CreditAccountsTb
      SET
              AccID = v_AccID
      WHERE
        Code = p_Code;
    END IF;

  IF p_IsUpdate = 1
     THEN
      SELECT cat.AccName INTO v_OldAccName FROM
              CreditAccountsTb cat
      WHERE
              cat.ID = p_ID;
      IF v_OldAccName <> p_AccName
         THEN
          UPDATE
                  AccountsTb
          SET
                  AccName = p_AccName
          WHERE
            AccName = v_OldAccName;
        END IF;
      UPDATE
              CreditAccountsTb
      SET
              AccName = p_AccName, Phone1 = p_Phone1, Phone2 = p_Phone2, BranchID = p_BranchID, IsActive = p_IsActive
      WHERE
        Code = p_Code;
    END IF;
  COMMIT;
END //
DELIMITER ;

