DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_Insert`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` TINYINT(1), IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50))
proc: BEGIN
DECLARE v_GETID INT;
DECLARE v_ACCaountDR BIGINT;
DECLARE v_IsDefalut BIT;
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


			START TRANSACTION;
			SELECT CMT.IsDefault INTO v_IsDefalut FROM
					CurrencyMainTb AS CMT
					where cmt.ID=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
			SELECT IDcode INTO v_GETID FROM
					CurrenciesBuyandsellTB AS a
			WHERE
					a.IDcode = p_IDcode
					AND a.TypeOP = 24;
			IF v_GETID = p_IDcode
				 THEN
					SET p_MSGSTatues =2;
					SET p_MsgBox = 'عذرا كود العملية موجود مسبقا الرجاء المحاولة مرة أخرى ';
					ROLLBACK;
					LEAVE proc;
				END IF;

			INSERT INTO `CurrenciesBuyandsellTB`
					(
						`IDcode`,
						`Code`,
						`BranchID`,
						`SaFACCount`,
						`AccSafeTo`,
						`FirstCurrency`,
						`BPrice1`,
						`CurrencyTo`,
						`BPrice2`,
						`Notes`,
						`TotalQt`,
						TotalPriceByLD,
						`UeserInset`,
						`IsActive`,
						`countUpdate`,
						TypeOP,
						Purchasingprice,
						IsCachorBank,
						CustIDNo,
						Phone,
						thepurpose,
						CusName,
						SafeTypefrom,
						SafeTypeTo
					)
			VALUES
					(
						p_IDcode, p_Code, p_BranchID, p_SaFACCount, p_SAFFACCTO, p_FirstCurrency, p_BPrice1, p_CurrencyTo, p_BPrice2, p_Notes, 1, 0, p_UeserInset, 1, 0, 24, p_Purchaseprice, p_IsCachorBank, p_CusIDNo, p_Phone, p_thepurpose, p_CustName, p_SAFTypeform, p_SafTypeTo
					);


			SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
					CurrencyMainTb AS a
			WHERE
					a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
			SELECT AccID INTO v_FirstCurrencysASSS FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FatherPerintACC
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_FirstCurrencyd FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FAtherPERints
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_ACCFPrintCridetACC FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_ACCFPrintCridet
					AND a.BranchID = p_BranchID
					AND a.AccActive = 1;
			SELECT AccID INTO v_SAFACCAS FROM
					TB_Users AS a
			WHERE
					a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;







			IF v_IsDefalut = 1
				 THEN


					IF p_SafTypeTo = 0
						 THEN
SET v_SAFACCAS = p_SAFFACCTO;
						END IF;

					IF p_SafTypeTo <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
					CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
					CALL ExSyAccounts_AccSafeActivityTb(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
					IF p_SAFTypeform <> 0
						 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal`(p_SaFACCount, p_FirstCurrency);
							IF p_BPrice1 > v_EMPORCUST_G
								 THEN
									SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الحساب ', ', ورصيد الحساب هو : ', CAST(v_EMPORCUST_G AS CHAR));
									SET p_MSGSTatues = 0;
									ROLLBACK;
									LEAVE proc;
								END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccounts_AccSafeActivityTb(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
								CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
						END IF;

					IF p_SafTypeTo = 0
						 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, p_CurrencyTo);
							IF p_BPrice2 > v_EMPORCUST_G
								 THEN
									SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
									SET p_MSGSTatues = 0;
									ROLLBACK;
									LEAVE proc;
								END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							IF p_IsCachorBank = 0
								 THEN
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
									CALL ExSyAccounts_AccSafeActivityTb(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
								END IF;
						END IF;
					IF p_SafTypeTo = 0
						 THEN
SET v_SAFACCAS = p_SAFFACCTO;
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
					INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
							(
								`ISID`,
								`ACCFRom`,
								`ACCCRint0`,
								`CRedetTO`,
								`CRedetDL`,
								`ACC_DEPET_DL`,
								`ACC_DEPET_TO`,
								`UESER_INSERt`,
								`Inseart_Date`,
								`IsActive`,
								`BID`,
								`TYPEFROM`,
								Purchaseprice,
								AccID
							)
					VALUES
							(
								p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, p_BPrice2, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, p_Purchaseprice, v_SAFACCAS
							);
				END IF;


			IF v_IsDefalut = 0
				 THEN

					SET p_MSGSTatues = 0;
					SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
					ROLLBACK;
					LEAVE proc;
				END IF;
			COMMIT;
			SET p_MSGSTatues = 1;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_LoadNatNumber`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_LoadNatNumber`()
BEGIN
START TRANSACTION;

  SELECT
          a.CustIDNo
  FROM
          CurrenciesBuyandsellTB AS a
          WHERE a.TypeOP=25
  GROUP BY
          a.CustIDNo;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_loadtoFrm`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_loadtoFrm`(IN `p_ID` LONGTEXT)
BEGIN
DECLARE v_IsDefalut BIT;


	SELECT CMT.IsDefault INTO v_IsDefalut FROM
			CurrencyMainTb AS CMT;
	SELECT
			Code,
			InsertDate,
      a.CountryID,
			BranchID,
		CASE when	IsCachorBank = 3 THEN 2 ELSE a.IsCachorBank END AS IsCachorBank,
			CusName,
			CustIDNo,
			Phone,
			BankID,
			AccAcountBank,
			CheckType,
			AccAcountBank,
			Typeoftransaction,
			Transactionnumber,
			SafeTypefrom,
			SaFACCount,
			FirstCurrency,
			BPrice1,
			thepurpose,
			SafeTypeTo,
			AccSafeTo,
			CurrencyTo,
			Purchasingprice,
			`EMPORCUST_GetAccVal`(SaFACCount, v_IsDefalut)	   AS ACCVALFORM,
			`EMPORCUST_GetAccVal_SAfs`(SaFACCount, v_IsDefalut) AS ACCValTo,
			BPrice2,
			Notes
	FROM
			CurrenciesBuyandsellTB AS a
	WHERE
			a.Code = p_ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_MAxID`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_MAxID`(IN `p_BrnchID` INT, INOUT `p_Code` LONGTEXT, INOUT `p_IDcode` INT, IN `p_Type` INT)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;


			START TRANSACTION;
SET p_Code   = CONCAT(CAST(p_BrnchID AS CHAR), CAST(p_Type AS CHAR), '-', CAST(GETIDCurrenciesBuyandsellTB(p_Type) AS CHAR));
SET p_IDcode = GETIDCurrenciesBuyandsellTB(p_Type);
			COMMIT;



	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_selectTYPe`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_selectTYPe`(IN `p_Typesf` INT, IN `p_BranchID` INT)
BEGIN
IF p_Typesf =2
 THEN
  SELECT
          x.AccCode,
          x.AccName,
          x.Typesf,
          x.PrType
  FROM
          (   SELECT
                      a.AccCode,
                      a.AccName,
                      0 AS Typesf,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = 20105
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      2,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 10105
                      AND a.AccActive = 1
              UNION
              SELECT
                      0,
                      'نقــــــداً',
                      2,
                      0 AS PrType
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = 20103
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 1030201
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 1030202
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION






              SELECT
                      a.AccCode,
                      a.AccName,
                      1,
                      1 AS PrType

              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 101012
                      AND a.AccActive = 1

              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType

              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 2010201
                      AND a.AccActive = 1) AS x
  WHERE
          (x.Typesf = p_Typesf
          );
          END IF;
          IF p_Typesf =0 OR p_Typesf =1
 THEN
  SELECT
          x.AccCode,
          x.AccName,
          x.Typesf,
          x.PrType
  FROM
          (   SELECT
                      a.AccCode,
                      a.AccName,
                      0 AS Typesf,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = 20105
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      2,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 10105
                      AND a.AccActive = 1
              UNION
              SELECT
                      0,
                      'نقــــــداً',
                      2,
                      0 AS PrType
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = 20103
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 1030201
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType
              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 1030202
                      AND a.AccActive = 1
                      AND a.BranchID = p_BranchID
              UNION
              SELECT
                      0,
                      'نقــــــداً',
                      0,
                      0 AS PrType
              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      1,
                      1 AS PrType

              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 101012
                      AND a.AccActive = 1

              UNION
              SELECT
                      a.AccCode,
                      a.AccName,
                      0,
                      0 AS PrType

              FROM
                      AccountsTb AS a
              WHERE
                      a.AccCode = 2010201
                      AND a.AccActive = 1) AS x
  WHERE
          (x.Typesf = p_Typesf
          );
          END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTB_Update`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTB_Update`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` TINYINT(1), IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50))
proc: BEGIN
DECLARE v_ACCaountDR BIGINT;
DECLARE v_GETDATEForInsert DATE;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_Costof DECIMAL(18, 3);
DECLARE v_GET_RetunsVlaue DECIMAL(18, 3);
DECLARE v_IsDefalut BIT;
DECLARE v_OldBuyprice DECIMAL(18, 3);
DECLARE v_NewBuyprice DECIMAL(18, 3);
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_ACCACountCredit BIGINT;
DECLARE v_FathersRevenueAccount BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
			START TRANSACTION;

			SELECT CMT.IsDefault INTO v_IsDefalut FROM
					CurrencyMainTb AS CMT
					where cmt.ID=p_FirstCurrency
 ORDER BY CMT.ID DESC LIMIT 1;


					SELECT CASE 					WHEN a.Typeofsalebuyorsell = 0 						THEN 						FORMAT(a.`Purchaseprice`, 3) 						else '0.000' END INTO v_OldBuyprice FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
			where a.ISID=p_Code;

			SELECT a.BuyPrice INTO v_NewBuyprice FROM CurrencyPriceDetailsTb AS a
			 where a.Currencyidto=p_FirstCurrency;








			SELECT CASE 										  WHEN a.CurrencyPower = 1 											  THEN 											  v_OldBuyprice - v_NewBuyprice 										  ELSE 										   v_NewBuyprice - v_OldBuyprice 								  END INTO v_GET_RetunsVlaue FROM
					CurrencyPriceDetailsTb AS a
					 where a.Currencyidto=p_FirstCurrency;
			IF v_GET_RetunsVlaue < 0
				 THEN
					SET p_MsgBox = 'عذرا لايمكن استرجاع هذه القيمة لانه تم تغير سعر الصرف ';
					SET p_MSGSTatues = 0;
					ROLLBACK;
					LEAVE proc;
				END IF;
			SELECT Inseart_Date INTO v_GETDATEForInsert FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					`CurrencyPriceDetailsTb` AS b
						ON a.`ACCFRom` = b.CurrencyIDTo
			WHERE
					a.ISID = p_Code;

			IF v_GETDATEForInsert <> v_getDate
				 THEN
					SET p_MsgBox = CONCAT(' عذراً  لا يمكن استرجاع عملية سابقة لانه ليست في نفس التاريخ يمكن شراء هذه القيمة فقط في الوقت الحالي', ', وتاريخ العلملية هو  : ', CAST(v_getDate AS CHAR));
					SET p_MSGSTatues = 0;
					ROLLBACK;
					LEAVE proc;
				END IF;

			UPDATE
			 	  `CurrenciesBuyandsellTB`
			SET
					`BranchID` = p_BranchID,
					`SaFACCount` = p_SaFACCount,
					`AccSafeTo` = p_SAFFACCTO,
					`FirstCurrency` = p_FirstCurrency,
					`BPrice1` = p_BPrice1,
					`CurrencyTo` = p_CurrencyTo,
					`BPrice2` = p_BPrice2,
					`Notes` = p_Notes,
					`TotalQt` = 1,
					TotalPriceByLD = 0,
					`UeserInset` = p_UeserInset,
					`IsActive` = 0,
					`countUpdate` = 0,
					TypeOP = 24,
					Purchasingprice = v_OldBuyprice,
					IsCachorBank = p_IsCachorBank,
					CustIDNo = p_CusIDNo,
					Phone = p_Phone,
					thepurpose = p_thepurpose,
					CusName = p_CustName,
					SafeTypefrom = p_SAFTypeform,
					SafeTypeTo = p_SafTypeTo,
					UeserUpDate = NOW(),
					UserUpdate = p_UeserInset
			WHERE
				Code = p_Code;

			SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet, a.FathersRevenueAccount INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet, v_FathersRevenueAccount FROM
					CurrencyMainTb AS a
			WHERE
					a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
			SELECT AccID INTO v_FirstCurrencysASSS FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FatherPerintACC
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_FirstCurrencyd FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FAtherPERints
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_ACCFPrintCridetACC FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_ACCFPrintCridet
					AND a.BranchID = p_BranchID
					AND a.AccActive = 1;
			SELECT AccID INTO v_ACCACountCredit FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FathersRevenueAccount
					AND a.BranchID = p_BranchID
					AND a.AccActive = 1;

			SELECT AccID INTO v_SAFACCAS FROM
					TB_Users AS a
			WHERE
					a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;



			IF p_SAFTypeform = 0
				 THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency);
					IF p_BPrice1 > v_EMPORCUST_G
						 THEN
							SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
							SET p_MSGSTatues = 0;
							ROLLBACK;
							LEAVE proc;
						END IF;

