							a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(v_SAFACCAS, p_FirstCurrency);
					IF p_BPrice1 > v_EMPORCUST_G
						 THEN
