							SET p_MSGSTatues = 0;
							ROLLBACK;
							LEAVE proc;
						END IF;
				END IF;


			IF v_IsDefalut = 0
				 THEN
					IF p_SafTypeTo = 0
						 THEN
SET v_SAFACCAS = p_SAFFACCTO;
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
