									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
SET v_MovementType   = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
					IF p_SAFTypeform <> 0
						 THEN
SET v_MovementType   = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
					if p_SafTypeTo<>0
					 THEN
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 22, 22, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
								CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 22, 22, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
						END IF;
					IF p_SafTypeTo = 0
						 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, v_IsDefalut);
SET v_MovementType   = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
									CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							IF p_IsCachorBank = 0
								 THEN
SET v_MovementType   = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
					if p_SAFTypeform=0
					 THEN
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;

											CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
									CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
								END IF;
						END IF;
					IF p_SafTypeTo = 0
						 THEN
SET v_SAFACCAS = p_SAFFACCTO;
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
					INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
							(
								`ISID`,
								`ACCFRom`,
								`ACCCRint0`,
								`CRedetTO`,
								`CRedetDL`,
								`ACC_DEPET_DL`,
								`ACC_DEPET_TO`,
								`UESER_INSERt`,
								`Inseart_Date`,
								`IsActive`,
								`BID`,
								`TYPEFROM`,
								Purchaseprice,
								AccID,
								Typeofsalebuyorsell,
								NetSale
							)
					VALUES
							(
								p_Code, p_FirstCurrency, p_CurrencyTo, 0.00, 0.00, p_BPrice2, p_BPrice1, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, v_OldBuyprice, v_SAFACCAS, 2, 0.000
							);
				END IF;
			IF v_IsDefalut = 1
				 THEN
					SET p_MSGSTatues = 0;
					SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
					ROLLBACK;
					LEAVE proc;
				END IF;
			COMMIT;
			SET p_MSGSTatues = 1;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTSElecSPreceB_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTSElecSPreceB_Insert`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` TINYINT(1), IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50))
proc: BEGIN
DECLARE v_GETID INT;
DECLARE v_ACCaountDR BIGINT;
DECLARE v_IsDefalut BIT;
DECLARE v_DEbitValue DECIMAL(13, 3);
DECLARE v_BuyPrice DECIMAL(13, 3);
DECLARE v_ACCRevenueCalculation BIGINT;
DECLARE v_valueevenueCalculation DECIMAL(13, 3);
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;

			START TRANSACTION;
			SELECT CMT.IsDefault INTO v_IsDefalut FROM
					CurrencyMainTb AS CMT
					where cmt.ID=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
			SELECT IFNULL(IDcode, 0) INTO v_GETID FROM
					CurrenciesBuyandsellTB AS a
			WHERE
					a.IDcode = p_IDcode
					AND a.TypeOP = 25;
			IF v_GETID = p_IDcode
				 THEN
					SET p_MSGSTatues = 2;
					SET p_MsgBox = 'عذرا كود العملية موجود مسبقا الرجاء المحاولة مرة أخرى ';
					ROLLBACK;
					LEAVE proc;
				END IF;






			SELECT CASE 									   WHEN a.CurrencyPower = 1 										   THEN 										   a.Costof 									   ELSE 									   1 / a.Costof 							   END INTO v_BuyPrice FROM
					GET_TABLE_FOR_Costof AS a
			WHERE
					a.ACCFRom = p_FirstCurrency
					AND a.BID = p_BranchID;

			INSERT INTO  `CurrenciesBuyandsellTB`
					(
						`IDcode`,
						`Code`,
						`BranchID`,
						`SaFACCount`,
						`AccSafeTo`,
						`FirstCurrency`,
						`BPrice1`,
						`CurrencyTo`,
						`BPrice2`,
						`Notes`,
						`TotalQt`,
						TotalPriceByLD,
						`UeserInset`,
						`IsActive`,
						`countUpdate`,
						TypeOP,
						Purchasingprice,
						IsCachorBank,
						CustIDNo,
						Phone,
						thepurpose,
						CusName,
						SafeTypefrom,
						SafeTypeTo
					)
			VALUES
					(
						p_IDcode, p_Code, p_BranchID, p_SaFACCount, p_SAFFACCTO, p_FirstCurrency, p_BPrice1, p_CurrencyTo, p_BPrice2, p_Notes, 1, 0, p_UeserInset, 1, 0, 25, p_Purchaseprice, p_IsCachorBank, p_CusIDNo, p_Phone, p_thepurpose, p_CustName, p_SAFTypeform, p_SafTypeTo
					);


			SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
					CurrencyMainTb AS a
			WHERE
					a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
			SELECT AccID INTO v_FirstCurrencysASSS FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FatherPerintACC
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_FirstCurrencyd FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FAtherPERints
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_ACCFPrintCridetACC FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_ACCFPrintCridet
					AND a.BranchID = p_BranchID
					AND a.AccActive = 1;
			SELECT AccID INTO v_SAFACCAS FROM
					TB_Users AS a
			WHERE
					a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;


			IF v_IsDefalut = 1
				 THEN


					IF p_SAFTypeform = 0
						 THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_EMPORCUST_G = `BranchCur_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency,p_BranchID);
							IF p_BPrice1 > v_EMPORCUST_G
								 THEN

									SET p_MsgBox = 'عذرا الشركة لايمكنها تغطية هذه القيمة حاليا الرجاء التواصل مع الإدارة بالخصوص ';
									SET p_MSGSTatues = 0;
									ROLLBACK;
									LEAVE proc;
								END IF;
						END IF;

					IF p_SAFTypeform <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_EMPORCUST_G = `BranchCur_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency,p_BranchID);
							IF p_BPrice1 > v_EMPORCUST_G
								 THEN
									SET p_MsgBox = 'عذرا الشركة لايمكنها تغطية هذه القيمة حاليا الرجاء التواصل مع الإدارة بالخصوص ';
									SET p_MSGSTatues = 0;
									ROLLBACK;
									LEAVE proc;
								END IF;
						END IF;
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
					CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
SET v_DEbitValue = Floor(p_BPrice1 * v_BuyPrice);
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, v_DEbitValue, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
					IF p_SAFTypeform <> 0
						 THEN
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 22, 22, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
								CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 22, 22, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
						END IF;
					IF p_SafTypeTo = 0
						 THEN
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0.00, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;

					IF p_SafTypeTo <> 0
						 THEN

							IF p_IsCachorBank = 0
								 THEN
SET v_EMPORCUST_G = `EMPCUST_GetAccValCashOnly`(p_SAFFACCTO);
									IF p_BPrice2 > v_EMPORCUST_G
										 THEN
											SET p_MsgBox = 'عذرا رصيد العميل النقدي لا يغطي هذه العملية';
											SET p_MSGSTatues = 0;
											ROLLBACK;
											LEAVE proc;
										END IF;
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
									CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
								END IF;

						END IF;


					IF p_SAFTypeform = 0
						 THEN
SET v_SAFACCAS = p_SaFACCount;
						END IF;

					IF p_SAFTypeform <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;
					INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
							(
								`ISID`,
								`ACCFRom`,
								`ACCCRint0`,
								`CRedetTO`,
								`CRedetDL`,
								`ACC_DEPET_DL`,
								`ACC_DEPET_TO`,
								`UESER_INSERt`,
								`Inseart_Date`,
								`IsActive`,
								`BID`,
								`TYPEFROM`,
								Purchaseprice,
								AccID,
								Typeofsalebuyorsell,
								NetSale,
								salesPurchaseprice
							)
					VALUES
							(
								p_Code, p_FirstCurrency, p_CurrencyTo, 0.000, 0.00, v_DEbitValue, p_BPrice1, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, v_BuyPrice, v_SAFACCAS, 1, v_valueevenueCalculation, p_Purchaseprice
							);
SET v_DEbitValue = Floor(p_BPrice1 * v_BuyPrice);SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;
					IF v_valueevenueCalculation > 0
						 THEN
							SELECT FathersRevenueAccount INTO v_FatherPerintACC FROM
									`CurrencyMainTb` AS a
							WHERE
									a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
							SELECT AccID INTO v_ACCRevenueCalculation FROM
									AccountsTb AS a
							WHERE
									a.AccParent = v_FatherPerintACC
									AND a.BranchID = p_BranchID;
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, v_valueevenueCalculation, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;


					IF v_valueevenueCalculation < 0
						 THEN
							SELECT FathersLossAccount INTO v_FatherPerintACC FROM
									`CurrencyMainTb` AS a
							WHERE
									a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
							SELECT AccID INTO v_ACCRevenueCalculation FROM
									AccountsTb AS a
							WHERE
									a.AccParent = v_FatherPerintACC
									AND a.BranchID = p_BranchID;
SET v_MovementType   = 'بيع عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);SET v_valueevenueCalculation = v_DEbitValue - p_BPrice2;
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, v_valueevenueCalculation, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;

				END IF;


			IF v_IsDefalut = 0
				 THEN

					SET p_MSGSTatues = 0;
					SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
					ROLLBACK;
					LEAVE proc;
				END IF;

			COMMIT;
			SET p_MSGSTatues = 1;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrenciesBuyandsellTSElecSPreceB_Updata`;
DELIMITER //
CREATE PROCEDURE `CurrenciesBuyandsellTSElecSPreceB_Updata`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` TINYINT(1), IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50))
proc: BEGIN
DECLARE v_DEbitValue DECIMAL(13, 3);
DECLARE v_BuyPrice DECIMAL(13, 3);
DECLARE v_ACCRevenueCalculation BIGINT;
DECLARE v_valueevenueCalculation DECIMAL(13, 3);
DECLARE v_GETDATEForInsert DATE;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_GET_RetunsVlaue DECIMAL(18, 3);
DECLARE v_IsDefalut BIT;
DECLARE v_OldSlerice DECIMAL(18, 3);
DECLARE v_NewSaleprice DECIMAL(18, 3);
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE v_STATUESValueevenueCalculatio DECIMAL(13, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
			START TRANSACTION;
			SELECT CMT.IsDefault INTO v_IsDefalut FROM
					CurrencyMainTb AS CMT
					where cmt.ID=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;


					SELECT CASE 					WHEN a.Typeofsalebuyorsell = 1 						THEN 						IFNULL(salesPurchaseprice, 0.000) END INTO v_OldSlerice FROM
			 ExSyAccountsCurrency_CurrencymovementPruse AS a
			where a.ISID=p_Code;

			SELECT a.SalePrice INTO v_NewSaleprice FROM  CurrencyPriceDetailsTb AS a
			 where a.Currencyidto=p_FirstCurrency;


			SELECT CASE 										  WHEN a.CurrencyPower = 1 											  THEN 											  v_NewSaleprice - v_OldSlerice 										  ELSE 										  v_OldSlerice - v_NewSaleprice  								  END INTO v_GET_RetunsVlaue FROM
					CurrencyPriceDetailsTb AS a
					 where a.Currencyidto=p_FirstCurrency;
			IF v_GET_RetunsVlaue < 0
				 THEN
					SET p_MsgBox = 'عذرا لايمكن استرجاع هذه القيمة لانه تم تغير سعر الصرف ';
					SET p_MSGSTatues = 0;
					ROLLBACK;
					LEAVE proc;
				END IF;




















			SELECT CASE 									   WHEN a.CurrencyPower = 1 										   THEN 										   a.Costof 									   ELSE 									   1 / a.Costof 							   END INTO v_BuyPrice FROM
					GET_TABLE_FOR_Costof AS a
			WHERE
					a.ACCFRom = p_FirstCurrency
					AND a.BID = p_BranchID;


			IF v_GETDATEForInsert <> v_getDate
				 THEN

					SET p_MsgBox = CONCAT(' عذراً  لا يمكن استرجاع عملية سابقة لانه ليست في نفس التاريخ يمكن شراء هذه القيمة فقط في الوقت الحالي', ', وتاريخ العلملية هو  : ', CAST(v_GETDATEForInsert AS CHAR));
					SET p_MSGSTatues = 0;
					ROLLBACK;
					LEAVE proc;


				END IF;



			UPDATE
					`CurrenciesBuyandsellTB`
			SET

					`Code` = p_Code,
					`BranchID` = p_BranchID,
					`SaFACCount` = p_SaFACCount,
					`AccSafeTo` = p_SAFFACCTO,
					`FirstCurrency` = p_FirstCurrency,
					`BPrice1` = p_BPrice1,
					`CurrencyTo` = p_CurrencyTo,
					`BPrice2` = p_BPrice2,
					`Notes` = p_Notes,
					`TotalQt` = 1,
					TotalPriceByLD = 0,
					`UeserInset` = p_UeserInset,
					`IsActive` = 0,
					`countUpdate` = 0,
					TypeOP = 25,
					Purchasingprice = p_Purchaseprice,
					IsCachorBank = p_IsCachorBank,
					CustIDNo = p_CusIDNo,
					Phone = p_Phone,
					thepurpose = p_thepurpose,
					CusName = p_CustName,
					SafeTypefrom = p_SAFTypeform,
					SafeTypeTo = p_SafTypeTo,
					UeserUpDate = NOW(),
					UserUpdate = p_UeserInset
			WHERE
				Code = p_Code;


			SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
					CurrencyMainTb AS a
			WHERE
					a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
			SELECT AccID INTO v_FirstCurrencysASSS FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FatherPerintACC
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_FirstCurrencyd FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_FAtherPERints
					AND a.BranchID = p_BranchID;
			SELECT AccID INTO v_ACCFPrintCridetACC FROM
					AccountsTb AS a
			WHERE
					a.AccParent = v_ACCFPrintCridet
					AND a.BranchID = p_BranchID
					AND a.AccActive = 1;
			SELECT AccID INTO v_SAFACCAS FROM
					TB_Users AS a
			WHERE
					a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;






			IF v_IsDefalut = 1
				 THEN



					IF p_SAFTypeform = 0
						 THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency);
						END IF;
					IF p_SAFTypeform <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(v_SAFACCAS, p_FirstCurrency);
						END IF;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
					CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
SET v_DEbitValue = p_BPrice1 * v_BuyPrice;
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, v_DEbitValue, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
					IF p_SAFTypeform <> 0
						 THEN
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
							CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
						   CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
						END IF;

					IF p_SafTypeTo = 0
						 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, p_CurrencyTo);
							IF p_BPrice2 > v_EMPORCUST_G
								 THEN
									SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
									SET p_MSGSTatues = 0;
									ROLLBACK;
									LEAVE proc;
								END IF;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0.00, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;
					IF p_SafTypeTo <> 0
						 THEN
							IF p_IsCachorBank = 0
								 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal`(p_SAFFACCTO, v_IsDefalut);
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
									CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
								END IF;
						END IF;

					IF p_SAFTypeform = 0
						 THEN
SET v_SAFACCAS = p_SaFACCount;
						END IF;
					IF p_SAFTypeform <> 0
						 THEN
							SELECT AccID INTO v_SAFACCAS FROM
									TB_Users AS a
							WHERE
									a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
						END IF;
SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;SET v_valueevenueCalculation = CASE 															 WHEN p_BPrice2 - v_DEbitValue > 0 																 THEN 																 v_DEbitValue - p_BPrice2 															 ELSE 															 v_DEbitValue - p_BPrice2 													 END;
					INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
							(
								`ISID`,
								`ACCFRom`,
								`ACCCRint0`,
								`CRedetTO`,
								`CRedetDL`,
								`ACC_DEPET_DL`,
								`ACC_DEPET_TO`,
								`UESER_INSERt`,
								`Inseart_Date`,
								`IsActive`,
								`BID`,
								`TYPEFROM`,
								Purchaseprice,
								AccID,
								Typeofsalebuyorsell,
								NetSale,
								salesPurchaseprice
							)
					VALUES
							(
								p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, v_DEbitValue, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, v_BuyPrice, v_SAFACCAS, 3, v_valueevenueCalculation, p_Purchaseprice
							);

SET v_DEbitValue = p_BPrice1 * v_BuyPrice;
SET v_STATUESValueevenueCalculatio = p_BPrice2 - v_DEbitValue;
					IF v_STATUESValueevenueCalculatio < 0
						 THEN
SET v_valueevenueCalculation = v_DEbitValue - p_BPrice2;
							SELECT FathersRevenueAccount INTO v_FatherPerintACC FROM
									`CurrencyMainTb` AS a
							WHERE
									a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
							SELECT AccID INTO v_ACCRevenueCalculation FROM
									AccountsTb AS a
							WHERE
									a.AccParent = v_FatherPerintACC
									AND a.BranchID = p_BranchID;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, v_valueevenueCalculation, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;

					IF v_STATUESValueevenueCalculatio > 0
						 THEN
							SELECT FathersLossAccount INTO v_FatherPerintACC FROM
									`CurrencyMainTb` AS a
							WHERE
									a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
							SELECT AccID INTO v_ACCRevenueCalculation FROM
									AccountsTb AS a
							WHERE
									a.AccParent = v_FatherPerintACC
									AND a.BranchID = p_BranchID;
SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;
							CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, v_valueevenueCalculation, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
						END IF;
				END IF;

			IF v_IsDefalut = 0
				 THEN
					SET p_MSGSTatues = 0;
					SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
					ROLLBACK;
					LEAVE proc;
				END IF;
			COMMIT;
			SET p_MSGSTatues = 1;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Currency_settingForBancksRet_insert`;
DELIMITER //
CREATE PROCEDURE `Currency_settingForBancksRet_insert`(IN `p_ID` TINYINT UNSIGNED, IN `p_CurrencyFrom` INT, IN `p_CurrencyTo` INT, IN `p_BuyPrice` DECIMAL(13,3), IN `p_SalePrice` DECIMAL(13,3), IN `p_RetBuyPrice` DECIMAL(13,3), IN `p_retSalePrice` DECIMAL(13,3), IN `p_Userinser` INT)
BEGIN
DECLARE v_IDcode TINYINT;
DECLARE v_updateCount INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;

			START TRANSACTION;

			SELECT `ID` INTO v_IDcode FROM
					`Currency_settingForBancksRet` AS a
			WHERE
					a.ID = p_ID;

			IF v_IDcode IS NULL
				 THEN
					INSERT INTO `Currency_settingForBancksRet`
							(
								`ID`,
								`CurrencyFrom`,
								`CurrencyTo`,
								`BuyPrice`,
								`SalePrice`,
								`RetBuyPrice`,
								`retSalePrice`,
								`insertDate`,
								`Userinser`,
								`ISactive`,
								`updateCount`
							)
					VALUES
							(
								p_ID, p_CurrencyFrom, p_CurrencyTo, p_BuyPrice, p_SalePrice, p_RetBuyPrice, p_retSalePrice, NOW(), p_Userinser, 1, 0
							);

					INSERT INTO `CurrencyPriceDetailsBancksTb`
							(
								`CPID`,
								`Banck_ID`,
								`CurrencyIDFrom`,
								`CurrencyIDTo`,
								`SalePrice`,
								`BuyPrice`,
								`CurrencyPower`,
								`ISactive`
							)
						SELECT
								a.CPID,
								a.BanckID,
								a.CurrencyIDFrom,
								a.CurrencyIDTo,
								a.BankSalePrice,
								a.BankBuyPrice,
								a.CurrencyPower,
								1
						FROM
								(SELECT
					a.ID,
					BankName,
					c.ID,
					c.CuName,
					(p_ID),
					B.CurrencyIDFrom,
					B.CurrencyIDTo,
					CurrencyPower,

					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_SalePrice) 							ELSE 							B.SalePrice * (p_retSalePrice) 					END,
					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_BuyPrice) 							ELSE 							B.BuyPrice * (p_RetBuyPrice) 					END
			FROM
					BanksTb AS a
				CROSS JOIN
					CurrencyMainTb AS c
				INNER JOIN
					CurrencyPriceDetailsTb AS B
						ON c.ID = B.CurrencyIDTo
			ORDER BY
					a.ID) AS a
						WHERE
								a.CPID = p_ID
						ORDER BY
								BanckID;
				END IF;

			IF v_IDcode IS NOT NULL


				 THEN

					SELECT updateCount INTO v_updateCount FROM
							Currency_settingForBancksRet
					WHERE
							ID = p_ID;
					DELETE FROM CurrencyPriceDetailsBancksTb WHERE
							CPID = p_ID;
					UPDATE
							`Currency_settingForBancksRet`
					SET
							`CurrencyFrom` = p_CurrencyFrom,
							`CurrencyTo` = p_CurrencyTo,
							`BuyPrice` = p_BuyPrice,
							`SalePrice` = p_SalePrice,
							`RetBuyPrice` = p_RetBuyPrice,
							`retSalePrice` = p_retSalePrice,
							`Updatedate` = NOW(),
							`userUpdate` = p_Userinser,
							`ISactive` = 1,
							`updateCount` = v_updateCount + 1
					WHERE
						ID = p_ID;

					INSERT INTO `CurrencyPriceDetailsBancksTb`
							(
								`CPID`,
								`Banck_ID`,
								`CurrencyIDFrom`,
								`CurrencyIDTo`,
								`SalePrice`,
								`BuyPrice`,
								`CurrencyPower`,
								`ISactive`
							)
						SELECT
								a.CPID,
								a.BanckID,
								a.CurrencyIDFrom,
								a.CurrencyIDTo,
								a.BankSalePrice,
								a.BankBuyPrice,
								a.CurrencyPower,
								1

						FROM
								(SELECT
					a.ID,
					BankName,
					c.ID,
					c.CuName,
					(p_ID),
					B.CurrencyIDFrom,
					B.CurrencyIDTo,
					CurrencyPower,

					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_SalePrice) 							ELSE 							B.SalePrice * (p_retSalePrice) 					END,
					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_BuyPrice) 							ELSE 							B.BuyPrice * (p_RetBuyPrice) 					END
			FROM
					BanksTb AS a
				CROSS JOIN
					CurrencyMainTb AS c
				INNER JOIN
					CurrencyPriceDetailsTb AS B
						ON c.ID = B.CurrencyIDTo
			ORDER BY
					a.ID) AS a
						WHERE
								a.CPID = p_ID
						ORDER BY
								BanckID;
				END IF;



			INSERT INTO CurrencyMovements2024.`CurrencyMovementsTable`
					(
						`TYPE`,
						`ISID`,
						`CurrencyFrom`,
						`CurrencyTo`,
						`BuyPrice`,
						`SalePrice`,
						`RetBuyPrice`,
						`retSalePrice`,
						`Ueserinsert`,
						`TypeMovet`
					)
				SELECT
						1,
						a.BanckID,
						a.CurrencyIDFrom,
						a.CurrencyIDTo,
						a.BankBuyPrice,
						a.BankSalePrice,
						p_RetBuyPrice,
						p_retSalePrice,
						p_Userinser,
						0
				FROM
						(SELECT
					a.ID,
					BankName,
					c.ID,
					c.CuName,
					(p_ID),
					B.CurrencyIDFrom,
					B.CurrencyIDTo,
					CurrencyPower,

					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_SalePrice) 							ELSE 							B.SalePrice * (p_retSalePrice) 					END,
					CASE 							WHEN B.CurrencyIDTo = 2 								THEN 								(p_BuyPrice) 							ELSE 							B.BuyPrice * (p_RetBuyPrice) 					END
			FROM
					BanksTb AS a
				CROSS JOIN
					CurrencyMainTb AS c
				INNER JOIN
					CurrencyPriceDetailsTb AS B
						ON c.ID = B.CurrencyIDTo
			ORDER BY
					a.ID) AS a
				WHERE
						a.CPID = p_ID
				ORDER BY
						BanckID;
			COMMIT;



	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyActivityTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrencyActivityTb_Insert`(IN `p_InserDate` DATE, IN `p_SafeCurID` INT, IN `p_SDebit` DECIMAL(15,3), IN `p_SCredit` DECIMAL(15,3), IN `p_CurrencyID` INT, IN `p_BranchID` INT, IN `p_SafeID` INT, IN `p_CCode` LONGTEXT, IN `p_Notes` LONGTEXT, IN `p_SafeCurTo` INT)
BEGIN
START TRANSACTION;
	INSERT INTO CurrencyActivityTb
			(
				InserDate,
				SafeCurID,
				SDebit,
				SCredit,
				CurrencyID,
				BranchID,
				SafeID,
				Isactive,
				Notes,
				CCode,
				SafeCurTo
			)
	VALUES
			(
				p_InserDate, p_SafeCurID, p_SDebit, p_SCredit, p_CurrencyID, p_BranchID, p_SafeID, 1, p_Notes, p_CCode, p_SafeCurTo
			);
	SELECT
			CurrencyActivityTb.ID,
			CurrencyActivityTb.InserDate,
			CurrencyActivityTb.SafeCurID,
			CurrencyActivityTb.SDebit,
			CurrencyActivityTb.SCredit,
			CurrencyActivityTb.CurrencyID,
			CurrencyActivityTb.BranchID,
			CurrencyActivityTb.SafeID,
			CurrencyActivityTb.Isactive,
			CurrencyActivityTb.Notes,
			CurrencyActivityTb.CCode,
			CurrencyActivityTb.SafeCurTo
	FROM
			CurrencyActivityTb
	WHERE
			(CurrencyActivityTb.ID = LAST_INSERT_ID());
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyActivityTb_SEARCH`;
DELIMITER //
CREATE PROCEDURE `CurrencyActivityTb_SEARCH`(IN `p_CCode` LONGTEXT)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY CCode ASC) AS '#',
			a.CCode								   AS 'الرمز',
			a.InserDate							   AS 'التاريخ',
			c.UName								   AS 'الخزنة المنقول منها',
			d.UName								   AS 'الخزنة المنقول إليها',
			a.SDebit							   AS 'القيمة'
	FROM
			CurrencyActivityTb AS a
		INNER JOIN
			CurrencyTb AS b
				ON a.CurrencyID = b.ID
		INNER JOIN
			TB_Users AS c
				ON a.SafeCurID = c.USID
		INNER JOIN
			TB_Users AS d
				ON a.SafeCurTo = d.USID
	WHERE
			a.IsActive = 1
			AND a.CCode = p_CCode;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyActivityTb_SelectALL`;
DELIMITER //
CREATE PROCEDURE `CurrencyActivityTb_SelectALL`(IN `p_CCode` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			ID,
			InserDate,
			SafeCurID,
			SDebit,
			SCredit,
			CurrencyID,
			BranchID,
			SafeID,
			Notes,
			CCode,
			SafeCurTo
	FROM
			CurrencyActivityTb
	WHERE
			(		CCode = p_CCode
					OR p_CCode IS NULL
					AND IsActive = 1);

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyActivityTb_Update`;
DELIMITER //
CREATE PROCEDURE `CurrencyActivityTb_Update`(IN `p_InserDate` DATE, IN `p_SafeCurID` INT, IN `p_SDebit` DECIMAL(15,3), IN `p_SCredit` DECIMAL(15,3), IN `p_CurrencyID` INT, IN `p_BranchID` INT, IN `p_SafeID` INT, IN `p_CCode` LONGTEXT, IN `p_Notes` LONGTEXT, IN `p_SafeCurTo` INT)
BEGIN
START TRANSACTION;
	UPDATE
			CurrencyActivityTb
	SET
			InserDate = p_InserDate, SafeCurID = p_SafeCurID, SDebit = p_SDebit, SCredit = p_SCredit, CurrencyID = p_CurrencyID, BranchID = p_BranchID, SafeID = p_SafeID, IsActive = 1, Notes = p_Notes, SafeCurTo = p_SafeCurTo
	WHERE
		(   CCode = p_CCode
			OR p_CCode IS NULL);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyBuyAndSale_LoadSafe`;
DELIMITER //
CREATE PROCEDURE `CurrencyBuyAndSale_LoadSafe`(IN `p_Type` INT, IN `p_UserID` INT, IN `p_UESERTYPE` INT, IN `p_BRnchID` INT, IN `p_CountryID` INT, IN `p_CurrID` INT, IN `p_TransType` INT, IN `p_Typesf` INT, IN `p_Action` INT)
BEGIN
DECLARE v_ErrorMessage  VARCHAR(4000);
DECLARE v_ErrorSeverity INT;
DECLARE v_ErrorState    INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
SET v_ErrorSeverity = ERROR_SEVERITY();
SET v_ErrorState    = ERROR_STATE();
    IF p_Action = 0
       THEN
        IF p_TransType = 0
          AND
          p_Typesf <> 2
           THEN
            IF p_Type = 0
               THEN
SET v_ErrorMessage  = '1';
SET v_ErrorSeverity = ERROR_SEVERITY();
SET v_ErrorState    = ERROR_STATE();
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='error';
                SELECT
                        a.AccID,
                        a.UName AS AccName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        b.BranchID = p_BRnchID
                        AND a.USID = p_UserID
                        AND p_UESERTYPE <> 1
                        AND a.IsActive = 1
                UNION
                SELECT
                        a.AccID,
                        a.UName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        a.BranchID = p_BRnchID
                        AND p_UESERTYPE = 1
                        AND a.IsActive = 1;
              END IF;
            IF p_Type <> 0
               THEN
SET v_ErrorMessage  = '2';
SET v_ErrorSeverity = ERROR_SEVERITY();
SET v_ErrorState    = ERROR_STATE();
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='error';
                SELECT
                        A.AccID,
                        A.AccName
                FROM
                        AccountsTb AS A
                    LEFT JOIN
                      `EmployeeTb` AS b
                        ON A.AccID = b.AccID
                    LEFT JOIN
                      CustomersTb AS c
                        ON A.AccID = c.AccID
                    LEFT JOIN
                      CoBranch AS d
                        ON a.AccID = d.CurrentAccID
                WHERE
                        A.AccParent = p_Type
                        AND A.AccActive = 1
                        AND (   b.IsActive = 1
                                OR c.IsActive = 1
                                OR (    d.IsActive = 1
                                        AND d.BranchType = 3));
              END IF;
          END IF;
        IF p_TransType = 1
          AND
          p_Typesf <> 2
           THEN
            IF p_Type <> 0
               THEN
SET v_ErrorMessage  = '3';
SET v_ErrorSeverity = ERROR_SEVERITY();
SET v_ErrorState    = ERROR_STATE();
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='error';
                SELECT
                        a.AccID,
                        a.AccName

                FROM
                        `AccountsTb` AS a
                WHERE
                        SUBSTRING(CAST(a.AccParent AS CHAR), 0, 7) = p_Type
                        AND a.Accline = 4
                        AND a.CountryID = p_CountryID
                GROUP BY
                        A.AccID,
                        A.AccName;


              END IF;
          END IF;
        IF p_TransType = 0
          AND
          p_Typesf = 2
           THEN
            IF p_Type <> 0
               THEN
SET v_ErrorMessage  = '4';
SET v_ErrorSeverity = ERROR_SEVERITY();
SET v_ErrorState    = ERROR_STATE();
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='error';
                SELECT
                        a.AccID,
                        a.AccName

                FROM
                        `AccountsTb` AS a
                    INNER JOIN
                      BBranchTb AS b
                        ON a.AccID = b.AccID
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS c
                        ON b.ID = c.BankID

                WHERE
                        SUBSTRING(CAST(a.AccParent AS CHAR), 0, 6) = p_Type
                        AND a.Accline = 4
                        AND a.BranchID = p_BRnchID
                        AND a.AccCurID = p_CurrID
                GROUP BY
                        A.AccID,
                        A.AccName
                HAVING
                        Account_GetAccVal(a.AccID, p_CurrID, 2) > 0.000;


              END IF;
          END IF;
      END IF;
    IF p_Action = 1
       THEN
        IF p_TransType = 0
          AND
          p_Typesf <> 2

           THEN
            IF p_Type = 0
               THEN

                SELECT
                        a.AccID,
                        a.UName AS AccName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        b.BranchID = p_BRnchID
                        AND a.USID = p_UserID
                        AND p_UESERTYPE <> 1
                        AND a.IsActive = 1
                UNION
                SELECT
                        a.AccID,
                        a.UName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        a.BranchID = p_BRnchID
                        AND p_UESERTYPE = 1
                        AND a.IsActive = 1;

              END IF;
            IF p_Type <> 0

               THEN

                SELECT
                        A.AccID,
                        A.AccName
                FROM
                        AccountsTb AS A
                WHERE
                        A.AccParent = p_Type
                        AND A.AccActive = 1
                GROUP BY
                        A.AccID,
                        A.AccName
                HAVING
                        `SafeIDEMP_GetCurrCustAccVal`(A.AccID, p_BRnchID) > 0.000;
              END IF;
          END IF;
        IF p_TransType = 1
          AND
          p_Typesf <> 2
           THEN
            SELECT
                    AccID,
                    AccName

            FROM
                    `AccountsTb` AS a
            WHERE
                    SUBSTRING(CAST(a.AccParent AS CHAR), 0, 7) = p_Type
                    AND a.Accline = 4
                    AND a.CountryID = p_CountryID
            GROUP BY
                    a.AccID,
                    a.AccName
                             HAVING
                        `SafeIDEMP_GetCurrAccVal`(a.AccID, p_BRnchID) > 0.000;

          END IF;
        IF p_TransType = 0
          AND
          p_Typesf = 2
           THEN
            IF p_Type <> 0
               THEN
                SELECT
                        a.AccID,
                        a.AccName

                FROM
                        `AccountsTb` AS a
                    INNER JOIN
                      BBranchTb AS b
                        ON a.AccID = b.AccID

                WHERE
                        SUBSTRING(CAST(a.AccParent AS CHAR), 0, 6) = p_Type
                        AND a.Accline = 4
                        AND a.BranchID = p_BRnchID
                        AND a.AccCurID = p_CurrID

                GROUP BY
                        A.AccID,
                        A.AccName;


              END IF;
          END IF;
      END IF;
    IF p_Action = 2
       THEN
        IF p_TransType = 0
          AND
          p_Typesf <> 2
           THEN
            IF p_Type = 0
               THEN

                SELECT
                        a.AccID,
                        a.UName AS AccName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        b.BranchID = p_BRnchID
                        AND a.USID = p_UserID
                        AND p_UESERTYPE <> 1
                        AND a.IsActive = 1
                UNION
                SELECT
                        a.AccID,
                        a.UName
                FROM
                        TB_Users AS a
                    INNER JOIN
                      AccountsTb AS b
                        ON a.AccID = b.AccID
                WHERE
                        a.BranchID = p_BRnchID
                        AND p_UESERTYPE = 1
                        AND a.IsActive = 1;

              END IF;
            IF p_Type <> 0
               THEN

                SELECT
                        A.AccID,
                        A.AccName
                FROM
                        AccountsTb AS A
                    LEFT JOIN
                      CoBranch b
                        ON a.AccID = b.CurrentAccID
                WHERE
                        A.AccParent = p_Type
                        AND A.AccActive = 1
                GROUP BY
                        A.AccID,
                        A.AccName,
                        AccParent,
                        BranchType,
                        BranchID
                HAVING
                        (       (       `SafeIDEMP_GetCustAccVal`(A.AccID, p_BRnchID) > 0.000
                                        AND a.AccParent <> 2010201)
                                OR (    a.AccParent LIKE '20103%'
                                        AND A.BranchID = p_BRnchID)
                                OR (    `SafeIDEMP_GetCustAccVal`(A.AccID, p_BRnchID) > 0.000
                                        AND b.BranchType = 3
                                        AND a.AccParent = 2010201)
                                OR (    a.AccParent LIKE '103020%'
                                        AND p_Type LIKE '103020%'
                                        AND A.BranchID = p_BRnchID));


              END IF;
          END IF;
        IF p_TransType = 1
          AND
          p_Typesf <> 2
           THEN
            IF p_Type = 0
               THEN
                SELECT
                        a.AccID,
                        a.AccName

                FROM
                        `AccountsTb` AS a
                WHERE
                        SUBSTRING(CAST(a.AccParent AS CHAR), 0, 7) = p_Type
                        AND a.Accline = 4
                        AND a.CountryID = p_CountryID
                GROUP BY
                        a.AccID,
                        a.AccName
                HAVING
                        `SafeIDEMP_GetCurrCustAccVal`(a.AccID, p_BRnchID) > 0.000;
              END IF;
          END IF;
        IF p_TransType = 0
          AND
          p_Typesf = 2
           THEN
            IF p_Type <> 0
               THEN
                SELECT
                        a.AccID,
                        a.AccName

                FROM
                        `AccountsTb` AS a
                WHERE
                        SUBSTRING(CAST(a.AccParent AS CHAR), 0, 6) = p_Type
                        AND a.Accline = 4
                        AND a.BranchID = p_BRnchID
                GROUP BY
                        A.AccID,
                        A.AccName
                HAVING
                        `SafeIDEMP_GetCurrAccVal`(a.AccID, p_BRnchID) > 0.000;
              END IF;
          END IF;
      END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyMainTb_CurADDPrice`;
DELIMITER //
CREATE PROCEDURE `CurrencyMainTb_CurADDPrice`()
BEGIN
START TRANSACTION;

    SELECT a.ID, CuName
    FROM   CurrencyMainTb as a
	where
	a.IsDefault<>1
	and
	not exists (select * from CurrencyPriceDetailsTb as b where a.id=b.CurrencyIDTo);
    COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyMainTb_FCurrGV`;
DELIMITER //
CREATE PROCEDURE `CurrencyMainTb_FCurrGV`()
BEGIN
START TRANSACTION;

	SELECT
			ID AS CurrID,
			CuName AS CurrencyName
	FROM
			CurrencyMainTb;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyMainTb_Get_Defult_BasedOnCountry`;
DELIMITER //
CREATE PROCEDURE `CurrencyMainTb_Get_Defult_BasedOnCountry`(IN `p_CountryID` INT)
BEGIN
START TRANSACTION;

	SELECT
			a.ID,
			a.CuName
	FROM
			CurrencyMainTb as a
      INNER JOIN
      CountiresTb  b
      ON a.ID = b.DefualtCurrency
WHERE
b.ID=p_CountryID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyMainTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrencyMainTb_Insert`(IN `p_ID` INT, IN `p_CuName` LONGTEXT, IN `p_IBAN` INT, IN `p_CurCode` VARCHAR(50), IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_IsDefault` TINYINT(1))
BEGIN
DECLARE v_AccCode BIGINT;
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_EMFtherPRint BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_FathersRevenueAccount BIGINT;
DECLARE v_FathersLossAccount BIGINT;
DECLARE v_AccName INT;
DECLARE v_ChekCurr INT;
DECLARE v_BRNAME LONGTEXT;
DECLARE v_MainAccName LONGTEXT;
DECLARE v_IDParent BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;



      START TRANSACTION;

      SELECT CB.IsDefault INTO p_IsDefault FROM
              CurrencyMainTb AS CB
      WHERE
              CB.CuName = p_CuName;
      SELECT CB.BName INTO v_BRNAME FROM
              CoBranch AS CB;
SET v_AccCode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
      IF p_IsUpdate = 0
         THEN


          IF p_IsDefault = 1
             THEN
SET v_AccName = 'خزينة العملة الافتراضية';
              SELECT COUNT(*) INTO v_ChekCurr FROM
                      AccountsTb AS a
              WHERE
                      a.AccName = v_AccName;

              IF v_ChekCurr = 0
                 THEN
SET v_MainAccName = 'الأصول المتداولة';
                  SELECT AccCode INTO v_IDParent FROM
                          AccountsTb AS a
                  WHERE
                          a.AccName = v_MainAccName;
                  SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                          AccountsTb AS a
                  WHERE
                          AccParent = v_IDParent;

                  IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                    END IF;
SET v_AccName = 'خزينة العملة الافتراضية';
                  INSERT INTO AccountsTb
                        (

                          AccCode,
                          AccName,
                          AccType,
                          Accline,
                          AccParent,
                          AccDmType,
                          AccFinal,
                          AccMaxLimit,
                          AccMaxDuration,
                          BranchID,
                          AccActive,
                          IDcode
                        )
                  VALUES
                          (

                            v_AccCode,
                            v_AccName,
                            1,
                            2,
                            v_IDParent,
                            0,
                            1,
                            0,
                            0,
                            0,
                            1,
                            v_IDcode
                          );
                END IF;
SET v_AccName = CONCAT('خزينة', ' ', p_CuName);
              SELECT COUNT(*) INTO v_ChekCurr FROM
                      AccountsTb AS a
              WHERE
                      a.AccName = v_AccName;

              IF v_ChekCurr = 0
                 THEN
SET v_MainAccName = 'خزينة العملة الافتراضية';
                  SELECT AccCode INTO v_IDParent FROM
                          AccountsTb AS a
                  WHERE
                          a.AccName = v_MainAccName;
                  SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                          AccountsTb AS a
                  WHERE
                          AccParent = v_IDParent;

                  IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                    END IF;
SET v_AccName = CONCAT('خزينة', ' ', p_CuName);
                  INSERT INTO AccountsTb
                        (

                          AccCode,
                          AccName,
                          AccType,
                          Accline,
                          AccParent,
                          AccDmType,
                          AccFinal,
                          AccMaxLimit,
                          AccMaxDuration,
                          BranchID,
                          AccActive,
                          IDcode
                        )
                  VALUES
                          (

                            v_AccCode,
                            v_AccName,
                            0,
                            3,
                            v_IDParent,
                            0,
                            1,
                            0,
                            0,
                            0,
                            1,
                            v_IDcode
                          );
                END IF;

            END IF;





          SELECT COUNT(*) INTO v_AccName FROM
                  AccountsTb AS a
              LEFT OUTER JOIN
                CurrencyMainTb AS b
                  ON RIGHT(a.AccName, 5) = RIGHT(b.CuName, 5)
          WHERE
                  a.AccName = CONCAT('خزينة', SPACE(1), p_CuName)
                  AND b.IsDefault = 0;

          IF v_AccName = 0
             THEN
SET v_AccCode = CAST(CONCAT(CAST(10102 AS CHAR), '0', CAST(`AccountTb_GetIDCode`(10102, 0) AS CHAR)) AS SIGNED);
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `AccCat`,
                      `IDcode`
                    )
              VALUES
                      (
                        v_AccCode, CONCAT('خزينة', SPACE(1), p_CuName), 0, 3, 10102, 0, 1, '', '', '', '', '', 0, 0, 0, 1, NOW(), 1, 4, `AccountTb_GetIDCode`(10102, 0)
                      );
            END IF;




          SELECT COUNT(AT.AccName) INTO v_AccName FROM
                  AccountsTb AS AT
              CROSS JOIN
                CoBranch AS CB
          WHERE
                  AT.AccName = CONCAT('خزينة', SPACE(1), p_CuName, SPACE(1), CB.BName);

          IF v_AccName = 0
             THEN
SET v_FatherPerintACC = v_AccCode;
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `IDcode`
                    )
                  SELECT
                          CAST(CONCAT(CAST(v_FatherPerintACC AS CHAR), '0', CAST(ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS CHAR)) AS SIGNED),
                          CONCAT('خزينة', SPACE(1), p_CuName, SPACE(1), a.BName),
                          1,
                          4,
                          v_FatherPerintACC,
                          0,
                          1,
                          a.Mobile1,
                          a.Mobile2,
                          '',
                          a.BAddress,
                          a.Notes,
                          0,
                          0,
                          a.ID,
                          1,
                          NOW(),
                          1,
                          ROW_NUMBER() OVER (ORDER BY a.ID ASC)
                  FROM
                          CoBranch AS a
                  WHERE
                          (       a.BranchType = 1
                                  OR a.BranchType = 2)
                          AND a.IsActive = 1;
            END IF;



          SELECT COUNT(a.AccName) INTO v_AccName FROM
                  AccountsTb AS a
              INNER JOIN
                CurrencyMainTb AS b
                  ON RIGHT(a.AccName, 5) = RIGHT(p_CuName, 5)
          WHERE
                  a.AccName = CONCAT('ودائع', SPACE(1), p_CuName);

          IF v_AccName = 0
             THEN
SET v_AccCode = CAST(CONCAT(CAST(10103 AS CHAR), '0', CAST(`AccountTb_GetIDCode`(10103, 0) AS CHAR)) AS SIGNED);
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `AccCat`,
                      `IDcode`
                    )
              VALUES
                      (
                        v_AccCode, CONCAT('ودائع', SPACE(1), p_CuName), 0, 3, 10103, 0, 1, '', '', '', '', '', 0, 0, 0, 1, NOW(), 1, 4, `AccountTb_GetIDCode`(10103, 0)
                      );
            END IF;


          SELECT COUNT(AT.AccName) INTO v_AccName FROM
                  AccountsTb AS AT
              CROSS JOIN
                CoBranch AS CB
              CROSS JOIN
                CurrencyMainTb AS CMT
          WHERE
                  AT.AccName = CONCAT('ودائع', SPACE(1), p_CuName, SPACE(1), CB.BName)
                  AND CMT.IsDefault = 0
                  AND CMT.IsActive = 1
                  AND CB.IsActive = 1;

          IF v_AccName = 0
             THEN
SET v_EMFtherPRint = v_AccCode;
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `IDcode`
                    )
                  SELECT
                          CAST(CONCAT(CAST(v_EMFtherPRint AS CHAR), '0', CAST(ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS CHAR)) AS SIGNED),
                          CONCAT('ودائع', SPACE(1), p_CuName, SPACE(1), a.BName),
                          1,
                          4,
                          v_EMFtherPRint,
                          0,
                          1,
                          a.Mobile1,
                          a.Mobile2,
                          '',
                          a.BAddress,
                          a.Notes,
                          0,
                          0,
                          a.ID,
                          1,
                          NOW(),
                          1,
                          ROW_NUMBER() OVER (ORDER BY a.ID ASC)
                  FROM
                          CoBranch AS a
                  WHERE
                          (       a.BranchType = 1
                                  OR a.BranchType = 2)
                          AND a.IsActive = 1;
            END IF;



          SELECT COUNT(a.AccName) INTO v_AccName FROM
                  AccountsTb AS a
              INNER JOIN
                CurrencyMainTb AS b
                  ON RIGHT(a.AccName, 0) = RIGHT(b.CuName, 0)
          WHERE
                  a.AccName = CONCAT('مستحقات ودائع', SPACE(1), p_CuName)
                  AND b.IsDefault = 0
                  AND b.IsActive = 1;

          IF v_AccName = 0
             THEN
SET v_AccCode = CAST(CONCAT(CAST(20109 AS CHAR), '0', CAST(`AccountTb_GetIDCode`(20109, 0) AS CHAR)) AS SIGNED);
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `AccCat`,
                      `IDcode`
                    )
              VALUES
                      (
                        v_AccCode, CONCAT('مستحقات ودائع', SPACE(1), p_CuName), 0, 3, 20109, 0, 1, '', '', '', '', '', 0, 0, 0, 1, NOW(), 1, 4, `AccountTb_GetIDCode`(20109, 0)
                      );
            END IF;

          SELECT COUNT(AT.AccName) INTO v_AccName FROM
                  AccountsTb AS AT
              CROSS JOIN
                CoBranch AS CB
              CROSS JOIN
                CurrencyMainTb AS CMT
          WHERE
                  AT.AccName = CONCAT('مستحقات ودائع', SPACE(1), p_CuName, SPACE(1), CB.BName)
                  AND CMT.IsActive = 1
                  AND CB.IsActive = 1
                  AND CMT.IsDefault = 0;

          IF v_AccName = 0
             THEN
SET v_ACCFPrintCridet = v_AccCode;
              INSERT INTO `AccountsTb`
                    (
                      `AccCode`,
                      `AccName`,
                      `AccType`,
                      `Accline`,
                      `AccParent`,
                      `AccDmType`,
                      `AccFinal`,
                      `AccPhone`,
                      `AccMobile`,
                      `AccEmail`,
                      `AccAddress`,
                      `AccNotes`,
                      `AccMaxLimit`,
                      `AccMaxDuration`,
                      `BranchID`,
                      `AddUser`,
                      `AddDate`,
                      `AccActive`,
                      `IDcode`
                    )
                  SELECT
                          CAST(CONCAT(CAST(v_ACCFPrintCridet AS CHAR), '0', CAST(ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS CHAR)) AS SIGNED),
                          CONCAT('مستحقات ودائع', SPACE(1), p_CuName, SPACE(1), a.BName),
                          1,
                          4,
                          v_ACCFPrintCridet,
                          0,
                          1,
                          a.Mobile1,
                          a.Mobile2,
                          '',
                          a.BAddress,
                          a.Notes,
                          0,
                          0,
                          a.ID,
                          1,
                          NOW(),
                          1,
                          ROW_NUMBER() OVER (ORDER BY a.ID ASC)
                  FROM
                          CoBranch AS a
                  WHERE
                          (       a.BranchType = 1
                                  OR a.BranchType = 2)
                          AND a.IsActive = 1;
            END IF;





          INSERT INTO CurrencyMainTb
                (
                  CuName,
                  IBAN,
                  CurCode,
                  IsActive,
                  FatherPerintACC,
                  EMFtherPRint,
                  ACCFPrintCridet,
                  FathersRevenueAccount,
                  FathersLossAccount,
                  IsDefault
                )
              SELECT
                      p_CuName,
                      p_IBAN,
                      p_CurCode,
                      p_IsActive,
                      v_FatherPerintACC,
                      v_EMFtherPRint,
                      v_ACCFPrintCridet,
                      v_FathersRevenueAccount,
                      v_FathersLossAccount,
                      p_IsDefault;

        END IF;

      IF p_IsUpdate = 1
         THEN
          UPDATE
                  CurrencyMainTb
          SET
                  IBAN = p_IBAN, CurCode = p_CurCode, IsActive = p_IsActive
          WHERE
            ID = p_ID;
          UPDATE
                  CurrencyTb
          SET
                  CurrencyTb.CurrencyName = p_CuName
          WHERE
            CurrencyTb.CurrID = p_ID;

        END IF;

      COMMIT;

  END //
DELIMITER ;

