DROP PROCEDURE IF EXISTS `CurrencyMainTb_LOADTOLKP_2026`;
DELIMITER //
CREATE PROCEDURE `CurrencyMainTb_LOADTOLKP_2026`(IN `p_Action` INT, IN `p_CurrID` INT, IN `p_CountryID` INT, IN `p_TypeID` INT, IN `p_BuyType` BIGINT)
BEGIN
DECLARE v_AccParent BIGINT;
START TRANSACTION;

IF p_Action=0
 THEN
		SELECT
			ID,
			CuName
	FROM
			CurrencyMainTb
	WHERE
			IsDefault <> 1
      AND IsActive=1;
END IF;

IF p_Action=1
 THEN


SELECT IFNULL(at.AccCode,0) INTO v_AccParent FROM AccountsTb at WHERE at.AccCode=p_BuyType AND at.AccParent=10105;

SELECT 			c.ID as ID ,
			CuName,
      b.BuyPrice,
      b.SalePrice,
      b.CurrencyPower
      FROM
NewCurrencyPricesOwnTb a
INNER JOIN
NewCurrencyPriceOwnDetailsTb b
ON a.ID = b.CPID
INNER JOIN
CurrencyMainTb c
ON a.CurrencyIDFrom=c.ID
WHERE a.PriceType=p_TypeID
AND a.CountryID=p_CountryID
AND ((v_AccParent IS NULL AND a.BankID=0) OR a.BankID = p_BuyType)
AND b.CurrencyIDTo=p_CurrID;


      END IF;
	COMMIT;
END //
DELIMITER ;

