DROP PROCEDURE IF EXISTS `CurrencymovementEMPSAFE_FILLGRid`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementEMPSAFE_FILLGRid`(IN `p_TYPE` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT, IN `p_UName` INT)
BEGIN
IF p_TYPE = 0
		 THEN
			SELECT
					a.ID,
					`ISID`,
					b.CurCode								 AS ACCFRom,
					c.CuName								 AS ACCCRint0,
					FORMAT(a.`CRedetTO`, 3)		 AS CRedetTO,
					FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END										 AS CRedetDL,
					FORMAT(a.`ACC_DEPET_DL`, 3)	 AS ACC_DEPET_DL,
					FORMAT(a.ACC_DEPET_TO, 3)	 AS ACC_DEPET_TO,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								CRedetDL 							ELSE 							NetSale + ACC_DEPET_DL 					END										 AS Revenue,
					UName,
					`Inseart_Date`,
					a.`IsActive`,
					FORMAT(a.NetSale, 3)		 AS NetSale,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END										 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END										 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							IFNULL(salesPurchaseprice, 0.000) 					END										 AS salesPurchaseprice,
				Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END	END																		 AS TYPEFROM
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`IsActive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (   `Typeofsalebuyorsell` = 0
							OR `Typeofsalebuyorsell` = 3)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;

		END IF;
	IF p_TYPE = 1
		 THEN
			SELECT
					a.ID,
					`ISID`,
					b.CurCode								 AS ACCFRom,
					c.CuName								 AS ACCCRint0,
					FORMAT(a.`CRedetTO`, 3)		 AS CRedetTO,
					FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END										 AS CRedetDL,
					FORMAT(a.`ACC_DEPET_DL`, 3)	 AS ACC_DEPET_DL,
					FORMAT(a.ACC_DEPET_TO, 3)	 AS ACC_DEPET_TO,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								CRedetDL 							ELSE 							NetSale + ACC_DEPET_DL 					END										 AS Revenue,
					UName,
					`Inseart_Date`,
					a.`IsActive`,
					FORMAT(a.NetSale, 3)		 AS NetSale,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							ELSE 							'0.000' 					END										 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END										 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell <> 2 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END										 AS salesPurchaseprice,
					Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END	END																		 AS TYPEFROM
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`IsActive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (   `Typeofsalebuyorsell` = 1
							OR `Typeofsalebuyorsell` = 2)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;

		END IF;
	IF p_TYPE = 2
		 THEN
			SELECT
					a.ID,
					`ISID`,
					b.CurCode								 AS ACCFRom,
					c.CuName								 AS ACCCRint0,
					FORMAT(a.`CRedetTO`, 3)		 AS CRedetTO,
					FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END										 AS CRedetDL,
					FORMAT(a.`ACC_DEPET_DL`, 3)	 AS ACC_DEPET_DL,
					FORMAT(a.ACC_DEPET_TO, 3)	 AS ACC_DEPET_TO,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								'0.000' 							ELSE 							NetSale + ACC_DEPET_DL 					END										 AS Revenue,
					UName,
					`Inseart_Date`,
					a.`IsActive`,
					FORMAT(a.NetSale, 3)		 AS NetSale,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END										 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END										 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell <> 2 								AND a.Typeofsalebuyorsell <> 3 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END										 AS salesPurchaseprice,
					Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END	END																		 AS TYPEFROM
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`IsActive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;

		END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencymovementPruse_FILLGRid`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementPruse_FILLGRid`(IN `p_TYPE` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT)
BEGIN
IF p_TYPE <> 4
		 THEN
			SELECT
					a.ID,
					`ISID`,
					b.CurCode								 AS ACCFRom,
					c.CuName								 AS ACCCRint0,
					FORMAT(a.`CRedetTO`, 3)		 AS CRedetTO,
					FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END										 AS CRedetDL,
					FORMAT(a.`ACC_DEPET_DL`, 3)	 AS ACC_DEPET_DL,
					FORMAT(a.ACC_DEPET_TO, 3)	 AS ACC_DEPET_TO,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								CRedetDL 							ELSE 							NetSale + ACC_DEPET_DL 					END										 AS Revenue,
					UName,
					`Inseart_Date`,
					a.`IsActive`,
					FORMAT(a.NetSale, 3)		 AS NetSale,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							ELSE 							'0.000' 					END										 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END										 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							IFNULL(salesPurchaseprice, 0.000) 					END										 AS salesPurchaseprice,
					CASE 							WHEN `TYPEFROM` = 0 								AND a.Typeofsalebuyorsell = 0 								THEN 								'شراء نقدي' 							WHEN `TYPEFROM` = 0 								AND a.Typeofsalebuyorsell = 1 								THEN 								'بيع نقدي' 							WHEN `TYPEFROM` = 0 								AND a.Typeofsalebuyorsell = 2 								THEN 								'إسترجاع شراء نقدي' 							WHEN `TYPEFROM` = 0 								AND a.Typeofsalebuyorsell = 3 								THEN 								'إسترجاع بيع نقدي' 							WHEN `TYPEFROM` = 1 								AND a.Typeofsalebuyorsell = 0 								THEN 								'شراء عالمصرف' 							WHEN `TYPEFROM` = 1 								AND a.Typeofsalebuyorsell = 1 								THEN 								'بيع عالمصرف' 							WHEN `TYPEFROM` = 1 								AND a.Typeofsalebuyorsell = 2 								THEN 								'إسترجاع شراء عالمصرف' 							WHEN `TYPEFROM` = 1 								AND a.Typeofsalebuyorsell = 3 								THEN 								'إسترجاع بيع عالمصرف'  					END										 AS TYPEFROM
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`IsActive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (   `Typeofsalebuyorsell` = p_TYPE
							OR p_TYPE = 5)
			ORDER BY
					a.ID ASC;

		END IF;

	IF p_TYPE = 4
		 THEN
			SELECT
					*
			FROM
					(   SELECT
								a.ID,
								`ISID`,
								b.CurCode AS ACCFRom,
								c.CuName AS ACCCRint0,
								FORMAT(a.`CRedetTO`, 3) AS CRedetTO,
								FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 3 											THEN 											FORMAT(CRedetTO * salesPurchaseprice, 3) 										ELSE 										FORMAT(a.`CRedetDL`, 3) 								END AS CRedetDL,
								FORMAT(a.`ACC_DEPET_DL`, 3) AS ACC_DEPET_DL,
								FORMAT(a.ACC_DEPET_TO, 3) AS ACC_DEPET_TO,
								CASE 										WHEN a.Typeofsalebuyorsell = 3 											THEN 											CRedetDL 										ELSE 										NetSale + ACC_DEPET_DL 								END AS Revenue,
								UName,
								`Inseart_Date`,
								a.`IsActive`,
								FORMAT(a.NetSale, 3) AS NetSale,
								CASE 										WHEN a.Typeofsalebuyorsell = 0 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										WHEN a.Typeofsalebuyorsell = 2 											THEN 											FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 										ELSE 										'0.000' 								END AS buyprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 1 											OR a.Typeofsalebuyorsell = 3 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										ELSE 										'0.000' 								END AS saleprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 2 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										ELSE 										IFNULL(salesPurchaseprice, 0.000) 								END AS salesPurchaseprice,
								CASE 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 0 											THEN 											'شراء نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 1 											THEN 											'بيع نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 2 											THEN 											'إسترجاع شراء نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 3 											THEN 											'إسترجاع بيع نقدي'  										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 0 											THEN 											'شراء عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 1 											THEN 											'بيع عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 2 											THEN 											'إسترجاع شراء عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 3 											THEN 											'إسترجاع بيع عالمصرف' 								END AS TYPEFROM
						FROM
								ExSyAccountsCurrency_CurrencymovementPruse AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.`ACCFRom` = b.ID
							INNER JOIN
								CurrencyMainTb AS c
									ON a.`ACCCRint0` = c.ID
							INNER JOIN
								TB_Users AS d
									ON a.UESER_INSERt = d.USID
							INNER JOIN
								`CurrencyPriceDetailsTb` AS e
									ON a.ACCFRom = e.CurrencyIDTo
						WHERE
								a.`IsActive` = 1
								AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
								AND (`Typeofsalebuyorsell` = 2)
						UNION
						SELECT
								a.ID,
								`ISID`,
								b.CurCode AS ACCFRom,
								c.CuName AS ACCCRint0,
								FORMAT(a.`CRedetTO`, 3) AS CRedetTO,
								FORMAT(a.`Purchaseprice`, 3) AS Purchaseprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 3 											THEN 											FORMAT(CRedetTO * salesPurchaseprice, 3) 										ELSE 										FORMAT(a.`CRedetDL`, 3) 								END AS CRedetDL,
								FORMAT(a.`ACC_DEPET_DL`, 3) AS ACC_DEPET_DL,
								FORMAT(a.ACC_DEPET_TO, 3) AS ACC_DEPET_TO,
								CASE 										WHEN a.Typeofsalebuyorsell = 3 											THEN 											CRedetDL 										ELSE 										NetSale + ACC_DEPET_DL 								END AS Revenue,
								UName,
								`Inseart_Date`,
								a.`IsActive`,
								FORMAT(a.NetSale, 3) AS NetSale,
								CASE 										WHEN a.Typeofsalebuyorsell = 0 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										WHEN a.Typeofsalebuyorsell = 2 											THEN 											FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 										ELSE 										'0.000' 								END AS buyprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 1 											OR a.Typeofsalebuyorsell = 3 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										ELSE 										'0.000' 								END AS saleprice,
								CASE 										WHEN a.Typeofsalebuyorsell = 2 											THEN 											FORMAT(a.`Purchaseprice`, 3) 										ELSE 										IFNULL(salesPurchaseprice, 0.000) 								END AS salesPurchaseprice,
								CASE 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 0 											THEN 											'شراء نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 1 											THEN 											'بيع نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 2 											THEN 											'إسترجاع شراء نقدي' 										WHEN `TYPEFROM` = 0 											AND a.Typeofsalebuyorsell = 3 											THEN 											'إسترجاع بيع نقدي'  										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 0 											THEN 											'شراء عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 1 											THEN 											'بيع عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 2 											THEN 											'إسترجاع شراء عالمصرف' 										WHEN `TYPEFROM` = 1 											AND a.Typeofsalebuyorsell = 3 											THEN 											'إسترجاع بيع عالمصرف' 								END AS TYPEFROM
						FROM
								ExSyAccountsCurrency_CurrencymovementPruse AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.`ACCFRom` = b.ID
							INNER JOIN
								CurrencyMainTb AS c
									ON a.`ACCCRint0` = c.ID
							INNER JOIN
								TB_Users AS d
									ON a.UESER_INSERt = d.USID
							INNER JOIN
								`CurrencyPriceDetailsTb` AS e
									ON a.ACCFRom = e.CurrencyIDTo
						WHERE
								a.`IsActive` = 1
								AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
								AND (`Typeofsalebuyorsell` = 3)) AS x

			ORDER BY
					x.ID ASC;

		END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyMovements_fillCrid`;
DELIMITER //
CREATE PROCEDURE `CurrencyMovements_fillCrid`(IN `p_TYPE` INT, IN `p_ISID` BIGINT, IN `p_DT1` DATE, IN `p_DT2` DATE, IN `p_Ueserinsert` BIGINT, IN `p_TypeMovet` BIGINT)
BEGIN
IF p_TYPE = 1
		 THEN


			SELECT
					CASE 							WHEN a.`TYPE` = 1 								THEN 								'عالمصرف' 							ELSE 							'نقدي' 					END								   AS 'TYPE',
					d.BankName						   AS ISID,
					b.CuName						   AS CurrencyFrom,
					c.CuName						   AS CurrencyTo,
					a.BuyPrice,
					SalePrice,
					RetBuyPrice,
					retSalePrice,
					e.UName							   AS Ueserinsert,
					InsertDate,
					CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
					f.Movementsnmae					   AS TypeMovet
			FROM
					`CurrencyMovements2024`.CurrencyMovementsTable AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyTo = c.id
				INNER JOIN
					BanksTb AS d
						ON a.ISID = d.id
				INNER JOIN
					TB_Users AS e
						ON a.Ueserinsert = e.USID
				INNER JOIN
					CurrencyMovements2024.MovementsnmaeTypeTB AS f
						ON a.TypeMovet = f.MovementstYPE

			WHERE
					(		a.`TYPE` = p_TYPE
							OR p_TYPE = 2)
					AND (   a.ISID = p_ISID
							OR p_ISID = 0)
					AND (   a.Ueserinsert = p_Ueserinsert
							OR p_Ueserinsert = 0)
					AND a.InsertDate BETWEEN p_DT1 AND p_DT2
					AND (   a.TypeMovet = p_TypeMovet
							OR p_TypeMovet = 3)
			ORDER BY
					a.InsertDate,
					a.DateForTime DESC;

		END IF;
	IF p_TYPE = 0
		 THEN
			SELECT
					CASE 							WHEN a.`TYPE` = 1 								THEN 								'عالمصرف' 							ELSE 							'نقدي' 					END								   AS 'TYPE',
					'بيع نقدي'						   AS ISID,
					b.CuName						   AS CurrencyFrom,
					c.CuName						   AS CurrencyTo,
					a.BuyPrice,
					SalePrice,
					RetBuyPrice,
					retSalePrice,
					e.UName							   AS Ueserinsert,
					InsertDate,
					CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
					f.Movementsnmae					   AS TypeMovet
			FROM
					`CurrencyMovements2024`.CurrencyMovementsTable AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyTo = c.id
				INNER JOIN
					TB_Users AS e
						ON a.Ueserinsert = e.USID
				INNER JOIN
					CurrencyMovements2024.MovementsnmaeTypeTB AS f
						ON a.TypeMovet = f.MovementstYPE

			WHERE
					(		a.`TYPE` = p_TYPE
							OR p_TYPE = 2)
					AND (   a.ISID = p_ISID
							OR p_ISID = 0)
					AND (   a.Ueserinsert = p_Ueserinsert
							OR p_Ueserinsert = 0)
					AND a.InsertDate BETWEEN p_DT1 AND p_DT2
					AND (   a.TypeMovet = p_TypeMovet
							OR p_TypeMovet = 3)
			ORDER BY
					a.InsertDate,
					a.DateForTime DESC;
		END IF;


	IF p_TYPE = 2
		 THEN
			SELECT
					*
			FROM
					(   SELECT
								CASE 										WHEN a.`TYPE` = 1 											THEN 											'عالمصرف' 										ELSE 										'نقدي' 								END AS 'TYPE',
								d.BankName AS ISID,
								b.CuName AS CurrencyFrom,
								c.CuName AS CurrencyTo,
								a.BuyPrice,
								SalePrice,
								RetBuyPrice,
								retSalePrice,
								e.UName AS Ueserinsert,
								InsertDate,
								CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
								f.Movementsnmae AS TypeMovet
						FROM
								`CurrencyMovements2024`.CurrencyMovementsTable AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.CurrencyFrom = b.id
							INNER JOIN
								CurrencyMainTb AS c
									ON a.CurrencyTo = c.id
							INNER JOIN
								BanksTb AS d
									ON a.ISID = d.id
							INNER JOIN
								TB_Users AS e
									ON a.Ueserinsert = e.USID
							INNER JOIN
								CurrencyMovements2024.MovementsnmaeTypeTB AS f
									ON a.TypeMovet = f.MovementstYPE

						WHERE
								(a.`TYPE` = 1)
								AND (   a.ISID = p_ISID
										OR p_ISID = 0)
								AND (   a.Ueserinsert = p_Ueserinsert
										OR p_Ueserinsert = 0)
								AND a.InsertDate BETWEEN p_DT1 AND p_DT2
								AND (   a.TypeMovet = p_TypeMovet
										OR p_TypeMovet = 3)
						UNION
						SELECT
								CASE 										WHEN a.`TYPE` = 1 											THEN 											'عالمصرف' 										ELSE 										'نقدي' 								END AS 'TYPE',
								'بيع نقدي' AS ISID,
								b.CuName AS CurrencyFrom,
								c.CuName AS CurrencyTo,
								a.BuyPrice,
								SalePrice,
								RetBuyPrice,
								retSalePrice,
								e.UName AS Ueserinsert,
								InsertDate,
								CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
								f.Movementsnmae AS TypeMovet
						FROM
								`CurrencyMovements2024`.CurrencyMovementsTable AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.CurrencyFrom = b.id
							INNER JOIN
								CurrencyMainTb AS c
									ON a.CurrencyTo = c.id
							INNER JOIN
								TB_Users AS e
									ON a.Ueserinsert = e.USID
							INNER JOIN
								CurrencyMovements2024.MovementsnmaeTypeTB AS f
									ON a.TypeMovet = f.MovementstYPE

						WHERE
								(a.`TYPE` = 0)
								AND (   a.ISID = p_ISID
										OR p_ISID = 0)
								AND (   a.Ueserinsert = p_Ueserinsert
										OR p_Ueserinsert = 0)
								AND a.InsertDate BETWEEN p_DT1 AND p_DT2
								AND (   a.TypeMovet = p_TypeMovet
										OR p_TypeMovet = 3)) AS x

			ORDER BY
					x.InsertDate,
					x.DateForTime DESC;
		END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Currencyonthebank_forselecPr`;
DELIMITER //
CREATE PROCEDURE `Currencyonthebank_forselecPr`(IN `p_CurrencyIDFrom` INT, IN `p_CurrencyIDTo` INT, IN `p_Type` INT, IN `p_SalePricevalue` DECIMAL(12,3), INOUT `p_ReturnSalePricevalue` LONGTEXT, INOUT `p_MSGsta` INT)
proc: BEGIN
DECLARE v_BuyPrice DECIMAL(12, 3);
DECLARE v_SalePrice DECIMAL(12, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_MSGsta = 0; END;

			START TRANSACTION;


			IF p_Type = 0
				 THEN
					SELECT IFNULL(a.BuyPrice, 0) INTO v_BuyPrice FROM
							CurrencyPriceDetailsTb AS a
					WHERE
							a.CurrencyIDFrom = p_CurrencyIDFrom
							AND a.CurrencyIDTo = p_CurrencyIDTo;

					IF v_BuyPrice > p_SalePricevalue
						 THEN
							SET p_MSGsta = 0;
							SET p_ReturnSalePricevalue = CONCAT('لا يجب ان يكون سعر الشراء علي مصرف اقل من سعر الشراء النقدي', ' ', ', وسعر شراء النقدي هو ', ':', CAST(v_BuyPrice AS CHAR));
							ROLLBACK;
							LEAVE proc;
						END IF;
				END IF;

			IF p_Type = 1
				 THEN
					SELECT IFNULL(a.SalePrice, 0) INTO v_SalePrice FROM
							CurrencyPriceDetailsTb AS a
					WHERE
							a.CurrencyIDFrom = p_CurrencyIDFrom
							AND a.CurrencyIDTo = p_CurrencyIDTo;
					IF v_SalePrice > p_SalePricevalue
						 THEN
							SET p_MSGsta = 0;
							SET p_ReturnSalePricevalue = CONCAT('لا يجب ان يكون سعر البيع علي مصرف اقل من سعر البيع  النقدي', ' ', ', وسعر البيع النقدي هو ', ':', CAST(v_SalePrice AS CHAR));
							SELECT
									p_ReturnSalePricevalue;
							ROLLBACK;
							LEAVE proc;
						END IF;
				END IF;

			SET p_ReturnSalePricevalue = CAST(Currencyonthebank_forselecPruse(p_Type, p_SalePricevalue, p_CurrencyIDFrom, p_CurrencyIDTo) AS CHAR);
			COMMIT;
			SET p_MSGsta = 1;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyPricCatogreUpdate`;
DELIMITER //
CREATE PROCEDURE `CurrencyPricCatogreUpdate`(IN `p_ID` INT, IN `p_TypeID` INT, IN `p_SalePrice` DECIMAL(12,3), IN `p_BuyPrice` DECIMAL(12,3), IN `p_UserID` INT, INOUT `p_TYpes` INT, INOUT `p_crUNSEFROM` INT, IN `p_AccountType` TINYINT UNSIGNED)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;
			START TRANSACTION;

			IF p_TypeID = 0
				 THEN
					UPDATE
							CurrencyPriceDetailsTb
					SET
							`SalePrice` = p_SalePrice,
							`BuyPrice` = p_BuyPrice

					WHERE
						ID = p_ID;
					INSERT INTO CurrencyMovements2024.`CurrencyMovementsTable`
							(
								`TYPE`,
								`ISID`,
								`CurrencyFrom`,
								`CurrencyTo`,
								`BuyPrice`,
								`SalePrice`,
								`RetBuyPrice`,
								`retSalePrice`,
								`Ueserinsert`,
								`InsertDate`,
								`DateForTime`,
								`TypeMovet`,
								`IsActive`,
								`AccountType`
							)

						SELECT
								0,
								0,
								a.CurrencyIDFrom,
								a.CurrencyIDTo,
								p_BuyPrice,
								p_SalePrice,
								0,
								0,
								p_UserID,
								NOW(),
								NOW(),
								1,
								1,
								p_AccountType
						FROM
								CurrencyPriceDetailsTb AS a

						WHERE
								ID = p_ID;

					SET p_TYpes = 1;
					SELECT A.CurrencyIDFrom INTO p_crUNSEFROM FROM
							CurrencyPriceDetailsTb AS A
					WHERE
							ID = p_ID;
				END IF;


			IF p_TypeID = 1
				 THEN
					UPDATE
							CurrencyPriceDetailsBancksTb
					SET
							`SalePrice` = p_SalePrice,
							`BuyPrice` = p_BuyPrice

					WHERE
						ID = p_ID;
					INSERT INTO CurrencyMovements2024.`CurrencyMovementsTable`
							(
								`TYPE`,
								`ISID`,
								`CurrencyFrom`,
								`CurrencyTo`,
								`BuyPrice`,
								`SalePrice`,
								`RetBuyPrice`,
								`retSalePrice`,
								`Ueserinsert`,
								`InsertDate`,
								`DateForTime`,
								`TypeMovet`,
								`IsActive`,
								`AccountType`
							)

						SELECT
								1,
								a.CPID,
								a.CurrencyIDFrom,
								a.CurrencyIDTo,
								p_BuyPrice,
								p_SalePrice,
								0,
								0,
								p_UserID,
								NOW(),
								NOW(),
								1,
								1,
								p_AccountType
						FROM
								CurrencyPriceDetailsBancksTb AS a

						WHERE
								ID = p_ID;

					SET p_TYpes = 2;
					SELECT A.CPID INTO p_crUNSEFROM FROM
							CurrencyPriceDetailsBancksTb AS A
					WHERE
							ID = p_ID;

				END IF;


			COMMIT;


	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencySales_GetSaleFunction`;
DELIMITER //
CREATE PROCEDURE `CurrencySales_GetSaleFunction`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

			START TRANSACTION;

			SELECT b.CurCode INTO v_CurrencyCode FROM
					CurrencyMainTb AS b
			WHERE
					b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
			SELECT a.CurrencyPower INTO v_CurrencyPower FROM
					CurrencyPriceDetailsTb AS a
			WHERE
					a.CurrencyIDFrom = 1
					AND a.CurrencyIDTo = p_CurrencyFrom;
			IF p_ISbaunk = 0
				 THEN
					IF v_CurrencyPower = 1
						 THEN


							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BuyPrice AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.SalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / SalePrice 												END AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;

					IF v_CurrencyPower = 0
						 THEN
							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BuyPrice 														ELSE 														1 / BuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION
										SELECT
												1 / (v_CurrencyBuyPrice * SalePrice) AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					SET p_Purchaseprice = Get_Purchaseprice(p_CurrencyTo, p_CurrencyFrom, p_ISbaunk);
				END IF;
			IF p_ISbaunk = 1
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BankBuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BankBuyPrice AS BankBuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION
										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.BankSalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / BankSalePrice 												END AS BankSalePrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					IF v_CurrencyPower = 0
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BankBuyPrice 														ELSE 														1 / BankBuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION
										SELECT
												1 / (v_CurrencyBuyPrice * BankSalePrice) AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
				END IF;
			SELECT
					p_BPrice11,
					p_Purchaseprice;
			COMMIT;


	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrencyTb_Insert`(IN `p_Code` LONGTEXT, IN `p_CurrencyName` LONGTEXT, IN `p_PartName` LONGTEXT, IN `p_PartValue` INT, IN `p_ExchangeRate` DECIMAL(12,3), IN `p_EqualValue` DECIMAL(12,3), IN `p_IsLocal` TINYINT(1), IN `p_IsActive` TINYINT(1), IN `p_IsDefault` TINYINT(1), IN `p_BranchID` INT)
BEGIN
