											v_acccode,
											v_AccName,
											1,
											4,
											v_IDParent,
											0,
											1,
											0,
											0,
											p_BranchID,
											1,
											v_IDcode
										);
							END IF;
						SELECT AccID INTO v_CurrncyAccID FROM
								AccountsTb
						WHERE
								AccountsTb.AccName = v_AccName;
						UPDATE
								CurrencyTb
						SET
								CurrencyTb.SafeCurID = v_CurrncyAccID
						WHERE
							CurrencyTb.CurrencyName = p_CurrencyName;
					END IF;
			END IF;
		IF p_IsDefault = 0
		 THEN
SET v_AccName = 'خزائن النقد الأجنبي';
				SELECT COUNT(*) INTO v_ChekCurr FROM
						AccountsTb AS a
				WHERE
						a.AccName = v_AccName;
				IF v_ChekCurr = 0
					 THEN
SET v_MainAccName = 'الأصول المتداولة';
						SELECT AccCode INTO v_IDParent FROM
								AccountsTb AS a
						WHERE
								a.AccName = v_MainAccName;
						SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
								AccountsTb AS a
						WHERE
								AccParent = v_IDParent;
						IF v_IDcode IS NULL
							 THEN
SET v_IDcode = 1;
							END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = 'خزائن النقد الأجنبي';
						INSERT INTO AccountsTb
								(

									AccCode,
									AccName,
									AccType,
									Accline,
									AccParent,
									AccDmType,
									AccFinal,
									AccMaxLimit,
									AccMaxDuration,
									BranchID,
									AccActive,
									IDcode
								)
						VALUES
								(

									v_acccode,
									v_AccName,
									1,
									2,
									v_IDParent,
									0,
									1,
									0,
									0,
									0,
									1,
									v_IDcode
								);
					END IF;
					SELECT BName INTO v_BName FROM
						CoBranch AS a
				WHERE
						a.ID = p_BranchID;
				SELECT AT.AccName INTO v_AccName FROM AccountsTb AS AT WHERE AT.AccName= CONCAT('خزينة', ' ', p_CurrencyName) AND AT.AccParent=v_acccode;
				SELECT COUNT(*) INTO v_ChekCurr FROM
						AccountsTb AS a
				WHERE
						a.AccName = v_AccName;
				IF v_ChekCurr = 0
					 THEN
						SELECT BName INTO v_BName FROM
								CoBranch AS a
						WHERE
								a.ID = p_BranchID;
SET v_MainAccName = 'خزائن النقد الأجنبي';
						SELECT AccCode INTO v_IDParent FROM
								AccountsTb AS a
						WHERE
								a.AccName = v_MainAccName;
						SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
								AccountsTb AS a
						WHERE
								AccParent = v_IDParent;
						IF v_IDcode IS NULL
							 THEN
SET v_IDcode = 1;
							END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خزينة', ' ', p_CurrencyName);
						INSERT INTO AccountsTb
								(

									AccCode,
									AccName,
									AccType,
									Accline,
									AccParent,
									AccDmType,
									AccFinal,
									AccMaxLimit,
									AccMaxDuration,
									BranchID,
									AccActive,
									IDcode
								)
						VALUES
								(

									v_acccode,
									v_AccName,
									0,
									3,
									v_IDParent,
									0,
									1,
									0,
									0,
									0,
									1,
									v_IDcode
								);
		END IF;

				SELECT BName INTO v_BName FROM
						CoBranch AS a
				WHERE
						a.ID = p_BranchID;
				SELECT AT.AccName INTO v_AccName FROM AccountsTb AS AT WHERE AT.AccName= CONCAT('خزينة', ' ', p_CurrencyName, SPACE(1), v_BName) AND AT.AccParent=v_acccode;
				SELECT COUNT(*) INTO v_ChekCurr FROM
						AccountsTb AS a
				WHERE
						a.AccName = v_AccName;
				IF v_ChekCurr = 0
					 THEN
						SELECT BName INTO v_BName FROM
								CoBranch AS a
						WHERE
								a.ID = p_BranchID;
SET v_MainAccName = 'خزائن النقد الأجنبي';
						SELECT AccCode INTO v_IDParent FROM
								AccountsTb AS a
						WHERE
								a.AccName = v_MainAccName;
						SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
								AccountsTb AS a
						WHERE
								AccParent = v_IDParent;
						IF v_IDcode IS NULL
							 THEN
SET v_IDcode = 1;
							END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خزينة', ' ', p_CurrencyName, v_BName);
						INSERT INTO AccountsTb
								(

									AccCode,
									AccName,
									AccType,
									Accline,
									AccParent,
									AccDmType,
									AccFinal,
									AccMaxLimit,
									AccMaxDuration,
									BranchID,
									AccActive,
									IDcode
								)
						VALUES
								(

									v_acccode,
									v_AccName,
									0,
									4,
									v_IDParent,
									0,
									1,
									0,
									0,
									p_BranchID,
									1,
									v_IDcode
								);
								END IF;


		END IF;

		INSERT INTO TB_Users
				(

					UName,
					UNameLog,
					UPass,
					IsActive,
					BranchID,
					ProfileID
				)
		VALUES
				(
					p_CurrencyName, p_CurrencyName, 'OmalPass', 1, 1, 1
				);
		SELECT
				ID,
				Code,
				CurrencyName,
				PartName,
				PartValue,
				ExchangeRate,
				EqualValue,
				IsLocal,
				IsActive,
				IsDefault
		FROM
				CurrencyTb
		WHERE
				ID = LAST_INSERT_ID();
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CURRENCYTB_LoadBasedOnAccID`;
DELIMITER //
CREATE PROCEDURE `CURRENCYTB_LoadBasedOnAccID`(IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

	SELECT
			ID,
			CurrencyName
	FROM
			CurrencyTb AS a
		LEFT JOIN
			AccountsTb AS b
				ON a.SafeCurID = b.AccID
	WHERE
			(IsActive = 1)
			AND b.AccID = p_AccID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CURRENCYTB_LoadBasedOnBranch`;
DELIMITER //
CREATE PROCEDURE `CURRENCYTB_LoadBasedOnBranch`(IN `p_BranchID` INT, IN `p_AccID` BIGINT, IN `p_AccountType` INT)
BEGIN


        START TRANSACTION;
        IF p_AccountType = 0
             THEN
                SELECT ID , CurrencyName
                FROM CurrencyTb
                WHERE BranchID = p_BranchID
                      AND
                      CurrencyTb.SafeCurID = p_AccID
                      AND
                      ( IsActive = 1 );
        END IF;
        IF ( p_AccountType = 1
             OR
             p_AccountType = 2
             OR
             p_AccountType = 3
			 OR
             p_AccountType = 4)
             THEN
                SELECT ID , CurrencyName
                FROM CurrencyTb
                WHERE BranchID = p_BranchID
                      AND
                      ( IsActive = 1 );
        END IF;
        COMMIT;
    END //
DELIMITER ;

