DROP PROCEDURE IF EXISTS `CURRENCYTB_UPDATE`;
DELIMITER //
CREATE PROCEDURE `CURRENCYTB_UPDATE`(IN `p_Code` LONGTEXT, IN `p_CurrencyName` LONGTEXT, IN `p_PartName` LONGTEXT, IN `p_PartValue` INT, IN `p_ExchangeRate` DECIMAL(12,3), IN `p_EqualValue` DECIMAL(12,3), IN `p_IsLocal` TINYINT(1), IN `p_IsActive` TINYINT(1), IN `p_IsDefault` TINYINT(1), IN `p_BranchID` INT)
BEGIN
DECLARE v_AccID BIGINT;
DECLARE v_acccode BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_SelectAccName LONGTEXT;
DECLARE v_AccName LONGTEXT;
DECLARE v_BName LONGTEXT;
DECLARE v_MainAccName LONGTEXT;
DECLARE v_ChekCurr INT;


        START TRANSACTION;


        SELECT BName INTO v_BName FROM CoBranch AS a LEFT OUTER JOIN CurrencyTb AS b ON a.ID = B.BranchID
        WHERE b.Code = p_Code;
SET v_AccName = CONCAT('خزينة', ' ', p_CurrencyName, ' ', v_BName);
        SELECT COUNT(*) INTO v_ChekCurr FROM AccountsTb AS a
        WHERE a.AccName = v_AccName;
        IF v_ChekCurr > 0
             THEN
                SELECT AccID INTO v_AccID FROM AccountsTb AS a
                WHERE a.AccName = v_AccName;
                SELECT BName INTO v_BName FROM CoBranch AS a
                WHERE a.ID = p_BranchID;
SET v_MainAccName = CONCAT('الخزينة الرئيسية', ' ', v_BName);
                SELECT acccode INTO v_IDParent FROM AccountsTb AS a
                WHERE a.accname = v_MainAccName;
                SELECT MAX(a.idcode) + 1 INTO v_IDcode FROM AccountsTb AS a
                WHERE accparent = v_IDParent;
                IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خزينة', ' ', p_CurrencyName, ' ', v_BName);
                UPDATE AccountsTb
                       SET AccountsTb.AccCode = v_acccode ,
                AccountsTb.AccName = v_AccName ,
                AccountsTb.AccParent = v_IDParent ,
                AccountsTb.BranchID = p_BranchID ,
                AccountsTb.IDcode = v_IDcode
                WHERE AccID = v_AccID;
        END IF;

        SELECT BName INTO v_BName FROM CoBranch AS a LEFT OUTER JOIN CurrencyTb AS b ON a.ID = B.BranchID
        WHERE b.Code = p_Code;
SET v_AccName = CONCAT('خسائر تغير أسعار', ' ', p_CurrencyName, ' ', v_BName);
        SELECT COUNT(*) INTO v_ChekCurr FROM AccountsTb AS a
        WHERE a.AccName = v_AccName;
        IF v_ChekCurr > 0
             THEN
                SELECT AccID INTO v_AccID FROM AccountsTb AS a
                WHERE a.AccName = v_AccName;
                SELECT BName INTO v_BName FROM CoBranch AS a
                WHERE a.ID = p_BranchID;
SET v_MainAccName = CONCAT('خسائر تغير أسعار', ' ', p_CurrencyName);
                SELECT acccode INTO v_IDParent FROM AccountsTb AS a
                WHERE a.accname = v_MainAccName;
                SELECT MAX(a.idcode) + 1 INTO v_IDcode FROM AccountsTb AS a
                WHERE accparent = v_IDParent;
                IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خسائر تغير أسعار', ' ', p_CurrencyName, ' ', v_BName);
                UPDATE AccountsTb
                       SET AccountsTb.AccCode = v_acccode ,
                AccountsTb.AccName = v_AccName ,
                AccountsTb.AccParent = v_IDParent ,
                AccountsTb.BranchID = p_BranchID ,
                AccountsTb.IDcode = v_IDcode
				WHERE AccID = v_AccID;
        END IF;

        SELECT BName INTO v_BName FROM CoBranch AS a LEFT OUTER JOIN CurrencyTb AS b ON a.ID = B.BranchID
        WHERE b.Code = p_Code;
SET v_AccName = CONCAT('مخصص تغير أسعار', ' ', p_CurrencyName, ' ', v_BName);
        SELECT COUNT(*) INTO v_ChekCurr FROM AccountsTb AS a
        WHERE a.AccName = v_AccName;
        IF v_ChekCurr > 0
             THEN
				SELECT AccID INTO v_AccID FROM AccountsTb AS a
                WHERE a.AccName = v_AccName;
                SELECT BName INTO v_BName FROM CoBranch AS a
                WHERE a.ID = p_BranchID;
SET v_MainAccName = CONCAT('مخصص تغير أسعار', ' ', p_CurrencyName);
                SELECT acccode INTO v_IDParent FROM AccountsTb AS a
                WHERE a.accname = v_MainAccName;
                SELECT MAX(a.idcode) + 1 INTO v_IDcode FROM AccountsTb AS a
                WHERE accparent = v_IDParent;
                IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('مخصص تغير أسعار', ' ', p_CurrencyName, ' ', v_BName);
                UPDATE AccountsTb
                       SET AccountsTb.AccCode = v_acccode ,
                AccountsTb.AccName = v_AccName ,
                AccountsTb.AccParent = v_IDParent ,
                AccountsTb.BranchID = p_BranchID ,
                AccountsTb.IDcode = v_IDcode
				WHERE AccID = v_AccID;
        END IF;

        SELECT BName INTO v_BName FROM CoBranch AS a LEFT OUTER JOIN CurrencyTb AS b ON a.ID = B.BranchID
        WHERE b.Code = p_Code;
SET v_AccName = CONCAT('خسائر بيع', ' ', p_CurrencyName, ' ', v_BName);
        SELECT COUNT(*) INTO v_ChekCurr FROM AccountsTb AS a
        WHERE a.AccName = v_AccName;
        IF v_ChekCurr > 0
             THEN
				SELECT AccID INTO v_AccID FROM AccountsTb AS a
                WHERE a.AccName = v_AccName;
                SELECT BName INTO v_BName FROM CoBranch AS a
                WHERE a.ID = p_BranchID;
SET v_MainAccName = CONCAT('خسائر بيع', ' ', p_CurrencyName);
                SELECT acccode INTO v_IDParent FROM AccountsTb AS a
                WHERE a.accname = v_MainAccName;
                SELECT MAX(a.idcode) + 1 INTO v_IDcode FROM AccountsTb AS a
                WHERE accparent = v_IDParent;
                IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خسائر بيع', ' ', p_CurrencyName, ' ', v_BName);
                UPDATE AccountsTb
                       SET AccountsTb.AccCode = v_acccode ,
                AccountsTb.AccName = v_AccName ,
                AccountsTb.AccParent = v_IDParent ,
                AccountsTb.BranchID = p_BranchID ,
                AccountsTb.IDcode = v_IDcode
				WHERE AccID = v_AccID;
        END IF;

        SELECT BName INTO v_BName FROM CoBranch AS a LEFT OUTER JOIN CurrencyTb AS b ON a.ID = B.BranchID
        WHERE b.Code = p_Code;
SET v_AccName = CONCAT('أرباح بيع', ' ', p_CurrencyName, ' ', v_BName);
        SELECT COUNT(*) INTO v_ChekCurr FROM AccountsTb AS a
        WHERE a.AccName = v_AccName;
        IF v_ChekCurr > 0
             THEN
				SELECT AccID INTO v_AccID FROM AccountsTb AS a
                WHERE a.AccName = v_AccName;
                SELECT BName INTO v_BName FROM CoBranch AS a
                WHERE a.ID = p_BranchID;
SET v_MainAccName = CONCAT('أرباح بيع', ' ', p_CurrencyName);
                SELECT acccode INTO v_IDParent FROM AccountsTb AS a
                WHERE a.accname = v_MainAccName;
                SELECT MAX(a.idcode) + 1 INTO v_IDcode FROM AccountsTb AS a
                WHERE accparent = v_IDParent;
                IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('أرباح بيع', ' ', p_CurrencyName, ' ', v_BName);
                UPDATE AccountsTb
                       SET AccountsTb.AccCode = v_acccode ,
                AccountsTb.AccName = v_AccName ,
                AccountsTb.AccParent = v_IDParent ,
                AccountsTb.BranchID = p_BranchID ,
                AccountsTb.IDcode = v_IDcode
				WHERE AccID = v_AccID;
        END IF;
        UPDATE CurrencyTb
               SET CurrencyName = p_CurrencyName , PartName = p_PartName , PartValue = p_PartValue , ExchangeRate = p_ExchangeRate , EqualValue = p_EqualValue , IsLocal = p_IsLocal , IsActive = p_IsActive , IsDefault = p_IsDefault , BranchID = p_BranchID
        WHERE CurrencyTb.Code = p_Code
              OR
              p_Code IS NULL;
        UPDATE TB_Users
               SET UName = p_CurrencyName , UNameLog = p_CurrencyName , UPass = 'OmalPass' , IsActive = 1 , BranchID = p_BranchID , ProfileID = 1
        WHERE UNameLog = p_CurrencyName;
        COMMIT;
    END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrLimetedTB_Insert`;
DELIMITER //
CREATE PROCEDURE `CurrLimetedTB_Insert`(IN `p_ID` INT, IN `p_MaxVal` DECIMAL(15,3), IN `p_CurID` INT, IN `p_IsEnabled` TINYINT(1), IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;

  IF p_IsUpdate = 0
     THEN
      INSERT INTO CurrLimetedTB
            (
              MaxVal,
              CurID,

              IsEnabled,
              IsActive
            )
          SELECT
                  p_MaxVal,
                  p_CurID,

                  p_IsEnabled,
                  1;
    END IF;
  IF p_IsUpdate = 1
     THEN
      UPDATE
              CurrLimetedTB
      SET
              MaxVal = p_MaxVal, CurID = p_CurID, IsEnabled = p_IsEnabled, IsActive = 1
      WHERE
        ID = p_ID;
    END IF;

  COMMIT;
END //
DELIMITER ;

