DROP PROCEDURE IF EXISTS `CustomerAccountStatement`;
DELIMITER //
CREATE PROCEDURE `CustomerAccountStatement`(IN `p_BranchID` INT, IN `p_CurrencyTo` INT, IN `p_TypeMov` INT, INOUT `p_OverAllDebit` LONGTEXT, INOUT `p_OverAllCredit` LONGTEXT, INOUT `p_OverAllTotal1` LONGTEXT, IN `p_USERID` INT)
BEGIN
DECLARE v_IsDefault INT;
DECLARE v_CanShowHACC BIT;


  SELECT IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.id = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

SELECT t.CanShowHACC INTO v_CanShowHACC FROM TB_Users t WHERE t.USID=p_USERID
 ORDER BY t.USID DESC LIMIT 1;

  IF v_IsDefault = 1
     THEN
      IF p_TypeMov = 0
         THEN

          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
                  AND (a.HiddenAccount=0 OR a.HiddenAccount=v_CanShowHACC)
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID;
        END IF;


      IF p_TypeMov = 1
         THEN

          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;



      IF p_TypeMov = 2
         THEN
          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID


          UNION


          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;
    END IF;

  IF v_IsDefault = 0
     THEN
      IF p_TypeMov = 0
         THEN

          SELECT
                  a.AccID,
                  a.CustName,
                  a.Code,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
                  AND (a.HiddenAccount=0 OR a.HiddenAccount=v_CanShowHACC)
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID,
                  a.Code;


        END IF;
      IF p_TypeMov = 1
         THEN

          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.AccID,
                  a.AccName;
        END IF;




      IF p_TypeMov = 2
         THEN
          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID


          UNION


          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;


    END IF;
SET p_OverAllDebit  = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 0), 3);
SET p_OverAllCredit = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 1), 3);
SET p_OverAllTotal1 = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 2), 3);
  SELECT
          p_OverAllDebit,
          p_OverAllCredit,
          p_OverAllTotal1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_CheckPHoneExist`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_CheckPHoneExist`(IN `p_Phone1` LONGTEXT, IN `p_Phone2` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			Phone1,
			Phone2
	FROM
			CustomersTb
      WHERE
      ((Phone1= p_Phone1 or Phone1=p_Phone2 AND phone1 <>  NULL) OR (Phone2= p_Phone1 OR Phone2=p_Phone2 and phone2 <>  null   ))
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_CheckPHoneExistUpdate`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_CheckPHoneExistUpdate`(IN `p_ID` INT)
BEGIN
START TRANSACTION;

	SELECT
			Phone1,
			Phone2
	FROM
			CustomersTb
      WHERE
           ID <> p_ID AND (phone1<> NULL  OR phone2 <> null)
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_Delete`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_Delete`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;
	DELETE FROM
	CustomersTb
	WHERE
			Code = p_Code;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_Insert`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_Insert`(IN `p_ID` INT, IN `p_InsertDate` DATE, IN `p_Code` LONGTEXT, IN `p_CustName` LONGTEXT, IN `p_Phone1` TEXT, IN `p_Phone2` TEXT, IN `p_CustmAddress` VARCHAR(150), IN `p_BranchID` INT, IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_CanDebit` TINYINT(1), IN `p_ISHidden` TINYINT(1), IN `p_NatNumber` VARCHAR(50), INOUT `p_accidRETURNS` INT, IN `p_Email` LONGTEXT, IN `p_MartialStaus` TINYINT UNSIGNED, IN `p_UserName` LONGTEXT, IN `p_Password` LONGTEXT, IN `p_ParentName` LONGTEXT, IN `p_Nationality` INT, IN `p_BIRTHDATE` DATE, IN `p_EmpReg` VARCHAR(250), IN `p_AccountNo` LONGTEXT, IN `p_BankID` TEXT, IN `p_sand_Group_ID` TINYINT(1), IN `p_Group_ID_fro_watssap` LONGTEXT, IN `p_AccType` TINYINT(1), IN `p_Registry1` LONGTEXT, IN `p_Registry2` LONGTEXT, IN `p_Ownername` LONGTEXT)
proc: BEGIN
DECLARE v_AccountID BIGINT;
DECLARE v_AccParent DECIMAL(18, 0);
DECLARE v_BName LONGTEXT;
DECLARE v_AccID BIGINT;
DECLARE v_OldeCustName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_AccCode BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IsExist INT;
DECLARE v_CheckName LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;



    START TRANSACTION;
    SELECT CB.BName INTO v_BName FROM
            CoBranch AS CB
    WHERE
            CB.ID = p_BranchID;
    SELECT AccCode INTO v_AccParent FROM
            AccountsTb AS AT
    WHERE
            AT.AccName = CONCAT('عملاء', SPACE(1), v_BName);

    IF p_IsUpdate = 0
       THEN
        SELECT COUNT(CT.CustName) INTO v_IsExist FROM
                CustomersTb AS CT
        WHERE
                CT.CustName = p_CustName;

        IF v_IsExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا هذا الاسم موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;



                  INSERT INTO `AccountsTb`
              (
                `AccCode`,
                `AccName`,
                `AccType`,
                `AccParent`,
                `AccDmType`,
                `AccFinal`,
                `AccPhone`,
                `AccMobile`,
                `AccAddress`,
                `AccMaxLimit`,
                `AccMaxDuration`,
                `BranchID`,
                `AccActive`,
                `Accline`,
                `IDcode`,
                sand_Group_ID,
                Group_ID_fro_watssap,
                CanDebit,
                IsHiddenAccount,
                AccNatNumber,
                AccIDNo
              )
            SELECT
                    CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT
                                MAX(xx.IDcode)
                        FROM
                                AccountsTb AS xx
                        WHERE
                                xx.AccParent = v_AccParent), 0) + 1 AS CHAR)) AS AccCode,
                    p_CustName                                       AS AccName,
                    1                                               AS `AccType`,
                    v_AccParent                                      AS `AccParent`,
                    1                                               AS `AccDmType`,
                    1                                               AS `AccFinal`,
                    p_Phone1                                         AS `AccPhone`,
                    p_Phone2                                         AS `AccMobile`,
                    p_CustmAddress                                   AS `AccAddress`,
                    0                                               AS `AccMaxLimit`,
                    0                                               AS `AccMaxDuration`,
                    p_BranchID                                       AS `BranchID`,
                    1                                               AS `AccActive`,
                    4                                               AS `Accline`,
                    IFNULL((SELECT
                                MAX(xx.IDcode)
                        FROM
                                AccountsTb AS xx
                        WHERE
                                xx.AccParent = v_AccParent), 0) + 1  AS IDcode,
                    p_sand_Group_ID,
                    p_Group_ID_fro_watssap,
                    p_CanDebit,
                    p_ISHidden,
                    p_NatNumber,
                    p_Phone2;

      SELECT AccID INTO v_AccountID FROM AccountsTb as a where AccID = LAST_INSERT_ID();


        INSERT INTO CustomersTb
              (
                InsertDate,
                Code,
                CustName,
                Phone1,
                IDNo,
                CustmAddress,
                BranchID,
                IsActive,
                CandDebit,
                HiddenAccount,
                NatNumber,
                Email,
                MartialStaus,
                UserName,
                Password,
                ParentName,
                Nationality,
                BIRTHDATE,
                EmpReg,
                AccNo,

                BankID,
                sand_Group_ID,
                Group_ID_fro_watssap,
                AccType,
                Registry1,
                Registry2,
                Ownername ,
                AccID
              )
        VALUES
                (
                  p_InsertDate, p_Code, p_CustName, p_Phone1, p_Phone2, p_CustmAddress, p_BranchID, 1, p_CanDebit, p_ISHidden,
                  p_NatNumber, p_Email, p_MartialStaus, p_UserName, p_Password, p_ParentName, p_Nationality, p_BIRTHDATE, p_EmpReg,
                  p_AccountNo, p_BankID, p_sand_Group_ID, p_Group_ID_fro_watssap, p_AccType, p_Registry1, p_Registry2, p_Ownername ,v_AccountID
                );



        SET p_accidRETURNS = v_AccountID;
      END IF;

    IF p_IsUpdate = 1
       THEN
        SELECT CT.CustName INTO v_OldeCustName FROM
                CustomersTb AS CT
        WHERE
                Code = p_Code;
        SELECT CT.BranchID INTO v_OldBranchID FROM
                CustomersTb AS CT
        WHERE
                Code = p_Code;
        SELECT CT.AccID INTO v_AccountID FROM
                CustomersTb AS CT
        WHERE
                Code = p_Code;

        SELECT CT.CustName INTO v_CheckName FROM
                CustomersTb AS CT
        WHERE
                Code = p_Code;


        IF v_OldeCustName <> p_CustName
          AND
          v_OldBranchID = p_BranchID

           THEN
                IF EXISTS( SELECT
                1
        FROM
                CustomersTb AS CT
                WHERE
                ID <> p_ID
                AND
                CT.CustName=p_CustName)
                   THEN
                    SET p_MSGSTatues = 0;
                    SET p_MsgBox = 'عذرا هذا الاسم موجود مسبقاً';
                    ROLLBACK;
                    LEAVE proc;
                  END IF;
            UPDATE
                    AccountsTb
            SET
                    AccName = p_CustName, sand_Group_ID = p_sand_Group_ID, Group_ID_fro_watssap = p_Group_ID_fro_watssap, CanDebit=p_CanDebit, IsHiddenAccount=p_ISHidden
            WHERE
              AccID = v_AccountID;

UPDATE CustomersTb
SET CustName=p_CustName
WHERE AccID=v_AccountID;
          END IF;

        IF v_OldeCustName <> p_CustName
          AND
          v_OldBranchID <> p_BranchID
           THEN
            SELECT CB.BName INTO v_BName FROM
                    CoBranch AS CB
            WHERE
                    CB.ID = p_BranchID;
            SELECT AccCode INTO v_AccParent FROM
                    AccountsTb AS AT
            WHERE
                    AT.AccName = CONCAT('عملاء', SPACE(1), v_BName);
SET v_IDcode = IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_AccParent) , 0) + 1;
            UPDATE
                    AccountsTb
            SET
                    AccName = p_CustName, AccCode = CONCAT(CAST(v_AccParent AS CHAR), '0', v_IDcode), IDcode = v_IDcode, BranchID = p_BranchID, CanDebit=p_CanDebit, IsHiddenAccount=p_ISHidden
            WHERE
              AccID = v_AccountID;

UPDATE CustomersTb
SET CustName=p_CustName
WHERE AccID=v_AccountID;
          END IF;

        IF v_OldeCustName = p_CustName
          AND
          v_OldBranchID <> p_BranchID
           THEN
            SELECT CB.BName INTO v_BName FROM
                    CoBranch AS CB
            WHERE
                    CB.ID = p_BranchID;
            SELECT AccCode INTO v_AccParent FROM
                    AccountsTb AS AT
            WHERE
                    AT.AccName = CONCAT('عملاء', SPACE(1), v_BName);
SET v_AccCode = CONCAT(CAST(v_AccParent AS CHAR), '0', CAST(IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_AccParent) , 0) + 1 AS CHAR));
SET v_IDcode = IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_AccParent) , 0) + 1;
            UPDATE
                    AccountsTb
            SET
                    AccCode = CONCAT(CAST(v_AccParent AS CHAR), '0', v_IDcode), IDcode = v_IDcode, BranchID = p_BranchID, AccParent = v_AccParent, AccPhone = p_Phone1, AccMobile = p_Phone2, sand_Group_ID = p_sand_Group_ID, Group_ID_fro_watssap = p_Group_ID_fro_watssap, CanDebit=p_CanDebit, IsHiddenAccount=p_ISHidden
            WHERE
              AccID = v_AccountID;
          END IF;

        UPDATE
                CustomersTb
        SET
                InsertDate = p_InsertDate, Code = p_Code, Phone1 = p_Phone1, Phone2 = p_Phone2, CustmAddress = p_CustmAddress, BranchID = p_BranchID, IsActive = 1, HiddenAccount = p_ISHidden, NatNumber = p_NatNumber, CandDebit = p_CanDebit, Email = p_Email, UserName = p_UserName, PASSWORD = p_Password, ParentName = p_ParentName, Nationality = p_Nationality, BIRTHDATE = p_BIRTHDATE, EmpReg = p_EmpReg, AccNo = p_AccountNo, BankID = p_BankID, Group_ID_fro_watssap = p_Group_ID_fro_watssap, sand_Group_ID = p_sand_Group_ID, AccType = p_AccType, Registry1 = p_Registry1, Registry2 = p_Registry2, Ownername = p_Ownername
        WHERE
          Code = p_Code;

            UPDATE
                    AccountsTb
            SET
                    AccPhone = p_Phone1, sand_Group_ID = p_sand_Group_ID, Group_ID_fro_watssap = p_Group_ID_fro_watssap, CanDebit=p_CanDebit, IsHiddenAccount=p_ISHidden, AccNatNumber=p_NatNumber, AccIDNo=p_Phone2
            WHERE
              AccID = v_AccountID;

        SET p_accidRETURNS = v_AccountID;
      END IF;

    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_LOADTODVG`()
BEGIN
START TRANSACTION;

  SELECT
          Code                  `الرمز`,
          CustName              `الاسم`,
          CONCAT(Phone1, '-', Phone2) `الهاتف`,
          a.AccID,
          NatNumber             AS `الرقم الوطني`,
          CASE                   WHEN b.CanDebit = 1                     THEN                     'نعم'                   WHEN b.CanDebit = 0                     THEN                     'لا'           END                   AS `تصريح بالآجل`,
          CASE                   WHEN b.CanDebit = 1                     AND b.IsLimited = 0                     THEN                     'مفتوح'                   WHEN b.CanDebit = 1                     AND b.IsLimited = 1                     THEN                     CAST(b.LimitedVal AS CHAR)                   WHEN b.CanDebit = 0                     THEN                     'غير مصرح'           END                   AS `سقف السحب`,
          CASE                   WHEN a.HiddenAccount = 1                     THEN                     'مخفي'                   ELSE                   'غير مخفي'           END                   AS `إظهار الحساب`
  FROM
          CustomersTb AS a
      INNER JOIN
        AccountsTb b
          ON a.AccID = b.AccID
  ORDER BY
          Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_LOADTOLKP`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_LOADTOLKP`()
BEGIN
START TRANSACTION;

	SELECT
			ID,
			CustName
	FROM
			CustomersTb
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_LOADTOLKPBasedOnBranchID`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_LOADTOLKPBasedOnBranchID`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			AccID,
			CustName
	FROM
			CustomersTb
	WHERE
			CustomersTb.BranchID = p_BranchID
			AND CustomersTb.IsActive = 1
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_LOADTOLKPBasedOnBranchIDAndCanShowHidden`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_LOADTOLKPBasedOnBranchIDAndCanShowHidden`(IN `p_BranchID` INT, IN `p_USERID` INT)
BEGIN
DECLARE v_CanShowHACC BIT;
START TRANSACTION;

SELECT t.CanShowHACC INTO v_CanShowHACC FROM TB_Users t WHERE t.USID=p_USERID
 ORDER BY t.USID DESC LIMIT 1;

	SELECT
			a.AccID,
			CustName,
      CASE WHEN a.sand_Group_ID=1 THEN a.Group_ID_fro_watssap ELSE a.Phone1 END AS PHONE1
	FROM
			CustomersTb a
      INNER JOIN
      AccountsTb b
      ON a.AccID=b.AccID
	WHERE
			a.BranchID = p_BranchID
			AND a.IsActive = 1
      AND (HiddenAccount=0 OR HiddenAccount=v_CanShowHACC)
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_MaxID`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_MaxID`(IN `p_BranchID` INT)
BEGIN
DECLARE v_Code LONGTEXT;


	START TRANSACTION;
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '4', '-', CAST(CustomersTb_GetMaxCode() AS CHAR));
	SELECT
			v_Code AS Code;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_Select`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_Select`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;
 SELECT
          ct.ID,
          ct.InsertDate,
          ct.IDCode,
          ct.Code,
          ct.CustName,
          ct.Phone1,
          ct.Phone2,
          ct.CustmAddress,
          ct.AccID,
          ct.BranchID,
          ct.IsActive,
          CAST(CandDebit AS SIGNED)  AS CanDebit,
          ct.HiddenAccount,
          ct.NatNumber,
          ct.IsLimited,
          ct.LimitedVal,
          ct.LimitedDate,
          ct.Email,
          IFNULL(ct.MartialStaus,0) MartialStaus,
          ct.UserName,
          ct.Password,
          ct.ParentName,
          IFNULL(ct.Nationality,0) Nationality,
          IFNULL(ct.BIRTHDATE,NOW()) BIRTHDATE,
          ct.EmpReg,
          ct.AccNo,
          ct.IDNo,
          ct.BankID,
                    d.NATNAME,
          ct.AccType,
         IFNULL( ct .Group_ID_fro_watssap,'') as  Group_ID_fro_watssap ,
          IFNULL( ct .sand_Group_ID,0) as sand_Group_ID ,
          Case when MartialStaus=0 then 'أعزب' else 'متزوج' END as RPT,
          ct.Registry1,
          ct.Registry2,
          ct.Ownername,
          CASE WHEN ct.AccType = 0 THEN 'أفراد' ELSE 'شركات' END AS `AccountType`

  FROM
          CustomersTb ct
          LEFT join
          Cobranch b
          on ct.BranchID=b.id

                  LEFT join
       `NationalityTb` d
          on ct.Nationality=d.ID
  WHERE
          ct.Code = p_Code;






















  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_SherchByAccID`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_SherchByAccID`(IN `p_AccID` BIGINT, IN `p_USERID` INT)
BEGIN
DECLARE v_CanShowHACC BIT;
START TRANSACTION;

SELECT t.CanShowHACC INTO v_CanShowHACC FROM TB_Users t WHERE t.USID=p_USERID
 ORDER BY t.USID DESC LIMIT 1;

	SELECT
			a.AccID,
			CustName,
      a.BranchID
	FROM
			CustomersTb a
      INNER JOIN
      AccountsTb b
      ON a.AccID=b.AccID
	WHERE
			a.AccID = p_AccID
			AND a.IsActive = 1
      AND (HiddenAccount=0 OR HiddenAccount=v_CanShowHACC)
	ORDER BY
			CustName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CustomersTb_Update`;
DELIMITER //
CREATE PROCEDURE `CustomersTb_Update`(IN `p_InsertDate` DATE, IN `p_Code` TEXT, IN `p_CustName` VARCHAR(100), IN `p_Phone1` VARCHAR(12), IN `p_Phone2` VARCHAR(12), IN `p_CustmAddress` VARCHAR(150), IN `p_BranchID` INT)
BEGIN
DECLARE v_AccountID BIGINT;


	START TRANSACTION;
	UPDATE
			CustomersTb
	SET
			InsertDate = p_InsertDate, Code = p_Code, CustName = p_CustName, Phone1 = p_Phone1, Phone2 = p_Phone2, CustmAddress = p_CustmAddress, BranchID = p_BranchID, IsActive = 1
	WHERE
		Code = p_Code;



	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Daily_transfer_preparer_schedule_DEttelse_Get`;
DELIMITER //
CREATE PROCEDURE `Daily_transfer_preparer_schedule_DEttelse_Get`(IN `p_ueserType` INT)
BEGIN
select a.ACCID , a.Daily , a.Weekly ,a.monthly ,a.Annual ,
a.ACCID ,c.AccName ,d.BName
from Daily_transfer_preparer_schedule_DEttelse as a
inner join users as b on a.ACCID =b.AccID
inner join AccountsTb as c on c.AccID = b.AccID
inner join CoBranch as d on c.BranchID = d.ID
where a.ueserTyp =p_ueserType

group by a.ACCID , a.Daily , a.Weekly ,a.monthly ,a.Annual ,
a.ACCID ,c.AccName ,d.BName;
END //
