CREATE PROCEDURE `Daily_transfer_preparer_schedule_insert`(IN `p_Weekly` DECIMAL(18,3), IN `p_Daily` DECIMAL(18,3), IN `p_monthly` DECIMAL(18,3), IN `p_Annual` DECIMAL(18,3), IN `p_Notes` TEXT, IN `p_uesertype` INT)
BEGIN
DECLARE v_Table_Count int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;
START TRANSACTION;

SELECT count (ID) INTO v_Table_Count FROM `Daily_transfer_preparer_schedule` where ueserTyp = p_uesertype;
if v_Table_Count = 0  THEN
INSERT INTO `Daily_transfer_preparer_schedule`
           (`Weekly`
           ,`Daily`
           ,`monthly`
           ,`Annual`,
		   Notes ,
           ueserTyp)
     VALUES
           (p_Weekly,
		   p_Daily ,
		   p_monthly ,
		   p_Annual ,
		   p_Notes ,
           p_uesertype
		   );
END IF;

if v_Table_Count >  0  THEN


UPDATE `Daily_transfer_preparer_schedule`
   SET `Weekly` = p_Weekly
      ,`Daily` = p_Daily
      ,`monthly` = p_monthly
      ,`Annual` = p_Annual ,
	  Notes =p_Notes ,
      ueserTyp = p_uesertype
      where ueserTyp =  p_uesertype;
END IF;

commit;



END //
