DROP PROCEDURE IF EXISTS `DailyCloseTb_Insert`;
DELIMITER //
CREATE PROCEDURE `DailyCloseTb_Insert`(IN `p_InsertDate` DATE, IN `p_Code` LONGTEXT, IN `p_CurrnecyID` INT, IN `p_SafeIDFrom` INT, IN `p_SafeIDTo` INT, IN `p_OverallDebit` DECIMAL(12,3), IN `p_OverallCredit` DECIMAL(12,3), IN `p_OverallRBVAL` DECIMAL(12,3), IN `p_OverallDBVAL` DECIMAL(12,3), IN `p_RBVALCanceled` DECIMAL(12,3), IN `p_RBVALFromBranches` DECIMAL(12,3), IN `p_OverallMainVal` DECIMAL(12,3), IN `p_RBVALFromCanceledBranches` DECIMAL(12,3), IN `p_BenefitNetTotal` DECIMAL(12,3), IN `p_SafeCID` INT, IN `p_BranchID` INT, IN `p_TransType` TINYINT UNSIGNED)
BEGIN
START TRANSACTION;

	INSERT INTO DailyCloseTb
			(
				InsertDate,
				Code,
				CurrnecyID,
				SafeIDFrom,
				SafeIDTo,
				OverallDebit,
				OverallCredit,
				OverallRBVAL,
				OverallDBVAL,
				RBVALCanceled,
				RBVALFromBranches,
				OverallMainVal,
				RBVALFromCanceledBranches,
				BenefitNetTotal,
				SafeCID,
				BranchID,
				TransType,
				IsActive
			)
	VALUES
			(
				p_InsertDate, p_Code, p_CurrnecyID, p_SafeIDFrom, p_SafeIDTo, p_OverallDebit, p_OverallCredit, p_OverallRBVAL, p_OverallDBVAL, p_RBVALCanceled, p_RBVALFromBranches, p_OverallMainVal, p_RBVALFromCanceledBranches, p_BenefitNetTotal, p_SafeCID, p_BranchID, p_TransType, 1

			);
	SELECT
			ID,
			InsertDate,
			Code,
			CurrnecyID,
			SafeIDFrom,
			SafeIDTo,
			OverallDebit,
			OverallCredit,
			OverallRBVAL,
			OverallDBVAL,
			RBVALCanceled,
			RBVALFromBranches,
			OverallMainVal,
			RBVALFromCanceledBranches,
			BenefitNetTotal,
			SafeCID,
			BranchID,
			TransType,
			IsActive
	FROM
			DailyCloseTb
	WHERE
			(ID = LAST_INSERT_ID());

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DailyCloseTb_LOADCURRENCYMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `DailyCloseTb_LOADCURRENCYMOVEMENT`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_InsertDateFrom` DATE, IN `p_InsertDateTo` DATE, INOUT `p_SumDebit` DECIMAL(15,2), INOUT `p_SumCredit` DECIMAL(15,2))
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#',
			a.Code									AS 'الرمز',
			a.InsertDate							'التاريخ',
			a.OverallDebit							AS 'مدين',
			a.OverallCredit							AS 'دائن',
			b.UName									'من خزنة',
			C.UName									'إلى خزنة',
			CASE 					WHEN a.TransType = 1 						THEN 						CONCAT('إغلاق خزنة', ' ', b.UName, ' ', 'إلى خزنة', ' ', C.UName) 					WHEN a.TransType = 2 						THEN 						CONCAT('نقل من خزنة', ' ', b.UName, ' ', 'إلى خزنة', ' ', C.UName) 			END										AS 'طبيعة الحركة'
	FROM
			DailyCloseTb AS a
		INNER JOIN
			TB_Users AS b
				ON a.SafeIDFrom = b.USID
		INNER JOIN
			TB_Users AS C
				ON a.SafeIDTo = C.USID
	WHERE
			a.IsActive = 1
			AND a.CurrnecyID = p_CurrencyID
			AND a.BranchID = p_BranchID
			AND a.InsertDate >= p_InsertDateFrom
			AND p_InsertDateFrom <= p_InsertDateTo;
	COMMIT;
SET p_SumDebit = `DailyCloseTb_GetSumTotalDebit`(p_BranchID, p_CurrencyID, p_InsertDateFrom, p_InsertDateTo);
SET p_SumCredit = `DailyCloseTb_GetSumTotalCredit`(p_BranchID, p_CurrencyID, p_InsertDateFrom, p_InsertDateTo);
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `deficit_OR_surplus_Calc`;
DELIMITER //
CREATE PROCEDURE `deficit_OR_surplus_Calc`(IN `p_CalcType` TINYINT(1), IN `p_InsertDate` DATE, IN `p_AccIDFrom` BIGINT, IN `p_CalcValue` DECIMAL(15,3), IN `p_BranchID` INT, IN `p_SAFEID` INT, IN `p_CurrencyID` INT, IN `p_BuyPrice` DECIMAL(15,3))
BEGIN
DECLARE v_IsDefault BIT;
DECLARE v_AccIDTO BIGINT;
DECLARE v_Code LONGTEXT;
DECLARE v_EMPCurrentAccID BIGINT;
DECLARE v_CalcValueDL DECIMAL(15, 3);
DECLARE v_CurrencyPower BIT;
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_DefalutCurr BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_DefalutCurrPrint BIGINT;
DECLARE v_SAFACCAS BIGINT;


  START TRANSACTION;


  SELECT a.FatherPerintACC INTO v_FatherPerintACC FROM
          CurrencyMainTb AS a
  WHERE
          a.ID = p_CurrencyID
 ORDER BY a.ID DESC LIMIT 1;

  SELECT AccID INTO v_FirstCurrencysASSS FROM
          AccountsTb AS a
  WHERE
          a.AccParent = v_FatherPerintACC
          AND a.BranchID = p_BranchID;

  SELECT a.ID INTO v_DefalutCurr FROM
          CurrencyMainTb AS a
  WHERE
          a.IsDefault = 1
 ORDER BY a.ID DESC LIMIT 1;


  SELECT aa.IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS aa
  WHERE
          aa.ID = p_CurrencyID
 ORDER BY aa.ID DESC LIMIT 1;

  SELECT EMPCurrentAccID INTO v_EMPCurrentAccID FROM
          `TB_Users`
  WHERE
          AccID = p_AccIDFrom
 ORDER BY TB_Users.USID DESC LIMIT 1;

  SELECT CPD.CurrencyPower INTO v_CurrencyPower FROM
          NewCurrencyPriceOwnDetailsTb AS CPD
      INNER JOIN
        NewCurrencyPricesOwnTb AS b
          ON CPD.CPID = b.ID
  WHERE
          CPD.CurrencyIDTo = p_CurrencyID
          AND b.PriceType = 0;

  IF v_CurrencyPower = 1
     THEN
SET v_CalcValueDL = FLOOR((p_CalcValue * p_BuyPrice) / 5) * 5;
    END IF;

  IF v_CurrencyPower = 0
     THEN
SET v_CalcValueDL = FLOOR((p_CalcValue / p_BuyPrice) / 5) * 5;
    END IF;


  IF p_CalcType = 0
     THEN
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '0', '30', '-', CAST(p_AccIDFrom AS CHAR), '-', CAST(deficit_OR_surplus_GetMaxIDCode() AS CHAR));
      SELECT AccID INTO v_AccIDTO FROM
              AccountsTb AS a
      WHERE
              a.AccParent = 3010301
              AND a.BranchID = p_BranchID;
      IF v_IsDefault = 1
         THEN

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SAFEID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose,
                  Note,
                  IsActive,
                  AccSafeActivityTb.SafeIDMovement
                )
          VALUES
                  (
                    p_SAFEID, 0.000, p_CalcValue, p_InsertDate, v_Code, 30, 58, p_BranchID, p_AccIDFrom, v_AccIDTO, 1, 0, 'عجز في خزنة الموظف', p_CurrencyID, 0, p_SAFEID, '', 1, 'عجز في خزنة الموظف'
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose,
                  Note,
                  IsActive,
                  AccSafeActivityTb.SafeIDMovement
                )
          VALUES
                  (
                    p_SAFEID, p_CalcValue, 0.000, p_InsertDate, v_Code, 30, 58, p_BranchID, v_AccIDTO, p_AccIDFrom, 1, 0, 'عجز في خزنة الموظف', p_CurrencyID, 0, p_SAFEID, '', 1, 'عجز في خزنة الموظف'
                  );


          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
