                  Note,
                  IsActive,
                  AccSafeActivityTb.SafeIDMovement
                )
          VALUES
                  (
                    p_SAFEID, 0.000, p_CalcValue, p_InsertDate, v_Code, 30, 58, p_BranchID, v_AccIDTO, v_EMPCurrentAccID, 1, 0, 'تسوية عجز في خزنة موظف', p_CurrencyID, 0, p_SAFEID, '', 1, 'تسوية عجز في خزنة موظف'
                  );
        END IF;
      IF v_IsDefault = 0
         THEN




          INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
