                )
          VALUES
                  (
                    p_SAFEID, 0.000, v_CalcValueDL, p_InsertDate, v_Code, 30, 58, p_BranchID, v_FirstCurrencysASSS, v_EMPCurrentAccID, 1, 0, 'عجز في خزنة الموظف', v_DefalutCurr, 0, p_SAFEID, '', 1, 'عجز في خزنة الموظف'
                  );


          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
