                  AccSafeActivityTb.SafeIDMovement
                )
          VALUES
                  (
                    p_SAFEID, v_CalcValueDL, 0.000, p_InsertDate, v_Code, 30, 58, p_BranchID, v_EMPCurrentAccID, v_FirstCurrencysASSS, 1, 0, 'عجز في خزنة الموظف', v_DefalutCurr, 0, p_SAFEID, '', 1, 'عجز في خزنة الموظف'
                  );
END IF;

          INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
                (
