                  );

        END IF;
    END IF;
  IF p_CalcType = 1
     THEN
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '0', '31', '-', CAST(p_AccIDFrom AS CHAR), '-', CAST(deficit_OR_surplus_GetMaxIDCode() AS CHAR));
      SELECT ACCID INTO v_AccIDTO FROM
              AccountsTb AS a
      WHERE
              a.AccParent = 4010203
              AND a.BranchID = p_BranchID;
      IF v_IsDefault = 1
         THEN

