DROP PROCEDURE IF EXISTS `DelegateTb_CHECK_PhoneNo`;
DELIMITER //
CREATE PROCEDURE `DelegateTb_CHECK_PhoneNo`(IN `p_Phone1` VARCHAR(50), IN `p_Phone2` VARCHAR(50))
BEGIN
START TRANSACTION;
	SELECT
			Phone1,
			Phone1
	FROM
			DelegateTb
	WHERE
			(		Phone1 = p_Phone1
					OR Phone1 = p_Phone2
					OR Phone2 = p_Phone1
					OR Phone2 = p_Phone2);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DelegateTb_Insert`;
DELIMITER //
CREATE PROCEDURE `DelegateTb_Insert`(IN `p_ID` INT, IN `p_DNAME` LONGTEXT, IN `p_Phone1` VARCHAR(50), IN `p_Phone2` VARCHAR(50), IN `p_IDNo` VARCHAR(50), IN `p_NationalityID` INT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO DelegateTb
					(
						DNAME,
						Phone1,
						Phone2,
						IDNo,
						NationalityID,
						IsActive
					)
			VALUES
					(
						p_DNAME, p_Phone1, p_Phone2, p_IDNo, p_NationalityID, 1
					);
			SELECT
					ID,
					DNAME,
					Phone1,
					Phone2,
					IDNo,
					NationalityID,
					IsActive
			FROM
					DelegateTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					DelegateTb
			SET
					DNAME = p_DNAME, Phone1 = p_Phone1, Phone2 = p_Phone2, IDNo = p_IDNo, NationalityID = p_NationalityID, IsActive = p_IsActive
			WHERE
				(   ID = p_ID
					OR p_ID IS NULL);
		END IF;
	COMMIT;
END //
DELIMITER ;

