DROP PROCEDURE IF EXISTS `DiscountsAndBounses_Statement`;
DELIMITER //
CREATE PROCEDURE `DiscountsAndBounses_Statement`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN



    START TRANSACTION;

    SELECT
            ROW_NUMBER() OVER (ORDER BY a.ID) AS '#',
            a.Code                            AS `الرمز`,
            b.EMPNAME                         AS `الاسم`,
            a.InsertDate                      AS `التاريخ`,
            c.DISNAME                         AS `البيان`,
            a.DISVAL                          AS `القيمة`,
            a.Notes                           AS `ملاحظات`,
            N'خصم'                            AS `النوع`
    FROM
            DiscountValTb AS a
        INNER JOIN
          EmployeeTb AS b
            ON a.EMPID = b.ID
        INNER JOIN
          DiscountTypeTb AS c
            ON a.DiscountTypeID = c.ID
    WHERE
            a.InsertDate BETWEEN p_D1 AND p_D2
            AND a.IsActive = 1

    UNION ALL

    SELECT
            ROW_NUMBER() OVER (ORDER BY a.ID) AS '#',
            a.Code                            AS `الرمز`,
            b.EMPNAME                         AS `الاسم`,
            a.InsertDate                      AS `التاريخ`,
            c.PIName                          AS `البيان`,
            a.INCVAL                          AS `القيمة`,
            a.Notes                           AS `ملاحظات`,
            N'علاوة'                          AS `النوع`
    FROM
            IncreaseValTb AS a
        INNER JOIN
          EmployeeTb AS b
            ON a.EMPID = b.ID
        INNER JOIN
          PayIncrease AS c
            ON a.IncreaseTypeID = c.ID
    WHERE
            a.InsertDate BETWEEN p_D1 AND p_D2
            AND a.IsActive = 1;

    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DiscountTypeTb_Insert`;
