DROP PROCEDURE IF EXISTS `DiscountValTb_Insert`;
DELIMITER //
CREATE PROCEDURE `DiscountValTb_Insert`(IN `p_InsertDate` DATE, IN `p_EMPID` BIGINT, IN `p_DISVAL` DECIMAL(12,3), IN `p_DiscountTypeID` INT, IN `p_SafeID` INT, IN `p_Code` LONGTEXT, IN `p_AccBranchID` INT, IN `p_CurrencyID` INT, IN `p_Notes` LONGTEXT, IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MSGBOX` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_AccDisc BIGINT;
DECLARE v_AccEmpBranchID BIGINT;
DECLARE v_AccEmp BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


			START TRANSACTION;

	SELECT a.AccID INTO v_AccDisc FROM
			AccountsTb AS a
		LEFT JOIN
			EmployeeTb AS b
				ON a.BranchID = b.BranchID
	WHERE
			b.ID = p_EMPID
			AND a.AccParent = 4121;

	SELECT a.AccID INTO v_AccEmp FROM
			AccountsTb AS a
		JOIN
			EmployeeTb AS b
				ON a.AccID = b.AccID
	WHERE
			b.ID = p_EMPID;

	IF p_IsUpdate = 0
		 THEN
		SELECT Code INTO v_GETID FROM
					DiscountValTb AS a
			WHERE
					a.Code = p_Code;
		IF p_Code = v_GETID
								 THEN
									SET p_MSGSTatues = 0;
									SET p_MSGBOX = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
									ROLLBACK;
									LEAVE proc;
		END IF;
			INSERT INTO DiscountValTb
					(
						InsertDate,
						EMPID,
						DiscountTypeID,
						DISVAL,
						Code,
						IsActive,
						Notes,
						IsOpened
					)
			VALUES
					(
						p_InsertDate, p_EMPID, p_DiscountTypeID, p_DISVAL, p_Code, 1, p_Notes, 1
					);











































































			SELECT
					ID,
					InsertDate,
					EMPID,
					DISVAL,
					Code,
					IsActive
			FROM
					DiscountValTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					DiscountValTb
			SET
					DiscountValTb.IsActive = 0,
					DiscountValTb.IsOpened = 0
			WHERE
				Code = p_Code;
		END IF;
					COMMIT;
			SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DiscountValTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `DiscountValTb_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ) AS '#',
			a.Code										   AS 'الرمز',
			a.InsertDate								   AS 'التاريخ',
			c.EMPNAME									   AS 'اسم الموظف',
			b.DISNAME									   AS 'نوع الخصم',
			a.DISVAL									   AS 'إجمالي الخصميات',
      a.Notes AS 'الملاحظات',
			CASE 					WHEN a.IsOpened = 0 						THEN 						'منتهي' 					ELSE 					'تحت الإجراء' 			END											   AS 'الحالة'
	FROM
			DiscountValTb AS a
		LEFT JOIN
			DiscountTypeTb AS b
				ON a.DiscountTypeID = b.ID
		LEFT JOIN
			EmployeeTb AS c
				ON a.EMPID = c.ID
	WHERE
			a.IsActive = 1
			AND b.IsActive = 1
			AND c.BranchID = p_BranchID
			AND a.InsertDate BETWEEN p_D1 AND p_D2
	ORDER BY
			a.ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DiscountValTb_LOADINTOLKP`;
DELIMITER //
CREATE PROCEDURE `DiscountValTb_LOADINTOLKP`()
BEGIN
