DROP PROCEDURE IF EXISTS `DiscountValTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `DiscountValTb_LOADTODVG`()
BEGIN
START TRANSACTION;

	SELECT
			ROW_NUMBER() OVER (ORDER BY A.ID ASC) AS '#',
			A.Code								  AS 'الرمز',
			A.InsertDate						  AS 'التاريخ',
			B.EMPNAME							  'اسم الموظف',
			A.DISVAL							  'القيمة',
			C.DISNAME							  'نوع الخصم',
			A.IsActive							  'الحالة'
	FROM
			DiscountValTb AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
		LEFT JOIN
			DiscountTypeTb AS C
				ON A.DiscountTypeID = C.ID
	WHERE
			A.IsActive = 1
			AND A.IsOpened = 1;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `DiscountValTb_Select`;
DELIMITER //
CREATE PROCEDURE `DiscountValTb_Select`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
	b.ID,
	a.Code,
	a.InsertDate,
	a.EMPID,
	a.DISVAL,
	a.DiscountTypeID,
	a.IsActive,
	b.BranchID,
	c.BName,
	b.EMPNAME,
	E.DISNAME,
     Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
	e.DISNAME
	 FROM
	 DiscountValTb AS a
	INNER JOIN EmployeeTb AS b ON a.EMPID=b.ID
	LEFT JOIN CoBranch AS C ON B.BranchID=C.ID
	LEFT JOIN DiscountTypeTb AS E ON A.DiscountTypeID =E.ID

	WHERE a.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

