DROP PROCEDURE IF EXISTS `EMPCHECK_PETTYCASHACCIDHASVAL`;
DELIMITER //
CREATE PROCEDURE `EMPCHECK_PETTYCASHACCIDHASVAL`(IN `p_EMPID` INT)
BEGIN
START TRANSACTION;

  SELECT
          a.ID,a.AccID
  FROM
          EmployeeTb AS a
      INNER JOIN
        PettyCashTb AS c
          ON a.ID = c.EMPID

  WHERE

           a.ID = p_EMPID
          AND c.IsActive = 1
          AND c.IsSettlement = 0
  GROUP BY
          a.ID,
          a.EMPNAME,a.AccID
  ORDER BY
          a.EMPNAME;
  COMMIT;
END //
DELIMITER ;

