DROP PROCEDURE IF EXISTS `EmployeeClassificationTb_Insert`;
DELIMITER //
CREATE PROCEDURE `EmployeeClassificationTb_Insert`(IN `p_ECNAME` LONGTEXT, IN `p_ID` INT, IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO EmployeeClassificationTb
					(
						ECNAME,
						IsActive
					)
			VALUES
					(
						p_ECNAME, 1
					);
			SELECT
					ID,
					ECNAME,
					IsActive
			FROM
					EmployeeClassificationTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					EmployeeClassificationTb
			SET
					ECNAME = p_ECNAME, IsActive = 1
			WHERE
				ID = p_ID;
			SELECT
					ID,
					ECNAME,
					IsActive
			FROM
					EmployeeClassificationTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	COMMIT;
END //
DELIMITER ;

