DROP PROCEDURE IF EXISTS `EmployeeTb_GetEMPBounsTotal`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_GetEMPBounsTotal`(IN `p_EMPID` INT)
BEGIN
DECLARE v_TotalConastanceVal DECIMAL(15, 3);
DECLARE v_TotalTempVal DECIMAL(12, 3);


	START TRANSACTION;
	SELECT IFNULL(SUM(a.INCVAL), 0.000) INTO v_TotalTempVal FROM
			IncreaseValTb AS a
	WHERE
			a.EMPID = p_EMPID
			AND a.IsConstant = 0
			AND a.IsActive = 1
			AND a.IsOpened = 1;
	SELECT IFNULL(SUM(a.INCVAL), 0.000) INTO v_TotalConastanceVal FROM
			IncreaseValTb AS a
	WHERE
			a.EMPID = p_EMPID
			AND a.IsConstant = 1
			AND a.IsActive = 1
			AND a.IsOpened = 1;
	SELECT
			v_TotalTempVal		AS TotalTempVal,
			v_TotalConastanceVal AS TotalConastanceVal;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EmployeeTb_GetUserAccID`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_GetUserAccID`(IN `p_EMPID` INT)
BEGIN
START TRANSACTION;
	SELECT
		IFNULL(	b.AccID,0) AS AccID
	FROM
			EmployeeTb AS a
		Left JOIN
			TB_Users b
				ON a.ID=b.EMPID
	WHERE
			a.ID = p_EMPID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPLOYEETB_Insert`;
DELIMITER //
CREATE PROCEDURE `EMPLOYEETB_Insert`(IN `p_CODE` LONGTEXT, IN `p_EMPNAME` LONGTEXT, IN `p_NATNUMBER` LONGTEXT, IN `p_CLASSIFICATION` INT, IN `p_PHONE1` VARCHAR(50), IN `p_PHONE2` VARCHAR(50), IN `p_BIRTHDATE` DATE, IN `p_EMPDATE` DATE, IN `p_PassportNo` LONGTEXT, IN `p_Nationality` LONGTEXT, IN `p_CertificateType` LONGTEXT, IN `p_SalaryVal` DOUBLE, IN `p_EMail` LONGTEXT, IN `p_CanDebit` TINYINT UNSIGNED, IN `p_Jobgrade` INT, IN `p_ISACTIVE` TINYINT(1), IN `p_BranchID` INT, IN `p_IsUpdate` TINYINT(1), IN `p_ID` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_BankID` INT, IN `p_BBranchID` INT, IN `p_AccOwner` LONGTEXT, IN `p_BankNo` LONGTEXT, IN `p_BankSalaryCalc` TINYINT(1), IN `p_ContractID` BIGINT)
proc: BEGIN
DECLARE v_IsExisit INT;
DECLARE v_OldeCustName LONGTEXT;
DECLARE v_CheckName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_fatherparent DECIMAL(18, 0);
DECLARE v_ADPMNTAccID DECIMAL(18, 0);
DECLARE v_PettyAccID DECIMAL(18, 0);
DECLARE v_acccode DECIMAL(18, 0);
DECLARE v_IDcode BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_BName LONGTEXT;
DECLARE v_AccID BIGINT;
DECLARE v_AccIDPTTCA BIGINT;
DECLARE v_AccIDEx BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;



    START TRANSACTION;





























    IF p_IsUpdate = 0
       THEN
                  SET p_MSGSTatues = 0;
            SET p_MsgBox = 'لا يمكن إضافة موظف  من المنظومة الرجاء الذهاب للموقع';
            ROLLBACK;
            LEAVE proc;
































































































      END IF;

    IF p_IsUpdate = 1
       THEN

        SELECT AccID INTO v_AccID FROM
                EmployeeTb AS ET
        WHERE
                ID = p_ID;
        SELECT ET.AccIDPTTCA INTO v_AccIDPTTCA FROM
                EmployeeTb AS ET
        WHERE
                ID = p_ID;
        SELECT ET.AccIDEx INTO v_AccIDEx FROM
                EmployeeTb AS ET
        WHERE
                ID = p_ID;


        SELECT CT.EMPNAME INTO v_OldeCustName FROM
                EmployeeTb AS CT
        WHERE
                ID = p_ID;

        SELECT CT.BranchID INTO v_OldBranchID FROM
                EmployeeTb AS CT
        WHERE
                ID = p_ID;

        SELECT CT.EMPNAME INTO v_CheckName FROM
                EmployeeTb AS CT
        WHERE
                ID <> p_ID;


        IF v_CheckName = p_EMPNAME
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا هذا الاسم موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;


        IF v_OldeCustName <> p_EMPNAME
          AND
          v_OldBranchID <> p_BranchID
           THEN
            SELECT CB.BName INTO v_BName FROM
                    CoBranch AS CB
            WHERE
                    CB.ID = p_BranchID;
SET v_IDcode = IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_fatherparent) , 0) + 1;
            UPDATE
                    AccountsTb
            SET
                    AccName = p_EMPNAME, AccCode = CONCAT(CAST(v_fatherparent AS CHAR), '0', v_IDcode), IDcode = v_IDcode, BranchID = p_BranchID
            WHERE
              AccID = v_AccID;
          END IF;

        IF v_OldeCustName = p_EMPNAME
          AND
          v_OldBranchID <> p_BranchID
           THEN
            SELECT CB.BName INTO v_BName FROM
                    CoBranch AS CB
            WHERE
                    CB.ID = p_BranchID;
SET v_acccode = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_fatherparent) , 0) + 1 AS CHAR));
SET v_IDcode = IFNULL((SELECT MAX(xx.IDcode) FROM AccountsTb AS xx WHERE xx.AccParent = v_fatherparent) , 0) + 1;
            UPDATE
                    AccountsTb
            SET
                    AccCode = CONCAT(CAST(v_fatherparent AS CHAR), '0', v_IDcode), IDcode = v_IDcode, BranchID = p_BranchID
            WHERE
              AccID = v_AccID;

          END IF;

        IF v_OldeCustName <> p_EMPNAME
          AND
          v_OldBranchID = p_BranchID
           THEN

            UPDATE
                    AccountsTb
            SET
                    AccName = p_EMPNAME
            WHERE
              AccID = v_AccID;
          END IF;


        UPDATE
                EmployeeTb
        SET
                CODE = p_CODE, EMPNAME = p_EMPNAME, NATNUMBER = p_NATNUMBER,
                `CLASSIFICATION` = p_CLASSIFICATION,
                PHONE1 = p_PHONE1,
                PHONE2 = p_PHONE2,
                BIRTHDATE = p_BIRTHDATE,
                EMPDATE = p_EMPDATE,
                PassportNo = p_PassportNo,
                Nationality = p_Nationality,
                CertificateType = p_CertificateType,
                SalaryVal = p_SalaryVal,
                EMail = p_EMail,
                CanDebit = p_CanDebit,
                Jobgrade = p_Jobgrade,
                ISACTIVE = p_ISACTIVE,
                BranchID = p_BranchID,
                BankID = p_BankID,
                BBranchID = p_BBranchID,
                AccOwner = p_AccOwner,
                BankNo = p_BankNo,
                BankSalaryCalc = p_BankSalaryCalc

        WHERE
          ID = p_ID;

        UPDATE
                AccountsTb
        SET
                AccPhone = p_PHONE1, AccMobile = p_PHONE2, AccEmail = p_EMail, AccIDNo = p_PassportNo, EditDate = NOW(), CanDebit = p_CanDebit, AccNatNumber=p_NATNUMBER
        WHERE
          AccID = v_AccID;
      END IF;

    UPDATE
            TB_Users
    SET
            IsActive = p_ISACTIVE
    WHERE
      EMPID = p_ID;

    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EmployeeTb_LOADBASEDOnBRANCHCODE`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_LOADBASEDOnBRANCHCODE`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			ID,
			EMPNAME,
      Code
	FROM
			EmployeeTb
	WHERE
			EmployeeTb.BranchID = p_BranchID
			AND EmployeeTb.IsActive = 1
	ORDER BY
			EmployeeTb.EMPNAME;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EmployeeTb_LOADBASISDATA`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_LOADBASISDATA`()
BEGIN
DECLARE v_BID BIGINT;
DECLARE v_BL BIGINT;
START TRANSACTION;

	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ASC)	  AS '#',
			CONCAT('0', '1', '0', CAST(a.ID AS CHAR)) AS 'الرمز',
			a.EMPNAME								  'الاسم',
			b.BName									  'الفرع',
			c.ECNAME								  'التصنيف'
	FROM
			EmployeeTb AS a
		LEFT OUTER JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
		LEFT OUTER JOIN
			EmployeeClassificationTb AS c
				ON a.`CLASSIFICATION` = c.ID
	WHERE
			a.ISACTIVE = 1
	ORDER BY
			a.ID ASC;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EmployeeTb_LOADINTOIndivdualSalary`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_LOADINTOIndivdualSalary`(IN `p_BranchID` INT, IN `p_Salarymonth` INT, IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
  IF p_IsUpdate = 0
     THEN
      SELECT
              b.AccID,
              a.EMPNAME
      FROM
              EmployeeTb AS a
          LEFT JOIN
            AccountsTb AS b
              ON a.AccID = b.AccID
      WHERE
              NOT EXISTS (SELECT
                          b.EMPID
                  FROM
                          SalaryCalculationTb AS b
                  WHERE
                          b.EMPID = a.ID
                          AND b.SALARYMONTH = p_Salarymonth)
              AND a.IsActive = 1
              AND a.BranchID = p_BranchID
      ORDER BY
              a.EMPNAME;
    END IF;
  IF p_IsUpdate = 1
     THEN
      SELECT
              b.AccID,
              a.EMPNAME
      FROM
              EmployeeTb AS a
          INNER JOIN
            AccountsTb AS b
              ON a.AccID = b.AccID
      WHERE
              a.IsActive = 1
              AND a.BranchID = p_BranchID
      ORDER BY
              a.EMPNAME;
    END IF;
  COMMIT;
END //
DELIMITER ;

