DROP PROCEDURE IF EXISTS `EmployeeTb_LOADINTOLKPBASEDONPETTYCASHACCID`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_LOADINTOLKPBASEDONPETTYCASHACCID`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			b.AccID,
			b.AccName AS EMPNAME
	FROM
			EmployeeTb AS a
		inner JOIN
			AccountsTb AS b
				ON a.EMPNAME = b.AccName
	WHERE
			a.BranchID = p_BranchID
			AND LEFT(AccParent, 3) = 10107
			AND b.Accline = 4
			AND a.IsActive = 1
	GROUP BY
			b.AccName,
			b.AccID
	ORDER BY
			b.AccName;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EmployeeTb_LOADINTOLKPBASEDONPETTYCASHACCIDHASVAL`;
DELIMITER //
CREATE PROCEDURE `EmployeeTb_LOADINTOLKPBASEDONPETTYCASHACCIDHASVAL`(IN `p_BranchID` INT, IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			SELECT
					a.AccID,
					a.EMPNAME
			FROM
					EmployeeTb AS a
				LEFT JOIN
					AccountsTb AS b ON
					a.EMPNAME = b.AccName
				LEFT JOIN
					PettyCashTb AS c
						ON a.ID = c.EMPID
			WHERE
					a.BranchID = p_BranchID
					AND LEFT(AccParent, 5) = 20105
					AND b.Accline = 4
					AND a.ID = c.EMPID
					AND c.IsActive = 1
					AND c.IsSettlement = 0
			GROUP BY
					a.AccID,
					a.EMPNAME
			ORDER BY
					a.EMPNAME;
		END IF;
	IF p_IsUpdate = 1
		 THEN
			SELECT
					A.AccID,
					a.EMPNAME
			FROM
					EmployeeTb AS a

				LEFT JOIN
					PCSettlementTB AS c
						ON a.ID = c.EMPID
			WHERE
					a.BranchID = p_BranchID


					AND c.IsActive = 1

			GROUP BY
					A.AccID,
					a.EMPNAME
			ORDER BY
					a.EMPNAME;
		END IF;
	COMMIT;
END //
DELIMITER ;

