DROP PROCEDURE IF EXISTS `EMPORCUST_LOADBASICDATA`;
DELIMITER //
CREATE PROCEDURE `EMPORCUST_LOADBASICDATA`(IN `p_TypeID` INT, IN `p_AccID` BIGINT, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_IsDefault BIT;
START TRANSACTION;
	SELECT cmt.IsDefault INTO v_IsDefault FROM
			CurrencyMainTb cmt where ID=p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;
	IF p_TypeID = 5
		 THEN
			SELECT
					a.PHONE1,
					a.PHONE2,
					a.PassportNo,
					b.AccID
			FROM
					EmployeeTb AS a
				LEFT JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
			WHERE
					b.AccID = p_AccID
			GROUP BY
					a.PHONE1,
					a.PHONE2,
					a.PassportNo,
					b.AccID,
					a.EMPNAME
			HAVING
					`EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID) > 0.000
			ORDER BY
					a.EMPNAME;
		END IF;
	IF p_TypeID = 6
		 THEN
			SELECT
					a.Phone1,
					a.Phone2,
					'لا يوجد' AS PassportNo,
					b.AccID

			FROM
					CustomersTb AS a
				LEFT JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
			WHERE
					b.AccID = p_AccID
			GROUP BY
					a.Phone1,
					a.Phone2,
					b.AccID,
                  a.CandDebit
          HAVING
                  (CASE                           WHEN a.CandDebit = 1                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) > 0.000
                  OR (CASE                           WHEN a.CandDebit = 0                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) <= 0.000
                  OR (CASE                           WHEN a.CandDebit = 0                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) >= 0.000
			ORDER BY
					b.AccID;
		END IF;
	IF p_TypeID = 7
		 THEN
			SELECT
					a.PHONE1,
					a.PHONE2,
					a.PassportNo,
					b.AccID
			FROM
					EmployeeTb AS a
				LEFT JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
			WHERE
					b.AccID = p_AccID
			ORDER BY
					a.EMPNAME;
		END IF;
	IF p_TypeID = 8
		 THEN
			SELECT
					a.Phone1,
					a.Phone2,
					'لا يوجد' AS PassportNo,
					b.AccID
			FROM
					CustomersTb AS a
				LEFT JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
			WHERE
					b.AccID = p_AccID
			GROUP BY
					a.Phone1,
					a.Phone2,
					b.AccID
			ORDER BY
					b.AccID;
		END IF;
	IF p_TypeID = 25
		 THEN
			SELECT
					a.Phone1,
					a.Phone2,
					'لا يوجد' AS PassportNo,
					a.AccID
			FROM
					CreditAccountsTb AS a

			WHERE
					a.AccID = p_AccID
			ORDER BY
					a.AccID;
		END IF;

	IF p_TypeID = 26
		 THEN
			SELECT
					a.Phone1,
					a.Phone2,
					a.IDNoe AS PassportNo,
					a.CurrentAcc AS AccID
			FROM
					AddPartnerTb  AS a
				INNER JOIN
					AccountsTb AS b
						ON a.CurrentAcc = b.AccID
			WHERE
					b.AccID = p_AccID
          AND b.AccActive=1
          AND a.IsActive=1





			ORDER BY
					b.AccID;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUST_LOADBASICDATATONEWWD`;
DELIMITER //
CREATE PROCEDURE `EMPORCUST_LOADBASICDATATONEWWD`(IN `p_BranchID` INT)
BEGIN
DECLARE v_dncurrent INT;
DECLARE v_SalaryVal DECIMAL(15, 3);
DECLARE v_AdvpVal DECIMAL(15, 3);
DECLARE v_resVal DECIMAL(15, 3);
DECLARE v_ValPerday DECIMAL(15, 3);
DECLARE v_netSalary DECIMAL(15, 3);
START TRANSACTION;
	SELECT
			x.EMPNAME,
			x.SalaryVal,
			x.ValPerMonth,
			x.AccID
	FROM
			(   (SELECT
						a.EMPNAME,
						a.SalaryVal,
						0.000 AS ValPerMonth,
						b.AccID
				FROM
						EmployeeTb AS a
					INNER JOIN
						AccountsTb AS b
							ON a.AccID = b.AccID
				WHERE
						a.BranchID = p_BranchID and a.ISACTIVE=1)
				UNION ALL
				(SELECT
						'' AS EMPNAME,
						0.000 AS SalaryVal,
						CASE 								WHEN C.IsActive = 1 									AND a.ID = C.EMPID 									AND C.IsOpened = 1 									THEN 									C.ValPerMonth 								ELSE 								0.000 						END AS ValPerMonth,
						0 AS AccID
				FROM
						EmployeeTb AS a
				INNER JOIN
						AdvancePaymentTb AS C
							ON a.ID = C.EMPID
				WHERE
						a.BranchID = p_BranchID
						AND C.IsActive = 1
						AND C.IsOpened = 1 AND a.ISACTIVE=1)) AS x;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUST_LOADBASICDATATONEWWDANDACCID`;
DELIMITER //
CREATE PROCEDURE `EMPORCUST_LOADBASICDATATONEWWDANDACCID`(IN `p_ACCID` BIGINT)
BEGIN
DECLARE v_dncurrent INT;
DECLARE v_SalaryVal DECIMAL(15, 3);
DECLARE v_AdvpVal DECIMAL(15, 3);
DECLARE v_resVal DECIMAL(15, 3);
DECLARE v_ValPerday DECIMAL(15, 3);
DECLARE v_netSalary DECIMAL(15, 3);
DECLARE v_mncurrent INT;
DECLARE v_yncurrent INT;
DECLARE v_EMPID BIGINT;
START TRANSACTION;
	SELECT COUNT(a.EMPID) INTO v_EMPID FROM
			SalaryCalculationTb AS a
		LEFT OUTER JOIN
			EmployeeTb AS b
				ON a.EMPID = b.ID
		LEFT OUTER JOIN
			AccountsTb AS c
				ON b.AccID = c.AccID
	WHERE
			c.AccID = p_ACCID
			AND a.SALARYMONTH = MONTH(NOW())
			AND a.SALARYEAR = YEAR(NOW());
SET v_dncurrent = DAY(NOW());
	IF v_EMPID = 0
		 THEN
			SELECT
					v_EMPID AS EMPID,
					a.EMPNAME,
					a.SalaryVal,
					CASE 							WHEN C.IsActive = 1 								AND b.AccID = p_ACCID 								AND C.IsOpened = 1 								THEN 								SUM(C.ValPerMonth) 							ELSE 							0.000 					END	   AS ValPerMonth,
					b.AccID

			FROM
					EmployeeTb AS a
				LEFT OUTER JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
				LEFT OUTER JOIN
					AdvancePaymentTb AS C
						ON a.ID = C.EMPID
			WHERE
					b.AccID = p_ACCID
			GROUP BY
					a.EMPNAME,
					a.SalaryVal,
					b.AccID,
					C.IsActive,
					C.IsOpened;
		END IF;
	IF v_EMPID > 0
		 THEN
			SELECT
					v_EMPID							  AS EMPID,
					a.EMPNAME,
					`EMPCUST_GetAccVal`(p_ACCID) AS SalaryVal,
					0.000							  AS ValPerMonth,
					b.AccID
			FROM
					EmployeeTb AS a
				LEFT OUTER JOIN
					AccountsTb AS b
						ON a.AccID = b.AccID
				LEFT OUTER JOIN
					AdvancePaymentTb AS C
						ON a.ID = C.EMPID
			WHERE
					b.AccID = p_ACCID
			GROUP BY
					a.EMPNAME,
					a.SalaryVal,
					b.AccID,
					C.IsActive,
					C.IsOpened;
			SELECT
					v_EMPID AS EMPID;
		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUST_LOADINTOLKPBASEDONACCID`;
DELIMITER //
CREATE PROCEDURE `EMPORCUST_LOADINTOLKPBASEDONACCID`(IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_IsUpdate` TINYINT(1), IN `p_CurrencyID` INT, IN `p_UserID` INT)
BEGIN
DECLARE v_IsDefault BIT;
DECLARE v_CanShowHACC BIT;
START TRANSACTION;
  SELECT cmt.IsDefault INTO v_IsDefault FROM
          CurrencyMainTb cmt
  WHERE
          ID = p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;

  SELECT t.CanShowHACC INTO v_CanShowHACC FROM
          TB_Users t
  WHERE
          t.USID = p_UserID
 ORDER BY t.USID DESC LIMIT 1;

  IF p_IsUpdate = 0
     THEN
      IF p_TypeID = 5
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID

          GROUP BY
                  b.AccID,
                  a.EMPNAME
          HAVING
                  `EMPCUST_GetAccValCashOnly`(b.AccID) > 0.000
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 7
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 6
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND (   a.HiddenAccount = 0
                          OR a.HiddenAccount = v_CanShowHACC)

          GROUP BY
                  b.AccID,
                  a.CustName,
                  a.CandDebit

          HAVING
                  (CASE                           WHEN a.CandDebit = 1                             THEN                             `EMPCUST_GetAccValCashOnly`(b.AccID)                   END > 0.000)
                  OR ( a.CandDebit = 0
                        )

          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 8
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 16
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          GROUP BY
                  b.AccID,
                  a.EMPNAME
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 18
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 19
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          GROUP BY
                  b.AccID,
                  a.CustName,
                  a.CandDebit
          HAVING
                  (CASE                           WHEN a.CandDebit = 1                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) > 0.000
                  OR (CASE                           WHEN a.CandDebit = 0                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) <= 0.000
                  OR (CASE                           WHEN a.CandDebit = 0                             THEN                             `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID)                   END) >= 0.000
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 17
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.ISACTIVE = 1
          GROUP BY
                  b.AccID,
                  a.EMPNAME
          HAVING
                  `EMPORCUST_GetAccVal`(b.AccID, p_CurrencyID) > 0.000
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 25
         THEN
          SELECT
                  a.AccID,
                  a.AccName AS EMCUST
          FROM
                  CreditAccountsTb AS a
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.AccName;
        END IF;
        IF p_TypeID = 26
         THEN
          SELECT
                  a.AccID,
                  a.AccName AS EMCUST
          FROM
                  AccountsTb  AS a
                  INNER JOIN
                  AddPartnerTb b
                  ON a.AccID=b.CurrentAcc
          WHERE
                  a.BranchID = p_BranchID
                  AND a.AccActive = 1
                  AND a.AccParent LIKE '2010100%'
                  AND b.IsActive=1
          ORDER BY
                  a.AccName;
        END IF;
    END IF;
  IF p_IsUpdate = 1
     THEN
      IF p_TypeID = 5
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          GROUP BY
                  b.AccID,
                  a.EMPNAME
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 7
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 6
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
                  AND (   a.HiddenAccount = 0
                          OR a.HiddenAccount = v_CanShowHACC)
          GROUP BY
                  b.AccID,
                  a.CustName
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 8
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 17
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 19
         THEN
          SELECT
                  b.AccID,
                  a.CustName AS EMCUST
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.CustName;
        END IF;
      IF p_TypeID = 16
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          GROUP BY
                  b.AccID,
                  a.EMPNAME
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 18
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          GROUP BY
                  b.AccID,
                  a.EMPNAME
          ORDER BY
                  a.EMPNAME;
        END IF;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_Insert`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_Insert`(IN `p_Code` TEXT, IN `p_AccParent` BIGINT, IN `p_WDVAL` DECIMAL(12,3), IN `p_SafeID` INT, IN `p_TypeID` TINYINT UNSIGNED, IN `p_CODEID` BIGINT, IN `p_BranchID` INT, IN `p_DPSVAL` DECIMAL(12,3), IN `p_Notes` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_AccIDFrom` BIGINT, IN `p_CurrencyFrom` INT, INOUT `p_MSG` INT, INOUT `p_MSGBOX` LONGTEXT, IN `p_PaidFor` LONGTEXT, IN `p_Phone` LONGTEXT, IN `p_IDNo` VARCHAR(50), IN `p_OPType` INT)
proc: BEGIN
DECLARE v_AccVal DECIMAL(12, 3);
DECLARE v_CanDEpit BIT;
DECLARE v_LimtedVal DECIMAL(12, 3);
DECLARE v_IsLimted BIT;
DECLARE v_IsDefault BIT;
DECLARE v_CurrDefault INT;
DECLARE v_UserID INT;
DECLARE v_AccName LONGTEXT;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_MovementType LONGTEXT;
DECLARE v_MovementType2 LONGTEXT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGBOX = 0; END;


      START TRANSACTION;




          SELECT cmt.IsDefault INTO v_IsDefault FROM
                  CurrencyMainTb cmt
          WHERE
                  cmt.ID = p_CurrencyFrom
 ORDER BY cmt.ID DESC LIMIT 1;

          SELECT cmt.ID INTO v_CurrDefault FROM
                  CurrencyMainTb cmt
          WHERE
                  cmt.IsDefault = 1
 ORDER BY cmt.ID DESC LIMIT 1;

          SELECT tu.USID INTO v_UserID FROM
                  TB_Users tu
          WHERE
                  tu.AccID = p_SafeID
 ORDER BY tu.USID DESC LIMIT 1;
SELECT at.AccName INTO v_AccName FROM AccountsTb at WHERE at.AccID=p_AccIDFrom;






          IF EXISTS (SELECT
                        1
                FROM
                        EMPORCUSTWITHDRAWALTB AS a
                WHERE
                        a.Code = p_Code)  AND p_IsUpdate=0
             THEN
              SET p_MSG = 2;
              SET p_MSGBOX = N'عذراً، رقم الكود محجوز مسبقاً. الرجاء إعادة المحاولة.';
              ROLLBACK;
              LEAVE proc;
            END IF;



          IF p_TypeID = 5 AND p_IsUpdate=0
             THEN

              SET v_AccVal = Account_GetAccVal(p_AccIDFrom, p_CurrencyFrom, 0);
              SELECT CASE                                           WHEN at.AccDmType = 0                                             THEN                                             1                                           ELSE                                           at.CanDebit                                   END, CASE                                           WHEN at.AccDmType = 0                                             THEN                                             0                                           ELSE                                           IFNULL(at.IsLimited, 0)                                   END, IFNULL(at.LimitedVal, 0) INTO v_CanDEpit, v_IsLimted, v_LimtedVal FROM
                      AccountsTb at
              WHERE
                      AccID = p_AccIDFrom;




              IF v_CanDEpit = 0
                AND
                p_WDVAL > v_AccVal
                AND
                p_OPType<>90
                 THEN
                  SET p_MSG = 0;
                  SET p_MSGBOX = N'عذراً، القيمة المراد سحبها أكبر من الرصيد المتاح.';
                  ROLLBACK;
                  LEAVE proc;
                END IF;

              IF v_CanDEpit = 1
                AND
                v_IsLimted = 1
                AND
                p_WDVAL > (v_LimtedVal + v_AccVal)
                 THEN
                  SET p_MSG = 0;
                  SET p_MSGBOX = N'القيمة المراد تحويلها أكبر من السقف المسموح به.';
                  ROLLBACK;
                  LEAVE proc;
                END IF;

              IF EXISTS (SELECT
                            1
                    FROM
                            EmployeeTb et
                    WHERE
                            et.AccID = p_AccIDFrom
                            AND et.IsResignation = 1
                            AND et.ResignatoinDate > NOW())
                 THEN
                  IF p_WDVAL > v_AccVal
                     THEN
                      SET p_MSG = 0;
                      SET p_MSGBOX = N'عذراً، الموظف لديه طلب استقالة مسجّل، ولا يحق له السحب بما يتجاوز رصيده الحالي. يرجى مراجعة الإدارة لمزيد من التفاصيل.';
                      ROLLBACK;
                      LEAVE proc;
                    END IF;
                END IF;
            END IF;




          IF p_IsUpdate=0
           THEN
          INSERT INTO EMPORCUSTWITHDRAWALTB
                (
                  Code,
                  InsertDate,
                  EMPID,
                  WDVAL,
                  SafeID,
                  IsActive,
                  TypeID,
                  EMPORCUSTWITHDRAWALTB.CODEID,
                  BranchID,
                  DPSVAL,
                  Notes,
                  CurrencyFrom,
                  PaidFor,
                  Phone,
                  IDNo,
                  parentCode
                )
          VALUES
                  (
                    p_Code, NOW(), p_AccIDFrom, p_WDVAL, p_SafeID, 1, p_TypeID, p_CODEID, p_BranchID, p_DPSVAL, p_Notes, p_CurrencyFrom, p_PaidFor, p_Phone, p_IDNo,p_AccParent
                  );
END IF;
          IF p_TypeID = 5
             THEN
            IF p_IsUpdate = 0
             THEN
                SET v_MovementType2  = CONCAT(N'صرف من حساب', SPACE(1), IFNULL(v_AccName,N''));
                SET v_MovementType = CONCAT(N'صُرفت لصالح ', SPACE(1), IFNULL(p_PaidFor,N''), N' هـ/ ', SPACE(1), IFNULL(p_Phone,N''));
             ELSE
                SET v_MovementType  = N'معالجة خطأ في عملية سحب من حساب';
                SET v_MovementType2 = N'معالجة خطأ في عملية سحب من حساب';
            END IF;

              IF v_IsDefault = 1
                 THEN
                  INSERT INTO ExSyAccounts_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note
                        )
                  VALUES
                          (
                            v_UserID, CASE WHEN p_IsUpdate = 0 THEN p_WDVAL ELSE 0.000 END, CASE WHEN p_IsUpdate = 0 THEN 0.000 ELSE p_WDVAL END, NOW(), p_Code, 1, 5, p_OPType, p_BranchID, p_AccIDFrom, p_SafeID, v_MovementType, p_CurrencyFrom, p_Notes, v_MovementType2, p_Notes
                          );
                  INSERT INTO ExSyAccounts_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note
                        )
                  VALUES
                          (
                            v_UserID, CASE WHEN p_IsUpdate = 0 THEN 0.000 ELSE p_WDVAL END, CASE WHEN p_IsUpdate = 0 THEN p_WDVAL ELSE 0.000 END, NOW(), p_Code, 1, 5, p_OPType, p_BranchID,p_SafeID, p_AccIDFrom,  v_MovementType, p_CurrencyFrom, p_Notes, v_MovementType2, p_Notes
                          );
                END IF;
              IF v_IsDefault <> 1
                 THEN


                  SELECT a.EMFtherPRint, a.ACCFPrintCridet INTO v_FAtherPERints, v_ACCFPrintCridet FROM
                          CurrencyMainTb AS a
                  WHERE
                          a.ID = p_CurrencyFrom
 ORDER BY a.ID DESC LIMIT 1;
                  SELECT AccID INTO v_FirstCurrencyd FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = v_FAtherPERints
                          AND a.BranchID = p_BranchID;
                  SELECT AccID INTO v_ACCFPrintCridetACC FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = v_ACCFPrintCridet
                          AND a.BranchID = p_BranchID
                          AND a.AccActive = 1;























































                        INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note,
                          ValType,
                          CountryID
                        )
                  VALUES
                          (
                            v_UserID, CASE WHEN p_IsUpdate=0 then 0.000 ELSE p_WDVAL END,
                    CASE WHEN p_IsUpdate=0 then p_WDVAL ELSE 0.000 END,
                            NOW(), p_Code, 5, 38,  p_BranchID, p_AccIDFrom, 225, v_MovementType, p_CurrencyFrom, p_Notes,
                            v_MovementType2, p_Notes,1,0
                          );

                       INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note,
                          ValType,
                          CountryID
                        )
                  VALUES
                          (
                            v_UserID, CASE WHEN p_IsUpdate=0 then p_WDVAL ELSE 0.000 END,
                    CASE WHEN p_IsUpdate=0 then 0.000 ELSE p_WDVAL END,
                            NOW(), p_Code, 5, 38,  p_BranchID, p_SafeID, 225, v_MovementType, p_CurrencyFrom, p_Notes,
                            v_MovementType2, p_Notes,0,0
                          );

                END IF;
            END IF;
                    IF p_TypeID = 7
             THEN
                        IF p_IsUpdate = 0
             THEN
                SET v_MovementType2  = CONCAT(N'إيداع في حساب', SPACE(1), IFNULL(v_AccName,N''));
                SET v_MovementType = CONCAT(N'دفعت من طرف', SPACE(1), IFNULL(p_PaidFor,N''), N' هـ/ ', SPACE(1), IFNULL(p_Phone,N''));
             ELSE
                SET v_MovementType  = N'معالجة خطأ في عملية إيداع في حساب';
                SET v_MovementType2 = N'معالجة خطأ في عملية إيداع في حساب';
            END IF;

              IF v_IsDefault = 1
                 THEN
                  INSERT INTO ExSyAccounts_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note
                        )
                  VALUES
                          (
                            v_UserID,CASE WHEN p_IsUpdate = 0 THEN 0.000 ELSE p_WDVAL END, CASE WHEN p_IsUpdate = 0 THEN p_WDVAL ELSE 0.000 END,  NOW(), p_Code, 1, 7, 40, p_BranchID, p_AccIDFrom, p_SafeID, v_MovementType, v_CurrDefault, p_Notes, v_MovementType2, p_Notes
                          );
                  INSERT INTO ExSyAccounts_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note
                        )
                  VALUES
                          (
                            v_UserID,CASE WHEN p_IsUpdate = 0 THEN p_WDVAL ELSE 0.000 END, CASE WHEN p_IsUpdate = 0 THEN 0.000 ELSE p_WDVAL END,  NOW(), p_Code, 1, 7, 40, p_BranchID,p_SafeID, p_AccIDFrom,  v_MovementType, v_CurrDefault, p_Notes, v_MovementType2, p_Notes
                          );
                END IF;
              IF v_IsDefault <> 1
                 THEN


                  SELECT a.EMFtherPRint, a.ACCFPrintCridet INTO v_FAtherPERints, v_ACCFPrintCridet FROM
                          CurrencyMainTb AS a
                  WHERE
                          a.ID = p_CurrencyFrom
 ORDER BY a.ID DESC LIMIT 1;
                  SELECT AccID INTO v_FirstCurrencyd FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = v_FAtherPERints
                          AND a.BranchID = p_BranchID;
                  SELECT AccID INTO v_ACCFPrintCridetACC FROM
                          AccountsTb AS a
                  WHERE
                          a.AccParent = v_ACCFPrintCridet
                          AND a.BranchID = p_BranchID
                          AND a.AccActive = 1;






















































                        INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note,
                          ValType,
                          CountryID
                        )
                  VALUES
                          (
                            v_UserID,CASE WHEN p_IsUpdate=0 then p_WDVAL ELSE 0.000 END, CASE WHEN p_IsUpdate=0 then 0.000 ELSE p_WDVAL END,
                            NOW(), p_Code, 7, 40,  p_BranchID, p_AccIDFrom, 225, v_MovementType, p_CurrencyFrom, p_Notes,
                            v_MovementType2, p_Notes,1,0
                          );

                       INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                        (

                          SafeID,
                          Debit,
                          Credit,
                          InsertDate,
                          ISID,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          MovementType,
                          CurrencyID,
                          `Description`,
                          SafeIDMovement,
                          AccSafeActivityTb.Note,
                          ValType,
                          CountryID
                        )
                  VALUES
                          (
                            v_UserID,CASE WHEN p_IsUpdate=0 then 0.000 ELSE p_WDVAL END, CASE WHEN p_IsUpdate=0 then p_WDVAL ELSE 0.000 END,
                            NOW(), p_Code, 7, 40,  p_BranchID, p_SafeID, 225, v_MovementType, p_CurrencyFrom, p_Notes,
                            v_MovementType2, p_Notes,0,0
                          );

                END IF;
            END IF;


IF p_IsUpdate=1
 THEN
	UPDATE EMPORCUSTWITHDRAWALTB SET IsActive=0 WHERE Code=p_Code;
END IF;





      COMMIT;
      SET p_MSG = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.insertdate ASC) AS '#',
			a.Code										  AS 'الرمز',
			a.InsertDate								  AS 'التاريخ',
			c.EMPNAME									  AS 'اسم الموظف',
			CASE 					WHEN a.TypeID = 5 						THEN 						a.WDVAL 					ELSE 					0.000 			END											  AS 'مدين',
			CASE 					WHEN a.TypeID = 7 						THEN 						IFNULL(a.WDVAL, 0.000) 					ELSE 					0.000 			END											  AS 'دائن',
			CASE 					WHEN a.TypeID = 5 						THEN 						'عملية سحب' 					WHEN a.TypeID = 7 						THEN 						'عملية إيداع' 			END											  AS 'نوع العملية',

			Notes										  AS 'الملاحظات'


	FROM
			EMPORCUSTWITHDRAWALTB AS a

		LEFT JOIN
			EmployeeTb AS c
				ON a.EMPID = c.ID
	WHERE
			a.IsActive = 1
			AND

			a.BranchID = p_BranchID
			AND a.InsertDate >= p_D1
			AND a.insertdate <= p_D2
			AND

			(		a.TypeID = 5
					OR a.TypeID = 7)
	ORDER BY
			a.insertdate;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_LOADTODVG`(IN `p_TypeID` TINYINT UNSIGNED, IN `p_BranchID` INT, IN `p_accTIPE` INT)
BEGIN
START TRANSACTION;
  IF p_accTIPE = 1
     THEN
      IF p_TypeID = 5
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  Account_GetParentName(a.EMPID) AS 'نوع الحساب',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
                  INNER JOIN
                  AccountsTb b
                  ON a.EMPID=b.AccID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
      IF p_TypeID = 7
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  Account_GetParentName(a.EMPID) AS 'نوع الحساب',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
                                    INNER JOIN
                  AccountsTb b
                  ON a.EMPID=b.AccID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;

               IF p_TypeID = 41
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.CustName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                 ContractDB.EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                ContractDB.ContractorTb AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
                      IF p_TypeID = 46
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.EMPNAME    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                 ContractDB.EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                ContractDB.EmployeeTb  AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;
IF p_TypeID = 49
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  B.CustName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                 ContractDB.EMPORCUSTWITHDRAWALTB AS A
              INNER JOIN
                ContractDB.SupplierTb   AS B
                  ON A.EMPID = B.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom = 1;
        END IF;

    END IF;

  IF p_accTIPE <> 1
     THEN
      IF p_TypeID = 5

         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  Account_GetParentName(a.EMPID) AS 'نوع الحساب',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
                                    INNER JOIN
                  AccountsTb b
                  ON a.EMPID=b.AccID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;
      IF p_TypeID = 7
         THEN
          SELECT
                  A.Code       AS 'الرمز',
                  A.InsertDate 'التاريخ',
                  Account_GetParentName(a.EMPID) AS 'نوع الحساب',
                  B.AccName    'الاسم',
                  A.WDVAL      'القيمة',
                  A.TypeID,
                  A.BranchID,
                  A.SafeID,
                  c.CuName     AS 'اسم العملة'
          FROM
                  EMPORCUSTWITHDRAWALTB AS A
                                    INNER JOIN
                  AccountsTb b
                  ON a.EMPID=b.AccID
              INNER JOIN
                CurrencyMainTb AS c
                  ON A.CurrencyFrom = c.ID
          WHERE
                  A.BranchID = p_BranchID
                  AND TypeID = p_TypeID
                  AND A.IsActive = 1
                  AND CurrencyFrom <> 1;
        END IF;

    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_LOADTORPTEMPWITHDRAWAL`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_LOADTORPTEMPWITHDRAWAL`(IN `p_TypeID` TINYINT UNSIGNED, IN `p_BranchID` INT)
BEGIN
DECLARE v_NetTotal DECIMAL(15, 3);
DECLARE v_crunseType BIT;


	START TRANSACTION;

	SELECT cmt.IsDefault INTO v_crunseType FROM
			CurrencyMainTb cmt;

	IF (p_TypeID = 5
		OR
		p_TypeID = 7)
		 THEN
			SELECT
					A.Code											  AS 'الرمز',
					A.InsertDate									  'التاريخ',
					B.EMPNAME										  'الحساب',
					A.WDVAL											  'القيمة',
					c.BName											  'الفرع',
					`EMPORCUST_GetAccVal`(F.AccID, v_crunseType) AS 'رصيد الحساب',
					d.AccName										  'الخزنة',
					A.Notes											  'ملاحظة',
					A.BranchID,
					A.SafeID
			FROM
					EMPORCUSTWITHDRAWALTB AS A
				INNER JOIN
					EmployeeTb AS B
						ON A.EMPID = B.ID
				LEFT JOIN
					`CoBranch` AS c
						ON A.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON A.SafeID = d.AccID
				LEFT JOIN
					`AccEmpActivityTb` AS e
						ON A.SafeID = e.SafeID
				LEFT JOIN
					AccountsTb AS F
						ON B.EMPNAME = F.AccName
			WHERE
					A.BranchID = p_BranchID
					AND A.TypeID = p_TypeID;
		END IF;
	IF (p_TypeID = 6
		OR
		p_TypeID = 8)
		 THEN
			SELECT
					A.Code											  AS 'الرمز',
					A.InsertDate									  'التاريخ',
					B.CustName										  'الحساب',
					A.WDVAL											  'القيمة',
					c.BName											  'الفرع',
					`EMPORCUST_GetAccVal`(F.AccID, v_crunseType) AS 'رصيد الحساب',
					d.AccName										  'الخزنة',
					A.Notes											  'ملاحظة',
					A.TypeID,
					A.BranchID,
					A.SafeID
			FROM
					EMPORCUSTWITHDRAWALTB AS A
				INNER JOIN
					CustomersTb AS B
						ON A.EMPID = B.ID
				LEFT JOIN
					`CoBranch` AS c
						ON A.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON A.SafeID = d.AccID
				LEFT JOIN
					`AccEmpActivityTb` AS e
						ON A.SafeID = e.SafeID
				LEFT JOIN
					AccountsTb AS F
						ON B.AccID = F.AccID
			WHERE
					A.BranchID = p_BranchID
					AND A.TypeID = p_TypeID;
		END IF;
	COMMIT;
END //
DELIMITER ;

