DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_SelectByCode`(IN `p_Code` TEXT, IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
START TRANSACTION;

	IF (p_TypeID = 7
		OR
		p_TypeID = 5)
		 THEN
			SELECT
					a.Code,
					a.InsertDate,
					F.AccID												 AS EMPID,
          a.ParentCode,
					a.WDVAL,
					a.SafeID,
					d.AccName,
					a.IsActive,
					a.TypeID,
					a.BranchID,
					c.BName,
					Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
					CASE WHEN b.IsHiddenAccount=0 THEN  CAST(Account_GetAccVal(b.AccID,a.CurrencyFrom,0) AS CHAR) ELSE 'مخفي' END  AS 'رصيد الحساب',
					a.CurrencyFrom,
          a.PaidFor,
          a.IDNo,
          a.Phone
			FROM
					EMPORCUSTWITHDRAWALTB AS a
				LEFT JOIN
					AccountsTb  AS b
						ON a.EMPID = b.AccID
				LEFT JOIN
					AccountsTb AS F
						ON b.AccID = F.AccID
				LEFT JOIN
					`CoBranch` AS c
						ON a.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON a.SafeID = d.AccID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;
	IF (p_TypeID = 8
		OR
		p_TypeID = 6)
		 THEN

			SELECT
					a.Code,
					a.InsertDate,
					b.AccID												 AS EMPID,
					a.WDVAL,
					a.SafeID,
					d.AccName,
					a.IsActive,
					a.TypeID,
					a.BranchID,
					c.BName,
					 Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
					`EMPORCUST_GetAccVal`(F.AccID, a.CurrencyFrom) AS 'رصيد الحساب',
					a.CurrencyFrom,
          a.PaidFor,
          a.IDNo,
          a.Phone
			FROM
					EMPORCUSTWITHDRAWALTB AS a
				LEFT JOIN
					CustomersTb AS b
						ON a.EMPID = b.ID
				LEFT JOIN
					AccountsTb AS F
						ON b.AccID = F.AccID
				LEFT JOIN
					`CoBranch` AS c
						ON a.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON a.SafeID = d.AccID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;

	IF (p_TypeID = 41)
		 THEN

			SELECT
					a.Code,
					a.InsertDate,
					b.AccID												 AS EMPID,
					a.WDVAL,
					a.SafeID,
					d.AccName,
					a.IsActive,
					a.TypeID,
					a.BranchID,
					c.BName,
					 Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
					`EMPORCUST_GetAccVal`(b.AccID, a.CurrencyFrom) AS 'رصيد الحساب',
					a.CurrencyFrom,
          a.PaidFor,
          a.IDNo,
          a.Phone
			FROM
				ContractDB.EMPORCUSTWITHDRAWALTB AS a
				LEFT JOIN
				ContractDB.	ContractorTb  AS b
						ON a.EMPID = b.ID
				LEFT JOIN
					`CoBranch` AS c
						ON a.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON a.SafeID = d.AccID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;

IF (p_TypeID = 46)
		 THEN
			SELECT
					a.Code,
					a.InsertDate,
					F.AccID												 AS EMPID,
					a.WDVAL,
					a.SafeID,
					d.AccName,
					a.IsActive,
					a.TypeID,
					a.BranchID,
					c.BName,
					Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
					`EMPORCUST_GetAccVal`(F.AccID, a.CurrencyFrom) AS 'رصيد الحساب',
					a.CurrencyFrom,
          a.PaidFor,
          a.IDNo,
          a.Phone
			FROM
				ContractDB.	EMPORCUSTWITHDRAWALTB AS a
				LEFT JOIN
					ContractDB.EmployeeTb AS b
						ON a.EMPID = b.ID
				LEFT JOIN
					AccountsTb AS F
						ON b.AccID = F.AccID
				LEFT JOIN
					`CoBranch` AS c
						ON a.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON a.SafeID = d.AccID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;

IF (p_TypeID = 49)
		 THEN
			SELECT
					a.Code,
					a.InsertDate,
					F.AccID												 AS EMPID,
					a.WDVAL,
					a.SafeID,
					d.AccName,
					a.IsActive,
					a.TypeID,
					a.BranchID,
					c.BName,
					Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
					`EMPORCUST_GetAccVal`(F.AccID, a.CurrencyFrom) AS 'رصيد الحساب',
					a.CurrencyFrom,
          a.PaidFor,
          a.IDNo,
          a.Phone
			FROM
				ContractDB.	EMPORCUSTWITHDRAWALTB AS a
				LEFT JOIN
					ContractDB.SupplierTb AS b
						ON a.EMPID = b.ID
				LEFT JOIN
					AccountsTb AS F
						ON b.AccID = F.AccID
				LEFT JOIN
					`CoBranch` AS c
						ON a.BranchID = c.ID
				LEFT JOIN
					`AccountsTb` AS d
						ON a.SafeID = d.AccID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPORCUSTWITHDRAWALTB_Update`;
DELIMITER //
CREATE PROCEDURE `EMPORCUSTWITHDRAWALTB_Update`(IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_EMPID` INT, IN `p_WDVAL` DECIMAL(12,3), IN `p_SafeID` INT, IN `p_IsActive` TINYINT(1), IN `p_TypeID` TINYINT UNSIGNED, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	UPDATE
			EMPORCUSTWITHDRAWALTB
	SET
			Code = p_Code, InsertDate = p_InsertDate, EMPID = p_EMPID, WDVAL = p_WDVAL, SafeID = p_SafeID, IsActive = p_IsActive, TypeID = p_TypeID, BranchID = p_BranchID
	WHERE
		Code = p_Code
		AND TypeID = p_TypeID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExBanksTb_CRUD`;
DELIMITER //
CREATE PROCEDURE `ExBanksTb_CRUD`(IN `p_Action` TINYINT UNSIGNED, IN `p_ID` INT, IN `p_BankName` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_CountryID` INT, IN `p_SALARYYEAR` INT, IN `p_SALARYMONTH` INT)
proc: BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN DECLARE __err_no BIGINT DEFAULT 0; DECLARE __err_msg VARCHAR(512) DEFAULT ''; ROLLBACK; GET DIAGNOSTICS CONDITION 1 __err_no = MYSQL_ERRNO, __err_msg = MESSAGE_TEXT; SELECT __err_no AS ErrorNumber, __err_msg AS ErrorMessage; END;


        IF p_Action = 0
         THEN

            IF EXISTS (SELECT 1
                       FROM ExBanksTb
                       WHERE BankName = p_BankName AND CountryID = p_CountryID)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='هذا البنك موجود بالفعل في نفس الدولة.';
                LEAVE proc;
            END IF;

            INSERT INTO ExBanksTb (BankName, IsActive, CountryID)
            VALUES (p_BankName, IFNULL(p_IsActive, 1), IFNULL(p_CountryID, 0));

            SELECT LAST_INSERT_ID() AS NewBankID;
         ELSEIF  p_Action = 1
         THEN

            IF EXISTS (SELECT 1
                       FROM ExBanksTb
                       WHERE BankName = p_BankName AND CountryID = p_CountryID AND ID <> p_ID)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='بنك بنفس الاسم موجود بالفعل في نفس الدولة.';
                LEAVE proc;
            END IF;

            UPDATE ExBanksTb
            SET BankName  = p_BankName, IsActive  = p_IsActive, CountryID = p_CountryID
            WHERE ID = p_ID;
         ELSEIF  p_Action = 2
         THEN

            DELETE FROM ExBanksTb
            WHERE ID = p_ID;
         ELSEIF  p_Action = 3
         THEN

            SELECT *
            FROM ExBanksTb
            WHERE p_ID IS NULL OR ID = p_ID;
         ELSEIF  p_Action = 4
         THEN

            SELECT ID, BankName, IsActive
            FROM ExBanksTb
            WHERE CountryID = p_CountryID;
         ELSEIF  p_Action = 5
         THEN

            SELECT ID, BankName
            FROM ExBanksTb
            WHERE CountryID = p_CountryID;
         ELSEIF  p_Action = 6
         THEN

            SELECT e.ID, e.BankName
    FROM
            SalaryCalculationTb a
        INNER JOIN
          EmployeeTb b
            ON a.EMPID = b.ID
            INNER JOIN ExBanksTb e
            ON e.ID= b.BankID
              where  a.SALARYEAR = p_SALARYYEAR
            AND a.SALARYMONTH = p_SALARYMONTH
             AND b.BankSalaryCalc=1
            GROUP BY e.ID, e.BankName;

        END IF;



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExBBranchTb_CRUD`;
DELIMITER //
CREATE PROCEDURE `ExBBranchTb_CRUD`(IN `p_Action` TINYINT UNSIGNED, IN `p_ID` INT, IN `p_BankID` INT, IN `p_BranchName` LONGTEXT, IN `p_IsActive` TINYINT(1))
proc: BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN DECLARE __err_no BIGINT DEFAULT 0; DECLARE __err_msg VARCHAR(512) DEFAULT ''; ROLLBACK; GET DIAGNOSTICS CONDITION 1 __err_no = MYSQL_ERRNO, __err_msg = MESSAGE_TEXT; SELECT __err_no AS ErrorNumber, __err_msg AS ErrorMessage; END;


        IF p_Action = 0
         THEN

            IF EXISTS (SELECT 1
                       FROM ExBBranchTb
                       WHERE BranchName = p_BranchName AND BankID = p_BankID)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='هذا الفرع موجود بالفعل لنفس البنك.';
                LEAVE proc;
            END IF;

            INSERT INTO ExBBranchTb (BankID, BranchName,  IsActive)
            VALUES (p_BankID, p_BranchName,  IFNULL(p_IsActive, 1));

            SELECT LAST_INSERT_ID() AS NewBranchID;
         ELSEIF  p_Action = 1
         THEN

            IF EXISTS (SELECT 1
                       FROM ExBBranchTb
                       WHERE BranchName = p_BranchName AND BankID = p_BankID AND ID <> p_ID)
             THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='فرع بنفس الاسم موجود بالفعل لنفس البنك.';
                LEAVE proc;
            END IF;

            UPDATE ExBBranchTb
            SET BankID     = p_BankID, BranchName = p_BranchName, IsActive   = p_IsActive
            WHERE ID = p_ID;
         ELSEIF  p_Action = 2
         THEN

            DELETE FROM ExBBranchTb
            WHERE ID = p_ID;
         ELSEIF  p_Action = 3
         THEN

            SELECT BranchName,BankID,ID,IsActive
            FROM ExBBranchTb
            WHERE p_ID IS NULL OR ID = p_ID;
         ELSEIF  p_Action = 4
         THEN

            SELECT ID, BranchName, IsActive
            FROM ExBBranchTb
            WHERE BankID = p_BankID;
         ELSEIF  p_Action = 5
         THEN

            SELECT ID, BranchName
            FROM ExBBranchTb;
         ELSEIF  p_Action =6
         THEN

            SELECT ID, BranchName
            FROM ExBBranchTb
            WHERE BankID = p_BankID;
        END IF;



END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EXCHANGESYS2024EMPORCUST_LOADINTOLKPBASEDONACCID`;
DELIMITER //
CREATE PROCEDURE `EXCHANGESYS2024EMPORCUST_LOADINTOLKPBASEDONACCID`(IN `p_BranchID` INT, IN `p_TypeID` INT, IN `p_IsUpdate` TINYINT(1), IN `p_crunsfrom` INT, IN `p_UserID` INT)
BEGIN
DECLARE v_Isdefult BIT;
DECLARE v_CanDebit BIT;
DECLARE v_CanShowHACC bit;
START TRANSACTION;

  SELECT a.IsDefault INTO v_Isdefult FROM
          CurrencyMainTb AS a
  WHERE
          a.ID = p_crunsfrom
 ORDER BY a.ID DESC LIMIT 1;

SELECT t.CanShowHACC INTO v_CanShowHACC FROM TB_Users t WHERE t.USID=p_UserID
 ORDER BY t.USID DESC LIMIT 1;

  IF p_IsUpdate = 0
     THEN
      IF p_TypeID = 5
        AND
        v_Isdefult = 1
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST,
                  a.ID      AS ID_LOCK
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
          GROUP BY
                  b.AccID,
                  a.EMPNAME,
                  a.ID
          HAVING
                  `EMPORCUST_GetCurrAccVal`(b.AccID, p_crunsfrom) > 0.000
          ORDER BY
                  a.EMPNAME;
        END IF;

      IF p_TypeID = 5
        AND
        v_Isdefult = 0
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST,
                  a.ID      AS ID_LOCK
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
          GROUP BY
                  b.AccID,
                  a.EMPNAME,
                  a.ID
          HAVING
                  `EMPORCUST_GetCurrAccVal`(b.AccID, p_crunsfrom) > 0.000
          ORDER BY
                  a.EMPNAME;
        END IF;

      IF p_TypeID = 7
         THEN
          SELECT
                  b.AccID,
                  a.EMPNAME AS EMCUST,
                  a.ID      AS ID_LOCK
          FROM
                  EmployeeTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND a.IsActive = 1
          ORDER BY
                  a.EMPNAME;
        END IF;
      IF p_TypeID = 6
         THEN

          SELECT
                  b.AccID,
                  a.CustName AS EMCUST,
                  a.ID       AS ID_LOCK,
                  a.CandDebit
          FROM
                  CustomersTb AS a
              LEFT JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BranchID
                  AND (a.HiddenAccount=0 OR a.HiddenAccount=v_CanShowHACC)
          GROUP BY
                  b.AccID,
                  a.CustName,
                  a.ID,
                  a.CandDebit
