DROP PROCEDURE IF EXISTS `ExchangeSystem_Analyz`;
DELIMITER //
CREATE PROCEDURE `ExchangeSystem_Analyz`(IN `p_BranchID` INT)
BEGIN
DECLARE v_ReCount INT;
DECLARE v_ReCountNotDel INT;
DECLARE v_IntNotConfirmed INT;
DECLARE v_ConfrimCount INT;
DECLARE v_IntIncomeNotDel INT;
DECLARE v_RecordCount INT;
DECLARE v_ConfirmCanceledInternal INT;
DECLARE v_FinishCanceledInternal INT;
DECLARE v_CanceledInteralIncome INT;
DECLARE v_OutcomeDeliveredInEx INT;
DECLARE v_DeliveredCancel INT;
DECLARE v_EditCount INT;
DECLARE v_RecordCountConfirmCancel INT;
DECLARE v_ExtOutcomeNotDelivered INT;
DECLARE v_ExtCanceledConfrimed INT;
DECLARE v_ExternalConfirm INT;
DECLARE v_ExtCONFIRMCANCEL INT;
DECLARE v_LeaveConfirm INT;
DECLARE v_LeaveEnd INT;
DECLARE v_IsMain BIT;
DECLARE v_MainBr INT;
DECLARE v_currD DATETIME DEFAULT NOW();
DECLARE v_CurrD2 DATETIME DEFAULT NOW() - DAY(5);
DECLARE v_TaxiADD int;
DECLARE v_TAxiNotSend int;
DECLARE v_taxiSendFrom int;
DECLARE v_TAxiCansel int;


  SELECT IsMain INTO v_IsMain FROM CoBranch
  WHERE ID = p_BranchID;


  SELECT COALESCE(SUM(CASE WHEN ConfirmType = 0 AND v_IsMain=1 THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 3 OR (ConfirmType = 4 AND IsCanceled = 0) AND v_IsMain=1 THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 1 AND  RecievedDate IS NULL  AND a.BranchRecievedID=p_BranchID AND cb.BranchType<>3 THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 2 AND a.BranchRecievedID=p_BranchID AND InsertDate BETWEEN v_CurrD2 AND v_currD THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 0 AND a.BranchRecievedID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 1 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 4 AND IsCanceled = 1 AND a.BranchRecievedID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 5  AND a.BranchRecievedID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 4 AND IsCanceled = 1 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 2 AND a.BranchDeliveredID=p_BranchID AND InsertDate BETWEEN v_CurrD2 AND v_currD THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 6 AND a.BranchRecievedID=p_BranchID AND InsertDate BETWEEN v_CurrD2 AND v_currD THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN IsEdit = 1 AND a.BranchRecievedID = p_BranchID AND (a.ConfirmType = 0 or a.ConfirmType = 1)  THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 7 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 8 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 9 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN ConfirmType = 10 AND a.BranchDeliveredID=p_BranchID THEN 1 ELSE 0 END), 0) INTO v_ConfrimCount, v_ConfirmCanceledInternal, v_ReCount, v_ReCountNotDel, v_IntNotConfirmed, v_IntIncomeNotDel, v_RecordCount, v_RecordCountConfirmCancel, v_CanceledInteralIncome, v_OutcomeDeliveredInEx, v_DeliveredCancel, v_EditCount, v_TaxiADD, v_TAxiNotSend, v_taxiSendFrom, v_TAxiCansel FROM InternalEx AS a
  LEFT JOIN CoBranch cb
  ON a.BranchDeliveredID=cb.ID
  WHERE a.IsActive = 1;


  SELECT COALESCE(SUM(CASE WHEN                           a.IsCanceled = 0                           AND IsConfirmed = 1                           AND a.IsDelivered = 0                           AND a.BranchDeleviredID = p_BranchID THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN                           a.IsCanceled = 2                           AND (   a.IsConfirmed = 0                                   OR (    a.IsConfirmed = 1                                           AND a.IsInOrOut = 0))                           AND a.IsDelivered = 0                           AND (   (       a.BranchDeleviredID = p_BranchID                                           AND a.IsInOrOut = 1)                                   OR (    a.RecievedBranchID = p_BranchID                                           AND a.IsInOrOut = 0)) THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN IsConfirmed = 0 AND IsDelivered = 0 AND IsCanceled = 0 THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN                             a.IsActive = 1                             AND ((a.ConfirmedType = 3)  OR (a.ConfirmedType = 4))                             AND a.IsCanceled = 1                                                 AND a.RefuseCanceled = 0 THEN 1 ELSE 0 END), 0) INTO v_ExtOutcomeNotDelivered, v_ExtCanceledConfrimed, v_ExternalConfirm, v_ExtCONFIRMCANCEL FROM ExternalEx AS a
  WHERE  a.IsActive = 1;


  SELECT COALESCE(SUM(CASE WHEN IsAccepted = 0 AND IsCalculated = 0 AND EndLeave = 0 THEN 1 ELSE 0 END), 0), COALESCE(SUM(CASE WHEN IsAccepted = 1 AND IsCalculated = 0 AND DateTo < NOW() AND EndLeave = 0 THEN 1 ELSE 0 END), 0) INTO v_LeaveConfirm, v_LeaveEnd FROM LeaveTB AS a
  WHERE a.IsActive = 1;


  SELECT
    v_ReCountNotDel AS ReCountNotDel,
    v_ReCount AS ReCount,
    v_IntNotConfirmed AS IntNotConfirmed,
    v_IntIncomeNotDel AS IntIncomeNotDel,
    v_ConfrimCount AS ConfrimCount,
    v_CanceledInteralIncome AS CanceledInteralIncome,
    v_ConfirmCanceledInternal AS ConfirmCanceledInternal,
    v_RecordCount AS RecordCount,
    v_OutcomeDeliveredInEx AS OutcomeDeliveredInEx,
    v_RecordCountConfirmCancel AS RecordCountConfirmCancel,
    v_DeliveredCancel AS DeliveredCancel,
    v_EditCount AS EditCount,
    v_ExtOutcomeNotDelivered AS ExtOutcomeNotDelivered,
    v_ExtCanceledConfrimed AS ExtCanceledConfrimed,
    v_ExternalConfirm AS ExternalConfirm,
    v_ExtCONFIRMCANCEL AS ExtCONFIRMCANCEL,
    v_LeaveConfirm AS LeaveConfirm,
    v_LeaveEnd AS LeaveEnd ,
	v_TaxiADD as  TaxiADD ,
	v_TAxiNotSend as TAxiNotSend ,
	v_taxiSendFrom as taxiSendFrom ,
	v_TAxiCansel as TAxiCansel;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EXET_GetCurrencyPrice`;
DELIMITER //
CREATE PROCEDURE `EXET_GetCurrencyPrice`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_CountryID` INT, IN `p_BankID` INT, IN `p_AccountType` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;

      SELECT b.CurCode INTO v_CurrencyCode FROM
              CurrencyMainTb AS b
      WHERE
              b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
      SELECT a.CurrencyPower INTO v_CurrencyPower FROM
              NewCurrencyPriceOwnDetailsTb AS a
              INNER JOIN NewCurrencyPricesOwnTb AS b ON a.CPID=b.ID
      WHERE
              a.CurrencyIDFrom = 1
              AND a.CurrencyIDTo = p_CurrencyFrom
              AND b.PriceType=2
              AND b.CountryID=p_CountryID
              AND b.AccountType=p_AccountType;



          IF v_CurrencyPower = 1
             THEN
              SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.CountryID = p_CountryID
                      AND b.PriceType = 2
                      AND b.AccountType=p_AccountType;


              SELECT
                      v_CurrencyBuyPrice;
              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  b.SalePrice AS SalePrice

                          FROM
                                  `NewCurrencyPricesOwnTb` AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON  a.ID =b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                  AND a.CountryID = p_CountryID
                                  AND a.PriceType = 2
                                   AND a.AccountType=p_AccountType

                          UNION

                          SELECT
                                  CASE                                           WHEN CurrencyPower = 0                                             THEN                                             b.BuyPrice * v_CurrencyBuyPrice                                           ELSE                                           v_CurrencyBuyPrice / BuyPrice                                   END AS BuyPrice
                          FROM
                                  `NewCurrencyPricesOwnTb` AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID =b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo <> p_CurrencyFrom
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.CountryID = p_CountryID
                                  AND a.PriceType = 2
                                   AND a.AccountType=p_AccountType) AS x;

              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;

          IF v_CurrencyPower = 0
             THEN
              SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.CountryID = p_CountryID
                      AND b.PriceType = 2
                       AND b.AccountType=p_AccountType;

              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  CASE                                           WHEN CurrencyPower = 1                                             THEN                                             b.SalePrice                                           ELSE                                           1 / SalePrice                                   END AS SalePrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                   ON  a.ID=b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON a.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                   AND a.CountryID = p_CountryID
                                  AND a.PriceType = 2
                                   AND a.AccountType=p_AccountType


                          UNION

                          SELECT
                                  1 / (v_CurrencyBuyPrice * BuyPrice) AS SalePrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                   ON  a.ID=b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                   AND a.CountryID = p_CountryID
                                  AND a.PriceType = 2
                                   AND a.AccountType=p_AccountType) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          SET p_Purchaseprice = EXET_GetSalePrice(p_CurrencyTo, p_CurrencyFrom, p_CountryID,0,p_AccountType);
          SELECT p_Purchaseprice AS Purchaseprice,p_BPrice11 AS BPrice11,v_ValueDev AS ValueDev;
































































































































      SELECT
              p_BPrice11,
              p_Purchaseprice;
      COMMIT;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EXEX_get_NetTotal`;
DELIMITER //
CREATE PROCEDURE `EXEX_get_NetTotal`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_AccountType` INT, IN `p_BranchID` INT, IN `p_CountryID` INT, IN `p_BankID` INT)
BEGIN
DECLARE v_CurrencyPower BIT;
DECLARE v_DefualtCurr INT;
DECLARE v_CurrencyPower1 BIT;
DECLARE v_CurrencyPower2 BIT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;
      SELECT CM.ID INTO v_DefualtCurr FROM
              CurrencyMainTb AS CM
      WHERE
              CM.IsDefault = 1
 ORDER BY CM.ID DESC LIMIT 1;
      IF p_AccountType = 1
         THEN
          SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                  NewCurrencyPriceOwnDetailsTb AS a
              INNER JOIN
                NewCurrencyPricesOwnTb AS b
                  ON a.CPID = b.ID
          WHERE
                  a.CurrencyIDFrom = v_DefualtCurr
                  AND (   a.CurrencyIDTo = p_CurrencyFrom
                          OR a.CurrencyIDTo = p_CurrencyTo)
                  AND b.PriceType = 2
                  AND b.AccountType = p_AccountType
                  AND b.BranchID = p_BranchID
				  AND b.CountryID=p_CountryID
          AND BankID=p_BankID;
        END IF;

      IF (p_AccountType = 0
        OR
        p_AccountType = 3)
         THEN
          SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                  NewCurrencyPriceOwnDetailsTb AS a
              INNER JOIN
                NewCurrencyPricesOwnTb AS b
                  ON a.CPID = b.ID
          WHERE
                  a.CurrencyIDFrom = v_DefualtCurr
                  AND (   a.CurrencyIDTo = p_CurrencyFrom
                          OR a.CurrencyIDTo = p_CurrencyTo)
                  AND b.PriceType = 2
                  AND b.AccountType = p_AccountType
				  AND b.CountryID=p_CountryID
          AND BankID=p_BankID;
        END IF;


      IF v_DefualtCurr = p_CurrencyFrom
         THEN
          SET p_Purchaseprice = `EXEX_Get_TransSaleprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
          IF v_CurrencyPower = 0
             THEN
              SET p_BPrice11 = CAST(p_Purchaseprice * p_BPrice1 AS CHAR);
            END IF;
          IF v_CurrencyPower = 1
             THEN
              SET p_BPrice11 = CAST(p_BPrice1 / p_Purchaseprice AS CHAR);
            END IF;
        END IF;


      IF v_DefualtCurr = p_CurrencyTo
         THEN
          SET p_Purchaseprice = `EXEX_Get_TransBuyprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
          IF v_CurrencyPower = 1
             THEN
              SET p_BPrice11 = CAST(FLOOR((p_Purchaseprice * p_BPrice1)/5)*5 AS CHAR);
            END IF;
          IF v_CurrencyPower = 0
             THEN
              SET p_BPrice11 = CAST(FLOOR((p_BPrice1 / p_Purchaseprice)/5)*5 AS CHAR);
            END IF;
        END IF;


      IF v_DefualtCurr <> p_CurrencyTo
        AND
        v_DefualtCurr <> p_CurrencyFrom
         THEN

          IF p_AccountType = 1
             THEN
              SELECT a.CurrencyPower INTO v_CurrencyPower1 FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = v_DefualtCurr
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = 2
                      AND b.AccountType = p_AccountType
                      AND b.BranchID = p_BranchID
                      AND BankID=p_BankID;
            END IF;

          IF (p_AccountType = 0
            OR
            p_AccountType = 3)
             THEN
              SELECT a.CurrencyPower INTO v_CurrencyPower1 FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = v_DefualtCurr
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = 2
                      AND b.AccountType = p_AccountType
                      AND BankID=p_BankID;
            END IF;

          IF p_AccountType = 1
             THEN
              SELECT a.CurrencyPower INTO v_CurrencyPower2 FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = v_DefualtCurr
                      AND a.CurrencyIDTo = p_CurrencyTo
                      AND b.PriceType = 2
                      AND b.AccountType = p_AccountType
                      AND b.BranchID = p_BranchID
                      AND BankID=p_BankID;
            END IF;

          IF (p_AccountType = 0
            OR
            p_AccountType = 3)
             THEN
              SELECT a.CurrencyPower INTO v_CurrencyPower2 FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = v_DefualtCurr
                      AND a.CurrencyIDTo = p_CurrencyTo
                      AND b.PriceType = 2
                      AND b.AccountType = p_AccountType
                      AND BankID=p_BankID;
            END IF;


          IF v_CurrencyPower1 > v_CurrencyPower2
             THEN

              SET p_Purchaseprice = `EXEX_Get_TransBuyprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
              IF v_CurrencyPower1 = 1
                 THEN
                  SET p_BPrice11 = CAST(p_Purchaseprice * p_BPrice1 AS CHAR);
                END IF;
              IF v_CurrencyPower1 = 0
                 THEN
                  SET p_BPrice11 = CAST(p_BPrice1 / p_Purchaseprice AS CHAR);
                END IF;
            END IF;

          IF v_CurrencyPower2 > v_CurrencyPower1
             THEN

              SET p_Purchaseprice = `EXEX_Get_TransBuyprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
              IF v_CurrencyPower2 = 0
                 THEN
                  SET p_BPrice11 = CAST(p_Purchaseprice * p_BPrice1 AS CHAR);
                END IF;
              IF v_CurrencyPower2 = 1
                 THEN
                  SET p_BPrice11 = CAST(p_BPrice1 / p_Purchaseprice AS CHAR);
                END IF;
            END IF;

          IF v_CurrencyPower1 = v_CurrencyPower2
             THEN

              IF v_CurrencyPower1 = 1
                 THEN

                  SET p_Purchaseprice = `EXEX_Get_TransBuyprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
                  SET p_BPrice11 = CAST(p_Purchaseprice * p_BPrice1 AS CHAR);
                END IF;


              IF v_CurrencyPower1 = 0
                 THEN
                  SET p_Purchaseprice = `EXEX_Get_TransBuyprice`(p_CurrencyFrom, p_CurrencyTo, p_AccountType, p_BranchID,p_CountryID,p_BankID);
                  SET p_BPrice11 = CAST(p_BPrice1 / p_Purchaseprice AS CHAR);
                END IF;
            END IF;

        END IF;


      SELECT
              p_BPrice11,
              p_Purchaseprice;
      COMMIT;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EXEX_LoadBranchsAndOurAccIDIntoLookUpEdit`;
DELIMITER //
CREATE PROCEDURE `EXEX_LoadBranchsAndOurAccIDIntoLookUpEdit`()
BEGIN


		START TRANSACTION;
		SELECT
				ID AS DBRID,
				BName,
				BranchType
		FROM
				CoBranch
		WHERE
				IsActive = 1 AND israted=1
				Union
				Select AccID AS DBRID,AccName as BName,0 as BranchType from `AccountsTb` As ac Where  AccParent=10101201;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_CHECKEXNAME`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_CHECKEXNAME`(IN `p_ExName` VARCHAR(150), IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			ExName
	FROM
			ExpensesTb
	WHERE
			ExpensesTb.ExName = p_ExName
			AND ExpensesTb.BranchID = p_BranchID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_Insert`(IN `p_InsertDate` DATE, IN `p_Code` VARCHAR(50), IN `p_ExName` VARCHAR(150), IN `p_BranchID` INT, IN `p_AccID` BIGINT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_TypeEx` TINYINT UNSIGNED)
BEGIN
DECLARE v_ExAccID BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_fatherparent DECIMAL(18, 0);
DECLARE v_IsExist INT;
DECLARE v_BranchName LONGTEXT;
DECLARE v_OldExName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_acccode DECIMAL(18, 0);
DECLARE v_AccName LONGTEXT;


  START TRANSACTION;
  SELECT cb.BName INTO v_BranchName FROM
          CoBranch cb
  WHERE
          ID = p_BranchID;
  IF p_IsUpdate = 0
     THEN
      INSERT INTO ExpensesTb
            (
              InsertDate,
              Code,
              ExName,
              BranchID,
              IsActive,
              TypeEx
            )
      VALUES
              (
                p_InsertDate, p_Code, p_ExName, p_BranchID, p_IsActive, p_TypeEx
              );
      IF p_TypeEx = 0
         THEN
          SELECT COUNT(*) INTO v_IsExist FROM
                  AccountsTb at
          WHERE
                  at.AccName = p_ExName;
          IF v_IsExist = 0
             THEN
SET v_fatherparent = 30101;
SET v_IDcode = CAST(`AccountTb_GetIDCode`(v_fatherparent, 0) AS CHAR);
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = p_ExName;
              CALL ACCOUNTSTB_insert(v_acccode, v_AccName, 0, v_fatherparent, 0, 0, '', '', '', '', '', 0, 0, 0, 3, v_IDcode);
            END IF;

          SELECT COUNT(*) INTO v_IsExist FROM
                  AccountsTb at
          WHERE
                  at.AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
          IF v_IsExist = 0
             THEN
              SELECT at.AccCode INTO v_fatherparent FROM
                      AccountsTb at
              WHERE
                      at.AccName = p_ExName;
SET v_IDcode = CAST(`AccountTb_GetIDCode`(v_fatherparent, 0) AS CHAR);
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
              CALL ACCOUNTSTB_insert(v_acccode, v_AccName, 1, v_fatherparent, 0, 0, '', '', '', '', '', 0, p_BranchID, 0, 4, v_IDcode);
            END IF;
          SELECT a.AccID INTO v_ExAccID FROM
                  AccountsTb AS a
          WHERE
                  a.AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
          UPDATE
                  ExpensesTb
          SET
                  ExpensesTb.AccID = v_ExAccID
          WHERE
            ExpensesTb.Code = p_Code;
        END IF;
      IF p_TypeEx = 1
         THEN
          SELECT at.AccCode INTO v_fatherparent FROM
                  AccountsTb at
          WHERE
                  at.AccName = CONCAT('أدوات ومواد', SPACE(1), v_BranchName);
          SELECT COUNT(*) INTO v_IsExist FROM
                  AccountsTb at
          WHERE
                  at.AccName = p_ExName
                  AND at.AccParent = v_fatherparent;
          IF v_IsExist = 0
             THEN
SET v_IDcode = CAST(`AccountTb_GetIDCode`(v_fatherparent, 1) AS CHAR);
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
              CALL ACCOUNTSTB_insert(v_acccode, v_AccName, 1, v_fatherparent, 0, 1, '', '', '', '', '', 0, p_BranchID, 0, 4, v_IDcode);
            END IF;
        END IF;
      SELECT
              ID,
              InsertDate,
              Code,
              ExName,
              BranchID,
              AccID,
              IsActive
      FROM
              ExpensesTb
      WHERE
              (ID = LAST_INSERT_ID());
    END IF;
  IF p_IsUpdate = 1
     THEN
    SELECT et.AccID INTO v_ExAccID FROM ExpensesTb et WHERE et.ID=p_Code;
      SELECT et.BranchID INTO v_OldBranchID FROM
              ExpensesTb et
      WHERE
              et.Code = p_Code;
      SELECT et.ExName INTO v_OldExName FROM
              ExpensesTb et
      WHERE
              et.Code = p_Code;
      IF p_TypeEx = 0
       THEN
      IF v_OldExName <> p_ExName AND v_OldBranchID = p_BranchID
         THEN

          UPDATE
                  AccountsTb
          SET
                  AccName = p_ExName
          WHERE
            AccID=AccID;
        END IF;
        END IF;
       IF p_TypeEx = 1
       THEN
               SELECT at.AccCode INTO v_fatherparent FROM
                  AccountsTb at
          WHERE
                  at.AccName = CONCAT('أدوات ومواد', SPACE(1), v_BranchName);
      IF v_OldExName <> p_ExName AND v_OldBranchID = p_BranchID
         THEN

          UPDATE
                  AccountsTb
          SET
                  AccName = p_ExName
          WHERE
            AccID=AccID;
        END IF;
        END IF;
      UPDATE
              ExpensesTb
      SET
              Code = p_Code, ExName = p_ExName, BranchID = p_BranchID, IsActive = p_IsActive
      WHERE
        Code = p_Code;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_Insert1`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_Insert1`(IN `p_ExName` LONGTEXT, IN `p_BranchID` INT, IN `p_AccCode` BIGINT, IN `p_TypeEx` TINYINT UNSIGNED)
BEGIN
DECLARE v_ExAccID BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_fatherparent BIGINT;
DECLARE v_IsExist INT;
DECLARE v_BranchName LONGTEXT;
DECLARE v_OldExName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_acccode1 BIGINT;
DECLARE v_AccName LONGTEXT;
DECLARE v_ExCode LONGTEXT;


  START TRANSACTION;
  SELECT cb.BName INTO v_BranchName FROM
          CoBranch cb
  WHERE
          ID = p_BranchID;
  SELECT CONCAT(p_BranchID, '-', IFNULL(MAX(ID), 1)) INTO v_ExCode FROM
          ExpensesTb et;
  INSERT INTO ExpensesTb
        (
          InsertDate,
          Code,
          ExName,
          BranchID,
          AccID,
          IsActive,
          TypeEx
        )
  VALUES
          (
            NOW(), v_ExCode, p_ExName, p_BranchID, 0, 1, p_TypeEx
          );
  IF p_TypeEx = 0
     THEN
SET v_IDcode = CAST(`AccountTb_GetIDCode`(p_AccCode, 1) AS CHAR);
      IF v_IDcode IS NULL
         THEN
SET v_IDcode = 1;
        END IF;
SET v_acccode1 = CONCAT(CAST(p_AccCode AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
      CALL ACCOUNTSTB_insert(v_acccode1, v_AccName, 1, p_AccCode, 0, 0, '', '', '', '', '', 0, 0, p_BranchID, 4, v_IDcode);
    END IF;
  IF p_TypeEx = 1
     THEN
      SELECT at.AccCode INTO v_fatherparent FROM
              AccountsTb at
      WHERE
              AccParent = p_AccCode
              AND BranchID = p_BranchID;
SET v_IDcode = CAST(`AccountTb_GetIDCode`(v_fatherparent, 1) AS CHAR);
      IF v_IDcode IS NULL
         THEN
SET v_IDcode = 1;
        END IF;
SET v_acccode1 = CONCAT(CAST(v_fatherparent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT(p_ExName, SPACE(1), v_BranchName);
      CALL ACCOUNTSTB_insert(v_acccode1, v_AccName, 1, v_fatherparent, 0, 1, '', '', '', '', '', 0, 0, p_BranchID, 4, v_IDcode);
    END IF;



  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_LOADTODVGBYBRANCH`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_LOADTODVGBYBRANCH`(IN `p_BranchID` INT)
BEGIN
