DROP PROCEDURE IF EXISTS `ExpensesTb_LOADTOLKPBasedOnBranchID`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_LOADTOLKPBasedOnBranchID`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			AccID,
			AccName as ExName
	FROM
			AccountsTb
	WHERE
			AccountsTb.BranchID = p_BranchID
			AND AccountsTb.AccParent Like '30101%'
	ORDER BY
			ExName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_LOADTOLKPBasedOnBranchIDAndAccounts`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_LOADTOLKPBasedOnBranchIDAndAccounts`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			a.AccID,
			a.ExName
	FROM
			ExpensesTb AS a
	WHERE
			a.BranchID = p_BranchID
			AND a.IsActive = 1
	ORDER BY
			ExName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExpensesTb_LOADTOLKPBasedOnExType`;
DELIMITER //
CREATE PROCEDURE `ExpensesTb_LOADTOLKPBasedOnExType`(IN `p_BranchID` INT, IN `p_ExType` TINYINT UNSIGNED)
BEGIN
START TRANSACTION;
  IF p_ExType = 0
     THEN
      SELECT
              AccID,
              AccName
      FROM
              AccountsTb
      WHERE
              LEFT(AccParent, 5) = 30101
              AND BranchID = p_BranchID
              AND LEFT(AccParent, 8) <> 30101011
              AND LEFT(AccParent, 8) <> 30101012
              AND LEFT(AccParent, 8) <> 30101010

      ORDER BY
              AccName;
    END IF;
  IF p_ExType = 1
     THEN
      SELECT
              AccID,
              AccName
      FROM
              AccountsTb
      WHERE
              (       LEFT(AccParent, 6) = 101011
                      OR LEFT(AccParent, 3) = 102)
              AND BranchID = p_BranchID
              AND Accline = 4

      ORDER BY
              AccName;
    END IF;
  COMMIT;
END //
DELIMITER ;

