DELIMITER //
CREATE PROCEDURE `ExpensesTb_Update`(IN `p_Code` VARCHAR(50), IN `p_ExName` VARCHAR(150), IN `p_BranchID` INT, IN `p_IsActive` TINYINT(1))
BEGIN
