DROP PROCEDURE IF EXISTS `ExtarnalEX_ShowALLRecords`;
DELIMITER //
CREATE PROCEDURE `ExtarnalEX_ShowALLRecords`(IN `p_RecievedBranchID` INT, IN `p_UNAME` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN


		START TRANSACTION;

		IF p_RecievedBranchID = 0
			AND
			p_UNAME = 0
			 THEN
				SELECT


						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
						CASE 								WHEN 									a.IsCanceled = 1 									THEN 									'قيد الإلغاء' 									WHEN 									a.IsCanceled = 2 or a.IsCanceled=7 									THEN 									'ملغية' 								WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 0 									THEN 									'غير معتمده'                   	WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 1 									THEN 									'معتمده' 						END				   AS 'الحالة'
				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
				WHERE
						a.InsertDate >= p_D1
						AND a.InsertDate <= p_D2
						AND a.IsActive = 1

				ORDER BY
						a.InsertDate;
			END IF;

		IF p_RecievedBranchID = 0
			AND
			p_UNAME <> 0
			 THEN
				SELECT



						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
						CASE 								WHEN 									a.IsCanceled = 1 									THEN 										'قيد الإلغاء' 									WHEN 									a.IsCanceled = 2 or a.IsCanceled=7 									THEN 									'ملغية' 								WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 0 									THEN 									'غير معتمده'                   	WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 1 									THEN 									'معتمده' 						END				   AS 'الحالة'
				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
				WHERE
						a.SafeRecievedID = p_UNAME
						AND a.IsActive = 1
						AND a.InsertDate >= p_D1
						AND a.InsertDate <= p_D2

				ORDER BY
						a.InsertDate;
			END IF;

		IF p_RecievedBranchID <> 0
			AND
			p_UNAME = 0
			 THEN
				SELECT



						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',

						Case when p_RecievedBranchID=RecievedBranchID then 'صادرة' when p_RecievedBranchID=BranchDeleviredID then 'واردة' END as 'النوع',

						CASE 								WHEN 									a.IsCanceled = 1 									THEN 										'قيد الإلغاء' 									WHEN 								a.IsCanceled = 2 or a.IsCanceled=7 									THEN 									'ملغية' 								WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 0 									THEN 									'غير معتمده'                   	WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 1 									THEN 									'معتمده' 						END				   AS 'الحالة'

				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
				WHERE
						(a.RecievedBranchID = p_RecievedBranchID
						OR a.BranchDeleviredID = p_RecievedBranchID)
						AND a.IsActive = 1
						AND a.InsertDate >= p_D1
						AND a.InsertDate <= p_D2

				ORDER BY
						a.InsertDate;
			END IF;


		IF p_RecievedBranchID <> 0
			AND
			p_UNAME <> 0
			 THEN
				SELECT



						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',

						Case when p_RecievedBranchID=RecievedBranchID then 'صادرة' when p_RecievedBranchID=BranchDeleviredID then 'واردة' END as 'النوع',

						CASE 								WHEN 									a.IsCanceled = 1 									THEN 										'قيد الإلغاء' 									WHEN 								a.IsCanceled = 2 or a.IsCanceled=7 									THEN 									'ملغية' 								WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 0 									THEN 									'غير معتمده'                   	WHEN 									a.IsCanceled = 0 									AND a.IsConfirmed = 1 									THEN 									'معتمده' 						END				   AS 'الحالة'

				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
				WHERE
						(a.RecievedBranchID = p_RecievedBranchID
						OR a.BranchDeleviredID = p_RecievedBranchID)
						AND SafeRecievedID = p_UNAME
						AND a.IsActive = 1
						AND a.InsertDate >= p_D1
						AND a.InsertDate <= p_D2
				ORDER BY
						a.InsertDate;
			END IF;


		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_CheckConfirmed`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_CheckConfirmed`(IN `p_Code` LONGTEXT, INOUT `p_msgIN` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_DSST_SET INT;
DECLARE v_IsDelivered_SET INT;
DECLARE v_IsConfirmed_Set INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL report_error(); SET p_msgIN = 0; END;


    START TRANSACTION;




    SELECT x.IsConfirmed INTO v_IsConfirmed_Set FROM
            (   SELECT
                        IsConfirmed
                FROM
                        ExternalEx_LoadToIssued AS a
                WHERE
                        a.Code = p_Code
                UNION
                SELECT

                        IsConfirmed
                FROM
                        ExternalEx_LoadToIssued AS a
                WHERE
                        a.Code = p_Code) AS X;

    IF v_IsConfirmed_Set > 0
       THEN
        SET p_msgIN = 0;
        SET p_MsgBox = 'تم اعتماد هذه الحوالة مسبقاً';
        ROLLBACK;
        LEAVE proc;
      END IF;
    COMMIT;
    SET p_msgIN = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_GetRequestByIDForCancel`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_GetRequestByIDForCancel`(IN `p_BranchID` INT)
BEGIN





		SELECT
				a.ID,
				a.Code,
				a.BranchDeleviredID AS BDID
		FROM
				ExternalEx AS a
		WHERE
				NOT EXISTS (SELECT
							tcrt.ISID
					FROM
							TransCancelRequestTb tcrt
					WHERE
							tcrt.ISID = a.Code
							AND tcrt.RefusuedRequset = 0)
				AND a.IsActive = 1
				AND IsCanceled = 0
				AND a.IsDelivered = 0
        AND (a.IsConfirmed=0 OR (a.IsConfirmed=1 AND a.IsInOrOut=0))
        AND (a.ConfirmedType=0 OR a.ConfirmedType=1)
        AND a.IsDelivered=0
				AND a.Iscash<>2
        AND a.RecievedBranchID =p_BranchID
		ORDER BY
				Code;

	END //
DELIMITER ;

