DROP PROCEDURE IF EXISTS `ExternalEx_LoadRecordToConfirm`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LoadRecordToConfirm`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;


  SELECT
          a.Code,
          a.SenderName,
          a.Phone1,
          a.Phone2,
          a.SIDNo,
          a.RecievedCurrencyID,
          a.CountryIDFrom,
          a.RecievedBranchID,
          a.RecievedName,
          a.RPhone1,
          a.RPhone2,
          a.CityIDTo,
          a.DeliveredCurrencyID as ID,
          a.CountryIDTo,
          a.TransType,
          a.TransPrice1,
          a.IsPrivateAccount,
		  a.OwnAccNo,
		  a.OwnNatioNum ,
		  a.ServiceType,
          a.IsServiceVal,
          a.ServiceExVal,
          a.BranchDeleviredID,
          a.CurrRecievedVal,
          a.ExVal,
          a.ExtraVal,
          a.NetTotal,
          a.InsertDate,
          a.SafeRecievedID,
          a.Notes,
          a.IsAccFrom,
          a.AccFrom,
          a.IsAccTo,
          a.AccTo,
          a.IsCash,
          a.TransPrice,
          a.BBranchAccID,
          a.BBRANCHID,
          a.BankExVAL,
          a.BankServiceType,
          a.CurrDeliveredVal,
          b.CuName AS RecCurName,
          c.CuName AS DelCurName,
          CASE WHEN tu.USID=55 THEN 'حوالة عن طريق التطبيق' WHEN tu.USID<>55 AND A.IsDelivered=1 THEN CONCAT('تنفيذ الموظف: ', tu.UName, '   ', 'سلمت بواسطة: ', T.UName) ELSE CONCAT('تنفيذ الموظف: ', tu.UName) END AS UnameR,
         case  when ServiceType = 4  then  a.bankidto else  a.CityIDTo  END as  CityIDTo_lode

 FROM
          ExternalEx AS a
          INNER JOIN CurrencyMainTb AS b on a.RecievedCurrencyID=b.ID
          INNER JOIN CurrencyMainTb AS c on a.DeliveredCurrencyID=c.ID
          LEFT JOIN TB_Users tu ON A.SafeRecievedID=tu.USID
          LEFT JOIN TB_Users t ON A.SafeRecievedID=t.USID
          WHERE a.Code=p_Code;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LoadRecordToPrint`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LoadRecordToPrint`(IN `p_Code` LONGTEXT, INOUT `p_SerType` INT)
BEGIN
DECLARE v_IsInOrOUT INT;


  START TRANSACTION;
SELECT a.IsInOrOut INTO v_IsInOrOUT FROM ExternalEx AS a WHERE a.Code=p_Code;
  SELECT COUNT(a.ID) INTO p_SerType FROM
          ExtTraServiceTypeTb AS a
      INNER JOIN
        ExternalEx AS b
          ON a.ID = b.ServiceType
  WHERE
          b.Code = p_Code;

  SELECT
          x.Code             AS 'الرمز',
          x.InsertDate       AS 'التاريخ',
          x.TRTYPE           AS 'نوع الحوالة',
          x.SCName           AS 'بلد الإرسال',
          x.SenderName       AS 'الراسل',
          x.SPhone           AS 'هاتف الراسل',
          x.SIDNo            AS 'هوية الراسل',
          x.DCName           AS 'بلد التسليم',
          x.RecievedName     AS 'المستلم',
          x.RPhone           AS 'هاتف المستلم',
          x.OwnNatioNum     AS 'هوية المستلم',
          FORMAT(x.NetTotal, 3) AS 'قيمة الحوالة',
          FORMAT(x.ExVal, 3) AS 'العمولة',
          x.BName            AS 'من',
          x.CaseStauts       AS 'إلى',
          x.SendStatus       AS 'الحالة',
          x.RecievedBranchID,
          x.ExType           AS 'نوع الدفع',
          x.ServiceName      AS 'نوع الخدمة',
          FORMAT(x.ServiceExVal, 3) AS 'عمولة الخدمة',
          FORMAT(x.ExtraVal, 3) AS 'عمولة إضافية',
          x.SerType,
          FORMAT(x.CurrRecievedVal, 3) AS 'القيمة',
          x.RecCurr          AS 'العملة المستلمة',
          x.DelCurr          AS 'العملة المسلمة',
          FORMAT(x.TransPrice, 3) AS 'سعر التحويل',
          FORMAT(x.CurrDeliveredVal, 3) AS 'قيمة التحويل',
          x.Notes            AS 'ملاحظات'

  FROM
          (   SELECT
                      a.Code,
                      a.InsertDate,
                      CASE                               WHEN a.TransType = 0                                 THEN                                 'حساب خاص'                               WHEN a.TransType = 1                                 THEN                                 'وكيــــــل عــام'                               WHEN a.TransType = 2                                 THEN                                 'وكيل'                                 WHEN a.TransType = 3                                 THEN                                 'فرع'                       END AS TRTYPE,
                      d.CName AS SCName,
                      a.SenderName,
                      CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                      a.SIDNo,
                      e.CName AS DCName,
                      a.RecievedName,
                      CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone,
                      a.OwnNatioNum,
                      a.NetTotal,
                      a.ExVal,
                      b.BName,
                      CASE                                           WHEN (a.BranchDeleviredID <> 0                                               OR a.BranchDeleviredID <> -1)                                             THEN                                             c.BName                                           WHEN (a.BranchDeleviredID = 0                                               OR a.BranchDeleviredID = -1)                                             THEN                                             'خارج المنظومة'                                   END AS CaseStauts,
                      CASE                                           WHEN a.IsCanceled = 2                                             AND a.IsConfirmed = 0                                             THEN                                             'ملغاة'                                   END AS SendStatus,
                      a.RecievedBranchID,
                      CASE                               WHEN a.IsCash = 0                                 THEN                                 'نقدا'                               WHEN a.IsCash = 1                                 THEN                                 'آجل'                               WHEN a.IsCash = 2                                 THEN                                 'خدمات مصرفية'                       END AS ExType,
                      CASE                               WHEN p_SerType > 0                                 THEN                                 f.ServiceName                       END AS ServiceName,
                      CASE                               WHEN p_SerType > 0                                 THEN                                 a.ServiceExVal                       END AS ServiceExVal,
                      a.ExtraVal,
                      p_SerType AS SerType,
                      a.CurrRecievedVal,
                      g.CuName AS RecCurr,
                      h.CuName AS DelCurr,
                      a.TransPrice,
                      a.CurrDeliveredVal,
                      a.Notes

              FROM
                      ExternalEx AS a
                  INNER JOIN
                    CoBranch AS b
                        ON a.RecievedBranchID = b.ID
                  LEFT JOIN
                    CoBranch AS c
                        ON a.BranchDeleviredID = c.ID
                  INNER JOIN
                    CountiresTb AS d
                        ON a.CountryIDFrom = d.ID
                  INNER JOIN
                    CountiresTb AS e
                        ON a.CountryIDTo = e.ID
                  LEFT JOIN
                    ExtTraServiceTypeTb AS f
                        ON a.ServiceType = f.ID
                  INNER JOIN
                    CurrencyMainTb g
                        ON a.RecievedCurrencyID = g.ID
                  INNER JOIN
                    CurrencyMainTb h
                        ON a.DeliveredCurrencyID = h.ID
              WHERE
                      a.Code = p_Code
              UNION
              SELECT
                      a.Code,
                      a.InsertDate,
                      CASE                               WHEN a.TransType = 0                                 THEN                                 'حساب خاص'                               WHEN a.TransType = 1                                 THEN                                 'وكيــــــل عــام'                                 WHEN a.TransType = 3                                 THEN                                 'فرع'                       END AS TRTYPE,
                      d.CName AS SCName,
                      a.SenderName,
                      CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                      a.SIDNo,
                      e.CName AS DCName,
                      a.RecievedName,
                      CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone,
                      a.OwnNatioNum,
                      a.NetTotal,
                      a.ExVal,
                      b.BName,
                      CASE                                           WHEN (a.BranchDeleviredID <> 0                                               OR a.BranchDeleviredID <> -1)                                             THEN                                             c.AccName                                           WHEN (a.BranchDeleviredID = 0                                               OR a.BranchDeleviredID = -1)                                             THEN                                             'خارج المنظومة'                                   END AS CaseStauts,
                      CASE                                           WHEN a.IsCanceled = 2                                             AND a.IsConfirmed = 0                                             THEN                                             'ملغاة'                                   END AS SendStatus,
                      a.RecievedBranchID,
                      CASE                               WHEN a.IsCash = 0                                 THEN                                 'نقدا'                               WHEN a.IsCash = 1                                 THEN                                 'آجل'                               WHEN a.IsCash = 2                                 THEN                                 'خدمات مصرفية'                       END AS ExType,
                      CASE                               WHEN p_SerType > 0                                 THEN                                 f.ServiceName                       END AS ServiceName,
                      CASE                               WHEN p_SerType > 0                                 THEN                                 a.ServiceExVal                       END AS ServiceExVal,
                      a.ExtraVal,
                      p_SerType AS SerType,
                      a.CurrRecievedVal,
                      g.CuName AS RecCurr,
                      h.CuName AS DelCurr,
                      a.TransPrice,
                      a.CurrDeliveredVal,
                      a.Notes
              FROM
                      ExternalEx AS a
                  INNER JOIN
                    CoBranch AS b
                        ON a.RecievedBranchID = b.ID
                  INNER JOIN
                    AccountsTb AS c
                        ON a.RecievedBranchID = c.AccID
                  INNER JOIN
                    CountiresTb AS d
                        ON a.CountryIDFrom = d.ID
                  INNER JOIN
                    CountiresTb AS e
                        ON a.CountryIDTo = e.ID
                  LEFT JOIN
                    ExtTraServiceTypeTb AS f
                        ON a.ServiceType = f.ID
                  INNER JOIN
                    CurrencyMainTb g
                        ON a.RecievedCurrencyID = g.ID
                  INNER JOIN
                    CurrencyMainTb h
                        ON a.DeliveredCurrencyID = h.ID
              WHERE
                      a.Code = p_Code) AS x;




















































  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LoadRecordToPrint1`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LoadRecordToPrint1`(IN `p_Code` LONGTEXT, INOUT `p_SerType` INT)
BEGIN
DECLARE v_IsInOrOUT INT;



  SELECT a.IsInOrOut INTO v_IsInOrOUT FROM
          ExternalEx AS a
  WHERE
          a.Code = p_Code;
  SELECT COUNT(a.ID) INTO p_SerType FROM
          ExtTraServiceTypeTb AS a
      INNER JOIN
        ExternalEx AS b
          ON a.ID = b.ServiceType
  WHERE
          b.Code = p_Code;
  IF v_IsInOrOUT = 0
     THEN
      SELECT
              x.Code                                    AS 'الرمز',
              x.InsertDate                              AS 'التاريخ',
              x.TRTYPE                                  AS 'نوع الحوالة',
              x.SCName                                  AS 'بلد الإرسال',
              x.SenderName                              AS 'الراسل',
              x.SPhone                                  AS 'هاتف الراسل',
              x.SIDNo                                   AS 'هوية الراسل',
              x.DCName                                  AS 'بلد التسليم',
              x.RecievedName                            AS 'المستلم',
              x.RPhone                                  AS 'هاتف المستلم',
              x.OwnNatioNum                             AS 'هوية المستلم',
              FORMAT(x.NetTotal, 3)         AS 'قيمة الحوالة',
              FORMAT(x.ExVal, 3)            AS 'العمولة',
              x.BName                                   AS 'من',
              x.CaseStauts                              AS 'إلى',
              x.SendStatus                              AS 'الحالة',
              x.RecievedBranchID,
              x.ExType                                  AS 'نوع الدفع',
              x.ServiceName                             AS 'نوع الخدمة',
              FORMAT(x.ServiceExVal, 3)     AS 'عمولة الخدمة',
              FORMAT(x.ExtraVal, 3)         AS 'عمولة إضافية',
              x.SerType,
              FORMAT(x.CurrRecievedVal, 3)  AS 'القيمة',
              FORMAT(x.CurrRecievedVal+x.ExVal, 3)  AS 'إجمالي القيمة',
              x.RecCurr                                 AS 'العملة المستلمة',
              x.DelCurr                                 AS 'العملة المسلمة',
              FORMAT(x.TransPrice1, 3)       AS 'سعر التحويل',
              FORMAT(x.CurrDeliveredVal, 3) AS 'قيمة التحويل',
              x.Notes                                   AS 'ملاحظات'
			,  x.OwnNatioNum                            as 'رقم الحساب'
			, x.IsInOrOut
      FROM
              (   SELECT
                          a.Code,
                          a.InsertDate,
                          CASE                                   WHEN a.TransType = 0                                     THEN                                     'حساب خاص'                                   WHEN a.TransType = 1                                     THEN                                     'وكيــــــل عــام'                                   WHEN a.TransType = 2                                     THEN                                     'وكيل'                                   WHEN a.TransType = 3                                     THEN                                     'فرع'                           END AS TRTYPE,
                          d.CName AS SCName,
                          a.SenderName,
                          CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                          a.SIDNo,
                          e.CName AS DCName,
                          a.RecievedName,
                          CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone,
                          a.OwnNatioNum,
                          a.NetTotal,
                          CASE WHEN a.IsCash=2 THEN a.ExVal+a.BankExVAL ELSE a.ExVal END ExVal,
                          a.BankExVAL,
                          b.BName,
						  a.IsInOrOut ,
                          CASE                                               WHEN (a.BranchDeleviredID <> 0                                                   OR a.BranchDeleviredID <> -1)                                                 THEN                                                 c.BName                                               WHEN (a.BranchDeleviredID = 0                                                   OR a.BranchDeleviredID = -1)                                                 THEN                                                 'خارج المنظومة'                                       END AS CaseStauts,
                          CASE                                               WHEN a.IsCanceled = 2                                                 AND a.IsConfirmed = 0                                                 THEN                                                 'ملغاة'                                       END AS SendStatus,
                          a.RecievedBranchID,
                          CASE                                   WHEN a.IsCash = 0                                     THEN                                     'نقدا'                                   WHEN a.IsCash = 1                                     THEN                                     'آجل'                                   WHEN a.IsCash = 2                                     THEN                                     'خدمات مصرفية'                           END AS ExType,
                          CASE                                   WHEN p_SerType > 0                                     THEN                                     f.ServiceName                           END AS ServiceName,
                          CASE                                   WHEN p_SerType > 0                                     THEN                                     a.ServiceExVal                            END AS ServiceExVal,
                          a.ExtraVal,
                          p_SerType AS SerType,
                          a.CurrRecievedVal,
                          g.CuName AS RecCurr,
                          h.CuName AS DelCurr,
                          a.TransPrice1,
                          a.CurrDeliveredVal,
                          a.Notes

                  FROM
                          ExternalEx AS a
                      INNER JOIN
                        CoBranch AS b
                            ON a.RecievedBranchID = b.ID
                      LEFT JOIN
                        CoBranch AS c
                            ON a.BranchDeleviredID = c.ID
                      INNER JOIN
                        CountiresTb AS d
                            ON a.CountryIDFrom = d.ID
                      INNER JOIN
                        CountiresTb AS e
                            ON a.CountryIDTo = e.ID
                      LEFT JOIN
                        ExtTraServiceTypeTb AS f
                            ON a.ServiceType = f.ID
                      INNER JOIN
                        CurrencyMainTb g
                            ON a.RecievedCurrencyID = g.ID
                      INNER JOIN
                        CurrencyMainTb h
                            ON a.DeliveredCurrencyID = h.ID
                  WHERE
                          a.Code = p_Code
                  UNION
                  SELECT
                          a.Code,
                          a.InsertDate,
                          CASE                                   WHEN a.TransType = 0                                     THEN                                     'حساب خاص'                                   WHEN a.TransType = 1                                     THEN                                     'وكيــــــل عــام'                                   WHEN a.TransType = 3                                     THEN                                     'فرع'                           END AS TRTYPE,
                          d.CName AS SCName,
                          a.SenderName,
                          CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                          a.SIDNo,
                          e.CName AS DCName,
                          a.RecievedName,
                          CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone,
                          a.OwnNatioNum,
                          a.NetTotal,
                          CASE WHEN a.IsCash=2 THEN a.ExVal+a.BankExVAL ELSE a.ExVal END ExVal,
                          a.BankExVAL,
                          b.BName,
						  a.IsInOrOut ,
                          CASE                                               WHEN (a.BranchDeleviredID <> 0                                                   OR a.BranchDeleviredID <> -1)                                                 THEN                                                 c.AccName                                               WHEN (a.BranchDeleviredID = 0                                                   OR a.BranchDeleviredID = -1)                                                 THEN                                                 'خارج المنظومة'                                       END AS CaseStauts,
                          CASE                                               WHEN a.IsCanceled = 2                                                 AND a.IsConfirmed = 0                                                 THEN                                                 'ملغاة'                                       END AS SendStatus,
                          a.RecievedBranchID,
                          CASE                                   WHEN a.IsCash = 0                                     THEN                                     'نقدا'                                   WHEN a.IsCash = 1                                     THEN                                     'آجل'                                   WHEN a.IsCash = 2                                     THEN                                     'خدمات مصرفية'                           END AS ExType,
                          CASE                                   WHEN p_SerType > 0                                     THEN                                     f.ServiceName                           END AS ServiceName,
                          CASE                                   WHEN p_SerType > 0                                     THEN                                     a.ServiceExVal                           END AS ServiceExVal,
                          a.ExtraVal,
                          p_SerType AS SerType,
                          a.CurrRecievedVal,
                          g.CuName AS RecCurr,
                          h.CuName AS DelCurr,
                          a.TransPrice1,
                          a.CurrDeliveredVal,
                          a.Notes
                  FROM
                          ExternalEx AS a
                      INNER JOIN
                        CoBranch AS b
                            ON a.RecievedBranchID = b.ID
                      INNER JOIN
                        AccountsTb AS c
                            ON a.RecievedBranchID = c.AccID
                      INNER JOIN
                        CountiresTb AS d
                            ON a.CountryIDFrom = d.ID
                      INNER JOIN
                        CountiresTb AS e
                            ON a.CountryIDTo = e.ID
                      LEFT JOIN
                        ExtTraServiceTypeTb AS f
                            ON a.ServiceType = f.ID
                      INNER JOIN
                        CurrencyMainTb g
                            ON a.RecievedCurrencyID = g.ID
                      INNER JOIN
                        CurrencyMainTb h
                            ON a.DeliveredCurrencyID = h.ID
                  WHERE
                          a.Code = p_Code) AS x;
    END IF;
  IF v_IsInOrOUT = 1
     THEN
      SELECT
              x.Code                                    AS 'الرمز',
              x.InsertDate                              AS 'التاريخ',
              x.TRTYPE                                  AS 'نوع الحوالة',
              x.SCName                                  AS 'بلد الإرسال',
              x.SenderName                              AS 'الراسل',
              x.SPhone                                  AS 'هاتف الراسل',
              x.SIDNo                                   AS 'هوية الراسل',
              x.DCName                                  AS 'بلد التسليم',
              x.RecievedName                            AS 'المستلم',
              x.RPhone                                  AS 'هاتف المستلم',
              x.OwnNatioNum                             AS 'هوية المستلم',
              FORMAT(x.NetTotal, 3)         AS 'قيمة الحوالة',
              FORMAT(x.ExVal, 3)            AS 'العمولة',
              x.BName                                   AS 'من',
              x.CaseStauts                              AS 'إلى',
              x.SendStatus                              AS 'الحالة',
              x.RecievedBranchID,
              x.ExType                                  AS 'نوع الدفع',
              x.ServiceName                             AS 'نوع الخدمة',
              FORMAT(x.ServiceExVal, 3)     AS 'عمولة الخدمة',
              FORMAT(x.ExtraVal, 3)         AS 'عمولة إضافية',
              x.SerType,
              FORMAT(x.CurrRecievedVal, 3)  AS 'القيمة',
              x.RecCurr                                 AS 'العملة المستلمة',
              x.DelCurr                                 AS 'العملة المسلمة',
              FORMAT(x.TransPrice1, 3)       AS 'سعر التحويل',
              FORMAT(x.CurrDeliveredVal, 3) AS 'قيمة التحويل',
              x.Notes                                   AS 'ملاحظات'
			 ,   x.OwnNatioNum                            as 'رقم الحساب'
			, x.IsInOrOut
      FROM
              (   SELECT
                          a.Code,
                          a.InsertDate,
                          CASE                                   WHEN a.TransType = 0                                     THEN                                     'حساب خاص'                                   WHEN a.TransType = 1                                     THEN                                     'وكيــــــل عــام'                                   WHEN a.TransType = 2                                     THEN                                     'وكيل'                                   WHEN a.TransType = 3                                     THEN                                     'فرع'                                   ELSE                                   'تحويل عادي'                           END AS TRTYPE,
                          d.CName AS SCName,
                          a.SenderName,
                          CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                          a.SIDNo,
                          e.CName AS DCName,
                          a.RecievedName,
                          CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone,
                          a.OwnNatioNum,
                          a.NetTotal,
                          a.ExVal,
						  a.IsInOrOut,
                          CASE                                   WHEN a.RecievedBranchID = I.AccID                                     THEN                                     I.AccName                                   WHEN a.RecievedBranchID = b.ID                                     THEN                                     b.BName                           END AS BName,
                          CASE                                               WHEN (a.BranchDeleviredID <> 0                                                   OR a.BranchDeleviredID <> -1)                                                 THEN                                                 c.BName                                               WHEN (a.BranchDeleviredID = 0                                                   OR a.BranchDeleviredID = -1)                                                 THEN                                                 'خارج المنظومة'                                       END AS CaseStauts,
                          CASE                                               WHEN a.IsCanceled = 2                                                 AND a.IsConfirmed = 0                                                 THEN                                                 'ملغاة'                                               WHEN a.IsCanceled = 0                                                 AND a.IsConfirmed = 0                                                 THEN                                                 'حوالة واردة غير معتمدة'                                               WHEN a.IsCanceled = 0                                                 AND a.IsConfirmed = 1                                                 THEN                                                 'حوالة واردة معتمدة'                                       END AS SendStatus,
                          a.RecievedBranchID,
                          CASE                                   WHEN a.IsCash = 0                                     THEN                                     'نقدا'                                   WHEN a.IsCash = 1                                     THEN                                     'آجل'                                   WHEN a.IsCash = 2                                     THEN                                     'خدمات مصرفية'                           END AS ExType,
                          CASE                                   WHEN a.ServiceType > 0                                     THEN                                     f.ServiceName                                   WHEN (a.ServiceType = 0                                       OR a.ServiceType < 0)                                     THEN                                     'لا يوجد'                           END AS ServiceName,
                          CASE                                   WHEN p_SerType > 0                                     THEN                                     a.ServiceExVal                                   ELSE                                   0.000                           END AS ServiceExVal,
                          a.ExtraVal,
                          p_SerType AS SerType,
                          a.CurrRecievedVal,
                          g.CuName AS RecCurr,
                          h.CuName AS DelCurr,
                          a.TransPrice1,
                          a.CurrDeliveredVal,
                          a.Notes

                  FROM
                          ExternalEx AS a
                      LEFT JOIN
                        CoBranch AS b
                            ON a.RecievedBranchID = b.ID
                      LEFT JOIN
                        CoBranch AS c
                            ON a.BranchDeleviredID = c.ID

                      INNER JOIN
                        CountiresTb AS d
                            ON a.CountryIDFrom = d.ID
                      INNER JOIN
                        CountiresTb AS e
                            ON a.CountryIDTo = e.ID
                      LEFT JOIN
                        ExtTraServiceTypeTb AS f
                            ON a.ServiceType = f.ID
                      INNER JOIN
                        CurrencyMainTb g
                            ON a.RecievedCurrencyID = g.ID
                      INNER JOIN
                        CurrencyMainTb h
                            ON a.DeliveredCurrencyID = h.ID
                      LEFT JOIN
                        AccountsTb AS I
                            ON a.RecievedBranchID = I.AccID
                  WHERE
                          a.Code = p_Code) AS x;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LoadToConfirm`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LoadToConfirm`()
BEGIN
START TRANSACTION;
	SELECT
					a.Code,
					a.InsertDate,
					a.SenderName,
					CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
					a.RecievedName,
					a.RPhone1,
					a.RPhone2,
					CASE WHEN a.IsInOrOut=0 Then a.CurrRecievedVal ELSE a.CurrDeliveredVal END AS OverallVal,
					a.ExVal,
					a.RecievedBranchID AS BranchRecievedID,
					a.CountryIDTo AS BranchDeliveredID,
          a.SafeRecievedID AS  UNameLog,
          b.ServiceName AS CANCELSTATUS,
          DATE_FORMAT(InsertTime, '%l:%i%p') AS InsertTime,
        Case When  a.CityIDTo=0 Then a.BankIDTo Else a.CityIDTo END AS CityIDTo
			FROM
					ExternalEx AS a
         LEFT JOIN
         ExtTraServiceTypeTb AS b
         ON a.ServiceType=b.ID
			WHERE
					a.IsActive = 1
					AND IsDelivered = 0
					AND IsConfirmed = 0
					AND IsCanceled = 0;
COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LOADTOCONFIRMCANCEL`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LOADTOCONFIRMCANCEL`()
BEGIN
DECLARE v_BRD INT;
    SELECT BranchDeleviredID INTO v_BRD FROM
            ExternalEx;



            SELECT
                            a.Code,
                            a.InsertDate,
                            a.SenderName,
                            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
                            a.RecievedName,
                            CONCAT(a.RPhone1, '-', a.RPhone2) AS RPhone1,
                            a.CurrRecievedVal AS OverallVal,
                            a.ExVal,
                            '' as DeliveryPlace,
                            a.RecievedBranchID AS BranchRecievedID,
                            a.IsDelivered,
                            b.SafeID AS UNameLog,
                            CASE WHEN a.IsConfirmed=0 Then   'غير معتمدة'ELSE 'معتمدة' END CANCELSTATUS,
                             CASE WHEN a.IsConfirmed=0 THEN a.CountryIDTo ELSE  a.BranchDeleviredID END AS BranchDeliveredID

                    FROM
                            ExternalEx_LoadToIssued AS a
                        INNER JOIN
                          TransCancelRequestTb_LoadToIssued AS b
                              ON a.Code = b.ISID
                    WHERE
                            a.IsActive = 1
                            AND (a.IsConfirmed = 0 OR (a.IsConfirmed=1 AND a.IsInOrOut=0))
                            AND a.IsCanceled = 1
                            AND a.RefuseCanceled = 0;































































































  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LODEforEX`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LODEforEX`(IN `p_BranchDeleviredID` INT, IN `p_DT1` DATE, IN `p_DT2` DATE, IN `p_BrnchID` INT)
BEGIN
select a.code ,a.SenderName , a.phone1  as Phone , a.RecievedName , a.RPhone1 as RPhone
,CurrRecievedVal , a.TransPrice , a.CurrDeliveredVal ,a.NewTrancPrice
,case when ConfirmedType  = 0   and a.IsCanceled = 0  then  'غير معتمدة'   when  ConfirmedType  = 1   and a.IsCanceled = 0   then 'معتمدة' else 'ملغية 'END
as ConfirmedType  ,
a.IsCanceled , BranchDeleviredID ,a.ConfirmedType ,  b.BName ,
 a.ISChickFor_Watssapp as ISChickFor_Watssapp
from ExternalEx as a
inner join CoBranch as b on a.RecievedBranchID  = b.ID

where ( a.BranchDeleviredID = p_BranchDeleviredID  or p_BranchDeleviredID = 0 )
and a.InsertDate between p_DT1 and p_DT2
and  (  RecievedBranchID = p_BrnchID or  p_BrnchID = 0 );
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_LODEforSendWhats`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_LODEforSendWhats`(IN `p_BranchID` INT)
BEGIN
DECLARE v_currD DATE DEFAULT DATE_ADD(CAST(NOW() AS date), INTERVAL 1 DAY);
DECLARE v_CurrD2 DATE DEFAULT NOW() - DAY(30);


  SELECT
          a.Code,
          a.InsertDate,
          a.SenderName,
          a.Phone1           AS Phone,
          a.RecievedName,
          a.RPhone1          AS RPhone,
          CurrRecievedVal,
          a.TransPrice,
          a.NewFinalTotal AS CurrDeliveredVal,
          a.NewTrancPrice,
          b.CuName,
          CASE                   WHEN ConfirmedType = 0                     AND a.IsCanceled = 0                     THEN                     'غير معتمدة'                    WHEN ConfirmedType = 1                     AND a.IsCanceled = 0                     THEN                     'معتمدة'                   ELSE                   'ملغية '           END
          AS ConfirmedType,
          c.IDGroup,
          d.ServiceName,
          e.CityName
  FROM
          ExternalEx AS a
      INNER JOIN
        CurrencyMainTb AS b
          ON a.DeliveredCurrencyID = b.ID
      INNER JOIN
        whtsappGRoup AS c
          ON a.RecievedBranchID = c.Branchid
      INNER JOIN
        ExtTraServiceTypeTb AS d
          ON a.ServiceType = d.ID
      INNER JOIN
        CitiesTb e
          ON a.CityIDTo = e.ID
  WHERE
          (       a.RecievedBranchID = p_BranchID
                  OR a.BranchDeleviredID = p_BranchID)
          AND a.InsertDate BETWEEN v_CurrD2 AND v_currD
          ORDER BY InsertDate;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_MaxID`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_MaxID`(IN `p_typID` INT, IN `p_BranchID` INT, IN `p_USRID` INT, IN `p_CountryID` INT, IN `p_CityID` INT)
BEGIN
DECLARE v_Code LONGTEXT;
SET v_Code = CONCAT(CAST(p_CountryID AS CHAR), CAST(p_CityID AS CHAR), CAST(p_BranchID AS CHAR), CAST(p_typID AS CHAR), '-', CAST(p_USRID AS CHAR), '-', CAST(ExternalEx_GetMaxIDCode() AS CHAR));
	SELECT
			v_Code						  AS Code,
			ExternalEx_GetMaxIDCode() AS ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_SendForWatsapp`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_SendForWatsapp`(IN `p_code` LONGTEXT)
BEGIN
select a.code , b.ServiceName  , a.IsPrivateAccount , case when   IsPrivateAccount = 1   and ServiceType <> 1 then  c.BankName  when IsPrivateAccount = 1 and a.ServiceType =  1 then   'ايداع بريدي'  else d.CityName END  as  CityName  ,OwnNatioNum ,a.RPhone1 ,a.CurrRecievedVal ,TransPrice , CASE WHEN  b.ServiceName = 'تسليم باليد'THEN d.CityName ELSE '' END CityName2
,CurrDeliveredVal ,ServiceExVal ,NetTotal ,
case when a.IsInOrOut = 0  then 'حوالة خارجية صادرة ' else 'لديك أمانه من' END as IsInOrOut  ,OwnAccNo ,a.NewTrancPrice
, a.NewFinalTotal ,NewCurrRecievedVal AS NewCurrDeliveredVal ,a.Phone1 ,a.SenderName ,e.BName  ,e.Mobile1 as  BranchDeliveredIDPhone ,f.IDGroup  , g.Mobile1 ,a.RecievedName  ,h.CuName as RecievedCurrencyID
, i.CuName as DeliveredCurrencyID
from ExternalEx a
left join
ExtTraServiceTypeTb b on a.ServiceType=b.ID
left join BanksTb as c on a.BankIDTo =c.ID
left join  CitiesTb as d on a.CityIDTo  = d.ID
left join CoBranch as e on a.BranchDeleviredID = e.ID
left join whtsappGRoup as f on e.ID = f.Branchid
left join CoBranch as g on a.RecievedBranchID = g.ID
inner join CurrencyMainTb as h on a.RecievedCurrencyID = h.ID
inner  join CurrencyMainTb as i on a.DeliveredCurrencyID = i.ID
where  a.Code = p_code;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExternalEx_ShowRecords`;
DELIMITER //
CREATE PROCEDURE `ExternalEx_ShowRecords`()
BEGIN
DECLARE v_BranchID INT;


		START TRANSACTION;
		SELECT b.ID INTO v_BranchID FROM
				InternalEx AS a
			LEFT OUTER JOIN
				CoBranch AS b
					ON a.BranchRecievedID = b.ID
		WHERE
				b.IsMain = 1;


				SELECT
						ROW_NUMBER() OVER (
						ORDER BY a.Code ASC)	  AS '#',
						a.Code					  AS 'الرمز',
						a.InsertDate			  AS 'التاريخ',
						a.SenderName			  AS 'الراسل',
						CONCAT(a.Phone1, '-', Phone2) AS 'هاتف الراسل',
						a.RecievedName			  AS 'المستلم',
						CONCAT(a.RPhone1, '-', RPhone2) AS 'هاتف المستلم',
						a.CurrRecievedVal			  AS 'القيمة',
						a.ExVal					  AS 'العمولة',
						b.BName					  AS 'مكان التسليم',
            a.NetTotal        AS 'القيمة المقابلة'
				FROM
						ExternalEx  AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
				WHERE
						 a.IsActive = 1
						AND a.IsCanceled = 0
						AND a.IsDelivered = 1
            AND a.IsConfirmed = 1
            AND a.IsInOrOut=0
				ORDER BY
						a.InsertDate;


































		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EXTERNALTRANS_CATEGORYTYPESTB`;
DELIMITER //
CREATE PROCEDURE `EXTERNALTRANS_CATEGORYTYPESTB`(IN `p_TransVal` DECIMAL(15,3), IN `p_CountryID` INT, IN `p_TransID` INT)
BEGIN
SELECT
			CASE 					WHEN C.TransType = 0 						THEN 						p_TransVal - C.DisVal 					WHEN C.TransType = 1 						THEN  						p_TransVal - p_TransVal * C.DisVal / 100  			END
	FROM
			`CATEGORYTYPESTB` AS a
		LEFT OUTER JOIN
			CATEGORYTYPESDETAILSTB AS C
				ON a.ID = C.CATID
	WHERE
			a.IsActive = 1
			AND C.ValFrom <= p_TransVal
			AND C.ValTo >= p_TransVal
			AND a.CountryID = p_CountryID
			AND a.TransID = p_TransID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExtTraServiceTypeTb_Insert`;
DELIMITER //
CREATE PROCEDURE `ExtTraServiceTypeTb_Insert`(IN `p_ID` INT, IN `p_ServiceName` VARCHAR(50), IN `p_CountryID` INT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_DisConstant` DECIMAL(12,3), IN `p_MaxValue` DECIMAL(24,3), IN `p_MaxSerValue` DECIMAL(12,3))
BEGIN
START TRANSACTION;

	IF p_IsUpdate = 0
		 THEN
			INSERT INTO  ExtTraServiceTypeTb
					(
						ServiceName,
						CountryID,
						IsActive,
            DisConstant,
			`MaxValue`,
			MaxSerVal
					)
				SELECT
						p_ServiceName,
						p_CountryID,
						1,
            p_DisConstant,
			p_MaxValue,
			p_MaxSerValue;
		END IF;

	IF p_IsUpdate = 1
		 THEN
			UPDATE
					ExtTraServiceTypeTb
			SET
					ServiceName = p_ServiceName, CountryID = p_CountryID, IsActive = p_IsActive, DisConstant=p_DisConstant,
		  `MaxValue`=p_MaxValue,
		  MaxSerVal=p_MaxSerValue
			WHERE
				ID = p_ID;
		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExtTraServiceTypeTb_LoadBaseOnCountryID`;
DELIMITER //
CREATE PROCEDURE `ExtTraServiceTypeTb_LoadBaseOnCountryID`(IN `p_CountryID` INT)
BEGIN
START TRANSACTION;

  SELECT
          ID AS DBRID,
          ServiceName as BName
  FROM
          ExtTraServiceTypeTb
  WHERE
          CountryID = p_CountryID
          AND IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExtTraServiceTypeTb_LoadRateToDVG`;
DELIMITER //
CREATE PROCEDURE `ExtTraServiceTypeTb_LoadRateToDVG`(IN `p_ServiceID` INT)
BEGIN
START TRANSACTION;

  SELECT
ID,
CATID,
ValFrom,
ValTo,
DisVal,
RateType AS RType,
Case When RateType=0 Then 'قيمة' When RateType=1 Then 'نسبة مئوية' END as  RateType
  FROM
          CATEGORYTYPESDETAILSTB
  WHERE
          CATID = p_ServiceID;


  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExtTraServiceTypeTb_LoadToLSBOX`;
