    SELECT ID, ServiceName
    FROM   ExtTraServiceTypeTb;
    COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ExtTraServiceTypeTb_SelectAllByID`;
DELIMITER //
CREATE PROCEDURE `ExtTraServiceTypeTb_SelectAllByID`(IN `p_ID` INT)
BEGIN
START TRANSACTION;

    SELECT ID, ServiceName, CountryID, IsActive,DisConstant,`MaxValue`,MaxSerVal
    FROM   ExtTraServiceTypeTb
    WHERE  ID = p_ID;
    COMMIT;
