DROP PROCEDURE IF EXISTS `FatherExpensesTb_Insert`;
DELIMITER //
CREATE PROCEDURE `FatherExpensesTb_Insert`(IN `p_AccName` LONGTEXT)
BEGIN
DECLARE v_IDcode BIGINT;
DECLARE v_acccode BIGINT;
START TRANSACTION;

SET v_IDcode = CAST(`AccountTb_GetIDCode`(30101, 0) AS CHAR);
              IF v_IDcode IS NULL
                 THEN
SET v_IDcode = 1;
                END IF;
SET v_acccode = CONCAT(CAST(30101 AS CHAR), '0', CAST(v_IDcode AS CHAR));
INSERT INTO AccountsTb
  (
    AccCode,
    AccName,
    AccType,
    Accline,
    AccParent,
    AccDmType,
    AccFinal,
    AccPhone,
    AccMobile,
    AccEmail,
    AccAddress,
    AccNotes,
    AccMaxLimit,
    AccMaxDuration,
    BranchID,
    AddDate,
    AccActive,
    IDcode
  )
VALUES
        (
           v_acccode, p_AccName, 0, 3, 30101, 0, 0, '', '', '', '', '', 0, 0, 0,  NOW(),  1, v_IDcode
        );



















  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `FatherExpensesTb_LOADTOLKPBasedOnExType`;
DELIMITER //
CREATE PROCEDURE `FatherExpensesTb_LOADTOLKPBasedOnExType`(IN `p_ExType` TINYINT UNSIGNED, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;


  IF p_ExType = 0
     THEN

SELECT
              a.AccCode,
             a. AccName
      FROM
              AccountsTb a

      WHERE
                    a.AccParent=30101
			  AND a.Accline = 3
AND  a.BranchID =0
AND NOT EXISTS (
SELECT at.acccode
  FROM AccountsTb at
  WHERE a.AccCode=at.AccParent AND at.BranchID=p_BranchID);

















    END IF;
  IF p_ExType = 1
     THEN
      SELECT
              AccCode,
              AccName
      FROM
              AccountsTb
      WHERE
	  AccCode=101011
	  or AccParent=102

      ORDER BY
              AccCode;
    END IF;
  COMMIT;
END //
DELIMITER ;

