DROP PROCEDURE IF EXISTS `Favorites_GetByUserID`;
DELIMITER //
CREATE PROCEDURE `Favorites_GetByUserID`(IN `p_UEserID` INT)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;
START TRANSACTION;




    DROP TEMPORARY TABLE IF EXISTS tmp_Favorites_TempResult; CREATE TEMPORARY TABLE tmp_Favorites_TempResult (
        Name_to VARCHAR(255),
        ID INT,
        insertdate DATE,
        time_insert TIME(6),
        UEserID INT,
        OverallVal DECIMAL(18,3),
        ExVal DECIMAL(18,3),
        RPhone1 VARCHAR(50),
        Type_Favorite INT ,
		CODE LONGTEXT
    );


    INSERT INTO tmp_Favorites_TempResult
    SELECT
        a.RecievedName,
        b.ID,
        b.insertdate,
        b.time_insert,
        c.id AS UEserID,
        a.OverallVal,
        a.ExVal,
        a.RPhone1,
        b.Type_Favorite
		,a.Code
    FROM InternalEx a
    INNER JOIN Favorites_Table b ON a.Code = b.code_Favorite
    INNER JOIN users c ON b.UEserID = c.id
    WHERE c.id = p_UEserID;


    INSERT INTO tmp_Favorites_TempResult
    SELECT
        a.RecievedName,
        b.ID,
        b.insertdate,
        b.time_insert,
        c.id AS UEserID,
        a.CurrRecievedVal AS OverallVal,
        a.ExVal,
        a.RPhone1,
        b.Type_Favorite
		,a.Code
    FROM ExternalEx a
    INNER JOIN Favorites_Table b ON a.Code = b.code_Favorite
    INNER JOIN users c ON b.UEserID = c.id
    WHERE c.id = p_UEserID;


    INSERT INTO tmp_Favorites_TempResult
    SELECT
        g.AccName,
        b.ID,
        b.insertdate,
        b.time_insert,
        c.id AS UEserID,
        a.TransValue,
        0 AS ExVal,
        g.AccPhone,
        b.Type_Favorite
		,a.Code
    FROM TransBetweenAccountsTB a
    INNER JOIN Favorites_Table b ON a.Code = b.code_Favorite
    INNER JOIN AccountsTb g ON a.TransTo = g.AccID
    INNER JOIN users c ON b.UEserID = c.id
    WHERE c.id = p_UEserID;


    SELECT * FROM tmp_Favorites_TempResult;



	commit;



END //
DELIMITER ;

