DROP PROCEDURE IF EXISTS `FrmScreensTb_selectITimsFormMovent_UeserID_insert`;
DELIMITER //
CREATE PROCEDURE `FrmScreensTb_selectITimsFormMovent_UeserID_insert`(IN `p_FrmScreensTb_ID` INT, IN `p_ColmenValue` INT, IN `p_AccfillValue` INT, IN `p_UeserID` INT, IN `p_UeserInsert` INT, INOUT `p_SMG` INT, INOUT `p_msgBox` LONGTEXT)
proc: BEGIN
DECLARE v_ColmenValue_select bigint;
DECLARE v_ACCvalueTO bigint;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); set p_SMG  =0; END;
 START TRANSACTION;


     if p_ColmenValue = 1
   THEN
   if p_AccfillValue<> 0

  THEN

 SELECT AccfillValue INTO v_ColmenValue_select FROM  `FrmScreensTb_selectITimsFormMovent_UeserID`
 where `UeserID` = p_UeserID and AccfillValue= p_AccfillValue and FrmScreensTb_ID =p_FrmScreensTb_ID and `ColmenValue`= p_ColmenValue;




  if v_ColmenValue_select  =  p_AccfillValue
   THEN
  set p_SMG  = 0;
  set p_msgBox = CONCAT('عذرا هذه الفرع مضاف مسبقا الرجاء التاكد من الفرع', CAST(p_ColmenValue AS CHAR), CAST(v_ColmenValue_select AS CHAR));
  rollback;
  LEAVE proc;
  END IF;

  SELECT AccfillValue INTO v_ACCvalueTO FROM   `FrmScreensTb_selectITimsFormMovent_UeserID`   as a
 where `UeserID` = p_UeserID  and   a.ColmenValue = p_ColmenValue and AccfillValue = 0;

 if v_ACCvalueTO = 0
  THEN
 set p_SMG  = 0;
  set p_msgBox = 'عذرا لايمكن اضافة فرع لهذا المستخدم لانه لدية كل الفروع ';
  rollback;
    LEAVE proc;
 END IF;


 END IF;

 if p_AccfillValue = 0
  THEN
 DELETE FROM `FrmScreensTb_selectITimsFormMovent_UeserID` where UeserID =   p_UeserID   and FrmScreensTb_ID = p_FrmScreensTb_ID and  ColmenValue = p_ColmenValue;
 END IF;
 END IF;




  if p_ColmenValue =  2
   THEN
  SELECT AccfillValue INTO v_ColmenValue_select FROM  `FrmScreensTb_selectITimsFormMovent_UeserID`
 where `UeserID` = p_UeserID and AccfillValue= p_AccfillValue and FrmScreensTb_ID =p_FrmScreensTb_ID;



 if v_ColmenValue_select  =  p_AccfillValue
   THEN
  set p_SMG  = 0;
  set p_msgBox = CONCAT('عذرا عرض اقفال الخزينة مضاف مسبقا ', CAST(p_ColmenValue AS CHAR), CAST(v_ColmenValue_select AS CHAR));
  rollback;
  LEAVE proc;
  END IF;
 END IF;

INSERT INTO `FrmScreensTb_selectITimsFormMovent_UeserID`
           (`FrmScreensTb_ID`
           ,`ColmenValue`
           ,`AccfillValue`
           ,`UeserID`


           ,`UeserInsert`)
     VALUES
           (p_FrmScreensTb_ID ,
		   p_ColmenValue ,
		   p_AccfillValue ,
		   p_UeserID  ,

		   p_UeserInsert
		   );
commit;
set p_SMG  =1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `FrmScreensTb2_insert`;
DELIMITER //
CREATE PROCEDURE `FrmScreensTb2_insert`(IN `p_ScreenName` LONGTEXT, IN `p_MainScreenID` INT, IN `p_EnglishName` LONGTEXT, IN `p_ShortName` VARCHAR(50), INOUT `p_smg` INT, INOUT `p_msg` LONGTEXT, IN `p_GRoup_ID` INT, IN `p_ScreenID` INT)
proc: BEGIN
DECLARE v_ID int;
DECLARE v_maxID bigint;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); set p_smg = 0; END;
START TRANSACTION;




SELECT a.ScreenID INTO v_ID FROM `FrmScreensTb2` as a  where a.ScreenName = p_ScreenName;
 if v_ID is not null
  THEN
 set p_smg =0;
 set p_msg = 'عذرا اسم هذا الشاشة موجود مسبقا';
 rollback;
 LEAVE proc;

 END IF;


SELECT a.ScreenID INTO v_ID FROM `FrmScreensTb2` as a  where a.ScreenName = p_EnglishName;
 if v_ID is not null
  THEN
 set p_smg =0;
 set p_msg = 'عذرا اسم  الانلجليوي لهذا الشاشة موجود مسبقا';
 rollback;
 LEAVE proc;

 END IF;



SELECT a.ScreenID INTO v_ID FROM `FrmScreensTb2` as a  where a.ScreenName = p_ShortName;
 if v_ID is not null
  THEN
 set p_smg =0;
 set p_msg = '`عذرا الاختصار لهذه الشاشة موجود مسبقاً';
 rollback;
 LEAVE proc;

 END IF;


INSERT INTO `FrmScreensTb2`
           (`ScreenName`
           ,`MainScreenID`
           ,`EnglishName`
           ,`CanShow`
           ,`CanSave`
           ,`CanEdit`
           ,`CanDelete`
           ,`CanSearch`
           ,`CanPrint`
           ,`ShortName`
		   ,GRoup_ID
		   ,ScreenID)
     VALUES(
	 p_ScreenName ,
	 p_MainScreenID ,
	 p_EnglishName ,
	 1,
	 1,
	 1
	 ,1
	 ,1
	 ,1
	 ,p_ShortName
	, p_GRoup_ID
	,p_ScreenID
	 );


SELECT max(a.ScreenID) INTO v_maxID FROM FrmScreensTb2 as a;
insert into UserAccessProfileTemplate
(a.ProfileID ,MainID, ScreenID , `CanShow` , CanSave ,CanEdit , CanDelete, CanSearch ,CanPrint,GRoup_ID  )
select a.ProfID ,p_MainScreenID , v_maxID  ,
case  when a.ProfID = 1 then  0 else 0  END  as `CanShow`
, case  when a.ProfID = 1 then  1 else 0  END  as CanSave

 , case  when a.ProfID = 1 then  1 else 0  END  as CanEdit
, case  when a.ProfID = 1 then  1 else 0  END  as CanDelete
, case  when a.ProfID = 1 then  1 else 0  END  as CanSearch
, case  when a.ProfID = 1 then  1 else 0  END  as CanPrint
,p_GRoup_ID
from ProfileName as a;

insert into UserAccessProfileTemplate_ID (ProfileID ,MainID ,ScreenID ,CanShow ,CanSave,CanEdit ,CanDelete, CanSearch,
CanPrint ,  UserID ,Group_ID    )
select a.UserType ,MainScreenID , v_maxID  ,
case  when a.UserType = 1 then  0 else 0  END  as `CanShow`
, case  when a.UserType = 1 then  1 else 0  END  as CanSave

 , case  when a.UserType = 1 then  1 else 0  END  as CanEdit
, case  when a.UserType = 1 then  1 else 0  END  as CanDelete
, case  when a.UserType = 1 then  1 else 0  END  as CanSearch
, case  when a.UserType = 1 then  1 else 0  END  as CanPrint ,
a.USID ,

p_GRoup_ID

from TB_Users as a inner join
ProfileName as b on a.UserType = b.ProfID
inner join UserROOLMAINPROFILETP_ID   as c on c.profid  =  b.ProfID
inner join FrmScreensTb2 as d on c.MainID = d.MainScreenID
inner join  UserAccessProfileTemplate as e on a.UserType  = e.ProfileID and e. MainID = MainScreenID
inner join UserAccessProfileTemplate_ID  as f on a.UserType = f.ProfileID and a.USID =f.UserID
and  MainScreenID  =e.MainID
where a.IsActive =1
and d.ScreenID =v_maxID
group by a.UserType   ,a.UserType  ,a.USID ,MainScreenID;

commit;
set p_smg =1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `get_BracuNetBurnnc`;
DELIMITER //
CREATE PROCEDURE `get_BracuNetBurnnc`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

			START TRANSACTION;

			SELECT b.CurCode INTO v_CurrencyCode FROM
					CurrencyMainTb AS b
			WHERE
					b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
			SELECT a.CurrencyPower INTO v_CurrencyPower FROM
					CurrencyPriceDetailsTb AS a
			WHERE
					a.CurrencyIDFrom = 1
					AND a.CurrencyIDTo = p_CurrencyFrom;
			IF p_ISbaunk = 0
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BuyPrice AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.SalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / SalePrice 												END AS BuyPrice



										FROM
												`CurrencyPricesTb` AS a


											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;



							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;

					IF v_CurrencyPower = 0
						 THEN
							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT


												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BuyPrice 														ELSE 														1 / BuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * SalePrice) AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a


											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					SET p_Purchaseprice = Get_Purchaseprice(p_CurrencyTo, p_CurrencyFrom, p_ISbaunk);
				END IF;


			IF p_ISbaunk = 1
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BankBuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BankBuyPrice AS BankBuyPrice

										FROM
												`CurrencyPricesTb` AS a


											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.BankSalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / BankSalePrice 												END AS BankSalePrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;


							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					IF v_CurrencyPower = 0
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BankBuyPrice 														ELSE 														1 / BankBuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * BankSalePrice) AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
				END IF;
			SELECT
					p_BPrice11,
					p_Purchaseprice;
			COMMIT;



	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `get_BracuNetBurnnc_SalePrice`;
DELIMITER //
CREATE PROCEDURE `get_BracuNetBurnnc_SalePrice`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

			START TRANSACTION;

			SELECT b.CurCode INTO v_CurrencyCode FROM
					CurrencyMainTb AS b
			WHERE
					b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
			SELECT a.CurrencyPower INTO v_CurrencyPower FROM
					CurrencyPriceDetailsTb AS a
			WHERE
					a.CurrencyIDFrom = 1
					AND a.CurrencyIDTo = p_CurrencyFrom;
			IF p_ISbaunk = 0
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.SalePrice INTO v_ValueDev FROM
									(   SELECT
												b.SalePrice AS SalePrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.BuyPrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / BuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;

							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;

					IF v_CurrencyPower = 0
						 THEN
							SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.SalePrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.SalePrice 														ELSE 														1 / SalePrice 												END AS SalePrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * BuyPrice) AS SalePrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					SET p_Purchaseprice = Get_PurchaseSalePrice(p_CurrencyTo, p_CurrencyFrom, p_ISbaunk);
				END IF;


			IF p_ISbaunk = 1
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BankBuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BankBuyPrice AS BankBuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.BankSalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / BankSalePrice 												END AS BankSalePrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;

							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
					IF v_CurrencyPower = 0
						 THEN
							SELECT a.BankSalePrice, a.BankBuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									CurrencyPriceDetailsTb AS a
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BankBuyPrice 														ELSE 														1 / BankBuyPrice 												END AS BuyPrice
										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * BankSalePrice) AS BuyPrice

										FROM
												`CurrencyPricesTb` AS a
											INNER JOIN
												CurrencyPriceDetailsTb AS b
													ON a.CurrencyIDFrom = b.CurrencyIDFrom
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;
				END IF;
			SELECT
					p_BPrice11,
					p_Purchaseprice;
			COMMIT;



	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Get_CurrencyIDByCountryID`;
DELIMITER //
CREATE PROCEDURE `Get_CurrencyIDByCountryID`(IN `p_CountryID` INT)
BEGIN
DECLARE v_IsDefult INT;



SELECT ct.IsMain INTO v_IsDefult FROM CountiresTb ct WHERE ct.ID=p_CountryID;

IF v_IsDefult=0
 THEN
	SELECT
			a.DefualtCurrency as CurrID
	FROM
			CountiresTb as a
			Where ID=p_CountryID;
      END IF;

IF v_IsDefult=1
 THEN
	SELECT
			a.ID as CurrID
	FROM
			CurrencyMainTb  as a
			Where a.IsDefault=1;
      END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `get_CurrencySpeculation`;
DELIMITER //
CREATE PROCEDURE `get_CurrencySpeculation`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

			START TRANSACTION;

			SELECT b.CurCode INTO v_CurrencyCode FROM
					CurrencyMainTb AS b
			WHERE
					b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
			SELECT a.CurrencyPower INTO v_CurrencyPower FROM
					NewCurrencyPriceOwnDetailsTb  AS a
			WHERE
					a.CurrencyIDFrom = 1
					AND a.CurrencyIDTo = p_CurrencyFrom;

			IF p_ISbaunk = 0 AND p_CurrencyFrom=1
				 THEN
				SELECT a.CurrencyPower INTO v_CurrencyPower FROM
					NewCurrencyPriceOwnDetailsTb AS a
          INNER JOIN
          NewCurrencyPricesOwnTb AS b
          ON a.CPID = b.ID
			WHERE
					a.CurrencyIDFrom = 1
					AND a.CurrencyIDTo = p_CurrencyTo
          AND b.PriceType=0;

							SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									NewCurrencyPriceOwnDetailsTb AS a
                            INNER JOIN
          NewCurrencyPricesOwnTb AS b
          ON a.CPID = b.ID
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyTo
                   AND b.PriceType=0;

							SELECT x.SalePrice INTO v_ValueDev FROM
									(   SELECT
												CASE 														WHEN CurrencyPower = 1 															THEN 															b.SalePrice 														ELSE 														1 / SalePrice 												END AS SalePrice
										FROM
												NewCurrencyPricesOwnTb  AS a
											INNER JOIN
												NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo
                        AND a.PriceType=0


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * BuyPrice) AS SalePrice

										FROM
												`NewCurrencyPricesOwnTb` AS a
											INNER JOIN
												NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo
                        AND a.PriceType=0) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 / v_ValueDev AS CHAR);
					SET p_Purchaseprice =   NewGet_PurchaseSalePrice(p_CurrencyFrom, p_CurrencyTo, 0,1,0);
				END IF;

			IF p_ISbaunk = 0 and p_CurrencyFrom<>1
				 THEN
					IF v_CurrencyPower = 1
						 THEN
							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									NewCurrencyPriceOwnDetailsTb AS a
                                      INNER JOIN
          NewCurrencyPricesOwnTb AS b
          ON a.CPID = b.ID
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom
                  AND b.PriceType=0;


							SELECT
									v_CurrencyBuyPrice;
							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT
												b.BuyPrice AS BuyPrice

										FROM
												`NewCurrencyPricesOwnTb` AS a
											INNER JOIN
												NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom
                        AND a.PriceType=0

										UNION

										SELECT
												CASE 														WHEN CurrencyPower = 0 															THEN 															b.SalePrice * v_CurrencyBuyPrice 														ELSE 														v_CurrencyBuyPrice / SalePrice 												END AS BuyPrice



										FROM
												`NewCurrencyPricesOwnTb` AS a


											INNER JOIN
												NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo <> p_CurrencyFrom
												AND b.CurrencyIDTo = p_CurrencyTo
                        AND a.PriceType=0) AS x;



							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;

					IF v_CurrencyPower = 0
						 THEN
							SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
									NewCurrencyPriceOwnDetailsTb AS a
                                      INNER JOIN
          NewCurrencyPricesOwnTb AS b
          ON a.CPID = b.ID
							WHERE
									a.CurrencyIDFrom = 1
									AND a.CurrencyIDTo = p_CurrencyFrom
                  AND b.PriceType=0;

							SELECT x.BuyPrice INTO v_ValueDev FROM
									(   SELECT


												CASE 														WHEN CurrencyPower = 1 															THEN 															b.BuyPrice 														ELSE 														1 / BuyPrice 												END AS BuyPrice
										FROM
												`NewCurrencyPricesOwnTb` AS a
											INNER JOIN
												NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDFrom = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = p_CurrencyTo
												AND b.CurrencyIDTo = p_CurrencyFrom
                        AND a.PriceType=0


										UNION

										SELECT
												1 / (v_CurrencyBuyPrice * SalePrice) AS BuyPrice

										 FROM
												`NewCurrencyPricesOwnTb` AS a


											INNER JOIN
												 NewCurrencyPriceOwnDetailsTb AS b
													ON a.ID = b.CPID
											INNER JOIN
												`CurrencyMainTb` AS c
													ON b.CurrencyIDTo = c.ID
										WHERE
												a.IsActive = 1
												AND b.IsActive = 1
												AND c.IsActive = 1
												AND a.CurrencyIDFrom = 1
												AND b.CurrencyIDTo = p_CurrencyTo
                        AND a.PriceType=0) AS x;
							SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
						END IF;


					SET p_Purchaseprice = New_Get_Purchaseprice(p_CurrencyTo, p_CurrencyFrom, 0,1,0);
				END IF;







































































































































			SELECT
					p_BPrice11,
					p_Purchaseprice;
			COMMIT;



	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `GET_TABLE_FOR_All`;
DELIMITER //
CREATE PROCEDURE `GET_TABLE_FOR_All`(IN `p_PriceType` INT, IN `p_CountryID` INT, IN `p_BranchID` INT)
BEGIN
SELECT
          x.CuName,
          x.BankName,
          x.Costof,
          SUM(x.Foreignbalance)                            Foreignbalance,
          SUM(x.LocalBalance)                              LocalBalance,
          SUM(x.costmerForPreseEn)                         costmerForPreseEn,
          SUM(x.Foreignbalance) + SUM(x.costmerForPreseEn) TotlaPrasceFor_Currency
  FROM
          (   SELECT
                      b.CuName AS CuName,
                      'اا خزائن الشركة' AS BankName,
                      GetCostOf_Currency_More_Detials(a.PriceType, a.CurrencyID, a.AccBranchID, p_CountryID,0) Costof,
                      SUM(a.Credit) - SUM(a.Debit) AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      0 AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE

                       a.IsActive=1
                      AND a.IsBank=0
                      AND a.PriceType=p_PriceType
                      AND a.CountryID=p_CountryID
                      AND a.AccBranchID=p_BranchID
              GROUP BY
                      b.ID,
                      b.CuName,
                      a.PriceType,
                      a.CurrencyID,
                      a.AccBranchID


               UNION

              SELECT

b.CuName  AS CuName,
 at.AccName AS BankName,
                      GetCostOf_Currency_More_Detials(a.PriceType, a.CurrencyID, a.AccBranchID, p_CountryID,a.ParentFrom) Costof,
                      SUM(a.Credit)-SUM(a.Debit) AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      0   AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
                        INNER JOIN
                        AccountsTb at
                        ON at.AccCode=a.ParentFrom
              WHERE
                          a.IsBank=1
                      AND a.IsActive=1
                      AND a.PriceType=p_PriceType
                                            AND a.CountryID=p_CountryID
                      AND a.AccBranchID=p_BranchID

              GROUP BY
                      b.ID,
                      b.CuName,
                      a.PriceType,
                      a.CurrencyID,
                      a.AccBranchID,
                      a.ParentFrom,
                      at.AccName
                      ) AS x

  GROUP BY
          x.ID,
          x.CuName,
          x.BankName,
          x.Costof

HAVING SUM(x.Foreignbalance)>0

ORDER BY
    CASE          WHEN x.BankName = N'خزائن الشركة' THEN 0          ELSE 1      END;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `GET_TABLE_FOR_Costof_Main_safs`;
DELIMITER //
CREATE PROCEDURE `GET_TABLE_FOR_Costof_Main_safs`(IN `p_BranchID` BIGINT, IN `p_ISInOrOut` TINYINT(1), IN `p_CountryID` INT, IN `p_CompanyOrCust` INT)
BEGIN
IF p_CompanyOrCust=0
 THEN
  SELECT
                      b.CuName AS CuName,
                      GetCostOf_Currency(p_ISInOrOut, b.ID, p_BranchID, p_CountryID) Costof,
                      SUM(a.Credit)-SUM(a.Debit)   AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      0 AS costmerForPreseEn,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE


                      a.IsActive=1
                      AND a.PriceType=p_ISInOrOut
                      AND a.CountryID=p_CountryID
                      AND a.AccBranchID=p_BranchID
              GROUP BY
                      b.ID,
                      b.CuName;




END IF;


IF p_CompanyOrCust=1
 THEN
	  SELECT
                      b.CuName AS CuName,
                      0 Costof,
                      0 AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      SUM(a.Debit)-SUM(a.Credit)   AS costmerForPreseEn,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE
                       a.ValType = 1
                      AND a.IsActive=1
                      AND a.PriceType=p_ISInOrOut

                      AND a.AccBranchID=p_BranchID
              GROUP BY
                      b.ID,
                      b.CuName;
END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `GET_TABLE_FOR_Costof_UESER_AccACount_PROC`;
DELIMITER //
CREATE PROCEDURE `GET_TABLE_FOR_Costof_UESER_AccACount_PROC`(IN `p_ACCID` BIGINT)
BEGIN
DECLARE v_UserID INT;
DECLARE v_Todey DATE;



SELECT tu.USID, NOW() INTO v_UserID, v_Todey FROM TB_Users tu WHERE tu.AccID=p_ACCID
 ORDER BY tu.USID DESC LIMIT 1;

  SELECT
          x.CuName,
          x.BankName,

          SUM(x.Foreignbalance)                            Foreignbalance,
          SUM(x.LocalBalance)                              LocalBalance,
          SUM(x.costmerForPreseEn)                         costmerForPreseEn,
          SUM(x.Foreignbalance) + SUM(x.costmerForPreseEn) TotlaPrasceFor_Currency
  FROM
          (   SELECT
                      b.CuName AS CuName,
                      'الخزينة الأجنبية'  AS BankName,


                      SUM(a.Credit) - SUM(a.Debit) AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      0 AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE
                      a.AccIDFrom = p_ACCID

                      AND a.IsActive=1
                      AND a.DailyClosed=0
                      AND a.AccIDTo<>225
              GROUP BY
                      b.ID,
                      b.CuName,

                      a.CurrencyID,
                      a.AccBranchID

              UNION

              SELECT
                      b.CuName AS CuName,
                      CASE WHEN a.PriceType=0 THEN 'الخزينة الأجنبية'WHEN a.PriceType=3 THEN 'مصرف ليبيا المركزي'ELSE 'خزائن أخرى' END AS BankName,

                      0 AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      SUM(a.Credit)-SUM(a.Debit)   AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE
                      a.AccIDFrom = p_ACCID
                      AND a.AccIDTo=225
                      AND a.ValType <> 1
                      AND a.IsActive=1
                      AND a.DailyClosed=0
              GROUP BY
                      b.ID,
                      b.CuName,
                      a.PriceType,
                      a.CurrencyID,
                      a.AccBranchID

              UNION

              SELECT
                      b.CuName AS CuName,
                      CONCAT('ا ', 'الخزينة المحلية') AS BankName,

                      SUM(a.Debit) - SUM(a.Credit) AS Foreignbalance,
                      0 AS LocalBalance,
                      0 AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccounts_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
              WHERE
                      a.AccIDFrom = p_ACCID
                      AND b.IsDefault = 1
                      AND a.IsActive=1
                      AND a.DailyClosed=0
              GROUP BY
                      b.ID,
                      b.CuName

               UNION

              SELECT

b.CuName   AS CuName,
 at.AccName AS BankName,

                      SUM(a.Credit)-SUM(a.Debit) AS Foreignbalance,
                      SUM(a.DL_Credit) - SUM(a.DL_Debit) AS LocalBalance,
                      0   AS costmerForPreseEn,
                      0 AS SafeTransfer,
                      b.ID
              FROM
                      ExSyAccountsCurrency_AccSafeActivityTb a
                  INNER JOIN
                    CurrencyMainTb b
                        ON a.CurrencyID = b.ID
                        INNER JOIN
                        AccountsTb at
                        ON at.AccCode=a.ParentFrom
              WHERE
                      a.SafeID = v_UserID
                      AND a.IsBank=1
                      AND a.IsActive=1
                      AND a.DailyClosed=0
                      AND a.InsertDate=v_Todey

              GROUP BY
                      b.ID,
                      b.CuName,
                      a.PriceType,
                      a.CurrencyID,
                      a.AccBranchID,
                      a.ParentFrom,
                      at.AccName
                      ) AS x

  GROUP BY
          x.ID,
          x.CuName,
          x.BankName

HAVING SUM(x.Foreignbalance)>0 OR SUM(x.costmerForPreseEn)>0;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Group_main_INSERRT`;
DELIMITER //
CREATE PROCEDURE `Group_main_INSERRT`(IN `p_GroupNAme` LONGTEXT, IN `p_group_ena` LONGTEXT, IN `p_Main_ID` INT, IN `p_ShortName` LONGTEXT, INOUT `p_smg` INT, INOUT `p_masg` LONGTEXT)
BEGIN
DECLARE v_GETID int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set p_smg = 2; CALL ERROR_PROC(); END;
START TRANSACTION;


INSERT INTO `Group-main`
           (`GroupNAme`
           ,`group_en`
           ,`Canshowe`
           ,`Main_ID`
           ,`ShortName`)

           values(
           p_GroupNAme ,
           p_group_ena
           , 0
           ,p_Main_ID  ,
           p_ShortName
           );


           SELECT max(id) INTO v_GETID FROM `Group-main`;

INSERT INTO `Ueser_Group_main`
           (`Profile`
           ,`GrouID`
           ,`Canshow`
           ,`ManID`)

           SELECT a.ProfID ,  v_GETID , 0 ,p_Main_ID FROM ProfileName AS A

           group by ProfID;


           INSERT INTO `Ueser_Group_main_ID`
           (`Profile`
           ,`GrouID`
           ,`Canshow`
           ,`ManID`
           ,`UserID`)
           select a.UserType ,v_GETID , 0 ,p_Main_ID , a.USID   from TB_Users as a

           group by  a.UserType ,  a.USID;

           commit;
            set p_smg = 1;
           END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `HagezOmlaAgnbia`;
DELIMITER //
CREATE PROCEDURE `HagezOmlaAgnbia`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
     SELECT a.AccID,
           a.AccName,
           bt.AccountNo
     FROM  AccountsTb as a
     LEFT JOIN
     BBranchTb bt
     ON a.AccID = bt.AccID
     WHERE (a.AccCode=101050102 OR a.AccCode=101050109 OR a.AccCode=2010140101 OR a.AccParent=1010504 OR a.AccCode=101050502 ) AND a.AccActive=1;
     COMMIT;
END //
DELIMITER ;

