DROP PROCEDURE IF EXISTS `IncomeTb_MaxID`;
DELIMITER //
CREATE PROCEDURE `IncomeTb_MaxID`(IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
DECLARE v_Code LONGTEXT;


	START TRANSACTION;
SET v_Code = CONCAT(CAST(p_TypeID AS CHAR), '-', CAST(Income_GetMaxCODEID(p_TypeID) AS CHAR));
	SELECT
			v_Code											AS Code,
			Income_GetMaxCODEID(p_TypeID) AS ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_Delete`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_Delete`(IN `p_Code` LONGTEXT, IN `p_EMPID` INT, IN `p_INCVAL` DECIMAL(12,3))
BEGIN
DECLARE v_EMPIPIVAL DECIMAL(15, 3);
DECLARE v_NEWEMPIPIVAL DECIMAL(15, 3);
DECLARE v_Bonus DECIMAL(12, 3);
DECLARE v_TotalBonusVal DECIMAL(12, 3);
DECLARE v_IsConstant BIT;


	START TRANSACTION;
	UPDATE
			IncreaseValTb
	SET
			IsActive = 0
	WHERE
		Code = p_Code;

	SELECT IsConstant INTO v_IsConstant FROM
			IncreaseValTb
	WHERE
			IncreaseValTb.EMPID = p_EMPID;

	SELECT IFNULL(SUM(incval), 0.000) INTO v_TotalBonusVal FROM
			IncreaseValTb
	WHERE
			EMPID = p_EMPID
			AND IncreaseValTb.IsActive = 1
			AND IncreaseValTb.IsConstant = 0;

	SELECT IFNULL(SUM(a.INCVAL), 0.000) INTO v_EMPIPIVAL FROM
			IncreaseValTb AS a
	WHERE
			a.IsActive = 1
			AND a.IsConstant = 1
			AND a.EMPID = p_EMPID;
SET v_NEWEMPIPIVAL = v_EMPIPIVAL - p_INCVAL;
	IF v_IsConstant = 1
		 THEN
			UPDATE
					EmployeeTb
			SET
					EmployeeTb.PIVAL = v_EMPIPIVAL
			WHERE
				ID = p_EMPID;
		END IF;
	IF v_IsConstant = 0
		 THEN
			UPDATE
					EmployeeTb
			SET
					EmployeeTb.BonusVal = v_TotalBonusVal
			WHERE
				ID = p_EMPID;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_DeleteByEMPID`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_DeleteByEMPID`(IN `p_EMPID` INT)
BEGIN
START TRANSACTION;
	UPDATE
			IncreaseValTb
	SET
			ISACTIVE = 0
	WHERE
		EMPID = p_EMPID
		AND IncreaseValTb.IsConstant = 0;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_Insert`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_Insert`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_IncreaseTypeID` INT, IN `p_EMPID` BIGINT, IN `p_INCVAL` DECIMAL(12,3), IN `p_IsConstant` TINYINT(1), IN `p_Notes` LONGTEXT, INOUT `p_MSGSTatues` INT, INOUT `p_MSGBOX` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_Bonus DECIMAL(12, 3);
DECLARE v_TotalBonusVal DECIMAL(12, 3);
DECLARE v_PREPIVAL DECIMAL(12, 3);
DECLARE v_NEWPIVAL DECIMAL(12, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


			START TRANSACTION;
	SELECT a.BonusVal INTO v_Bonus FROM
			EmployeeTb AS a
	WHERE
			a.ID = p_EMPID;

			SELECT Code INTO v_GETID FROM
					IncreaseValTb AS a
			WHERE
					a.Code = p_Code;
		IF p_Code = v_GETID
								 THEN
									SET p_MSGSTatues = 0;
									SET p_MSGBOX = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
									ROLLBACK;
									LEAVE proc;
		END IF;

	INSERT INTO IncreaseValTb
			(
				CODE,
				InsertDate,
				IncreaseTypeID,
				EMPID,
				INCVAL,
				ISACTIVE,
				IsConstant,
				Notes,
				IsOpened
			)
	VALUES
			(
				p_Code, p_InsertDate, p_IncreaseTypeID, p_EMPID, p_INCVAL, 1, p_IsConstant, p_Notes, 1

			);
	SELECT IFNULL(SUM(INCVAL), 0.000) INTO v_TotalBonusVal FROM
			IncreaseValTb
	WHERE
			EMPID = p_EMPID
			AND IncreaseValTb.ISACTIVE = 1
			AND IncreaseValTb.IsConstant = 0
			AND IsOpened = 1;
	IF p_IsConstant = 0
		 THEN
			UPDATE
					EmployeeTb
			SET
					EmployeeTb.BonusVal = v_TotalBonusVal
			WHERE
				ID = p_EMPID;
		END IF;
	IF p_IsConstant = 1
		 THEN
			SELECT EmployeeTb.PIVAL INTO v_PREPIVAL FROM
					EmployeeTb
			WHERE
					EmployeeTb.ID = p_EMPID;
			IF v_PREPIVAL IS NULL
				 THEN
SET v_PREPIVAL = 0.000;
				END IF;
SET v_NEWPIVAL = v_PREPIVAL + p_INCVAL;
			UPDATE
					EmployeeTb
			SET
					EmployeeTb.PIVAL = v_NEWPIVAL
			WHERE
				EmployeeTb.ID = p_EMPID;
		END IF;
					COMMIT;
			SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ) AS '#',
			a.CODE										   AS 'الرمز',
			a.InsertDate								   AS 'التاريخ',
			c.EMPNAME									   AS 'اسم الموظف',
			b.PIName									   AS 'نوع العلاوة',
			a.INCVAL									   AS 'إجمالي العلاوات',

			CASE 					WHEN a.IsConstant = 1 						THEN 						'علاوة دائمة' 					ELSE 					'علاوة مؤقتة' 			END											   AS 'طبيعة العلاوة',
       a.Notes AS 'الملاحظات',
			CASE 					WHEN a.IsOpened = 0 						THEN 						'منتهية' 					ELSE 					'مستمرة' 			END											   AS 'الحالة'

	FROM
			IncreaseValTb AS a
		LEFT JOIN
			PayIncrease AS b
				ON a.IncreaseTypeID = b.ID
		LEFT JOIN
			EmployeeTb AS c
				ON a.EMPID = c.ID
	WHERE
			a.ISACTIVE = 1
			AND b.ISACTIVE = 1
			AND c.BranchID = p_BranchID
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
	ORDER BY
			a.ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_LOADTODVG`()
BEGIN
START TRANSACTION;

	SELECT
			ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
			a.Code								  AS 'الرمز',
			a.InsertDate						  'التاريخ',
			b.PIName							  'نوع العلاوة',
			c.EMPNAME							  'اسم الموظف',
			CASE 					WHEN a.IsConstant = 1 						THEN 						'علاوة دائمة' 					WHEN a.IsConstant = 0 						THEN 						'علاوة مؤقتة' 			END									  AS 'طبيعة العلاوة',
			a.INCVAL							  'القيمة',
			a.IsActive							  'الحالة'
	FROM
			IncreaseValTb AS a
		LEFT JOIN
			PayIncrease AS b
				ON a.IncreaseTypeID = b.ID
		LEFT JOIN
			EmployeeTb AS c
				ON a.EMPID = c.ID
	WHERE
			a.IsActive = 1;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_Select`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_Select`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code,
			A.InsertDate,
			A.IncreaseTypeID,
			A.EMPID,
			D.EMPNAME,
			E.PIName,
			C.BName,
			A.INCVAL,
			A.IsActive,
			A.IsConstant,
			Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
			CASE 					WHEN A.IsConstant = 1 						THEN 						'علاوة دائمة' 					WHEN A.IsConstant = 0 						THEN 						'علاوة مؤقتة' 			END						   AS 'طبيعة العلاوة'
	FROM
			IncreaseValTb AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
		LEFT JOIN
			CoBranch AS C
				ON B.BranchID = C.ID
		LEFT JOIN
			EmployeeTb AS D
				ON A.EMPID = D.ID
		LEFT JOIN
			PayIncrease AS E
				ON A.IncreaseTypeID = E.ID


	WHERE
			A.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreaseValTb_Update`;
DELIMITER //
CREATE PROCEDURE `IncreaseValTb_Update`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_IncreaseTypeID` INT, IN `p_EMPID` BIGINT, IN `p_INCVAL` DECIMAL(12,3), IN `p_IsConstant` TINYINT(1))
BEGIN
DECLARE v_Bonus DECIMAL(12, 3);
DECLARE v_TotalBonusVal DECIMAL(12, 3);
DECLARE v_PREPIVAL DECIMAL(12, 3);
DECLARE v_NEWPIVAL DECIMAL(12, 3);


	START TRANSACTION;
	UPDATE
			IncreaseValTb
	SET
			InsertDate = p_InsertDate, IncreaseTypeID = p_IncreaseTypeID, EMPID = p_EMPID, INCVAL = p_INCVAL, IsActive = 1, IsConstant = p_IsConstant, IsOpened = 1
	WHERE
		Code = p_Code;

	SELECT IFNULL(SUM(INCVAL), 0.000) INTO v_TotalBonusVal FROM
			IncreaseValTb
	WHERE
			EMPID = p_EMPID
			AND IncreaseValTb.IsActive = 1
			AND IncreaseValTb.IsConstant = 0
			AND IsOpened = 1;
	IF p_IsConstant = 0
		 THEN
			UPDATE
					EmployeeTb
			SET
					EmployeeTb.BonusVal = v_TotalBonusVal
			WHERE
				ID = p_EMPID;
		END IF;

	IF p_IsConstant = 1
		 THEN
			SELECT IFNULL(SUM(ivt.INCVAL), 0.000) INTO v_NEWPIVAL FROM
					IncreaseValTb ivt
			WHERE
					ivt.IsConstant = 1
					AND ivt.EMPID = p_EMPID;

			UPDATE
					EmployeeTb
			SET
					EmployeeTb.PIVal = v_NEWPIVAL
			WHERE
				EmployeeTb.ID = p_EMPID;
		END IF;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `IncreasValTb_LOADINTOLKP`;
DELIMITER //
CREATE PROCEDURE `IncreasValTb_LOADINTOLKP`()
BEGIN
START TRANSACTION;

	SELECT
			dtt.ID,
			dtt.PIName
	FROM
			PayIncrease dtt
	ORDER BY
			dtt.PIName;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InteralEx_CheckCode`;
DELIMITER //
CREATE PROCEDURE `InteralEx_CheckCode`(IN `p_Code` LONGTEXT)
BEGIN


    START TRANSACTION;
    SELECT
          ie.Code
    FROM

        InternalEx ie

    WHERE
            ie.Code = p_Code;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_AgentRedirection`;
DELIMITER //
CREATE PROCEDURE `InternalEx_AgentRedirection`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;


	SELECT
			ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#',
			a.Code,
			a.InsertDate,
			a.SenderName,
			a.RecievedName,
			b.BName,
			c.BName									AS DBName,
			a.OverallVal,
			a.ExVal,
			a.BranchRecievedID,
			a.BranchDeliveredID,
      b.BranchType AS RBRTYPE,
      c.BranchType AS DBRTYPE
	FROM
			InternalEx AS a
		INNER JOIN
			CoBranch AS b
				ON a.BranchRecievedID = b.ID
		INNER JOIN
			CoBranch AS c
				ON a.BranchDeliveredID = c.ID
	WHERE
			a.IsActive = 1
			AND a.Code = p_Code
	ORDER BY
			a.InsertDate ASC;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_CheckConfirmed`;
DELIMITER //
CREATE PROCEDURE `InternalEx_CheckConfirmed`(IN `p_Code` LONGTEXT, INOUT `p_msgIN` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_DSST_SET INT;
DECLARE v_IsDelivered_SET INT;
DECLARE v_IsConfirmed_Set INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL report_error(); SET p_msgIN = 0; END;


    START TRANSACTION;




    SELECT x.IsConfirmed INTO v_IsConfirmed_Set FROM
            (   SELECT
                        IsConfirmed
                FROM
                      InternalExTb_LoadToIssued AS a
                WHERE
                        a.Code = p_Code
                UNION
                SELECT

                        IsConfirmed
                FROM
                        InternalExTb_LoadToIssued AS a
                WHERE
                        a.Code = p_Code) AS X;

    IF v_IsConfirmed_Set > 0
       THEN
        SET p_msgIN = 0;
        SET p_MsgBox = 'تم اعتماد هذه الحوالة مسبقاً';
        ROLLBACK;
        LEAVE proc;
      END IF;
    COMMIT;
    SET p_msgIN = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEX_LOADINTOLKPBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `InternalEX_LOADINTOLKPBASEDONAccParent`(IN `p_BranchID` INT, IN `p_AccParent` BIGINT, IN `p_SendOrRec` TINYINT UNSIGNED, IN `p_CurrencyID` INT)
BEGIN
START TRANSACTION;

  SELECT
          at.AccID,
          at.AccName,
          IFNULL(at.AccPhone,'0') AS AccPhone,
          IFNULL(at.AccMobile,'0') AS AccMobile,
          IFNULL(at.AccIDNo,'لا يوجد') AS AccIDNo,
          Account_GetAccVal(at.AccID,p_CurrencyID,0) AS GetAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,1) AS GetBankAccVal
  FROM
          AccountsTb at
  WHERE
          ((at.AccParent =  p_AccParent ) OR (p_AccParent=0 AND at.AccParent LIKE '30101%' AND p_SendOrRec=0))
          AND At.accActive = 1
          AND at.BranchID = p_BranchID;


  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_LOADTOCONFIRM`;
DELIMITER //
CREATE PROCEDURE `InternalEx_LOADTOCONFIRM`(IN `p_Type` INT)
BEGIN
START TRANSACTION;

  IF p_Type = 1
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d') AS InsertDate,
              a.SenderName,
              a.RecievedName,
              a.OverallVal,
              a.ExVal,
              a.DeliveryPlace,
              c.BName                            AS BranchRecievedID,
              d.CityName                         AS BranchDeliveredID,
              CASE                       WHEN a.Type_Moble = 1                         THEN                         'تطبيق'                       ELSE                       b.UName               END                                AS UNameLog,
              DATE_FORMAT(a.InsertDate, '%h:%i %p')   AS InsertTime,
              'غير معتمدة' AS CANCELSTATUS
      FROM
              InternalEx AS a
          LEFT JOIN
            TB_Users b
              ON a.SafeRecievedID = b.USID
          LEFT JOIN
            CoBranch c
              ON a.BranchRecievedID = c.ID
          LEFT JOIN
            CitiesTb d
              ON a.DeliveryPlace = d.ID
      WHERE
              a.IsActive = 1
              AND a.ConfirmType = 0;
    END IF;

  IF p_Type = 3
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d') AS InsertDate,
              a.SenderName,
              a.RecievedName,
              a.OverallVal,
              a.ExVal,
              a.DeliveryPlace,
              c.BName                            AS BranchRecievedID,
              d.CityName                         AS BranchDeliveredID,
              CASE                       WHEN a.Type_Moble = 1                         THEN                         'تطبيق'                       ELSE                       b.UName               END                                AS UNameLog,
              DATE_FORMAT(a.InsertDate, '%h:%i %p')   AS InsertTime,
              'غير معتمدة' AS CANCELSTATUS
      FROM
              InternalEx AS a
          LEFT JOIN
            TB_Users b
              ON a.SafeRecievedID = b.USID
          LEFT JOIN
            CoBranch c
              ON a.BranchRecievedID = c.ID
          LEFT JOIN
            CitiesTb d
              ON a.DeliveryPlace = d.ID
      WHERE
              a.IsActive = 1
              AND (   a.ConfirmType = 3
                      OR a.ConfirmType = 4)
              AND a.IsCanceled = 0;
    END IF;

  IF p_Type = 2
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d') AS InsertDate,
              a.SenderName,
              a.RecievedName,
              CASE WHEN a.IsInOrOut=0 Then a.CurrRecievedVal ELSE a.CurrDeliveredVal END AS OverallVal,
              a.ExVal,
             '' as DeliveryPlace,
              c.BName                            AS BranchRecievedID,
              d.CName                         AS BranchDeliveredID,
              CASE                       WHEN a.Type_Moble = 1                         THEN                         'تطبيق'                       ELSE                       b.UName               END                                AS UNameLog,
              DATE_FORMAT(a.InsertDate, '%h:%i %p')   AS InsertTime,
             e.ServiceName AS CANCELSTATUS
      FROM
              ExternalEx AS a
          LEFT JOIN
            TB_Users b
              ON a.SafeRecievedID = b.USID
          LEFT JOIN
            CoBranch c
              ON a.RecievedBranchID = c.ID
          LEFT JOIN
            CountiresTb d
              ON a.CountryIDTo = d.ID
                       LEFT JOIN
         ExtTraServiceTypeTb AS e
         ON a.ServiceType=e.ID
			WHERE
					a.IsActive = 1
					AND IsDelivered = 0
					AND IsConfirmed = 0
					AND IsCanceled = 0;
    END IF;

  IF p_Type = 4
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d') AS InsertDate,
              a.SenderName,
              a.RecievedName,
              CASE WHEN a.IsInOrOut=0 Then a.CurrRecievedVal ELSE a.CurrDeliveredVal END AS OverallVal,
              a.ExVal,
             '' as DeliveryPlace,
              c.BName                            AS BranchRecievedID,
              d.CName                         AS BranchDeliveredID,
              a.RecievedBranchID AS Brid,
              CASE                       WHEN a.Type_Moble = 1                         THEN                         'تطبيق'                       ELSE                       b.UName               END                                AS UNameLog,
              DATE_FORMAT(a.InsertDate, '%h:%i %p')   AS InsertTime,
              CASE WHEN a.IsConfirmed=0 Then   'غير معتمدة'ELSE 'معتمدة' END CANCELSTATUS
      FROM
              ExternalEx AS a
          LEFT JOIN
            TB_Users b
              ON a.SafeRecievedID = b.USID
          LEFT JOIN
            CoBranch c
              ON a.RecievedBranchID = c.ID
          LEFT JOIN
            CountiresTb d
              ON a.CountryIDTo = d.ID
                       LEFT JOIN
         ExtTraServiceTypeTb AS e
          ON a.ServiceType=e.ID
                                 LEFT JOIN
                          TransCancelRequestTb_LoadToIssued AS f
                              ON a.Code = f.ISID
                    WHERE
                            a.IsActive = 1
                            AND ((a.ConfirmedType = 3)  OR (a.ConfirmedType = 4))
                            AND a.IsCanceled = 1
                            AND a.RefuseCanceled = 0;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_LoadToEdit`;
DELIMITER //
CREATE PROCEDURE `InternalEx_LoadToEdit`(IN `p_BranchID` INT, IN `p_EditType` TINYINT UNSIGNED)
BEGIN
DECLARE v_IsMain BIT;


START TRANSACTION;

SELECT IsMain INTO v_IsMain FROM CoBranch WHERE id=p_BranchID;
IF p_EditType=0  THEN
  SELECT ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#', a.Code AS 'الرمز', a.SenderName AS 'اسم الراسل', a.SPhone1 'هاتف الراسل', a.SPhone2 'جوال الراسل', a.RecievedName 'اسم المستلم', a.RPhone1 'هاتف المستلم', RPhone2 'جوال المستلم'

  FROM InternalEx AS a
       JOIN CoBranch AS b ON a.BranchRecievedID=b.ID
  WHERE a.BranchRecievedID = p_BranchID
  AND (a.ConfirmType = 1 OR a.ConfirmType = 0)
  AND a.IsActive = 1
  AND a.IsEdit <> 1
  AND a.IsAccFrom=0
  ORDER BY a.Code ASC;
END IF;

IF p_EditType=1  THEN
  SELECT ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#', a.Code AS 'الرمز', a.SenderName AS 'اسم الراسل', a.SPhone1 'هاتف الراسل', a.SPhone2 'جوال الراسل', a.RecievedName 'اسم المستلم', a.RPhone1 'هاتف المستلم', RPhone2 'جوال المستلم'

  FROM InternalEx AS a
       JOIN CoBranch AS b ON a.BranchRecievedID=b.ID
  WHERE a.BranchRecievedID = p_BranchID
  AND (a.ConfirmType = 1 OR a.ConfirmType = 0)
  AND a.IsActive = 1
  AND a.IsEdit <> 1
  AND a.IsAccTo=0
  ORDER BY a.Code ASC;
END IF;

IF p_EditType=2  THEN
  SELECT ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#', a.Code AS 'الرمز', a.SenderName AS 'اسم الراسل', a.SPhone1 'هاتف الراسل', a.SPhone2 'جوال الراسل', a.RecievedName 'اسم المستلم', a.RPhone1 'هاتف المستلم', RPhone2 'جوال المستلم'

  FROM InternalEx AS a
       JOIN CoBranch AS b ON a.BranchRecievedID=b.ID
  WHERE a.BranchRecievedID = p_BranchID
  AND (a.ConfirmType = 1 OR a.ConfirmType = 0)
  AND a.IsActive = 1
  AND a.IsEdit <> 1
  AND (a.IsAccFrom=0 AND a.IsAccTo=0)
  ORDER BY a.Code ASC;
END IF;

COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_Log_Statement`;
DELIMITER //
CREATE PROCEDURE `InternalEx_Log_Statement`(IN `p_SafeID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_USID INT;
START TRANSACTION;

SELECT tu.USID INTO v_USID FROM TB_Users tu WHERE tu.AccID=p_SafeID
 ORDER BY tu.USID DESC LIMIT 1;

        SELECT
            ROW_NUMBER () OVER (ORDER BY a.InsertDate ASC) AS '#',
			a.Code AS 'رمز الحوالة',
            a.InsertDate AS 'التاريخ',
            c.UName AS 'تنفيذ الموظف',
            i.OldOverallVal AS 'القيمة السابقة',
            i.OldExVal AS 'العمولة السابقة',
            i.NewOverallVal AS 'القيمة الجديدة',
            i.NewExVal AS 'العمولة الجديدة',
            d.UName AS 'عدلت بواسطة'
        FROM
InternalEx_Log i
            left JOIN
            TB_Users AS c
            ON i.InsertedBy = c.USID
                        left JOIN
            TB_Users AS d
            ON i.ModifiedBy = d.USID
                        left JOIN
            InternalEx  AS a
            ON a.ID = i.InternalExID
        WHERE

            (i.InsertedBy = v_USID OR p_SafeID=0) AND
            a.InsertDate >= p_D1 AND
            a.insertdate <= DATE_ADD(p_D2, INTERVAL 1 DAY);
        COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_MaxID`;
DELIMITER //
CREATE PROCEDURE `InternalEx_MaxID`(IN `p_typID` INT, IN `p_BranchID` INT, IN `p_USRID` INT, IN `p_CountryID` INT, IN `p_CityID` INT)
BEGIN
DECLARE v_Code LONGTEXT;
SET v_Code = CONCAT(CAST(p_CountryID AS CHAR), CAST(p_CityID AS CHAR), CAST(p_BranchID AS CHAR), CAST(p_typID AS CHAR), '-', CAST(p_USRID AS CHAR), '-', CAST(InternalEx_GetMaxIDCode() AS CHAR));
	SELECT
			v_Code						  AS Code,
			InternalEx_GetMaxIDCode() AS ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_MaxID1`;
DELIMITER //
CREATE PROCEDURE `InternalEx_MaxID1`(IN `p_typID` INT, IN `p_BranchID` INT, IN `p_USRID` INT, IN `p_CountryID` INT, IN `p_CityID` INT, INOUT `p_Code` LONGTEXT)
BEGIN
DECLARE v_MaxID INT DEFAULT InternalEx_GetMaxIDCode();



    SET p_Code =
        CONCAT(CAST(p_CountryID AS CHAR), CAST(p_CityID AS CHAR), CAST(p_BranchID AS CHAR), CAST(p_typID AS CHAR), '-', CAST(p_USRID AS CHAR), '-', CAST(v_MaxID AS CHAR));
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_ReDireciton`;
DELIMITER //
CREATE PROCEDURE `InternalEx_ReDireciton`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

			SELECT
					ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#',
					a.Code,
					a.InsertDate,
					a.SenderName,
					a.RecievedName,
					b.BName,
					c.BName as BranchDeliveredID,
					a.OverallVal,
					a.ExVal,
					a.BranchRecievedID,
					a.BranchDeliveredID						AS BranchDeliveredIDID,
					c.BranchType

			FROM
					InternalEx AS a
				INNER JOIN
					CoBranch AS b
						ON a.BranchRecievedID = b.ID
				INNER JOIN
					CoBranch AS c
						ON a.BranchDeliveredID = c.ID
			WHERE
					a.IsActive = 1
					AND (a.ConfirmType=1 OR (a.ConfirmType=2 AND c.BranchType=3))
					AND a.IsAccTo=0
          AND (a.BranchRecievedID=p_BranchID OR a.BranchDeliveredID=p_BranchID)
  ORDER BY
          a.Code ASC;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_SearchToEdit`;
DELIMITER //
CREATE PROCEDURE `InternalEx_SearchToEdit`(IN `p_Code` LONGTEXT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#',
          a.Code                                  AS 'الرمز',
          a.SenderName                            AS 'اسم الراسل',
          a.SPhone1                               'هاتف الراسل',
          a.SPhone2                               'جوال الراسل',
          a.RecievedName                          'اسم المستلم',
          a.RPhone1                               'هاتف المستلم',
          RPhone2                                 'جوال المستلم',
          ''                                      AS 'اختيار'
  FROM
          InternalEx AS a
  WHERE
          (a.BranchRecievedID = p_BranchID  )
 AND (a.ConfirmType = 1 OR a.ConfirmType = 0)
          AND a.IsActive = 1
          AND a.IsEdit <> 1
          AND a.Code = p_Code

  ORDER BY
          a.Code ASC;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_SelectType`;
DELIMITER //
CREATE PROCEDURE `InternalEx_SelectType`(IN `p_BranchID` INT, IN `p_SelectType` INT, IN `p_UserID` INT)
BEGIN
DECLARE v_currD DATETIME DEFAULT NOW();
DECLARE v_CurrD2 DATETIME DEFAULT NOW() - DAY(5);
DECLARE v_UType INT;
START TRANSACTION;


  IF p_SelectType = 1
     THEN
      SELECT
              a.Code                                                                   AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.InsertDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                             AS 'الراسل',
              a.RecievedName                                                           AS 'المستلم',
              a.RPhone1                                                                AS 'الهاتف',
              a.OverallVal                                                             AS 'قيمة الحوالة',
              a.ExVal                                                                  AS 'العمولة',

              CASE                       WHEN a.BranchDeliveredID > 0                         THEN                         b.BName                       ELSE                       c.CityName               END                                                                      AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.IsActive = 1


              AND a.ConfirmType = 0
              AND a.BranchRecievedID = p_BranchID;
    END IF;

  IF p_SelectType = 2
     THEN
      SELECT
              a.Code                                                                   AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.InsertDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                             AS 'الراسل',
              a.RecievedName                                                           AS 'المستلم',
              a.RPhone1                                                                AS 'الهاتف',
              a.OverallVal                                                             AS 'قيمة الحوالة',
              a.ExVal                                                                  AS 'العمولة',

              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                      AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.IsActive = 1


              AND a.ConfirmType = 1
              AND a.BranchRecievedID = p_BranchID;

    END IF;

  IF p_SelectType = 3
     THEN
      SELECT
              a.Code                                                                     AS 'الرمز',
              DATE_FORMAT(a.RecievedDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.RecievedDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                               AS 'الراسل',
              a.RecievedName                                                             AS 'المستلم',
              a.RPhone1                                                                  AS 'الهاتف',
              a.OverallVal                                                               AS 'قيمة الحوالة',
              a.ExVal                                                                    AS 'العمولة',

              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                        AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.IsActive = 1


              AND a.ConfirmType = 2
              AND a.BranchRecievedID = p_BranchID
              AND a.InsertDate BETWEEN v_CurrD2 AND v_currD;

    END IF;

  IF p_SelectType = 4
     THEN

      SELECT
              a.Code                                                                   AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.InsertDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                             AS 'الراسل',
              a.RecievedName                                                           AS 'المستلم',
              a.RPhone1                                                                AS 'الهاتف',
              a.OverallVal                                                             AS 'قيمة الحوالة',
              a.ExVal                                                                  AS 'العمولة',
              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                      AS 'من'

      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchRecievedID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON b.CityID = c.ID
      WHERE

              a.ConfirmType = 1

              AND a.BranchDeliveredID = p_BranchID;
    END IF;

  IF p_SelectType = 5
     THEN
SELECT tu.UserType INTO v_UType FROM TB_Users tu WHERE tu.USID=p_UserID
 ORDER BY tu.USID DESC LIMIT 1;
      SELECT
              a.Code                                                                            AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.InsertDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                                      AS 'الراسل',
              a.RecievedName                                                                    AS 'المستلم',
              a.RPhone1                                                                         AS 'الهاتف',
              a.OverallVal                                                                      AS 'قيمة الحوالة',
              a.ExVal                                                                           AS 'العمولة',
              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                               AS 'من'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchRecievedID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.ConfirmType = 4

              AND a.IsCanceled = 1
              AND (a.BranchDeliveredID = p_BranchID  OR v_UType=3 OR v_UType=1);

    END IF;

  IF p_SelectType = 6
     THEN
      SELECT
              a.Code                                                                     AS 'الرمز',
              DATE_FORMAT(a.RecievedDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.RecievedDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                               AS 'الراسل',
              a.RecievedName                                                             AS 'المستلم',
              a.RPhone1                                                                  AS 'الهاتف',
              a.OverallVal                                                               AS 'قيمة الحوالة',
              a.ExVal                                                                    AS 'العمولة',

              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                        AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.IsActive = 1
              AND a.ConfirmType = 6
              AND a.BranchRecievedID =p_BranchID
              AND a.InsertDate BETWEEN v_CurrD2 AND v_currD;
    END IF;

  IF p_SelectType = 7
     THEN
      SELECT
              a.Code                                                                     AS 'الرمز',
              DATE_FORMAT(a.RecievedDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.RecievedDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                               AS 'الراسل',
              a.RecievedName                                                             AS 'المستلم',
              a.RPhone1                                                                  AS 'الهاتف',
              a.OverallVal                                                               AS 'قيمة الحوالة',
              a.ExVal                                                                    AS 'العمولة',
              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                        AS 'من'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchRecievedID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON b.CityID = c.ID
      WHERE
              a.ConfirmType = 2
              AND a.BranchDeliveredID = p_BranchID;
    END IF;

  IF p_SelectType = 8
     THEN
      SELECT
              a.Code                                                                            AS 'الرمز',
              DATE_FORMAT(a.ConfirmCanceledDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.ConfirmCanceledDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                                      AS 'الراسل',
              a.RecievedName                                                                    AS 'المستلم',
              a.RPhone1                                                                         AS 'الهاتف',
              a.OverallVal                                                                      AS 'قيمة الحوالة',
              a.ExVal                                                                           AS 'العمولة',
              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                               AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.ConfirmType = 4
              AND a.IsCanceled = 1
              AND a.BranchRecievedID = p_BranchID;
    END IF;

  IF p_SelectType = 9
     THEN
      SELECT
              a.Code                                                                            AS 'الرمز',
              DATE_FORMAT(a.ConfirmCanceledDate, '%Y-%m-%d')                                       AS 'التاريخ',
              REPLACE(REPLACE(DATE_FORMAT(a.ConfirmCanceledDate, '%h:%i %p'), 'AM', 'ص'), 'PM', 'م') AS 'الوقت',
              a.SenderName                                                                      AS 'الراسل',
              a.RecievedName                                                                    AS 'المستلم',
              a.RPhone1                                                                         AS 'الهاتف',
              a.OverallVal                                                                      AS 'قيمة الحوالة',
              a.ExVal                                                                           AS 'العمولة',
              CASE                       WHEN b.BranchType = 3                         THEN                         c.CityName                       ELSE                       b.BName               END                                                                               AS 'إلى'
      FROM
              InternalEx AS a
          LEFT JOIN
            CoBranch AS b
              ON a.BranchDeliveredID = b.ID
          LEFT JOIN
            CitiesTb AS c
              ON a.DeliveryPlace = c.ID
      WHERE
              a.ConfirmType = 5
              AND a.BranchRecievedID = p_BranchID;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_update_Taxi_ISMobile`;
DELIMITER //
CREATE PROCEDURE `InternalEx_update_Taxi_ISMobile`(IN `p_Code` LONGTEXT, IN `p_TaxiValues` DECIMAL(18,3), INOUT `p_Smg` INT, INOUT `p_Masge` LONGTEXT)
proc: BEGIN
DECLARE v_ConfirmType int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set p_Smg= 2; CALL ERROR_PROC(); END;
START TRANSACTION;
SELECT a.ConfirmType INTO v_ConfirmType FROM InternalEx as a  where a.Code = p_Code;
if v_ConfirmType <> 7
 THEN
set p_Smg= 0;
set p_Masge = 'عذرا لايمكن اعتماد هذه الحوالة في الوقت الحالي';
rollback;
LEAVE proc;
END IF;


update InternalEx set ConfirmType = 8 , TaxiValues= p_TaxiValues , Taxi_Ret_DriverS = p_TaxiValues
where Code = p_Code  and ConfirmType = 7;

commit;
set p_Smg= 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalEx_UpdateAfterConfirmEdit`;
DELIMITER //
CREATE PROCEDURE `InternalEx_UpdateAfterConfirmEdit`(IN `p_Code` LONGTEXT, IN `p_IsConfirm` TINYINT(1))
BEGIN
DECLARE v_MaxID int;
START TRANSACTION;
	SELECT max(id) INTO v_MaxID FROM TransEditRequistTb where ISID=p_Code;
	IF p_IsConfirm = 1
		 THEN
			UPDATE InternalEx AS a
				INNER JOIN
					TransEditRequistTb AS b
						ON a.Code = b.ISID SET a.SenderName = b.SenderName,
					a.SPhone1 = b.SPhone1,
					a.SPhone2 = b.Phone2,
					a.RecievedName = b.RecievedName,
					a.RPhone1 = b.RPhone1,
					a.RPhone2 = b.Rhpone2,
					a.IsEdit = 2 WHERE
			 b.ISID=p_Code And b.id=v_MaxID;

			UPDATE
					TransEditRequistTb
			SET
					IsUpdated = 2
			WHERE
				ISID = p_Code;
		END IF;
	IF p_IsConfirm = 0
		 THEN
			UPDATE
					InternalEx
			SET
					IsEdit = 3
			WHERE
				Code = p_Code;

			UPDATE
					TransEditRequistTb
			SET
					IsUpdated = 3, IsConfirmed = 1
			WHERE
				ISID = p_Code;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalExValues_LoadDeliveredBranch`;
DELIMITER //
CREATE PROCEDURE `InternalExValues_LoadDeliveredBranch`(IN `p_RecievedBranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			ID AS DBRID,
			BName,
			BranchType
	FROM
			CoBranch
	WHERE
			IsActive = 1
			AND ID <> p_RecievedBranchID
			AND israted=1;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalExValues_PrintRecords`;
DELIMITER //
CREATE PROCEDURE `InternalExValues_PrintRecords`(IN `p_Code` LONGTEXT)
BEGIN


		START TRANSACTION;
		SELECT
				a.Code										 AS 'الرمز',
				a.InsertDate								 AS 'التاريخ',
				a.SenderName								 AS 'الراسل',
				IFNULL('لا يوجد', CONCAT(a.SPhone1, '-', SPhone2)) AS 'هاتف الراسل',
				IFNULL('لا يوجد', a.SenderIDNo)				 AS 'هوية الراسل',
				D.CurrencyName								 AS 'العملة المرسلة',
				a.RecievedName								 AS 'المستلم',
				IFNULL('لا يوجد', CONCAT(a.RPhone1, '-', RPhone2)) AS 'هاتف المستلم',
				IFNULL('لا يوجد', a.RecievedIDNo)			 AS 'هوية المستلم',
				E.CurrencyName								 AS 'العملة المستلمة',
				a.OverallVal								 AS 'القيمة',
				IFNULL('لا يوجد', a.Notes)					 AS 'ملاحظات'
		FROM
				InternalEx AS a
			LEFT OUTER JOIN
				CurrencyTb AS D
					ON a.RecievedCurrencyID = D.ID
			LEFT OUTER JOIN
				CurrencyTb AS E
					ON a.DeliveredCurrencyID = E.ID
		WHERE
				a.Code = p_Code
				AND a.IsActive = 1
		GROUP BY
				a.Code,
				a.InsertDate,
				a.SenderName,
				a.SPhone1,
				a.SPhone2,
				a.RPhone1,
				a.RPhone2,
				a.SenderIDNo,
				a.RecievedName,
				a.RecievedIDNo,
				a.Notes,
				a.OverallVal,
				D.CurrencyName,
				E.CurrencyName
		ORDER BY
				a.InsertDate;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `InternalExValues_PrintRPT`;
DELIMITER //
CREATE PROCEDURE `InternalExValues_PrintRPT`(IN `p_Code` LONGTEXT)
BEGIN


		START TRANSACTION;
		SELECT
				a.Code		   AS 'الرمز',
				a.InsertDate   AS 'التاريخ',
				a.SenderName   AS 'الراسل',
				a.ExVal		   AS 'العمولة',

				CASE 						WHEN a.SPhone1 = '' 							AND a.SPhone2 = '' 							THEN 							'لا يوجد' 						WHEN a.SPhone2 = '' 							THEN 							a.SPhone1 						ELSE 						CONCAT(a.SPhone1, '-', a.SPhone2) 				END			   AS 'هاتف الراسل',

				CASE 						WHEN a.SenderIDNo = '' 							THEN 							'لا يوجد' 						ELSE 						a.SenderIDNo 				END			   AS 'هوية الراسل',

				D.CurrencyName AS 'العملة المرسلة',
				a.RecievedName AS 'المستلم',

				CASE 						WHEN a.RPhone1 = '' 							AND a.RPhone2 = '' 							THEN 							'لا يوجد' 						WHEN a.RPhone2 = '' 							THEN 							a.RPhone1 						ELSE 						CONCAT(a.RPhone1, '-', a.RPhone2) 				END			   AS 'هاتف المستلم',

				CASE 						WHEN a.RecievedIDNo = '' 							THEN 							'لا يوجد' 						ELSE 						a.RecievedIDNo 				END			   AS 'هوية المستلم',

				E.CurrencyName AS 'العملة المستلمة',
				a.OverallVal   AS 'القيمة',

				CASE 						WHEN a.Notes = '' 							THEN 							'لا يوجد' 						ELSE 						a.Notes 				END			   AS 'ملاحظات'
		FROM
				InternalEx AS a
			LEFT OUTER JOIN
				CurrencyTb AS D
					ON a.RecievedCurrencyID = D.ID
			LEFT OUTER JOIN
				CurrencyTb AS E
					ON a.DeliveredCurrencyID = E.ID
		WHERE
				a.Code = p_Code
				AND a.IsActive = 1
		GROUP BY
				a.Code,
				a.InsertDate,
				a.SenderName,
				a.SPhone1,
				a.SPhone2,
				a.RPhone1,
				a.RPhone2,
				a.SenderIDNo,
				a.RecievedName,
				a.RecievedIDNo,
				a.Notes,
				a.OverallVal,
				D.CurrencyName,
				E.CurrencyName,
				a.ExVal
		ORDER BY
				a.InsertDate;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ItarnalAndExtarnalEX_ShowALLRecords`;
DELIMITER //
CREATE PROCEDURE `ItarnalAndExtarnalEX_ShowALLRecords`(IN `p_RecievedBranchID` INT, IN `p_UNAME` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_Type` INT)
BEGIN


		START TRANSACTION;

		IF p_Type=0
			 THEN

				SELECT
						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.sPhone1, '-', a.sPhone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.OverallVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeliveredID = 0 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
            f.UName			   AS 'تسليم',
	 i.SName   AS 'الحالة'
				FROM
						InternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.BranchRecievedID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeliveredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.deliveryplace = e.ID
              LEFT JOIN InternalEx_Stautes i
              ON a.ConfirmType=i.ConfirmType
              					LEFT JOIN
						TB_Users AS f
							ON a.SafeDeliveredID = f.USID
				WHERE
						a.InsertDate >= p_D1
						AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY)
						AND a.IsActive = 1
            AND						((a.BranchRecievedID = p_RecievedBranchID
						OR a.BranchDeliveredID = p_RecievedBranchID)OR p_RecievedBranchID=0)
						AND (SafeRecievedID = p_UNAME OR p_UNAME=0);

			END IF;
		IF p_Type=1
			 THEN
				SELECT
						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
            f.UName			   AS 'تسليم',
 i.SName AS 'الحالة'
				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
                            LEFT JOIN InternalEx_Stautes i
              ON a.ConfirmedType=i.ConfirmType
                            					LEFT JOIN
						TB_Users AS f
							ON a.SafeDeliveredID = f.USID
				WHERE
						a.InsertDate >= p_D1
						AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY)
						AND a.IsActive = 1
                        AND						((a.BranchDeleviredID = p_RecievedBranchID
						OR a.RecievedBranchID = p_RecievedBranchID)OR p_RecievedBranchID=0)
						AND (SafeRecievedID = p_UNAME OR p_UNAME=0);




			END IF;
		IF p_Type=2
			 THEN
				SELECT
						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.Phone1, '-', a.Phone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.CurrRecievedVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeleviredID = 0 OR a.BranchDeleviredID =-1 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
            f.UName			   AS 'تسليم',
 i.SName AS 'الحالة'
				FROM
						ExternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.RecievedBranchID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeleviredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.CityIDTo = e.ID
                            LEFT JOIN InternalEx_Stautes i
              ON a.ConfirmedType=i.ConfirmType
                            					LEFT JOIN
						TB_Users AS f
							ON a.SafeDeliveredID = f.USID
				WHERE
						a.InsertDate >= p_D1
						AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY)
						AND a.IsActive = 1
                        AND						((a.BranchDeleviredID = p_RecievedBranchID
						OR a.RecievedBranchID = p_RecievedBranchID)OR p_RecievedBranchID=0)
						AND (SafeRecievedID = p_UNAME OR p_UNAME=0)

UNION ALL

				SELECT
						a.Code			   AS 'الكود',
						InsertDate		   AS 'التاريخ',
						a.SenderName	   AS 'المرسل',
            CONCAT(a.sPhone1, '-', a.sPhone2) AS SPhone,
						a.RecievedName	   AS 'المستلم',
             CONCAT(a.rPhone1, '-', a.rPhone2) AS RPhone,
						a.OverallVal	   AS 'القيمة',
						a.ExVal			   AS 'العمولة',
						b.BName			   AS 'من',
						CASE 								WHEN a.BranchDeliveredID = 0 									THEN 									e.CityName 								ELSE 								d.BName 						END				   AS 'إلى',
						c.UName			   AS 'الموظف',
            f.UName			   AS 'تسليم',
	 i.SName   AS 'الحالة'
				FROM
						InternalEx AS a
					INNER JOIN
						CoBranch AS b
							ON a.BranchRecievedID = b.ID
					INNER JOIN
						TB_Users AS c
							ON a.SafeRecievedID = c.USID
					LEFT JOIN
						CoBranch AS d
							ON a.BranchDeliveredID = d.ID
					LEFT JOIN
						CitiesTb AS e
							ON a.deliveryplace = e.ID
              LEFT JOIN InternalEx_Stautes i
              ON a.ConfirmType=i.ConfirmType
                            					LEFT JOIN
						TB_Users AS f
							ON a.SafeDeliveredID = f.USID
				WHERE
						a.InsertDate >= p_D1
						AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY)
						AND a.IsActive = 1
            AND						((a.BranchRecievedID = p_RecievedBranchID
						OR a.BranchDeliveredID = p_RecievedBranchID)OR p_RecievedBranchID=0)
						AND (SafeRecievedID = p_UNAME OR p_UNAME=0);

			END IF;

























































































































































































































































































































































































































































































































































































		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `LeaveTB_LeaveStatment`;
DELIMITER //
CREATE PROCEDURE `LeaveTB_LeaveStatment`()
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID) AS `#`,
          a.Code                              ,
          b.EMPNAME                        ,
cb.BName ,
          DateFrom                         ,
          DateTo                         ,
          CASE                   WHEN VacationType = 0                     THEN                     'داخلية'                   ELSE                   'خارجية'           END                               AS VacationType,
          CASE                   WHEN LeaveType = 0                     THEN                     'بمرتب'                   WHEN a.LeaveType = 1                     THEN                     'بدون مرتب'           END                               AS LeaveType,
          c.LeaveName                       AS LeaveName,

          CASE           WHEN IsAbsence = 0           THEN 'لا يوجد'                   WHEN AbsenceID = 0                     THEN                     'بأذن'                   WHEN a.AbsenceID = 1                     THEN                     'بدون أذن'                   ELSE                   'تقديري'           END                               AS AbsenceID,








          ABDays                            AS ABDays,
          IFNULL(DiscountVal,0)                       AS DiscountVal,
          OverallLeaveDays                  AS OverallLeaveDays,
            a.Notes                            ,
          CASE                   WHEN a.EndLeave = 0                     THEN                     'غير منتهية'                   ELSE                   'منتهية'           END                               AS EndLeave
  FROM
          LeaveTB AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      INNER JOIN
        AddLeaveTypeTb AS c
          ON a.LeaveTypeID = c.ID
          LEFT JOIN
          CoBranch cb
          on a.BranchID=cb.ID
  WHERE
          a.IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `LeaveTb_LOADEmployeeToLKP`;
DELIMITER //
CREATE PROCEDURE `LeaveTb_LOADEmployeeToLKP`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			ID,
			EMPNAME,
      Code
	FROM
			EmployeeTb a
	WHERE
			a.BranchID = p_BranchID
			AND a.IsActive = 1

	ORDER BY
			a.EMPNAME;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `LeaveTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `LeaveTB_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID) AS `#`,
          a.Code                              AS `الرمز`,
          b.EMPNAME                         AS `اسم الموظف`,

          DateFrom                          AS `من`,
          DateTo                            AS `إلى`,
          CASE                   WHEN VacationType = 0                     THEN                     'داخلية'                   ELSE                   'خارجية'           END                               AS `طبيعة الإجازة`,
          CASE                   WHEN LeaveType = 0                     THEN                     'بمرتب'                   WHEN a.LeaveType = 1                     THEN                     'بدون مرتب'           END                               AS `نوع الاحتساب`,
          c.LeaveName                       AS `نوع الإجازة`,
          Notes                             AS `ملاحظات`,
          CASE                   WHEN AbsenceID = 0                     THEN                     'بأذن'                   WHEN a.AbsenceID = 1                     THEN                     'بدون أذن'                   ELSE                   'تقديري'           END                               AS `نوع الغياب`,
          CASE                   WHEN IsAbsence = 0                     THEN                     'لا'                   WHEN a.IsAbsence = 1                     THEN                     'نعم'           END                               AS `الغياب`,
          ABDays                            AS `أيام الغياب`,
          DiscountVal                       AS `قيمة الخصم`,
          OverallLeaveDays                  AS `إجمالي الإجازة`,
          CASE                   WHEN a.EndLeave = 0                     THEN                     'غير منتهية'                   ELSE                   'منتهية'           END                               AS `حالة الإجازة`
  FROM
          LeaveTB AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      INNER JOIN
        AddLeaveTypeTb AS c
          ON a.LeaveTypeID = c.ID
  WHERE
          a.IsActive = 1
          AND b.ISACTIVE = 1
          AND c.IsActive = 1
          AND a.BranchID = p_BranchID;


  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `LeaveTB_LOADTODVGToConfirm`;
DELIMITER //
CREATE PROCEDURE `LeaveTB_LOADTODVGToConfirm`(IN `p_LoadType` INT)
BEGIN
DECLARE v_GetDate DATE;
START TRANSACTION;
SET v_GetDate=NOW();
  if p_LoadType=1
   THEN
  SELECT
  ROW_NUMBER() OVER (ORDER BY a.ID) AS '#',
          a.Code,
          a.InsertDate,
          b.EMPNAME,
          a.DateFrom,
          a.DateTo,
          CASE                   WHEN a.LeaveType = 0                     THEN                     'بمرتب'                   ELSE                   'بدون مرتب'           END AS LeaveType,
          a.OverallLeaveDays
  FROM
          LeaveTB a
          INNER JOIN
          EmployeeTb b
          ON a.EMPID=b.ID
  WHERE
          a.IsAccepted = 0
          AND a.IsActive = 1
AND a.IsCalculated=0
AND a.EndLeave=0;
END IF;
  if p_LoadType=2
   THEN
  SELECT
    ROW_NUMBER() OVER (ORDER BY a.ID) AS '#',
          a.Code,
          a.InsertDate,
          b.EMPNAME,
          a.DateFrom,
          a.DateTo,
          CASE                   WHEN a.LeaveType = 0                     THEN                     'بمرتب'                   ELSE                   'بدون مرتب'           END AS LeaveType,
          a.OverallLeaveDays
  FROM
          LeaveTB a
          INNER JOIN
          EmployeeTb b
          ON a.EMPID=b.ID
  WHERE
          a.IsAccepted = 1
          AND a.IsActive = 1
AND a.IsCalculated=0
AND a.DateTo<v_GetDate
AND a.EndLeave=0;
END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `LeaveTB_Select`;
DELIMITER //
CREATE PROCEDURE `LeaveTB_Select`(IN `p_Code` VARCHAR(50))
BEGIN
START TRANSACTION;

  SELECT
          a.ID,
          a.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                 AS InsertDate,
          DATE_FORMAT(a.InsertDate, '%y')                                 AS YaerDate,
          DATE_FORMAT(a.InsertDate, '%m')                                 AS MDate,
          DATE_FORMAT(a.InsertDate, '%d')                                 AS DDate,
          EMPID,
          b.CODE AS EMPCODE,
          a.BranchID AS DBRID,
          DATE_FORMAT(DateFrom, '%Y/%m/%d')                                     AS DateFrom,
          DATE_FORMAT(DateTo, '%Y/%m/%d')                                       AS DateTo,
          VacationType,
          LeaveType,
          CASE WHEN a.LeaveType = 0 THEN 'إجازة مدفوعة الراتب'WHEN a.LeaveType=1 THEN 'إجازة غير مدفوعة الراتب'WHEN a.LeaveType=2 THEN 'غياب بدون اذن' END AS RptLeaveType,
          LeaveTypeID,
          InOutType,
          a.notes,
          AbsenceID,
          IsAbsence,
          ABDays,
          DiscountVal,
          OverallLeaveDays,
          b.EMPNAME,
          d.BName,
          CASE                   WHEN VacationType = 0                     THEN                     'داخلية'                   ELSE                   'خارجية'           END                                                                AS `طبيعة الإجازة`,
          CASE                   WHEN VacationType = 0                     THEN                     'نعم'                   ELSE                   'لا'           END                                                                AS VType1,
          CASE                   WHEN VacationType = 0                     THEN                     'لا'                   ELSE                   'نعم'           END                                                                AS VType2,
          CASE                   WHEN LeaveType = 0                     THEN                     'بمرتب'                   WHEN a.LeaveType = 1                     THEN                     'بدون مرتب'           END                                                                AS `نوع الاحتساب`,
          c.LeaveName                                                        AS `نوع الإجازة`,
          CASE                   WHEN AbsenceID = 0                     THEN                     'بأذن'                   WHEN a.AbsenceID = 1                     THEN                     'بدون أذن'                   ELSE                   'تقديري'           END                                                                AS `نوع الغياب`,
          CASE                   WHEN IsAbsence = 0                     THEN                     'لا'                   WHEN a.IsAbsence = 1                     THEN                     'نعم'           END                                                                AS `الغياب`,
          CASE                   WHEN a.EndLeave = 0                     THEN                     'غير منتهية'                   ELSE                   'منتهية'           END                                                                AS `حالة الإجازة`,
          IsDiscount,
          e.ECNAME,
         a.EndLeave,

          TIMESTAMPDIFF(DAY, DateFrom, a.DateTo) + 1  AS LDays,
         CASE WHEN TIMESTAMPDIFF(DAY, DateFrom, a.DateTo) + 1 >10 THEN CONCAT(CAST(TIMESTAMPDIFF(DAY, DateFrom, a.DateTo) + 1 AS CHAR), ' يوم ') ELSE CONCAT(CAST(TIMESTAMPDIFF(DAY, DateFrom, a.DateTo) + 1 AS CHAR), ' أيام ') END AS RPTLDays ,
          CONCAT('اليوم', ':', ' ', Case DAYOFWEEK(DateFrom)     WHEN 1 THEN 'الأحد'     WHEN 2 THEN 'الاثنين'     WHEN 3 THEN 'الثلاثاء'     WHEN 4 THEN 'الأربعاء'     WHEN 5 THEN 'الخميس'     WHEN 6 THEN 'الجمعة'     WHEN 7 THEN 'السبت'   END, ' ', 'الموافق', ':', ' ', DATE_FORMAT(a.DateFrom, '%Y/%m/%d'), 'م') AS DayName,

            CONCAT('اليوم', ':', ' ', Case DAYOFWEEK(DATE_ADD(DateTo, INTERVAL 1 DAY))     WHEN 1 THEN 'الأحد'     WHEN 2 THEN 'الاثنين'     WHEN 3 THEN 'الثلاثاء'     WHEN 4 THEN 'الأربعاء'     WHEN 5 THEN 'الخميس'     WHEN 6 THEN 'السبت'     WHEN 7 THEN 'السبت'   END, ' ', 'الموافق', ':', ' ', case DAYOFWEEK(DATE_ADD(DateTo, INTERVAL 1 DAY)) WHEN 6 THEN DATE_FORMAT(DATE_ADD(DateTo, INTERVAL 2 DAY), '%Y/%m/%d') ELSE DATE_FORMAT(DATE_ADD(DateTo, INTERVAL 1 DAY), '%Y/%m/%d') END, 'م') AS DayName2,
          a.IsActive,
          a.ManagerOpinion


  FROM
          LeaveTB AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      INNER JOIN
        AddLeaveTypeTb AS c
          ON a.LeaveTypeID = c.ID
      INNER JOIN
        CoBranch AS d
          ON a.BranchID = d.ID
      INNER JOIN
        EmployeeClassificationTb e
          ON b.CLASSIFICATION = e.ID
  WHERE
          a.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MeasurmentUnitTb_LoadToLSBOX`;
DELIMITER //
CREATE PROCEDURE `MeasurmentUnitTb_LoadToLSBOX`(IN `p_ID` INT)
BEGIN
START TRANSACTION;

  SELECT
          ID,
          MUName
  FROM
          ContractDB.MeasurmentUnitTb
  WHERE
          ID = p_ID
  ORDER BY
          MUName;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MembersCalculationTb_CheckMonthSelected`;
DELIMITER //
CREATE PROCEDURE `MembersCalculationTb_CheckMonthSelected`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_AssoID` INT)
BEGIN
START TRANSACTION;

	SELECT
			a.SALARYMONTH,
			a.SALARYEAR,
			a.IsIndivdual
	FROM
			MembersCalculationTb  AS a
	WHERE
			a.SALARYMONTH = p_SALARYMONTH
			AND a.SALARYEAR = p_SALARYEAR
			AND a.IsIndivdual = 0
			AND a.AssoID = p_AssoID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MembersCalculationTb_Insert`;
DELIMITER //
CREATE PROCEDURE `MembersCalculationTb_Insert`(IN `p_INSERTDATE` DATE, IN `p_EMPID` INT, IN `p_SalaryVal` DECIMAL(12,3), IN `p_SALARYTOTAL` DECIMAL(12,3), IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_CodeID` LONGTEXT, IN `p_SafeID` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_MeccID` BIGINT, IN `p_SalaryCalc` INT, IN `p_AssoID` INT)
BEGIN
DECLARE v_SalariesAccID BIGINT;
DECLARE v_EMPIDAccID BIGINT;
DECLARE v_IncreaseAccID BIGINT;
DECLARE v_EMPSalaryVal DECIMAL(12, 3);
DECLARE v_MovType LONGTEXT;
DECLARE v_Code VARCHAR(50);
DECLARE v_ADVPMNTAccID BIGINT;
DECLARE v_BranchID INT;
DECLARE v_DeserveAssoAccID BIGINT;
DECLARE v_currentRow INT DEFAULT 0;
DECLARE v_date DATETIME DEFAULT EOMONTH(NOW());
DECLARE v_Currdate DATETIME DEFAULT NOW();


  START TRANSACTION;



  SELECT at.ID INTO v_BranchID FROM
          CoBranch at
  WHERE
          at.IsMain = 1;
  SELECT a.AccIDPartic INTO v_DeserveAssoAccID FROM
          ASSOCIATIONNAMETB AS a
  WHERE
          a.ID = p_AssoID;
  SELECT a.AssValue INTO p_SalaryVal FROM
          ASSOCIATIONNAMETB a
  WHERE
          a.ID = p_AssoID;
  SET v_currentRow = v_currentRow + 1;
SET p_CodeID = CONCAT(YEAR(NOW()), ' - ', MONTH(NOW()), ' - ', v_BranchID, ' - ', p_AssoID, ' - ', v_currentRow);
  SET p_SalaryCalc = 1;
  IF p_SalaryCalc = 1
     THEN
      INSERT INTO MembersCalculationTb
            (
              InsertDate,
              MEMBERID,
              AssVal,
              SALARYTOTAL,
              SALARYMONTH,
              SALARYEAR,
              CodeID,
              IsActive,
              IsIndivdual,
              AssoID
            )
      VALUES
              (
                p_INSERTDATE, p_EMPID, p_SalaryVal, p_SALARYTOTAL, p_SALARYMONTH, p_SALARYEAR, p_CodeID, 1, p_IsIndivdual, p_AssoID
              );
SET v_MovType = CONCAT('مستحق اشتراك شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_Code = CONCAT(CAST(p_SALARYEAR AS CHAR), ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', '21', ' - ', CAST(p_EMPID AS CHAR));
      INSERT INTO ExSyAccounts_AccSafeActivityTb
            (
              SafeID,
              Debit,
              Credit,
              InsertDate,
              ISID,
              IsActive,
              TypeID,
              OperationTypeID,
              AccBranchID,
              AccIDFrom,
              AccIDTo,
              IsConfirmed,
              IsCanceled,
              MovementType,
              CurrencyID,
              DailyClosed,
              SafeIDDailyClose,
              SafeIDMovement
            )

      VALUES
              (
                p_SafeID, p_SalaryVal, 0.000, p_INSERTDATE, p_CodeID, 1, 21, 51, v_BranchID, p_MeccID, v_DeserveAssoAccID, 1, 0, v_MovType, 1, 0, 0, v_MovType
              );

      INSERT INTO ExSyAccounts_AccSafeActivityTb
            (
              SafeID,
              Debit,
              Credit,
              InsertDate,
              ISID,
              IsActive,
              TypeID,
              OperationTypeID,
              AccBranchID,
              AccIDFrom,
              AccIDTo,
              IsConfirmed,
              IsCanceled,
              MovementType,
              CurrencyID,
              DailyClosed,
              SafeIDDailyClose
            )
      VALUES
              (
                p_SafeID, 0.000, p_SalaryVal, p_INSERTDATE, p_CodeID, 1, 21, 51, v_BranchID, v_DeserveAssoAccID, p_MeccID, 1, 0, v_MovType, 1, 0, 0
              );

    END IF;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MembersCalculationTb_LOADDATATOCALC`;
DELIMITER //
CREATE PROCEDURE `MembersCalculationTb_LOADDATATOCALC`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_ASSOCIATIONID` INT)
BEGIN
START TRANSACTION;

	SELECT
			b.MEMBERNAME AS 'الاسم',
			a.AssValue	 AS 'قيمة الاشتراك',
			b.ID,
			b.ASSOCIATIONID,
			b.AccID		 AS MeAccID,
			a.AccID,
			a.ASSOACCID
			,b.PHONE
	FROM
			ASSOCIATIONNAMETB a
		LEFT OUTER JOIN
			ASSOCIATIONTB AS b
				ON a.ID = b.ASSOCIATIONID
	WHERE
			b.IsActive = 1
			AND NOT EXISTS (SELECT
						c.MEMBERID
				FROM
						MembersCalculationTb AS c
				WHERE
						c.MEMBERID = b.ID
						AND c.SALARYMONTH = p_SALARYMONTH
						AND c.SALARYEAR = p_SALARYEAR)
			AND b.ASSOCIATIONID = p_ASSOCIATIONID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ModifyingAccountingEntries_Insert`;
DELIMITER //
CREATE PROCEDURE `ModifyingAccountingEntries_Insert`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_FirstAccMain` INT, IN `p_FirstAccParent` BIGINT, IN `p_FirstAccID` BIGINT, IN `p_SecondAccMain` INT, IN `p_SecondAccParent` BIGINT, IN `p_SecondAccID` BIGINT, IN `p_CurrencyID` INT, IN `p_DebitVal` DECIMAL(18,3), IN `p_CreditVal` DECIMAL(18,3), IN `p_Notes` LONGTEXT, IN `p_MovmentType` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_SafeID` INT, IN `p_DepitValCheck` TINYINT(1), IN `p_CreditValCheck` TINYINT(1))
BEGIN
DECLARE v_DataBaseType Bit DEFAULT 0;
DECLARE v_FAcc BigInt;
DECLARE v_SAcc Bigint;


		START TRANSACTION;



		 SELECT Accid INTO v_FAcc FROM AccountsTb Where (AccParent Like '101090%' OR AccParent=2010801 OR AccParent=2010702) AND Accid=p_FirstAccID;
		  SELECT Accid INTO v_SAcc FROM AccountsTb Where (AccParent Like '101090%' OR AccParent=2010801 OR AccParent=2010702) AND Accid=p_SecondAccID;


		 IF (v_FAcc=p_FirstAccID OR v_FAcc=p_SecondAccID)
		  THEN
SET v_DataBaseType=1;
		 END IF;
		 IF  (v_SAcc=p_FirstAccID OR v_SAcc=p_SecondAccID)
		  THEN
SET v_DataBaseType=1;
		 END IF;



		INSERT INTO `ModifyingAccountingEntries_TB`
										 (`Code`
           ,`InsertDate`
           ,`BranchID`
           ,`FirstAccMain`
           ,`FirstAccParent`
           ,`FirstAccID`
           ,`SecondAccMain`
           ,`SecondAccParent`
           ,`SecondAccID`
           ,`CurrencyID`
           ,`DeapitVal`
           ,`CreaditVal`
           ,`MovmentType`
           ,`Notes`
           ,`IsActive`
           ,`UserInsert`)
								VALUES
										(
											p_Code, p_InsertDate, p_BranchID, p_FirstAccMain, p_FirstAccParent,p_FirstAccID,p_SecondAccMain,p_SecondAccParent,p_SecondAccID,
											 p_CurrencyID, p_DebitVal,p_CreditVal,p_MovmentType,p_Notes,1, p_SafeID
										);

                   IF v_DataBaseType=0
							 THEN
							IF p_DepitValCheck=0
							 THEN

								INSERT INTO ExSyAccounts_AccSafeActivityTb
										(
											SafeID,
											Debit,
											Credit,
											InsertDate,
											`Description`,
											ISID,
											IsActive,
											TypeID,
											OperationTypeID,
											AccBranchID,
											AccIDFrom,
											AccIDTo,
											IsConfirmed,
											IsCanceled,
											MovementType,
											CurrencyID,
											DailyClosed,
											SafeIDDailyClose,
											Note,
											SafeIDMovement
										)
								VALUES
										(
											p_SafeID, p_DebitVal, 0.000, p_InsertDate, p_Notes, p_Code, 1, 35, 65, p_BranchID, p_FirstAccID, p_SecondAccID, 1, 0, p_MovmentType, p_CurrencyID, 0, 0, p_Notes, CONCAT('تعديل قيد محاسبي', CHAR(13), p_Code)
											);
											END IF;
											If p_CreditValCheck=0
											 THEN

											INSERT INTO ExSyAccounts_AccSafeActivityTb
										(
											SafeID,
											Debit,
											Credit,
											InsertDate,
											`Description`,
											ISID,
											IsActive,
											TypeID,
											OperationTypeID,
											AccBranchID,
											AccIDFrom,
											AccIDTo,
											IsConfirmed,
											IsCanceled,
											MovementType,
											CurrencyID,
											DailyClosed,
											SafeIDDailyClose,
											Note,
											SafeIDMovement
										)
								VALUES
										(
											p_SafeID, 0.000,p_CreditVal,  p_InsertDate, p_Notes, p_Code, 1, 35, 65, p_BranchID, p_SecondAccID, p_FirstAccID, 1, 0, p_MovmentType, p_CurrencyID, 0, 0, p_Notes, CONCAT('تعديل قيد محاسبي', CHAR(13), p_Code)
											);
										END IF;



END IF;


                   IF v_DataBaseType=1
							 THEN
							IF p_DepitValCheck=0
							 THEN
								INSERT INTO ExAssociationAct_AssActivityTb
										(
											SafeID,
											Debit,
											Credit,
											InsertDate,
											`Description`,
											ISID,
											IsActive,
											TypeID,
											OperationTypeID,
											AccBranchID,
											AccIDFrom,
											AccIDTo,
											IsConfirmed,
											IsCanceled,
											MovementType,
											CurrencyID,
											DailyClosed,
											SafeIDDailyClose,
											Note,
											SafeIDMovement
										)
								VALUES
												(
											p_SafeID, p_DebitVal, 0.000, p_InsertDate, p_Notes, p_Code, 1, 35, 65, p_BranchID, p_FirstAccID, p_SecondAccID, 1, 0, p_MovmentType, p_CurrencyID, 0, 0, p_Notes, CONCAT('تعديل قيد محاسبي', CHAR(13), p_Code)
											);
											END IF;
											IF p_CreditValCheck=0
							 THEN

											INSERT INTO ExAssociationAct_AssActivityTb
										(
											SafeID,
											Debit,
											Credit,
											InsertDate,
											`Description`,
											ISID,
											IsActive,
											TypeID,
											OperationTypeID,
											AccBranchID,
											AccIDFrom,
											AccIDTo,
											IsConfirmed,
											IsCanceled,
											MovementType,
											CurrencyID,
											DailyClosed,
											SafeIDDailyClose,
											Note,
											SafeIDMovement
										)
								VALUES
										(
											p_SafeID, 0.000,p_CreditVal,  p_InsertDate, p_Notes, p_Code, 1, 35, 65, p_BranchID, p_SecondAccID, p_FirstAccID, 1, 0, p_MovmentType, p_CurrencyID, 0, 0, p_Notes, CONCAT('تعديل قيد محاسبي', CHAR(13), p_Code)
											);

											END IF;
						END IF;



   COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ModifyingAccountingEntries_TB_MaxID`;
DELIMITER //
CREATE PROCEDURE `ModifyingAccountingEntries_TB_MaxID`(IN `p_BranchID` INT, IN `p_AccID` INT)
BEGIN
DECLARE v_Code LONGTEXT;


		START TRANSACTION;
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '0', '35', '-', CAST(p_AccID AS CHAR), '-', CAST(`ModifyingAccountingEntries_TB_GetMaxIDCode`() AS CHAR));
		SELECT
				v_Code									AS Code,
				`ModifyingAccountingEntries_TB_GetMaxIDCode`() AS ID;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MPAMNTWDMEMBERTB_Insert`;
DELIMITER //
CREATE PROCEDURE `MPAMNTWDMEMBERTB_Insert`(IN `p_InsertDate` DATE, IN `p_Code` LONGTEXT, IN `p_MEMBERID` BIGINT, IN `p_Credit` DECIMAL(12,3), IN `p_SafeID` INT, IN `p_TypeID` INT, IN `p_CodeID` BIGINT, IN `p_MBACCID` BIGINT, IN `p_AssID` BIGINT, IN `p_SafeAccID` BIGINT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), IN `p_Notes` LONGTEXT, IN `p_PaidFor` LONGTEXT, IN `p_Phone` LONGTEXT, IN `p_IDNo` VARCHAR(50), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_AssAccID   BIGINT;
DECLARE v_MBAssAccID BIGINT;
DECLARE v_BranchID   INT;
DECLARE v_SafeMOV    LONGTEXT;
DECLARE v_MEMBERNAME LONGTEXT;
DECLARE v_MEMBERNOTE LONGTEXT;
DECLARE v_ASSNAME    LONGTEXT;
DECLARE v_AccID      INT;
DECLARE v_AssoName LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


    START TRANSACTION;

IF p_MEMBERID=0
 THEN

SET p_MBACCID=0;
  END IF;

    SELECT a.MEMBERNAME, a.AccID INTO v_MEMBERNAME, v_AccID FROM
            ASSOCIATIONTB a
    WHERE
            ID = p_MEMBERID;

    SELECT ID INTO v_BranchID FROM
            CoBranch cb
    WHERE
            cb.IsMain = 1;
    SELECT at.AccID INTO v_AssAccID FROM
            AccountsTb at
        INNER JOIN
          ASSOCIATIONNAMETB a
            ON at.AccID = a.ASSOACCID
    WHERE
            a.ID = p_AssID;
    SELECT a.AccIDPartic INTO v_MBAssAccID FROM
            ASSOCIATIONNAMETB a
    WHERE
            a.ID =p_AssID;
    SELECT a.ASSNAME INTO v_ASSNAME FROM
            ASSOCIATIONNAMETB a
    WHERE
            a.ID = p_AssID;
    IF p_TypeID = 22
       THEN
        IF p_IsUpdate = 0
           THEN

            SELECT Code INTO v_GETID FROM
                    MPAMNTWDMEMBERTB AS a
            WHERE
                    a.Code = p_Code;
            IF p_Code = v_GETID
               THEN
                SET p_MSGSTatues = 0;
                SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
                ROLLBACK;
                LEAVE proc;
              END IF;

            IF p_MBACCID <> v_AccID
               THEN
                SET p_MSGSTatues = 2;
                SET p_MsgBox = 'عذرا الرجاء إعادة اختيار مشترك الجمعية لتتم عملية الحفظ';
                ROLLBACK;
                LEAVE proc;
              END IF;
SET v_SafeMOV = CONCAT('قبض من', ' ', v_MEMBERNAME, ' ', 'اشتراك جمعية');
            INSERT INTO MPAMNTWDMEMBERTB
                  (
                    InsertDate,
                    Code,
                    MEMBERID,
                    MBACCID,
                    AssID,
                    Debit,
                    Credit,
                    SafeID,
                    SafeAccID,
                    AssAccID,
                    CodeID,
                    TypeID,
                    IsActive,
                    Notes
                  )
                SELECT
                        p_InsertDate,
                        p_Code,
                        p_MEMBERID,
                        p_MBACCID,
                        p_AssID,
                        0.000,
                        p_Credit,
                        p_SafeID,
                        p_SafeAccID,
                        v_AssAccID,
                        p_CodeID,
                        p_TypeID,
                        1,
                        p_Notes;

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, p_SafeAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);
SET v_MEMBERNOTE = CONCAT('قبض اشتراك جمعية', ' ', v_ASSNAME);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, p_MBACCID, p_SafeAccID, 1, 0, p_Notes, 1, 0, 0, v_MEMBERNOTE);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, v_MBAssAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, v_AssAccID, p_MBACCID, 1, 0, p_Notes, 1, 0, 0, v_SafeMOV);
          END IF;
        IF p_IsUpdate = 1
           THEN
SET v_SafeMOV = CONCAT('تصحيح أمر قبض من', ' ', v_MEMBERNAME, ' ', 'مقابل شتراك جمعية');
            UPDATE
                    MPAMNTWDMEMBERTB
            SET
                    IsActive = 0
            WHERE
              Code = p_Code;

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, p_SafeAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);
SET v_MEMBERNOTE = CONCAT('تصحيح خطأ اشتراك جمعية', ' ', v_ASSNAME);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, p_MBACCID, p_SafeAccID, 1, 0, p_Notes, 1, 0, 0, v_MEMBERNOTE);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, v_MBAssAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);
            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 52, v_BranchID, v_AssAccID, p_MBACCID, 1, 0, p_Notes, 1, 0, 0, v_SafeMOV);
          END IF;
      END IF;
    IF p_TypeID = 23
       THEN
        SELECT a.ASSNAME INTO v_SafeMOV FROM
                ASSOCIATIONNAMETB a
        WHERE
                ID = p_AssID;

        IF p_IsUpdate = 0
           THEN
SET v_SafeMOV = CONCAT('صرف من جمعية', ' ', v_SafeMOV);
            INSERT INTO MPAMNTWDMEMBERTB
                  (
                    InsertDate,
                    Code,
                    MEMBERID,
                    MBACCID,
                    AssID,
                    Debit,
                    Credit,
                    SafeID,
                    SafeAccID,
                    AssAccID,
                    CodeID,
                    TypeID,
                    IsActive,
                    Notes,
                    PaidFor,
                    Phone,
                    IDNo
                  )
                SELECT
                        p_InsertDate,
                        p_Code,
                        p_MEMBERID,
                        p_MBACCID,
                        p_AssID,
                        0.000,
                        p_Credit,
                        p_SafeID,
                        p_SafeAccID,
                        v_AssAccID,
                        p_CodeID,
                        p_TypeID,
                        1,
                        p_Notes,
                        p_PaidFor,
                        p_Phone,
                        p_IDNo;

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 53, v_BranchID, p_SafeAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 53, v_BranchID, v_AssAccID, p_MBACCID, 1, 0, p_Notes, 1, 0, 0, v_SafeMOV);
          END IF;
        IF p_IsUpdate = 1
           THEN
SET v_SafeMOV = CONCAT('تصحيح خطأ في قيمة صرف لـ', ' ', v_SafeMOV);
            UPDATE
                    MPAMNTWDMEMBERTB
            SET
                    IsActive = 0
            WHERE
              Code = p_Code;

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, p_Credit, 0.000, p_InsertDate, '', p_Code, p_TypeID, 53, v_BranchID, p_SafeAccID, p_MBACCID, 1, 0, '', 1, 0, 0, v_SafeMOV);

            CALL ExSyAccounts_AccSafeActivityTb_Insert(p_SafeID, 0.000, p_Credit, p_InsertDate, '', p_Code, p_TypeID, 53, v_BranchID, v_AssAccID, p_MBACCID, 1, 0, p_Notes, 1, 0, 0, v_SafeMOV);
          END IF;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MPAMNTWDMEMBERTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `MPAMNTWDMEMBERTB_LOADTODVG`(IN `p_TypeID` TINYINT UNSIGNED, IN `p_AssID` INT)
BEGIN
START TRANSACTION;
	IF p_TypeID = 22
		 THEN
			SELECT
					A.Code		 AS 'الرمز',
					A.InsertDate 'التاريخ',
					B.MEMBERNAME 'الاسم',
					A.Debit		 'مدين',
					A.Credit	 'دائن',
					A.TypeID,
					A.AssID,
					A.SafeID,
					A.MBACCID
			FROM
					MPAMNTWDMEMBERTB AS A
				INNER JOIN
					ASSOCIATIONTB AS B
						ON A.MEMBERID = B.ID
			WHERE
					A.AssID = p_AssID
					AND TypeID = p_TypeID
					AND A.IsActive = 1;
		END IF;
	IF p_TypeID = 23
		 THEN
			SELECT
					A.Code		 AS 'الرمز',
					A.InsertDate 'التاريخ',
					A.PaidFor	 'الاسم',
					A.Debit		 'مدين',
					A.Credit	 'دائن',
					A.TypeID,
					A.AssID,
					A.SafeID
			FROM
					MPAMNTWDMEMBERTB AS A
				INNER JOIN
					ASSOCIATIONNAMETB AS B
						ON A.AssID = B.ID
			WHERE
					A.AssID = p_AssID
					AND TypeID = p_TypeID
					AND A.IsActive = 1;
		END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MPAMNTWDMEMBERTB_MaxID`;
DELIMITER //
CREATE PROCEDURE `MPAMNTWDMEMBERTB_MaxID`(IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
DECLARE v_Code LONGTEXT;


	START TRANSACTION;
SET v_Code = CONCAT(CAST(p_TypeID AS CHAR), '-', CAST(`MPAMNTWDMEMBERTB_GetMaxCODEID`(p_TypeID) AS CHAR));
	SELECT
			v_Code										   AS Code,
			`MPAMNTWDMEMBERTB_GetMaxCODEID`(p_TypeID) AS ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `MPAMNTWDMEMBERTB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `MPAMNTWDMEMBERTB_SelectByCode`(IN `p_Code` LONGTEXT, IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
DECLARE v_EMPCUSTID INT;
START TRANSACTION;
	IF p_TypeID = 22
		 THEN
			SELECT
					a.Code,
					a.InsertDate,
					B.MEMBERNAME AS MEMBERNAME,
					CASE 							WHEN a.Debit > a.Credit 								THEN 								a.Debit 							ELSE 							a.Credit 					END			 AS Credit,
					a.SafeID,
					a.IsActive,
					a.TypeID,
					a.AssID,
					CASE 							WHEN a.Notes = '' 								THEN 								'لا يوجد' 							ELSE 							a.Notes 					END			 AS Notes,
					a.MEMBERID,
					d.UName
			FROM
					MPAMNTWDMEMBERTB AS a
				LEFT JOIN
					ASSOCIATIONTB AS B
						ON a.MEMBERID = B.ID
				LEFT OUTER JOIN
					TB_Users AS d
						ON a.SafeID = d.USID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;
	IF p_TypeID = 23
		 THEN
			SELECT
					a.Code,
					a.InsertDate,
					a.PaidFor AS MEMBERID,
					a.PHONE,
					a.IDNO,
					CASE 							WHEN a.Debit > a.Credit 								THEN 								a.Debit 							ELSE 							a.Credit 					END		  AS Credit,
					a.SafeID,
					a.IsActive,
					a.TypeID,
					a.AssID,
					CASE 							WHEN a.Notes = '' 								THEN 								'لا يوجد' 							ELSE 							a.Notes 					END		  AS Notes,
					d.UName
			FROM
					MPAMNTWDMEMBERTB AS a
				LEFT OUTER JOIN
					TB_Users AS d
						ON a.SafeID = d.USID
			WHERE
					a.TypeID = p_TypeID
					AND a.Code = p_Code
			ORDER BY
					Code;
		END IF;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NationalityTb_Delete`;
DELIMITER //
CREATE PROCEDURE `NationalityTb_Delete`(IN `p_ID` INT)
BEGIN
START TRANSACTION;
	UPDATE
			NationalityTb
	SET
			NationalityTb.IsActive = 1
	WHERE
		(   ID = p_ID
			OR p_ID IS NULL);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NationalityTb_Insert`;
DELIMITER //
CREATE PROCEDURE `NationalityTb_Insert`(IN `p_ID` INT, IN `p_NATNAME` LONGTEXT, IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO NationalityTb
					(
						NATNAME,
						ISACTIVE
					)
			VALUES
					(
						p_NATNAME, 1
					);
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					NationalityTb
			SET
					NATNAME = p_NATNAME, ISACTIVE = 1
			WHERE
				(   ID = p_ID
					OR p_ID IS NULL);
		END IF;
	COMMIT;
END //
DELIMITER ;

