DROP PROCEDURE IF EXISTS `New_CurrenciesBuyandsellTB_loadtoFrm`;
DELIMITER //
CREATE PROCEDURE `New_CurrenciesBuyandsellTB_loadtoFrm`(IN `p_ID` LONGTEXT)
BEGIN
DECLARE v_IsDefalut BIT;


	SELECT CMT.IsDefault INTO v_IsDefalut FROM
