DROP PROCEDURE IF EXISTS `New_get_BracuNetBurnnc`;
DELIMITER //
CREATE PROCEDURE `New_get_BracuNetBurnnc`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT, IN `p_CountryID` INT, IN `p_BankID` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE v_BNKAACID BIGINT DEFAULT 0;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;



      SELECT IFNULL(ID, 0) INTO v_BNKAACID FROM
              BBranchTb bt
      WHERE
              (       bt.AccID = p_BankID
                      OR bt.AccID = 0);
      SELECT b.CurCode INTO v_CurrencyCode FROM
              CurrencyMainTb AS b
      WHERE
              b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
      SELECT a.CurrencyPower INTO v_CurrencyPower FROM
              NewCurrencyPriceOwnDetailsTb AS a
          INNER JOIN
            NewCurrencyPricesOwnTb AS b
              ON a.CPID = b.ID
      WHERE
              a.CurrencyIDFrom = 1
              AND a.CurrencyIDTo = p_CurrencyFrom
              AND b.PriceType = p_ISbaunk
              AND b.CountryID = p_CountryID
              AND b.BankID = v_BNKAACID;
      IF (p_ISbaunk = 0
        OR
        p_ISbaunk = 1)
         THEN
          IF v_CurrencyPower = 1
             THEN
              SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = p_ISbaunk
                      AND b.CountryID = p_CountryID
                      AND b.BankID = 0;




              SELECT x.BuyPrice INTO v_ValueDev FROM
                      (   SELECT
                                  b.BuyPrice AS BuyPrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = 0

                          UNION

                          SELECT
                                  CASE                                           WHEN CurrencyPower = 0                                             THEN                                             b.SalePrice * v_CurrencyBuyPrice                                           ELSE                                           v_CurrencyBuyPrice / SalePrice                                   END AS BuyPrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo <> p_CurrencyFrom
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = 0) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          IF v_CurrencyPower = 0
             THEN
              SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = p_ISbaunk
                      AND b.CountryID = p_CountryID
                      AND b.BankID = 0;

              SELECT x.BuyPrice INTO v_ValueDev FROM
                      (   SELECT
                                  CASE                                           WHEN CurrencyPower = 1                                             THEN                                             b.BuyPrice                                           ELSE                                           1 / BuyPrice                                   END AS BuyPrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = 0


                          UNION

                          SELECT
                                  1 / (v_CurrencyBuyPrice * SalePrice) AS BuyPrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = 0) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          SET p_Purchaseprice = New_Get_Purchaseprice(p_CurrencyTo, p_CurrencyFrom, p_ISbaunk, p_CountryID, p_BankID);
        END IF;


      IF p_ISbaunk = 3
         THEN

          IF v_CurrencyPower = 1
             THEN
              SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = p_ISbaunk
                      AND b.CountryID = p_CountryID
                      AND b.BankID = v_BNKAACID;


              SELECT
                      v_CurrencyBuyPrice;
              SELECT x.BankBuyPrice INTO v_ValueDev FROM
                      (   SELECT
                                  b.BuyPrice AS BankBuyPrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = v_BNKAACID

                          UNION

                          SELECT
                                  CASE                                           WHEN CurrencyPower = 0                                             THEN                                             b.SalePrice * v_CurrencyBuyPrice                                           ELSE                                           v_CurrencyBuyPrice / b.SalePrice                                   END AS BankSalePrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo <> p_CurrencyFrom
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = v_BNKAACID) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          IF v_CurrencyPower = 0
             THEN
              SELECT a.SalePrice, a.BuyPrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyFrom
                      AND b.PriceType = p_ISbaunk
                      AND b.CountryID = p_CountryID
                      AND b.BankID = v_BNKAACID;

              SELECT x.BuyPrice INTO v_ValueDev FROM
                      (   SELECT
                                  CASE                                           WHEN CurrencyPower = 1                                             THEN                                             b.BuyPrice                                           ELSE                                           1 / b.BuyPrice                                   END AS BuyPrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = p_CurrencyTo
                                  AND b.CurrencyIDTo = p_CurrencyFrom
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = v_BNKAACID


                          UNION

                          SELECT
                                  1 / (v_CurrencyBuyPrice * b.SalePrice) AS BuyPrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID = b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.PriceType = p_ISbaunk
                                  AND a.CountryID = p_CountryID
                                  AND a.BankID = v_BNKAACID) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          SET p_Purchaseprice = New_Get_Purchaseprice(p_CurrencyTo, p_CurrencyFrom, p_ISbaunk, p_CountryID, v_BNKAACID);
        END IF;
      SELECT
              p_BPrice11,
              p_Purchaseprice;
      COMMIT;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `New_get_BracuNetBurnnc_SalePrice`;
DELIMITER //
CREATE PROCEDURE `New_get_BracuNetBurnnc_SalePrice`(IN `p_CurrencyFrom` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, INOUT `p_BPrice11` LONGTEXT, INOUT `p_Purchaseprice` DOUBLE, IN `p_ISbaunk` INT, IN `p_CountryID` INT, IN `p_BankID` INT)
BEGIN
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_CurrencyPower BIT;
DECLARE v_ValueDev DECIMAL(15, 10);
DECLARE v_CurrencyCode VARCHAR(50);
DECLARE v_BNKAACID BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;



      SELECT IFNULL(ID, 0) INTO v_BNKAACID FROM
              BBranchTb bt
      WHERE
              (       bt.AccID = p_BankID
                      OR bt.AccID = 0);
      SELECT b.CurCode INTO v_CurrencyCode FROM
              CurrencyMainTb AS b
      WHERE
              b.ID = p_CurrencyTo
 ORDER BY b.ID DESC LIMIT 1;
      SELECT a.CurrencyPower INTO v_CurrencyPower FROM
              NewCurrencyPriceOwnDetailsTb AS a
              INNER JOIN NewCurrencyPricesOwnTb AS b ON a.CPID=b.ID
      WHERE
              a.CurrencyIDFrom = 1
              AND a.CurrencyIDTo = p_CurrencyTo
              AND b.PriceType=p_ISbaunk
              AND b.CountryID=p_CountryID
               AND (b.BankID = v_BNKAACID OR v_BNKAACID IS null);
  IF (p_ISbaunk = 0 OR p_ISbaunk=1)
   THEN


          IF v_CurrencyPower = 1
             THEN




              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  b.SalePrice AS SalePrice

                          FROM
                                  `NewCurrencyPricesOwnTb` AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON  a.ID =b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk) AS x;


              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;

          IF v_CurrencyPower = 0
             THEN

              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  CASE                                           WHEN CurrencyPower = 1                                             THEN                                             b.SalePrice                                           ELSE                                           1 / SalePrice                                   END AS SalePrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                   ON  a.ID=b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON a.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                   AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk

) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          SET p_Purchaseprice = NewGet_PurchaseSalePrice(p_CurrencyFrom,p_CurrencyTo,  p_ISbaunk,p_CountryID,v_BNKAACID);
          SELECT p_Purchaseprice AS Purchaseprice,p_BPrice11 AS BPrice11,v_ValueDev AS ValueDev;

  END IF;
 IF p_ISbaunk = 3
   THEN


          IF v_CurrencyPower = 1
             THEN
              SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyTo
                      AND b.CountryID = p_CountryID
                      AND b.PriceType = p_ISbaunk
                      AND b.BankID=v_BNKAACID;


              SELECT
                      v_CurrencyBuyPrice;
              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  b.SalePrice AS SalePrice

                          FROM
                                  `NewCurrencyPricesOwnTb` AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON  a.ID =b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk
                                   AND a.BankID=v_BNKAACID

                          UNION

                          SELECT
                                  CASE                                           WHEN CurrencyPower = 0                                             THEN                                             b.BuyPrice * v_CurrencyBuyPrice                                           ELSE                                           v_CurrencyBuyPrice / BuyPrice                                   END AS BuyPrice
                          FROM
                                  `NewCurrencyPricesOwnTb` AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                    ON a.ID =b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo <> p_CurrencyFrom
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                  AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk
                                  AND a.BankID=v_BNKAACID) AS x;

              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;

          IF v_CurrencyPower = 0
             THEN
              SELECT a.BuyPrice, a.SalePrice INTO v_CurrencySalePrice, v_CurrencyBuyPrice FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = 1
                      AND a.CurrencyIDTo = p_CurrencyTo
                      AND b.CountryID = p_CountryID
                      AND b.PriceType = p_ISbaunk
                       AND b.BankID=v_BNKAACID;

              SELECT x.SalePrice INTO v_ValueDev FROM
                      (   SELECT
                                  CASE                                           WHEN CurrencyPower = 1                                             THEN                                             b.SalePrice                                           ELSE                                           1 / SalePrice                                   END AS SalePrice
                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                   ON  a.ID=b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON a.CurrencyIDFrom = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                   AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk
                                  AND a.BankID=v_BNKAACID


                          UNION

                          SELECT
                                  1 / (v_CurrencyBuyPrice * BuyPrice) AS SalePrice

                          FROM
                                  NewCurrencyPricesOwnTb AS a
                              INNER JOIN
                                NewCurrencyPriceOwnDetailsTb AS b
                                   ON  a.ID=b.CPID
                              INNER JOIN
                                `CurrencyMainTb` AS c
                                    ON b.CurrencyIDTo = c.ID
                          WHERE
                                  a.IsActive = 1
                                  AND b.IsActive = 1
                                  AND c.IsActive = 1
                                  AND a.CurrencyIDFrom = 1
                                  AND b.CurrencyIDTo = p_CurrencyTo
                                   AND a.CountryID = p_CountryID
                                  AND a.PriceType = p_ISbaunk
                                  AND a.BankID=v_BNKAACID) AS x;
              SET p_BPrice11 = CAST(p_BPrice1 * v_ValueDev AS CHAR);
            END IF;
          SET p_Purchaseprice = NewGet_PurchaseSalePrice(p_CurrencyFrom,p_CurrencyTo,  p_ISbaunk,p_CountryID,v_BNKAACID);
          SELECT p_Purchaseprice AS Purchaseprice,p_BPrice11 AS BPrice11,v_ValueDev AS ValueDev;

  END IF;
      SELECT
              p_BPrice11,
              p_Purchaseprice,
              v_CurrencyPower;
      COMMIT;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrenciesBankSell_Update`;
DELIMITER //
CREATE PROCEDURE `NewCurrenciesBankSell_Update`(IN `p_Code` LONGTEXT, IN `p_IsCachorBank` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;

      START TRANSACTION;

          IF p_IsCachorBank = 3
             THEN

              INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
                    (
                      `ISID`,
                      `ACCFRom`,
                      `ACCCRint0`,
                      `ACC_DEPET_TO`,
                      `CRedetDL`,
                      `ACC_DEPET_DL`,
                      `CRedetTO`,
                      `UESER_INSERt`,
                      `Inseart_Date`,
                      `IsActive`,
                      `BID`,
                      `TYPEFROM`,
                      Purchaseprice,
                      AccID,
                      Typeofsalebuyorsell,
                      NetSale,
                      salesPurchaseprice,
                      BankID,
                      CountryID
                    )
                  SELECT
                          ISID,
                          ACCFRom,
                          ACCCRint0,
                          CRedetTO,
                          ACC_DEPET_DL,
                          CRedetDL,
                          ACC_DEPET_TO,
                          UESER_INSERt,
                          Inseart_Date,
                          ISactive,
                          BID,
                          TYPEFROM,
                          Purchaseprice,
                          ACCID,
                          Typeofsalebuyorsell,
                          NetSale,
                          salesPurchaseprice,
                          BankID,
                          CountryID

                  FROM
                          `ExSyAccountsCurrency`.`CurrencymovementPruse`
                  WHERE
                          ISID = p_Code;

              INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      AccTotal,
                      InsertDate,
                      Description,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      IsConfirmed,
                      IsCanceled,
                      MovementType,
                      CurrencyID,
                      DailyClosed,
                      SafeIDDailyClose,
                      Note,
                      SafeIDMovement,
                      PriceType,
                      CountryID
                    )
                  SELECT
                          SafeID,
                          Credit,
                          Debit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          PriceType,
                          CountryID
                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb
                  WHERE
                          ISID = p_Code;

              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      AccTotal,
                      InsertDate,
                      DESCRIPTION,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      IsConfirmed,
                      IsCanceled,
                      MovementType,
                      CurrencyID,
                      DailyClosed,
                      SafeIDDailyClose,
                      Note,
                      SafeIDMovement,
                      IsBank
                    )
                  SELECT
                          SafeID,
                          Credit,
                          Debit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          IsBank

                  FROM
                          ExSyAccounts_AccSafeActivityTb
                  WHERE
                          ISID = p_Code;

        END IF;

      COMMIT;
      SET p_MSGSTatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrenciesBuyandsellTB_Update`;
DELIMITER //
CREATE PROCEDURE `NewCurrenciesBuyandsellTB_Update`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` INT, IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50), IN `p_BankID` INT, IN `p_CountryID` INT)
proc: BEGIN
DECLARE v_ACCaountDR BIGINT;
DECLARE v_GETDATEForInsert DATE;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_Costof DECIMAL(18, 3);
DECLARE v_GET_RetunsVlaue DECIMAL(18, 3);
DECLARE v_IsDefalut BIT;
DECLARE v_OldBuyprice DECIMAL(18, 3);
DECLARE v_NewBuyprice DECIMAL(18, 3);
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_ACCACountCredit BIGINT;
DECLARE v_FathersRevenueAccount BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
		START TRANSACTION;

		SELECT CMT.IsDefault INTO v_IsDefalut FROM CurrencyMainTb AS CMT
		WHERE CMT.ID = p_FirstCurrency
 ORDER BY CMT.ID DESC LIMIT 1;


		SELECT CASE 				WHEN a.Typeofsalebuyorsell = 0 THEN FORMAT(a.`Purchaseprice`, 3) 				ELSE '0.000' 			END INTO v_OldBuyprice FROM ExSyAccountsCurrency_CurrencymovementPruse AS a
		WHERE a.ISID = p_Code;

		SELECT a.BuyPrice INTO v_NewBuyprice FROM NewCurrencyPriceOwnDetailsTb AS a
		INNER JOIN NewCurrencyPricesOwnTb AS B
			ON a.CPID = B.ID
		WHERE a.CurrencyIDTo = p_FirstCurrency
		AND B.PriceType = p_IsCachorBank
		AND B.CountryID = p_CountryID
		AND B.BankID = p_BankID;








		SELECT CASE 				WHEN a.CurrencyPower = 1 THEN v_OldBuyprice - v_NewBuyprice 				ELSE v_NewBuyprice - v_OldBuyprice 			END INTO v_GET_RetunsVlaue FROM NewCurrencyPriceOwnDetailsTb  AS a
        		INNER JOIN NewCurrencyPricesOwnTb AS B
			ON a.CPID = B.ID
		WHERE a.CurrencyIDTo = p_FirstCurrency
    		AND B.PriceType = p_IsCachorBank
		AND B.CountryID = p_CountryID
		AND B.BankID = p_BankID;
		IF v_GET_RetunsVlaue < 0
		 THEN
			SET p_MsgBox = 'عذرا لايمكن استرجاع هذه القيمة لانه تم تغير سعر الصرف ';
			SET p_MSGSTatues = 0;
			ROLLBACK;
			LEAVE proc;
		END IF;
		SELECT Inseart_Date INTO v_GETDATEForInsert FROM ExSyAccountsCurrency_CurrencymovementPruse AS a
		INNER JOIN NewCurrencyPriceOwnDetailsTb AS b
			ON a.`ACCFRom` = b.CurrencyIDTo
		INNER JOIN NewCurrencyPricesOwnTb AS c
			ON b.CPID = c.ID
		WHERE a.ISID = p_Code
		AND c.PriceType = p_IsCachorBank
		AND c.CountryID = p_CountryID
		AND c.BankID = p_BankID;

		IF v_GETDATEForInsert <> v_getDate
		 THEN
			SET p_MsgBox = CONCAT(' عذراً  لا يمكن استرجاع عملية سابقة لانه ليست في نفس التاريخ يمكن شراء هذه القيمة فقط في الوقت الحالي', ', وتاريخ العلملية هو  : ', CAST(v_getDate AS CHAR));
			SET p_MSGSTatues = 0;
			ROLLBACK;
			LEAVE proc;
		END IF;

		UPDATE `CurrenciesBuyandsellTB`
		SET `BranchID` = p_BranchID
		   ,`SaFACCount` = p_SaFACCount
		   ,`AccSafeTo` = p_SAFFACCTO
		   ,`FirstCurrency` = p_FirstCurrency
		   ,`BPrice1` = p_BPrice1
		   ,`CurrencyTo` = p_CurrencyTo
		   ,`BPrice2` = p_BPrice2
		   ,`Notes` = p_Notes
		   ,`TotalQt` = 1
		   ,TotalPriceByLD = 0
		   ,`UeserInset` = p_UeserInset
		   ,`IsActive` = 0
		   ,`countUpdate` = 0
		   ,TypeOP = 24
		   ,Purchasingprice = v_OldBuyprice
		   ,IsCachorBank = p_IsCachorBank
		   ,CustIDNo = p_CusIDNo
		   ,Phone = p_Phone
		   ,thepurpose = p_thepurpose
		   ,CusName = p_CustName
		   ,SafeTypefrom = p_SAFTypeform
		   ,SafeTypeTo = p_SafTypeTo
		   ,UeserUpDate = NOW()
		   ,UserUpdate = p_UeserInset
		WHERE Code = p_Code;

		SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet, a.FathersRevenueAccount INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet, v_FathersRevenueAccount FROM CurrencyMainTb AS a
		WHERE a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;

    IF p_IsCachorBank<>1
     THEN
    		SELECT AccID INTO v_FirstCurrencysASSS FROM AccountsTb AS a
		WHERE a.AccParent = v_FatherPerintACC
		AND a.BranchID = p_BranchID;
    END IF;
	 IF p_IsCachorBank=1
     THEN
    		SELECT AccID INTO v_FirstCurrencysASSS FROM AccountsTb AS a
		WHERE a.AccParent LIKE '101012%'
		AND a.CountryID = p_CountryID
    AND a.AccCurID=p_FirstCurrency;
    END IF;
		SELECT AccID INTO v_FirstCurrencyd FROM AccountsTb AS a
		WHERE a.AccParent = v_FAtherPERints
		AND a.BranchID = p_BranchID;
		SELECT AccID INTO v_ACCFPrintCridetACC FROM AccountsTb AS a
		WHERE a.AccParent = v_ACCFPrintCridet
		AND a.BranchID = p_BranchID
		AND a.AccActive = 1;
		SELECT AccID INTO v_ACCACountCredit FROM AccountsTb AS a
		WHERE a.AccParent = v_FathersRevenueAccount
		AND a.BranchID = p_BranchID
		AND a.AccActive = 1;

IF p_IsCachorBank=0
 THEN
	SELECT AccID INTO v_SAFACCAS FROM TB_Users AS a
		WHERE a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
END IF;




		IF p_SAFTypeform = 0 OR p_IsCachorBank=1
		 THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency);
			IF p_BPrice1 > v_EMPORCUST_G
			 THEN
				SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
				SET p_MSGSTatues = 0;
				ROLLBACK;
				LEAVE proc;
			END IF;

		END IF;
		IF p_SAFTypeform <> 0 AND p_IsCachorBank<>1
		 THEN
			SELECT AccID INTO v_SAFACCAS FROM TB_Users AS a
			WHERE a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(v_SAFACCAS, p_FirstCurrency);
			IF p_BPrice1 > v_EMPORCUST_G
			 THEN
				SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
				SET p_MSGSTatues = 0;
				ROLLBACK;
				LEAVE proc;
			END IF;
		END IF;



		IF v_IsDefalut = 0
		 THEN
			IF p_SafTypeTo = 0
			 THEN
SET v_SAFACCAS = p_SAFFACCTO;
			END IF;
			IF p_SafTypeTo <> 0
			 THEN
				SELECT AccID INTO v_SAFACCAS FROM TB_Users AS a
				WHERE a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
			END IF;
SET v_MovementType = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
			IF p_SAFTypeform <> 0 AND p_IsCachorBank<>1
			 THEN
SET v_MovementType = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
				IF p_SafTypeTo <> 0
				 THEN
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,0 ,p_BPrice2 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_FirstCurrencysASSS ,p_SaFACCount ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
				END IF;
				CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,0 ,p_BPrice1 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_ACCFPrintCridetACC ,p_SaFACCount ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
				CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,p_BPrice1 ,0 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_FirstCurrencyd ,p_SaFACCount ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
				CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset ,p_BPrice1 ,0 ,v_getDate ,p_Notes ,p_Code ,22 ,22 ,p_BranchID ,p_SaFACCount ,p_SAFFACCTO ,0 ,0 ,v_SafeIDMovement ,p_FirstCurrency ,0 ,1 ,v_SafeIDMovement);
				CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset ,0 ,p_BPrice1 ,v_getDate ,p_Notes ,p_Code ,22 ,22 ,p_BranchID ,v_SAFACCAS ,v_FirstCurrencysASSS ,0 ,0 ,v_SafeIDMovement ,p_FirstCurrency ,0 ,1 ,v_SafeIDMovement);
			END IF;
			IF p_SafTypeTo = 0
			 THEN
      IF p_IsCachorBank=1
       THEN
SET v_SAFACCAS = p_SaFACCount;
      END IF;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, v_IsDefalut);
SET v_MovementType = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
				CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset ,p_BPrice1 ,0 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_SAFACCAS ,v_FirstCurrencysASSS ,0 ,0 ,v_SafeIDMovement ,p_FirstCurrency ,0 ,1 ,v_SafeIDMovement);
				CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,0 ,p_BPrice2 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_FirstCurrencysASSS ,p_SAFFACCTO ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
				CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,p_BPrice2 ,0 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,p_SAFFACCTO ,v_FirstCurrencysASSS ,0 ,0 ,v_MovementType ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
			END IF;
			IF p_SafTypeTo <> 0
			 THEN
      IF p_IsCachorBank=1
       THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_FirstCurrencysASSS=p_SaFACCount;
      END IF;
SET v_MovementType = 'استرجاع قيمة شراء عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
					IF p_SAFTypeform = 0 OR p_IsCachorBank=1
					 THEN
						CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,0 ,p_BPrice2 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_FirstCurrencysASSS ,p_SAFFACCTO ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
					END IF;

					CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset ,p_BPrice1 ,0 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,v_SAFACCAS ,v_FirstCurrencysASSS ,0 ,0 ,v_SafeIDMovement ,p_FirstCurrency ,0 ,1 ,v_SafeIDMovement);
					CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset ,p_BPrice2 ,0 ,v_getDate ,p_Notes ,p_Code ,1 ,1 ,p_BranchID ,p_SAFFACCTO ,v_FirstCurrencysASSS ,0 ,0 ,v_SafeIDMovement ,p_CurrencyTo ,0 ,1 ,v_SafeIDMovement);
			END IF;
			IF p_SafTypeTo = 0
			 THEN
SET v_SAFACCAS = p_SAFFACCTO;
			END IF;
			IF p_SafTypeTo <> 0
			 THEN
				SELECT AccID INTO v_SAFACCAS FROM TB_Users AS a
				WHERE a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
			END IF;
       IF p_IsCachorBank=1
       THEN
SET v_SAFACCAS = p_SaFACCount;
      END IF;
			INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse (`ISID`,
			`ACCFRom`,
			`ACCCRint0`,
			`CRedetTO`,
			`CRedetDL`,
			`ACC_DEPET_DL`,
			`ACC_DEPET_TO`,
			`UESER_INSERt`,
			`Inseart_Date`,
			`IsActive`,
			`BID`,
			`TYPEFROM`,
			Purchaseprice,
			AccID,
			Typeofsalebuyorsell,
			NetSale,
			BankID,
			CountryID)
				VALUES (p_Code, p_FirstCurrency, p_CurrencyTo, 0.00, 0.00, p_BPrice2, p_BPrice1, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, v_OldBuyprice, v_SAFACCAS, 2, 0.000,p_BankID,p_CountryID);
		END IF;
		IF v_IsDefalut = 1
		 THEN
			SET p_MSGSTatues = 0;
			SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
			ROLLBACK;
			LEAVE proc;
		END IF;
		COMMIT;
		SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrenciesBuyandsellTSElecSPreceB_Updata`;
DELIMITER //
CREATE PROCEDURE `NewCurrenciesBuyandsellTSElecSPreceB_Updata`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_SaFACCount` BIGINT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` TINYINT(1), IN `p_SAFTypeform` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` TINYINT UNSIGNED, IN `p_CustName` VARCHAR(50), IN `p_BankID` INT, IN `p_CountryID` INT)
proc: BEGIN
DECLARE v_DEbitValue DECIMAL(13, 6);
DECLARE v_BuyPrice DECIMAL(13, 6);
DECLARE v_ACCRevenueCalculation BIGINT;
DECLARE v_valueevenueCalculation DECIMAL(13, 3);
DECLARE v_GETDATEForInsert DATE;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_GET_RetunsVlaue DECIMAL(18, 3);
DECLARE v_IsDefalut BIT;
DECLARE v_OldSlerice DECIMAL(18, 3);
DECLARE v_NewSaleprice DECIMAL(18, 3);
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE v_STATUESValueevenueCalculatio DECIMAL(13, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;

      START TRANSACTION;
      SELECT CMT.IsDefault INTO v_IsDefalut FROM
              CurrencyMainTb AS CMT
      WHERE
              cmt.ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;


      SELECT CASE                                    WHEN a.Typeofsalebuyorsell = 1                                      THEN                                      IFNULL(salesPurchaseprice, 0.000)                            END INTO v_OldSlerice FROM
              ExSyAccountsCurrency_CurrencymovementPruse AS a
      WHERE
              a.ISID = p_Code;

      SELECT a.SalePrice INTO v_NewSaleprice FROM
              NewCurrencyPriceOwnDetailsTb AS a
          INNER JOIN
            NewCurrencyPricesOwnTb AS b
              ON a.CPID = b.ID
      WHERE
              a.CurrencyIDTo = p_FirstCurrency
              AND B.PriceType = p_IsCachorBank
              AND B.CountryID = p_CountryID
              AND B.BankID = p_BankID;



      SELECT CASE                                         WHEN a.CurrencyPower = 1                                           THEN                                           v_NewSaleprice - v_OldSlerice                                         ELSE                                         v_OldSlerice - v_NewSaleprice                                 END INTO v_GET_RetunsVlaue FROM
              CurrencyPriceDetailsTb AS a
      WHERE
              a.CurrencyIDTo = p_FirstCurrency;


      IF v_IsDefalut = 1
         THEN

          IF p_SAFTypeform = 0

            OR
            p_IsCachorBank = 1
             THEN
SET v_SAFACCAS = p_SaFACCount;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SaFACCount, p_FirstCurrency);
              IF p_IsCachorBank = 1
                 THEN
SET v_FirstCurrencysASSS = p_SaFACCount;
                END IF;
            END IF;
          IF p_SAFTypeform <> 0
            AND
            p_IsCachorBank <> 1
             THEN
              SELECT AccID INTO v_SAFACCAS FROM
                      TB_Users AS a



              WHERE
                      a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(v_SAFACCAS, p_FirstCurrency);
            END IF;
          IF p_IsCachorBank = 1
            OR
            p_IsCachorBank = 0
             THEN
              IF p_IsCachorBank = 0
                 THEN
                  SELECT CASE                                              WHEN a.CurrencyPower = 1                                                THEN                                                a.Costof                                              ELSE                                              1 / a.Costof                                      END INTO v_BuyPrice FROM
                          NEW_GET_TABLE_FOR_Costof AS a
                  WHERE
                          a.ACCFRom = p_FirstCurrency
                          AND a.BID = p_BranchID
                          AND A.TYPEFROM = p_IsCachorBank
                          AND A.CountryID = p_CountryID
                          AND a.CurrencyIDTo = p_FirstCurrency;
                END IF;
              IF p_IsCachorBank = 1
                 THEN
                  SELECT CASE                                              WHEN a.CurrencyPower = 1                                                THEN                                                a.Costof                                              ELSE                                              1 / a.Costof                                      END INTO v_BuyPrice FROM
                          NEW_GET_TABLE_FOR_Costof AS a
                  WHERE
                          a.ACCFRom = p_FirstCurrency
                          AND a.BID = p_BranchID
                          AND (   A.TYPEFROM = 1
                                  OR (    a.TYPEFROM = 2
                                          AND a.AccountType = 0))
                          AND A.CountryID = p_CountryID
                          AND a.CurrencyIDTo = p_FirstCurrency;












                END IF;



              UPDATE
                      `CurrenciesBuyandsellTB`
              SET

                      `Code` = p_Code,
                      `BranchID` = p_BranchID,
                      `SaFACCount` = p_SaFACCount,
                      `AccSafeTo` = p_SAFFACCTO,
                      `FirstCurrency` = p_FirstCurrency,
                      `BPrice1` = p_BPrice1,
                      `CurrencyTo` = p_CurrencyTo,
                      `BPrice2` = p_BPrice2,
                      `Notes` = p_Notes,
                      `TotalQt` = 1,
                      TotalPriceByLD = 0,
                      `UeserInset` = p_UeserInset,
                      `IsActive` = 0,
                      `countUpdate` = 0,
                      TypeOP = 25,
                      Purchasingprice = p_Purchaseprice,
                      IsCachorBank = p_IsCachorBank,
                      CustIDNo = p_CusIDNo,
                      Phone = p_Phone,
                      thepurpose = p_thepurpose,
                      CusName = p_CustName,
                      SafeTypefrom = p_SAFTypeform,
                      SafeTypeTo = p_SafTypeTo,
                      UeserUpDate = NOW(),
                      UserUpdate = p_UeserInset
              WHERE
                Code = p_Code;














              SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
                      CurrencyMainTb AS a
              WHERE
                      a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
              SELECT AccID INTO v_FirstCurrencysASSS FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = v_FatherPerintACC
                      AND a.BranchID = p_BranchID;
              SELECT AccID INTO v_FirstCurrencyd FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = v_FAtherPERints
                      AND a.BranchID = p_BranchID;
              SELECT AccID INTO v_ACCFPrintCridetACC FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = v_ACCFPrintCridet
                      AND a.BranchID = p_BranchID
                      AND a.AccActive = 1;

































              SELECT AccID INTO v_SAFACCAS FROM
                      TB_Users AS a
              WHERE
                      a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
              CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
SET v_DEbitValue = p_BPrice1 * v_BuyPrice;
              CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, v_DEbitValue, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);


              IF p_SAFTypeform <> 0
                AND
                p_IsCachorBank <> 1
                 THEN
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);

                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);

                  CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);


                  CALL ExSyAccountsCurrency_AccSafeActivityTb_Inert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 21, 21, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);

                END IF;

              IF p_SafTypeTo = 0
                 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, p_CurrencyTo);
                  IF p_BPrice2 > v_EMPORCUST_G
                     THEN
                      SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
                      SET p_MSGSTatues = 0;
                      ROLLBACK;
                      LEAVE proc;
                    END IF;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0.00, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);

                END IF;
              IF p_SafTypeTo <> 0
                 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal`(p_SAFFACCTO, v_IsDefalut);
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);


                END IF;

              IF p_SAFTypeform = 0
                OR
                p_IsCachorBank = 1
                 THEN
SET v_SAFACCAS = p_SaFACCount;
                END IF;
              IF p_SAFTypeform <> 0
                AND
                p_IsCachorBank <> 1
                 THEN
                  SELECT AccID INTO v_SAFACCAS FROM
                          TB_Users AS a
                  WHERE
                          a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
                END IF;
SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;SET v_valueevenueCalculation = CASE                                                        WHEN p_BPrice2 - v_DEbitValue > 0                                                          THEN                                                          v_DEbitValue - p_BPrice2                                                        ELSE                                                        v_DEbitValue - p_BPrice2                                                END;
              INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
                    (
                      `ISID`,
                      `ACCFRom`,
                      `ACCCRint0`,
                      `CRedetTO`,
                      `CRedetDL`,
                      `ACC_DEPET_DL`,
                      `ACC_DEPET_TO`,
                      `UESER_INSERt`,
                      `Inseart_Date`,
                      `IsActive`,
                      `BID`,
                      `TYPEFROM`,
                      Purchaseprice,
                      AccID,
                      Typeofsalebuyorsell,
                      NetSale,
                      salesPurchaseprice,
                      CountryID
                    )
              VALUES
                      (
                        p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, v_DEbitValue, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, v_BuyPrice, v_SAFACCAS, 3, v_valueevenueCalculation, p_Purchaseprice, p_CountryID


                      );
SET v_DEbitValue = p_BPrice1 * v_BuyPrice;
SET v_STATUESValueevenueCalculatio = p_BPrice2 - v_DEbitValue;
              IF v_STATUESValueevenueCalculatio < 0
                 THEN

                  IF p_IsCachorBank <> 1
                     THEN
SET v_valueevenueCalculation = v_DEbitValue - p_BPrice2;
                      SELECT FathersRevenueAccount INTO v_FatherPerintACC FROM
                              `CurrencyMainTb` AS a
                      WHERE
                              a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
                      SELECT AccID INTO v_ACCRevenueCalculation FROM
                              AccountsTb AS a
                      WHERE
                              a.AccParent = v_FatherPerintACC
                              AND a.BranchID = p_BranchID;
                    END IF;
                  IF p_IsCachorBank = 1
                     THEN
                      SELECT AccID INTO v_ACCRevenueCalculation FROM
                              AccountsTb AS a
                      WHERE
                              a.AccID = 1482;
                    END IF;
SET v_MovementType   = 'استرجاع قيمة بيع عملة مقابل الدينار اللببي';
SET v_SafeIDMovement = GET_ReturnsSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, 0, v_valueevenueCalculation, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                END IF;

              IF v_STATUESValueevenueCalculatio > 0
                 THEN
                  IF p_IsCachorBank <> 1
                     THEN
                      SELECT FathersLossAccount INTO v_FatherPerintACC FROM
                              `CurrencyMainTb` AS a
                      WHERE
                              a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
                      SELECT AccID INTO v_ACCRevenueCalculation FROM
                              AccountsTb AS a
                      WHERE
                              a.AccParent = v_FatherPerintACC
                              AND a.BranchID = p_BranchID;
                    END IF;
                  IF p_IsCachorBank = 1
                     THEN
                      SELECT AccID INTO v_ACCRevenueCalculation FROM
                              AccountsTb AS a
                      WHERE
                              a.AccID = 1484;
                    END IF;
SET v_valueevenueCalculation = p_BPrice2 - v_DEbitValue;
                  CALL ExSyAccounts_AccSafeActivityTb_Insert(p_UeserInset, v_valueevenueCalculation, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCRevenueCalculation, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                END IF;
            END IF;
          IF p_IsCachorBank = 3
             THEN

              INSERT INTO ExSyAccountsCurrency_CurrencymovementPruse
                    (
                      `ISID`,
                      `ACCFRom`,
                      `ACCCRint0`,
                      `ACC_DEPET_TO`,
                      `CRedetDL`,
                      `ACC_DEPET_DL`,
                      `CRedetTO`,
                      `UESER_INSERt`,
                      `Inseart_Date`,
                      `IsActive`,
                      `BID`,
                      `TYPEFROM`,
                      Purchaseprice,
                      AccID,
                      Typeofsalebuyorsell,
                      NetSale,
                      salesPurchaseprice,
                      BankID,
                      CountryID
                    )
                  SELECT
                          ISID,
                          ACCFRom,
                          ACCCRint0,
                          CRedetTO,
                          ACC_DEPET_DL,
                          CRedetDL,
                          ACC_DEPET_TO,
                          UESER_INSERt,
                          Inseart_Date,
                          ISactive,
                          BID,
                          TYPEFROM,
                          Purchaseprice,
                          ACCID,
                          Typeofsalebuyorsell,
                          NetSale,
                          salesPurchaseprice,
                          BankID,
                          CountryID

                  FROM
                          ExSyAccountsCurrency_CurrencymovementPruse
                  WHERE
                          ISID = p_Code;

              INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      AccTotal,
                      InsertDate,
                      Description,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      IsConfirmed,
                      IsCanceled,
                      MovementType,
                      CurrencyID,
                      DailyClosed,
                      SafeIDDailyClose,
                      Note,
                      SafeIDMovement,
                      PriceType,
                      CountryID
                    )
                  SELECT
                          SafeID,
                          Credit,
                          Debit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          PriceType,
                          CountryID
                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb
                  WHERE
                          ISID = p_Code;

              INSERT INTO ExSyAccounts_AccSafeActivityTb
                    (
                      SafeID,
                      Debit,
                      Credit,
                      AccTotal,
                      InsertDate,
                      DESCRIPTION,
                      ISID,
                      IsActive,
                      TypeID,
                      OperationTypeID,
                      AccBranchID,
                      AccIDFrom,
                      AccIDTo,
                      IsConfirmed,
                      IsCanceled,
                      MovementType,
                      CurrencyID,
                      DailyClosed,
                      SafeIDDailyClose,
                      Note,
                      SafeIDMovement,
                      IsBank
                    )
                  SELECT
                          SafeID,
                          Credit,
                          Debit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          IsBank

                  FROM
                          ExSyAccounts_AccSafeActivityTb
                  WHERE
                          ISID = p_Code;

            END IF;

        END IF;

      IF v_IsDefalut = 0
         THEN
          SET p_MSGSTatues = 0;
          SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
          ROLLBACK;
          LEAVE proc;
        END IF;
      COMMIT;
      SET p_MSGSTatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrenciesSaleTB_Insert`;
DELIMITER //
CREATE PROCEDURE `NewCurrenciesSaleTB_Insert`(IN `p_IDcode` INT, IN `p_Code` LONGTEXT, IN `p_BranchID` INT, IN `p_FirstCurrency` INT, IN `p_BPrice1` DOUBLE, IN `p_CurrencyTo` INT, IN `p_BPrice2` DOUBLE, IN `p_Notes` LONGTEXT, IN `p_UeserInset` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT, IN `p_IsCachorBank` INT, IN `p_SAFTypeform` BIGINT, IN `p_SaFACCount` BIGINT, IN `p_SafTypeTo` BIGINT, IN `p_SAFFACCTO` BIGINT, IN `p_Purchaseprice` DECIMAL(13,3), IN `p_CusIDNo` VARCHAR(50), IN `p_Phone` VARCHAR(25), IN `p_thepurpose` INT, IN `p_CustName` VARCHAR(50), IN `p_BankID` INT, IN `p_AccAcountBank` VARCHAR(50), IN `p_CHECKTYPE` INT, IN `p_AccountOwnName` LONGTEXT, IN `p_Typeoftransaction` INT, IN `p_Transactionnumber` BIGINT, IN `p_AgentBankNumber` LONGTEXT, IN `p_CountryID` INT, IN `p_PrType` INT)
proc: BEGIN
DECLARE v_GETID INT;
DECLARE v_ACCaountDR BIGINT;
DECLARE v_IsDefalut BIT;
DECLARE v_BNKAACID BIGINT DEFAULT 0;
DECLARE v_MovementType LONGTEXT;
DECLARE v_SafeIDMovement LONGTEXT;
DECLARE v_FatherPerintACC BIGINT;
DECLARE v_FAtherPERints BIGINT;
DECLARE v_FirstCurrencyd BIGINT;
DECLARE v_FirstCurrencysASSS BIGINT;
DECLARE v_ACCFPrintCridet BIGINT;
DECLARE v_ACCFPrintCridetACC BIGINT;
DECLARE v_SAFACCAS BIGINT;
DECLARE v_getDate DATE DEFAULT NOW();
DECLARE v_EMPORCUST_G DECIMAL(15, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


      START TRANSACTION;
      SELECT IFNULL(ID, 0) INTO v_BNKAACID FROM
              BBranchTb bt
      WHERE
              (       bt.AccID = p_BankID
                      OR bt.AccID = 0);
      SELECT CMT.IsDefault INTO v_IsDefalut FROM
              CurrencyMainTb AS CMT
      WHERE
              CMT.ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
      SELECT IDcode INTO v_GETID FROM
              CurrenciesBuyandsellTB AS a
      WHERE
              a.IDcode = p_IDcode
              AND a.TypeOP = 24;
      IF v_GETID = p_IDcode
         THEN
          SET p_MSGSTatues = 2;
          SET p_MsgBox = 'عذرا كود العملية موجود مسبقا الرجاء المحاولة مرة أخرى ';
          ROLLBACK;
          LEAVE proc;
        END IF;

      INSERT INTO `CurrenciesBuyandsellTB`
            (
              `IDcode`,
              `Code`,
              `BranchID`,
              `SaFACCount`,
              `AccSafeTo`,
              `FirstCurrency`,
              `BPrice1`,
              `CurrencyTo`,
              `BPrice2`,
              `Notes`,
              `TotalQt`,
              TotalPriceByLD,
              `UeserInset`,
              `IsActive`,
              `countUpdate`,
              TypeOP,
              Purchasingprice,
              IsCachorBank,
              CustIDNo,
              Phone,
              thepurpose,
              CusName,
              SafeTypefrom,
              SafeTypeTo,
              BankID,
              AccAcountBank,
              CheckType,
              AccountOwnName,
              Typeoftransaction,
              Transactionnumber,
              AgentBankNumber,
              CountryID

            )
      VALUES
              (
                p_IDcode, p_Code, p_BranchID, p_SaFACCount, p_SAFFACCTO, p_FirstCurrency, p_BPrice1, p_CurrencyTo, p_BPrice2, p_Notes, 1, 0, p_UeserInset, 1, 0, 24, p_Purchaseprice, p_IsCachorBank, p_CusIDNo, p_Phone, p_thepurpose, p_CustName, p_SAFTypeform, p_SafTypeTo, v_BNKAACID, p_AccAcountBank, p_CHECKTYPE, p_AccountOwnName, p_Typeoftransaction, p_Transactionnumber, p_AgentBankNumber, p_CountryID
              );




      SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
              CurrencyMainTb AS a
      WHERE
              a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
      IF p_IsCachorBank = 0
        OR
        p_IsCachorBank = 1
         THEN
          IF p_IsCachorBank = 0
             THEN

              SELECT AccID INTO v_FirstCurrencysASSS FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent = v_FatherPerintACC
                      AND a.BranchID = p_BranchID;
            END IF;
          IF p_IsCachorBank = 1
             THEN
              SELECT AccID INTO v_FirstCurrencysASSS FROM
                      AccountsTb AS a
              WHERE
                      a.AccParent LIKE '101012%'
                      AND a.CountryID = p_CountryID
                      AND a.AccCurID = p_FirstCurrency;
            END IF;
          SELECT AccID INTO v_FirstCurrencyd FROM
                  AccountsTb AS a
          WHERE
                  a.AccParent = v_FAtherPERints
                  AND a.BranchID = p_BranchID;
          SELECT AccID INTO v_ACCFPrintCridetACC FROM
                  AccountsTb AS a
          WHERE
                  a.AccParent = v_ACCFPrintCridet
                  AND a.BranchID = p_BranchID
                  AND a.AccActive = 1;
          SELECT AccID INTO v_SAFACCAS FROM
                  TB_Users AS a
          WHERE
                  a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;


          IF v_IsDefalut = 1
             THEN



              IF p_PrType <> 1
                 THEN
                  IF p_SafTypeTo = 0
                     THEN
SET v_SAFACCAS = p_SAFFACCTO;
                    END IF;

                  IF p_SafTypeTo <> 0
                     THEN
                      SELECT AccID INTO v_SAFACCAS FROM
                              TB_Users AS a
                      WHERE
                              a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
                    END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencysASSS, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                END IF;



              IF p_PrType = 1
                 THEN

                  IF p_SafTypeTo = 0
                     THEN
SET v_SAFACCAS = p_SAFFACCTO;
                    END IF;

                  IF p_SafTypeTo <> 0
                     THEN
                      SELECT AccID INTO v_SAFACCAS FROM
                              TB_Users AS a
                      WHERE
                              a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
                    END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                END IF;

              IF (p_SAFTypeform <> 0
                AND

                p_PrType <> 1)
                 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal`(p_SaFACCount, p_FirstCurrency);
                  IF p_BPrice1 > v_EMPORCUST_G
                     THEN
                      SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الحساب ', ', ورصيد الحساب هو : ', CAST(v_EMPORCUST_G AS CHAR));
                      SET p_MSGSTatues = 0;
                      ROLLBACK;
                      LEAVE proc;
                    END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, p_BPrice1, 0, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_ACCFPrintCridetACC, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, v_FirstCurrencyd, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                  INSERT INTO `ExSyAccountsCurrency2026`.`AccSafeActivityTbCurrency`
                        (
                          SafeID,
                          Debit,
                          Credit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          PriceType,
                          CountryID
                        )
                  VALUES
                          (
                            p_UeserInset, 0, p_BPrice1, 0, NOW(), p_Notes, p_Code, 1, 21, 21, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 0, p_Notes, v_SafeIDMovement, p_IsCachorBank, p_CountryID
                          );

                  INSERT INTO `ExSyAccountsCurrency2026`.`AccSafeActivityTbCurrency`
                        (
                          SafeID,
                          Debit,
                          Credit,
                          AccTotal,
                          InsertDate,
                          Description,
                          ISID,
                          IsActive,
                          TypeID,
                          OperationTypeID,
                          AccBranchID,
                          AccIDFrom,
                          AccIDTo,
                          IsConfirmed,
                          IsCanceled,
                          MovementType,
                          CurrencyID,
                          DailyClosed,
                          SafeIDDailyClose,
                          Note,
                          SafeIDMovement,
                          PriceType,
                          CountryID
                        )
                  VALUES
                          (
                            p_UeserInset, p_BPrice1, 0, 0, NOW(), p_Notes, p_Code, 1, 21, 21, p_BranchID, v_SAFACCAS, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 0, p_Notes, v_SafeIDMovement, p_IsCachorBank, p_CountryID
                          );

                END IF;

              IF p_SafTypeTo = 0
                 THEN
SET v_EMPORCUST_G = `EMPORCUST_GetAccVal_SAfs`(p_SAFFACCTO, p_CurrencyTo);
                  IF p_BPrice2 > v_EMPORCUST_G
                     THEN
                      SET p_MsgBox = CONCAT('عذرا القيمة المسحوبة اكبر من الرصيد الحالي الرجاء التاكد من رصيد الخزينة ', ', ورصيد الخزينة هو : ', CAST(v_EMPORCUST_G AS CHAR));
                      SET p_MSGSTatues = 0;
                      ROLLBACK;
                      LEAVE proc;
                    END IF;
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 0, p_BPrice1, p_Purchaseprice);
                  CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_MovementType, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                END IF;

              IF p_SafTypeTo <> 0
                 THEN
                  IF p_IsCachorBank = 0
                    OR
                    p_IsCachorBank = 1
                     THEN
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
                      CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, v_FirstCurrencysASSS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
                    END IF;
                END IF;

              IF p_PrType = 1
                 THEN

                  IF p_SafTypeTo = 0
                     THEN
SET v_SAFACCAS = p_SAFFACCTO;
                    END IF;

                  IF p_SafTypeTo <> 0
                     THEN
                      SELECT AccID INTO v_SAFACCAS FROM
                              TB_Users AS a
                      WHERE
                              a.USID = p_UeserInset
 ORDER BY a.USID DESC LIMIT 1;
                    END IF;
                END IF;
              IF p_PrType = 1
                 THEN
SET v_SAFACCAS = p_SaFACCount;
                END IF;

            END IF;

          IF v_IsDefalut = 0
             THEN

              SET p_MSGSTatues = 0;
              SET p_MsgBox = '  عذرا هذه الميزة غير متوفره في الوقت الحالي الرجاء المحاولة في وقت لاحق لانه تحت التطوير الان في الوقت هذه متوفر الشراء فقط بالدينار الليبــــي ';
              ROLLBACK;
              LEAVE proc;
            END IF;
          INSERT INTO `ExSyAccountsCurrency2026`.`CurrencymovementPruse`
                (
                  `ISID`,
                  `ACCFRom`,
                  `ACCCRint0`,
                  `CRedetTO`,
                  `CRedetDL`,
                  `ACC_DEPET_DL`,
                  `ACC_DEPET_TO`,
                  `UESER_INSERt`,
                  `Inseart_Date`,
                  `IsActive`,
                  `BID`,
                  `TYPEFROM`,
                  Purchaseprice,
                  AccID,
                  BankID,
                  CountryID
                )
          VALUES
                  (
                    p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, p_BPrice2, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, p_Purchaseprice, v_SAFACCAS, p_BankID, p_CountryID
                  );
        END IF;
      IF p_IsCachorBank = 3
         THEN
          IF p_SAFTypeform = 0
             THEN

              SELECT a.FatherPerintACC, a.EMFtherPRint, a.ACCFPrintCridet INTO v_FatherPerintACC, v_FAtherPERints, v_ACCFPrintCridet FROM
                      CurrencyMainTb AS a
              WHERE
                      a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;















              CALL AccSafeActivityTb_Insert(p_UeserInset, 0.000, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
              CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, v_SAFACCAS, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
              CALL AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0.000, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
              INSERT INTO `ExSyAccountsCurrency2026`.`CurrencymovementPruse`
                    (
                      `ISID`,
                      `ACCFRom`,
                      `ACCCRint0`,
                      `CRedetTO`,
                      `CRedetDL`,
                      `ACC_DEPET_DL`,
                      `ACC_DEPET_TO`,
                      `UESER_INSERt`,
                      `Inseart_Date`,
                      `IsActive`,
                      `BID`,
                      `TYPEFROM`,
                      Purchaseprice,
                      AccID,
                      BankID,
                      CountryID,
                      salesPurchaseprice
                    )
              VALUES
                      (
                        p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, p_BPrice2, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, 0, p_Purchaseprice, p_SaFACCount, p_BankID, p_CountryID, 0.000
                      );
            END IF;

          IF p_SAFTypeform = 10105
             THEN

              CALL AccSafeActivityTb_Insert(p_UeserInset, 0.000, p_BPrice1, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_FirstCurrency, 0, 1, v_SafeIDMovement);
SET v_MovementType   = 'شراء عملة مقابل دينار الليبي';
SET v_SafeIDMovement = GETSafeIDMovement(p_FirstCurrency, p_SAFTypeform, p_IsCachorBank, p_SafTypeTo, p_SAFFACCTO, p_UeserInset, p_SaFACCount, 1, p_BPrice1, p_Purchaseprice);
              CALL AccSafeActivityTb_Insert(p_UeserInset, 0, p_BPrice2, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SAFFACCTO, p_SaFACCount, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
              CALL AccSafeActivityTb_Insert(p_UeserInset, p_BPrice2, 0.000, v_getDate, p_Notes, p_Code, 1, 1, p_BranchID, p_SaFACCount, p_SAFFACCTO, 0, 0, v_SafeIDMovement, p_CurrencyTo, 0, 1, v_SafeIDMovement);
              INSERT INTO `ExSyAccountsCurrency2026`.`CurrencymovementPruse`
                    (
                      `ISID`,
                      `ACCFRom`,
                      `ACCCRint0`,
                      `CRedetTO`,
                      `CRedetDL`,
                      `ACC_DEPET_DL`,
                      `ACC_DEPET_TO`,
                      `UESER_INSERt`,
                      `Inseart_Date`,
                      `IsActive`,
                      `BID`,
                      `TYPEFROM`,
                      Purchaseprice,
                      AccID,
                      BankID,
                      CountryID,
                      salesPurchaseprice
                    )
              VALUES
                      (
                        p_Code, p_FirstCurrency, p_CurrencyTo, p_BPrice1, p_BPrice2, 0.00, 0.00, p_UeserInset, NOW(), 1, p_BranchID, p_IsCachorBank, p_Purchaseprice, p_SaFACCount, p_BankID, p_CountryID, 0.000
                      );
            END IF;
        END IF;

      COMMIT;
      SET p_MSGSTatues = 1;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrencyBuyAndSale_CRUD`;
DELIMITER //
CREATE PROCEDURE `NewCurrencyBuyAndSale_CRUD`(IN `p_Action` INT, IN `p_ID` INT, IN `p_BuyOrSale` INT, IN `p_PriceType` INT, IN `p_Code` LONGTEXT, IN `p_CountryID` INT, IN `p_BranchID` INT, IN `p_ParentFromID` BIGINT, IN `p_AccIDFrom` BIGINT, IN `p_CurrencyIDFrom` INT, IN `p_Price` DECIMAL(18,3), IN `p_ValFrom` DECIMAL(18,3), IN `p_ParentToID` BIGINT, IN `p_AccIDTo` BIGINT, IN `p_CurrencyIDTo` INT, IN `p_ValTo` DECIMAL(18,3), IN `p_Notes` LONGTEXT, IN `p_UserID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CustName` VARCHAR(250), IN `p_CustPhone` VARCHAR(250), IN `p_NationalNumper` VARCHAR(250), IN `p_PassNumber` VARCHAR(250), IN `p_OwnBankName` VARCHAR(250), IN `p_OwnBankNumber` VARCHAR(250), IN `p_ThePurpose` INT, IN `p_CurrPower` INT)
proc: BEGIN
DECLARE v_MovmentType LONGTEXT;
DECLARE v_CostOf DECIMAL(18, 6);
DECLARE v_RealVal DECIMAL(18, 6);
DECLARE v_NetVal   DECIMAL(18, 6);
DECLARE v_AccProft BIGINT;
DECLARE v_TypID INT;
DECLARE v_OpTypeID INT;
DECLARE v_CunName  VARCHAR(150);
DECLARE v_PriceMov VARCHAR(50);
DECLARE v_AccLoss BIGINT;
DECLARE v_IDCode      INT;
DECLARE v_IsBank TINYINT DEFAULT 0;
DECLARE v_CurrAccSafe BIGINT;
DECLARE v_AccPerant BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;









      IF p_Action = 0
         THEN
          SELECT
                  *
          FROM
                  NewCurrencyBuyAndSale
          WHERE
                  IsActive = 1
                  AND (   p_BranchID IS NULL
                          OR BranchID = p_BranchID)
                  AND (   p_CountryID IS NULL
                          OR CountryID = p_CountryID)
                  AND (   p_BuyOrSale IS NULL
                          OR BuyOrSale = p_BuyOrSale)
                  AND (   p_PriceType IS NULL
                          OR PriceType = p_PriceType)
                  AND (   p_UserID IS NULL
                          OR UserID = p_UserID)
                  AND (   p_Code IS NULL
                          OR Code = p_Code)
          ORDER BY
                  ID DESC;
         ELSEIF  p_Action = 1
         THEN

          START TRANSACTION;



          IF EXISTS (SELECT
                        1
                FROM
                        NewCurrencyBuyAndSale gvt
                WHERE
                        gvt.Code = p_Code)
             THEN
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='عذرا رمز المعاملة موجود مسبقا الرجاء الحفظ مرة أخرى';
              LEAVE proc;
            END IF;



          SELECT IFNULL(MAX(IDCode), 0) + 1 INTO v_IDCode FROM
                  NewCurrencyBuyAndSale
          WHERE
                  BuyOrSale = p_BuyOrSale;

IF p_PriceType<>1
 THEN

  SELECT at.AccID INTO v_CurrAccSafe FROM
                  AccountsTb at

              INNER JOIN
                CurrencyMainTb c
                  ON at.AccParent = c.FatherPerintACC
          WHERE
                  c.ID = p_CurrencyIDFrom
                  AND at.BranchID = p_BranchID;
END IF;

   IF p_PriceType=1
 THEN

IF p_ParentFromID=0
 THEN
SET v_CurrAccSafe = p_AccIDFrom;
END IF;

IF p_ParentFromID<>0
 THEN
 SELECT at.AccID INTO v_CurrAccSafe FROM
                  AccountsTb at
          WHERE
                  at.AccCurID = p_CurrencyIDFrom
                  AND at.BranchID = p_BranchID
                  AND at.CountryID=p_CountryID
                  AND at.AccParent LIKE '1010120%';
END IF;

END IF;

          IF EXISTS (SELECT
                        1
                FROM
                        AccountsTb a
                WHERE
                        a.AccCode = p_ParentFromID
                        AND a.AccParent = 10105)
             THEN
              SET v_CurrAccSafe = p_AccIDFrom;
            END IF;

          IF p_PriceType = 3
             THEN
              SELECT at.AccCode INTO v_AccPerant FROM
                      AccountsTb at
              WHERE
                      at.AccParent = 101013
                      AND at.AccCurID = p_CurrencyIDFrom;

              IF v_AccPerant IS NOT NULL
                 THEN
                  SELECT at.AccID INTO v_CurrAccSafe FROM
                          AccountsTb at
                  WHERE
                          at.AccParent = v_AccPerant
                          AND at.BranchID = p_BranchID;
                END IF;
