                  CASE                           WHEN a.ParentFromID = 0                             THEN                             'نقدا'                           ELSE                           e.AccName                   END                                              ParentFromID,
                  b.AccName                                        FromAccName,
                  Price,
                  CONCAT(CAST(ValFrom AS CHAR), ' ', d.CurCode)  ValFrom,
                  d.CuName,
                  cu.CuName                                        CuNameTo,
                  CONCAT(CAST(a.ValTo AS CHAR), ' ', cu.CurCode) ValTo,
                  CASE                           WHEN a.ParentToID = 0                             THEN                             'نقدا'                           ELSE                           f.AccName                   END                                              ParentToID,
                  c.AccName                                        ToAccName,
                  cb.Mobile1,
                  a.Notes
          FROM
