              LEFT JOIN
                AccountsTb e
                  ON a.ParentFromID = e.AccCode
              LEFT JOIN
                AccountsTb f
                  ON a.ParentToID = f.AccCode
          WHERE
                  a.IsActive = 1
                  AND p_Code = a.Code
          ORDER BY
                  a.ID DESC;
         ELSEIF  p_Action = 5
         THEN
          SELECT
                  a.ID,
                  a.ISID,
                  InsertDate,
                  BuyPrice,
                  SalePrice,
                  CostOfPrice,
                  cmt.CurCode,
                  a.Debit,
                  a.Credit,
                  a.DL_Debit,
                  a.DL_Credit,
                  CONCAT(CASE                           WHEN a.TypeID = 24                             THEN                             'شراء'                           WHEN a.TypeID = 25                             THEN                             'بيع'                           WHEN a.TypeID = 28                             THEN                             'استرجاع شراء'                           WHEN a.TypeID = 29                             THEN                             'استرجاع بيع'                           ELSE                           '-'                   END, ' ', CASE                                      WHEN a.IsBank = 0                                        THEN                                        'نقدي'                                      WHEN a.IsBank = 1                                        THEN                                        'مصرفي'                                      ELSE                                      ''                              END) AS OPType
          FROM
                  ExSyAccountsCurrency_AccSafeActivityTb a
              INNER JOIN
                CurrencyMainTb cmt
                  ON a.CurrencyID = cmt.ID
          WHERE
                  a.IsActive = 1
                  AND InsertDate >= p_D1
                  AND InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY)
                  AND PriceType = p_PriceType
                  AND CountryID = p_CountryID
                  AND a.AccBranchID = p_BranchID
          ORDER BY
                  InsertDate;
        END IF;





  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrencyBuyAndSale_LoadGLKP`;
DELIMITER //
CREATE PROCEDURE `NewCurrencyBuyAndSale_LoadGLKP`(IN `p_Typesf` INT, IN `p_BranchID` INT, IN `p_GLKPTYPE` INT)
proc: BEGIN



    IF p_GLKPTYPE = 0
       THEN

        IF p_Typesf = 0
           THEN
            SELECT
                    x.AccCode,
                    x.AccName,
                    0 AS Typesf,
                    0 AS PrType
            FROM
                    (   SELECT
                                0 AS AccCode,
                                N'نقــــــداً' AS AccName

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccParent IN (20103, 20105)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccCode IN (1030201, 1030202)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID) x;
           ELSEIF  p_Typesf = 1
           THEN

            SELECT
                    a.AccCode,
                    a.AccName,
                    1 AS Typesf,
                    1 AS PrType
            FROM
                    AccountsTb a
            WHERE
                    a.AccCode = 101012
                    AND a.AccActive = 1;
           ELSEIF  p_Typesf = 2
           THEN
            SELECT
                    x.AccCode,
                    x.AccName,
                    1 AS Typesf,
                    1 AS PrType
            FROM
                    (   SELECT
                                0 AS AccCode,
                                N'نقــــــداً' AS AccName

                        UNION ALL
                        SELECT
                                10105 AS AccCode,
                                N'المصارف' AccName) x;
          END IF;

        LEAVE proc;
      END IF;




    IF p_GLKPTYPE = 1
       THEN

        IF p_Typesf = 0
           THEN
            SELECT
                    x.AccCode,
                    x.AccName,
                    0 AS Typesf,
                    0 AS PrType
            FROM
                    (   SELECT
                                0 AS AccCode,
                                N'نقــــــداً' AS AccName

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccParent IN (20103, 20105)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccCode IN (1030201, 1030202)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID) x;
           ELSEIF  p_Typesf = 1
           THEN
            SELECT
                    x.AccCode,
                    x.AccName,
                    0 AS Typesf,
                    0 AS PrType
            FROM
                    (   SELECT
                                0 AS AccCode,
                                N'نقــــــداً' AS AccName

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccParent IN (20103, 20105)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID

                        UNION ALL
                        SELECT
                                a.AccCode,
                                a.AccName
                        FROM
                                AccountsTb a
                        WHERE
                                a.AccCode IN (1030201, 1030202)
                                AND a.AccActive = 1
                                AND a.BranchID = p_BranchID) x

            WHERE
                    x.AccCode NOT IN (SELECT
                                AccCode
                        FROM
                                AccountsTb
                        WHERE
                                AccParent = 20105);
           ELSEIF  p_Typesf = 2
           THEN

            SELECT
                    0              AS AccCode,
                    N'نقــــــداً' AS AccName,
                    0              AS Typesf,
                    0              AS PrType;
          END IF;

        LEAVE proc;
      END IF;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrencyMainTb_LOADTOLKP_MAIN`;
DELIMITER //
CREATE PROCEDURE `NewCurrencyMainTb_LOADTOLKP_MAIN`(IN `p_TypeID` INT, IN `p_CountryID` INT, IN `p_BankID` INT)
BEGIN
START TRANSACTION;
  IF p_TypeID = 0
     THEN

      SELECT
              ID,
              CuName,
              'بيع وشراء داخلي' AS typesf,
              1                      AS ITYPE
      FROM
              CurrencyMainTb;
    END IF;
  IF p_TypeID = 1
     THEN
      SELECT
              ID,
              a.CuName               AS CuName,
              'بيع وشراء خارجي' AS typesf,
              2                      AS ITYPE
      FROM
              CurrencyMainTb AS a;
    END IF;
  IF p_TypeID = 2
     THEN

      SELECT
              ID,
              CuName,
              'تحويلات خارجية' AS typesf,
              3                AS ITYPE
      FROM
              CurrencyMainTb;
    END IF;
  IF p_TypeID = 3
     THEN

      SELECT
              c.ID,
              c.CuName    AS CuName,
              'مصرف ليبيا المركزي' AS typesf,
              5           AS ITYPE
      FROM
              CurrencyMainTb c;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewCurrencyPricUpdate`;
DELIMITER //
CREATE PROCEDURE `NewCurrencyPricUpdate`(IN `p_ID` INT, IN `p_PriceType` INT, IN `p_SalePrice` DECIMAL(12,3), IN `p_BuyPrice` DECIMAL(12,3), IN `p_UserID` INT, INOUT `p_Types` INT, INOUT `p_crUNSEFROM` INT, IN `p_AccountType` TINYINT UNSIGNED)
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;
      START TRANSACTION;

      IF p_PriceType = 0
         THEN
          UPDATE
                  NewCurrencyPriceOwnDetailsTb
          SET
                  `SalePrice` = p_SalePrice,
                  `BuyPrice` = p_BuyPrice
          WHERE
            ID = p_ID;







































          SET p_Types = 0;
          SELECT A.CurrencyIDFrom INTO p_crUNSEFROM FROM
                  NewCurrencyPriceOwnDetailsTb AS A
          WHERE
                  ID = p_ID;
        END IF;

      IF p_PriceType = 1
         THEN
          UPDATE
                  NewCurrencyPriceOwnDetailsTb
          SET
                  `SalePrice` = p_SalePrice,
                  `BuyPrice` = p_BuyPrice

          WHERE
            ID = p_ID;







































          SET p_Types = 1;
          SELECT A.CurrencyIDFrom INTO p_crUNSEFROM FROM
                  NewCurrencyPriceOwnDetailsTb AS A
          WHERE
                  ID = p_ID;
        END IF;
      IF p_PriceType = 2
         THEN
          UPDATE
                  NewCurrencyPriceOwnDetailsTb
          SET
                  `SalePrice` = p_SalePrice,
                  `BuyPrice` = p_BuyPrice

          WHERE
            ID = p_ID;







































          SET p_Types = 2;
          SELECT A.CurrencyIDFrom INTO p_crUNSEFROM FROM
                  NewCurrencyPriceOwnDetailsTb AS A
          WHERE
                  ID = p_ID;
        END IF;

      IF p_PriceType = 3
         THEN
          UPDATE
                  NewCurrencyPriceOwnDetailsTb
          SET
                  `SalePrice` = p_SalePrice,
                  `BuyPrice` = p_BuyPrice

          WHERE
            ID = p_ID;







































          SET p_Types = 3;
          SELECT A.CPID INTO p_crUNSEFROM FROM
                  NewCurrencyPriceOwnDetailsTb AS A
          WHERE
                  ID = p_ID;

        END IF;


      COMMIT;


  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `NewGetCurrencyPriceDetailsTb_ID`;
DELIMITER //
CREATE PROCEDURE `NewGetCurrencyPriceDetailsTb_ID`(IN `p_CurrencyIDFrom` INT, INOUT `p_MSG` LONGTEXT, IN `p_AccounType` INT, IN `p_BranchID` INT, IN `p_CountryID` INT, IN `p_BankID` INT, IN `p_PriceType` INT)
BEGIN
DECLARE v_IsDefault INT;
DECLARE v_BankAccID INT;


  START TRANSACTION;

  SELECT a.IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS a
  WHERE
          a.ID = p_CurrencyIDFrom
 ORDER BY a.ID DESC LIMIT 1;
  SELECT ID INTO v_BankAccID FROM
          BBranchTb bt
  WHERE
          bt.AccID = p_BankID;
  SELECT
          b.ID     AS CurDetailsID,
          c.CuName AS CurrencyIDTo,
          b.SalePrice,
          b.BuyPrice
  FROM
          `NewCurrencyPricesOwnTb` AS a
      INNER JOIN
        NewCurrencyPriceOwnDetailsTb AS b
          ON a.ID = b.CPID
      INNER JOIN
        `CurrencyMainTb` AS c
          ON b.CurrencyIDTo = c.ID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1
          AND c.IsActive = 1
          AND a.CurrencyIDFrom = p_CurrencyIDFrom
          AND a.CountryID = p_CountryID
          AND a.PriceType = p_PriceType
          AND a.BankID = v_BankAccID;
  COMMIT;
END //
DELIMITER ;

