DROP PROCEDURE IF EXISTS `OpeningBalanceTb_DeleteByCode`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_DeleteByCode`(IN `p_Code` LONGTEXT, IN `p_IsUpdate` TINYINT(1))
BEGIN


		START TRANSACTION;
		IF p_IsUpdate = 1
			 THEN
				UPDATE
						OpeningBalanceTb
				SET
						OpeningBalanceTb.IsActive = 0
				WHERE
					OpeningBalanceTb.Code = p_Code;
				UPDATE
						ExSyAccounts_AccSafeActivityTb
				SET
						ExSyAccounts_AccSafeActivityTb.IsActive = 0
				WHERE
					ExSyAccounts_AccSafeActivityTb.ISID = p_Code;
			END IF;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_Insert`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_Insert`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_AccID` BIGINT, IN `p_CurrencyID` INT, IN `p_Debit` DECIMAL(15,3), IN `p_Credit` DECIMAL(15,3), IN `p_SafeID` INT, IN `p_Notes` LONGTEXT, IN `p_IDCode` BIGINT, IN `p_AccountType` TINYINT UNSIGNED, IN `p_IsUpdate` TINYINT(1), IN `p_ValType` INT)
BEGIN
DECLARE v_IsPartner BIT;
DECLARE v_IsMain INT;
DECLARE v_AccIDTo   BIGINT;


		START TRANSACTION;
		IF p_IsUpdate = 0
