CREATE PROCEDURE `OpeningBalanceTb_LoadMainAccounts`(IN `p_BranchID` INT, IN `p_AccType` DECIMAL(18,3))
BEGIN
DECLARE v_BrName LONGTEXT;
DECLARE v_AccName LONGTEXT;
DECLARE v_AccParent BIGINT;
DECLARE v_IsPartner BIT;
DECLARE v_BankAccID BIGINT;


		START TRANSACTION;



		select AccParent, AccID, AccName from AccountsTb where substring(CAST(AccParent AS CHAR),1,1)=p_AccType and BranchID=p_BranchID and accline=4;
































































































































































































































































































		COMMIT;
	END //
DELIMITER ;

