		START TRANSACTION;


		select AccID as FAccID,AccCode as FAccCode, AccName as FAccName from AccountsTb where Accline=3 and (branchid=p_BranchID or BranchID=0) AND substring(CAST(AccParent AS CHAR),1,1)=p_AccParent;


		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_LoadMainParents2`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_LoadMainParents2`(IN `p_BranchID` INT, IN `p_AccParent` INT)
BEGIN


		START TRANSACTION;


		select AccID as SAccID,AccCode as SAccCode, AccName as SAccName from AccountsTb where Accline=3 and (branchid=p_BranchID or BranchID=0)  AND substring(CAST(AccParent AS CHAR),1,1)=p_AccParent;

		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_LoadMainParentsExist`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_LoadMainParentsExist`(IN `p_AccCode` DECIMAL(18,3), IN `p_BranchID` INT)
BEGIN
DECLARE v_BrName LONGTEXT;
DECLARE v_AccParent BIGINT;
DECLARE v_IsPartner BIT;
DECLARE v_BankAccID BIGINT;


		START TRANSACTION;

		if p_AccCode=2010201 or p_AccCode=2010701
		 THEN

		select AccID as FSAccID,AccCode as FSAccCode, AccName as FSAccName  from AccountsTb where Accline=4 and AccParent=p_AccCode and BranchID<>p_BranchID;

		END IF;
		if p_AccCode<>2010201 or p_AccCode<>2010701
		 THEN
		select AccID as FSAccID,AccCode as FSAccCode, AccName as FSAccName  from AccountsTb where Accline=4 and AccParent=p_AccCode and BranchID=p_BranchID;

	END IF;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_LoadMainParentsExist2`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_LoadMainParentsExist2`(IN `p_AccCode` DECIMAL(18,3), IN `p_BranchID` INT)
BEGIN


		START TRANSACTION;

		if p_AccCode=2010201 or p_AccCode=2010701
		 THEN

		select AccID as SSAccID,AccCode as SSAccCode, AccName as SSAccName  from AccountsTb where Accline=4 and AccParent=p_AccCode and BranchID<>p_BranchID;
	END IF;
	if p_AccCode<>2010201 or p_AccCode<>2010701
		 THEN
	select AccID as SSAccID,AccCode as SSAccCode, AccName as SSAccName  from AccountsTb where Accline=4 and AccParent=p_AccCode and BranchID=p_BranchID;
	END IF;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_LoadMainParentsNotExist`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_LoadMainParentsNotExist`(IN `p_AccCode` DECIMAL(18,3), IN `p_BranchID` INT)
BEGIN
DECLARE v_BrName LONGTEXT;
DECLARE v_AccParent BIGINT;
DECLARE v_IsPartner BIT;
DECLARE v_BankAccID BIGINT;


		START TRANSACTION;

		if p_AccCode = 1
		 THEN

		select AccID, AccName from AccountsTb where Accline=4 and substring(CAST(AccParent AS CHAR),1,1)=2 and BranchID=p_BranchID and AccCode<>p_AccCode;
	END IF;
	if p_AccCode = 2
		 THEN

		select AccID, AccName from AccountsTb where Accline=4 and substring(CAST(AccParent AS CHAR),1,1)=1 and BranchID=p_BranchID and AccCode<>p_AccCode;
	END IF;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_LoadToDVG`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_LoadToDVG`(IN `p_BranchID` INT)
BEGIN


    START TRANSACTION;
    SELECT
            a.Code       AS 'الرمز',
            a.InsertDate AS 'التاريخ',
            B.AccName    AS 'من حساب',
            C.AccName    AS 'إلى حساب',
            a.OPPVal     AS 'القيمة',
            d.UName      AS 'المستخدم',
            CASE                     WHEN A.Notes = ''                       THEN                       'لا يوجد'                     ELSE                     A.Notes             END          AS 'الملاحظات'
    FROM
            OPENINGBALANCE_TB AS a
        LEFT OUTER JOIN
          AccountsTb AS B
            ON a.FirstAccID = B.AccID
        LEFT OUTER JOIN
          AccountsTb AS C
            ON a.SecondAccID = C.AccID
        LEFT OUTER JOIN
          TB_Users AS D
            ON a.userinsert = D.USID;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_MaxID`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_MaxID`(IN `p_BranchID` INT, IN `p_AccID` INT)
BEGIN
DECLARE v_Code LONGTEXT;


		START TRANSACTION;
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), '0', '20', '-', CAST(p_AccID AS CHAR), '-', CAST(`OpeningBalanceTb_GetMaxIDCode`() AS CHAR));
		SELECT
				v_Code									AS Code,
				`OpeningBalanceTb_GetMaxIDCode`() AS ID;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `OpeningBalanceTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `OpeningBalanceTb_SelectByCode`(IN `p_Code` LONGTEXT)
BEGIN


		START TRANSACTION;
		SELECT
				Code,
				InsertDate,
				a.BranchID,
				ValType,
				FirstAccMain ,
				FirstAccParent AS FAccID,
				FirstAccID as FSAccID,
				SecondAccMain,
				SecondAccParent AS SAccID,
				SecondAccID as SSAccID ,
				b.AccCode as FAccCode ,
				c.AccCode as SAccCode ,
				CurrencyID,
				OPPVal,
				Notes,
				IsActive,
				UserInsert
		FROM
				OPENINGBALANCE_TB as a
				inner join accountstb as b on a.FirstAccParent=b.AccID
				inner join accountstb as c on a.SecondAccParent=c.AccID
		WHERE
				a.Code = p_Code;
		COMMIT;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PartnerAccounts_LOADTOLKP`;
DELIMITER //
CREATE PROCEDURE `PartnerAccounts_LOADTOLKP`(IN `p_BranchID` INT)
BEGIN
DECLARE v_MainBr INT;
START TRANSACTION;
SELECT a.ID INTO v_MainBr FROM CoBranch a WHERE a.IsMain=1;
	SELECT
							a.AccID,
							a.AccName
				FROM
                  AccountsTb AS a
          WHERE
                  a.BranchID = p_BranchID
                  AND (a.AccParent LIKE '2010100%' OR (a.BranchID=v_MainBr AND a.AccParent LIKE '20401016%'))
                  AND a.Accline = 4
                  AND a.AccActive=1
          GROUP BY
                  a.AccID,
                  a.AccName,
                  a.AccCode

          ORDER BY
                  a.AccName;

	COMMIT;
END //
DELIMITER ;

