BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;
  START TRANSACTION;


  DELETE FROM PcForUeserActivtion where id= p_id;


    commit;



  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PcForUeserActivtion_insert_forUpdate`;
DELIMITER //
CREATE PROCEDURE `PcForUeserActivtion_insert_forUpdate`(IN `p_UserID` INT, IN `p_pcName` BIGINT, IN `p_brnchID` INT, INOUT `p_msg` INT, INOUT `p_msgBox` LONGTEXT)
proc: BEGIN
DECLARE v_ID bigint;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;
START TRANSACTION;


SELECT ID INTO v_ID FROM  `PcForUeserActivtion` as a where  a.UserID = p_UserID and a.pcName = p_pcName AND A.brnchID =p_brnchID;
if v_ID is not null
 THEN
set p_msg= 0;
set p_msgBox = 'عذرا تمت اضافة هذه الشاشة من قبل الرجاء محاولة في وقت لاحق';
rollback;
LEAVE proc;

END IF;




SELECT ID INTO v_ID FROM  `PcForUeserActivtion` as a where  a.UserID = p_UserID and a.pcName = 0 AND A.brnchID =0;
if v_ID is not null
 THEN
set p_msg= 0;
set p_msgBox = 'عذرا هذه المستخدم  يمكنة الدخول الي جميع الاجهزة ';
rollback;
LEAVE proc;

END IF;



IF p_brnchID > 0 AND p_pcName = 0
 THEN
DELETE FROM `PcForUeserActivtion` WHERE UserID =  p_UserID   AND brnchID =p_brnchID;
 END IF;

 IF p_brnchID = 0 AND p_pcName = 0
  THEN
DELETE FROM `PcForUeserActivtion` WHERE UserID =  p_UserID;
 END IF;





INSERT INTO `PcForUeserActivtion`
           (`UserID`
           ,`pcName`
           ,`insertdate`
           ,`brnchID`
           ,`isActive`)
     VALUES
           (
		   p_UserID ,
		   p_pcName ,
		   NOW() ,
		   p_brnchID ,
		   1
		   );




commit;
 set p_msg =1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PCSettlementDetailsTB_SELECTByCODE`;
DELIMITER //
CREATE PROCEDURE `PCSettlementDetailsTB_SELECTByCODE`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.SPCISID ASC) AS SN,
			b.AccName                                  AS ExName,
			a.ExpensVal								   AS ExVal,
			a.Notes									   AS NotesDe,
			a.EXID									   AS ID,
			a.AccIDEX								   AS AccEX
	FROM
			PCSettlementDetailsTB AS a
		LEFT JOIN
			AccountsTb AS b
				ON a.AccIDEX = b.AccID
	WHERE
			a.SPCISID = p_Code
			AND a.IsActive = 1;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PCSettlementTB_CHECKCODE`;
DELIMITER //
CREATE PROCEDURE `PCSettlementTB_CHECKCODE`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;
	SELECT
			a.Code
	FROM
			PCSettlementTB AS a
	WHERE
			Code = p_Code;
	COMMIT;
END //
DELIMITER ;

