								Note
							)
					VALUES
							(

								p_SafeID,
								0.000,
								p_ExpensVal,
								p_InsertDate,
								p_Code,
								1,
								14,
								44,
								p_BranchID,
								p_AccIDEX,
								p_AccIDSafeID,
								1,
								0,
								v_MovementType,
