DROP PROCEDURE IF EXISTS `PCSettlementTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `PCSettlementTB_LOADTODVG`(IN `p_BranchID` INT, IN `p_DataBaseType` INT)
BEGIN
START TRANSACTION;
IF p_DataBaseType=1
 THEN
	SELECT
			A.Code		 AS 'الرمز',
			A.InsertDate AS 'التاريخ',
			B.EMPNAME	 AS 'الموظف',
			A.PCVal		 AS 'القيمة'
	FROM
			PCSettlementTB AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1;
END IF;

IF p_DataBaseType=2
 THEN
	SELECT
			A.Code		 AS 'الرمز',
			A.InsertDate AS 'التاريخ',
			B.PartnerName	 AS 'الموظف',
			A.PCVal		 AS 'القيمة'
	FROM
			ContractDB.PCSettlementTB AS A
		LEFT JOIN
			ContractDB.AddPartnerTb AS B
				ON A.EMPID = B.ID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1;
END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PCSettlementTB_SELECTByCODE`;
DELIMITER //
CREATE PROCEDURE `PCSettlementTB_SELECTByCODE`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code,
			ROW_NUMBER() OVER (ORDER BY F.SPCISID ASC) AS SN,
			F.ExpensVal								   AS ExVal,
			IFNULL('لا يوجد', F.Notes)				   AS NotesDe,
			F.EXID									   AS EXID,
			F.AccIDEX								   AS AccEX,
			b.AccID                                    AS EmpAccID,

			A.InsertDate,
			A.EMPID,
			B.EMPNAME,
			A.BranchID,
			C.BName,
			A.SafeID,
			A.CurrencyID,
			E.AccName,
			A.ISID,
			A.PCVal,
			D.ExName								   AS ExNamePC,
			A.SettlementVal,
			A.NetTotal,
			IFNULL('لا يوجد', A.Notes)				   AS Notes,

			A.IDCode,
			AccSafeID,
			A.AccIDPC								   AS AccID,
			G.CurrencyName
	FROM
			PCSettlementTB AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
		LEFT JOIN
			CoBranch AS C
				ON A.BranchID = C.ID
		LEFT JOIN
			AccountsTb AS E
				ON A.AccSafeID = E.AccID
		LEFT JOIN
			PCSettlementDetailsTB AS F
				ON A.Code = F.SPCISID
		LEFT JOIN
			ExpensesTb AS D
				ON F.EXID = D.ID
		LEFT JOIN
			CurrencyTb AS G
				ON A.CurrencyID = G.ID

	WHERE
			A.Code = p_Code
			AND A.IsActive = 1;


	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PCSettlementTB_UPDATE`;
DELIMITER //
CREATE PROCEDURE `PCSettlementTB_UPDATE`(IN `p_Code` LONGTEXT, IN `p_InsertDate` DATE, IN `p_EMPID` BIGINT, IN `p_BranchID` INT, IN `p_SafeID` BIGINT, IN `p_CurrencyID` INT, IN `p_ISID` TEXT, IN `p_PCVal` DECIMAL(12,3), IN `p_SettlementVal` DECIMAL(12,3), IN `p_Notes` LONGTEXT, IN `p_IDCode` BIGINT, IN `p_ExpensVal` DECIMAL(12,3), IN `p_AccIDEX` BIGINT, IN `p_EXID` BIGINT, IN `p_NotesDe` LONGTEXT, IN `p_AccIDSafeID` BIGINT, IN `p_AccIDPetty` BIGINT)
BEGIN
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_MovementType VARCHAR(100);
START TRANSACTION;
SET v_NetVal = p_PCVal - p_SettlementVal;
	UPDATE
			PCSettlementTB
	SET
			PCSettlementTB.IsActive = 0
	WHERE
		PCSettlementTB.Code = p_Code;


	UPDATE
			PCSettlementDetailsTB
	SET
			PCSettlementDetailsTB.IsActive = 0
	WHERE
		PCSettlementDetailsTB.SPCISID = p_Code;




	IF p_SettlementVal < p_PCVal
		 THEN
SET v_MovementType = CONCAT('معالجة خطأ في تسوية عهدة موظف رقم', ' - ', p_ISID);
			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note

					)
			VALUES
					(

						p_SafeID,
						p_PCVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						14,
						44,
						p_BranchID,
						p_AccIDPetty,
						p_AccIDSafeID,
						1,
						0,
						v_MovementType,
						p_CurrencyID,
						0,
						0,
						p_NotesDe
					);


			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
