DROP PROCEDURE IF EXISTS `PettyCashTb_Insert`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_Insert`(IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_EMPID` INT, IN `p_PettyCashVal` DECIMAL(12,3), IN `p_IDCode` BIGINT, IN `p_CurrencyID` INT, IN `p_SafeID` INT, IN `p_Notes` TEXT, IN `p_AccIDPetty` BIGINT, IN `p_AccIDSafeID` BIGINT, IN `p_MovementType` LONGTEXT, IN `p_MovementType2` LONGTEXT, IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_AccIDPettyBranch BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


			START TRANSACTION;
	SELECT a.accid INTO v_AccIDPettyBranch FROM AccountsTb as a  where AccParent like '%101070%' and a.BranchID=p_BranchID;

	IF p_IsUpdate = 0
		 THEN
		SELECT Code INTO v_GETID FROM
					PettyCashTb AS a
			WHERE
					a.Code = p_Code;
		IF p_Code = v_GETID
								 THEN
									SET p_MSGSTatues = 0;
									SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
									ROLLBACK;
									LEAVE proc;
		END IF;
			INSERT INTO PettyCashTb
					(
						Code,
						InsertDate,
						BranchID,
						EMPID,
						PettyCashVal,
						IsSettlement,
						IsActive,
						IDCode,
						CurrencyID,
						SafeID,
						PettyCashTb.Notes,
						AccIDPetty,
						PettyCashTb.AccIDSafeID
					)
			VALUES
					(
						p_Code, p_InsertDate, p_BranchID, p_EMPID, p_PettyCashVal, 0, 1, p_IDCode, p_CurrencyID, p_SafeID, p_Notes, v_AccIDPettyBranch, p_AccIDSafeID
					);


			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						p_PettyCashVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						13,
						43,
						p_BranchID,
						v_AccIDPettyBranch,
						p_AccIDSafeID,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_MovementType2
					);

			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_PettyCashVal,
						p_InsertDate,
						p_Code,
						1,
						13,
						43,
						p_BranchID,
						p_AccIDSafeID,
						v_AccIDPettyBranch,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_MovementType2
					);
			SELECT
					ID,
					Code,
					InsertDate,
					BranchID,
					EMPID,
					PettyCashVal,
					IsSettlement,
					IsActive,
					IDCode,
					CurrencyID,
					SafeID,
					PettyCashTb.Notes,
					AccIDPetty,
					PettyCashTb.AccIDSafeID
			FROM
					PettyCashTb
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					PettyCashTb
			SET
					PettyCashTb.IsActive = 0
			WHERE
				Code = p_Code;

			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						0.000,
						p_PettyCashVal,
						p_InsertDate,
						p_Code,
						1,
						13,
						43,
						p_BranchID,
						v_AccIDPettyBranch,
						p_AccIDSafeID,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_MovementType2
					);

			INSERT INTO ExSyAccounts_AccSafeActivityTb
					(

						SafeID,
						Debit,
						Credit,
						InsertDate,
						ISID,
						IsActive,
						TypeID,
						OperationTypeID,
						AccBranchID,
						AccIDFrom,
						AccIDTo,
						IsConfirmed,
						IsCanceled,
						MovementType,
						CurrencyID,
						DailyClosed,
						SafeIDDailyClose,
						Note,
						SafeIDMovement
					)
			VALUES
					(

						p_SafeID,
						p_PettyCashVal,
						0.000,
						p_InsertDate,
						p_Code,
						1,
						13,
						43,
						p_BranchID,
						p_AccIDSafeID,
						v_AccIDPettyBranch,
						1,
						0,
						p_MovementType,
						p_CurrencyID,
						0,
						0,
						p_Notes, p_MovementType2
					);
		END IF;
				COMMIT;
			SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PettyCashTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_LOADTODVG`(IN `p_BranchID` INT, IN `p_DataBaseType` INT)
BEGIN
START TRANSACTION;

IF p_DataBaseType=1
 THEN
	SELECT
			A.Code		   AS 'الرمز',
			A.InsertDate   AS 'التاريخ',
			B.EMPNAME	   AS 'الموظف',
			A.PettyCashVal AS 'القيمة'
	FROM
			PettyCashTb AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1
			AND A.IsSettlement = 0;
END IF;

IF p_DataBaseType=2
 THEN
	SELECT
			A.Code		   AS 'الرمز',
			A.InsertDate   AS 'التاريخ',
			B.PartnerName	   AS 'الموظف',
			A.PettyCashVal AS 'القيمة'
	FROM
			ContractDB.PettyCashTb AS A
		LEFT JOIN
			ContractDB.AddPartnerTb AS B
				ON A.EMPID = B.ID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1;

END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PettyCashTb_LOADTOREPORT`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_LOADTOREPORT`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code					   AS 'الرمز',
			c.BName					   AS 'الفرع',
			E.CurrencyName			   AS 'العملة',
			D.UName					   AS 'الخزنة',
			B.EMPNAME				   AS 'الموظف',
			A.PettyCashVal			   AS 'القيمة',
			IFNULL('لا يوجد', A.Notes) AS 'ملاحظة'
	FROM
			PettyCashTb AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
		LEFT JOIN
			`CoBranch` AS c
				ON A.BranchID = c.ID
		LEFT JOIN
			TB_Users AS D
				ON A.SafeID = D.USID
		LEFT JOIN
			CurrencyTb AS E
				ON A.CurrencyID = E.ID
	WHERE
			A.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PettyCashTb_LOADTORPTANOTHEREXPENS`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_LOADTORPTANOTHEREXPENS`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.InsertDate,
			A.Code					   AS 'الرمز',
			c.BName					   AS 'الفرع',
			E.CurrencyName			   AS 'العملة',
			D.UName					   AS 'الخزنة',
			A.ExpensVal				   AS 'القيمة',
			F.ExName				   AS 'اسم المصروف',
			IFNULL('لا يوجد', A.Notes) AS 'ملاحظة'
	FROM
			ANOTHEREXPENSTB AS A
		LEFT JOIN
			`CoBranch` AS c
				ON A.BranchID = c.ID
		LEFT JOIN
			TB_Users AS D
				ON A.SafeID = D.USID
		LEFT JOIN
			CurrencyTb AS E
				ON A.CurrencyID = E.ID
		LEFT JOIN
			ExpensesTb AS F
				ON A.AccIDPC = F.AccID
	WHERE
			A.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PettyCashTb_LOADTOSETLEMENT`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_LOADTOSETLEMENT`(IN `p_BranchID` INT, IN `p_EMPID` INT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code		   AS 'الرمز',
			A.InsertDate   AS 'التاريخ',
			B.EMPNAME	   AS 'الموظف',
			A.PettyCashVal AS 'القيمة'
	FROM
			PettyCashTb AS A
		LEFT JOIN
			EmployeeTb AS B
				ON A.EMPID = B.ID
	WHERE
			A.BranchID = p_BranchID
			AND A.IsActive = 1
			AND A.IsSettlement = 0
			AND A.EMPID = p_EMPID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `PettyCashTb_Select`;
DELIMITER //
CREATE PROCEDURE `PettyCashTb_Select`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

	SELECT
			A.ID,
			A.Code,
			A.InsertDate,
			A.BranchID,
			A.EMPID,
			A.PettyCashVal,
			A.IsSettlement,
			A.IsActive,
			A.IDCode,
			A.CurrencyID,
			A.SafeID,
			 Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes,
			A.AccIDPetty,
			A.AccIDSafeID,
			B.AccID  AS EmpAccID
	FROM
			PettyCashTb AS A
			join EmployeeTb AS B
			ON a.EMPID=B.ID
	WHERE
			A.Code = p_Code;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ProfileName_delete`;
DELIMITER //
CREATE PROCEDURE `ProfileName_delete`(IN `p_ProfID` INT, INOUT `p_msg` INT, IN `p_msgBox` LONGTEXT)
proc: BEGIN
DECLARE v_IDtype int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set  p_msg = 0; CALL ERROR_PROC(); END;
 START TRANSACTION;



  SELECT count (a.USID ) INTO v_IDtype FROM TB_Users as a where  a.UserType = p_ProfID;
   set p_msg = 0;
   set p_msgBox= CONCAT('عذرا لايمكن حذف هذه المجموعه لانه  يوجد بها عدد من المستخدمين وهم ', SPACE(1), CAST(v_IDtype AS CHAR));
   rollback;
   LEAVE proc;

DELETE FROM `UserROOLMAINPROFILETP`
      WHERE profid =  p_ProfID;
DELETE FROM `UserAccessProfileTemplate`
 WHERE ProfileID =  p_ProfID;

 DELETE FROM `Ueser_Group_main`
  WHERE `Profile`  =  p_ProfID;
  delete  from ProfileName  where ProfID = p_ProfID;



	  commit;
	  set p_msg  =1;
	  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ProfileName_delete_from`;
DELIMITER //
CREATE PROCEDURE `ProfileName_delete_from`(IN `p_ProfID` INT, INOUT `p_msg` INT, INOUT `p_msgBox` LONGTEXT)
proc: BEGIN
DECLARE v_IDtype int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set  p_msg = 0; CALL ERROR_PROC(); END;
 START TRANSACTION;



  SELECT count (a.USID ) INTO v_IDtype FROM TB_Users as a where  a.UserType = p_ProfID;
  if v_IDtype > 0
   THEN
   set p_msg = 0;
   set p_msgBox= CONCAT('عذرا لايمكن حذف هذه المجموعه لانه  يوجد بها عدد من المستخدمين وهم ', SPACE(1), CAST(v_IDtype AS CHAR));
   rollback;
   LEAVE proc;
   END IF;
DELETE FROM `UserROOLMAINPROFILETP`
      WHERE profid =  p_ProfID;
DELETE FROM `UserAccessProfileTemplate`
 WHERE ProfileID =  p_ProfID;

 DELETE FROM `Ueser_Group_main`
  WHERE `Profile`  =  p_ProfID;
  delete  from ProfileName  where ProfID = p_ProfID;



	  commit;
	  set p_msg  =1;
	  END //
DELIMITER ;

