DROP PROCEDURE IF EXISTS `ResignationTb_Insert`;
DELIMITER //
CREATE PROCEDURE `ResignationTb_Insert`(IN `p_Code` TEXT, IN `p_InsertDate` DATE, IN `p_ResignatoinDate` DATE, IN `p_BranchID` INT, IN `p_EMPID` INT, IN `p_Notes` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_ISExist INT;
DECLARE v_ResignationID INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
    START TRANSACTION;
    IF p_IsUpdate = 0
       THEN
        SELECT COUNT(Code) INTO v_ISExist FROM
                ResignationTb rt WHERE rt.Code=p_Code;
        IF v_ISExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'عذرا هذا الرقم موجود مسبقا';
            ROLLBACK;
            LEAVE proc;
          END IF;

        INSERT INTO ResignationTb
              (
                Code,
                InsertDate,
                BranchID,
                EMPID,
                Notes,
                ResignatoinDate,
                IsActive
              )
            SELECT
                    p_Code,
                    p_InsertDate,
                    p_BranchID,
                    p_EMPID,
                    p_Notes,
                    p_ResignatoinDate,
                    1;
        SELECT ID INTO v_ResignationID FROM
                ResignationTb rt
        WHERE
                rt.Code = p_Code;
        UPDATE
                EmployeeTb
        SET
                IsResignation = 1, ResignationID = v_ResignationID, ResignatoinDate=p_ResignatoinDate
        WHERE
          ID = p_EMPID;
      END IF;
    IF p_IsUpdate = 1
       THEN

        UPDATE
                ResignationTb
        SET
                Code = p_Code, InsertDate = p_InsertDate, BranchID = p_BranchID, EMPID = p_EMPID, Notes = p_Notes, IsActive = p_IsActive
        WHERE
          Code = p_Code;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ResignationTb_LOADEmployeeToLKP`;
DELIMITER //
CREATE PROCEDURE `ResignationTb_LOADEmployeeToLKP`(IN `p_BranchID` INT, IN `p_ISUPDATE` TINYINT(1))
BEGIN
START TRANSACTION;
  IF p_ISUPDATE=0
   THEN
  	SELECT
			ID,
			EMPNAME,
      Code
	FROM
			EmployeeTb a
	WHERE
			a.BranchID = p_BranchID
			AND a.IsActive = 1
      AND a.IsResignation=0
	ORDER BY
			a.EMPNAME;
  END IF;
	  IF p_ISUPDATE=1
   THEN
  	SELECT
			ID,
			EMPNAME,
      Code
	FROM
			EmployeeTb a
	WHERE
			a.BranchID = p_BranchID
			AND a.IsActive = 1
   	ORDER BY
			a.EMPNAME;
  END IF;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ResignationTb_LoadToDVG`;
DELIMITER //
CREATE PROCEDURE `ResignationTb_LoadToDVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

  SELECT
          a.Code       AS `الرمز`,
          InsertDate AS `التاريخ`,
          b.EMPNAME  AS `الموظف`
  FROM
          ResignationTb AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
  WHERE
          a.BranchID = p_BranchID;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ResignationTb_Select`;
DELIMITER //
CREATE PROCEDURE `ResignationTb_Select`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

  SELECT
          a.ID,
          a.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
          a.BranchID,
          a.EMPID,
          e.Code                             AS EmpCode,
          a.Notes,
          a.IsActive,
          c.ECNAME,
          DATE_FORMAT(EMPDATE, '%Y/%m/%d')      AS EMPDATE,
          DATE_FORMAT(a.ResignatoinDate, '%Y/%m/%d')      AS ResignatoinDate,
          EMPNAME
  FROM
          ResignationTb a
      INNER JOIN
        EmployeeTb e
          ON a.EMPID = e.ID
      INNER JOIN
        EmployeeClassificationTb c
          ON e.CLASSIFICATION = c.id
  WHERE
          a.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `RibbonPermission_Insert`;
DELIMITER //
CREATE PROCEDURE `RibbonPermission_Insert`(IN `p_ProfileID` INT, IN `p_RPID` INT, IN `p_CanShow` TINYINT(1), IN `p_IsUpdate` TINYINT(1))
BEGIN
START TRANSACTION;
	IF p_IsUpdate = 0
		 THEN
			INSERT INTO RibbonPermission
					(
						ProfileID,
						RPID,
						CanShow
					)
			VALUES
					(
						p_ProfileID, p_RPID, p_CanShow

					);
			SELECT
					ID,
					ProfileID,
					RPID,
					CanShow
			FROM
					RibbonPermission
			WHERE
					(ID = LAST_INSERT_ID());
		END IF;
	IF p_IsUpdate = 1
		 THEN
			UPDATE
					RibbonPermission
			SET
					ProfileID = p_ProfileID, RPID = p_RPID, CanShow = p_CanShow
			WHERE
				ProfileID = p_ProfileID
				AND RibbonPermission.RPID = p_RPID;
		END IF;
	COMMIT;
END //
DELIMITER ;

