DROP PROCEDURE IF EXISTS `SafeID_LODE`;
DELIMITER //
CREATE PROCEDURE `SafeID_LODE`(IN `p_Type` BIGINT, IN `p_UserID` INT, IN `p_UESERTYPE` INT, IN `p_BRnchID` INT, IN `p_CountryID` INT, IN `p_CurrID` INT, IN `p_TransType` INT, IN `p_Typesf` INT)
BEGIN
IF p_TransType = 0
   AND
    p_Typesf <> 2
     THEN
      IF p_Type = 0
         THEN

          SELECT
                  a.AccID,
                  a.UName AS AccName
          FROM
                  TB_Users AS a
              INNER JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  b.BranchID = p_BRnchID
                  AND a.USID = p_UserID
                  AND p_UESERTYPE <> 1
                  AND a.IsActive = 1
          UNION
          SELECT
                  a.AccID,
                  a.UName
          FROM
                  TB_Users AS a
              INNER JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  a.BranchID = p_BRnchID
                  AND p_UESERTYPE = 1
                  AND a.IsActive = 1;
        END IF;
      IF p_Type <> 0
         THEN
          SELECT
                  A.AccID,
                  A.AccName
          FROM
                  AccountsTb AS A
              LEFT JOIN
                `EmployeeTb` AS b
                  ON A.AccID = b.AccID
              LEFT JOIN
                CustomersTb AS c
                  ON A.AccID = c.AccID
              LEFT JOIN
                CoBranch AS d
                  ON a.AccID = d.CurrentAccID
          WHERE
                  A.AccParent = p_Type
                  AND A.AccActive = 1
                  AND (   b.IsActive = 1
                          OR c.IsActive = 1
                          OR (    d.IsActive = 1
                                  AND d.BranchType = 3));
        END IF;
    END IF;


  IF p_TransType = 1


     THEN
      IF p_Type <> 0
         THEN
          SELECT
                  a.AccID,
                  a.AccName

          FROM
                  `AccountsTb` AS a
          WHERE
                  SUBSTRING(CAST(a.AccParent AS CHAR), 0, 7) = p_Type
                  AND a.Accline = 4
                  AND a.CountryID = p_CountryID
          GROUP BY
                  A.AccID,
                  A.AccName
          HAVING
                  `SafeIDEMP_GetCurrAccVal`(a.AccID, p_BRnchID) > 0.000;

        END IF;
    END IF;
  IF p_TransType = 0


     THEN
      IF p_Type <> 0
         THEN
          SELECT
                  a.AccID,
                  a.AccName

          FROM
                  `AccountsTb` AS a
          WHERE
                  SUBSTRING(CAST(a.AccParent AS CHAR), 0, 6) = p_Type
                  AND a.Accline = 4
                  AND a.BranchID = p_BRnchID
          GROUP BY
                  A.AccID,
                  A.AccName
          HAVING
                  `SafeIDEMP_GetCurrAccVal`(a.AccID, p_BRnchID) > 0.000;

        END IF;
    END IF;
END //
DELIMITER ;

