DROP PROCEDURE IF EXISTS `SafeID_LODE3`;
DELIMITER //
CREATE PROCEDURE `SafeID_LODE3`(IN `p_Type` INT, IN `p_UserID` INT, IN `p_UESERTYPE` INT, IN `p_BRnchID` INT, IN `p_CountryID` INT, IN `p_CurrID` INT, IN `p_TransType` INT, IN `p_Typesf` INT)
BEGIN
IF p_TransType = 0
    AND
    p_Typesf <> 2
     THEN
      IF p_Type = 0
         THEN

          SELECT
                  a.AccID,
                  a.UName AS AccName
          FROM
                  TB_Users AS a
              INNER JOIN
                AccountsTb AS b
                  ON a.AccID = b.AccID
          WHERE
                  b.BranchID = p_BRnchID
                  AND a.USID = p_UserID
                  AND p_UESERTYPE <> 1
                  AND a.IsActive = 1
          UNION
          SELECT
                  a.AccID,
                  a.UName
          FROM
