                                  AND A.BranchID = p_BRnchID)
                          OR (    `SafeIDEMP_GetCustAccVal`(A.AccID, p_BRnchID) > 0.000
                                  AND b.BranchType = 3
                                  AND a.AccParent = 2010201)
                          OR (    a.AccParent LIKE '103020%'
                                  AND p_Type LIKE '103020%'
                                  AND A.BranchID = p_BRnchID));


        END IF;
    END IF;
  IF p_TransType = 1
    AND
    p_Typesf <> 2
     THEN
      IF p_Type = 0
         THEN
