DROP PROCEDURE IF EXISTS `SalaryCalc_LoadToCalculate`;
DELIMITER //
CREATE PROCEDURE `SalaryCalc_LoadToCalculate`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT)
BEGIN
DECLARE v_SalaryDate DATE;


  START TRANSACTION;
  SET v_SalaryDate = EOMONTH(CAST(CONCAT(p_SALARYEAR, '-', p_SALARYMONTH, '-', '01') AS DATE));
  SELECT

          A.ID,
          A.AccID,
          `اسم الموظف`,
          الفرع,
          التصنيف,
          CASE                   WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                     THEN                     a.`الراتب الأساسي`                   ELSE                   CAST(ROUND((IFNULL(a.`الراتب الأساسي`, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))           END                                 AS `الراتب الأساسي`,
          `علاوات ثابتة`,
          `علاوات أخرى`,
          `خصميات متنوعة`,
          `خصم إجازة`,
          `خصم السلفة`,
          `باقي السلفة`,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.الصافي                               ELSE                               CAST(ROUND((IFNULL(a.الصافي, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END                                                                                                                                                                          AS الصافي,
          A.BranchID,

          `رقم هاتف الموظف`,
          `الرقمي الوظيفي`,
          a.BankSalaryCalc
  FROM
          `VW_SALARYCALCLAST` AS A
  WHERE
          a.EMPDATE <= v_SalaryDate
          AND NOT EXISTS (SELECT
                      b.EMPID
              FROM
                      SalaryCalculationTb AS b
              WHERE
                      b.EMPID = A.ID
                      AND b.SALARYMONTH >= p_SALARYMONTH
                      AND b.SALARYEAR >= p_SALARYEAR

          )
          AND a.ISACTIVE=1
  ORDER BY
          ID;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalc_LoadToCalculateByEMPAccID`;
DELIMITER //
CREATE PROCEDURE `SalaryCalc_LoadToCalculateByEMPAccID`(IN `p_AccID` BIGINT, IN `p_BranchID` INT, IN `p_DDay` INT)
BEGIN
DECLARE v_WorkDays INT DEFAULT CASE               WHEN p_DDay = 0                 THEN                 30               ELSE               p_DDay - 1       END;


  START TRANSACTION;


  IF p_DDay = 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY ID ASC)                                                                              AS '#',
              A.ID,
              A.AccID,
              A.`اسم الموظف`,
              A.`الفرع`,
              A.`الراتب الأساسي`,
              A.`علاوات ثابتة`,
              A.`علاوات أخرى`,
              A.`باقي السلفة`,
              a.`خصميات متنوعة`,

              A.`الراتب الأساسي` + A.`علاوات ثابتة` + A.`علاوات أخرى` - a.`خصميات متنوعة` - A.`باقي السلفة` AS `الصافي`,
              A.BranchID
      FROM
              `VW_SALARYCALCLAST` AS A
      WHERE
              A.AccID = p_AccID
              AND A.BranchID = p_BranchID
      ORDER BY
              ID;
    END IF;


  IF p_DDay <> 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY ID ASC)                                                                                                                    AS '#',
              A.ID,
              A.AccID,
              A.`الفرع`,
              A.`الراتب الأساسي`,
              FLOOR(((A.`الراتب الأساسي` / 30) * v_WorkDays) / 5) * 5                                                                              AS 'الراتب بالأيام',
              A.`الراتب الأساسي` - FLOOR(((A.`الراتب الأساسي` / 30) * v_WorkDays) / 5) * 5                                                         AS 'القيمة المتبقية',
              A.`علاوات ثابتة`,
              A.`علاوات أخرى`,
              A.`باقي السلفة`,
              a.`خصميات متنوعة`,

              (FLOOR(((A.`الراتب الأساسي` / 30) * v_WorkDays) / 5) * 5) + A.`علاوات ثابتة` + A.`علاوات أخرى` - a.`خصميات متنوعة` - A.`باقي السلفة` AS `الصافي`,
              A.BranchID
      FROM
              `VW_SALARYCALCLAST` AS A
      WHERE
              A.AccID = p_AccID
              AND A.BranchID = p_BranchID
      ORDER BY
              ID;
    END IF;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalc_LoadToCalculateByEMPID`;
DELIMITER //
CREATE PROCEDURE `SalaryCalc_LoadToCalculateByEMPID`(IN `p_EMPID` INT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (
			ORDER BY ID ASC) AS '#',
			            A.ID,
            A.`اسم الموظف`,
            A.`الفرع`,
            A.`الراتب الأساسي`,
            A.`علاوات ثابتة`,
            A.`علاوات أخرى`,
            A.`خصميات متنوعة`,
            A.`خصم السلفة`,
            A.`الصافي`,
            A.BranchID
	FROM
			`VW_SALARYCALCLAST` AS A
	WHERE
			A.AccID = p_EMPID
			AND A.BranchID = p_BranchID
	ORDER BY
			ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalc_LoadToCalculatePrint`;
DELIMITER //
CREATE PROCEDURE `SalaryCalc_LoadToCalculatePrint`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT)
BEGIN
START TRANSACTION;

	SELECT
			b.EMPNAME			 AS 'اسم الموظف',
			c.BName				 AS 'الفرع',
			a.SalaryVal			 AS 'الراتب الأساسي',
			a.ConstanceVal		 AS 'علاوات ثابتة',
			a.BONUSVAL			 AS 'علاوات أخرى',
			DiscountsVal		 AS 'خصميات متنوعة',
			a.AdvancePaymentDisc AS 'خصم السلفة',
			a.SALARYTOTAL		 AS 'الصافي'
	FROM
			SalaryCalculationTb AS a
		LEFT OUTER JOIN
			EmployeeTb AS b
				ON a.EMPID = b.ID
		LEFT OUTER JOIN
			CoBranch AS c
				ON a.BranchID = c.ID

	WHERE
			a.SALARYMONTH = p_SALARYMONTH
			AND a.SALARYEAR = p_SALARYEAR
	ORDER BY
			a.ID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalc_LoadToCalculateTotals`;
DELIMITER //
CREATE PROCEDURE `SalaryCalc_LoadToCalculateTotals`()
BEGIN
START TRANSACTION;
	SELECT
			SUM(a.`الراتب الأساسي`) AS 'إجمالي الراتب',
			SUM(a.`علاوات ثابتة`)   AS 'إجمالي العلاوات الثابتة',
			SUM(a.`علاوات أخرى`)	AS 'إجمالي العلاوات الأخرى',
			SUM(a.`خصميات متنوعة`)  AS 'إجمالي الخصميات',
			SUM(a.`خصم السلفة`)		AS 'إجمالي خصم السلف',
			SUM(a.`الصافي`)			AS 'الإجمالي الصافي'
	FROM
			VW_SALARYCALCLAST AS a;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_CheckMonthSelected`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_CheckMonthSelected`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_IsIndivdual` TINYINT(1))
BEGIN
START TRANSACTION;

	SELECT
			SALARYMONTH,
			SALARYEAR,
			SalaryCalculationTb.IsIndivdual
	FROM
			SalaryCalculationTb
	WHERE
			SalaryCalculationTb.SALARYMONTH = p_SALARYMONTH
			AND SalaryCalculationTb.SALARYEAR = p_SALARYEAR
			AND SalaryCalculationTb.IsIndivdual = 0;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_CheckMonthSelectedIndivdual`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_CheckMonthSelectedIndivdual`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_EMPID` INT)
BEGIN
START TRANSACTION;

	SELECT
			CAST(SALARYMONTH AS SIGNED) AS SALARYMONTH,
			CAST(SALARYEAR AS SIGNED)	  AS SALARYEAR,
			SalaryCalculationTb.IsIndivdual
	FROM
			SalaryCalculationTb
	WHERE
			SalaryCalculationTb.SALARYMONTH = p_SALARYMONTH
			AND SalaryCalculationTb.SALARYEAR = p_SALARYEAR
			and EMPID =p_EMPID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_CheckMonthSelectedIndivdualEMP`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_CheckMonthSelectedIndivdualEMP`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_EMPNAME` LONGTEXT)
BEGIN
DECLARE v_EMPID INT;
START TRANSACTION;
	SELECT a.ID INTO v_EMPID FROM
			EmployeeTb AS a
	WHERE
			a.EMPNAME = p_EMPNAME;
	SELECT
			CAST(SALARYMONTH AS SIGNED) AS SALARYMONTH,
			CAST(SALARYEAR AS SIGNED)	  AS SALARYEAR,
			a.IsIndivdual,
			b.ID,
			a.EMPID					  AS EMPID2,
			b.EMPNAME,
			C.BName
	FROM
			SalaryCalculationTb AS a
		INNER JOIN
			EmployeeTb AS b
				ON a.EMPID = b.ID
		INNER JOIN
			CoBranch AS C
				ON a.BranchID = C.ID
	WHERE
			a.SALARYMONTH = p_SALARYMONTH
			AND a.SALARYEAR = p_SALARYEAR
			AND a.EMPID = v_EMPID
      AND a.IsIndivdual =p_IsIndivdual;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Delete`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Delete`(IN `p_CodeID` LONGTEXT)
BEGIN
START TRANSACTION;
	DELETE FROM
	SalaryCalculationTb
	WHERE
			CodeID = p_CodeID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_GetEMPSalaryByEMPID`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_GetEMPSalaryByEMPID`(IN `p_EMPID` INT, IN `p_MDATE` TINYINT UNSIGNED, IN `p_YDATE` INT)
BEGIN
START TRANSACTION;
	SELECT
			a.CodeID			 'الرمز',
			a.INSERTDATE		 'التاريخ',
			b.EMPNAME			 'اسم الموظف',
			c.BName				 'الفرع',
			a.SalaryVal			 'الراتب الأساسي',
			a.ConstanceVal		 'علاوة ثابتة',
			a.BONUSVAL			 'علاوة مؤقتة',
			a.DiscountsVal		 'خصميات',
			a.AdvancePaymentDisc 'خصم سلفة',
			a.SALARYTOTAL		 'الصافي',
			a.BranchID,
			a.EMPID
	FROM
			SalaryCalculationTb AS a
		LEFT OUTER JOIN
		EmployeeTb AS b
				ON a.EMPID = b.ID
		LEFT OUTER JOIN
			CoBranch AS c
				ON a.BranchID = c.ID
	WHERE
			a.IsActive = 1
			AND b.accid = p_EMPID
			AND a.SALARYMONTH = p_MDATE
			AND a.SALARYEAR = p_YDATE;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_IndivdualInsert`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_IndivdualInsert`(IN `p_INSERTDATE` DATE, IN `p_EMPID` INT, IN `p_BranchID` INT, IN `p_SalaryVal` DECIMAL(12,3), IN `p_ConstanceVal` DECIMAL(12,3), IN `p_BONUSVAL` DECIMAL(12,3), IN `p_DiscountsVal` DECIMAL(12,3), IN `p_AdvancePaymentDisc` DECIMAL(12,3), IN `p_SALARYTOTAL` DECIMAL(12,3), IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_CodeID` LONGTEXT, IN `p_SafeID` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_SecondSalaryVal` DECIMAL(12,3), IN `p_SecondConstanceVal` DECIMAL(12,3), IN `p_SecondBONUSVAL` DECIMAL(12,3), IN `p_SecondAdvancePaymentDisc` DECIMAL(12,3), IN `p_SecondSALARYTOTAL` DECIMAL(12,3), IN `p_SecondDiscountsVal` DECIMAL(12,3), IN `p_SalaryCalc` INT, IN `p_IsTotal` TINYINT(1), IN `p_DDATE` INT, IN `p_RestValue` DECIMAL(18,3))
BEGIN
DECLARE v_SalariesAccID BIGINT;
DECLARE v_EMPIDAccID BIGINT;
DECLARE v_IncreaseAccID BIGINT;
DECLARE v_EMPSalaryVal DECIMAL(12, 3);
DECLARE v_MovType LONGTEXT;
DECLARE v_Code VARCHAR(50);
DECLARE v_ADVPMNTAccID BIGINT;
DECLARE v_DisAccID BIGINT;
DECLARE v_BONUSACCID BIGINT;
DECLARE v_ADVPMNTTOTAL DECIMAL(18, 3);
DECLARE v_AnotherDis BIGINT;
DECLARE v_PaymentTimes int;
DECLARE v_PaidVal DECIMAL(18, 3);
DECLARE v_Note LONGTEXT DEFAULT 'إخلاء طرف موظف';
DECLARE v_CurDate INT;
DECLARE v_FinalDate INT;
DECLARE v_RestDaysValue DECIMAL(18, 3);


  START TRANSACTION;


  SELECT AccID INTO v_SalariesAccID FROM
          AccountsTb
  WHERE
          AccParent = 30101010
          AND AccountsTb.BranchID = p_BranchID;

  SELECT at.AccID INTO v_EMPIDAccID FROM
          AccountsTb at
      INNER JOIN
        EmployeeTb et
          ON at.AccID = et.AccID
  WHERE
          et.ID = p_EMPID;

  SELECT AccID INTO v_IncreaseAccID FROM
          AccountsTb
  WHERE
          AccParent = 30101011
          AND AccountsTb.BranchID = p_BranchID;

  SELECT AccID INTO v_BONUSACCID FROM
          AccountsTb
  WHERE
          AccParent = 30101012
          AND AccountsTb.BranchID = p_BranchID;

  SELECT EmployeeTb.SalaryVal INTO v_EMPSalaryVal FROM
          EmployeeTb
  WHERE
          EmployeeTb.ID = p_EMPID;

  SELECT AccID INTO v_ADVPMNTAccID FROM
          AccountsTb
  WHERE
          AccParent = 1010801
          AND AccountsTb.BranchID = p_BranchID;

  SELECT AccID INTO v_DisAccID FROM
          AccountsTb
  WHERE
          AccParent = 4010201
          AND AccountsTb.BranchID = p_BranchID;

  SELECT AccID INTO v_AnotherDis FROM
          AccountsTb
  WHERE
          AccParent = 4010202
          AND AccountsTb.BranchID = p_BranchID;

  IF p_SalaryCalc = 1
     THEN
      UPDATE
              EmployeeTb
      SET
              EmployeeTb.BonusVal = 0.000
      WHERE
        EmployeeTb.ID = p_EMPID;
      UPDATE
              DiscountValTb
      SET
              DiscountValTb.IsOpened = 0
      WHERE
        DiscountValTb.EMPID = p_EMPID;
      UPDATE
              IncreaseValTb
      SET
              IncreaseValTb.IsOpened = 0
      WHERE
        IncreaseValTb.EMPID = p_EMPID
        AND IncreaseValTb.IsConstant = 0;
      INSERT INTO SalaryCalculationTb
            (
              INSERTDATE,
              EMPID,
              BranchID,
              SalaryVal,
              ConstanceVal,
              BONUSVAL,
              DiscountsVal,
              AdvancePaymentDisc,
              SALARYTOTAL,
              SALARYMONTH,
              SALARYEAR,
              CodeID,
              IsActive,
              IsIndivdual
            )
      VALUES
              (
                p_INSERTDATE, p_EMPID, p_BranchID, p_SalaryVal, p_ConstanceVal, p_BONUSVAL, p_DiscountsVal, p_AdvancePaymentDisc, p_SALARYTOTAL, p_SALARYMONTH, p_SALARYEAR, p_CodeID, 1, p_IsIndivdual
              );

      IF p_SalaryVal > 0.000
         THEN
SET v_MovType = CONCAT('مرتب شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_Code = CONCAT(CAST(p_SALARYEAR AS CHAR), ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', '12', ' - ', CAST(p_EMPID AS CHAR));
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    p_SalaryVal,
                    0.000,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    12,
                    37,
                    p_BranchID,
                    v_SalariesAccID,
                    v_EMPIDAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    0.000,
                    p_SalaryVal,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    12,
                    37,
                    p_BranchID,
                    v_EMPIDAccID,
                    v_SalariesAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );
        END IF;

      IF p_ConstanceVal > 0.000
         THEN
SET v_MovType = CONCAT('علاوات ثابتة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), ' - ', '9', ' - ', CAST(p_EMPID AS CHAR));
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    0.000,
                    p_ConstanceVal,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    9,
                    36,
                    p_BranchID,
                    v_EMPIDAccID,
                    v_IncreaseAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    p_ConstanceVal,
                    0.000,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    9,
                    36,
                    p_BranchID,
                    v_IncreaseAccID,
                    v_EMPIDAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );
        END IF;

      IF p_BONUSVAL > 0.000
         THEN
SET v_MovType = CONCAT('علاوات مؤقتة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), ' - ', '9', ' - ', CAST(p_EMPID AS CHAR));
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    0.000,
                    p_BONUSVAL,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    9,
                    36,
                    p_BranchID,
                    v_EMPIDAccID,
                    v_BONUSACCID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
          VALUES
                  (
                    p_SafeID,
                    p_BONUSVAL,
                    0.000,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    9,
                    36,
                    p_BranchID,
                    v_BONUSACCID,
                    v_EMPIDAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );
        END IF;

      IF p_AdvancePaymentDisc > 0.000
         THEN
SET v_MovType = CONCAT('خصم سلفة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_Code = CONCAT(CAST(p_BranchID AS CHAR), ' - ', '10', ' - ', CAST(p_EMPID AS CHAR));
          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
