                    v_EMPIDAccID,
                    v_ADVPMNTAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0
                  );

          INSERT INTO ExSyAccounts_AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
