DROP PROCEDURE IF EXISTS `SalaryCalculationTb_IndividualSalaryByEMPSHOWRECORD`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_IndividualSalaryByEMPSHOWRECORD`(IN `p_ID` INT)
BEGIN
START TRANSACTION;
  SELECT

          CAST(SALARYMONTH AS SIGNED) AS SALARYMONTH,
          CAST(SALARYEAR AS SIGNED) AS SALARYEAR,
          a.SalaryVal,
          C.BName,
          a.EMPID,
          a.BranchID,
          b.AccID
  FROM
          SalaryCalculationTb AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      INNER JOIN
        CoBranch AS C
          ON a.BranchID = C.ID
  WHERE
          a.IsIndivdual = 1
          AND a.IsActive = 1
          AND a.ID = p_ID;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Insert`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Insert`(IN `p_INSERTDATE` DATE, IN `p_EMPID` INT, IN `p_BranchID` INT, IN `p_SalaryVal` DECIMAL(12,3), IN `p_ConstanceVal` DECIMAL(12,3), IN `p_BONUSVAL` DECIMAL(12,3), IN `p_DiscountsVal` DECIMAL(12,3), IN `p_AdvancePaymentDisc` DECIMAL(12,3), IN `p_SALARYTOTAL` DECIMAL(12,3), IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_CodeID` LONGTEXT, IN `p_SafeID` INT, IN `p_IsIndivdual` TINYINT(1), IN `p_SecondSalaryVal` DECIMAL(12,3), IN `p_SecondConstanceVal` DECIMAL(12,3), IN `p_SecondBONUSVAL` DECIMAL(12,3), IN `p_SecondAdvancePaymentDisc` DECIMAL(12,3), IN `p_SecondSALARYTOTAL` DECIMAL(12,3), IN `p_SecondDiscountsVal` DECIMAL(12,3), IN `p_SalaryCalc` INT, IN `p_Notes` LONGTEXT)
