                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose,
                  Note
                )
          VALUES
                  (
                    p_SafeID,
                    0.000,
                    p_DiscountsVal,
                    p_INSERTDATE,
                    v_Code,
                    1,
                    11,
                    34,
                    p_BranchID,
                    v_DisAccID,
                    v_EMPIDAccID,
                    1,
                    0,
                    v_MovType,
                    1,
                    0,
                    0,
                    v_Note
                  );
        END IF;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Insert2`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Insert2`(IN `p_SafeID` INT, IN `p_SalaryCalc` INT, IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_SalaryCalcType` INT)
BEGIN
DECLARE v_SalariesAccID BIGINT;
DECLARE v_EMPIDAccID BIGINT;
DECLARE v_IncreaseAccID BIGINT;
DECLARE v_EMPSalaryVal DECIMAL(12, 3);
DECLARE v_MovType LONGTEXT;
DECLARE v_MovType2 LONGTEXT;
DECLARE v_Code VARCHAR(50);
DECLARE v_ADVPMNTAccID BIGINT;
DECLARE v_DisAccID BIGINT;
DECLARE v_BONUSACCID BIGINT;
DECLARE v_LeaveDiscountAcc BIGINT;
DECLARE v_BankAcc          BIGINT;
DECLARE v_Note LONGTEXT DEFAULT 'إخلاء طرف موظف';
DECLARE v_SalaryDate DATE;

  SELECT AccID INTO v_BankAcc FROM
          AccountsTb AS a
  WHERE
          a.AccParent = 2010703;
  SET v_SalaryDate = EOMONTH(CAST(CONCAT(p_SALARYEAR, '-', p_SALARYMONTH, '-', '01') AS DATE));
  IF p_SalaryCalc = 1
     THEN
      IF p_SalaryCalcType = 0
         THEN
          INSERT INTO `SalaryCalculationTb`
                (
                  `INSERTDATE`,
                  `EMPID`,
                  `BranchID`,
                  `SalaryVal`,
                  `ConstanceVal`,
                  `BONUSVAL`,
                  `DiscountsVal`,
                  `AdvancePaymentDisc`,
                  `LeaveDiscountVal`,
                  `SALARYTOTAL`,
                  `SALARYMONTH`,
                  `SALARYEAR`,
                  `CodeID`,
                  `IsActive`,
                  `IsIndivdual`,
                  `Notes`,
                  BankSalaryCalc
                )
              SELECT
                      NOW(),
                      A.ID,
                      A.BranchID,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.`الراتب الأساسي`                               ELSE                               CAST(ROUND((IFNULL(a.`الراتب الأساسي`, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END                                                                                                                                                                          AS `الراتب الأساسي`,
                      A.`علاوات ثابتة`,
                      A.`علاوات أخرى`,
                      A.`خصميات متنوعة`,
                      A.`خصم السلفة`,
                      a.`خصم إجازة`,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.الصافي                               ELSE                               CAST(ROUND((IFNULL(a.الصافي, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END                                                                                                                                                                          AS الصافي,
                      p_SALARYMONTH                                                                                                                                                                 AS `Month`,
                      p_SALARYEAR                                                                                                                                                                   AS `Year`,
                      CONCAT(CAST(p_SALARYEAR AS CHAR), '-', CAST(p_SALARYMONTH AS CHAR), '-', CAST(A.BranchID AS CHAR), '-', CAST(ROW_NUMBER() OVER (ORDER BY A.ID ASC) AS CHAR)) AS CodeID,
                      1,
                      0,
                      '',
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= EOMONTH(CAST(CONCAT(p_SALARYEAR, '-', p_SALARYMONTH, '-', '01') AS DATE))
                      AND NOT EXISTS (SELECT
                                  b.EMPID
                          FROM
                                  SalaryCalculationTb AS b
                          WHERE
                                  b.EMPID = A.ID
                                  AND b.SALARYMONTH = p_SALARYMONTH
                                  AND b.SALARYEAR = p_SALARYEAR)
                      AND a.ISACTIVE = 1;
SET v_MovType = CONCAT('مرتب شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )

              SELECT
                      p_SafeID,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.`الراتب الأساسي`                               ELSE                               CAST(ROUND((IFNULL(a.`الراتب الأساسي`, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END,
                      0.000,
                      NOW(),
                      CONCAT(CAST(p_SALARYEAR AS CHAR), ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', '12', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      12,
                      37,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101010
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.`الراتب الأساسي` > 0.000
                      AND a.EMPDATE <= v_SalaryDate
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )

              SELECT
                      p_SafeID,
                      0.000,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.`الراتب الأساسي`                               ELSE                               CAST(ROUND((IFNULL(a.`الراتب الأساسي`, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END,
                      NOW(),
                      CONCAT(CAST(p_SALARYEAR AS CHAR), ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', '12', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      12,
                      37,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101010
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.`الراتب الأساسي` > 0.000
                      AND a.EMPDATE <= v_SalaryDate
                      AND a.ISACTIVE = 1;
SET v_MovType = CONCAT('علاوات ثابتة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      A.`علاوات ثابتة`,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '9', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      9,
                      36,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101011
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`علاوات ثابتة` > 0.000
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      A.`علاوات ثابتة`,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '9', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      9,
                      36,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101011
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate

                      AND A.`علاوات ثابتة` > 0.000
                      AND a.ISACTIVE = 1;
SET v_MovType = CONCAT('علاوات مؤقتة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      A.`علاوات أخرى`,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '9', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      9,
                      36,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101012
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate

                      AND A.`علاوات أخرى` > 0.000
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  INSERTDATE,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      A.`علاوات أخرى`,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '9', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      9,
                      36,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 30101012
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`علاوات أخرى` > 0.000
                      AND a.ISACTIVE = 1;
SET v_MovType = CONCAT('خصم سلفة شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )

              SELECT
                      p_SafeID,
                      A.`خصم السلفة`,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '10', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      10,
                      42,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 1010801
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`خصم السلفة` > 0.000
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      A.`خصم السلفة`,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '10', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      10,
                      42,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 1010801
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`خصم السلفة` > 0.000
                      AND a.ISACTIVE = 1;
          UPDATE `EXCHANGESYS2026`.`VW_SALARYCALCLAST` AS A
              INNER JOIN
                AdvancePaymentTb AS b
                  ON A.ID = b.EMPID SET PaymentTimes = PaymentTimes + 1,
                  PaidVal = PaidVal + b.ValPerMonth WHERE
            b.EMPID = A.ID
            AND a.IsActive = 1
            AND IsOpened = 1
            AND RepaymentPeroid > PaymentTimes
            AND A.`خصم السلفة` > 0.000;
          UPDATE `EXCHANGESYS2026`.`VW_SALARYCALCLAST` AS A
              INNER JOIN
                AdvancePaymentTb AS b
                  ON A.ID = b.EMPID SET IsOpened = 0 WHERE
            b.EMPID = A.ID
            AND a.IsActive = 1
            AND IsOpened = 1
            AND RepaymentPeroid = PaymentTimes
            AND A.`خصم السلفة` > 0.000;
SET v_MovType = CONCAT('خصميات شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      A.`خصميات متنوعة`,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '11', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      11,
                      34,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010201
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`خصميات متنوعة` > 0.000
                      AND a.ISACTIVE = 1;


          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      A.`خصميات متنوعة`,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '11', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      11,
                      34,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010201
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND A.`خصميات متنوعة` > 0.000
                      AND a.ISACTIVE = 1;
SET v_MovType  = CONCAT('خصميات شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
SET v_MovType2 = 'خصم إجازة غير مدفوعة';
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  Note,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      b.DiscountVal,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '54', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      54,
                      89,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010209
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      CASE                               WHEN b.LeaveType = 1                                 THEN                                 CONCAT(v_MovType2, ' لمدة ', CAST(b.OverallLeaveDays AS CHAR)) + (CASE                                         WHEN b.OverallLeaveDays > 11                                           THEN                                           ' يوم'                                         ELSE                                         ' أيام'                                 END)                               WHEN b.LeaveType = 0                                 THEN                                 CONCAT('غياب لمدة ', CAST(b.ABDays AS CHAR), ' أيام')                               WHEN b.LeaveType = 2                                 THEN                                 CONCAT('غياب بدون اذن  لمدة ', CAST(b.OverallLeaveDays AS CHAR), ' أيام')                       END,
                      1,
                      0,
                      0
              FROM
                      EmployeeTb AS A
                  LEFT JOIN
                    LeaveTB b
                      ON a.ID = b.EMPID
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND b.DiscountVal > 0.000
                      AND IsCalculated = 0
                      AND b.IsAccepted = 1
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      b.DiscountVal,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '54', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      54,
                      89,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010209
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EmployeeTb AS A
                  LEFT JOIN
                    LeaveTB b
                      ON a.ID = b.EMPID
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND b.DiscountVal > 0.000
                      AND IsCalculated = 0
                      AND b.IsAccepted = 1
                      AND a.ISACTIVE = 1;
          UPDATE
                  LeaveTB
          SET
                  IsCalculated = 1
          WHERE
            EndLeave = 1
            AND IsCalculated = 0
            AND IsAccepted = 1;

          UPDATE EmployeeTb, `EXCHANGESYS2026`.`VW_SALARYCALCLAST` AS A SET EmployeeTb.BonusVal = 0.000 WHERE
            EmployeeTb.ID = a.ID
            AND a.`علاوات أخرى` > 0.000;
          UPDATE DiscountValTb, `EXCHANGESYS2026`.`VW_SALARYCALCLAST` AS A SET DiscountValTb.IsOpened = 0 WHERE
            DiscountValTb.EMPID = a.ID
            AND a.`خصميات متنوعة` > 0.000;
          UPDATE IncreaseValTb, `EXCHANGESYS2026`.`VW_SALARYCALCLAST` AS A SET IncreaseValTb.IsOpened = 0 WHERE
            IncreaseValTb.EMPID = a.id
            AND a.`علاوات أخرى` > 0.000
            AND IsConstant = 0;
        END IF;
      IF p_SalaryCalcType = 1
         THEN
          INSERT INTO `SalaryCalculationTb`
                (
                  `INSERTDATE`,
                  `EMPID`,
                  `BranchID`,
                  `SalaryVal`,
                  `ConstanceVal`,
                  `BONUSVAL`,
                  `DiscountsVal`,
                  `AdvancePaymentDisc`,
                  `LeaveDiscountVal`,
                  `SALARYTOTAL`,
                  `SALARYMONTH`,
                  `SALARYEAR`,
                  `CodeID`,
                  `IsActive`,
                  `IsIndivdual`,
                  `Notes`,
                  BankSalaryCalc
                )
              SELECT
                      NOW(),
                      A.ID,
                      A.BranchID,
                      CASE                               WHEN A.EMPDATE < CAST(DATE_ADD(0, INTERVAL TIMESTAMPDIFF(MONTH, 0, v_SalaryDate) MONTH) AS DATE)                                 THEN                                 a.`الراتب الأساسي`                               ELSE                               CAST(ROUND((IFNULL(a.`الراتب الأساسي`, 0.000) / DAY(v_SalaryDate) * (TIMESTAMPDIFF(DAY, A.EMPDATE, v_SalaryDate) + 1)) / 5, 0) * 5 AS DECIMAL(15, 3))                       END                                                                                                                                                                          AS `الراتب الأساسي`,
                      A.`علاوات ثابتة`,
                      A.`علاوات أخرى`,
                      A.`خصميات متنوعة`,
                      A.`خصم السلفة`,
                      a.`خصم إجازة`,
                      CASE                               WHEN Account_GetAccVal(a.AccID, 1, 2) >= 0                                 THEN                                 a.`الراتب الأساسي` + `EMP_GetTempIncreaseToals`(a.EMPID) + `EMP_GetConstanceIncreaseToals`(a.EMPID) - `EMP_GetDiscTtoals`(a.EMPID) - `EMP_GetADVPMNTTtoals`(a.EMPID) - EMP_GetLeaveDiscountTotal(a.EMPID)                                ELSE                               Account_GetAccVal(a.AccID, 1, 2) +                               a.`الراتب الأساسي` + `EMP_GetTempIncreaseToals`(a.EMPID) + `EMP_GetConstanceIncreaseToals`(a.EMPID) - `EMP_GetDiscTtoals`(a.EMPID) - `EMP_GetADVPMNTTtoals`(a.EMPID) - EMP_GetLeaveDiscountTotal(a.EMPID)                       END                                                                                                                                                                          AS الصافي,
                      p_SALARYMONTH                                                                                                                                                                 AS `Month`,
                      p_SALARYEAR                                                                                                                                                                   AS `Year`,
                      CONCAT(CAST(p_SALARYEAR AS CHAR), '-', CAST(p_SALARYMONTH AS CHAR), '-', CAST(A.BranchID AS CHAR), '-', CAST(ROW_NUMBER() OVER (ORDER BY A.ID ASC) AS CHAR)) AS CodeID,
                      1,
                      0,
                      '',
                      1
              FROM
                      EXCHANGESYS2026.`VW_SALARYCALCLAST` AS A
              WHERE
                      a.EMPDATE <= EOMONTH(CAST(CONCAT(p_SALARYEAR, '-', p_SALARYMONTH, '-', '01') AS DATE))
                      AND NOT EXISTS (SELECT
                                  b.EMPID
                          FROM
                                  SalaryCalculationTb AS b
                          WHERE
                                  b.EMPID = A.ID
                                  AND b.SALARYMONTH = p_SALARYMONTH
                                  AND b.SALARYEAR = p_SALARYEAR
                                  AND b.ISACTIVE = 1)
                      AND a.ISACTIVE = 1;
SET v_MovType = CONCAT('مرتب شهر', ' - ', CAST(p_SALARYMONTH AS CHAR), ' - ', CAST(p_SALARYEAR AS CHAR));
          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
