                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  Note,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      b.DiscountVal,
                      0.000,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '54', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      54,
                      89,
                      A.BranchID,
                      A.AccID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010209
                                  AND AccountsTb.BranchID = A.BranchID),
                      1,
                      0,
                      v_MovType,
                      CASE                               WHEN b.LeaveType = 1                                 THEN                                 CONCAT(v_MovType2, ' لمدة ', CAST(b.OverallLeaveDays AS CHAR)) + (CASE                                         WHEN b.OverallLeaveDays > 11                                           THEN                                           ' يوم'                                         ELSE                                         ' أيام'                                 END)                               WHEN b.LeaveType = 0                                 THEN                                 CONCAT('غياب لمدة ', CAST(b.ABDays AS CHAR), ' أيام')                               WHEN b.LeaveType = 2                                 THEN                                 CONCAT('غياب بدون اذن  لمدة ', CAST(b.OverallLeaveDays AS CHAR), ' أيام')                       END,
                      1,
                      0,
                      0
              FROM
                      EmployeeTb AS A
                  LEFT JOIN
                    LeaveTB b
                      ON a.ID = b.EMPID
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND b.DiscountVal > 0.000
                      AND IsCalculated = 0
                      AND b.IsAccepted = 1
                      AND a.ISACTIVE = 1;

          INSERT INTO ExSyAccounts2026.AccSafeActivityTb
                (
                  SafeID,
                  Debit,
                  Credit,
                  InsertDate,
                  ISID,
                  IsActive,
                  TypeID,
                  OperationTypeID,
                  AccBranchID,
                  AccIDFrom,
                  AccIDTo,
                  IsConfirmed,
                  IsCanceled,
                  MovementType,
                  CurrencyID,
                  DailyClosed,
                  SafeIDDailyClose
                )
              SELECT
                      p_SafeID,
                      0.000,
                      b.DiscountVal,
                      NOW(),
                      CONCAT(CAST(A.BranchID AS CHAR), ' - ', '54', ' - ', CAST(A.ID AS CHAR)) AS ISID,
                      1,
                      54,
                      89,
                      A.BranchID,
                      (   SELECT
                                  AccID
                          FROM
                                  AccountsTb
                          WHERE
                                  AccParent = 4010209
                                  AND AccountsTb.BranchID = A.BranchID),
                      A.AccID,
                      1,
                      0,
                      v_MovType,
                      1,
                      0,
                      0
              FROM
                      EmployeeTb AS A
                  LEFT JOIN
                    LeaveTB b
                      ON a.ID = b.EMPID
              WHERE
                      a.EMPDATE <= v_SalaryDate
                      AND b.DiscountVal > 0.000
                      AND IsCalculated = 0
                      AND b.IsAccepted = 1
                      AND a.ISACTIVE = 1;
          UPDATE
                  LeaveTB
          SET
                  IsCalculated = 1
          WHERE
            EndLeave = 1
            AND IsCalculated = 0
            AND IsAccepted = 1;


        END IF;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_MoneyCard1`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_MoneyCard1`(IN `p_accid` INT)
BEGIN
START TRANSACTION;

  SELECT
            a.SALARYEAR      ,
          Case  a.SALARYMONTH           WHEN 1 THEN 'يناير'           WHEN 2 THEN 'فبراير'           WHEN 3 THEN 'مارس'           WHEN 4 THEN 'ابريل'           WHEN 5 THEN 'مايو'           WHEN 6 THEN 'يونيو'           WHEN 7 THEN 'يوليو'           WHEN 8 THEN 'اغسطس'           WHEN 9 THEN 'سبتمبر'           WHEN 10 THEN 'اكتوبر'           WHEN 11 THEN 'نوفمبر'           WHEN 12 THEN 'ديسمبر'           END AS SALARYMONTH ,
          b.EMPNAME            ,
          b.NATNUMBER,
c.BName,
d.ECNAME,
b.CODE,
b.PassportNo,
b.PHONE1,
DATE_FORMAT(b.EMPDATE, '%Y-%m-%d') AS EMPDATE ,
          a.SalaryVal          ,
          FORMAT(a.ConstanceVal + a.BONUSVAL, 0) AS  BONUSVAL    ,
          FORMAT(a.DiscountsVal  +a.LeaveDiscountVal, 0) AS  DiscountsVal    ,
           FORMAT(a.AdvancePaymentDisc, 0) AS AdvancePaymentDisc,
           FORMAT(a.SalaryVal+a.ConstanceVal + a.BONUSVAL -a.DiscountsVal  -a.LeaveDiscountVal -a.AdvancePaymentDisc, 0) AS   SALARYTOTAL    ,
          CASE WHEN a.Notes ='' THEN 'لا يوجد'ELSE a.Notes END AS   Notes
  FROM
          SalaryCalculationTb a
      INNER JOIN
        EmployeeTb b
          ON a.id = b.AccID
           LEFT JOIN
        CoBranch c
          ON b.BranchID = c.id
          LEFT JOIN
          EmployeeClassificationTb d
          ON b.CLASSIFICATION=d.ID
  WHERE
         b.AccID= p_accid
  ORDER BY
  a.SALARYEAR,
          a.SALARYMONTH;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Select`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Select`(IN `p_CodeID` LONGTEXT)
BEGIN
START TRANSACTION;

	SELECT
			ID,
			INSERTDATE,
			EMPID,
			BranchID,
			SalaryVal,
			ConstanceVal,
			BONUSVAL,
			DiscountsVal,
			AdvancePaymentDisc,
			SALARYTOTAL,
			SALARYMONTH,
			SALARYEAR,
			CodeID,
			IsActive
	FROM
			SalaryCalculationTb
	WHERE
			CodeID = p_CodeID;

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Statment`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Statment`(IN `p_BranchID` INT, IN `p_Month` TINYINT UNSIGNED, IN `p_Yare` INT, IN `p_IsAll` TINYINT UNSIGNED)
BEGIN
START TRANSACTION;
IF p_IsAll = 0
 THEN
SELECT
          a.SALARYMONTH        AS 'شهر',
          a.SALARYEAR          AS 'سنة',
          a.INSERTDATE         AS 'تاريخ الاحتساب',
          b.EMPNAME            AS 'الموظف',
          a.SalaryVal          AS 'الراتب الأساسي',
          a.ConstanceVal       AS 'علاوات ثابتة',
          a.BONUSVAL           AS 'علاوات أخرى',
          a.DiscountsVal       AS 'خصميات متنوعة',
          a.AdvancePaymentDisc AS 'خصم السلفة',
          a.SalaryVal+ConstanceVal+a.BONUSVAL-DiscountsVal-AdvancePaymentDisc          AS 'الصافي'
  FROM
          SalaryCalculationTb a
      INNER JOIN
        EmployeeTb b
          ON a.EMPID = b.ID
  WHERE
          a.BranchID = p_BranchID

  ORDER BY
          a.INSERTDATE;
END IF;
IF p_IsAll = 1
 THEN
  SELECT
          a.SALARYMONTH        AS 'شهر',
          a.SALARYEAR          AS 'سنة',
          a.INSERTDATE         AS 'تاريخ الاحتساب',
          b.EMPNAME            AS 'الموظف',
          a.SalaryVal          AS 'الراتب الأساسي',
          a.ConstanceVal       AS 'علاوات ثابتة',
          a.BONUSVAL           AS 'علاوات أخرى',
          a.DiscountsVal       AS 'خصميات متنوعة',
          a.AdvancePaymentDisc AS 'خصم السلفة',
          a.SalaryVal+ConstanceVal+a.BONUSVAL-DiscountsVal-AdvancePaymentDisc      AS 'الصافي'
  FROM
          SalaryCalculationTb a
      INNER JOIN
        EmployeeTb b
          ON a.EMPID = b.ID
  WHERE
          a.BranchID = p_BranchID
          AND a.SALARYMONTH = p_Month
          AND a.SALARYEAR = p_Yare

  ORDER BY
          a.INSERTDATE;
END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_Update`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_Update`(IN `p_INSERTDATE` DATE, IN `p_EMPID` INT, IN `p_BranchID` INT, IN `p_SalaryVal` DECIMAL(12,3), IN `p_ConstanceVal` DECIMAL(12,3), IN `p_BONUSVAL` DECIMAL(12,3), IN `p_DiscountsVal` DECIMAL(12,3), IN `p_AdvancePaymentDisc` DECIMAL(12,3), IN `p_SALARYTOTAL` DECIMAL(12,3), IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_CodeID` LONGTEXT)
BEGIN
START TRANSACTION;
	UPDATE
			SalaryCalculationTb
	SET
			INSERTDATE = p_INSERTDATE, EMPID = p_EMPID, BranchID = p_BranchID, SalaryVal = p_SalaryVal, ConstanceVal = p_ConstanceVal, BONUSVAL = p_BONUSVAL, DiscountsVal = p_DiscountsVal, AdvancePaymentDisc = p_AdvancePaymentDisc, SALARYTOTAL = p_SALARYTOTAL, SALARYMONTH = p_SALARYMONTH, SALARYEAR = p_SALARYEAR, IsActive = 1
	WHERE
		CodeID = p_CodeID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_ViewIndividualSalaryByEMP`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_ViewIndividualSalaryByEMP`()
BEGIN
START TRANSACTION;
  SELECT
          b.EMPNAME                 AS 'الموظف',
          CAST(SALARYMONTH AS SIGNED) AS 'الشهر',
          CAST(SALARYEAR AS SIGNED)   AS 'السنة',
          a.SalaryVal               AS 'القيمة',
          CASE                   WHEN a.IsIndivdual = 0                     THEN                     'احتساب جماعي'                   ELSE                   'احتساب فردي'           END                       AS 'حالة الاحتساب',
          C.BName                   AS 'الفرع',
          a.ID
  FROM
          SalaryCalculationTb AS a
      LEFT JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      LEFT JOIN
        CoBranch AS C
          ON a.BranchID = C.ID
  WHERE
          a.IsIndivdual = 1
          AND a.IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SalaryCalculationTb_ViewIndividualSalaryByEMPNotActive`;
DELIMITER //
CREATE PROCEDURE `SalaryCalculationTb_ViewIndividualSalaryByEMPNotActive`()
BEGIN
START TRANSACTION;
  SELECT
          a.CodeID                  ,
          b.EMPNAME                 ,
		  C.BName                   ,
          CAST(SALARYMONTH AS SIGNED) AS SALARYMONTH,
          CAST(SALARYEAR AS SIGNED)   AS SALARYEAR,
          a.SalaryVal               ,
		  a.ConstanceVal            ,
		  a.BONUSVAL                ,
		  a.DiscountsVal            ,
		  a.AdvancePaymentDisc      ,
		  a.SALARYTOTAL             ,
          a.ID
 FROM
          SalaryCalculationTb AS a
      LEFT JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      LEFT JOIN
        CoBranch AS C
          ON a.BranchID = C.ID
  WHERE
          a.IsIndivdual = 1
          AND a.IsActive = 1
		  AND b.ISACTIVE=0;


  COMMIT;
END //
DELIMITER ;

