DROP PROCEDURE IF EXISTS `Settlement_with_Agent`;
DELIMITER //
CREATE PROCEDURE `Settlement_with_Agent`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CountryTo` INT)
BEGIN
START TRANSACTION;

WITH cte AS
(
    SELECT
        ee.*,
        grp = ROW_NUMBER() OVER (ORDER BY ee.ID)
            - ROW_NUMBER() OVER (PARTITION BY ee.NewTrancPrice ORDER BY ee.ID)
    FROM ExternalEx ee
    WHERE ee.BranchDeleviredID = p_BranchID
      AND ee.ConfirmDate >= p_D1
AND ee.ConfirmDate < DATE_ADD(CAST(p_D2 AS date), INTERVAL 1 DAY)
      AND ee.CountryIDTo=p_CountryTo
      AND ee.IsActive=1
      AND ee.IsCanceled=0
)
SELECT
     FORMAT(NewTrancPrice, 3) NewTrancPrice
   , CONCAT(FORMAT(SUM(a.CurrDeliveredVal), 3), ' ', c.CurCode)   NewFinalTotal
   , FORMAT(SUM(NewCurrRecievedVal), 3) NewCurrRecievedVal
   ,MIN(ConfirmDate) InsertDate
   ,SUM(CurrDeliveredVal) SumNewFinalTotal
FROM cte a
INNER JOIN
CurrencyMainTb c
ON a.DeliveredCurrencyID=c.ID
GROUP BY NewTrancPrice, grp,CAST(ConfirmDate AS DATE),c.CurCode
ORDER BY MIN(ConfirmDate);

  COMMIT;
END //
DELIMITER ;

