DROP PROCEDURE IF EXISTS `TB_Users_CHECKUName`;
DELIMITER //
CREATE PROCEDURE `TB_Users_CHECKUName`(IN `p_UName` LONGTEXT, IN `p_USID` INT, IN `p_IsUpdate` TINYINT(1))
BEGIN


		START TRANSACTION;
		IF p_IsUpdate = 0
			 THEN
				SELECT
						A.UName
				FROM
						TB_Users AS A
				WHERE
						A.UName = p_UName;
			END IF;
		IF p_IsUpdate = 1
			 THEN
				SELECT
						A.UName
				FROM
						TB_Users AS A
				WHERE
						A.UName = p_UName
						AND A.USID <> p_USID;
			END IF;
		COMMIT;
	END //
DELIMITER ;

