			END IF;
		IF p_IsUpdate = 1
			 THEN
				SELECT
						A.UNameLog
				FROM
						TB_Users AS A
				WHERE
						A.UNameLog = p_UNameLog
						AND A.USID <> p_USID;
			END IF;
		COMMIT;
	END //
