DROP PROCEDURE IF EXISTS `TB_Users_Insert`;
DELIMITER //
CREATE PROCEDURE `TB_Users_Insert`(IN `p_USID` INT, IN `p_UName` LONGTEXT, IN `p_UNameLog` LONGTEXT, IN `p_UPass` LONGTEXT, IN `p_IsActive` TINYINT(1), IN `p_BranchID` INT, IN `p_USettingProfileID` INT, IN `p_UserType` TINYINT UNSIGNED, IN `p_IsUpdate` TINYINT(1), IN `p_EMPCurrentAccID` BIGINT, IN `p_EMPID` INT, INOUT `p_msg` INT, INOUT `p_msgBox` LONGTEXT, IN `p_IsEmplloy` INT, IN `p_ISHidden` TINYINT(1), IN `p_Phone` TEXT)
proc: BEGIN
DECLARE v_acccode       BIGINT;
DECLARE v_OldBranchID INT;
DECLARE v_AccID         BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IDParent BIGINT;
DECLARE v_SelectAccName LONGTEXT;
DECLARE v_AccName LONGTEXT;
DECLARE v_BName LONGTEXT;
DECLARE v_PreeAccName LONGTEXT;
DECLARE v_MainAccName LONGTEXT;
DECLARE v_ChekCurr INT;
DECLARE v_ID_FromEM INT;
DECLARE v_IDUESER INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; SET p_msg = 0; CALL ERROR_PROC(); END;



      START TRANSACTION;





      IF p_IsUpdate = 0
         THEN

          IF p_IsEmplloy = 0
             THEN
              SELECT USID INTO v_ID_FromEM FROM
                      TB_Users AS a
              WHERE
                      a.EMPID = p_EMPID
 ORDER BY a.USID DESC LIMIT 1;
              IF v_ID_FromEM > 0
                 THEN
                  SET p_msg = 0;
                  SET p_msgBox = CONCAT('عذرا هذا الموظف مربوط بمستخدم اخر ', SPACE(1));
                  ROLLBACK;
                  LEAVE proc;
                END IF;
            END IF;





          INSERT INTO TB_Users
                (
                  UName,
                  UNameLog,
                  UPass,
                  IsActive,
                  BranchID,
                  TypeID,
                  USettingProfileID,
                  UserType,
                  EMPCurrentAccID,
                  EMPID,
                  ISEmpOrUser,
                  CanShowHACC,
                  Phone
                )
          VALUES
                  (
                    p_UName, p_UNameLog, p_UPass, 1, p_BranchID, 1, p_USettingProfileID, p_UserType, p_EMPCurrentAccID, p_EMPID, p_IsEmplloy, p_ISHidden,p_Phone
                  );
SET v_PreeAccName = 'خزائن موظفي';
          SELECT BName INTO v_BName FROM
                  CoBranch AS a
          WHERE
                  ID = p_BranchID;
SET v_MainAccName = CONCAT(v_PreeAccName, ' ', v_BName);
          SELECT AccCode INTO v_IDParent FROM
                  AccountsTb AS a
          WHERE
                  a.AccName = v_MainAccName;
          SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                  AccountsTb AS a
          WHERE
                  AccParent = v_IDParent;
          IF v_IDcode IS NULL
             THEN
SET v_IDcode = 1;
            END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خزينة', ' ', p_UName);
          INSERT INTO AccountsTb
                (
                  AccCode,
                  AccName,
                  AccType,
                  Accline,
                  AccParent,
                  BranchID,
                  AccDmType,
                  AccFinal,
                  AccActive,
                  IDcode
                )
          VALUES
                  (
                    v_acccode,
                    v_AccName,
                    1,
                    4,
                    v_IDParent,
                    p_BranchID,
                    0,
                    1,
                    1,
                    v_IDcode
                  );
          SELECT AccID INTO v_AccID FROM
                  AccountsTb AS a
          WHERE
                  a.AccName = v_AccName;
          UPDATE
                  TB_Users
          SET
                  TB_Users.AccID = v_AccID
          WHERE
            TB_Users.UName = p_UName;
          SELECT
                  USID,
                  UName,
                  UNameLog,
                  UPass,
                  IsActive,
                  BranchID,
                  ProfileID,
                  TypeID,
                  AccID,
                  USettingProfileID,
                  UserType
          FROM
                  TB_Users
          WHERE
                  (USID = LAST_INSERT_ID());



          SELECT IFNULL(MAX(USID), 1) INTO v_IDUESER FROM
                  TB_Users;
          INSERT INTO `Ueser_Group_main_ID`
                (
                  `Profile`,
                  `GrouID`,
                  `Canshow`,
                  `ManID`,
                  `UserID`
                )

              SELECT
                      `Profile`,
                      `GrouID`,
                      `Canshow`,
                      `ManID`,
                      v_IDUESER
              FROM
                      `Ueser_Group_main`

              WHERE
                      `Profile` = p_UserType;



          INSERT INTO `UserAccessProfileTemplate_ID`
                (
                  `ProfileID`,
                  `MainID`,
                  `Group_ID`,
                  `ScreenID`,
                  `CanShow`,
                  `CanSave`,
                  `CanEdit`,
                  `CanDelete`,
                  `CanSearch`,
                  `CanPrint`,
                  `UserID`
                )




              SELECT
                      `ProfileID`,
                      `MainID`,
                      `Group_ID`,
                      `ScreenID`,
                      `CanShow`,
                      `CanSave`,
                      `CanEdit`,
                      `CanDelete`,
                      `CanSearch`,
                      `CanPrint`,
                      v_IDUESER

              FROM
                      `UserAccessProfileTemplate`
              WHERE
                      ProfileID = p_UserType;


          INSERT INTO `UserROOLMAINPROFILETP_ID`
                (
                  `profid`,
                  `canshow`,
                  `mainid`,
                  `Userid`
                )


              SELECT
                      `profid`,
                      `canshow`,
                      `mainid`,
                      v_IDUESER
              FROM
                      `UserROOLMAINPROFILETP`
              WHERE
                      profid = p_UserType;

          INSERT INTO `FrmScreensTb_Details_UESIRID`
                (
                  `ScreenID`,
                  `Can_branch`,
                  `Can_safID`,
                  `Can_Close_safid`,
                  `Can_Accfrom`,
                  `Can_accTo`,
                  `Can_ISbacnk`,
                  CaN_calCylaTion,
                  Can_CarunCe,
                  `UeserID`
                )
              SELECT
                      a.FrmScreensTb_ID,
                      0,
                      0,
                      0,
                      0,
                      0,
                      0,
                      0,
                      0,
                      v_IDUESER
              FROM
                      FrmScreensTb_selectITimsFormMovent AS a
              GROUP BY
                      a.FrmScreensTb_ID;

          INSERT INTO `NotificationUSERID`
                (
                  `profileID`,
                  `NotificationID`,
                  `canshow`,
                  `userID`
                )
              SELECT
                      a.profileID,
                      a.NotificationID,
                      1,
                      USID
              FROM
                      NotificationPROFILE AS a
                  INNER JOIN
                    ProfileName AS b
                      ON a.profileID = b.ProfID
                  INNER JOIN
                    TB_Users AS c
                      ON b.ProfID = c.UserType
              WHERE
                      c.USID = v_IDUESER
              ORDER BY
                      USID,
                      a.`profileID`,
                      a.NotificationID ASC;

        END IF;
      IF p_IsUpdate = 1
         THEN
          IF p_IsEmplloy = 0
             THEN
              SELECT a.AccID INTO v_AccID FROM
                      TB_Users AS a
              WHERE
                      a.USID = p_USID
 ORDER BY a.USID DESC LIMIT 1;
              SELECT TB_Users.BranchID INTO v_OldBranchID FROM
                      TB_Users
              WHERE
                      TB_Users.USID = p_USID
 ORDER BY TB_Users.USID DESC LIMIT 1;
              IF v_OldBranchID <> p_BranchID
                 THEN
SET v_PreeAccName = 'خزائن الموظفين';
                  SELECT BName INTO v_BName FROM
                          CoBranch AS a
                  WHERE
                          ID = p_BranchID;
SET v_MainAccName = CONCAT(v_PreeAccName, ' ', v_BName);
                  SELECT AccCode INTO v_IDParent FROM
                          AccountsTb AS a
                  WHERE
                          a.AccName = v_MainAccName;
                  SELECT MAX(a.IDcode) + 1 INTO v_IDcode FROM
                          AccountsTb AS a
                  WHERE
                          AccParent = v_IDParent;
                  IF v_IDcode IS NULL
                     THEN
SET v_IDcode = 1;
                    END IF;
SET v_acccode = CONCAT(CAST(v_IDParent AS CHAR), '0', CAST(v_IDcode AS CHAR));
SET v_AccName = CONCAT('خزينة', ' ', p_UName);
                  UPDATE
                          AccountsTb
                  SET
                          AccName = v_AccName, BranchID = p_BranchID,
                          AccountsTb.AccCode = v_acccode,
                          AccountsTb.AccParent = v_IDParent,
                          AccountsTb.IDcode = v_IDcode
                  WHERE
                    AccID = v_AccID;
                END IF;

              IF v_OldBranchID = p_BranchID
                 THEN
SET v_AccName = CONCAT('خزينة', ' ', p_UName);
                  UPDATE
                          AccountsTb
                  SET
                          AccName = v_AccName
                  WHERE
                    AccID = v_AccID;
                END IF;
            END IF;
          UPDATE
                  TB_Users
          SET
                  UName = p_UName, UNameLog = p_UNameLog, UPass = p_UPass, IsActive = p_IsActive, BranchID = p_BranchID, TypeID = 1, USettingProfileID = p_USettingProfileID, UserType = p_UserType, ISEmpOrUser = p_IsEmplloy, CanShowHACC = p_ISHidden, Phone=p_Phone
          WHERE
            ( USID = p_USID
              OR p_USID IS NULL);

                  UPDATE
                          AccountsTb
                  SET
                          AccActive=p_IsActive
                  WHERE
                    AccID = v_AccID;

          DELETE FROM
          `UserAccessProfileTemplate_ID`
          WHERE
                  UserID = p_USID;
          DELETE FROM
          `Ueser_Group_main_ID`
          WHERE
                  UserID = p_USID;
          DELETE FROM
          `UserROOLMAINPROFILETP_ID`
          WHERE
                  UserID = p_USID;
          DELETE FROM
          NotificationUSERID
          WHERE
                  userID = p_USID;

          INSERT INTO `Ueser_Group_main_ID`
                (
                  `Profile`,
                  `GrouID`,
                  `Canshow`,
                  `ManID`,
                  `UserID`
                )

              SELECT
                      `Profile`,
                      `GrouID`,
                      `Canshow`,
                      `ManID`,
                      p_USID
              FROM
                      `Ueser_Group_main`

              WHERE
                      `Profile` = p_UserType;



          INSERT INTO `UserAccessProfileTemplate_ID`
                (
                  `ProfileID`,
                  `MainID`,
                  `Group_ID`,
                  `ScreenID`,
                  `CanShow`,
                  `CanSave`,
                  `CanEdit`,
                  `CanDelete`,
                  `CanSearch`,
                  `CanPrint`,
                  `UserID`
                )




              SELECT
                      `ProfileID`,
                      `MainID`,
                      `Group_ID`,
                      `ScreenID`,
                      `CanShow`,
                      `CanSave`,
                      `CanEdit`,
                      `CanDelete`,
                      `CanSearch`,
                      `CanPrint`,
                      p_USID

              FROM
                      `UserAccessProfileTemplate`
              WHERE
                      ProfileID = p_UserType;


          INSERT INTO `UserROOLMAINPROFILETP_ID`
                (
                  `profid`,
                  `canshow`,
                  `mainid`,
                  `Userid`
                )

              SELECT
                      `profid`,
                      `canshow`,
                      `mainid`,
                      p_USID
              FROM
                      `UserROOLMAINPROFILETP`
              WHERE
                      profid = p_UserType;

          INSERT INTO `NotificationUSERID`
                (
                  `profileID`,
                  `NotificationID`,
                  `canshow`,
                  `userID`
                )
              SELECT
                      a.profileID,
                      a.NotificationID,
                      1,
                      USID
              FROM
                      NotificationPROFILE AS a
                  INNER JOIN
                    ProfileName AS b
                      ON a.profileID = b.ProfID
                  INNER JOIN
                    TB_Users AS c
                      ON b.ProfID = c.UserType
              WHERE
                      c.USID = p_USID
              ORDER BY
                      USID,
                      a.`profileID`,
                      a.NotificationID ASC;

























        END IF;
      COMMIT;
      SET p_msg = 1;
  END //
DELIMITER ;

