DROP PROCEDURE IF EXISTS `TransBetweenAccountsTB_Insert`;
DELIMITER //
CREATE PROCEDURE `TransBetweenAccountsTB_Insert`(IN `p_Code` LONGTEXT, IN `p_IDCode` BIGINT, IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_SafeAccID` BIGINT, IN `p_AccFromParent` BIGINT, IN `p_AccFrom` BIGINT, IN `p_AccToParent` BIGINT, IN `p_AccTo` BIGINT, IN `p_TransValue` DECIMAL(18,3), IN `p_Notes` LONGTEXT, IN `p_CurrencyID` INT, IN `p_SafeID` INT, INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_IsDefault BIT;
DECLARE v_MovementType VARCHAR(300);
DECLARE v_AccfromName VARCHAR(300);
DECLARE v_AccToName    VARCHAR(300);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


    START TRANSACTION;
    SELECT a.IDCode INTO v_GETID FROM
            TransBetweenAccountsTB AS a
    WHERE
            a.IDCode = p_IDCode;
    IF p_IDCode = v_GETID
       THEN
        SET p_MSGSTatues = 0;
        SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
        ROLLBACK;
        LEAVE proc;
      END IF;

    SELECT cmt.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb cmt
    WHERE
            id = p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;

    SELECT AccName INTO v_AccfromName FROM
            AccountsTb
    WHERE
            AccID = p_AccFrom;
    SELECT AccName INTO v_AccToName FROM
            AccountsTb
    WHERE
            AccID = p_AccTo;
    SET v_MovementType = CONCAT('تحويل قيمة مالية من حساب/', v_AccfromName, ' ', 'إلى حساب/', v_AccToName);
    INSERT INTO TransBetweenAccountsTB
          (
            IDCode,
            Code,
            TransDate,
            TransFrom,
            TransTo,
            CurrencyID,
            TransValue,
            Notes,
            IsActive,
            BranchID,
            SAFEID,
           AccFromParent,
           AccToParent
          )
    VALUES
            (
              p_IDCode, p_Code, NOW(), p_AccFrom, p_AccTo, p_CurrencyID, p_TransValue, p_Notes, 1, p_BranchID, p_SafeID,p_AccFromParent,p_AccToParent
            );


    IF v_IsDefault = 1
       THEN

        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (

                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                `Description`,
                SafeIDMovement,
                Note
              )
        VALUES
                (
                  p_SafeID, p_TransValue, 0.000, p_InsertDate, p_Code, 1, 37, 67, p_BranchID, p_AccFrom, p_AccTo, 1, 0, v_MovementType, p_CurrencyID, 0, 0, p_Notes, v_MovementType, p_Notes
                );

        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (

                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                `Description`,
                SafeIDMovement,
                Note
              )
        VALUES
                (
                  p_SafeID, 0.000, p_TransValue, p_InsertDate, p_Code, 1, 37, 67, p_BranchID, p_SafeAccID, p_AccFrom, 1, 0, v_MovementType, p_CurrencyID, 0, 0, p_Notes, v_MovementType, p_Notes
                );

        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (

                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                `Description`,
                SafeIDMovement,
                Note
              )
        VALUES
                (
                  p_SafeID, 0.000, p_TransValue, p_InsertDate, p_Code, 1, 37, 67, p_BranchID, p_AccTo, p_AccFrom, 1, 0, v_MovementType, p_CurrencyID, 0, 0, p_Notes, v_MovementType, p_Notes
                );

        INSERT INTO ExSyAccounts_AccSafeActivityTb
              (

                SafeID,
                Debit,
                Credit,
                InsertDate,
                ISID,
                IsActive,
                TypeID,
                OperationTypeID,
                AccBranchID,
                AccIDFrom,
                AccIDTo,
                IsConfirmed,
                IsCanceled,
                MovementType,
                CurrencyID,
                DailyClosed,
                SafeIDDailyClose,
                `Description`,
                SafeIDMovement,
                Note
              )
        VALUES
                (
                  p_SafeID, p_TransValue, 0.000, p_InsertDate, p_Code, 1, 37, 67, p_BranchID, p_SafeAccID, p_AccTo, 1, 0, v_MovementType, p_CurrencyID, 0, 0, p_Notes, v_MovementType, p_Notes
                );
      END IF;

    IF v_IsDefault <> 1
       THEN
        SET p_MSGSTatues = 0;
        SET p_MsgBox = 'عذرا هذه الميزة غير متوفرة حاليا يمكنك التحويل بالدينار الليبي فقط';
        ROLLBACK;
        LEAVE proc;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `TransBetweenAccountsTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `TransBetweenAccountsTB_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

	SELECT
			A.Code		   'الرمز',
			A.TransDate   'التاريخ',
			B.AccName	   'من حساب',
			C.AccName	   'إلى حساب',
			A.TransValue 'القيمة',
d.UName  'المستخدم'
	FROM
			TransBetweenAccountsTB  AS A
		LEFT OUTER JOIN
			AccountsTb AS B
				ON A.TransFrom = B.AccID
		LEFT OUTER JOIN
			AccountsTb AS C
				ON A.TransTo = C.AccID
        LEFT OUTER JOIN
        TB_Users as d
        ON a.SAFEID=d.USID
	WHERE
			 A.BranchID = p_BranchID
			AND A.IsActive = 1;

	COMMIT;
END //
DELIMITER ;

