DROP PROCEDURE IF EXISTS `TransCancelRequestTb_CHECKIFBRANCHCANCELDELIVERED`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_CHECKIFBRANCHCANCELDELIVERED`(IN `p_BranchID` INT)
BEGIN
SELECT
			a.ISID
	FROM
			TransCancelRequestTb AS a
		INNER JOIN
			InternalEx AS b
				ON a.ISID = b.Code
	WHERE
			b.BranchDeliveredID = p_BranchID
			AND b.IsCanceled = 5
			AND a.IsConfirmCancel = 4
			AND a.IsCanceledRequest = 0;
END //
