DROP PROCEDURE IF EXISTS `TransCancelRequestTb_GetExISID`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_GetExISID`(IN `p_BranchID` INT)
BEGIN
DECLARE v_IsMain INT;



    SELECT cb.IsMain INTO v_IsMain FROM
            CoBranch cb
    WHERE
            cb.ID = p_BranchID;

    SELECT
            a.ID,
            a.Code,
            a.BranchDeliveredID AS BDID,
            a.ConfirmType,
            c.BranchType        AS RBType


    FROM
            InternalEx AS a
        LEFT JOIN
          CoBranch b
            ON a.BranchDeliveredID = b.ID
        LEFT JOIN
          CoBranch c
            ON a.BranchRecievedID = c.ID
    WHERE


            a.IsActive = 1

            AND (   a.ConfirmType = 0
                    OR (    a.ConfirmType = 1

                            AND a.IsAccFrom <> 2)
                    OR
                    (       a.ConfirmType = 2
                            AND b.BranchType = 3))
            AND (   BranchRecievedID = p_BranchID
                    OR (    c.BranchType = 3
                            AND v_IsMain = 1))
    ORDER BY
            Code;

  END //
DELIMITER ;

