DROP PROCEDURE IF EXISTS `TransCancelRequestTb_GetRequestByID`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_GetRequestByID`(IN `p_ID` INT, IN `p_BranchID` INT)
BEGIN
SELECT
			a.ID,
			a.InsertDate,
			a.ReasonID,
			a.SafeID,
			a.BranchID,
			a.ISID,
			a.ISIDTYPE,
			a.Notes,
			a.IsActive,
			b.ID AS ICID,
			b.Code
	FROM
			TransCancelRequestTb AS a
		INNER JOIN
			InternalEx AS b
				ON a.ISID = b.code
	WHERE
			a.ID = p_ID
			AND a.BranchID = p_BranchID
			AND a.IsActive = 1
			AND b.IsActive = 1;
END //
