DROP PROCEDURE IF EXISTS `TransCancelRequestTb_Insert`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_Insert`(IN `p_InsertDate` DATE, IN `p_ReasonID` INT, IN `p_SafeID` INT, IN `p_BranchID` INT, IN `p_ISID` LONGTEXT, IN `p_ISIDTYPE` INT, IN `p_Notes` LONGTEXT)
BEGIN
INSERT INTO TransCancelRequestTb
			(
				InsertDate,
				ReasonID,
				SafeID,
				BranchID,
				ISID,
				ISIDTYPE,
				Notes,
				IsActive,
				IsConfirmCancel,
				IsCanceledRequest
			)
	VALUES
			(
				p_InsertDate, p_ReasonID, p_SafeID, p_BranchID, p_ISID, p_ISIDTYPE, p_Notes, 1, 0, 0
			);
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `TransCancelRequestTb_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
SELECT
			a.ISID
	FROM
			TransCancelRequestTb AS a
		INNER JOIN
			InternalEx AS b
				ON a.ISID = b.Code
	WHERE
			b.BranchDeliveredID = p_BranchID
			AND b.IsCanceled = 3
			AND a.IsConfirmCancel = 2
			AND a.IsCanceledRequest = 0;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `TransCancelRequestTb_Update`;
DELIMITER //
CREATE PROCEDURE `TransCancelRequestTb_Update`(IN `p_ID` INT, IN `p_InsertDate` DATE, IN `p_ReasonID` INT, IN `p_SafeID` INT, IN `p_BranchID` INT, IN `p_ISID` LONGTEXT, IN `p_ISIDTYPE` INT, IN `p_Notes` LONGTEXT)
BEGIN
UPDATE
			TransCancelRequestTb
	SET
			InsertDate = p_InsertDate, ReasonID = p_ReasonID, SafeID = p_SafeID, BranchID = p_BranchID, ISID = p_ISID, ISIDTYPE = p_ISIDTYPE, Notes = p_Notes, IsActive = 1, IsConfirmCancel = 0, IsCanceledRequest = 0
	WHERE
		ID = p_ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `TransEditRequistTb_Insert`;
DELIMITER //
CREATE PROCEDURE `TransEditRequistTb_Insert`(IN `p_InsertDate` DATE, IN `p_BranchID` INT, IN `p_ISID` LONGTEXT, IN `p_SenderName` LONGTEXT, IN `p_SPhone1` VARCHAR(50), IN `p_Phone2` VARCHAR(50), IN `p_RecievedName` LONGTEXT, IN `p_RPhone1` VARCHAR(50), IN `p_Rhpone2` VARCHAR(50), IN `p_TransType` TINYINT UNSIGNED, IN `p_EditType` TINYINT UNSIGNED)
BEGIN
DECLARE v_INTID BIGINT;
START TRANSACTION;
	SELECT ID INTO v_INTID FROM
			InternalEx ie
	WHERE
			ie.Code = p_ISID;

	INSERT INTO TransEditRequistTb
			(
				ISID,
				InsertDate,
				BranchID,
				SenderName,
				SPhone1,
				PHONE2,
				RecievedName,
				RPhone1,
				Rhpone2,
				IsConfirmed,
				IsUpdated,
				IsActive,
				TransType,
				EditType
			)
	VALUES
			(
				p_ISID, p_InsertDate, p_BranchID, p_SenderName, p_SPhone1, p_Phone2, p_RecievedName, p_RPhone1, p_Rhpone2, 0, 1, 1, p_TransType, p_EditType
			);

	UPDATE
			InternalEx
	SET
			IsEdit = 1
	WHERE
		Code = p_ISID;
	UPDATE
			TransEditRequistTb
	SET
			TransID = v_INTID
	WHERE
		ISID = p_ISID;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Transfer_commissions_inserert`;
DELIMITER //
CREATE PROCEDURE `Transfer_commissions_inserert`(IN `p_First_Value` DOUBLE, IN `p_Second_value` DOUBLE, IN `p_Commission_value` DOUBLE, IN `p_ID` INT, IN `p_typeInsertrt` INT, INOUT `p_SMG` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_First_Value_Staues int;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; set p_SMG=  0; CALL ERROR_PROC(); END;
START TRANSACTION;
if p_typeInsertrt = 0
 THEN

if p_Second_value <= p_First_Value
 THEN
set p_SMG = 0;
set p_MsgBox = 'عذرا يجب ان تكون القيمة الثاية اكبر من القيمة الاولة';
rollback;
LEAVE proc;
END IF;


SELECT count (a.ID) INTO v_First_Value_Staues FROM `Transfer_commissions` as a where   p_First_Value < a.Second_value;
select v_First_Value_Staues;
if v_First_Value_Staues > 0
 THEN
set p_SMG = 0;
set p_MsgBox = 'عذرا القيمة المدخلة موجودة مسبقاً';
rollback;
LEAVE proc;
END IF;

INSERT INTO `Transfer_commissions`
           (`First_Value`
           ,`Second_value`
           ,`Commission_value`)
		   values (p_First_Value ,p_Second_value ,p_Commission_value   );
END IF;

if p_typeInsertrt = 1
 THEN
DELETE FROM `Transfer_commissions`
      WHERE ID= p_ID;
END IF;

commit;
set p_SMG=  1;
END //
DELIMITER ;

