DROP PROCEDURE IF EXISTS `TransLoadToConfirmEdit`;
DELIMITER //
CREATE PROCEDURE `TransLoadToConfirmEdit`()
BEGIN
START TRANSACTION;
	SELECT
			ROW_NUMBER() OVER (ORDER BY a.Code ASC) AS '#',
			a.Code									AS 'الرمز',
			a.SenderName							AS 'اسم الراسل',
			a.SPhone1								'هاتف الراسل',
			a.SPhone2								'جوال الراسل',
			a.RecievedName							'اسم المستلم',
			a.RPhone1								'هاتف المستلم',
			a.RPhone2								'جوال المستلم',
			c.BName,
			''										AS 'اختيار'
	FROM
			InternalEx AS a
		LEFT OUTER JOIN
			TransEditRequistTb AS b
				ON a.code = b.ISID
		LEFT OUTER JOIN
			CoBranch AS c
				ON a.BranchRecievedID = c.ID
	WHERE
			 a.IsCanceled = 0
			AND a.IsActive = 1
			AND a.IsEdit = 1
			AND b.IsUpdated = 1
	ORDER BY
			a.Code ASC;
	COMMIT;
END //
DELIMITER ;

