DROP PROCEDURE IF EXISTS `TransTypeTb_Insert`;
DELIMITER //
CREATE PROCEDURE `TransTypeTb_Insert`(IN `p_ID` INT, IN `p_TransTypeName` LONGTEXT, IN `p_CountryID` INT, IN `p_IsActive` TINYINT(1), IN `p_IsUpdate` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_AccountID BIGINT;
DECLARE v_AccParent DECIMAL(18, 0);
DECLARE v_BName LONGTEXT;
DECLARE v_AccID BIGINT;
DECLARE v_OldeCustName LONGTEXT;
DECLARE v_OldBranchID INT;
DECLARE v_AccCode BIGINT;
DECLARE v_IDcode BIGINT;
DECLARE v_IsExist INT;
DECLARE v_CheckName LONGTEXT;
DECLARE v_OldCountry INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;
    START TRANSACTION;
    IF p_IsUpdate = 0
       THEN
        SELECT COUNT(TransTypeName) INTO v_IsExist FROM
                TransTypeTb
        WHERE
                CountryID = p_CountryID
                AND TransTypeName = p_TransTypeName;
        IF v_IsExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'نوع التحويل موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;
        INSERT INTO TransTypeTb
              (
                TransTypeName,
                CountryID
              )
            SELECT
                    p_TransTypeName,
                    p_CountryID;
        UPDATE
                CountiresTb
        SET
                IsService = 1
        WHERE
          ID = p_CountryID;
      END IF;
    IF p_IsUpdate = 1
       THEN
        SELECT CountryID INTO v_OldCountry FROM
                TransTypeTb
        WHERE
                ID = p_ID;
        UPDATE
                CountiresTb
        SET
                IsService = 0
        WHERE
          ID = v_OldCountry;
        SELECT COUNT(TransTypeName) INTO v_IsExist FROM
                TransTypeTb
        WHERE
                CountryID = p_CountryID
                AND TransTypeName = p_TransTypeName;
        IF v_IsExist > 0
           THEN
            SET p_MSGSTatues = 0;
            SET p_MsgBox = 'نوع التحويل موجود مسبقاً';
            ROLLBACK;
            LEAVE proc;
          END IF;
        UPDATE
                TransTypeTb
        SET
                TransTypeName = p_TransTypeName, CountryID = p_CountryID, IsActive = p_IsActive
        WHERE
          ID = p_ID;

        UPDATE
                CountiresTb
        SET
                IsService = 1
        WHERE
          ID = p_CountryID;
      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

