DROP PROCEDURE IF EXISTS `USERCHECK_PETTYCASHACCIDHASVAL`;
DELIMITER //
CREATE PROCEDURE `USERCHECK_PETTYCASHACCIDHASVAL`(IN `p_USERID` INT)
BEGIN
START TRANSACTION;

  SELECT
          COUNT(a.ID)
  FROM
          EmployeeTb AS a
      INNER JOIN
        PettyCashTb AS c
          ON a.ID = c.EMPID
      INNER JOIN
        TB_Users AS d
          ON a.ID = d.EMPID
  WHERE
          (D.USID = p_USERID OR a.ID=p_USERID)
          AND a.ID = c.EMPID
          AND c.IsActive = 1
          AND c.IsSettlement = 0
  GROUP BY
          c.EMPID,
          a.EMPNAME
  ORDER BY
          a.EMPNAME;
  COMMIT;
END //
DELIMITER ;

