DROP PROCEDURE IF EXISTS `UserSafe_GetTotalVal`;
DELIMITER //
CREATE PROCEDURE `UserSafe_GetTotalVal`(IN `p_SafeID` BIGINT)
BEGIN
DECLARE v_DebitTotal DECIMAL(15, 3);
DECLARE v_CreditTotal DECIMAL(15, 3);
DECLARE v_NetTotal DECIMAL(15, 3);


	START TRANSACTION;
	SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_DebitTotal FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT JOIN
			TB_Users AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			a.IsActive = 1
			AND b.IsActive = 1
			AND a.AccIDFrom = p_SafeID;
	SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_CreditTotal FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT JOIN
			TB_Users AS b
				ON a.AccIDFrom = b.AccID
	WHERE
			a.IsActive = 1
			AND b.IsActive = 1
			AND a.AccIDFrom = p_SafeID;
SET v_NetTotal = v_DebitTotal - v_CreditTotal;
	SELECT
			v_NetTotal AS NetTotoal;
	COMMIT;
END //
DELIMITER ;

