DROP PROCEDURE IF EXISTS `Withdrawal_INSERT`;
DELIMITER //
CREATE PROCEDURE `Withdrawal_INSERT`(IN `p_WDCode` LONGTEXT, IN `p_WithdrawalDate` DATE, IN `p_WithdrawalFrom` INT, IN `p_WithdrawalTo` INT, IN `p_WithdrawalValue` DECIMAL(15,3), IN `p_Notes` LONGTEXT, IN `p_BranchID` INT, IN `p_SAFEID` INT, IN `p_CurrencyID` INT, IN `p_WIDCode` BIGINT)
BEGIN
START TRANSACTION;

	INSERT INTO WithdrawalTb
			(
				WDCode,
				WithdrawalDate,
				WithdrawalFrom,
				WithdrawalTo,
				WithdrawalValue,
				Notes,
				IsActive,
				BranchID,
				SafeID,
				CurrencyID,
				WithdrawalTb.WIDCode
			)
	VALUES
			(
				p_WDCode, p_WithdrawalDate, p_WithdrawalFrom, p_WithdrawalTo, p_WithdrawalValue, p_Notes, 1, p_BranchID, p_SAFEID, p_CurrencyID, p_WIDCode

			);
	SELECT
			WithdrawalID,
			WDCode,
			WithdrawalDate,
			WithdrawalFrom,
			WithdrawalTo,
			WithdrawalValue,
			Notes,
			IsActive,
			BranchID,
			SafeID,
			CurrencyID
	FROM
			WithdrawalTb
	WHERE
			(WithdrawalID = LAST_INSERT_ID());

	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Withdrawal_LOADINTOLKPBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `Withdrawal_LOADINTOLKPBASEDONAccParent`(IN `p_BranchID` INT, IN `p_AccParent` BIGINT, IN `p_SendOrRec` TINYINT UNSIGNED, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_IsMain INT;
START TRANSACTION;


SELECT cb.IsMain INTO v_IsMain FROM  CoBranch cb WHERE cb.ID=p_BranchID;
  SELECT
          at.AccID,
          at.AccName,
          IFNULL(at.AccPhone,'0') AS AccPhone,
          IFNULL(at.AccMobile,'0') AS AccMobile,
          IFNULL(at.AccIDNo,'لا يوجد') AS AccIDNo,
         CASE WHEN at.IsHiddenAccount=0 THEN  CAST(Account_GetAccVal(at.AccID,p_CurrencyID,0) AS CHAR) ELSE 'مخفي' END AS ShowAccVal,
Account_GetAccVal(at.AccID,p_CurrencyID,0) AS GetAccVal
  FROM
          AccountsTb at
          LEFT JOIN
          CoBranch cb
          ON at.AccID=cb.CurrentAccID
  WHERE
          (at.AccParent =  p_AccParent
          AND At.accActive = 1
          AND at.BranchID = p_BranchID
          AND at.AccParent <>  2010201
          AND (Account_GetAccVal(at.AccID,p_CurrencyID,0)>0 OR at.CanDebit=1 OR at.AccDmType=0 OR p_SendOrRec=1))
          OR
          (
          at.AccParent =  2010201
          AND p_AccParent= 2010201
          AND v_IsMain=1
          AND cb.BranchType=3
          AND (Account_GetAccVal(at.AccID,p_CurrencyID,0)>0 OR at.CanDebit=1 OR at.AccDmType=0 OR p_SendOrRec=1)
          );



  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WithdrawalTb_Insert`;
DELIMITER //
CREATE PROCEDURE `WithdrawalTb_Insert`(IN `p_WDCode` LONGTEXT, IN `p_WithdrawalDate` DATE, IN `p_WithdrawalFrom` BIGINT, IN `p_WithdrawalTo` BIGINT, IN `p_WithdrawalValue` DECIMAL(15,3), IN `p_Notes` LONGTEXT, IN `p_BranchID` INT, IN `p_SAFEID` INT, IN `p_CurrencyID` INT, IN `p_WIDCode` BIGINT, IN `p_MovementType` LONGTEXT, IN `p_MovementType2` LONGTEXT, IN `p_IsUpdate` TINYINT(1), IN `p_TypID` INT, IN `p_DailyClose` TINYINT(1), INOUT `p_MSGSTatues` INT, INOUT `p_MsgBox` LONGTEXT)
proc: BEGIN
DECLARE v_GETID VARCHAR(300);
DECLARE v_IsDefault BIT;
DECLARE v_AccWithdrawalFrom BIGINT;
DECLARE v_AccWithdrawalTo BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); SET p_MSGSTatues = 0; END;


    START TRANSACTION;



    SELECT aa.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS aa
    WHERE
            aa.ID = p_CurrencyID
 ORDER BY aa.ID DESC LIMIT 1;

    IF p_WithdrawalFrom <> 0
       THEN
SET v_AccWithdrawalFrom = p_WithdrawalFrom;
      END IF;

    IF p_WithdrawalTo <> 0
       THEN
SET v_AccWithdrawalTo = p_WithdrawalTo;
      END IF;


    IF v_IsDefault = 1
       THEN


        IF p_WithdrawalFrom = 0
           THEN

            SELECT AccID INTO v_AccWithdrawalFrom FROM
                    AccountsTb AS a
            WHERE
                    a.AccParent = 1010101
                    AND a.BranchID = p_BranchID;
          END IF;

        IF p_WithdrawalTo = 0
           THEN

            SELECT AccID INTO v_AccWithdrawalTo FROM
                    AccountsTb AS a
            WHERE
                    a.AccParent = 1010101
                    AND a.BranchID = p_BranchID;
          END IF;


      END IF;



    IF v_IsDefault = 0
       THEN













        IF p_WithdrawalFrom = 0
           THEN

            SELECT AccID INTO v_AccWithdrawalFrom FROM
                    AccountsTb AS a
            WHERE
                    LEFT(AccParent, 5) = 10102
                    AND a.BranchID = p_BranchID
                    AND AccCurID = p_CurrencyID;
          END IF;

        IF p_WithdrawalTo = 0
           THEN

            SELECT AccID INTO v_AccWithdrawalTo FROM
                    AccountsTb AS a
            WHERE
                    LEFT(AccParent, 5) = 10102
                    AND a.BranchID = p_BranchID
                    AND AccCurID = p_CurrencyID;
          END IF;



      END IF;



    IF p_WithdrawalValue > 0
       THEN


        IF p_IsUpdate = 0
           THEN
            SELECT WDCode INTO v_GETID FROM
                    WithdrawalTb AS a
            WHERE
                    a.WDCode = p_WDCode;
            IF v_GETID = p_WDCode
               THEN
                SET p_MSGSTatues = 0;
                SET p_MsgBox = 'عذرا كود العملية محجوز مسبقا الرجاء الحفظ مرة أخرى';
                ROLLBACK;
                LEAVE proc;
              END IF;
            INSERT INTO WithdrawalTb
                  (
                    WDCode,
                    WithdrawalDate,
                    WithdrawalFrom,
                    WithdrawalTo,
                    WithdrawalValue,
                    Notes,
                    IsActive,
                    BranchID,
                    SafeID,
                    CurrencyID,
                    WithdrawalTb.WIDCode,
                    TypeID
                  )
            VALUES
                    (
                      p_WDCode, p_WithdrawalDate, v_AccWithdrawalFrom, v_AccWithdrawalTo, p_WithdrawalValue, p_Notes, 1, p_BranchID, p_SAFEID, p_CurrencyID, p_WIDCode, p_TypID
                    );

            IF v_IsDefault = 1
               THEN

                INSERT INTO ExSyAccounts_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, 0.000, p_WithdrawalValue, p_WithdrawalDate, p_WDCode, 4, 33, p_BranchID, v_AccWithdrawalFrom, v_AccWithdrawalTo, 1, 0, p_MovementType2, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType2
                        );


                INSERT INTO ExSyAccounts_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, p_WithdrawalValue, 0.000, p_WithdrawalDate, p_WDCode, 4, 33, p_BranchID, v_AccWithdrawalTo, v_AccWithdrawalFrom, 1, 0, p_MovementType, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType
                        );
              END IF;


            IF v_IsDefault = 0
               THEN

                INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, p_WithdrawalValue, 0.000, p_WithdrawalDate, p_WDCode, 4, 33, p_BranchID, v_AccWithdrawalFrom, v_AccWithdrawalTo, 1, 0, p_MovementType2, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType2
                        );


                INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, 0.000, p_WithdrawalValue, p_WithdrawalDate, p_WDCode, 4, 33, p_BranchID, v_AccWithdrawalTo, v_AccWithdrawalFrom, 1, 0, p_MovementType, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType
                        );
              END IF;


          END IF;
        IF p_IsUpdate = 1
           THEN
            UPDATE
                    WithdrawalTb
            SET

                    WithdrawalTb.IsActive = 0
            WHERE
              WithdrawalTb.WDCode = p_WDCode;

            IF v_IsDefault = 1
               THEN
                INSERT INTO ExSyAccounts_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, p_WithdrawalValue, 0.000, p_WithdrawalDate, p_WDCode, 4, 14, p_BranchID, v_AccWithdrawalFrom, v_AccWithdrawalTo, 1, 0, p_MovementType2, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType2
                        );


                INSERT INTO ExSyAccounts_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, 0.000, p_WithdrawalValue, p_WithdrawalDate, p_WDCode, 4, 15, p_BranchID, v_AccWithdrawalTo, v_AccWithdrawalFrom, 1, 0, p_MovementType, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType
                        );
              END IF;
            IF v_IsDefault = 0
               THEN

                INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, 0.000, p_WithdrawalValue, p_WithdrawalDate, p_WDCode, 4, 15, p_BranchID, v_AccWithdrawalFrom, v_AccWithdrawalTo, 1, 0, p_MovementType2, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType2
                        );


                INSERT INTO ExSyAccountsCurrency_AccSafeActivityTb
                      (
                        SafeID,
                        Debit,
                        Credit,
                        InsertDate,
                        ISID,
                        TypeID,
                        OperationTypeID,
                        AccBranchID,
                        AccIDFrom,
                        AccIDTo,
                        IsConfirmed,
                        IsCanceled,
                        MovementType,
                        CurrencyID,
                        DailyClosed,
                        SafeIDDailyClose,
                        Note,
                        IsActive,
                        SafeIDMovement
                      )
                VALUES
                        (
                          p_SAFEID, p_WithdrawalValue, 0.000, p_WithdrawalDate, p_WDCode, 4, 14, p_BranchID, v_AccWithdrawalTo, v_AccWithdrawalFrom, 1, 0, p_MovementType, p_CurrencyID, p_DailyClose, p_SAFEID, p_Notes, 1, p_MovementType
                        );


              END IF;
            SELECT
                    WithdrawalID,
                    WDCode,
                    WithdrawalDate,
                    WithdrawalFrom,
                    WithdrawalTo,
                    WithdrawalValue,
                    Notes,
                    IsActive,
                    BranchID,
                    SafeID,
                    WithdrawalTb.CurrencyID,
                    TypeID
            FROM
                    WithdrawalTb
            WHERE
                    (WithdrawalID = LAST_INSERT_ID());
          END IF;
      END IF;

    IF p_TypID = 17
       THEN
        IF v_IsDefault = 1
           THEN
            UPDATE
                    ExSyAccounts_AccSafeActivityTb
            SET
                    DailyClosed = 1, SafeIDDailyClose = p_SAFEID
            WHERE
              AccIDFrom = p_WithdrawalFrom
              AND (CurrencyID = p_CurrencyID
                OR currencyID = 13);
          END IF;
        IF v_IsDefault = 0
           THEN
            UPDATE
                    ExSyAccountsCurrency_AccSafeActivityTb
            SET
                    DailyClosed = 1, SafeIDDailyClose = p_SAFEID
            WHERE
              AccIDFrom = p_WithdrawalFrom
              AND CurrencyID = p_CurrencyID;
            UPDATE
                    ExSyAccountsCurrency_CurrencymovementPruse
            SET
                    DailyClose = 1
            WHERE
              ACCID = p_WithdrawalFrom
              AND ACCFRom = p_CurrencyID;
          END IF;

      END IF;
    COMMIT;
    SET p_MSGSTatues = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WithdrawalTb_MaxID`;
DELIMITER //
CREATE PROCEDURE `WithdrawalTb_MaxID`(IN `p_typID` INT, IN `p_BranchID` INT, IN `p_USRID` INT, IN `p_CountryID` INT, IN `p_CityID` INT)
BEGIN
DECLARE v_Code LONGTEXT;
SET v_Code = CONCAT(CAST(p_CountryID AS CHAR), CAST(p_CityID AS CHAR), CAST(p_BranchID AS CHAR), CAST(p_typID AS CHAR), '-', CAST(p_USRID AS CHAR), '-', CAST(WithdrawalTb_GetMaxIDCode() AS CHAR));
	SELECT
			v_Code							AS Code,
			WithdrawalTb_GetMaxIDCode() AS ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WithdrawalTb_SEARCH`;
DELIMITER //
CREATE PROCEDURE `WithdrawalTb_SEARCH`(IN `p_WDCode` LONGTEXT)
BEGIN
DECLARE v_crunseType BIT;
START TRANSACTION;
	SELECT cmt.IsDefault INTO v_crunseType FROM
			CurrencyMainTb cmt;

	SELECT
			a.WDCode,
			a.WithdrawalDate,
			d.BName,
			e.CurrencyName,
			a.WithdrawalFrom,
			a.WithdrawalTo,
			f.AccName										  AS firstuname,
			g.AccName										  AS Seconduname,
			a.WithdrawalValue,
			`EMPORCUST_GetAccVal`(f.AccID, A.CurrencyID) AS 'رصيد الحساب',
			a.BranchID,
			a.CurrencyID,
			 Case When A.Notes =''  Then 'لا يوجد' else A.Notes END as Notes
	FROM
			WithdrawalTb AS a
		LEFT JOIN
			AccountsTb AS b
				ON a.WithdrawalFrom = b.AccID
		LEFT JOIN
			AccountsTb AS c
				ON a.WithdrawalTo = c.AccID
		LEFT JOIN
			CoBranch AS d
				ON a.BranchID = d.ID
		LEFT JOIN
			CurrencyTb AS e
				ON a.CurrencyID = e.ID
		LEFT JOIN
			AccountsTb AS f
				ON a.WithdrawalFrom = f.AccID
		LEFT JOIN
			AccountsTb AS g
				ON a.WithdrawalTo = g.AccID


	WHERE
			a.IsActive = 1
			AND WDCode = p_WDCode;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WorkshopOperationsTB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `WorkshopOperationsTB_LOADTODVG`(IN `p_BranchID` INT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code         AS 'الرمز',
          A.InsertDate   AS 'التاريخ',
          B.AccName  AS 'من حساب',
          c.AccName AS 'إلى حساب',
          a.NetVal  AS 'القيمة'
  FROM
          WorkshopOperationsTB AS A
      INNER JOIN
        AccountsTb AS B
          ON A.AccIDFrom = B.AccID
            INNER JOIN
        AccountsTb AS C
          ON A.AccIDTO = C.AccID
  WHERE
          A.BranchID = p_BranchID
          AND A.IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WorkshopOperationsTB_LOADTOSELECT`;
DELIMITER //
CREATE PROCEDURE `WorkshopOperationsTB_LOADTOSELECT`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code       ,
          A.InsertDate ,
          a.AccIDFrom,
          A.AccIDFrom AS UserAccID,
          A.AccIDTO,
          a.NetVal,
          a.CodeID,
          a.BranchID,
          a.TypeID,
          a.Note ,
          a.ActivityAccCode,
          A.CountOfOperation,
          BankNo,
          CustName,
          CustBankNo,
          CustPhone
  FROM
          WorkshopOperationsTB AS A

  WHERE
          A.Code = p_Code
          AND A.IsActive = 1;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZPRT_SalaryCalc_LoadToCalculateByEMPID`;
DELIMITER //
CREATE PROCEDURE `ZPRT_SalaryCalc_LoadToCalculateByEMPID`(IN `p_AccID` BIGINT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;
  SELECT
          ROW_NUMBER() OVER (
          ORDER BY A.ID ASC) AS '#',
          A.ID,
          A.AccID,
          A.`اسم الموظف`,
          A.`الفرع`,
          A.`الراتب الأساسي`,
          A.`علاوات ثابتة`,
          A.`علاوات أخرى`,
          A.`خصميات متنوعة`,
          A.`خصم السلفة`,
          A.`الصافي`,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END                AS Phone,
          A.BranchID
  FROM
          `VW_SALARYCALCLAST` AS A
      LEFT JOIN
        CoBranch AS C
          ON A.BranchID = C.ID
  WHERE
          A.AccID = p_AccID
          AND A.BranchID = p_BranchID
  ORDER BY
          ID;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccountsTb_LoadMainBranchSafes`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccountsTb_LoadMainBranchSafes`(IN `p_BranchID` INT, IN `p_SType` INT)
BEGIN
START TRANSACTION;
  IF p_SType = 0
     THEN
        SELECT
              ROW_NUMBER() OVER (
              ORDER BY x.AccID ASC) AS '#',
              x.AccID,
              x.AccName             AS 'الخزنة',
              x.Total               AS 'الرصيد'
      FROM
              (   SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Account_GetAccVal(a.AccID,b.CurrencyID,0) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccounts_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE
                          NOT EXISTS (SELECT
                                      b.AccID
                              FROM
                                      TB_Users AS b
                              WHERE
                                      a.AccID = b.AccID
                                      AND b.BranchID = p_BranchID)
                          AND a.BranchID = p_BranchID
                          AND a.AccParent = 1010101
                          AND Accline = 4
                          AND (   b.CurrencyID = 1
                                  OR b.CurrencyID = 13)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID
UNION
                           SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Account_GetAccVal(a.AccID,b.CurrencyID,0) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccounts_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE

                           a.BranchID = p_BranchID
                          AND a.AccParent LIKE '101040%'
                          AND Accline = 4
                          AND (   b.CurrencyID = 1
                                  OR b.CurrencyID = 13)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID

                  UNION

                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccID,
                          b.AccName,
                          Sum_MainSAfes(p_BranchID, A.CurrencyID, 1) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                  WHERE
                          A.IsActive = 1
                          AND LEFT(b.AccParent, 5) = 10102
                          AND A.AccBranchID = p_BranchID
                          AND (   A.CurrencyID <> 1
                                  OR A.CurrencyID <> 13)
                  GROUP BY
                          b.AccID,
                          b.AccName,
                          A.CurrencyID

                  UNION


                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY a.AccID ASC) AS Rownum,
                          a.AccID,
                          a.AccName,
                          Sum_MainSAfes(p_BranchID, b.CurrencyID, 2) AS Total
                  FROM
                          AccountsTb AS a
                      INNER JOIN
                        ExSyAccountsCurrency_AccSafeActivityTb AS b
                            ON a.AccID = b.AccIDFrom
                  WHERE
                          NOT EXISTS (SELECT
                                      b.AccID
                              FROM
                                      TB_Users AS b
                              WHERE
                                      a.AccID = b.AccID
                                      AND b.BranchID = p_BranchID)
                          AND a.BranchID = p_BranchID
                          AND a.AccParent = 10104
                          AND Accline = 4
                          AND (   b.CurrencyID <> 1
                                  OR b.CurrencyID <> 13)
                  GROUP BY
                          a.AccID,
                          a.AccName,
                          b.CurrencyID

                  UNION
                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccParent AS AccID,
                          CONCAT('خزائن الموظفين', SPACE(1), c.CuName) AS AccName,
                          IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(A.Debit), 0) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      INNER JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                      INNER JOIN
                        CurrencyMainTb AS c
                            ON a.CurrencyID = c.ID
                  WHERE
                          A.IsActive = 1
                          AND A.AccBranchID = p_BranchID
                          AND LEFT(b.AccParent, 5) = 10104
                          AND a.DailyClosed = 0
                  GROUP BY
                          b.AccParent,
                          b.AccID,
                          A.CurrencyID,
                          c.CuName
                  UNION

                  SELECT
                          ROW_NUMBER() OVER (
                          ORDER BY b.AccID ASC) AS Rownum,
                          b.AccParent AS AccID,
                          CONCAT('حسابات المصارف لعملة', SPACE(1), c.CuName) AS AccName,
                          Sum_MainSAfes(p_BranchID, A.CurrencyID, 3) AS Total

                  FROM
                          ExSyAccountsCurrency_AccSafeActivityTb AS A
                      JOIN
                        AccountsTb AS b
                            ON A.AccIDFrom = b.AccID
                      INNER JOIN
                        CurrencyMainTb AS c
                            ON a.CurrencyID = c.ID
                  WHERE
                          A.IsActive = 1
                          AND LEFT(b.AccParent, 5) = 10105
                          AND A.AccBranchID = p_BranchID
                          AND (   A.CurrencyID <> 1
                                  OR A.CurrencyID <> 13)
                  GROUP BY
                          b.AccID,
                          A.CurrencyID,
                          c.CuName,
                          b.AccParent) x
                                                    GROUP BY x.AccID,
                          x.AccName,
                          x.Total
                          HAVING x.Total<>0;
    END IF;
  IF p_SType = 1
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.AccID ASC)                                          AS '#',
              a.AccID,
              a.AccName                                                      AS 'الخزنة',
              FORMAT(`EMPCUST_GetAccVal`(a.AccID) * -1, 3) AS 'الرصيد'
      FROM
              AccountsTb AS a
      WHERE
              a.CountryID = p_BranchID
              AND LEFT(a.AccParent, 6) = 101012
              AND Accline = 4
              AND `EMPCUST_GetAccVal`(a.AccID) * -1 > 0;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_ACCOUNTSTB_select_for`;
DELIMITER //
CREATE PROCEDURE `ZRPT_ACCOUNTSTB_select_for`(IN `p_tybid` INT, IN `p_dat1` DATE, IN `p_date2` DATE, IN `p_accline` TINYINT UNSIGNED, IN `p_BrnchID` INT)
BEGIN
DECLARE v_SELECTASS INT DEFAULT 0;
DECLARE v_SELECTDASS INT DEFAULT 0;
DECLARE v_MainBranch INT;
DECLARE v_Ismain BIT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;  END;

    START TRANSACTION;


    SELECT co.IsMain INTO v_Ismain FROM
            CoBranch AS co
    WHERE
            co.ID = p_BrnchID;
    SELECT co.ID INTO v_MainBranch FROM
            CoBranch AS co
    WHERE
            co.IsMain = 1;
    IF p_tybid = 0
       THEN
        SELECT
                AccCode,
                AccName,
                LEFT(AccCode, 1)
                AS ID,
                AccID,
                FORMAT(sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1), 2)               AS debet,
                FORMAT(sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1), 2)                   AS credet,
                v_SELECTASS                                                                               AS INSERTDEBIT,
                v_SELECTDASS                                                                              AS INSERCREDET,
                FORMAT(sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1) + v_SELECTDASS, 2) AS Noetes,
                FORMAT(sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1) + v_SELECTASS, 2)      AS total
        FROM
                AccountsTb
        WHERE
                AccActive = 1
                AND BranchID = p_BrnchID

                AND (   Accline = p_accline
                        OR p_accline = 0)
        GROUP BY
                AccCode,
                AccName,
                AccID
        HAVING
                sumDEBETalter(p_tybid, AccCode, p_dat1, p_date2, 1) > 0
                OR sumcredet(p_tybid, AccCode, p_dat1, p_date2, 1) > 0
        ORDER BY

                AccCode;
      END IF;


    IF p_tybid = 1
       THEN
        IF v_Ismain = 1
           THEN
            SELECT
                    AccCode,
                    AccName,
                    CASE                             WHEN accparent LIKE '10109%'                               THEN                               'مشترك جمعية'                             WHEN accparent LIKE '1010100%'                               THEN                               'حساب مدين'                             WHEN accparent LIKE '20103%'                               THEN                               'عميل'                             WHEN accparent LIKE '20105%'                               THEN                               'موظف'                             WHEN accparent LIKE '10104%'                               THEN                               'خزنة موظف'                             WHEN accparent LIKE '201010%'                               THEN                               'شريك'                             ELSE                             '-'                     END                                                                                                                                                         AS accparent,
                    AccID,
                    FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) + Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2) AS debet,
                    FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) + Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)         AS credet,
                    v_SELECTASS                                                                                                                                                  AS INSERTDEBIT,
                    v_SELECTDASS                                                                                                                                                 AS INSERCREDET,
                    CASE                             WHEN (sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) + (Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0                               THEN                               FORMAT((sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) + (Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)), 2)                             ELSE                             '0.00'                     END                                                                                                                                                         AS Noetes,
                    CASE                             WHEN (sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) + (Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0                               THEN                               FORMAT((sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) + (Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)), 2)                             ELSE                             '0.00'                     END                                                                                                                                                         AS total
            FROM
                    AccountsTb AS a
            WHERE
                    AccActive = 1
                    AND AccType = p_tybid
                    AND (   (       a.BranchID = p_BrnchID
                                    AND (   AccParent <> 2010201
                                            OR AccParent <> 2010701))
                            OR (    a.BranchID <> p_BrnchID
                                    AND (   AccParent = 2010201
                                            OR AccParent = 2010701)))
            GROUP BY
                    AccCode,
                    AccName,
                    AccID,
                    accparent
            HAVING
                    (sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) + Ass_sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0
                    OR (sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) + Ass_sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID)) > 0;


          END IF;

        IF v_Ismain <> 1
           THEN
            BEGIN
              SELECT
                      AccCode,
                      AccName,
                      AccID,
                      CASE                               WHEN accparent LIKE '10109%'                                 THEN                                 'مشترك جمعية'                               WHEN accparent LIKE '1010100%'                                 THEN                                 'حساب مدين'                               WHEN accparent LIKE '20103%'                                 THEN                                 'عميل'                               WHEN accparent LIKE '20105%'                                 THEN                                 'موظف'                               WHEN accparent LIKE '10104%'                                 THEN                                 'خزنة موظف'                               WHEN accparent LIKE '201010%'                                 THEN                                 'شريك'                               ELSE                               '-'                       END                                                                                   AS accparent,
                      FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2) AS debet,
                      FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)     AS credet,
                      v_SELECTASS                                                                            AS INSERTDEBIT,
                      v_SELECTDASS                                                                           AS INSERCREDET,
                      CASE                               WHEN sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0                                 THEN                                 FORMAT(sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)                               ELSE                               '0'                       END                                                                                   AS Noetes,
                      CASE                               WHEN sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0                                 THEN                                 FORMAT(sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) - sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID), 2)                               ELSE                               '0'                       END                                                                                   AS total
              FROM
                      AccountsTb AS a
              WHERE
                      AccActive = 1
                      AND AccType = p_tybid
                      AND (   (       a.BranchID = v_MainBranch
                                      AND (   AccParent = 2010201
                                              OR AccParent = 2010701))
                              OR (    a.BranchID = p_BrnchID
                                      AND (   AccParent <> 2010201
                                              OR AccParent <> 2010701)))
              GROUP BY
                      AccCode,
                      AccName,
                      AccID,
                      accparent
              HAVING
                      sumDEBETalter1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0
                      OR sumcredet1(p_tybid, AccCode, p_dat1, p_date2, 1, p_BrnchID) > 0
              ORDER BY
                      AccCode;
            END;
          END IF;

      END IF;

    COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_GETBBranchMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_GETBBranchMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT)
BEGIN
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_CurrencyID BIT;


  START TRANSACTION;
  SELECT IsDefault INTO v_CurrencyID FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.id = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
  IF v_CurrencyID = 1
     THEN
      SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO v_PrievewBalance FROM
              ExSyAccounts_AccSafeActivityTb AS a
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate < p_D1;
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.ID ASC)                                                                                          AS '#',
              a.ISID                                                                                                      AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                          'التاريخ',
              b.CurrencyName                                                                                              'العملة',
              FORMAT(a.Debit, 3)                                                                              'مدين',
              FORMAT(a.Credit, 3)                                                                             'دائن',
              FORMAT(`CUSTMOVEMENT_GetNetTotal`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo) * -1, 3) AS 'الرصيد',
              a.MovementType                                                                                              'طبيعة الحركة',
              a.Description                                                                                               AS 'ملاحظات',
              v_PrievewBalance                                                                                             AS PrievewBalance
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN
            CurrencyTb AS b
              ON a.CurrencyID = b.ID
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
      ORDER BY
              a.ID ASC;
    END IF;
  IF v_CurrencyID = 0
     THEN
      SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO v_PrievewBalance FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS a
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate < p_D1
              AND a.CurrencyID = p_CurrencyTo;
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.ID ASC)                                                                                          AS '#',
              a.ISID                                                                                                      AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                          'التاريخ',
              b.CuName                                                                                                    'العملة',
              FORMAT(a.Credit, 3)                                                                             'مدين',
              FORMAT(a.Debit, 3)                                                                              'دائن',

              FORMAT(`CUSTMOVEMENT_GetNetTotal`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo) * -1, 3) AS 'الرصيد',
              a.MovementType                                                                                              'طبيعة الحركة',
              a.Description                                                                                               AS 'ملاحظات',
              v_PrievewBalance                                                                                             AS PrievewBalance
      FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN
            CurrencyMainTb AS b
              ON a.CurrencyID = b.ID
      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND a.CurrencyID = p_CurrencyTo
      ORDER BY
              a.ID ASC;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_GETByEXPENSE`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_GETByEXPENSE`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          A.ISID                             AS 'الرمز',
          A.Debit                            AS 'مدين',
          A.Credit                           AS 'دائن',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
          A.MovementType                     AS 'طبيعة الحركة',
          A.Note                             AS 'ملاحظات'
  FROM
          ExSyAccounts_AccSafeActivityTb  AS A
      INNER JOIN
        AccountsTb AS B
          ON A.AccIDFrom = B.AccID

  WHERE
          A.AccBranchID = p_BranchID
          AND A.InsertDate BETWEEN p_D1 AND p_D2
          AND A.IsActive = 1
          AND A.CurrencyID = 1
          AND a.AccIDFrom = p_AccID;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_GETCUSTMOVEMENT`;
DELIMITER //
