                  b.CurrencyName                                                                                                                'العملة',
                  FORMAT(a.Debit, 3)                                                                                                'مدين',
                  FORMAT(a.Credit, 3)                                                                                               'دائن',
                  FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                                                'طبيعة الحركة',
                  CASE                           WHEN a.Description = ''                             THEN                             'لايوجد'                           ELSE                           a.Description                   END                                                                                                                           AS 'ملاحظات',
                  v_PrievewBalance                                                                                                               AS PrievewBalance
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.IsBank = 1
          ORDER BY
                  a.ID ASC;
        END IF;
      IF v_CurrencyID = 0
         THEN
          SELECT FORMAT(IFNULL(SUM(Credit), 0) - IFNULL(SUM(Debit), 0), 3) INTO p_NEt_Totale FROM
                  ExSyAccountsCurrency_AccSafeActivityTb
          WHERE
                  AccIDFrom = p_AccID
                  AND InsertDate BETWEEN p_D1 AND p_D2
                  AND IsActive = 1
                  AND CurrencyID = p_CurrencyTo;
          SELECT FORMAT(IFNULL(SUM(Credit), 0) - IFNULL(SUM(Debit), 0), 3) INTO p_sumtotal FROM
                  ExSyAccountsCurrency_AccSafeActivityTb
          WHERE
                  AccIDFrom = p_AccID
                  AND IsActive = 1
                  AND CurrencyID = p_CurrencyTo;


          SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS a
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate < p_D1
                  AND a.CurrencyID = p_CurrencyTo;
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                                            AS '#',
                  a.ISID                                                                                                                        AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                                            'التاريخ',
                  DATE_FORMAT(p_D1, '%Y/%m/%d')                                                                                                     AS D1,
                  DATE_FORMAT(p_D2, '%Y/%m/%d')                                                                                                     AS D2,
                  b.CuName                                                                                                                      'العملة',
                  FORMAT(a.Credit, 3)                                                                                               'مدين',
                  FORMAT(a.Debit, 3)                                                                                                'دائن',

                  FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                                                'طبيعة الحركة',
                  CASE                           WHEN a.Description = ''                             THEN                             'لايوجد'                           ELSE                           a.Description                   END                                                                                                                           AS 'ملاحظات',
                  v_PrievewBalance                                                                                                               AS PrievewBalance
          FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS a
              LEFT JOIN
                CurrencyMainTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.CurrencyID = p_CurrencyTo
          ORDER BY
                  a.ID ASC;
        END IF;
    END IF;


  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_GETEMPMOVEMENT`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_GETEMPMOVEMENT`(IN `p_AccID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyTo` INT, IN `p_Type` TINYINT UNSIGNED)
BEGIN
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_IsDefault BIT;


  START TRANSACTION;
  SELECT IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.id = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

  IF p_Type = 0
     THEN
      IF v_IsDefault = 1
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccounts_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND (   c.CurrencyID = p_CurrencyTo
                          OR c.CurrencyID = 13);
        END IF;

      IF v_IsDefault = 0
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND c.CurrencyID = p_CurrencyTo;
        END IF;

      IF v_IsDefault = 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND (   a.CurrencyID = p_CurrencyTo
                          OR a.CurrencyID = 13);
        END IF;


      IF v_IsDefault = 0
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.CurrencyID = p_CurrencyTo;
        END IF;

    END IF;




  IF p_Type = 1
     THEN
      IF v_IsDefault = 1
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccounts_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND (   c.CurrencyID = p_CurrencyTo
                          OR c.CurrencyID = 13)
                  AND c.IsBank = 0;
        END IF;

      IF v_IsDefault = 0
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND c.CurrencyID = p_CurrencyTo;
        END IF;

      IF v_IsDefault = 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND (   a.CurrencyID = p_CurrencyTo
                          OR a.CurrencyID = 13)
                  AND a.IsBank = 0;
        END IF;


      IF v_IsDefault = 0
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.CurrencyID = p_CurrencyTo;
        END IF;

    END IF;


  IF p_Type = 2
     THEN
      IF v_IsDefault = 1
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccounts_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND (   c.CurrencyID = p_CurrencyTo
                          OR c.CurrencyID = 13)
                  AND c.IsBank = 1;
        END IF;

      IF v_IsDefault = 0
         THEN
          SELECT IFNULL(SUM(c.Credit) - SUM(c.Debit), 0.000) INTO v_PrievewBalance FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS c
          WHERE
                  c.AccIDFrom = p_AccID
                  AND c.IsActive = 1
                  AND c.InsertDate < p_D1
                  AND c.CurrencyID = p_CurrencyTo;
        END IF;

      IF v_IsDefault = 1
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND (   a.CurrencyID = p_CurrencyTo
                          OR a.CurrencyID = 13)
                  AND a.IsBank = 1;
        END IF;


      IF v_IsDefault = 0
         THEN
          SELECT
                  ROW_NUMBER() OVER (
                  ORDER BY a.ID ASC)                                                                                      AS '#',
                  a.ISID                                                                                                  AS 'الرمز',
                  DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                      AS 'التاريخ',
                  b.CurrencyName                                                                                          AS 'العملة',
                  FORMAT(a.Debit, 3)                                                                          AS 'مدين',
                  FORMAT(a.Credit, 3)                                                                         AS 'دائن',
                  FORMAT(`EMPMOVEMENT_GetNetTotal`(p_AccID, a.AccBranchID, a.ID, p_CurrencyTo, p_Type), 3) AS 'الرصيد',
                  a.MovementType                                                                                          AS 'طبيعة الحركة',
                  a.Note                                                                                                  AS 'ملاحظات',
                  v_PrievewBalance                                                                                         AS 'الرصيد السابق'
          FROM
                  ExSyAccountsCurrency_AccSafeActivityTb AS a
              LEFT OUTER JOIN
                CurrencyTb AS b
                  ON a.CurrencyID = b.ID
          WHERE
                  a.AccIDFrom = p_AccID
                  AND a.IsActive = 1
                  AND a.InsertDate >= p_D1
                  AND a.InsertDate <= p_D2
                  AND a.CurrencyID = p_CurrencyTo;
        END IF;

    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_GETPCEMPID`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_GETPCEMPID`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_IsSettlement` INT)
BEGIN
START TRANSACTION;
  IF p_IsSettlement = 1
     THEN
      SELECT
              a.ISID                             AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') 'التاريخ',
              D.AccName                          AS AccName,
              a.Debit                            AS 'مدين',
              a.Credit                           AS 'دائن',
              A.MovementType                     AS 'طبيعة الحركة',
              CASE                       WHEN A.Note = ''                         THEN                         'لا يوجد'                       ELSE                       A.Note               END                                AS 'ملاحظات'

      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN
            CurrencyTb AS b
              ON a.CurrencyID = b.ID
          LEFT JOIN
            PCSettlementTB AS C
              ON A.AccIDFrom = C.AccIDPC
          LEFT JOIN
            AccountsTb AS D
              ON C.AccIDPC = D.AccID
          LEFT JOIN
            PettyCashTb AS E
              ON a.AccIDFrom = e.AccIDPetty
      WHERE
              C.BranchID = p_BranchID
              AND a.IsActive = 1
              AND A.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
              AND A.TypeID = 14
              AND e.IsSettlement = 1
      GROUP BY
              a.ISID,
              a.InsertDate,
              D.AccName,
              a.Debit,
              a.Credit,
              a.Note,
              a.MovementType;
    END IF;
  IF p_IsSettlement = 0
     THEN
      SELECT
              a.Code                             AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
              f.EMPNAME                          AS AccName,
              a.PettyCashVal                     AS 'مدين',
              0.000                              AS 'دائن',
              B.MovementType                     AS 'طبيعة الحركة',
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END                                AS 'ملاحظات'
      FROM
              PettyCashTb AS a
          INNER JOIN
            ExSyAccounts_AccSafeActivityTb AS b
              ON a.Code = B.ISID
          INNER JOIN
            `EmployeeTb` AS f
              ON A.EMPID = f.ID
      WHERE
              A.BranchID = p_BranchID
              AND a.IsActive = 1
              AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
              AND A.IsSettlement = 0
      GROUP BY
              a.Code,
              a.InsertDate,
              f.EMPNAME,
              a.PettyCashVal,
              a.NoteS,
              B.MovementType
      ORDER BY
              a.InsertDate ASC;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectAccountsBetweenBranches`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectAccountsBetweenBranches`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_CurrentAccID BIGINT;


	START TRANSACTION;
	SELECT at.AccID INTO v_CurrentAccID FROM
			AccountsTb at
	WHERE
			at.BranchID = p_BranchID
			AND at.AccParent = 2010201;

	SELECT
			d.ID,
			ROW_NUMBER() OVER (ORDER BY b.AccName ASC) AS '#',
			b.AccName								   AS 'اسم الحساب',
			CASE 					WHEN SUM(a.Debit) > SUM(a.Credit) 						THEN 						FORMAT(SUM(a.Credit) - SUM(a.Debit), 3) 					ELSE 					FORMAT((0.000), 3) 			END										   AS 'مدين (له)',
			CASE 					WHEN SUM(a.Credit) > SUM(a.Debit) 						THEN 						FORMAT(SUM(a.Credit) - SUM(a.Debit), 3) 					ELSE 					FORMAT((0.000), 3) 			END										   AS 'دائن (عليه)'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		INNER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
		INNER JOIN
			CoBranch AS d
				ON b.BranchID = d.ID
	WHERE
			a.IsActive = 1
			AND b.AccActive = 1
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND a.AccBranchID = p_BranchID
			AND b.AccParent = 2010201
	GROUP BY
			b.AccName,
			d.ID
	ORDER BY
			b.AccName ASC;
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectBankServices`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectBankServices`(IN `p_BranchID` INT, IN `p_BBranchID` INT, IN `p_ServiceID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY c.ID ASC)     AS '#',
          c.ISID                                    AS 'الرمز',
          DATE_FORMAT(c.InsertDate, '%Y/%m/%d')        AS 'التاريخ',
          FORMAT(c.Debit, 4)            AS 'مدين',
          FORMAT(d.Credit, 4)           AS 'دائن',
          FORMAT(c.Debit - d.Credit, 3) AS 'الإجمالي'
  FROM
          BBranchTb AS a
      INNER JOIN
        BankServicesTb AS b
          ON a.ID = b.BBranchID
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb AS c
          ON a.AccID = c.AccIDFrom
      INNER JOIN
        ExSyAccounts_AccSafeActivityTb AS d
          ON a.AccIDBBranchAllowance = d.AccIDFrom
  WHERE
          a.AccountType = 1
          AND c.AccBranchID = p_BranchID
          AND a.ID = p_BBranchID
          AND b.ID = p_ServiceID
          AND c.InsertDate >= p_D1
          AND c.InsertDate <= p_D2
          AND c.ISID = d.ISID
  GROUP BY
          a.BranchName,
          c.ISID,
          c.InsertDate,
          c.Debit,
          d.Credit,
          c.ID
  ORDER BY
          c.ID;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectByAgent`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectByAgent`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(18,3), INOUT `p_SumCreditFinal` DECIMAL(18,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(18,3), INOUT `p_OverAllNetTotalFinal_total` LONGTEXT, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_BranchType INT;
DECLARE v_SumDebit               DECIMAL(18, 3);
DECLARE v_SumCredit              DECIMAL(18, 3);
DECLARE v_OverAllNetTotal        DECIMAL(18, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(18, 3);
DECLARE v_AccID BIGINT;
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE v_isDeffCurr BIT;


  START TRANSACTION;

  SELECT cmt.IsDefault INTO v_isDeffCurr FROM
          CurrencyMainTb cmt
  WHERE
          cmt.id = p_CurrencyID
 ORDER BY cmt.ID DESC LIMIT 1;

  SELECT a.AccID INTO v_AccID FROM
          AccountsTb AS a
  WHERE
          a.AccParent = 2010201
          AND a.BranchID = p_BranchID;

  IF v_isDeffCurr = 1
     THEN
      SELECT IFNULL(SUM(x.Credit) - SUM(x.Debit), 0.000) INTO v_PrievewBalance FROM
              ExSyAccounts_AccSafeActivityTb AS x
      WHERE
              x.AccIDFrom = v_AccID
              AND x.IsActive = 1
              AND x.InsertDate < p_D1;
      SELECT
              ROW_NUMBER() OVER (ORDER BY a.ID ASC)                                                                                     AS '#',
              a.ISID                                                                                                                    AS 'رمز الحوالة',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                                        AS 'التاريخ',
              FORMAT(a.Debit, 3)                                                                                            AS 'مدين',
              FORMAT(a.Credit, 3)                                                                                           AS 'دائن',
              FORMAT(v_PrievewBalance, 0)                                                                                    AS 'الرصيد السابق',
              c.CurrencyName                                                                                                            AS 'العملة',
              FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyID, 0), 3) AS 'الصافي',
              CASE                       WHEN a.MovementType = ''                         THEN                         a.SafeIDMovement                       ELSE                       a.MovementType               END                                                                                                                       AS 'طبيعة الحركة',
              CASE                       WHEN a.Description <> ''                         THEN                         a.Description                       WHEN a.Description = ''                         AND a.Note <> ''                         THEN                         a.Note                       ELSE                       'لايوجد'               END                                                                                                                       AS 'ملاحظات',
              b.AccName
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS B
              ON a.AccIDFrom = B.AccID
          LEFT JOIN
            CurrencyTb AS c
              ON a.CurrencyID = c.ID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND a.AccIDFrom = v_AccID
      ORDER BY
              a.ID ASC;
      SELECT SUM(a.Debit) INTO v_SumDebit FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID;
      SELECT SUM(a.Credit) INTO v_SumCredit FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID;

      SET p_SumDebitFinal = v_SumDebit;
      SET p_SumCreditFinal = v_SumCredit;
      IF p_SumDebitFinal > p_SumCreditFinal
         THEN
          SET p_OverAllNetTotalFinal = p_SumDebitFinal - p_SumCreditFinal;
        END IF;
      IF p_SumCreditFinal > p_SumDebitFinal
         THEN
          SET p_OverAllNetTotalFinal = p_SumCreditFinal - p_SumDebitFinal;
        END IF;
      SELECT
              p_SumDebitFinal,
              p_SumCreditFinal,
              p_OverAllNetTotalFinal;


      SELECT FORMAT(IFNULL(SUM(Credit), 0) - IFNULL(SUM(Debit), 0), 3) INTO p_OverAllNetTotalFinal_total FROM
              ExSyAccounts_AccSafeActivityTb
      WHERE
              AccIDFrom = v_AccID
              AND IsActive = 1;

    END IF;

  IF v_isDeffCurr <> 1
     THEN
      SELECT IFNULL(SUM(x.Debit) - SUM(x.Credit), 0.000) INTO v_PrievewBalance FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS x
      WHERE
              x.AccIDFrom = v_AccID
              AND x.IsActive = 1
              AND x.InsertDate < p_D1
              AND x.CurrencyID = p_CurrencyID;
      SELECT
              ROW_NUMBER() OVER (ORDER BY a.ISID ASC)                                                                                   AS '#',
              a.ISID                                                                                                                    AS 'رمز الحوالة',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                                        AS 'التاريخ',
              FORMAT(a.Credit, 3)                                                                                           AS 'مدين',
              FORMAT(a.Debit, 3)                                                                                            AS 'دائن',
              FORMAT(`CUSTMOVEMENT_GetNetTotalBasidONBankORNot`(a.AccIDFrom, a.AccBranchID, a.ID, p_CurrencyID, 0), 3) AS 'الصافي',
              a.MovementType                                                                                                            AS 'طبيعة الحركة',
              a.Note                                                                                                                    AS 'ملاحظات',
              v_PrievewBalance                                                                                                           AS 'الرصيد السابق',
              b.CurrencyName                                                                                                            AS 'العملة',
              c.AccName
      FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN
            CurrencyTb AS b
              ON a.CurrencyID = b.ID
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND a.AccIDFrom = v_AccID
              AND a.CurrencyID = p_CurrencyID
      ORDER BY
              a.ID ASC;
      SELECT SUM(a.Credit) INTO v_SumDebit FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID;
      SELECT SUM(a.Debit) INTO v_SumCredit FROM
              ExSyAccountsCurrency_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID;

      SET p_SumDebitFinal = v_SumDebit;
      SET p_SumCreditFinal = v_SumCredit;
      IF p_SumDebitFinal > p_SumCreditFinal
         THEN
          SET p_OverAllNetTotalFinal = p_SumDebitFinal - p_SumCreditFinal;
        END IF;
      IF p_SumCreditFinal > p_SumDebitFinal
         THEN
          SET p_OverAllNetTotalFinal = p_SumCreditFinal - p_SumDebitFinal;
        END IF;
      SELECT
              p_SumDebitFinal,
              p_SumCreditFinal,
              p_OverAllNetTotalFinal;


      SELECT FORMAT(IFNULL(SUM(Debit), 0) - IFNULL(SUM(Credit), 0), 3) INTO p_OverAllNetTotalFinal_total FROM
              ExSyAccountsCurrency_AccSafeActivityTb
      WHERE
              AccIDFrom = v_AccID
              AND IsActive = 1
              AND CurrencyID = p_CurrencyID;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectByAgent_ALL`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectByAgent_ALL`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(18,3), INOUT `p_SumCreditFinal` DECIMAL(18,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(18,3), INOUT `p_NET_FORTotalFinal` DECIMAL(18,3))
BEGIN
DECLARE v_BranchType INT;
DECLARE v_SumDebit               DECIMAL(18, 3);
DECLARE v_SumCredit              DECIMAL(18, 3);
DECLARE v_OverAllNetTotal        DECIMAL(18, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(18, 3);
DECLARE v_AccID BIGINT;
DECLARE v_PrievewBalance DECIMAL(15, 3);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; CALL ERROR_PROC(); END;

      START TRANSACTION;

      SELECT a.AccID INTO v_AccID FROM
              AccountsTb AS a
      WHERE
              a.AccParent = 2010201
              AND a.BranchID = p_BranchID;
      SELECT IFNULL(SUM(x.Credit) - SUM(x.Debit), 0.000) INTO v_PrievewBalance FROM
              ExSyAccounts_AccSafeActivityTb AS x
      WHERE
              x.AccIDFrom = v_AccID
              AND x.IsActive = 1
              AND x.InsertDate < p_D1;
      SELECT
              ROW_NUMBER() OVER (ORDER BY a.ISID ASC)                                               AS '#',
              a.ISID                                                                                AS 'رمز الحوالة',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                    AS 'التاريخ',
              FORMAT(a.Debit, 3)                                                        AS 'مدين',
              FORMAT(a.Credit, 3)                                                       AS 'دائن',
              FORMAT(`AgentView_GetNetTotal`(a.AccIDFrom, a.CurrencyID, a.ID), 3) AS 'الصافي',
              a.MovementType                                                                        AS 'طبيعة الحركة',
              a.Note                                                                                AS 'ملاحظات',
              v_PrievewBalance                                                                       AS 'الرصيد السابق',
              b.CurrencyName                                                                        AS 'العملة',
              c.AccName
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN
            CurrencyTb AS b
              ON a.CurrencyID = b.ID
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND a.AccIDFrom = v_AccID
      ORDER BY
              a.ID ASC;
      SELECT SUM(a.Debit) INTO v_SumDebit FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID;
      SELECT SUM(a.Credit) INTO v_SumCredit FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            AccountsTb AS c
              ON a.AccIDFrom = c.AccID
      WHERE
              a.IsActive = 1
              AND a.InsertDate >= p_D1
              AND a.InsertDate <= p_D2
              AND c.BranchID = p_BranchID;

      SET p_SumDebitFinal = v_SumDebit;
      SET p_SumCreditFinal = v_SumCredit;
      SET p_OverAllNetTotalFinal = p_SumCreditFinal - p_SumDebitFinal;
      SELECT IFNULL(SUM(x.Credit) - SUM(x.Debit), 0.000) INTO p_NET_FORTotalFinal FROM
              ExSyAccounts_AccSafeActivityTb AS x
      WHERE
              x.AccIDFrom = v_AccID
              AND x.IsActive = 1;
      COMMIT;


  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectByBankSerivecsEmSafe`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectByBankSerivecsEmSafe`(IN `p_BankService` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault BIT;


    START TRANSACTION;
    SELECT CMT.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS CMT
    WHERE
            CMT.ID = p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;

    SELECT USID INTO v_AccFrom FROM
            TB_Users
    WHERE
            accid = p_SafeID
 ORDER BY TB_Users.USID DESC LIMIT 1;

    IF v_IsDefault = 1
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.id ASC)                                                                                            AS '#',
                a.ISID                                                                                                        AS 'الكود',
                DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                            AS 'التاريخ',
                b.BranchName                                                                                                  AS 'اسم الحساب',
                FORMAT(a.Debit, 3)                                                                                AS 'مدين',
                FORMAT(a.Credit, 3)                                                                               AS 'دائن',
                FORMAT(`SafeIDBankServices_GetNetTotal`(v_AccFrom, p_BankService, p_CurrencyID, a.ID) * -1, 3) AS 'الصافي',
                a.SafeIDMovement                                                                                              AS 'طبيعة الحركة'
        FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND c.ID = p_BankService
        ORDER BY
                a.ID ASC;
      END IF;
    IF v_IsDefault = 0
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.id ASC)                                                                                            AS '#',
                a.ISID                                                                                                        AS 'الكود',
                DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                             AS 'التاريخ',
                FORMAT(a.Debit, 3)                                                                                AS 'مدين',
                FORMAT(a.Credit, 3)                                                                               AS 'دائن',
                FORMAT(`SafeIDBankServices_GetNetTotal`(v_AccFrom, p_BankService, p_CurrencyID, a.ID) * -1, 3) AS 'الصافي',
                a.SafeIDMovement                                                                                              AS 'طبيعة الحركة'
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.accIDfrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = v_AccFrom
                AND c.ID = p_BankService
        ORDER BY
                a.InsertDate ASC;
      END IF;
  END;

COMMIT //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AccSafeActivityTb_SelectByEmSafe`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AccSafeActivityTb_SelectByEmSafe`(IN `p_BranchID` INT, IN `p_CurrencyID` INT, IN `p_SafeID` BIGINT, IN `p_D1` DATE, IN `p_D2` DATE, INOUT `p_SumDebitFinal` DECIMAL(15,3), INOUT `p_SumCreditFinal` DECIMAL(15,3), INOUT `p_OverAllNetTotalFinal` DECIMAL(15,3), INOUT `p_OverAllPeroidTotal` DECIMAL(15,3), INOUT `p_PreviewBalanceTotal` DECIMAL(15,3))
BEGIN
DECLARE v_MainBr INT;
DECLARE v_SumDebit               DECIMAL(12, 3);
DECLARE v_SumCredit              DECIMAL(12, 3);
DECLARE v_OverAllPeroid          DECIMAL(15, 3);
DECLARE v_PreviewBalance         DECIMAL(15, 3);
DECLARE v_OverAllNetTotal        DECIMAL(12, 3);
DECLARE v_SumDeliveredCurrentAcc DECIMAL(12, 3);
DECLARE v_AccFrom BIGINT;
DECLARE v_IsDefault BIT;


    START TRANSACTION;
    SELECT CMT.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS CMT
    WHERE
            cmt.ID = p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;
    IF v_IsDefault = 1
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.InsertDate ASC)                                                                          AS 'SN',
                a.ISID                                                                                              AS 'RPTCode',
                DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                  AS 'RPTDate',
                FORMAT(a.Debit, 3)                                                                      AS 'مدين',
                FORMAT(a.Credit, 3)                                                                     AS 'دائن',
                FORMAT(`SafeIDEMP_GetNetTotal`(a.AccIDFrom, a.AccBranchID, p_CurrencyID, a.ID), 3) AS 'الصافي',
                a.SafeIDMovement                                                                                    AS 'طبيعة الحركة'
        FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID
        ORDER BY
                a.InsertDate ASC;
        SELECT SUM(a.Debit) INTO v_SumDebit FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SELECT SUM(a.Credit) INTO v_SumCredit FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SET p_SumDebitFinal = v_SumDebit;
        SET p_SumCreditFinal = v_SumCredit;
        SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllNetTotalFinal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.AccBranchID = p_BranchID;
        SELECT SUM(a.Debit) - SUM(a.Credit) INTO p_OverAllPeroidTotal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SELECT IFNULL(SUM(a.Debit) - SUM(a.Credit), 0.000) INTO p_PreviewBalanceTotal FROM
                ExSyAccounts_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate < p_D1
                AND a.AccBranchID = p_BranchID;
        SELECT
                p_SumDebitFinal,
                p_SumCreditFinal,
                p_OverAllPeroidTotal,
                p_OverAllNetTotalFinal,
                p_PreviewBalanceTotal AS PrievewBalance;
      END IF;
    IF v_IsDefault = 0
       THEN
        SELECT
                ROW_NUMBER() OVER (
                ORDER BY a.InsertDate ASC)                                                                          AS 'SN',
                a.ISID                                                                                              AS 'RPTCode',
                DATE_FORMAT(a.InsertDate, '%Y/%m/%d')                                                                  AS 'RPTDate',
                FORMAT(a.Debit, 3)                                                                      AS 'دائن',
                FORMAT(a.Credit, 3)                                                                     AS 'مدين',
                FORMAT(`SafeIDEMP_GetNetTotal`(a.AccIDFrom, a.AccBranchID, p_CurrencyID, a.ID), 3) AS 'الصافي',
                a.SafeIDMovement                                                                                    AS 'طبيعة الحركة'
        FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID
        ORDER BY
                a.InsertDate ASC;
        SELECT SUM(a.Credit) INTO v_SumDebit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SELECT SUM(a.Debit) INTO v_SumCredit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SET p_SumDebitFinal = v_SumDebit;
        SET p_SumCreditFinal = v_SumCredit;
        SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllNetTotalFinal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.AccBranchID = p_BranchID;
        SELECT SUM(a.Credit) - SUM(a.Debit) INTO p_OverAllPeroidTotal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate >= p_D1
                AND a.InsertDate <= p_D2
                AND a.AccBranchID = p_BranchID;
        SELECT IFNULL(SUM(a.Credit) - SUM(a.Debit), 0.000) INTO p_PreviewBalanceTotal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.AccIDFrom = p_SafeID
                AND a.InsertDate < p_D1
                AND a.AccBranchID = p_BranchID;
        SELECT
                p_SumDebitFinal,
                p_SumCreditFinal,
                p_OverAllPeroidTotal,
                p_OverAllNetTotalFinal,
                p_PreviewBalanceTotal AS PrievewBalance;
      END IF;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AdvancePaymentTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AdvancePaymentTb_LoadAllData`(IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
  SELECT
          ROW_NUMBER() OVER (
          ORDER BY a.Code ASC)               AS '#',
          a.Code                             AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
          c.EMPNAME                          AS 'اسم الموظف',
          d.BName                            AS 'الفرع',
          b.CurrencyName                     AS 'نوع العملة',
          a.OverAllVal                       AS 'إجمالي السلفة',
          a.RepaymentPeroid                  AS 'عدد الدفعات',
          a.ValPerMonth                      AS 'قيمة الدفع الشهري',
          a.ValPerMonth * a.PaymentTimes     AS 'المدفوع منها',
          a.RepaymentPeroid - a.PaymentTimes AS 'الدفعات المتبقية',
          a.OverAllVal - a.PaidVal           AS 'القيمة المتبقية',
          CASE                   WHEN a.IsOpened = 1                     THEN                     'مستمرة'                   ELSE                   'منتهية'           END                                AS 'الحالة'
  FROM
          AdvancePaymentTb AS a
      LEFT JOIN
        CurrencyTb AS b
          ON a.CurrencyID = b.ID
      LEFT JOIN
        EmployeeTb AS c
          ON a.EMPID = c.ID
      LEFT JOIN
        CoBranch AS d
          ON a.BranchID = d.ID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1
          AND a.InsertDate >= p_D1
          AND a.insertdate <= p_D2;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AdvancePaymentTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AdvancePaymentTb_SelectByCode`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

  SELECT
          A.ID,
          A.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          A.EMPID,
          A.BranchID,
          B.CurrencyName,
          C.BName,
          D.EMPNAME,
          E.AccName,
          A.OverAllVal,
          A.RepaymentPeroid,
          A.ValPerMonth,
          A.IsOpened,
          A.PaymentTimes,
          A.PaidVal,
          A.IsActive,
          A.SafeID,
          A.CurrencyID,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END AS Phone,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END AS Notes
  FROM
          AdvancePaymentTb AS A
      LEFT JOIN
        CurrencyTb AS B
          ON A.CurrencyID = B.ID
      LEFT JOIN
        CoBranch AS C
          ON A.BranchID = C.ID
      LEFT JOIN
        EmployeeTb AS D
          ON A.EMPID = D.ID
      LEFT JOIN
        AccountsTb AS E
          ON A.SafeID = E.AccID
  WHERE
          A.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AssActivityTb_GETASSO`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AssActivityTb_GETASSO`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')    AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',
          CASE                   WHEN a.Note = ''                     OR a.Note IS NULL                     THEN                     a.MovementType                   ELSE                   a.Note           END                                   AS 'ملاحظات'

  FROM
          ExSyAccounts_AccSafeActivityTb AS a

  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE);
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_AssActivityTb_GETMEMBER`;
DELIMITER //
CREATE PROCEDURE `ZRPT_AssActivityTb_GETMEMBER`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT, IN `p_AssID` INT, IN `p_LOADTYPE` INT)
BEGIN
START TRANSACTION;
  IF p_LOADTYPE = 2
     THEN

      SELECT
              ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
              a.ISID                                AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d')    AS 'التاريخ',
              b.MEMBERNAME                          AS 'الاسم',
              a.Debit                               AS 'مدين',
              a.Credit                              AS 'دائن',
              a.SafeIDMovement                      AS 'طبيعة الحركة',
              a.MovementType                        AS 'ملاحظات'

      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            ASSOCIATIONTB AS b
              ON a.AccIDFrom = b.AccID

      WHERE
              a.AccIDFrom = p_AccID
              AND a.IsActive = 1
              AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)

ORDER BY a.ID;
    END IF;
  IF p_LOADTYPE = 1
     THEN

      SELECT
              ROW_NUMBER() OVER (ORDER BY b.ID ASC) AS '#',
              b.MEMBERNAME                          AS 'الاسم',
              FORMAT(SUM(a.Debit), 3)   AS 'مدين',
              FORMAT(SUM(a.Credit), 3)  AS 'دائن',
              b.AccID,
              a.MovementType                        AS 'ملاحظات'
      FROM
              ExSyAccounts_AccSafeActivityTb AS a
          INNER JOIN
            ASSOCIATIONTB AS b
              ON a.AccIDFrom = b.AccID

      WHERE
              b.ASSOCIATIONID = p_AssID
              AND a.IsActive = 1
              AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
      GROUP BY
              b.MEMBERNAME,
              b.ID,
              b.AccID,
              a.MovementType,
              a.ID
              ORDER BY a.ID;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_BankDipWdTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_BankDipWdTb_SelectByCode`(IN `p_Code` LONGTEXT, IN `p_TypeID` INT)
BEGIN
START TRANSACTION;

  IF p_TypeID <> 47
     THEN
      SELECT
              A.Code,
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
              A.BranchID,
              B.BName,
              A.SafeAccID,
              C.AccName AS SafeName,
              A.AccFrom,
              D.AccName AS FromName,
              A.AccTo,
              E.AccName AS ToName,
              A.CurrencyID,
              F.CurrencyName,
              A.BillVal,
              A.IsDiscount,
              A.DiscountFrom,
              A.DiscountType,
              A.OverAllTotal,
              A.DiscountVal,
              A.BillNo,
              g.ExName,
              a.OwnAccountName,
              a.OwnAccountPhone,
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END       AS Notes,
              A.IsActive,
              CASE                       WHEN B.Mobile1 = ''                         AND B.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN B.Mobile1 = ''                         THEN                         B.Mobile2                       WHEN B.Mobile2 = ''                         THEN                         B.Mobile1                       ELSE                       CONCAT(B.Mobile1, '-', B.Mobile2)               END       AS Phone,
              CASE                       WHEN A.IsDiscount = 0                         THEN                         'نعم'                       ELSE                       'لا'               END       AS IsDiscount1,
              CASE                       WHEN A.DiscountFrom = 0                         THEN                         'العميل'                       WHEN A.DiscountFrom = 1                         THEN                         'الشركة'                       ELSE                       'لا يوجد'               END       AS DiscountFrom1,
              CASE                       WHEN A.DiscountType = 0                         THEN                         'نقدي'                       WHEN A.DiscountType = 1                         THEN                         'من الحساب'                       ELSE                       'لا يوجد'               END       AS DiscountType1
      FROM
              BankDipWdTb AS A
          LEFT JOIN
            CoBranch AS B
              ON A.BranchID = B.ID
          LEFT JOIN
            AccountsTb AS C
              ON A.SafeAccID = C.AccID
          LEFT JOIN
            AccountsTb AS D
              ON A.AccFrom = D.AccID
          LEFT JOIN
            AccountsTb AS E
              ON A.AccTo = E.AccID
          LEFT JOIN
            CurrencyTb AS F
              ON A.CurrencyID = F.ID
          LEFT JOIN
            ContractDB.ExpensesTb AS g
              ON a.EXID = g.ID

      WHERE
              A.Code = p_Code
              AND A.TypeID = p_TypeID;
    END IF;

  IF p_TypeID = 47
     THEN
      SELECT
              A.Code,
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
              B.BName,
              D.AccName  AS FromName,
              E.AccName  AS ToName,
              F.CurrencyName,
              A.BillVal,
              A.BillNo,
              a.OwnAccountName,
              a.OwnAccountPhone,
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END        AS Notes,
              CASE                       WHEN B.Mobile1 = ''                         AND B.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN B.Mobile1 = ''                         THEN                         B.Mobile2                       WHEN B.Mobile2 = ''                         THEN                         B.Mobile1                       ELSE                       CONCAT(B.Mobile1, '-', B.Mobile2)               END        AS Phone,
              j.BankName AS BankFrom,
              i.BankName AS BankTo

      FROM
              BankDipWdTb AS A
          LEFT JOIN
            CoBranch AS B
              ON A.BranchID = B.ID
          LEFT JOIN
            AccountsTb AS D
              ON A.AccFrom = D.AccID
          LEFT JOIN
            AccountsTb AS E
              ON A.AccTo = E.AccID
          LEFT JOIN
            CurrencyTb AS F
              ON A.CurrencyID = F.ID
          LEFT JOIN
            BBranchTb AS bf
              ON A.AccFrom = bf.AccID
          LEFT JOIN
            BBranchTb AS bt
              ON A.AccTo = bt.AccID
          LEFT JOIN
            BanksTb AS j
              ON bf.BankID = j.ID
          LEFT JOIN
            BanksTb AS i
              ON bt.BankID = i.ID

      WHERE
              A.Code = p_Code
              AND A.TypeID = p_TypeID;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_BayAseetTB_Insert`;
DELIMITER //
CREATE PROCEDURE `ZRPT_BayAseetTB_Insert`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          A.Code         AS 'الرمز',
          c.BName        AS 'الفرع',
          E.CurrencyName AS 'العملة',
          D.UName        AS 'الخزنة',
          A.AssetVal     AS 'القيمة',
          F.AccName      AS 'اسم المصروف',
          G.UName        AS UserInsert,
          CASE                   WHEN c.Mobile1 = ''                     AND c.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN c.Mobile1 = ''                     THEN                     c.Mobile2                   WHEN c.Mobile2 = ''                     THEN                     c.Mobile1                   ELSE                   CONCAT(c.Mobile1, '-', c.Mobile2)           END            AS Phone,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END            AS 'ملاحظة'
  FROM
          ContractDB.BayAseetTB AS A
      LEFT JOIN
        `CoBranch` AS c
          ON A.BranchID = c.ID
      LEFT JOIN
        TB_Users AS D
          ON A.SafeID = D.USID
      LEFT JOIN
        CurrencyTb AS E
          ON A.CurrencyID = E.ID
      LEFT JOIN
        AccountsTb AS F
          ON A.AccID = F.AccID
      LEFT JOIN
        TB_Users AS G
          ON A.SafeID = G.USID
  WHERE
          A.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_Branch_GetInteralBenefits`;
DELIMITER //
CREATE PROCEDURE `ZRPT_Branch_GetInteralBenefits`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_CurrencyID` INT)
BEGIN
DECLARE v_ACCPARENT BIGINT;
DECLARE v_ACCLOSINGPARENT BIGINT;
DECLARE v_BankBouns BIGINT;
DECLARE v_BankLosing BIGINT;


	START TRANSACTION;
	SELECT at.AccCode INTO v_ACCPARENT FROM
			AccountsTb at
	WHERE
			at.AccName = 'الإيرادات';
	SELECT at.AccCode INTO v_ACCLOSINGPARENT FROM
			AccountsTb at
	WHERE
			at.AccName = 'خسائر حوالات ملغاة';
	SELECT at.AccCode INTO v_BankBouns FROM
			AccountsTb at
	WHERE
			at.AccName = 'عمولات تحويلات مصرفية فرع البيضاء';
	SELECT at.AccID INTO v_BankLosing FROM
			AccountsTb at
	WHERE
			at.AccName = 'عمولة تحويل مصرفي فرع البيضاء';
	SELECT
			a.ISID	 AS 'الرمز',
			C.ExVal	 AS 'العمولة',
			a.Credit AS 'الحصة',
			CASE 					WHEN C.BranchRecievedID <> p_BranchID 						AND b.AccCode <> 401010901 						THEN 						CONCAT('حوالة واردة من', ' ', d.BName) 					WHEN C.BranchDeliveredID <> p_BranchID 						AND b.AccCode <> 401010901 						THEN 						CONCAT('حوالة صادرة إلى', ' ', f.BName) 					WHEN b.AccCode = 401010901 						THEN 						CONCAT('حوالة من', ' ', d.BName, ' ', 'إلى', ' ', f.BName) 			END		 AS 'وجهة الحوالة',
			CASE 					WHEN b.AccParent = 4010102 						THEN 						'إيراد حوالة داخلية صادرة' 					WHEN b.AccParent = 4010103 						THEN 						'إيرادات حوالات داخلية واردة' 					WHEN b.AccParent = 4010104 						THEN 						'حوالة داخلية صادرة ملغية' 					WHEN b.AccParent = 4010105 						THEN 						'حوالة داخلية واردة ملغية' 					WHEN b.AccCode = 401010901 						THEN 						'حصة الرئيسي من حوالة بين الفروع' 					WHEN b.AccCode = 4010101001 						THEN 						'عمولة حوالة داخلية ملغية بين الفروع' 					WHEN b.AccParent = 3010209 						THEN 						'خسائر حوالة داخلية صادرة ملغاة' 					WHEN b.AccParent = 3010206 						THEN 						'خسائر حوالة داخلية واردة ملغاة' 					WHEN b.AccCode = 301020701 						THEN 						'حصة الرئيسي من حوالة بين الفروع' 					WHEN b.AccCode = v_BankBouns 						THEN 						'عمولة تحويل مصرفي' 					WHEN b.AccCode = v_BankLosing 						THEN 						'عمولة حويل من حساب مصرفي' 			END		 AS 'بيان الإيراد'
	FROM
			ExSyAccounts_AccSafeActivityTb AS a
		LEFT OUTER JOIN
			AccountsTb AS b
				ON a.AccIDFrom = b.AccID
		LEFT OUTER JOIN
			InternalEx AS C
				ON a.ISID = C.Code
		LEFT OUTER JOIN
			CoBranch AS d
				ON C.BranchRecievedID = d.ID
		LEFT OUTER JOIN
			CoBranch AS f
				ON C.BranchDeliveredID = f.ID
		LEFT OUTER JOIN
			BankDipWdTb G
				ON b.AccID = G.AccFrom
	WHERE
			b.BranchID = p_BranchID
			AND a.InsertDate >= p_D1
			AND a.InsertDate <= p_D2
			AND (   a.CurrencyID = p_CurrencyID
					OR a.CurrencyID = 13)
			AND (   SUBSTRING(CAST(b.AccParent AS CHAR), 1, 1) = v_ACCPARENT
					OR SUBSTRING(CAST(b.AccParent AS CHAR), 1, 2) = v_ACCLOSINGPARENT);
	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CashMonment_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CashMonment_LOADTODVG`(IN `p_BranchID` INT, IN `p_accTIPE` INT, IN `p_CurrencyID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;

  IF p_accTIPE = 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY A.Code ASC)        AS '#',
              A.Code                      AS 'الرمز',
             DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
              A.WDVAL                     'القيمة',
              CONCAT('لحساب/', ' ', c.AccName) AS 'لحساب',
              B.UName                     'المستخدم',
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END                         AS 'الملاحظات'
      FROM
              EMPORCUSTWITHDRAWALTB AS A
          INNER JOIN
            TB_Users AS B
              ON A.SafeID = B.AccID
          INNER JOIN
            AccountsTb  AS c
              ON A.EMPID = c.AccID
      WHERE
              A.BranchID = p_BranchID
              AND A.CurrencyFrom = p_CurrencyID
              AND (A.TypeID = 5)
              AND A.IsActive = 1
              AND (A.InsertDate BETWEEN p_D1 AND p_D2)

      ORDER BY
              'التاريخ';
    END IF;
  IF p_accTIPE = 1
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY A.Code ASC)        AS '#',
              A.Code                      AS 'الرمز',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
              A.WDVAL                     'القيمة',
              CONCAT('لحساب/', ' ', c.AccName) AS 'لحساب',
              B.UName                     'المستخدم',
              CASE                       WHEN A.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       A.Notes               END                         AS 'الملاحظات'
      FROM
              EMPORCUSTWITHDRAWALTB AS A
          INNER JOIN
            TB_Users AS B
              ON A.SafeID = B.AccID
          INNER JOIN
            AccountsTb  AS c
              ON A.EMPID = c.AccID
      WHERE
              A.BranchID = p_BranchID
              AND A.CurrencyFrom = p_CurrencyID
              AND (A.TypeID = 7)
              AND A.IsActive = 1
              AND (A.InsertDate BETWEEN p_D1 AND p_D2)

      ORDER BY
              'التاريخ';
    END IF;
  IF p_accTIPE = 2
     THEN
      SELECT
              a.Code                             AS 'الرمز',
              ROW_NUMBER() OVER (
              ORDER BY a.Code ASC)               AS '#',
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
              a.ExpensVal                        AS 'القيمة',
              B.UName                            AS 'المستخدم',
              d.ExName                           AS 'لحساب',
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END                                AS 'الملاحظات'
      FROM
              ANOTHEREXPENSTB AS a
          INNER JOIN
            TB_Users AS B
              ON a.AccSafeID = B.AccID
          LEFT JOIN
            ExpensesTb AS d
              ON a.AccIDPC = d.AccID
      WHERE
              a.BranchID = p_BranchID
              AND a.CurrencyID = p_CurrencyID
              AND (a.InsertDate BETWEEN p_D1 AND p_D2)
              AND a.IsActive = 1
      ORDER BY
              a.InsertDate;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CurrenciesBuyandsellTB_loadtoFrm`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CurrenciesBuyandsellTB_loadtoFrm`(IN `p_ID` LONGTEXT)
BEGIN
DECLARE v_IsDefalut BIT;
  SELECT CMT.IsDefault INTO v_IsDefalut FROM
          CurrencyMainTb AS CMT;

  SELECT
          a.Code,
          DATE_FORMAT(InsertDate, '%Y/%m/%d'),
          b.BName,
          IsCachorBank,
          CusName,
          CustIDNo,
          Phone,
          BankID,
          AccAcountBank,
          CheckType,
          AccAcountBank,
          CASE                   WHEN a.thepurpose = 0                     THEN                     'سياحة'                   WHEN a.thepurpose = 1                     THEN                     'علاج'                   WHEN a.thepurpose = 2                     THEN                     'دراسة'           END                                                    AS purpose,
          Typeoftransaction,
          Transactionnumber,
          SafeTypefrom,
          d.CuName                                               AS CuNameFrom,
          c.AccName                                              AS AccNamefrom,
          e.AccName                                              AS AccNameTo,
          BPrice1,
          thepurpose,
          SafeTypeTo,
          AccSafeTo,
          f.CuName                                               AS CuNameTo,
          CurrencyTo,
          Purchasingprice,
          `EMPORCUST_GetAccVal`(SaFACCount, v_IsDefalut)      AS ACCVALFORM,
          `EMPORCUST_GetAccVal_SAfs`(SaFACCount, v_IsDefalut) AS ACCValTo,
          CASE                   WHEN B.Mobile1 = ''                     THEN                     B.Mobile2                   WHEN B.Mobile2 = ''                     THEN                     B.Mobile1                   ELSE                   CONCAT(B.Mobile1, '-', B.Mobile2)           END                                                    AS Phone1,
          BPrice2,
          CASE                   WHEN a.Notes = ''                     THEN                     'لايوجد'                   ELSE                   a.Notes           END                                                    AS notes
  FROM
          CurrenciesBuyandsellTB AS a
      LEFT JOIN
        CoBranch AS b
          ON a.BranchID = b.ID
      LEFT JOIN
        AccountsTb AS c
          ON a.SaFACCount = c.AccID
      LEFT JOIN
        CurrencyMainTb AS d
          ON a.FirstCurrency = d.ID
      LEFT JOIN
        AccountsTb AS e
          ON a.AccSafeTo = e.AccID
      LEFT JOIN
        CurrencyMainTb AS f
          ON a.CurrencyTo = f.ID
  WHERE
          a.Code = p_ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CurrencymovementPruse_FILLGRid`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CurrencymovementPruse_FILLGRid`(IN `p_Bid` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT)
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_TotalProfit DECIMAL(15, 3);
DECLARE v_Totallosses DECIMAL(15, 3);
DECLARE v_c1 DECIMAL(15, 7);
DECLARE v_c2 DECIMAL(15, 7);
DECLARE v_ctotal DECIMAL(15, 3);
DECLARE v_TotalProfit2 DECIMAL(15, 3);
DECLARE v_Totallosses2 DECIMAL(15, 3);
DECLARE v_AccCreditVal2 DECIMAL(15, 3);
DECLARE v_AccdebitVal2 DECIMAL(15, 3);
DECLARE v_AccVal2 DECIMAL(15, 3);
DECLARE v_Costof DECIMAL(15, 3);



  SELECT a.Costof INTO v_Costof FROM
          (SELECT
					b.CuName,
					CASE 							WHEN c.CurrencyPower = 0 								THEN 								CASE 										WHEN (IFNULL(SUM(CRedetDL),0.000) - IFNULL(SUM(ACC_DEPET_DL),0.000)) = 0  											THEN 											0.00 										ELSE 										(IFNULL(SUM(a.CRedetTO),0.000) - IFNULL(SUM(a.ACC_DEPET_TO),0.000)) / (IFNULL(SUM(CRedetDL),0.000) - IFNULL(SUM(ACC_DEPET_DL),0.000)) 								END 							ELSE 							CASE 									WHEN (IFNULL(SUM(a.CRedetTO),0.000) - IFNULL(SUM(a.ACC_DEPET_TO),0.000)) = 0 										THEN 										0.00 									ELSE 									(IFNULL(SUM(CRedetDL),0.000) - IFNULL(SUM(ACC_DEPET_DL),0.000)) / (IFNULL(SUM(a.CRedetTO),0.000) - IFNULL(SUM(a.ACC_DEPET_TO),0.000)) 							END 					END										AS Costof,
					(IFNULL(SUM(a.CRedetTO),0.000) - IFNULL(SUM(a.ACC_DEPET_TO),0.000)) AS Foreignbalance,
					(IFNULL(SUM(CRedetDL),0.000) - IFNULL(SUM(ACC_DEPET_DL),0.000))		AS LocalBalance,

										IFNULL((SELECT
											SUM(x.Credit) - SUM(x.Debit)
									 FROM
											ExSyAccountsCurrency_AccSafeActivityTb AS x
											left join TB_Users as y on x.AccIDFrom=accid
									WHERE

											 x.OperationTypeID<>34
											AND (x.TypeID = 22 or x.TypeID = 21)
											AND AccIDTo<>y.AccID

											), 0.000) AS costmerForPreseEn,
					a.BID,
					a.ACCFRom,
					c.CurrencyPower,
					c.SalePrice,
					c.BuyPrice
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.ACCFRom = b.ID
				INNER JOIN
					NewCurrencyPriceOwnDetailsTb AS c
						ON b.ID = c.CurrencyIDTo
       	INNER JOIN
        NewCurrencyPricesOwnTb AS D
        ON c.CPID=d.ID
			WHERE
					a.ISactive = 1
					AND d.PriceType = 0
					AND a.BID = (p_Bid)
			GROUP BY
					b.CuName,
					c.CurrencyPower,
					a.BID,
					a.ACCFRom,
					c.CurrencyPower,
					c.SalePrice,
					c.BuyPrice) AS a
  WHERE
          a.ACCFRom = p_ACCFRom;
  SELECT IFNULL(SUM(a.CRedetTO), 0.000) INTO v_AccCreditVal FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          AccFrom = p_ACCFRom
          AND BID = p_Bid;
  SELECT IFNULL(SUM(a.ACC_DEPET_TO), 0.000) INTO v_AccdebitVal FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          AccFrom = p_ACCFRom
          AND BID = p_Bid;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
  SELECT IFNULL(SUM(a.CRedetTO), 0.000) INTO v_AccCreditVal2 FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          AccFrom = p_ACCFRom
          AND BID = p_Bid
          AND Inseart_Date < p_dt1;
  SELECT IFNULL(SUM(a.ACC_DEPET_TO), 0.000) INTO v_AccdebitVal2 FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          AccFrom = p_ACCFRom
          AND BID = p_Bid
          AND Inseart_Date < p_dt1;
SET v_AccVal2 = v_AccCreditVal2 - v_AccdebitVal2;
  SELECT SUM(NetSale) INTO v_TotalProfit FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          NetSale > 0
          AND a.`IsActive` = 1
          AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
          AND (   a.AccFrom = p_ACCFRom
                  OR p_ACCFRom = 0)
          AND BID = p_Bid;
  SELECT SUM(NetSale) INTO v_Totallosses FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          NetSale < 0
          AND a.`IsActive` = 1
          AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
          AND (   a.AccFrom = p_ACCFRom
                  OR p_ACCFRom = 0)
          AND BID = p_Bid;
  SELECT SUM(`CRedetDL`) - SUM(`ACC_DEPET_DL`) INTO v_c1 FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE
          a.`IsActive` = 1
          AND (a.AccFrom = p_ACCFRom)
          AND BID = p_Bid;
  SELECT CASE                            WHEN e.CurrencyPower = 0                              AND v_c1 <> 0                              THEN                              v_AccVal / v_c1                            WHEN e.CurrencyPower = 1                              AND v_AccVal <> 0                              THEN                              v_c1 / v_AccVal                            ELSE                            0.000                    END INTO v_ctotal FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
      INNER JOIN
        `CurrencyPriceDetailsTb` AS e
          ON a.AccFrom = e.CurrencyIDTo
  WHERE
          a.`IsActive` = 1
          AND (   a.AccFrom = p_ACCFRom
                  OR p_ACCFRom = 0)
          AND BID = p_Bid;
  SELECT
          ROW_NUMBER() OVER (
          ORDER BY a.ID ASC)                                                           AS SN,
          a.ID,
          a.`ISID`,
          b.CurCode                                                                    AS ACCFRom,
          c.CuName                                                                     AS ACCCRint0,
          FORMAT(a.`Purchaseprice`, 3)                                     AS Purchaseprice,
          FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal
          ,
          UName,
          DATE_FORMAT(a.Inseart_Date, '%Y/%m/%d'),
          a.`IsActive`,
          FORMAT(a.`CRedetTO`, 3)                                          AS CRedetTO
          ,
          FORMAT(a.ACC_DEPET_TO, 3)                                        AS ACC_DEPET_TO
          ,
          CASE                   WHEN a.Typeofsalebuyorsell = 0                     OR a.Typeofsalebuyorsell = 3                     THEN                     a.`CRedetTO`                   WHEN a.Typeofsalebuyorsell = 1                     OR a.Typeofsalebuyorsell = 2                     THEN                     a.ACC_DEPET_TO * -1           END                                                                          AS Currencyquantity
          ,
          CASE                   WHEN a.Typeofsalebuyorsell = 0                     THEN                     FORMAT(a.`Purchaseprice`, 3)                   WHEN a.Typeofsalebuyorsell = 3                     THEN                     salesPurchaseprice           END                                                                          AS buyprice
          ,
          CASE                   WHEN a.Typeofsalebuyorsell = 3                     THEN                     CASE                             WHEN FORMAT(CRedetTO * salesPurchaseprice, 3) LIKE '%.000'                               THEN                               FORMAT(CRedetTO * salesPurchaseprice, 0)                             ELSE                             FORMAT(CRedetTO * salesPurchaseprice, 3)                     END                   ELSE                   CASE                           WHEN a.`CRedetDL` LIKE '%.000'                             THEN                             FORMAT(a.`CRedetDL`, 0)                           ELSE                           FORMAT(a.`CRedetDL`, 3)                   END           END                                                                          AS CRedetDL
          ,
          CASE                   WHEN a.Typeofsalebuyorsell = 2                     THEN                     FORMAT(a.`Purchaseprice`, 3)                   WHEN a.Typeofsalebuyorsell = 1                     THEN                     IFNULL(salesPurchaseprice, 0.000)           END                                                                          AS salesPurchaseprice
          ,
          0                                                                            AS zero,
          CASE                   WHEN a.Typeofsalebuyorsell = 3                     THEN                     CASE                             WHEN a.`ACC_DEPET_DL` LIKE '%.000'                               THEN                               FORMAT(a.`ACC_DEPET_DL`, 0)                             ELSE                             FORMAT(a.`ACC_DEPET_DL`, 3)                     END                   ELSE                   CASE                           WHEN FORMAT(NetSale + ACC_DEPET_DL, 3) LIKE '%.000'                             THEN                             FORMAT(NetSale + ACC_DEPET_DL, 0)                           ELSE                           FORMAT(NetSale + ACC_DEPET_DL, 3)                   END           END                                                                          AS ACC_DEPET_DL
          ,
          CASE                   WHEN a.Typeofsalebuyorsell = 3                     OR a.Typeofsalebuyorsell = 0                     THEN                     CASE                             WHEN a.`CRedetDL` LIKE '%.000'                               THEN                               FORMAT(a.`CRedetDL`, 0)                             ELSE                             FORMAT(a.`CRedetDL`, 3)                     END                   ELSE                   CASE                           WHEN a.`ACC_DEPET_DL` LIKE '%.000'                             THEN                             FORMAT(-(a.`ACC_DEPET_DL`), 0)                           ELSE                           FORMAT(-(a.`ACC_DEPET_DL`), 3)                   END           END                                                                          AS Revenue
          ,
          CASE                   WHEN a.NetSale LIKE '%.000'                     THEN                     FORMAT(a.NetSale, 0)                   ELSE                   FORMAT(a.NetSale, 3)           END                                                                          AS NetSale
          ,
          v_Costof                                                                      AS ctotal,
          IFNULL(v_Totallosses, 0.000)                                                  AS losses,
          IFNULL(v_TotalProfit, 0.000)                                                  AS Profit,
          a.`IsActive`,
          FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
          v_AccVal2                                                                     AS GetAccVal3,
          v_AccVal                                                                      AS GetAccVal2,
          CASE                   WHEN a.Typeofsalebuyorsell = 1                     OR a.Typeofsalebuyorsell = 3                     THEN                     FORMAT(a.`Purchaseprice`, 3)                   WHEN a.Typeofsalebuyorsell = 2                     THEN                     FORMAT(a.`Purchaseprice`, 3)           END                                                                          AS saleprice
          ,
          CASE                   WHEN TypeofCalcORsaleBuy = 1                     THEN                     CASE                             WHEN `TYPEFROM` = 0                               AND a.Typeofsalebuyorsell = 0                               THEN                               'شراء نقدي'                             WHEN `TYPEFROM` = 0                               AND a.Typeofsalebuyorsell = 1                               THEN                               'بيع نقدي'                             WHEN `TYPEFROM` = 0                               AND a.Typeofsalebuyorsell = 2                               THEN                               'إسترجاع شراء نقدي'                             WHEN `TYPEFROM` = 0                               AND a.Typeofsalebuyorsell = 3                               THEN                               'إسترجاع بيع نقدي'                             WHEN `TYPEFROM` = 1                               AND a.Typeofsalebuyorsell = 0                               THEN                               'شراء خارجي'                             WHEN `TYPEFROM` = 1                               AND a.Typeofsalebuyorsell = 1                               THEN                               'بيع خارجي'                             WHEN `TYPEFROM` = 1                               AND a.Typeofsalebuyorsell = 2                               THEN                               'إسترجاع شراء خارجي'                             WHEN `TYPEFROM` = 1                               AND a.Typeofsalebuyorsell = 3                               THEN                               'إسترجاع بيع خارجي'                             WHEN `TYPEFROM` = 2                               AND a.Typeofsalebuyorsell = 0                               THEN                               'شراء ت.خارجي'                             WHEN `TYPEFROM` = 2                               AND a.Typeofsalebuyorsell = 1                               THEN                               'بيع ت.خارجي'                             WHEN `TYPEFROM` = 2                               AND a.Typeofsalebuyorsell = 2                               THEN                               'إسترجاع شراء ت.خارجي'                             WHEN `TYPEFROM` = 2                               AND a.Typeofsalebuyorsell = 3                               THEN                               'إسترجاع بيع ت.خارجي'                             WHEN `TYPEFROM` = 3                               AND a.Typeofsalebuyorsell = 0                               THEN                               'شراء عالمصرف'                             WHEN `TYPEFROM` = 3                               AND a.Typeofsalebuyorsell = 1                               THEN                               'بيع عالمصرف'                             WHEN `TYPEFROM` = 3                               AND a.Typeofsalebuyorsell = 2                               THEN                               'إسترجاع شراء عالمصرف'                             WHEN `TYPEFROM` = 3                               AND a.Typeofsalebuyorsell = 3                               THEN                               'إسترجاع بيع عالمصرف'                     END                   ELSE                   CASE                           WHEN                             a.Typeofsalebuyorsell = 1                             THEN                             'عجز خزنة'                           WHEN                             a.Typeofsalebuyorsell = 0                             THEN                             'فائض خزنة'                   END           END                                                                          AS TYPEFROM
  FROM
          ExSyAccountsCurrency_CurrencymovementPruse AS a
      INNER JOIN
        CurrencyMainTb AS b
          ON a.`ACCFRom` = b.ID
      INNER JOIN
        CurrencyMainTb AS c
          ON a.`ACCCRint0` = c.ID
      INNER JOIN
        TB_Users AS d
          ON a.UESER_INSERt = d.USID

  WHERE
          a.`IsActive` = 1
          AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
          AND (   a.ACCFRom = p_ACCFRom
                  OR p_ACCFRom = 0)
          AND BID = p_Bid
          AND a.TYPEFROM = 0
  ORDER BY
          a.ID ASC;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CurrencymovementPruseUser_FILLGRid`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CurrencymovementPruseUser_FILLGRid`(IN `p_TYPE` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT, IN `p_UName` INT)
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_TotalProfit DECIMAL(15, 3);
DECLARE v_Totallosses DECIMAL(15, 3);
DECLARE v_c1 DECIMAL(15, 7);
DECLARE v_c2 DECIMAL(15, 7);
DECLARE v_ctotal DECIMAL(15, 3);
DECLARE v_TotalProfit2 DECIMAL(15, 3);
DECLARE v_Totallosses2 DECIMAL(15, 3);
DECLARE v_AccCreditVal2 DECIMAL(15, 3);
DECLARE v_AccdebitVal2 DECIMAL(15, 3);
DECLARE v_AccVal2 DECIMAL(15, 3);
	SELECT IFNULL(SUM(a.CRedetTO), 0.000) INTO v_AccCreditVal FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			AccFrom = p_ACCFRom
			AND (a.AccID = p_UName);
	SELECT IFNULL(SUM(a.ACC_DEPET_TO), 0.000) INTO v_AccdebitVal FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			AccFrom = p_ACCFRom
			AND (a.AccID = p_UName);
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
	SELECT IFNULL(SUM(a.CRedetTO), 0.000) INTO v_AccCreditVal2 FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			AccFrom = p_ACCFRom
			AND (a.AccID = p_UName)
			AND Inseart_Date < p_dt1;
	SELECT IFNULL(SUM(a.ACC_DEPET_TO), 0.000) INTO v_AccdebitVal2 FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			AccFrom = p_ACCFRom
			AND (a.AccID = p_UName)
			AND Inseart_Date < p_dt1;
SET v_AccVal2 = v_AccCreditVal2 - v_AccdebitVal2;
	SELECT SUM(NetSale) INTO v_TotalProfit FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			NetSale > 0
			AND a.`ISactive` = 1
			AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
			AND (   a.AccFrom = p_ACCFRom
					OR p_ACCFRom = 0)
			AND (a.AccID = p_UName);
	SELECT SUM(NetSale) INTO v_Totallosses FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			NetSale < 0
			AND a.`ISactive` = 1
			AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
			AND (   a.AccFrom = p_ACCFRom
					OR p_ACCFRom = 0)
			AND (a.AccID = p_UName);

	SELECT SUM(`CRedetDL`) - SUM(`ACC_DEPET_DL`) INTO v_c1 FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
	WHERE
			a.`ISactive` = 1
			AND (a.AccFrom = p_ACCFRom)
			AND a.UESER_INSERt = p_UName;

	SELECT CASE 							 WHEN e.CurrencyPower = 0 								 AND v_c1 <> 0 								 THEN 								 v_AccVal / v_c1 							 WHEN e.CurrencyPower = 1 								 AND v_AccVal <> 0 								 THEN 								 v_c1 / v_AccVal 							 ELSE 							 0.000 					 END INTO v_ctotal FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
		INNER JOIN
			`CurrencyPriceDetailsTb` AS e
				ON a.AccFrom = e.CurrencyIDTo
	WHERE
			a.`ISactive` = 1
			AND (   a.AccFrom = p_ACCFRom
					OR p_ACCFRom = 0)
			AND a.UESER_INSERt = p_UName;

	IF p_TYPE = 0
		 THEN
			SELECT
					`ISID`,
					b.CurCode																	 AS ACCFRom,
					c.CuName																	 AS ACCCRint0,
					`CRedetTO`,
					`Purchaseprice`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END																			 AS CRedetDL,
					`ACC_DEPET_DL`,
					`ACC_DEPET_TO`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								CRedetDL 							ELSE 							NetSale + ACC_DEPET_DL 					END																			 AS Revenue,
					UName,
					DATE_FORMAT(a.Inseart_Date, '%Y/%m/%d'),
					a.`ISactive`,
					FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
					v_AccVal2																	 AS GetAccVal3,
					v_AccVal																		 AS GetAccVal2,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							ELSE 							'0.000' 					END																			 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END																			 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							IFNULL(salesPurchaseprice, 0.000) 					END																			 AS salesPurchaseprice,
					IFNULL(v_Totallosses, 0.000)													 AS losses,
					IFNULL(v_TotalProfit, 0.000)													 AS Profit,
					v_ctotal																		 AS ctotal,
Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END									 					END																			 AS TYPEFROM,
					FORMAT(a.NetSale, 3)											 AS NetSale
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`ISactive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (   `Typeofsalebuyorsell` = 0
							OR `Typeofsalebuyorsell` = 3)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;
		END IF;

	IF p_TYPE = 1
		 THEN
			SELECT
					`ISID`,
					b.CurCode																	 AS ACCFRom,
					c.CuName																	 AS ACCCRint0,
					`CRedetTO`,
					`Purchaseprice`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END																			 AS CRedetDL,
					`ACC_DEPET_DL`,
					`ACC_DEPET_TO`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								CRedetDL 							ELSE 							NetSale + ACC_DEPET_DL 					END																			 AS Revenue,
					UName,
					DATE_FORMAT(a.Inseart_Date, '%Y/%m/%d'),
					a.`ISactive`,
					FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
					v_AccVal2																	 AS GetAccVal3,
					v_AccVal																		 AS GetAccVal2,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							ELSE 							'0.000' 					END																			 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END																			 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							IFNULL(salesPurchaseprice, 0.000) 					END																			 AS salesPurchaseprice,
					IFNULL(v_Totallosses, 0.000)													 AS losses,
					IFNULL(v_TotalProfit, 0.000)													 AS Profit,
					v_ctotal																		 AS ctotal,
Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END									 					END																			 AS TYPEFROM,
					FORMAT(a.NetSale, 3)											 AS NetSale
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`ISactive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (   `Typeofsalebuyorsell` = 1
							OR `Typeofsalebuyorsell` = 2)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;
		END IF;

	IF p_TYPE = 2
		 THEN
			SELECT
					`ISID`,
					b.CurCode																	 AS ACCFRom,
					c.CuName																	 AS ACCCRint0,
					`CRedetTO`,
					`Purchaseprice`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(CRedetTO * salesPurchaseprice, 3) 							ELSE 							FORMAT(a.`CRedetDL`, 3) 					END																			 AS CRedetDL,
					`ACC_DEPET_DL`,
					`ACC_DEPET_TO`,
					CASE 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								'0.000' 							ELSE 							NetSale + ACC_DEPET_DL 					END																			 AS Revenue,
					UName,
					DATE_FORMAT(a.Inseart_Date, '%Y/%m/%d'),
					a.`ISactive`,
					FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
					v_AccVal2																	 AS GetAccVal3,
					v_AccVal																		 AS GetAccVal2,
					CASE 							WHEN a.Typeofsalebuyorsell = 0 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell = 3 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END																			 AS buyprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 1 								OR a.Typeofsalebuyorsell = 3 								THEN 								FORMAT(a.`Purchaseprice`, 3) 							ELSE 							'0.000' 					END																			 AS saleprice,
					CASE 							WHEN a.Typeofsalebuyorsell = 2 								AND ACC_DEPET_TO <> 0 								THEN 								FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 							WHEN a.Typeofsalebuyorsell <> 2 								AND a.Typeofsalebuyorsell <> 3 								THEN 								IFNULL(salesPurchaseprice, 0.000) 							ELSE 							'0.000' 					END																			 AS salesPurchaseprice,
					IFNULL(v_Totallosses, 0.000)													 AS losses,
					IFNULL(v_TotalProfit, 0.000)													 AS Profit,
					v_ctotal																		 AS ctotal,
Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END									 					END																			 AS TYPEFROM,
					FORMAT(a.NetSale, 3)											 AS NetSale
			FROM
					ExSyAccountsCurrency_CurrencymovementPruse AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.`ACCFRom` = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.`ACCCRint0` = c.ID
				INNER JOIN
					TB_Users AS d
						ON a.UESER_INSERt = d.USID
				INNER JOIN
					`CurrencyPriceDetailsTb` AS e
						ON a.ACCFRom = e.CurrencyIDTo
			WHERE
					a.`ISactive` = 1
					AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
					AND (   a.ACCFRom = p_ACCFRom
							OR p_ACCFRom = 0)
					AND (a.AccID = p_UName)
			ORDER BY
					a.ID ASC;

		END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CurrencyMovements_fillCrid`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CurrencyMovements_fillCrid`(IN `p_TYPE` INT, IN `p_ISID` BIGINT, IN `p_DT1` DATE, IN `p_DT2` DATE, IN `p_Ueserinsert` BIGINT, IN `p_TypeMovet` BIGINT)
BEGIN
IF p_TYPE = 1
		 THEN
			SELECT
					CASE 							WHEN a.`TYPE` = 1 								THEN 								'عالمصرف' 							ELSE 							'نقدي' 					END								   AS 'TYPE',
					d.BankName						   AS ISID,
					b.CuName						   AS CurrencyFrom,
					c.CuName						   AS CurrencyTo,
					a.BuyPrice,
					SalePrice,
					RetBuyPrice,
					retSalePrice,
					e.UName							   AS Ueserinsert,
					InsertDate,
					CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
					f.Movementsnmae					   AS TypeMovet
			FROM
					`CurrencyMovements2024`.CurrencyMovementsTable AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyFrom = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyTo = c.ID
				INNER JOIN
					BanksTb AS d
						ON a.ISID = d.ID
				INNER JOIN
					TB_Users AS e
						ON a.Ueserinsert = e.USID
				INNER JOIN
					CurrencyMovements2024.MovementsnmaeTypeTB AS f
						ON a.TypeMovet = f.MovementstYPE

			WHERE
					(		a.`TYPE` = p_TYPE
							OR p_TYPE = 2)
					AND (   a.ISID = p_ISID
							OR p_ISID = 0)
					AND (   a.Ueserinsert = p_Ueserinsert
							OR p_Ueserinsert = 0)
					AND a.InsertDate BETWEEN p_DT1 AND p_DT2
					AND (   a.TypeMovet = p_TypeMovet
							OR p_TypeMovet = 3)
			ORDER BY
					a.InsertDate,
					a.DateForTime DESC;
		END IF;
	IF p_TYPE = 0
		 THEN
			SELECT
					CASE 							WHEN a.`TYPE` = 1 								THEN 								'عالمصرف' 							ELSE 							'نقدي' 					END								   AS 'TYPE',
					'بيع نقدي'						   AS ISID,
					b.CuName						   AS CurrencyFrom,
					c.CuName						   AS CurrencyTo,
					a.BuyPrice,
					SalePrice,
					RetBuyPrice,
					retSalePrice,
					e.UName							   AS Ueserinsert,
					InsertDate,
					CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
					f.Movementsnmae					   AS TypeMovet
			FROM
					`CurrencyMovements2024`.CurrencyMovementsTable AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyFrom = b.ID
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyTo = c.ID
				INNER JOIN
					TB_Users AS e
						ON a.Ueserinsert = e.USID
				INNER JOIN
					CurrencyMovements2024.MovementsnmaeTypeTB AS f
						ON a.TypeMovet = f.MovementstYPE

			WHERE
					(		a.`TYPE` = p_TYPE
							OR p_TYPE = 2)
					AND (   a.ISID = p_ISID
							OR p_ISID = 0)
					AND (   a.Ueserinsert = p_Ueserinsert
							OR p_Ueserinsert = 0)
					AND a.InsertDate BETWEEN p_DT1 AND p_DT2
					AND (   a.TypeMovet = p_TypeMovet
							OR p_TypeMovet = 3)
			ORDER BY
					a.InsertDate,
					a.DateForTime DESC;
		END IF;
	IF p_TYPE = 2
		 THEN
			SELECT
					*
			FROM
					(   SELECT
								CASE 										WHEN a.`TYPE` = 1 											THEN 											'عالمصرف' 										ELSE 										'نقدي' 								END AS 'TYPE',
								d.BankName AS ISID,
								b.CuName AS CurrencyFrom,
								c.CuName AS CurrencyTo,
								a.BuyPrice,
								SalePrice,
								RetBuyPrice,
								retSalePrice,
								e.UName AS Ueserinsert,
								InsertDate,
								CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
								f.Movementsnmae AS TypeMovet
						FROM
								`CurrencyMovements2024`.CurrencyMovementsTable AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.CurrencyFrom = b.ID
							INNER JOIN
								CurrencyMainTb AS c
									ON a.CurrencyTo = c.ID
							INNER JOIN
								BanksTb AS d
									ON a.ISID = d.ID
							INNER JOIN
								TB_Users AS e
									ON a.Ueserinsert = e.USID
							INNER JOIN
								CurrencyMovements2024.MovementsnmaeTypeTB AS f
									ON a.TypeMovet = f.MovementstYPE

						WHERE
								(a.`TYPE` = 1)
								AND (   a.ISID = p_ISID
										OR p_ISID = 0)
								AND (   a.Ueserinsert = p_Ueserinsert
										OR p_Ueserinsert = 0)
								AND a.InsertDate BETWEEN p_DT1 AND p_DT2
								AND (   a.TypeMovet = p_TypeMovet
										OR p_TypeMovet = 3)

						UNION
						SELECT
								CASE 										WHEN a.`TYPE` = 1 											THEN 											'عالمصرف' 										ELSE 										'نقدي' 								END AS 'TYPE',
								'بيع نقدي' AS ISID,
								b.CuName AS CurrencyFrom,
								c.CuName AS CurrencyTo,
								a.BuyPrice,
								SalePrice,
								RetBuyPrice,
								retSalePrice,
								e.UName AS Ueserinsert,
								InsertDate,
								CONCAT(DATE_FORMAT(DateForTime, '%m/%d/%y '), LPAD(DATE_FORMAT(DateForTime, '%l'), 2, ' '), DATE_FORMAT(DateForTime, ':%i:%s %p')) AS DateForTime,
								f.Movementsnmae AS TypeMovet
						FROM
								`CurrencyMovements2024`.CurrencyMovementsTable AS a
							INNER JOIN
								CurrencyMainTb AS b
									ON a.CurrencyFrom = b.ID
							INNER JOIN
								CurrencyMainTb AS c
									ON a.CurrencyTo = c.ID
							INNER JOIN
								TB_Users AS e
									ON a.Ueserinsert = e.USID
							INNER JOIN
								CurrencyMovements2024.MovementsnmaeTypeTB AS f
									ON a.TypeMovet = f.MovementstYPE
						WHERE
								(a.`TYPE` = 0)
								AND (   a.ISID = p_ISID
										OR p_ISID = 0)
								AND (   a.Ueserinsert = p_Ueserinsert
										OR p_Ueserinsert = 0)
								AND a.InsertDate BETWEEN p_DT1 AND p_DT2
								AND (   a.TypeMovet = p_TypeMovet
										OR p_TypeMovet = 3)) AS x
			ORDER BY
					x.InsertDate,
					x.DateForTime DESC;
		END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CustomerAccountStatement`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CustomerAccountStatement`(IN `p_BranchID` INT, IN `p_CurrencyTo` INT, IN `p_TypeMov` INT, INOUT `p_OverAllDebit` LONGTEXT, INOUT `p_OverAllCredit` LONGTEXT, INOUT `p_OverAllTotal1` LONGTEXT)
BEGIN
DECLARE v_IsDefault BIT;
  SELECT IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
  IF v_IsDefault = 1
     THEN
      IF p_TypeMov = 0
         THEN
          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.ID,
                  a.CustName,
                  a.AccID;

        END IF;
      IF p_TypeMov = 1
         THEN
          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;
      IF p_TypeMov = 2
         THEN
          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.ID,
                  a.CustName,
                  a.AccID

          UNION
          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccounts_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;
    END IF;
  IF v_IsDefault = 0
     THEN
      IF p_TypeMov = 0
         THEN

          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID;


        END IF;
      IF p_TypeMov = 1
         THEN

          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.AccID,
                  a.AccName;
        END IF;




      IF p_TypeMov = 2
         THEN
          SELECT
                  a.AccID,
                  a.CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.ID,
                  0                                                                                AS TypeMov
          FROM
                  `CustomersTb` AS a
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       a.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.IsActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.ID,
                  a.CustName,
                  AccID


          UNION


          SELECT
                  a.AccID,
                  a.AccName                                                                        AS CustName,
                  FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Debit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Credit,
                  FORMAT(IFNULL(SUM(b.Debit), 0.000) - IFNULL(SUM(b.Credit), 0.00), 3) AS ACCNETtotel,
                  a.AccID                                                                          AS ID,
                  1                                                                                AS TypeMov
          FROM
                  AccountsTb AS a
              INNER JOIN
                EmployeeTb AS c
                  ON a.AccID = c.AccID
              INNER JOIN
                ExSyAccountsCurrency_AccSafeActivityTb AS b
                  ON a.AccID = b.AccIDFrom
          WHERE
                  (       c.BranchID = p_BranchID
                          OR p_BranchID = 0)
                  AND a.AccActive = 1
                  AND b.IsActive = 1
                  AND b.CurrencyID = p_CurrencyTo
          GROUP BY
                  a.AccID,
                  a.AccName;

        END IF;
    END IF;
SET p_OverAllDebit  = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 0), 3);
SET p_OverAllCredit = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 1), 3);
SET p_OverAllTotal1 = FORMAT(GET_OverAllTotal1(p_TypeMov, p_CurrencyTo, p_BranchID, 2), 3);
  SELECT
          p_OverAllDebit,
          p_OverAllCredit,
          p_OverAllTotal1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_DiscountValTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `ZRPT_DiscountValTb_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
  SELECT
          ROW_NUMBER() OVER (ORDER BY a.InsertDate DESC) AS '#',
          a.Code                                         AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')             AS 'التاريخ',
          c.EMPNAME                                      AS 'اسم الموظف',
          b.DISNAME                                      AS 'نوع الخصم',
          a.DISVAL                                       AS 'إجمالي الخصميات',
          CASE                   WHEN a.IsOpened = 0                     THEN                     'منتهي'                   ELSE                   'تحت الإجراء'           END                                            AS 'الحالة'
  FROM
          DiscountValTb AS a
      LEFT JOIN
        DiscountTypeTb AS b
          ON a.DiscountTypeID = b.ID
      LEFT JOIN
        EmployeeTb AS c
          ON a.EMPID = c.ID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1
          AND c.BranchID = p_BranchID
          AND a.insertdate BETWEEN p_D1 AND p_D2
  ORDER BY
          a.InsertDate DESC;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_DiscountValTb_Select`;
DELIMITER //
CREATE PROCEDURE `ZRPT_DiscountValTb_Select`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          b.ID,
          a.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          a.EMPID,
          a.DISVAL,
          a.DiscountTypeID,
          a.IsActive,
          b.BranchID,
          C.BName,
          b.EMPNAME,
          E.DISNAME,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END AS Phone,
          CASE                   WHEN a.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   a.Notes           END AS Notes,
          E.DISNAME
  FROM
          DiscountValTb AS a
      INNER JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      LEFT JOIN
        CoBranch AS C
          ON b.BranchID = C.ID
      LEFT JOIN
        DiscountTypeTb AS E
          ON a.DiscountTypeID = E.ID
  WHERE
          a.Code = p_Code;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_EMPORCUSTWITHDRAWALTB_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `ZRPT_EMPORCUSTWITHDRAWALTB_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
  SELECT
          ROW_NUMBER() OVER (ORDER BY a.insertdate ASC) AS '#',
          a.Code                                        AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')            AS 'التاريخ',
          c.EMPNAME                                     AS 'اسم الموظف',
          CASE                   WHEN a.TypeID = 5                     THEN                     a.WDVAL                   ELSE                   0.000           END                                           AS 'مدين',
          CASE                   WHEN a.TypeID = 7                     THEN                     IFNULL(a.WDVAL, 0.000)                   ELSE                   0.000           END                                           AS 'دائن',
          CASE                   WHEN a.TypeID = 5                     THEN                     'عملية سحب'                   WHEN a.TypeID = 7                     THEN                     'عملية إيداع'           END                                           AS 'نوع العملية',
          Notes                                         AS 'الملاحظات'
  FROM
          EMPORCUSTWITHDRAWALTB AS a
      LEFT JOIN
        EmployeeTb AS c
          ON a.EMPID = c.ID
  WHERE
          a.IsActive = 1
          AND a.BranchID = p_BranchID
          AND a.InsertDate >= p_D1
          AND a.insertdate <= p_D2
          AND (   a.TypeID = 5
                  OR a.TypeID = 7)
  ORDER BY
          a.insertdate;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_EMPORCUSTWITHDRAWALTB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_EMPORCUSTWITHDRAWALTB_SelectByCode`(IN `p_Code` TEXT, IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
DECLARE v_EMPCUSTID INT;
START TRANSACTION;
  IF (p_TypeID = 7
    OR
    p_TypeID = 5)
     THEN
      SELECT
              a.Code,
             DATE_FORMAT(a.InsertDate, '%Y/%m/%d') as InsertDate ,
              f.AccName AS EMPID,
              a.WDVAL,
              a.SafeID,
              d.AccName,
              a.IsActive,
              a.TypeID,
              a.BranchID,
              c.BName,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END       AS Notes,
              CASE                       WHEN c.Mobile1 = ''                         AND c.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN c.Mobile1 = ''                         THEN                         c.Mobile2                       WHEN c.Mobile2 = ''                         THEN                         c.Mobile1                       ELSE                       CONCAT(c.Mobile1, '-', c.Mobile2)               END       AS Phone,
              a.PaidFor,
              a.IDNo,
              a.Phone   AS Phone2

      FROM
              EMPORCUSTWITHDRAWALTB AS a
          LEFT JOIN
            AccountsTb AS F
              ON a.EMPID=f.AccID
          LEFT JOIN
            `CoBranch` AS c
              ON a.BranchID = c.ID
          LEFT JOIN
            `AccountsTb` AS d
              ON a.safeid = d.AccID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;
  IF (p_TypeID = 41)
     THEN

      SELECT
              a.Code,
             DATE_FORMAT(a.InsertDate, '%Y/%m/%d') as InsertDate,
              b.CustName AS EMPID,
              a.WDVAL,
              a.SafeID,
              d.AccName,
              a.IsActive,
              a.TypeID,
              a.BranchID,
              c.BName,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END        AS Notes,
              CASE                       WHEN c.Mobile1 = ''                         AND c.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN c.Mobile1 = ''                         THEN                         c.Mobile2                       WHEN c.Mobile2 = ''                         THEN                         c.Mobile1                       ELSE                       CONCAT(c.Mobile1, '-', c.Mobile2)               END        AS Phone,
              a.PaidFor,
              a.IDNo,
              a.Phone    AS Phone2
      FROM
              ContractDB.EMPORCUSTWITHDRAWALTB AS a
          LEFT JOIN
            ContractDB.ContractorTb AS b
              ON a.EMPID = b.ID
          LEFT JOIN
            `CoBranch` AS c
              ON a.BranchID = c.ID
          LEFT JOIN
            `AccountsTb` AS d
              ON a.SafeID = d.AccID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;

  IF (p_TypeID = 46)
     THEN
      SELECT
              a.Code,
             DATE_FORMAT(a.InsertDate, '%Y/%m/%d') as InsertDate,
              b.EMPNAME AS EMPID,
              a.WDVAL,
              a.SafeID,
              d.AccName,
              a.IsActive,
              a.TypeID,
              a.BranchID,
              c.BName,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END       AS Notes,
              CASE                       WHEN c.Mobile1 = ''                         AND c.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN c.Mobile1 = ''                         THEN                         c.Mobile2                       WHEN c.Mobile2 = ''                         THEN                         c.Mobile1                       ELSE                       CONCAT(c.Mobile1, '-', c.Mobile2)               END       AS Phone,
              a.PaidFor,
              a.IDNo,
              a.Phone   AS Phone2
      FROM
              ContractDB.EMPORCUSTWITHDRAWALTB AS a
          LEFT JOIN
            ContractDB.EmployeeTb AS b
              ON a.EMPID = b.ID
          LEFT JOIN
            `CoBranch` AS c
              ON a.BranchID = c.ID
          LEFT JOIN
            `AccountsTb` AS d
              ON a.SafeID = d.AccID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;

  IF (p_TypeID = 49)
     THEN

      SELECT
              a.Code,
             DATE_FORMAT(a.InsertDate, '%Y/%m/%d') as InsertDate,
              b.CustName AS EMPID,
              a.WDVAL,
              a.SafeID,
              d.AccName,
              a.IsActive,
              a.TypeID,
              a.BranchID,
              c.BName,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END        AS Notes,
              CASE                       WHEN c.Mobile1 = ''                         AND c.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN c.Mobile1 = ''                         THEN                         c.Mobile2                       WHEN c.Mobile2 = ''                         THEN                         c.Mobile1                       ELSE                       CONCAT(c.Mobile1, '-', c.Mobile2)               END        AS Phone,
              a.PaidFor,
              a.IDNo,
              a.Phone    AS Phone2
      FROM
              ContractDB.EMPORCUSTWITHDRAWALTB AS a
          LEFT JOIN
            ContractDB.SupplierTb AS b
              ON a.EMPID = b.ID
          LEFT JOIN
            `CoBranch` AS c
              ON a.BranchID = c.ID
          LEFT JOIN
            `AccountsTb` AS d
              ON a.SafeID = d.AccID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_IncreaseValTb_LoadAllData`;
DELIMITER //
CREATE PROCEDURE `ZRPT_IncreaseValTb_LoadAllData`(IN `p_BranchID` INT, IN `p_D1` DATE, IN `p_D2` DATE)
BEGIN
START TRANSACTION;
  SELECT
          ROW_NUMBER() OVER (ORDER BY a.InsertDate DESC) AS '#',
          a.Code                                         AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')             AS 'التاريخ',
          c.EMPNAME                                      AS 'اسم الموظف',
          b.PIName                                       AS 'نوع العلاوة',
          a.INCVAL                                       AS 'إجمالي العلاوات',
          CASE                   WHEN a.IsConstant = 1                     THEN                     'علاوة دائمة'                   ELSE                   'علاوة مؤقتة'           END                                            AS 'طبيعة العلاوة',
          CASE                   WHEN a.IsOpened = 0                     THEN                     'منتهية'                   ELSE                   'مستمرة'           END                                            AS 'الحالة'

  FROM
          IncreaseValTb AS a
      LEFT JOIN
        PayIncrease AS b
          ON a.IncreaseTypeID = b.ID
      LEFT JOIN
        EmployeeTb AS c
          ON a.EMPID = c.ID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1
          AND c.BranchID = p_BranchID
          AND a.InsertDate >= p_D1
          AND a.insertdate <= p_D2
  ORDER BY
          a.InsertDate DESC;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_IncreaseValTb_Select`;
DELIMITER //
CREATE PROCEDURE `ZRPT_IncreaseValTb_Select`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          A.IncreaseTypeID,
          A.EMPID,
          D.EMPNAME,
          E.PIName,
          C.BName,
          A.INCVAL,
          A.IsActive,
          A.IsConstant,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END AS Phone,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END AS Notes,
          CASE                   WHEN A.IsConstant = 1                     THEN                     'علاوة دائمة'                   WHEN A.IsConstant = 0                     THEN                     'علاوة مؤقتة'           END AS 'طبيعة العلاوة'
  FROM
          IncreaseValTb AS A
      LEFT JOIN
        EmployeeTb AS B
          ON A.EMPID = B.ID
      LEFT JOIN
        CoBranch AS C
          ON B.BranchID = C.ID
      LEFT JOIN
        EmployeeTb AS D
          ON A.EMPID = D.ID
      LEFT JOIN
        PayIncrease AS E
          ON A.IncreaseTypeID = E.ID
  WHERE
          A.Code = p_Code;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_InternalExValues_PrintRecords`;
DELIMITER //
CREATE PROCEDURE `ZRPT_InternalExValues_PrintRecords`(IN `p_Code` LONGTEXT)
BEGIN


    START TRANSACTION;
    SELECT
            A.Code,
            DATE_FORMAT(a.InsertDate, '%Y/%m/%d') InsertDate,
            A.SenderName,
            A.SPhone1,
            A.SPhone2,
            CASE                     WHEN A.SPhone1 = ''                       AND A.SPhone2 = ''                       THEN                       'لا يوجد'                     WHEN A.SPhone1 = ''                       THEN                       A.SPhone2                     WHEN A.SPhone2 = ''                       THEN                       A.SPhone1                     ELSE                     CONCAT(A.SPhone1, '-', A.SPhone2)             END                                 AS 'هاتف الراسل',

            CASE                     WHEN A.SenderIDNo = ''                       THEN                       'لا يوجد'                     ELSE                     A.SenderIDNo             END                                 AS 'هوية الراسل',
            A.RecievedName,
            A.RPhone1,
            A.RPhone2,
            CASE                     WHEN A.RPhone1 = ''                       AND A.RPhone2 = ''                       THEN                       'لا يوجد'                     WHEN A.RPhone1 = ''                       THEN                       A.RPhone2                     WHEN A.RPhone2 = ''                       THEN                       A.RPhone1                     ELSE                     CONCAT(A.RPhone1, '-', A.RPhone2)             END                                 AS 'هاتف المستلم',

            CASE                     WHEN A.RecievedIDNo = ''                       THEN                       'لا يوجد'                     ELSE                     A.RecievedIDNo             END                                 AS 'هوية المستلم',
            A.RecievedCurrencyID,
            A.DeliveredCurrencyID,
            A.OverallVal,
            A.ExVal,
            A.SafeRecievedID,
            A.DeliveryPlace,
            A.BranchRecievedID,
            A.BranchDeliveredID,
            CASE                     WHEN A.Notes = ''                       THEN                       'لا يوجد'                     ELSE                     A.Notes             END                                 AS 'ملاحظات',
            CASE                     WHEN A.IsAccFrom = 0                       THEN                       'نقدا'                     WHEN A.IsAccFrom = 1                       THEN                       'من حساب'                     WHEN A.IsAccFrom = 2                       THEN                       'خدمات مصرفية'             END                                 AS 'نوع الحوالة',
            B.CurrencyName,
            C.BName                             AS BNameRecieved,
            D.BName                             AS BNameDelivered,
            CASE                     WHEN a.BranchDeliveredID <= 0                       THEN                       h.CityName                     ELSE                     g.CityName             END                                 AS CityName,
            g.ID                                AS CityID,
            c.bname                             AS DName,
            d.bname                             AS RNAME,
            C.Mobile2                           AS Phone1,
            D.Mobile2                           AS Phone2,
            c.Baddress                          AS Address1,
            D.Baddress                          AS Address2,
            CAST(A.OverallVal AS CHAR) AS OV
    FROM
            InternalEx AS A
        LEFT JOIN
          CurrencyTb AS B
            ON A.RecievedCurrencyID = B.ID
        LEFT JOIN
          CoBranch AS C
            ON A.BranchRecievedID = C.ID
        LEFT JOIN
          CoBranch AS D
            ON A.BranchDeliveredID = D.ID
        LEFT JOIN
          AccountsTb AS E
            ON A.SafeDeliveredID = E.AccID
        LEFT JOIN
          AccountsTb AS F
            ON A.SafeRecievedID = F.AccID
        LEFT JOIN
          CitiesTb AS g
            ON d.CityID = g.ID
        LEFT JOIN
          CitiesTb AS h
            ON a.DeliveryPlace = h.ID
    WHERE
            A.Code = p_Code
            AND A.IsActive = 1

    ORDER BY
            A.InsertDate;
    COMMIT;
  END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_MembersCalculationTb_LOADDATATOCALC`;
DELIMITER //
CREATE PROCEDURE `ZRPT_MembersCalculationTb_LOADDATATOCALC`(IN `p_SALARYMONTH` TINYINT UNSIGNED, IN `p_SALARYEAR` INT, IN `p_ASSOCIATIONID` INT)
BEGIN
START TRANSACTION;

  SELECT
          b.MEMBERNAME AS 'الاسم',
          a.AssValue   AS 'قيمة الاشتراك',
          b.ID,
          b.ASSOCIATIONID,
          b.AccID      AS MeAccID,
          a.AccID,
          a.ASSOACCID
  FROM
          ASSOCIATIONNAMETB a
      LEFT OUTER JOIN
        ASSOCIATIONTB AS b
          ON a.ID = b.ASSOCIATIONID
  WHERE
          b.IsActive = 1
          AND NOT EXISTS (SELECT
                      c.MEMBERID
              FROM
                      MembersCalculationTb AS c
              WHERE
                      c.MEMBERID = b.ID
                      AND c.SALARYMONTH = p_SALARYMONTH
                      AND c.SALARYEAR = p_SALARYEAR)
          AND b.ASSOCIATIONID = p_ASSOCIATIONID;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_ModifyingAccountingEntries_TB_LOADTODVG`;
DELIMITER //
CREATE PROCEDURE `ZRPT_ModifyingAccountingEntries_TB_LOADTODVG`()
BEGIN
START TRANSACTION;
  SELECT
          a.`Code`                           AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
          b.BName                            AS 'الفرع',
          CASE                   WHEN a.FirstAccID > 0                     THEN                     c.AccName                   ELSE                   'بدون'           END                                AS 'الطرف الأول',
          CASE                   WHEN a.DeapitVal > 0.000                     THEN                     a.DeapitVal                   ELSE                   0.000           END                                AS 'القيمة',
          CASE                   WHEN a.SecondAccID > 0                     THEN                     c.AccName                   ELSE                   'بدون'           END                                AS 'الطرف الثاني',
          CASE                   WHEN a.CreaditVal > 0.000                     THEN                     a.CreaditVal                   ELSE                   0.000           END                                AS 'القيمة'

  FROM
          `ModifyingAccountingEntries_TB` AS a
      INNER JOIN
        CoBranch AS b
          ON a.BranchID = b.ID
      INNER JOIN
        AccountsTb AS c
          ON a.FirstAccID = c.AccID
      INNER JOIN
        AccountsTb AS d
          ON a.SecondAccID = d.AccID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_ModifyingAccountingEntries_TB_SelectAll`;
DELIMITER //
CREATE PROCEDURE `ZRPT_ModifyingAccountingEntries_TB_SelectAll`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;
  SELECT
          a.Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
          a.ID,
          a.BranchID,
          a.FirstAccMain,
          a.FirstAccParent  AS FAccID,
          b.AccCode,
          a.FirstAccID      AS FSAccID,
          a.SecondAccMain,
          a.SecondAccParent AS SAccID,
          c.AccCode         AS SAccCode,
          a.SecondAccID     AS SSAccID,
          a.CurrencyID,
          a.DeapitVal,
          a.CreaditVal,
          a.MovmentType,
          a.Notes,
          a.IsActive,
          a.UserInsert
  FROM
          `ModifyingAccountingEntries_TB` AS a
      INNER JOIN
        AccountsTb AS b
          ON a.FirstAccParent = b.AccID
      INNER JOIN
        AccountsTb AS c
          ON a.SecondAccParent = c.AccID
  WHERE
          a.IsActive = 1
          AND a.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_ModifyingAccountingEntries_TB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_ModifyingAccountingEntries_TB_SelectByCode`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;
  SELECT
          a.`Code`,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
          b.BName,
          c.AccName AS FAccName,
          CASE                   WHEN a.DeapitVal > 0.000                     THEN                     a.DeapitVal                   ELSE                   0.000           END       AS DeapitVal,
          d.AccName AS SAccName,
          CASE                   WHEN a.CreaditVal > 0.000                     THEN                     a.CreaditVal                   ELSE                   0.000           END       AS CreaditVal,
          e.CuName,
          `MovmentType`,
          a.Notes,
          f.UName
  FROM
          `ModifyingAccountingEntries_TB` AS a
      INNER JOIN
        CoBranch AS b
          ON a.BranchID = b.ID
      INNER JOIN
        AccountsTb AS c
          ON a.FirstAccID = c.AccID
      INNER JOIN
        AccountsTb AS d
          ON a.SecondAccID = d.AccID
      INNER JOIN
        CurrencyMainTb AS e
          ON a.CurrencyID = e.ID
      INNER JOIN
        TB_Users AS f
          ON a.UserInsert = f.USID
  WHERE
          a.IsActive = 1
          AND b.IsActive = 1
          AND c.AccActive = 1
          AND d.AccActive = 1
          AND e.IsActive = 1
          AND f.IsActive = 1
          AND a.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_MPAMNTWDMEMBERTB_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_MPAMNTWDMEMBERTB_SelectByCode`(IN `p_Code` LONGTEXT, IN `p_TypeID` TINYINT UNSIGNED)
BEGIN
DECLARE v_EMPCUSTID INT;
START TRANSACTION;
  IF p_TypeID = 22
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') InsertDate,
              B.MEMBERNAME AS MEMBERNAME,
              CASE                       WHEN a.Debit > a.Credit                         THEN                         a.Debit                       ELSE                       a.Credit               END          AS Credit,
              a.SafeID,
              a.IsActive,
              a.TypeID,
              a.AssID,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END          AS Notes,
              a.MEMBERID,
              d.UName,
              c.ASSNAME
      FROM
              MPAMNTWDMEMBERTB AS a
          LEFT JOIN
            ASSOCIATIONTB AS B
              ON a.MEMBERID = B.ID
          LEFT OUTER JOIN
            TB_Users AS d
              ON a.SafeID = d.USID
          LEFT JOIN
            ASSOCIATIONNAMETB AS c
              ON a.AssID = c.ID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;
  IF p_TypeID = 23
     THEN
      SELECT
              a.Code,
              DATE_FORMAT(a.InsertDate, '%Y/%m/%d') InsertDate,
              a.PaidFor AS MEMBERID,
              a.PHONE,
              a.IDNO,
              CASE                       WHEN a.Debit > a.Credit                         THEN                         a.Debit                       ELSE                       a.Credit               END       AS Credit,
              a.SafeID,
              a.IsActive,
              a.TypeID,
              a.AssID,
              CASE                       WHEN a.Notes = ''                         THEN                         'لا يوجد'                       ELSE                       a.Notes               END       AS Notes,
              d.UName,
              c.ASSNAME

      FROM
              MPAMNTWDMEMBERTB AS a
          LEFT OUTER JOIN
            TB_Users AS d
              ON a.SafeID = d.USID
          LEFT JOIN
            ASSOCIATIONNAMETB AS c
              ON a.AssID = c.ID
      WHERE
              a.TypeID = p_TypeID
              AND a.Code = p_Code
      ORDER BY
              Code;
    END IF;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_PCSettlementTB_SELECTByCODE`;
DELIMITER //
CREATE PROCEDURE `ZRPT_PCSettlementTB_SELECTByCODE`(IN `p_Code` TEXT)
BEGIN
START TRANSACTION;

  SELECT
          A.Code,
          ROW_NUMBER() OVER (ORDER BY F.SPCISID ASC) AS SN,
          F.ExpensVal                                AS ExVal,
          IFNULL('لا يوجد', F.Notes)                 AS NotesDe,
          F.EXID                                     AS EXID,
          F.AccIDEX                                  AS AccEX,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          A.EMPID,
          B.EMPNAME,
          A.BranchID,
          C.BName,
          A.SafeID,
          A.CurrencyID,
          E.AccName,
          A.ISID,
          A.PCVal,
          h.AccName                                  AS ExNamePC,
          A.SettlementVal,
          A.NetTotal,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END                                        AS Notes,
          CASE                   WHEN F.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   F.Notes           END                                        AS NotesD,
          A.IDCode,
          AccSafeID,
          A.AccIDPC                                  AS AccID,
          G.CurrencyName
  FROM
          PCSettlementTB AS A
      LEFT JOIN
        EmployeeTb AS B
          ON A.EMPID = B.ID
      LEFT JOIN
        CoBranch AS C
          ON A.BranchID = C.ID
      LEFT JOIN
        AccountsTb AS E
          ON A.AccSafeID = E.AccID
      LEFT JOIN
        PCSettlementDetailsTB AS F
          ON A.Code = F.SPCISID
      LEFT JOIN
        AccountsTb AS h
          ON F.AccIDEX = h.AccID
      LEFT JOIN
        CurrencyTb AS G
          ON A.CurrencyID = G.ID
  WHERE
          A.Code = p_Code
          AND A.IsActive = 1;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_PettyCashTb_LOADTOREPORT`;
DELIMITER //
CREATE PROCEDURE `ZRPT_PettyCashTb_LOADTOREPORT`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS 'التاريخ',
          A.Code                             AS 'الرمز',
          c.BName                            AS 'الفرع',
          E.CurrencyName                     AS 'العملة',
          D.UName                            AS 'الخزنة',
          B.EMPNAME                          AS 'الموظف',
          A.PettyCashVal                     AS 'القيمة',
          CASE                   WHEN c.Mobile1 = ''                     AND c.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN c.Mobile1 = ''                     THEN                     c.Mobile2                   WHEN c.Mobile2 = ''                     THEN                     c.Mobile1                   ELSE                   CONCAT(c.Mobile1, '-', c.Mobile2)           END                                AS Phone,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END                                AS 'ملاحظة'
  FROM
          PettyCashTb AS A
      LEFT JOIN
        EmployeeTb AS B
          ON A.EMPID = B.ID
      LEFT JOIN
        `CoBranch` AS c
          ON A.BranchID = c.ID
      LEFT JOIN
        TB_Users AS D
          ON A.AccIDSafeID = D.AccID
      LEFT JOIN
        CurrencyTb AS E
          ON A.CurrencyID = E.ID
  WHERE
          A.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_PettyCashTb_LOADTORPTANOTHEREXPENS`;
DELIMITER //
CREATE PROCEDURE `ZRPT_PettyCashTb_LOADTORPTANOTHEREXPENS`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
           DATE_FORMAT(a.InsertDate, '%Y/%m/%d') AS InsertDate,
          A.Code         AS 'الرمز',
          c.BName        AS 'الفرع',
          E.CurrencyName AS 'العملة',
          D.AccName        AS 'الخزنة',
          A.ExpensVal    AS 'القيمة',
          F.AccName      AS 'اسم المصروف',
          G.UName        AS UserInsert,
          CASE                   WHEN c.Mobile1 = ''                     AND c.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN c.Mobile1 = ''                     THEN                     c.Mobile2                   WHEN c.Mobile2 = ''                     THEN                     c.Mobile1                   ELSE                   CONCAT(c.Mobile1, '-', c.Mobile2)           END            AS Phone,
          CASE                   WHEN A.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   A.Notes           END            AS 'ملاحظة'
  FROM
          ANOTHEREXPENSTB AS A
      LEFT JOIN
        `CoBranch` AS c
          ON A.BranchID = c.ID
      LEFT JOIN
        AccountsTb AS D
          ON A.AccSafeID = D.AccID
      LEFT JOIN
        CurrencyTb AS E
          ON A.CurrencyID = E.ID
      LEFT JOIN
        AccountsTb AS F
          ON A.AccIDPC = F.AccID
      LEFT JOIN
        TB_Users AS G
          ON A.UserInsert = G.USID
  WHERE
          A.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_SalaryCalc_LoadToCalculateByEMPAccID`;
DELIMITER //
CREATE PROCEDURE `ZRPT_SalaryCalc_LoadToCalculateByEMPAccID`(IN `p_AccID` INT, IN `p_BranchID` INT)
BEGIN
START TRANSACTION;


	SELECT
			ROW_NUMBER() OVER (
			ORDER BY a.ID ASC) AS '#',
		            A.ID,
            A.`اسم الموظف`,
            A.`الفرع`,
            A.`الراتب الأساسي`,
            A.`علاوات ثابتة`,
            A.`علاوات أخرى`,
            A.`خصميات متنوعة`,
            A.`خصم السلفة`,
            A.`الصافي`,
			CASE 					WHEN C.Mobile1 = '' 						AND C.Mobile2 = '' 						THEN 						'0924903885-0915511445' 					WHEN C.Mobile1 = '' 						THEN 						C.Mobile2 					WHEN C.Mobile2 = '' 						THEN 						C.Mobile1 					ELSE 					CONCAT(C.Mobile1, '-', C.Mobile2) 			END				   AS Phone,
			A.BranchID
	FROM
			`VW_SALARYCALCLAST` AS A
		LEFT JOIN
			CoBranch AS C
				ON A.BranchID = C.ID
	WHERE
			A.AccID = p_AccID
			AND A.BranchID = p_BranchID
	ORDER BY
			ID;







	COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_SalaryCalc_LoadToCalculateByEMPID`;
DELIMITER //
CREATE PROCEDURE `ZRPT_SalaryCalc_LoadToCalculateByEMPID`(IN `p_AccID` INT, IN `p_BranchID` INT, IN `p_DDay` INT)
BEGIN
START TRANSACTION;

  IF p_DDay = 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.ID ASC)                                                                            AS '#',
              A.ID,
              A.AccID,
              A.`اسم الموظف`,
              A.`الفرع`,
              A.`الراتب الأساسي`,
              A.`علاوات ثابتة`,
              A.`علاوات أخرى`,
              A.`باقي السلفة`,
              a.`خصميات متنوعة`,
              A.`الراتب الأساسي` + A.`علاوات ثابتة` + A.`علاوات أخرى` - a.`خصميات متنوعة` - A.`باقي السلفة` AS `الصافي`,
              CASE                       WHEN C.Mobile1 = ''                         AND C.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN C.Mobile1 = ''                         THEN                         C.Mobile2                       WHEN C.Mobile2 = ''                         THEN                         C.Mobile1                       ELSE                       CONCAT(C.Mobile1, '-', C.Mobile2)               END                                                                                           AS Phone,
              A.BranchID
      FROM
              `VW_SALARYCALCLAST` AS A
          LEFT JOIN
            CoBranch AS C
              ON A.BranchID = C.ID
      WHERE
              A.AccID = p_AccID
              AND A.BranchID = p_BranchID
      ORDER BY
              ID;
    END IF;


  IF p_DDay <> 0
     THEN
      SELECT
              ROW_NUMBER() OVER (
              ORDER BY a.ID ASC)                                                                                                              AS '#',
              A.ID,
              A.AccID,
              A.`اسم الموظف`,
              A.`الفرع`,
              A.`الراتب الأساسي`,
              FLOOR(((A.`الراتب الأساسي` / 30) * p_DDay) / 5) * 5                                                                              AS 'الراتب بالأيام',
              A.`علاوات ثابتة`,
              A.`علاوات أخرى`,
              A.`باقي السلفة`,
              a.`خصميات متنوعة`,
              (FLOOR(((A.`الراتب الأساسي` / 30) * p_DDay) / 5) * 5) + A.`علاوات ثابتة` + A.`علاوات أخرى` - a.`خصميات متنوعة` - A.`باقي السلفة` AS `الصافي`,
              CASE                       WHEN C.Mobile1 = ''                         AND C.Mobile2 = ''                         THEN                         '0924903885-0915511445'                       WHEN C.Mobile1 = ''                         THEN                         C.Mobile2                       WHEN C.Mobile2 = ''                         THEN                         C.Mobile1                       ELSE                       CONCAT(C.Mobile1, '-', C.Mobile2)               END                                                                                                                             AS Phone,
              A.BranchID
      FROM
              `VW_SALARYCALCLAST` AS A
          LEFT JOIN
            CoBranch AS C
              ON A.BranchID = C.ID
      WHERE
              A.AccID = p_AccID
              AND A.BranchID = p_BranchID
      ORDER BY
              ID;
    END IF;



  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_SalaryCalculationTb_ViewIndividualSalaryByEMP`;
DELIMITER //
CREATE PROCEDURE `ZRPT_SalaryCalculationTb_ViewIndividualSalaryByEMP`(IN `p_ID` INT)
BEGIN
START TRANSACTION;
  SELECT
          a.CodeID                  AS Code,
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d'),
          b.EMPNAME                 AS 'الموظف',
          CAST(SALARYMONTH AS SIGNED) AS 'الشهر',
          CAST(SALARYEAR AS SIGNED)   AS 'السنة',
          CASE                   WHEN a.IsIndivdual = 0                     THEN                     'احتساب جماعي'                   ELSE                   'احتساب فردي'           END                       AS 'حالة الاحتساب',
          C.BName                   AS BName,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END                       AS Phone,
          a.SalaryVal
  FROM
          SalaryCalculationTb AS a
      LEFT JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      LEFT JOIN
        CoBranch AS C
          ON a.BranchID = C.ID
  WHERE
          a.ID = p_ID;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_SalaryCalculationTb_ViewIndividualSalaryByEMPNotActive`;
DELIMITER //
CREATE PROCEDURE `ZRPT_SalaryCalculationTb_ViewIndividualSalaryByEMPNotActive`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;
  SELECT
          a.CodeID,
          b.EMPNAME,
          C.BName,
          CAST(SALARYMONTH AS SIGNED) AS SALARYMONTH,
          CAST(SALARYEAR AS SIGNED)   AS SALARYEAR,
          a.SalaryVal,
          a.ConstanceVal,
          a.BONUSVAL,
          a.DiscountsVal,
          a.AdvancePaymentDisc,
          a.SALARYTOTAL,
          a.ID,
          CASE                   WHEN C.Mobile1 = ''                     AND C.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN C.Mobile1 = ''                     THEN                     C.Mobile2                   WHEN C.Mobile2 = ''                     THEN                     C.Mobile1                   ELSE                   CONCAT(C.Mobile1, '-', C.Mobile2)           END                       AS Phone
  FROM
          SalaryCalculationTb AS a
      LEFT JOIN
        EmployeeTb AS b
          ON a.EMPID = b.ID
      LEFT JOIN
        CoBranch AS C
          ON a.BranchID = C.ID
  WHERE
          a.IsIndivdual = 1
          AND a.IsActive = 1
          AND b.ISACTIVE = 0
          AND a.CodeID = p_Code;


  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_TransBtweenAccountsTb_SelectByCode`;
DELIMITER //
CREATE PROCEDURE `ZRPT_TransBtweenAccountsTb_SelectByCode`(IN `p_Code` LONGTEXT)
BEGIN
START TRANSACTION;

  SELECT
          a.Code,
          CB.BName,
          DATE_FORMAT(a.TransDate, '%Y/%m/%d'),
          cmt.CuName,
          b.AccName AS TransFrom,
          c.AccName AS AccFromParent,
          d.AccName AS TransTo,
          e.AccName AS AccToParent,
          tu.UName,
          a.Notes

  FROM
          TransBetweenAccountsTB AS a
      LEFT JOIN
        CoBranch cb
          ON a.BranchID = cb.ID
      LEFT JOIN
        CurrencyMainTb cmt
          ON a.CurrencyID = cmt.ID
      LEFT JOIN
        AccountsTb b
          ON a.TransFrom = b.AccID
      LEFT JOIN
        AccountsTb c
          ON a.AccFromParent = c.AccCode
      LEFT JOIN
        AccountsTb d
          ON a.TransTo = d.AccID
      LEFT JOIN
        AccountsTb e
          ON a.AccToParent = e.AccCode
      LEFT JOIN
        TB_Users tu
          ON a.SAFEID = tu.USID
  WHERE
          A.Code = p_Code;

  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_WithdrawalTb_SEARCH`;
DELIMITER //
CREATE PROCEDURE `ZRPT_WithdrawalTb_SEARCH`(IN `p_WDCode` LONGTEXT)
BEGIN
DECLARE v_crunseType BIT;
START TRANSACTION;
  SELECT cmt.IsDefault INTO v_crunseType FROM
          CurrencyMainTb cmt;

  SELECT
          a.WDCode,
          DATE_FORMAT(a.WithdrawalDate, '%Y/%m/%d') AS WithdrawalDate,
          d.BName,
          e.CurrencyName,
          a.WithdrawalFrom,
          a.WithdrawalTo,
          f.AccName                                         AS firstuname,
          g.AccName                                         AS Seconduname,
          a.WithdrawalValue,
          `EMPORCUST_GetAccVal`(f.AccID, v_crunseType) AS 'رصيد الحساب',
          a.BranchID,
          a.CurrencyID,
          h.Uname,
          CASE                   WHEN d.Mobile1 = ''                     AND d.Mobile2 = ''                     THEN                     '0924903885-0915511445'                   WHEN d.Mobile1 = ''                     THEN                     d.Mobile2                   WHEN d.Mobile2 = ''                     THEN                     d.Mobile1                   ELSE                   CONCAT(d.Mobile1, '-', d.Mobile2)           END                                               AS Phone,
          CASE                   WHEN a.Notes = ''                     THEN                     'لا يوجد'                   ELSE                   a.Notes           END                                               AS Notes
  FROM
          WithdrawalTb AS a
      LEFT JOIN
        AccountsTb AS b
          ON a.WithdrawalFrom = b.AccID
      LEFT JOIN
        AccountsTb AS c
          ON a.WithdrawalTo = c.AccID
      LEFT JOIN
        CoBranch AS d
          ON a.BranchID = d.ID
      LEFT JOIN
        CurrencyTb AS e
          ON a.CurrencyID = e.ID
      LEFT JOIN
        AccountsTb AS f
          ON a.WithdrawalFrom = f.AccID
      LEFT JOIN
        AccountsTb AS g
          ON a.WithdrawalTo = g.AccID
      LEFT JOIN
        TB_Users AS h
          ON a.SAFEID = h.USID
  WHERE
          a.IsActive = 1
          AND WDCode = p_WDCode;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPTAssociation_expenses`;
DELIMITER //
CREATE PROCEDURE `ZRPTAssociation_expenses`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')    AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',
          CASE                   WHEN a.Note = ''                     OR a.Note IS NULL                     THEN                     a.MovementType                   ELSE                   a.Note           END                                   AS 'ملاحظات'

  FROM
          ExSyAccounts_AccSafeActivityTb AS a

  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
            AND a.Debit > 0;
  COMMIT;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPTAssociation_revenues`;
DELIMITER //
CREATE PROCEDURE `ZRPTAssociation_revenues`(IN `p_D1` DATE, IN `p_D2` DATE, IN `p_AccID` BIGINT)
BEGIN
START TRANSACTION;

  SELECT
          ROW_NUMBER() OVER (ORDER BY a.ID ASC) AS '#',
          a.ISID                                AS 'الرمز',
          DATE_FORMAT(a.InsertDate, '%Y/%m/%d')    AS 'التاريخ',
          a.Debit                               AS 'مدين',
          a.Credit                              AS 'دائن',
          a.SafeIDMovement                      AS 'طبيعة الحركة',
          CASE                   WHEN a.Note = ''                     OR a.Note IS NULL                     THEN                     a.MovementType                   ELSE                   a.Note           END                                   AS 'ملاحظات'

  FROM
          ExSyAccounts_AccSafeActivityTb AS a

  WHERE
          a.AccIDFrom = p_AccID
          AND a.IsActive = 1
          AND a.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE)
            AND a.Credit > 0;
  COMMIT;
END //
DELIMITER ;

